// CORS proxy for AI provider chat completions
// Browser cannot call provider APIs directly due to CORS — this route proxies the request server-side
// + edge response cache (see chat-proxy-cache.ts): identical prompts, when the client passes
// cacheEnabled, are served from the Cloudflare edge cache — zero upstream calls, zero provider quota.
import { NextRequest, NextResponse } from "next/server";
import { chatCacheKey, matchCachedChat, putCachedChat } from "@/lib/ai/providers/chat-proxy-cache";
import { isWorkersAIQuotaError, runWorkersAIChat } from "@/lib/ai/providers/workers-ai-core";

export const runtime = "edge";

// ============================================================================
// SSRF Protection — inlined (avoids @/ import issues on Cloudflare Pages Edge Runtime)
// Must stay in sync with src/lib/ssrf-allowlist.ts
// ============================================================================
const ALLOWED_PROVIDER_HOSTS = new Set([
  "api.openai.com", "api.anthropic.com", "generativelanguage.googleapis.com",
  "api.groq.com", "api.deepseek.com", "integrate.api.nvidia.com",
  "openrouter.ai", "api.opencode.com", "opencode.ai",
  "api.perplexity.ai", "api.mistral.ai", "api.cohere.com",
  "api.together.xyz", "api.z.ai", "api.aimlapi.com", "api.azure.com",
  "api-inference.huggingface.co", "api.puter.com",
  "bedrock-runtime.us-east-1.amazonaws.com", "bedrock-runtime.us-west-2.amazonaws.com",
  "api.cerebras.ai", "api.sambanova.ai",
  "models.inference.ai.azure.com", "models.inference.github.com",
]);

const BLOCKED_PROXY_HEADERS = new Set([
  "host", "cookie", "authorization", "x-forwarded-for", "x-real-ip",
  "proxy-authorization", "connection", "content-length",
]);

function isAllowedProviderUrl(urlStr: string): boolean {
  try {
    const url = new URL(urlStr);
    const h = url.hostname.toLowerCase();
    if (h === "localhost" || h === "127.0.0.1" || h === "0.0.0.0" ||
      h.startsWith("192.168.") || h.startsWith("10.") ||
      /^172\.(1[6-9]|2[0-9]|3[0-1])\./.test(h) ||
      h.startsWith("169.254.") || h === "metadata.google.internal" ||
      h.endsWith(".local") || h.endsWith(".internal")) {
      return false;
    }
    return ALLOWED_PROVIDER_HOSTS.has(h);
  } catch { return false; }
}

export async function POST(req: NextRequest) {
  // Hoisted so the catch block can reference it in the timeout error message.
  let proxyTimeoutMs = 30_000;
  try {
    const raw = await req.text().catch(() => "");
    const body = raw ? JSON.parse(raw) : {};
    let { baseUrl, apiKey, authType, headersJson, model, messages, maxTokens, temperature, topP, responsePath, timeoutMs } = body;

    // ========================================================================
    // WORKERS AI NATIVE PATH — in-account inference via the [ai] binding.
    // No upstream URL exists: the edge runtime itself is the inference
    // endpoint (getRequestContext().env.AI). Bypasses SSRF/baseUrl checks,
    // WAF/bot-management, and every third-party per-IP quota — the classes of
    // failure that kill external free engines (opencode-zen 429).
    // ========================================================================
    if (body.workersAI === true) {
      const waiCacheKey = body.cacheEnabled === true
        ? await chatCacheKey({ baseUrl: "workers-ai://native", model, messages, maxTokens, temperature, topP })
        : null;
      if (waiCacheKey) {
        const cached = await matchCachedChat(waiCacheKey);
        if (cached) return NextResponse.json(cached, { headers: { "X-Cache": "HIT" } });
      }
      let aiBinding: any;
      try {
        const { getRequestContext } = await import("@cloudflare/next-on-pages");
        aiBinding = (getRequestContext() as any)?.env?.AI;
      } catch {
        aiBinding = undefined; // not running under next-on-pages (local dev/test)
      }

      // Preferred transport: local [ai] binding on the Pages project. When it
      // is not configured, forward to the Workers API (resumeai-pro-api) which
      // owns the [ai] binding — a SAME-ACCOUNT Cloudflare-internal hop, not a
      // third-party egress: no WAF/bot-management, no per-IP quota.
      if (!aiBinding?.run) {
        const workerBase = "https://resumeai-pro-api.rachidelsabah.workers.dev";
        const sharedSecret = process.env.WORKERSAI_SHARED_SECRET || "";
        if (!sharedSecret) {
          return NextResponse.json({
            ok: false,
            error: "Workers AI is not reachable: no [ai] binding on Pages and no WORKERSAI_SHARED_SECRET for the Workers API relay.",
          }, { status: 501 });
        }
        const fwdTimeoutMs = typeof timeoutMs === "number" && timeoutMs > 0 ? Math.min(timeoutMs, 180_000) : 120_000;
        proxyTimeoutMs = fwdTimeoutMs;
        const t0f = performance.now();
        try {
          const fwdRes = await fetch(`${workerBase}/api/ai/workers-ai`, {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              "X-WorkersAI-Secret": sharedSecret,
            },
            body: JSON.stringify({ model, messages, maxTokens, temperature, topP, timeoutMs: fwdTimeoutMs }),
            signal: AbortSignal.timeout(fwdTimeoutMs + 5000),
          });
          const fwdData = (await fwdRes.json().catch(() => ({}))) as any;
          if (!fwdRes.ok || !fwdData.ok) {
            const retryAfter = Number(fwdData?.retryAfterSeconds);
            return NextResponse.json({
              ok: false, success: false,
              error: fwdData?.error || `Workers AI relay returned HTTP ${fwdRes.status}`,
              message: fwdData?.message || fwdData?.error,
              latencyMs: Math.round(performance.now() - t0f),
              isTimeout: fwdData?.isTimeout === true,
              ...(Number.isFinite(retryAfter) && retryAfter > 0 ? { retryAfterSeconds: retryAfter } : {}),
            }, { status: fwdRes.status });
          }
          const successBodyF: Record<string, unknown> = {
            ok: true,
            latencyMs: Math.round(performance.now() - t0f),
            text: fwdData.text,
            inputTokens: fwdData.inputTokens,
            outputTokens: fwdData.outputTokens,
          };
          if (waiCacheKey) await putCachedChat(waiCacheKey, successBodyF);
          return NextResponse.json(successBodyF, { headers: { "X-Cache": waiCacheKey ? "MISS" : "BYPASS" } });
        } catch (fwdErr: any) {
          const fIsTimeout = fwdErr?.name === "AbortError" || /timed out/i.test(String(fwdErr?.message ?? ""));
          return NextResponse.json({
            ok: false, success: false,
            error: fIsTimeout ? `Workers AI relay timed out after ${fwdTimeoutMs / 1000}s` : `Workers AI relay unreachable: ${String(fwdErr?.message ?? fwdErr).slice(0, 200)}`,
            message: fIsTimeout ? `Workers AI relay timed out after ${fwdTimeoutMs / 1000}s` : `Workers AI relay unreachable`,
            latencyMs: Math.round(performance.now() - t0f),
            isTimeout: fIsTimeout,
          }, { status: fIsTimeout ? 504 : 502 });
        }
      }
      const clientTimeoutMs2 = typeof timeoutMs === "number" && timeoutMs > 0 ? Math.min(timeoutMs, 180_000) : 120_000;
      proxyTimeoutMs = clientTimeoutMs2;
      const t0w = performance.now();
      try {
        const result = await runWorkersAIChat(aiBinding, { model, messages, maxTokens, temperature, topP, timeoutMs: clientTimeoutMs2 });
        if (!result.text) {
          return NextResponse.json({ ok: false, latencyMs: Math.round(performance.now() - t0w), error: "Workers AI returned an empty response" }, { status: 502 });
        }
        const successBodyW: Record<string, unknown> = {
          ok: true,
          latencyMs: Math.round(performance.now() - t0w),
          text: result.text,
          inputTokens: result.inputTokens,
          outputTokens: result.outputTokens,
        };
        if (waiCacheKey) await putCachedChat(waiCacheKey, successBodyW);
        return NextResponse.json(successBodyW, { headers: { "X-Cache": waiCacheKey ? "MISS" : "BYPASS" } });
      } catch (waiErr: any) {
        const wIsTimeout = waiErr?.name === "AbortError" || /timed out/i.test(String(waiErr?.message ?? ""));
        const wQuota = isWorkersAIQuotaError(waiErr);
        const wMsg = wQuota
          ? `Workers AI daily neurons exhausted (free tier). It will recover after the UTC reset — failover to the next provider. Detail: ${String(waiErr?.message ?? waiErr).slice(0, 200)}`
          : String(waiErr?.message ?? waiErr).slice(0, 300);
        return NextResponse.json({
          ok: false, success: false,
          error: wMsg, message: wMsg,
          latencyMs: Math.round(performance.now() - t0w),
          isTimeout: wIsTimeout,
        }, { status: wIsTimeout ? 504 : wQuota ? 429 : 500 });
      }
    }

    if (!baseUrl) {
      return NextResponse.json({ ok: false, error: "baseUrl is required" }, { status: 400 });
    }

    if (!isAllowedProviderUrl(baseUrl)) {
      return NextResponse.json(
        { ok: false, error: "Provider URL not allowed. Only known AI provider APIs are supported." },
        { status: 403 },
      );
    }

    // Rewrite Google Gemini API to OpenAI-compatible endpoint
    if (baseUrl.includes("generativelanguage.googleapis.com")) {
      if (!baseUrl.includes("/openai")) {
        baseUrl = baseUrl.replace(/\/v1beta\/?$/, "/v1beta/openai").replace(/\/v1\/?$/, "/v1/openai");
        if (!baseUrl.includes("/openai")) {
          baseUrl = `${baseUrl.replace(/\/$/, "")}/openai`;
        }
      }
    }

    // === Edge response cache (opt-in via body.cacheEnabled) ===
    // Keyed AFTER the baseUrl rewrites above so the key reflects the FINAL
    // upstream URL. The key never includes the API key — identical prompts
    // from different users share one hit instead of doubling the shared-IP
    // provider quota burn (the OpenCode Zen free-tier squeeze).
    let cacheKey: string | null = null;
    if (body.cacheEnabled === true) {
      cacheKey = await chatCacheKey({ baseUrl, model, messages, maxTokens, temperature, topP });
      const cached = await matchCachedChat(cacheKey);
      if (cached) {
        return NextResponse.json(cached, { headers: { "X-Cache": "HIT" } });
      }
    }

    const headers: Record<string, string> = { "Content-Type": "application/json" };
    if (headersJson) {
      try {
        const parsed = JSON.parse(headersJson);
        for (const [key, value] of Object.entries(parsed)) {
          if (!BLOCKED_PROXY_HEADERS.has(key.toLowerCase())) {
            headers[key] = String(value);
          }
        }
      } catch (e) { console.warn("[ProviderChat] Invalid headersJson:", e); }
    }
    if (apiKey) {
      if (baseUrl.includes("generativelanguage.googleapis.com")) {
        headers["Authorization"] = `Bearer ${apiKey}`;
      } else if (authType === "header") {
        headers["x-api-key"] = apiKey;
      } else {
        headers["Authorization"] = `Bearer ${apiKey}`;
      }
    }

    let url = baseUrl.endsWith("/chat/completions")
      ? baseUrl
      : `${baseUrl.replace(/\/$/, "")}/chat/completions`;

    if (authType === "query" && apiKey && !baseUrl.includes("generativelanguage.googleapis.com")) {
      const sep = url.includes("?") ? "&" : "?";
      url = `${url}${sep}key=${encodeURIComponent(apiKey)}`;
    }

    const reqBody: Record<string, unknown> = {
      model: model || "gpt-4o-mini",
      messages: messages || [{ role: "user", content: "Hello" }],
      max_tokens: maxTokens ?? 4096,
      temperature: temperature ?? 0.7,
      top_p: topP ?? undefined,
      stream: false,
    };

    const controller = new AbortController();
    // Respect the client-requested timeoutMs (sent by callUserProvider for
    // optimizer calls that need up to 120s). Fall back to body.timeout (in
    // seconds) for older clients. Hard cap at 180s to protect the edge runtime.
    const clientTimeoutMs = typeof timeoutMs === "number" && timeoutMs > 0
      ? Math.min(timeoutMs, 180_000)
      : (body.timeout || 30) * 1000;
    proxyTimeoutMs = Math.min(clientTimeoutMs, 180_000);
    const timeoutId = setTimeout(() => controller.abort(), proxyTimeoutMs);

    const t0 = performance.now();
    const res = await fetch(url, {
      method: "POST",
      headers,
      body: JSON.stringify(reqBody),
      signal: controller.signal,
    });
    clearTimeout(timeoutId);
    const latencyMs = Math.round(performance.now() - t0);

    if (!res.ok) {
      const errText = await res.text().catch(() => "");
      let errorMessage = errText.slice(0, 300);
      try {
        const errJson = JSON.parse(errText);
        if (errJson?.error?.message) {
          errorMessage = errJson.error.type
            ? `${errJson.error.type}: ${errJson.error.message}`
            : errJson.error.message;
        } else if (errJson?.error?.code && errJson?.error?.message) {
          errorMessage = `Error ${errJson.error.code}: ${errJson.error.message}`;
        } else if (errJson?.message) { errorMessage = errJson.message; }
        else if (errJson?.detail) { errorMessage = errJson.detail; }
      } catch { /* not JSON */ }

      let cleanMessage = errorMessage;
      if (res.status === 401) {
        // OpenCode/ZenCode return 401 for an *unsupported model* (body:
        // {"error":{"type":"ModelError","message":"Model X is not supported"}}),
        // not just a bad key. Surface the real cause instead of always blaming the key.
        const isModelError = /model/i.test(errorMessage) &&
          (/ModelError|not supported|unknown model|model not found/i.test(errorMessage));
        cleanMessage = isModelError
          ? `Model not supported by provider. ${errorMessage}`
          : `Invalid API Key. Please verify that your API key is correct and has the necessary permissions. Detail: ${errorMessage}`;
      }

      // P2 — relay the upstream Retry-After hint (exact cooldown evidence).
      // Providers that send `Retry-After` (delta-seconds or HTTP-date) tell us
      // EXACTLY when to come back; without relaying it, the client would guess
      // a window instead. Relay as a structured field AND as a message note
      // (message survives every error-shaping path, including truncation).
      let retryAfterSeconds: number | undefined;
      const retryAfterRaw = res.headers.get("retry-after");
      if (retryAfterRaw) {
        const asNum = Number(retryAfterRaw.trim());
        if (Number.isFinite(asNum) && asNum > 0) {
          retryAfterSeconds = Math.floor(asNum);
        } else {
          const ts = Date.parse(retryAfterRaw);
          if (!Number.isNaN(ts)) {
            const s = Math.ceil((ts - Date.now()) / 1000);
            if (s > 0) retryAfterSeconds = s;
          }
        }
      }
      const retryNote = retryAfterSeconds !== undefined ? ` (retry-after: ${retryAfterSeconds}s)` : "";

      return NextResponse.json({
        ok: false, latencyMs,
        error: `API returned HTTP ${res.status}: ${cleanMessage}${retryNote}`,
        ...(retryAfterSeconds !== undefined ? { retryAfterSeconds } : {}),
      }, { status: res.status });
    }

    const data = (await res.json()) as any;

    let text = "";
    if (responsePath) {
      text = responsePath.split(".").reduce((acc: unknown, key: string) => {
        const m = key.match(/^([^\[]+)(?:\[(\d+)\])?$/);
        if (!m) return acc;
        const v = (acc as Record<string, unknown>)?.[m[1]];
        return m[2] !== undefined ? (v as unknown[])?.[parseInt(m[2], 10)] : v;
      }, data) ?? "";
    } else if (data?.choices?.[0]?.message?.content) {
      text = data.choices[0].message.content;
    } else if (data?.choices?.[0]?.message?.reasoning_content) {
      text = data.choices[0].message.reasoning_content;
    } else if (data?.choices?.[0]?.message?.reasoning) {
      text = data.choices[0].message.reasoning;
    } else if (Array.isArray(data?.content) && data.content[0]?.text) {
      text = data.content[0].text;
    } else if (data?.candidates?.[0]?.content?.parts?.[0]?.text) {
      text = data.candidates[0].content.parts[0].text;
    } else if (typeof data?.text === "string") {
      text = data.text;
    } else if (typeof data?.content === "string") {
      text = data.content;
    } else {
      text = JSON.stringify(data);
    }

    const successBody: Record<string, unknown> = { ok: true, latencyMs, text };
    if (cacheKey) {
      await putCachedChat(cacheKey, successBody);
    }
    return NextResponse.json(successBody, { headers: { "X-Cache": cacheKey ? "MISS" : "BYPASS" } });
  } catch (e: unknown) {
    const isAbort = e instanceof Error && e.name === "AbortError";
    const isFetchFail = e instanceof Error && (e.message.includes("fetch") || e.message.includes("Failed to fetch"));
    const msg = isAbort
      ? `Provider request timed out after ${proxyTimeoutMs / 1000}s`
      : isFetchFail
      ? "The provider endpoint is unreachable. Possible causes: wrong URL, CORS blocked, provider offline."
      : (e instanceof Error ? e.message : "Connection failed");
    console.warn("[ProviderChat] Unhandled error:", msg);
    // Return BOTH `error` and `message` so clients checking either field work.
    // The timeout message includes "timed out" so client-side isTimeoutError()
    // can detect it and apply the timeout cooldown.
    return NextResponse.json({
      ok: false, success: false, code: "PROVIDER_CHAT_FAILED",
      error: msg, message: msg, latencyMs: 0,
      isTimeout: isAbort,
    });
  }
}

