export const runtime = "edge";

export async function POST(_req: NextRequest) {
  const ZAI_API_KEY = process.env.ZAI_API_KEY || process.env.NEXT_PUBLIC_ZAI_API_KEY || "";

  if (!ZAI_API_KEY) {
    return NextResponse.json({
