    });

    if (!res.ok) {
      return NextResponse.json({
        ok: false,
        error: "Z.ai API key is no longer valid. Please reconnect.",
      }, { status: 401 });
    }

    return NextResponse.json({
      ok: true,
      authenticated: true,
      expiresAt: Date.now() + 24 * 60 * 60 * 1000,
    });
  } catch (e: any) {
    return NextResponse.json({
      ok: false,
      error: `Refresh failed: ${e?.message || "Unknown error"}`,
    }, { status: 500 });
