@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  html {
    scroll-behavior: smooth;
    overflow-x: hidden; /* prevent horizontal page scroll on mobile */
  }
  body {
    @apply bg-background text-foreground antialiased;
    font-feature-settings: "rlig" 1, "calt" 1;
    overflow-x: hidden; /* safety net: prevent horizontal page scroll on mobile */
    width: 100%;
  }
  ::selection {
    background-color: color-mix(in srgb, var(--brand) 22%, transparent);
  }
  /* Custom scrollbar */
  ::-webkit-scrollbar {
    width: 10px;
    height: 10px;
  }
  ::-webkit-scrollbar-track {
    background: transparent;
  }
  ::-webkit-scrollbar-thumb {
    background: color-mix(in srgb, var(--muted-foreground) 30%, transparent);
    border-radius: 9999px;
    border: 2px solid transparent;
    background-clip: padding-box;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: color-mix(in srgb, var(--muted-foreground) 55%, transparent);
    background-clip: padding-box;
    border: 2px solid transparent;
  }
  /* Thin scrollbar variant for horizontal tab strips on mobile */
  .scrollbar-thin::-webkit-scrollbar {
    width: 4px;
    height: 4px;
  }
  .scrollbar-thin::-webkit-scrollbar-thumb {
    background: color-mix(in srgb, var(--muted-foreground) 25%, transparent);
    border: none;
    border-radius: 9999px;
  }
  .scrollbar-thin {
    scrollbar-width: thin;
    scrollbar-color: color-mix(in srgb, var(--muted-foreground) 25%, transparent) transparent;
  }
}

/* Utilities */
@layer utilities {
  .text-balance { text-wrap: balance; }
  .text-pretty { text-wrap: pretty; }

  .gradient-brand {
    background-image: linear-gradient(135deg, var(--brand) 0%, var(--brand-dark) 100%);
  }
  .gradient-gold {
