import { FallbackChain } from "./modules/FallbackChain";
import { PipelineProfiles } from "./modules/PipelineProfiles";
import { AgentConfigCenter } from "./modules/AgentConfigCenter";
import { AIDevAgent } from "./modules/AIDevAgent";
import { AIWorkspace } from "./modules/AIWorkspace";
import { Workers } from "./modules/Workers";
import { RecruiterIntelligence } from "./modules/RecruiterIntelligence";
import { CandidateExperience } from "./modules/CandidateExperience";
import { FlightRecorderConsole } from "./modules/FlightRecorderConsole";
import { InterviewAnalytics } from "./modules/InterviewAnalytics";
import { InterviewReports } from "./modules/InterviewReports";
import { Explainability } from "./modules/Explainability";
import { ScenarioManagement } from "./modules/ScenarioManagement";
import { PersonaManagement } from "./modules/PersonaManagement";
import {
  LinkedinImport, ResumeVersioning, MultiLanguage, ResumeSharing, AbTesting,
  BulkGenerator, ResumeAnalytics, SalaryInsights, SkillGap,
  CareerPath, CompanyResearch, JobAlerts, CertTracker, Networking,
  AiCoach, AiMockInterview, AiSalaryCoach, AiEmailWriter,
  AiJobMatch, AiAchievement, Integrations,
} from "./modules/CareerTools";
import { VoiceMockInterview } from "./modules/VoiceMockInterview";
import { ApplicationTracker } from "./modules/ApplicationTracker";
import { ResumeReviewPlatform } from "./modules/ResumeReviewPlatform";
import { BatchOptimizer } from "./modules/BatchOptimizer";
import { SafeRender } from "./SafeRender";
import { GlobalErrorCatcher } from "@/components/shared/GlobalErrorCatcher";
import { Button } from "@/components/ui/button";
import { Icon } from "@/components/shared";
import { toast } from "sonner";
import type { ViewKey, AIProvider } from "@/lib/types";

const VIEW_COMPONENTS: Record<ViewKey, React.FC> = {
  landing: Dashboard, // never used (landing renders separately)
  dashboard: Dashboard,
  resumes: MyResumes,
  "ats-checker": ATSChecker,
  builder: Builder,
  optimizer: Optimizer,
  "cover-letter": CoverLetter,
  interview: Interview,
  "jd-scraper": JDScraper,
  "ai-tools": AITools,
  downloads: Downloads,
  settings: Settings,
  admin: Admin,
  users: Users,
  "user-approvals": UserApprovals,
  "suspended-users": UserApprovals, // reuse — shows same component, filtered differently
  analytics: Analytics,
  "super-admin": SuperAdmin,
  "ai-providers": AIProviders,
  "ai-models": AIModels,
  "ai-settings": AIProviderSettings,
  "ai-logs": Logs,
  prompts: Prompts,
  branding: Branding,
  "feature-flags": FeatureFlags,
  "optimizer-directive": OptimizerDirective,
  "fallback-chain": FallbackChain,
  "pipeline-profiles": PipelineProfiles,
  "agent-config": AgentConfigCenter,
  "ai-dev-agent": AIDevAgent,
  "ai-workspace": AIWorkspace,
  "workers": Workers,
  "linkedin-import": LinkedinImport,
  "resume-versioning": ResumeVersioning,
  "multi-language": MultiLanguage,
  "resume-sharing": ResumeSharing,
  "ab-testing": AbTesting,
  "bulk-generator": BulkGenerator,
  "resume-analytics": ResumeAnalytics,
  "app-tracker": ApplicationTracker,
  "salary-insights": SalaryInsights,
  "skill-gap": SkillGap,
  "career-path": CareerPath,
  "company-research": CompanyResearch,
  "job-alerts": JobAlerts,
  "cert-tracker": CertTracker,
  "networking": Networking,
  "ai-coach": AiCoach,
  "ai-mock-interview": AiMockInterview,
  "ai-voice-interview": VoiceMockInterview,
  "ai-salary-coach": AiSalaryCoach,
  "ai-email-writer": AiEmailWriter,
  "ai-resume-review": ResumeReviewPlatform,
  "ai-job-match": AiJobMatch,
  "ai-achievement": AiAchievement,
  "integrations": Integrations,
  "batch-optimizer": BatchOptimizer,
  "recruiter": RecruiterIntelligence,
  "candidate-experience": CandidateExperience,
  "flight-recorder": FlightRecorderConsole,
  "interview-analytics": InterviewAnalytics,
  "interview-reports": InterviewReports,
  "explainability": Explainability,
  "scenario-mgmt": ScenarioManagement,
  "persona-mgmt": PersonaManagement,
  logs: Logs,
};

// ============================================================================
// Access control — which views require which role.
// ============================================================================
// The sidebar already hides these views from non-superadmin users, but this
// map enforces access control at the AppShell level too. If a user somehow
// navigates to a restricted view (via browser history, URL, or programmatic
// setView), they'll be redirected to the dashboard instead of seeing the
// restricted content.

const SUPER_ADMIN_VIEWS: ViewKey[] = [
  "super-admin",
  "user-approvals",
  "suspended-users",
  "ai-providers",
  "ai-models",
  "ai-settings",
  "ai-logs",
  "prompts",
  "branding",
  "feature-flags",
  "optimizer-directive",
  "fallback-chain",
  "pipeline-profiles",
  "agent-config",
  "ai-dev-agent",
  "ai-workspace",
  "scenario-mgmt",
  "persona-mgmt",
  "logs",
];

const ADMIN_VIEWS: ViewKey[] = [
  "admin",
  "users",
  "analytics",
  "recruiter",
  "flight-recorder",
  "interview-analytics",
  "interview-reports",
  "explainability",
];

/**
 * Check if the user's role allows access to the given view.
 *   - "user" → only NAV_USER views (dashboard, resumes, tools, settings, downloads)
 *   - "admin" → NAV_USER + NAV_ADMIN views (admin overview, users, analytics)
 *   - "super_admin" → all views (including AI providers, branding, feature flags, logs)
 */
function canAccessView(view: ViewKey, role: string): boolean {
  // Super admin can access everything
  if (role === "super_admin") return true;
  // Admin can access user + admin views (but NOT super-admin views)
  if (role === "admin") {
    return !SUPER_ADMIN_VIEWS.includes(view);
  }
  // Regular user can only access user views (NOT admin or super-admin views)
  return !SUPER_ADMIN_VIEWS.includes(view) && !ADMIN_VIEWS.includes(view);
}

export function AppShell() {
  const view = useApp((s) => s.view) as ViewKey;
  const setView = useApp((s) => s.setView);
  const user = useApp((s) => s.user);
  const role = user?.role ?? "user";
  const fallbackOfferOpen = useApp((s) => s.fallbackOfferOpen);

  // Task 19 — bootstrap Puter account restore.
  // Accounts live in localStorage + the accounts API, but they were only
  // reloaded when the AI Providers module mounted. After a page refresh on
  // ANY other view the provider singleton started EMPTY, so Puter silently
  // fell back to anonymous (heavily limited) mode — which made the optimizer
  // exhaust the chain and die at the heavy Resume Optimizer step (~50%), and
  // made "auto-rotate accounts" look broken (nothing to rotate).
  useEffect(() => {
    getPuterProvider().restore().catch((e) =>
      console.warn("[AppShell] Puter account restore failed:", e instanceof Error ? e.message : e)
    );
  }, []);

  // Access control: if the current view requires a higher role than the user
  // has, redirect to the dashboard. This prevents non-superadmin users from
  // seeing AI Providers, API settings, branding, feature flags, etc. even if
  // they somehow trigger setView("ai-providers").
  useEffect(() => {
    if (!canAccessView(view, role)) {
      console.warn(`[AppShell] Access denied: user role "${role}" cannot view "${view}". Redirecting to dashboard.`);
      setView("dashboard");
    }
  }, [view, role, setView]);

  // If the view is restricted, render the dashboard while the redirect effect runs
  const effectiveView = canAccessView(view, role) ? view : "dashboard";
  // Build a friendly label for the error boundary based on the view
  const viewLabel = effectiveView.replace(/-/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
  const ActiveView = VIEW_COMPONENTS[effectiveView] ?? Dashboard;

  return (
    <div className="min-h-screen flex bg-background">
      <GlobalErrorCatcher />
      <Sidebar />
      <div className="flex-1 flex flex-col min-w-0">
        <TopBar />
        <main className="flex-1 p-4 sm:p-6 max-w-[1400px] w-full mx-auto overflow-x-hidden">
          <AnimatePresence mode="wait">
            <motion.div
              key={effectiveView}
              initial={{ opacity: 0, y: 8 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -4 }}
              transition={{ duration: 0.2 }}
            >
              <SafeRender label={viewLabel}>
                <ActiveView />
              </SafeRender>
            </motion.div>
          </AnimatePresence>
        </main>
      </div>
      <AnimatePresence>
        {fallbackOfferOpen && <FallbackOfferModal />}
      </AnimatePresence>
    </div>
  );
}

function FallbackOfferModal() {
  const fallbackOfferChoices = useApp((s) => s.fallbackOfferChoices);
  const closeFallbackOffer = useApp((s) => s.closeFallbackOffer);
  const setDefaultProvider = useApp((s) => s.setDefaultProvider);

  const handleSelect = (providerId: string, providerName: string) => {
    setDefaultProvider(providerId);
    closeFallbackOffer();
    toast.success(`Switched default provider to ${providerName}. Please retry your operation.`);
  };

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="fixed inset-0 z-50 bg-background/80 backdrop-blur-sm flex items-center justify-center p-4"
      onClick={closeFallbackOffer}
    >
      <motion.div
        initial={{ y: 20, opacity: 0, scale: 0.97 }}
        animate={{ y: 0, opacity: 1, scale: 1 }}
        exit={{ y: 20, opacity: 0, scale: 0.97 }}
        transition={{ type: "spring", damping: 26, stiffness: 280 }}
        className="bg-card rounded-2xl border border-border shadow-premium w-full max-w-md overflow-hidden"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="p-6 border-b border-border flex items-start gap-4">
          <div className="w-10 h-10 rounded-full bg-amber-500/10 flex items-center justify-center shrink-0">
            <Icon name="AlertTriangle" className="w-5 h-5 text-amber-500" />
          </div>
          <div className="flex-1">
            <h3 className="font-display font-bold text-lg text-foreground">
              Rate Limit Encountered
            </h3>
            <p className="text-sm text-muted-foreground mt-1">
              OpenCode Zen free models are temporarily rate-limited for third-party applications. Switch to a recommended fallback provider to continue.
            </p>
          </div>
          <Button variant="ghost" size="icon" className="-mt-1 -mr-2" onClick={closeFallbackOffer}>
            <Icon name="X" className="w-4 h-4" />
          </Button>
        </div>

        <div className="p-6 space-y-3">
          <div className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">
            Recommended Fallbacks
          </div>

          {fallbackOfferChoices.length === 0 ? (
            <p className="text-sm text-muted-foreground">No fallback providers configured. Please go to AI Providers settings to configure a provider.</p>
          ) : (
            <div className="space-y-2">
              {fallbackOfferChoices.map((p: AIProvider) => {
                let badgeText = "Recommended Fallback";
                if (p.type === "puter") badgeText = "Free & Keyless (Puter.js)";
                else if (p.type === "gemini") badgeText = "Google Gemini API";
                else if (p.type === "openrouter") badgeText = "OpenRouter API";
                else if (p.type === "opencode") badgeText = "Paid Zen Model";

                return (
                  <button
                    key={p.id}
                    onClick={() => handleSelect(p.id, p.name)}
                    className="w-full text-left p-3.5 rounded-xl border border-border bg-card hover:bg-accent/50 hover:border-brand/40 transition-all flex items-center justify-between group"
                  >
                    <div>
                      <div className="font-medium text-foreground group-hover:text-brand transition-colors">
                        {p.name}
                      </div>
                      <div className="text-xs text-muted-foreground mt-0.5">
                        {badgeText} · {p.modelName || "Default Model"}
                      </div>
                    </div>
                    <Icon name="ChevronRight" className="w-4 h-4 text-muted-foreground group-hover:text-brand group-hover:translate-x-0.5 transition-all" />
                  </button>
                );
              })}
            </div>
          )}
        </div>

        <div className="p-4 bg-muted/40 border-t border-border flex justify-end gap-2">
          <Button variant="outline" onClick={closeFallbackOffer}>
            Cancel
          </Button>
        </div>
      </motion.div>
    </motion.div>
  );
}

src/components/app/AuthModal.tsx:
"use client";

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Icon, Logo } from "@/components/shared";
import { useApp, uid } from "@/lib/store";
import { toast } from "sonner";
import { BRAND } from "@/lib/brand";
import { validateRealEmail } from "@/lib/email-validation";
import { validatePassword, passwordStrength } from "@/lib/auth-utils";
import type { User } from "@/lib/types";

export function AuthModal() {
  const open = useApp((s) => s.authOpen);
  const close = useApp((s) => s.closeAuth);
  const signIn = useApp((s) => s.signIn);
  const signInWithEmail = useApp((s) => s.signInWithEmail);
  const registerWithEmail = useApp((s) => s.registerWithEmail);
  const signInWithPuter = useApp((s) => s.signInWithPuter);
  const [mode, setMode] = useState<"signin" | "signup">("signin");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [name, setName] = useState("");
  const [username, setUsername] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState<string | null>(null);

  // === Puter.js sign in ===
  // Puter users are auto-approved (their email is verified by Puter's OAuth:
  // Google/GitHub/etc), so they go straight to the dashboard without admin approval.
  const handlePuter = async () => {
    setLoading("puter");
    const result = await signInWithPuter();
    if (!result.ok) {
      toast.error(result.error || "Puter sign-in failed.");
    } else if (result.user) {
      // Puter users are always auto-approved — no pending state possible.
      toast.success(`Welcome to ${BRAND.name}!`);
    }
    setLoading(null);
  };

  // === Email sign in ===
  const handleEmailSignIn = async () => {
    const emailCheck = validateRealEmail(email);
    if (!emailCheck.valid) {
      toast.error(emailCheck.error || "Please enter a valid email.");
      return;
    }
    if (password.length < 4) {
      toast.error("Password must be at least 4 characters.");
      return;
    }
    setLoading("email");
    await new Promise((r) => setTimeout(r, 400));
    const result = signInWithEmail(email, password);
    setLoading(null);
    if (!result.ok) {
      toast.error(result.error || "Sign in failed.");
    } else if (result.user) {
      if (result.user.status === "pending") {
        toast.success("Signed in. Your account is awaiting admin approval.");
      } else {
        toast.success(`Welcome back, ${result.user.name}!`);
      }
    }
  };

  // === Email registration ===
  const handleEmailSignUp = async () => {
    const emailCheck = validateRealEmail(email);
    if (!emailCheck.valid) {
      toast.error(emailCheck.error || "Please enter a valid email.");
      return;
    }
    const pwCheck = validatePassword(password);
    if (!pwCheck.valid) {
      toast.error(`Password requirements: ${pwCheck.errors.join(", ")}`);
      return;
    }
    if (name.trim().length < 2) {
      toast.error("Please enter your name.");
      return;
    }
    setLoading("email");
    await new Promise((r) => setTimeout(r, 400));
    const result = registerWithEmail(email, password, name, username);
    setLoading(null);
    if (!result.ok) {
      toast.error(result.error || "Registration failed.");
    } else if (result.user) {
      toast.success("Account created! Your account is pending admin approval. You'll be notified when approved.");
    }
  };

  const strength = passwordStrength(password);
  const strengthLabel = ["Too weak", "Weak", "Fair", "Good", "Strong"][strength];
  const strengthColor = ["#DC2626", "#DC2626", "#F59E0B", "#1154A3", "#10B981"][strength];

  return (
    <AnimatePresence>
      {open && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-background/80 backdrop-blur-sm"
          onClick={close}
        >
          <motion.div
            initial={{ opacity: 0, scale: 0.96, y: 12 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.96, y: 12 }}
            transition={{ type: "spring", damping: 24, stiffness: 300 }}
            className="relative w-full max-w-md bg-card rounded-2xl border border-border shadow-premium overflow-hidden"
            onClick={(e) => e.stopPropagation()}
            role="dialog"
            aria-modal="true"
          >
            {/* Header band */}
            <div className="gradient-brand text-white p-6 relative">
              <button onClick={close} className="absolute top-4 right-4 w-8 h-8 rounded-full bg-white/15 hover:bg-white/25 flex items-center justify-center" aria-label="Close">
                <Icon name="X" className="w-4 h-4" />
              </button>
              <Logo size={36} className="[&_span]:text-white [&_.gradient-text]:text-white" />
              <h2 className="font-display text-xl font-bold mt-3">
                {mode === "signin" ? "Welcome back" : "Create your account"}
              </h2>
              <p className="text-sm text-white/80 mt-1">
                100% free forever. No credit card. No paywall.
              </p>
            </div>

            <div className="p-6 space-y-4">
              {/* Continue with Puter */}
              <Button onClick={handlePuter} disabled={!!loading} className="w-full bg-brand hover:bg-brand-dark text-white gap-2 h-11">
                {loading === "puter" ? <Icon name="Loader2" className="w-4 h-4 animate-spin" /> : <Icon name="Sparkles" className="w-4 h-4" />}
                Continue with Puter (free AI)
              </Button>

              <div className="relative">
                <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-border" /></div>
                <div className="relative flex justify-center"><span className="px-2 bg-card text-xs text-muted-foreground">or with email</span></div>
              </div>

              {/* Email/Password form */}
              {mode === "signup" && (
                <div className="space-y-1.5">
                  <Label htmlFor="auth-name">Full name</Label>
                  <Input id="auth-name" value={name} onChange={(e) => setName(e.target.value)} placeholder="John Doe" />
                </div>
              )}
              {mode === "signup" && (
                <div className="space-y-1.5">
                  <Label htmlFor="auth-username">Username (optional)</Label>
                  <Input id="auth-username" value={username} onChange={(e) => setUsername(e.target.value)} placeholder="johndoe" />
                </div>
              )}
              <div className="space-y-1.5">
                <Label htmlFor="auth-email">Email</Label>
                <Input id="auth-email" type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@gmail.com" onKeyDown={(e) => e.key === "Enter" && (mode === "signin" ? handleEmailSignIn() : handleEmailSignUp())} />
              </div>
              <div className="space-y-1.5">
                <Label htmlFor="auth-pass">Password</Label>
                <div className="relative">
                  <Input
                    id="auth-pass"
                    type={showPassword ? "text" : "password"}
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    placeholder={mode === "signup" ? "Min 12 chars, Aa1!" : "••••••••"}
                    className="pr-9"
                    onKeyDown={(e) => e.key === "Enter" && (mode === "signin" ? handleEmailSignIn() : handleEmailSignUp())}
                  />
                  <button type="button" onClick={() => setShowPassword((v) => !v)} className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground" aria-label="Toggle visibility">
                    <Icon name={showPassword ? "EyeOff" : "Eye"} className="w-4 h-4" />
                  </button>
                </div>
                {mode === "signup" && password && (
                  <div className="space-y-1">
                    <div className="flex gap-1">
                      {[0, 1, 2, 3, 4].map((i) => (
                        <div key={i} className="h-1.5 flex-1 rounded-full transition-all" style={{ background: i < strength ? strengthColor : "var(--muted)" }} />
                      ))}
                    </div>
                    <span className="text-[10px]" style={{ color: strengthColor }}>{strengthLabel}</span>
                  </div>
                )}
              </div>

              <Button
                onClick={mode === "signin" ? handleEmailSignIn : handleEmailSignUp}
                disabled={!!loading}
                className="w-full bg-brand hover:bg-brand-dark text-white gap-2"
              >
                {loading === "email" ? <Icon name="Loader2" className="w-4 h-4 animate-spin" /> : <Icon name="ArrowRight" className="w-4 h-4" />}
                {mode === "signin" ? "Sign in" : "Create account"}
              </Button>

              <p className="text-center text-xs text-muted-foreground">
                {mode === "signin" ? "New to ResumeAI Pro?" : "Already have an account?"}{" "}
                <button onClick={() => setMode(mode === "signin" ? "signup" : "signin")} className="text-brand font-medium hover:underline">
                  {mode === "signin" ? "Create an account" : "Sign in"}
                </button>
              </p>

              {mode === "signup" && (
                <p className="text-center text-[11px] text-muted-foreground">
                  New accounts require admin approval before accessing features.
                </p>
              )}
            </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

