"use client";

import { recordAI, setFlightScope } from "@/lib/ai/flight-recorder";
setFlightScope({ scope: "resume-copilot", feature: "AI Tools", module: "src.components.app.modules.AITools" });

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Badge, Icon } from "@/components/shared";
import { useApp, uid } from "@/lib/store";
import { callAI } from "@/lib/ai";
import { toast } from "sonner";

const TOOLS = [
  { id: "summary", name: "Professional Summary Generator", icon: "AlignLeft", desc: "Generate a 2-3 line summary from your experience.", color: "#1154A3" },
  { id: "bullets", name: "Bullet Point Generator", icon: "List", desc: "Rewrite weak bullets with measurable outcomes.", color: "#F59E0B" },
  { id: "linkedin", name: "LinkedIn Profile Generator", icon: "Linkedin", desc: "Generate a full LinkedIn About + Experience section.", color: "#0EA5E9" },
  { id: "translator", name: "Resume Translator", icon: "Languages", desc: "Translate your resume to 30+ languages.", color: "#10B981" },
  { id: "career", name: "Career Advisor", icon: "Compass", desc: "Get tailored next-role suggestions.", color: "#8B5CF6" },
  { id: "keywords", name: "Keyword Generator", icon: "KeyRound", desc: "Extract industry keywords from your field.", color: "#EC4899" },
  { id: "skills", name: "Skill Suggestions", icon: "Wrench", desc: "Suggest skills you should add based on your role.", color: "#1154A3" },
  { id: "rewrite", name: "Resume Rewriter", icon: "RefreshCcw", desc: "Rewrite your entire resume section-by-section.", color: "#F59E0B" },
  { id: "salary", name: "Salary Negotiator", icon: "DollarSign", desc: "Draft a professional email to negotiate salary offers.", color: "#10B981" },
  { id: "interview", name: "Interview Q&A Builder", icon: "MessagesSquare", desc: "Generate mock interview Q&As tailored to your resume.", color: "#8B5CF6" },
  { id: "cover_letter_outline", name: "Cover Letter Outline", icon: "FileText", desc: "Create a structured outline for your cover letter.", color: "#EC4899" },
  { id: "roast", name: "Resume Roaster (Critic)", icon: "Flame", desc: "Roast your resume with brutal, constructive feedback.", color: "#DC2626" },
  { id: "star_transformer", name: "STAR Bullet Transformer", icon: "Wand2", desc: "Convert weak bullets into metric-driven STAR bullets.", color: "#10B981" },
  { id: "cold_pitch", name: "Cold Outreach Pitcher", icon: "Mail", desc: "Draft personalized cold emails to recruiters.", color: "#8B5CF6" },
];

export function AITools() {
  const resumes = useApp((s) => s.resumes);
  const incUsage = useApp((s) => s.incUsage);
  const log = useApp((s) => s.log);

  const [active, setActive] = useState<string | null>(null);
  const [input, setInput] = useState("");
  const [output, setOutput] = useState("");
  const [running, setRunning] = useState(false);

  const resume = resumes[0];

  const run = async () => {
    if (!active) return;
    setRunning(true);
    setOutput("");
    try {
      let sys = "You are ResumeAI Pro, an expert career assistant. Respond clearly and concisely.";
      let user = input;
      if (active === "summary") {
        user = `Generate a 2-3 line professional summary for:\n${input || JSON.stringify(resume?.experience)}`;
      } else if (active === "bullets") {
        user = `Rewrite these bullets with strong action verbs and measurable outcomes (one per line):\n${input}`;
      } else if (active === "linkedin") {
        user = `Generate a LinkedIn About section (~250 words) and 3 experience entries from this resume:\n${input || JSON.stringify(resume ?? {})}`;
      } else if (active === "translator") {
        user = `Translate this resume content to French (keep proper nouns):\n${input}`;
      } else if (active === "career") {
        user = `Suggest 5 next career roles with rationale, based on:\n${input || JSON.stringify(resume?.experience)}`;
      } else if (active === "keywords") {
        user = `Extract the 15 most important ATS keywords for this role/field:\n${input}`;
      } else if (active === "skills") {
        user = `Suggest 10 skills (with brief justification) this candidate should add:\n${input || JSON.stringify(resume?.skills)}`;
      } else if (active === "rewrite") {
        user = `Rewrite this resume section to be ATS-friendly and impactful:\n${input}`;
      } else if (active === "salary") {
        user = `Draft a professional email to negotiate a salary offer based on these details (role, target salary, original offer):\n${input}`;
      } else if (active === "interview") {
        user = `Generate 5 custom behavioral interview questions (STAR method) and recommended answers for this resume:\n${input || JSON.stringify(resume ?? {})}`;
      } else if (active === "cover_letter_outline") {
        user = `Create a structured cover letter outline based on this target role/description:\n${input}`;
      } else if (active === "roast") {
        sys = "You are a brutally honest, highly critical, yet constructive resume auditor. Roast this resume with sharp humor and direct remarks on formatting, clichés, metrics, and experience structure. Give 5 bullet points of roasting and then provide a fully rewritten better version.";
        user = `Roast this resume and rewrite it to be 10x better:\n${input || JSON.stringify(resume ?? {})}`;
      } else if (active === "star_transformer") {
        sys = "You are an elite interview prep coach. Take a candidate's weak resume bullet point and transform it into the high-impact STAR method (Situation, Task, Action, Result) with clear metrics.";
        user = `Transform this weak achievement bullet point into a strong STAR bullet point (include metrics):\n${input}`;
      } else if (active === "cold_pitch") {
        sys = "You are an expert recruiter outreach strategist. Write a highly personalized, brief, and professional cold email pitch or LinkedIn message to a hiring manager or recruiter.";
        user = `Write a personalized cold email pitch based on this resume and target role details:\n${input || JSON.stringify(resume ?? {})}`;
      }
      const result = await recordAI({ systemPrompt: sys, userPrompt: user, maxTokens: 1500, taskCategory: "document" });
      setOutput(result.text);
      incUsage("resumesGenerated");
      log({ actor: "you", action: `AI tool: ${active}`, category: "ai", details: `via ${result.provider}`, severity: "info" });
      toast.success(`Generated via ${result.provider}`);
    } catch (e: any) {
      toast.error(e?.message || "Failed.");
    } finally {
      setRunning(false);
    }
  };

  return (
    <div className="space-y-6">
      <div>
        <h1 className="font-display text-2xl font-bold flex items-center gap-2"><Icon name="Sparkles" className="w-6 h-6 text-brand" /> AI Tools</h1>
        <p className="text-sm text-muted-foreground mt-1">Fourteen AI-powered generators. Free, unlimited. Pick a tool and start writing.</p>
      </div>

      <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-3">
        {TOOLS.map((t) => (
          <button
            key={t.id}
            onClick={() => { setActive(t.id); setInput(""); setOutput(""); }}
            className={`text-left rounded-xl border p-4 transition ${active === t.id ? "border-brand bg-brand-light/40 shadow-premium" : "border-border hover:border-brand/40 hover:shadow-card"}`}
          >
            <div className="w-10 h-10 rounded-lg flex items-center justify-center mb-3" style={{ background: `${t.color}15`, color: t.color }}>
              <Icon name={t.icon} className="w-5 h-5" />
            </div>
            <div className="font-semibold text-sm">{t.name}</div>
            <div className="text-xs text-muted-foreground mt-1">{t.desc}</div>
          </button>
        ))}
      </div>

      {active && (
        <Card>
          <CardHeader>
            <div className="flex items-center justify-between">
              <CardTitle className="text-base flex items-center gap-2">
                <Icon name={TOOLS.find((t) => t.id === active)?.icon ?? "Sparkles"} className="w-4 h-4 text-brand" />
                {TOOLS.find((t) => t.id === active)?.name}
              </CardTitle>
              <Button size="sm" variant="ghost" onClick={() => setActive(null)}><Icon name="X" className="w-4 h-4" /></Button>
            </div>
          </CardHeader>
          <CardContent className="space-y-3">
            <Textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              rows={6}
              placeholder="Paste your content here, or leave blank to use your current resume…"
            />
            <Button onClick={run} disabled={running} className="bg-brand hover:bg-brand-dark text-white gap-2">
              {running ? <Icon name="Loader2" className="w-4 h-4 animate-spin" /> : <Icon name="Sparkles" className="w-4 h-4" />}
              {running ? "Generating…" : "Generate"}
            </Button>
            {output && (
              <div className="rounded-lg border border-border bg-secondary/40 p-4">
                <div className="flex items-center justify-between mb-2">
                  <Badge variant="success"><Icon name="CheckCircle2" className="w-3 h-3" /> Output</Badge>
                  <Button size="sm" variant="ghost" onClick={() => { navigator.clipboard.writeText(output); toast.success("Copied to clipboard."); }}>
                    <Icon name="Copy" className="w-3.5 h-3.5" /> Copy
                  </Button>
                </div>
                <pre className="whitespace-pre-wrap text-sm font-sans text-foreground/90 text-pretty">{output}</pre>
              </div>
            )}
          </CardContent>
        </Card>
      )}
    </div>
  );
}

src/components/app/modules/Analytics.tsx:
"use client";

import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Badge, Icon } from "@/components/shared";
import { useApp } from "@/lib/store";
import {
  BarChart, Bar, PieChart, Pie, Cell, LineChart, Line,
  XAxis, YAxis, Tooltip, ResponsiveContainer,
} from "recharts";

export function Analytics() {
  const resumes = useApp((s) => s.resumes);
  const atsReports = useApp((s) => s.atsReports);
  const coverLetters = useApp((s) => s.coverLetters);
  const interviews = useApp((s) => s.interviews);
  const users = useApp((s) => s.users);
  const downloads = useApp((s) => s.logs).filter((l) => /export|download/i.test(l.action));

  // Live KPIs from actual store data
  const avgATS = atsReports.length > 0
    ? Math.round(atsReports.reduce((sum, r) => sum + (r.scores?.ats || 0), 0) / atsReports.length)
    : 0;

  const kpis = [
    { label: "Avg ATS score", value: avgATS.toString(), icon: "Gauge", color: "#1154A3" },
    { label: "Total resumes", value: resumes.length.toString(), icon: "FileText", color: "#F59E0B" },
    { label: "Cover letters", value: coverLetters.length.toString(), icon: "Mail", color: "#10B981" },
    { label: "Downloads", value: downloads.length.toString(), icon: "Download", color: "#8B5CF6" },
  ];

  // Live ATS score trend from actual reports
  const scoreTrend = atsReports.slice(0, 10).reverse().map((r, i) => ({
    name: `#${i + 1}`,
    avg: r.scores?.ats || 0,
  }));

  // Live template usage from actual resumes
  const templateCounts: Record<string, number> = {};
  for (const r of resumes) {
    const tpl = r.template || "default";
    templateCounts[tpl] = (templateCounts[tpl] || 0) + 1;
  }
  const templateUsage = Object.entries(templateCounts).map(([name, value], i) => ({
    name,
    value,
    color: ["#1154A3", "#F59E0B", "#10B981", "#8B5CF6", "#EC4899", "#94A3B8"][i % 6],
  }));

  // Live funnel from actual data
  const totalUsersCount = users.length;
  const usersWithResumes = users.filter((u) => resumes.some((r) => r.id?.includes(u.id))).length; // simplified
  const funnel = [
    { stage: "Users", value: totalUsersCount },
    { stage: "Resumes", value: resumes.length },
    { stage: "ATS checks", value: atsReports.length },
    { stage: "Cover letters", value: coverLetters.length },
    { stage: "Downloads", value: downloads.length },
  ];

  return (
    <div className="space-y-6">
      <div>
        <h1 className="font-display text-2xl font-bold flex items-center gap-2"><Icon name="BarChart3" className="w-6 h-6 text-brand" /> Analytics</h1>
        <p className="text-sm text-muted-foreground mt-1">Live platform metrics from actual user data.</p>
      </div>

      {/* KPI cards — live data */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        {kpis.map((kpi) => (
          <Card key={kpi.label}>
            <CardContent className="p-5">
              <div className="flex items-center justify-between mb-2">
                <div className="w-10 h-10 rounded-lg flex items-center justify-center" style={{ background: `${kpi.color}15`, color: kpi.color }}>
                  <Icon name={kpi.icon} className="w-5 h-5" />
                </div>
              </div>
              <div className="text-2xl font-bold font-display">{kpi.value}</div>
              <div className="text-xs text-muted-foreground">{kpi.label}</div>
            </CardContent>
          </Card>
        ))}
      </div>

      <div className="grid lg:grid-cols-3 gap-6">
        {/* Score trend — live data */}
        <Card className="lg:col-span-2">
          <CardHeader><CardTitle className="text-lg">ATS score trend</CardTitle><CardDescription>Recent ATS check scores.</CardDescription></CardHeader>
          <CardContent>
            {scoreTrend.length === 0 ? (
              <div className="flex items-center justify-center h-[240px] text-sm text-muted-foreground">
                <div className="text-center">
                  <Icon name="LineChart" className="w-8 h-8 mx-auto mb-2 opacity-40" />
                  No ATS checks yet. Scores will appear here as users run ATS checks.
                </div>
              </div>
            ) : (
              <div style={{ width: "100%", height: 240 }}>
                <ResponsiveContainer>
                  <LineChart data={scoreTrend} margin={{ top: 5, right: 10, bottom: 0, left: -20 }}>
                    <XAxis dataKey="name" tick={{ fontSize: 11 }} stroke="#94A3B8" />
                    <YAxis domain={[0, 100]} tick={{ fontSize: 11 }} stroke="#94A3B8" />
                    <Tooltip contentStyle={{ borderRadius: 8, fontSize: 12 }} />
                    <Line type="monotone" dataKey="avg" stroke="#1154A3" strokeWidth={3} dot={{ r: 4, fill: "#1154A3" }} />
                  </LineChart>
                </ResponsiveContainer>
              </div>
            )}
          </CardContent>
        </Card>

        {/* Template usage — live data */}
        <Card>
          <CardHeader><CardTitle className="text-lg">Template usage</CardTitle></CardHeader>
          <CardContent>
            {templateUsage.length === 0 ? (
              <div className="flex items-center justify-center h-[200px] text-sm text-muted-foreground">
                <div className="text-center">
                  <Icon name="PieChart" className="w-8 h-8 mx-auto mb-2 opacity-40" />
                  No resumes yet.
                </div>
              </div>
            ) : (
              <>
                <div style={{ width: "100%", height: 200 }}>
                  <ResponsiveContainer>
                    <PieChart>
                      <Pie data={templateUsage} dataKey="value" nameKey="name" innerRadius={45} outerRadius={75} paddingAngle={2}>
                        {templateUsage.map((d) => <Cell key={d.name} fill={d.color} />)}
                      </Pie>
                      <Tooltip contentStyle={{ borderRadius: 8, fontSize: 12 }} />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
                <div className="space-y-1 mt-2">
                  {templateUsage.map((t) => (
                    <div key={t.name} className="flex items-center justify-between text-xs">
                      <span className="flex items-center gap-1.5"><span className="w-2 h-2 rounded-full" style={{ background: t.color }} /> {t.name}</span>
                      <span className="font-semibold">{t.value}</span>
                    </div>
                  ))}
                </div>
              </>
            )}
          </CardContent>
        </Card>
      </div>

      {/* Funnel — live data */}
      <Card>
        <CardHeader><CardTitle className="text-lg">User activity funnel</CardTitle><CardDescription>From registered users to downloads.</CardDescription></CardHeader>
        <CardContent>
          <div style={{ width: "100%", height: 260 }}>
            <ResponsiveContainer>
              <BarChart data={funnel} margin={{ top: 5, right: 10, bottom: 0, left: -20 }}>
                <XAxis dataKey="stage" tick={{ fontSize: 11 }} stroke="#94A3B8" />
                <YAxis tick={{ fontSize: 11 }} stroke="#94A3B8" allowDecimals={false} />
                <Tooltip contentStyle={{ borderRadius: 8, fontSize: 12 }} />
                <Bar dataKey="value" fill="#1154A3" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

