// ============================================================================
// Application Tracker — per-user Kanban CRM for job applications.
// ============================================================================
// Replaces the old in-memory AppTracker stub (CareerTools.tsx): everything is
// now persisted through the ApplicationsSlice → Workers API → D1 with strict
// per-user isolation, crash-recovery backups (userScopedKey), status history,
// and follow-up reminders. Domain logic lives in src/lib/applications-logic.ts
// (unit-tested); this file is presentation + wiring only.

"use client";

import { useMemo, useState } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/shared";
import {
  Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle,
} from "@/components/ui/dialog";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import { Icon } from "@/components/shared";
import { useApp } from "@/lib/store";
import { toast } from "sonner";
import {
  APPLICATION_COLUMNS,
  APPLICATION_STATUS_LABELS,
  computeStats,
  daysSinceApplied,
  dueFollowUps,
  isFollowUpDue,
  type ApplicationRecord,
  type ApplicationStatus,
} from "@/lib/applications-logic";

// ---------------------------------------------------------------------------
// Date helpers (form <input type="date"> ↔ ISO)
// ---------------------------------------------------------------------------

function isoToDateInput(iso: string | null): string {
  if (!iso) return "";
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "";
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

function dateInputToIso(value: string): string | null {
  if (!value) return null;
  const d = new Date(`${value}T12:00:00`);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
}

function fmtDate(iso: string | null): string {
  if (!iso) return "—";
  const d = new Date(iso);
  return Number.isNaN(d.getTime()) ? "—" : d.toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" });
}

// ---------------------------------------------------------------------------
// Column / card accents
// ---------------------------------------------------------------------------

const COLUMN_ACCENT: Record<ApplicationStatus, string> = {
  wishlist: "text-muted-foreground",
  applied: "text-sky-600",
  "phone-screen": "text-amber-600",
  interview: "text-violet-600",
  offer: "text-emerald-600",
  rejected: "text-rose-600",
};

const COLUMN_DOT: Record<ApplicationStatus, string> = {
  wishlist: "bg-slate-400",
  applied: "bg-sky-500",
  "phone-screen": "bg-amber-500",
  interview: "bg-violet-500",
  offer: "bg-emerald-500",
  rejected: "bg-rose-500",
};

// ---------------------------------------------------------------------------
// Form state shared by Add + Edit dialogs
// ---------------------------------------------------------------------------

interface FormState {
  company: string;
  role: string;
  status: ApplicationStatus;
  source: string;
  url: string;
  location: string;
  salary: string;
  resumeId: string;
  notes: string;
  appliedAt: string;      // yyyy-mm-dd
  nextActionAt: string;   // yyyy-mm-dd
  nextActionNote: string;
}

function toFormState(a: ApplicationRecord | null): FormState {
  return {
    company: a?.company ?? "",
    role: a?.role ?? "",
    status: a?.status ?? "wishlist",
    source: a?.source ?? "",
    url: a?.url ?? "",
    location: a?.location ?? "",
    salary: a?.salary ?? "",
    resumeId: a?.resumeId ?? "",
    notes: a?.notes ?? "",
    appliedAt: isoToDateInput(a?.appliedAt ?? null),
    nextActionAt: isoToDateInput(a?.nextActionAt ?? null),
    nextActionNote: a?.nextActionNote ?? "",
  };
}

// ---------------------------------------------------------------------------
// Module
// ---------------------------------------------------------------------------

export function ApplicationTracker() {
  const applications = useApp((s) => s.applications);
  const addApplication = useApp((s) => s.addApplication);
  const updateApplication = useApp((s) => s.updateApplication);
  const moveApplication = useApp((s) => s.moveApplication);
  const removeApplication = useApp((s) => s.removeApplication);
  const dismissFollowUp = useApp((s) => s.dismissFollowUp);
  const resumes = useApp((s) => s.resumes);
  const jobDescriptions = useApp((s) => s.jobDescriptions);
  const log = useApp((s) => s.log);

  const [query, setQuery] = useState("");
  const [dragOverCol, setDragOverCol] = useState<ApplicationStatus | null>(null);
  const [addOpen, setAddOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  const stats = useMemo(() => computeStats(applications), [applications]);
  const followUps = useMemo(() => dueFollowUps(applications), [applications]);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return applications;
    return applications.filter((a) =>
      [a.company, a.role, a.location, a.source, a.notes].some((f) => f.toLowerCase().includes(q))
    );
  }, [applications, query]);

  const addDialogOpen = addOpen || editingId !== null;
  const editing = editingId ? applications.find((a) => a.id === editingId) ?? null : null;
  const closeDialog = () => { setAddOpen(false); setEditingId(null); };

  const handleSubmit = (form: FormState) => {
    if (!form.company.trim() || !form.role.trim()) {
      toast.error("Company and role are required.");
      return;
    }
    const payload = {
      company: form.company.trim(),
      role: form.role.trim(),
      status: form.status,
      source: form.source.trim(),
      url: form.url.trim(),
      location: form.location.trim(),
      salary: form.salary.trim(),
      resumeId: form.resumeId || null,
      notes: form.notes,
      appliedAt: dateInputToIso(form.appliedAt),
      nextActionAt: dateInputToIso(form.nextActionAt),
      nextActionNote: form.nextActionNote.trim(),
    };
    if (editingId) {
      const before = editing?.status;
      updateApplication(editingId, payload);
      if (before && before !== form.status) {
        log({ actor: "you", action: "Application status changed", category: "resume", details: `${payload.role} @ ${payload.company}: ${APPLICATION_STATUS_LABELS[before]} → ${APPLICATION_STATUS_LABELS[form.status]}`, severity: "info" });
      } else {
        log({ actor: "you", action: "Application updated", category: "resume", details: `${payload.role} @ ${payload.company}`, severity: "info" });
      }
      toast.success("Application updated");
    } else {
      addApplication(payload);
      log({ actor: "you", action: "Application tracked", category: "resume", details: `${payload.role} @ ${payload.company}`, severity: "info" });
      toast.success("Application added to your pipeline");
    }
    closeDialog();
  };

  const handleDelete = (id: string) => {
    const app = applications.find((a) => a.id === id);
    removeApplication(id);
    log({ actor: "you", action: "Application deleted", category: "resume", details: app ? `${app.role} @ ${app.company}` : id, severity: "warning" });
    toast.success("Application removed");
    closeDialog();
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <h1 className="font-display text-2xl font-bold flex items-center gap-2">
            <Icon name="KanbanSquare" className="w-6 h-6 text-brand" /> Application Tracker
          </h1>
          <p className="text-sm text-muted-foreground mt-1">
            Your pipeline from wishlist to offer — drag cards between columns, set follow-up reminders, and never lose track of an application.
          </p>
        </div>
        <Button onClick={() => setAddOpen(true)} className="bg-brand hover:bg-brand-dark text-white gap-2">
          <Icon name="Plus" className="w-4 h-4" /> Add application
        </Button>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-3">
        <StatCard icon="Layers" label="Total" value={stats.total} hint={`${stats.wishlist} in wishlist`} />
        <StatCard icon="Send" label="Active" value={stats.active} hint="applied / screening / interviewing" />
        <StatCard icon="MessagesSquare" label="Interviews" value={stats.interviews} hint="stage reached" />
        <StatCard icon="Trophy" label="Offers" value={stats.offers} hint={`${Math.round(stats.offerRate * 100)}% of sent`} />
        <StatCard icon="Activity" label="Response rate" value={`${Math.round(stats.responseRate * 100)}%`} hint="employers that replied" />
      </div>

      {/* Follow-ups due */}
      {followUps.length > 0 && (
        <div className="rounded-xl border border-amber-300 bg-amber-50 p-4 dark:border-amber-900 dark:bg-amber-950/40">
          <div className="flex items-center gap-2 font-medium text-amber-900 dark:text-amber-200">
            <Icon name="BellRing" className="w-4 h-4" />
            {followUps.length} follow-up{followUps.length > 1 ? "s" : ""} due
          </div>
          <ul className="mt-2 space-y-1.5">
            {followUps.slice(0, 4).map((a) => (
              <li key={a.id} className="flex flex-wrap items-center gap-2 text-sm text-amber-900 dark:text-amber-100">
                <button className="underline-offset-2 hover:underline font-medium" onClick={() => setEditingId(a.id)}>
                  {a.role} @ {a.company}
                </button>
                <span className="text-xs opacity-80">
                  {a.nextActionNote || "Follow up"} · due {fmtDate(a.nextActionAt)}
                </span>
                <span className="flex-1" />
                <Button size="sm" variant="outline" className="h-7 text-xs" onClick={() => setEditingId(a.id)}>Open</Button>
                <Button size="sm" variant="outline" className="h-7 text-xs" onClick={() => { dismissFollowUp(a.id); toast.success("Follow-up cleared"); }}>Done</Button>
              </li>
            ))}
          </ul>
          {followUps.length > 4 && (
            <p className="mt-2 text-xs text-amber-800 dark:text-amber-300">+{followUps.length - 4} more — open the cards on the board.</p>
          )}
        </div>
      )}

      {/* Search */}
      <div className="relative max-w-sm">
        <Icon name="Search" className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
        <Input
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Search company, role, notes…"
          className="pl-9"
          aria-label="Search applications"
        />
      </div>

      {/* Kanban board */}
      {applications.length === 0 ? (
        <EmptyBoard onAdd={() => setAddOpen(true)} />
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-3">
          {APPLICATION_COLUMNS.map((col) => {
            const cards = filtered.filter((a) => a.status === col);
            return (
              <div
                key={col}
                onDragOver={(e) => { e.preventDefault(); setDragOverCol(col); }}
                onDragLeave={() => setDragOverCol((c) => (c === col ? null : c))}
                onDrop={(e) => {
                  e.preventDefault();
                  setDragOverCol(null);
                  const id = e.dataTransfer.getData("text/plain");
                  if (id) moveApplication(id, col);
                }}
                className={`rounded-xl border p-2 min-h-[140px] transition-colors ${
                  dragOverCol === col ? "border-brand bg-brand/5" : "border-border bg-muted/30"
                }`}
                aria-label={`${APPLICATION_STATUS_LABELS[col]} column`}
              >
                <div className="flex items-center gap-1.5 px-1 pb-2">
                  <span className={`w-2 h-2 rounded-full ${COLUMN_DOT[col]}`} />
                  <span className={`text-xs font-semibold uppercase tracking-wide ${COLUMN_ACCENT[col]}`}>
                    {APPLICATION_STATUS_LABELS[col]}
                  </span>
                  <span className="text-xs text-muted-foreground">({cards.length})</span>
                </div>
                <div className="space-y-2">
                  {cards.map((app) => (
                    <ApplicationCard
                      key={app.id}
                      app={app}
                      onOpen={() => setEditingId(app.id)}
                      onMove={(status) => moveApplication(app.id, status)}
                    />
                  ))}
                  {cards.length === 0 && (
                    <p className="text-[11px] text-muted-foreground px-1 py-3 text-center italic">Drop cards here</p>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Add / Edit dialog */}
      <ApplicationDialog
        open={addDialogOpen}
        editing={editing}
        resumes={resumes}
        jobDescriptions={jobDescriptions}
        onSubmit={handleSubmit}
        onDelete={editingId ? () => handleDelete(editingId) : undefined}
        onClose={closeDialog}
      />
    </div>
  );
}

// ---------------------------------------------------------------------------
// Sub-components
// ---------------------------------------------------------------------------

function StatCard({ icon, label, value, hint }: { icon: string; label: string; value: number | string; hint: string }) {
  return (
    <Card>
      <CardContent className="p-4">
        <div className="flex items-center gap-2 text-muted-foreground">
          <Icon name={icon} className="w-4 h-4" />
          <span className="text-xs font-medium uppercase tracking-wide">{label}</span>
        </div>
        <div className="mt-1 text-2xl font-bold tabular-nums">{value}</div>
        <p className="text-[11px] text-muted-foreground mt-0.5">{hint}</p>
      </CardContent>
    </Card>
  );
}

function ApplicationCard({ app, onOpen, onMove }: { app: ApplicationRecord; onOpen: () => void; onMove: (s: ApplicationStatus) => void }) {
  const due = isFollowUpDue(app);
  const days = daysSinceApplied(app);
  return (
    <div
      draggable
      onDragStart={(e) => {
        e.dataTransfer.setData("text/plain", app.id);
        e.dataTransfer.effectAllowed = "move";
      }}
      onClick={onOpen}
      onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onOpen(); } }}
      role="button"
      tabIndex={0}
      className={`rounded-lg border bg-background p-2.5 cursor-pointer transition-shadow hover:shadow-md ${
        due ? "border-amber-400 ring-1 ring-amber-300" : "border-border"
      }`}
    >
      <div className="flex items-start justify-between gap-1">
        <div className="min-w-0">
          <div className="text-sm font-medium truncate" title={app.role}>{app.role || "Untitled role"}</div>
          <div className="text-xs text-muted-foreground truncate" title={app.company}>{app.company || "—"}</div>
        </div>
        {due && <Icon name="BellRing" className="w-3.5 h-3.5 text-amber-500 shrink-0 mt-0.5" />}
      </div>
      <div className="flex flex-wrap gap-1 mt-1.5">
        {app.location && <Badge variant="outline" className="text-[10px] px-1.5 py-0">{app.location}</Badge>}
        {app.source && <Badge variant="outline" className="text-[10px] px-1.5 py-0">{app.source}</Badge>}
        {days >= 0 && <Badge variant="outline" className="text-[10px] px-1.5 py-0">{days}d since applied</Badge>}
      </div>
      {/* Touch/keyboard-friendly status switch (drag is desktop-only) */}
      <select
        value={app.status}
        onClick={(e) => e.stopPropagation()}
        onChange={(e) => onMove(e.target.value as ApplicationStatus)}
        aria-label={`Change status for ${app.role} at ${app.company}`}
        className="w-full h-7 px-2 rounded-md border border-input bg-background text-xs mt-2"
      >
        {APPLICATION_COLUMNS.map((c) => (
          <option key={c} value={c}>{APPLICATION_STATUS_LABELS[c]}</option>
        ))}
      </select>
    </div>
  );
}

function EmptyBoard({ onAdd }: { onAdd: () => void }) {
  return (
    <Card>
      <CardContent className="p-10 text-center space-y-3">
        <Icon name="KanbanSquare" className="w-12 h-12 mx-auto text-muted-foreground/40" />
        <h3 className="font-semibold">No applications yet</h3>
        <p className="text-sm text-muted-foreground max-w-md mx-auto">
          Track every role you're interested in — save it to your wishlist now, then drag it across the pipeline as you apply, screen, and interview. Set follow-up reminders so no application goes cold.
        </p>
        <Button onClick={onAdd} className="bg-brand hover:bg-brand-dark text-white gap-2">
          <Icon name="Plus" className="w-4 h-4" /> Add your first application
        </Button>
      </CardContent>
    </Card>
  );
}

function ApplicationDialog({
  open, editing, resumes, jobDescriptions, onSubmit, onDelete, onClose,
}: {
  open: boolean;
  editing: ApplicationRecord | null;
  resumes: Array<{ id: string; name?: string; title?: string }>;
  jobDescriptions: Array<{ id: string; title?: string; company?: string; url?: string; location?: string; salary?: string }>;
  onSubmit: (form: FormState) => void;
  onDelete?: () => void;
  onClose: () => void;
}) {
  const [form, setForm] = useState<FormState>(() => toFormState(editing));
  const [prefillJdId, setPrefillJdId] = useState<string>("");

  // Re-seed the form whenever the dialog opens for a different target.
  const [lastKey, setLastKey] = useState<string>("");
  const openKey = editing?.id ?? (open ? "new" : "closed");
  if (open && openKey !== lastKey) {
    setLastKey(openKey);
    setForm(toFormState(editing));
    setPrefillJdId("");
  }

  const set = <K extends keyof FormState>(k: K, v: FormState[K]) => setForm((f) => ({ ...f, [k]: v }));

  const applyJdPrefill = (jdId: string) => {
    setPrefillJdId(jdId);
    const jd = jobDescriptions.find((j) => j.id === jdId);
    if (!jd) return;
    setForm((f) => ({
      ...f,
      role: jd.title || f.role,
      company: jd.company || f.company,
      url: jd.url || f.url,
      location: jd.location || f.location,
      salary: jd.salary || f.salary,
    }));
  };

  return (
    <Dialog open={open} onOpenChange={(o) => { if (!o) onClose(); }}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{editing ? "Edit application" : "Track an application"}</DialogTitle>
          <DialogDescription>
            {editing
              ? "Update details, move it through the pipeline, or adjust the follow-up reminder."
              : "Save a role you're targeting. You can drag it across the board as it progresses."}
          </DialogDescription>
        </DialogHeader>

        {!editing && jobDescriptions.length > 0 && (
          <div className="space-y-1.5">
            <Label>Pre-fill from a saved job description</Label>
            <Select value={prefillJdId} onValueChange={applyJdPrefill}>
              <SelectTrigger><SelectValue placeholder="Choose a saved JD (optional)" /></SelectTrigger>
              <SelectContent>
                {jobDescriptions.slice(0, 50).map((jd) => (
                  <SelectItem key={jd.id} value={jd.id}>
                    {jd.title || "Untitled role"}{jd.company ? ` — ${jd.company}` : ""}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        )}

        <div className="grid sm:grid-cols-2 gap-3">
          <div className="space-y-1.5">
            <Label>Company *</Label>
            <Input value={form.company} onChange={(e) => set("company", e.target.value)} placeholder="Acme Corp" />
          </div>
          <div className="space-y-1.5">
            <Label>Role *</Label>
            <Input value={form.role} onChange={(e) => set("role", e.target.value)} placeholder="Senior Frontend Engineer" />
          </div>
          <div className="space-y-1.5">
            <Label>Status</Label>
            <Select value={form.status} onValueChange={(v) => set("status", v as ApplicationStatus)}>
              <SelectTrigger><SelectValue /></SelectTrigger>
              <SelectContent>
                {APPLICATION_COLUMNS.map((c) => (
                  <SelectItem key={c} value={c}>{APPLICATION_STATUS_LABELS[c]}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div className="space-y-1.5">
            <Label>Source</Label>
            <Input value={form.source} onChange={(e) => set("source", e.target.value)} placeholder="LinkedIn, referral, Bayt…" />
          </div>
          <div className="space-y-1.5 sm:col-span-2">
            <Label>Job posting URL</Label>
            <Input value={form.url} onChange={(e) => set("url", e.target.value)} placeholder="https://…" type="url" />
          </div>
          <div className="space-y-1.5">
            <Label>Location</Label>
            <Input value={form.location} onChange={(e) => set("location", e.target.value)} placeholder="Dubai, UAE" />
          </div>
          <div className="space-y-1.5">
            <Label>Salary</Label>
            <Input value={form.salary} onChange={(e) => set("salary", e.target.value)} placeholder="25k AED / month" />
          </div>
          <div className="space-y-1.5">
            <Label>Applied on</Label>
            <Input type="date" value={form.appliedAt} onChange={(e) => set("appliedAt", e.target.value)} />
          </div>
          <div className="space-y-1.5">
            <Label>Resume sent</Label>
            <Select value={form.resumeId || "none"} onValueChange={(v) => set("resumeId", v === "none" ? "" : v)}>
              <SelectTrigger><SelectValue placeholder="None" /></SelectTrigger>
              <SelectContent>
                <SelectItem value="none">None</SelectItem>
                {resumes.slice(0, 50).map((r) => (
                  <SelectItem key={r.id} value={r.id}>{r.name || r.title || r.id}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div className="space-y-1.5">
            <Label>Follow-up reminder</Label>
            <Input type="date" value={form.nextActionAt} onChange={(e) => set("nextActionAt", e.target.value)} />
          </div>
          <div className="space-y-1.5">
            <Label>Follow-up note</Label>
            <Input value={form.nextActionNote} onChange={(e) => set("nextActionNote", e.target.value)} placeholder="Chase HR for feedback" />
          </div>
          <div className="space-y-1.5 sm:col-span-2">
            <Label>Notes</Label>
            <Textarea
              value={form.notes}
              onChange={(e) => set("notes", e.target.value)}
              placeholder="Interviewer names, tech stack, recruiter contact, next steps…"
              rows={3}
            />
          </div>
        </div>

        {editing && editing.history.length > 0 && (
          <div className="rounded-lg border border-border p-3">
            <div className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-2">Status history</div>
            <ol className="space-y-1 text-xs text-muted-foreground">
              {editing.history.slice(-6).reverse().map((h, i) => (
                <li key={`${h.at}-${i}`} className="flex items-center gap-2">
                  <Icon name="Clock" className="w-3 h-3" />
                  {fmtDate(h.at)} — {h.from ? `${APPLICATION_STATUS_LABELS[h.from]} → ` : ""}
                  <span className="font-medium text-foreground">{APPLICATION_STATUS_LABELS[h.to]}</span>
                </li>
              ))}
            </ol>
          </div>
        )}

        <DialogFooter className="gap-2 sm:justify-between">
          {onDelete ? (
            <Button variant="ghost" className="text-destructive hover:text-destructive gap-1.5" onClick={onDelete}>
              <Icon name="Trash2" className="w-4 h-4" /> Delete
            </Button>
          ) : <span />}
          <div className="flex gap-2">
            <Button variant="outline" onClick={onClose}>Cancel</Button>
            <Button className="bg-brand hover:bg-brand-dark text-white" onClick={() => onSubmit(form)}>
              {editing ? "Save changes" : "Add application"}
            </Button>
          </div>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

src/components/app/modules/ATSChecker.ts:
"use client";

import { useState, useMemo, useRef } from "react";
import { motion } from "framer-motion";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge, Icon, ScoreRing } from "@/components/shared";
import { useApp } from "@/lib/store";
import { scoreATS, scoreLabel } from "@/lib/ats";
import { parseResumeFile } from "@/lib/parser";
import { toast } from "sonner";
import type { ResumeData, JobDescription } from "@/lib/types";

export function ATSChecker() {
  const resumes = useApp((s) => s.resumes);
  const jds = useApp((s) => s.jobDescriptions);
  const addATS = useApp((s) => s.addATSReport);
  const incUsage = useApp((s) => s.incUsage);
  const log = useApp((s) => s.log);
  const setView = useApp((s) => s.setView);

  const [resumeId, setResumeId] = useState<string>(resumes[0]?.id ?? "");
  const [jdId, setJdId] = useState<string>("none");
  const [running, setRunning] = useState(false);
  const [report, setReport] = useState<ReturnType<typeof scoreATS> | null>(null);
  const fileRef = useRef<HTMLInputElement>(null);

  const resume = useMemo(() => resumes.find((r) => r.id === resumeId), [resumes, resumeId]);
  const jd = useMemo(() => jds.find((j) => j.id === jdId), [jds, jdId]);

  const run = async () => {
    if (!resume) {
      toast.error("Select or upload a resume first.");
      return;
    }
    setRunning(true);
    await new Promise((r) => setTimeout(r, 900)); // simulate AI provider latency
    const r = scoreATS(resume, jd);

    // === ATS PIPELINE INTEGRITY CHECK ===
    // Detect false-success: parser returned all-zero scores which indicates
    // a silent parse failure. Do not surface this as "success" to the user.
    const totalScore = r.scores.ats + r.scores.formatting + r.scores.keywords +
      r.scores.content + r.scores.grammar + r.scores.completeness;
    if (totalScore === 0) {
      setRunning(false);
      toast.error("ATS check failed: resume could not be parsed (0% score). Please re-upload your resume file.");
      return;
    }

    setReport(r);
    addATS(r);
    incUsage("atsChecks");
    log({ actor: "you", action: "ATS check completed", category: "resume", details: `Score ${r.scores.ats}/100 for "${resume.name}"`, severity: "info" });
    setRunning(false);
    toast.success(`ATS score: ${r.scores.ats}/100`);
  };

  const onUpload = async (files: FileList | null) => {
    if (!files?.[0]) return;
    const file = files[0];
    try {
      const parsed = await parseResumeFile(file);
      useApp.getState().addResume(parsed);
      setResumeId(parsed.id);
      toast.success(`Parsed ${file.name} successfully.`);
    } catch (e: any) {
      toast.error(e?.message || "Parse failed.");
    } finally {
      if (fileRef.current) fileRef.current.value = "";
    }
  };

  const scores = report?.scores;
  const scoreRows: { label: string; value: number; key: keyof NonNullable<typeof scores> }[] = scores ? [
    { label: "ATS Overall", value: scores.ats, key: "ats" },
    { label: "Formatting", value: scores.formatting, key: "formatting" },
    { label: "Keywords", value: scores.keywords, key: "keywords" },
    { label: "Content", value: scores.content, key: "content" },
    { label: "Grammar", value: scores.grammar, key: "grammar" },
    { label: "Completeness", value: scores.completeness, key: "completeness" },
  ] : [];

  return (
    <div className="space-y-6">
      <div>
        <h1 className="font-display text-2xl font-bold flex items-center gap-2">
          <Icon name="ScanText" className="w-6 h-6 text-brand" /> ATS Resume Checker
        </h1>
        <p className="text-sm text-muted-foreground mt-1">Six-axis scoring with actionable recommendations. Outperforms Enhancv — and it's free.</p>
      </div>

      <div className="grid lg:grid-cols-3 gap-6">
        <Card className="lg:col-span-1">
          <CardHeader>
            <CardTitle className="text-lg">1. Pick a resume</CardTitle>
            <CardDescription>Choose from your library or upload a new one.</CardDescription>
          </CardHeader>
          <CardContent className="space-y-3">
            <select
              value={resumeId}
              onChange={(e) => setResumeId(e.target.value)}
              className="w-full h-10 px-3 rounded-md border border-input bg-background text-sm"
            >
              {resumes.length === 0 && <option value="">No resumes yet</option>}
              {resumes.map((r) => (
                <option key={r.id} value={r.id}>{r.name} {r.headline ? `— ${r.headline}` : ""}</option>
              ))}
            </select>
            <Button variant="outline" className="w-full gap-2" onClick={() => fileRef.current?.click()}>
              <Icon name="Upload" className="w-4 h-4" /> Upload new (PDF/DOCX/TXT)
            </Button>
            <input ref={fileRef} type="file" accept=".pdf,.docx,.txt" className="hidden" onChange={(e) => onUpload(e.target.files)} />
          </CardContent>
        </Card>

        <Card className="lg:col-span-1">
          <CardHeader>
            <CardTitle className="text-lg">2. Compare to a job? (optional)</CardTitle>
            <CardDescription>Score against a saved job description.</CardDescription>
          </CardHeader>
          <CardContent className="space-y-3">
            <select
              value={jdId}
              onChange={(e) => setJdId(e.target.value)}
              className="w-full h-10 px-3 rounded-md border border-input bg-background text-sm"
            >
              <option value="none">No JD — generic ATS check</option>
              {jds.map((j) => (
                <option key={j.id} value={j.id}>{j.title}{j.company ? ` — ${j.company}` : ""}</option>
              ))}
            </select>
            {jd && (
              <div className="rounded-lg bg-secondary p-3 text-xs">
                <div className="font-semibold">{jd.title}</div>
                <div className="text-muted-foreground mt-0.5">{jd.keywords.length} keywords · {jd.requiredSkills.length} required skills</div>
              </div>
            )}
            <Button variant="outline" className="w-full gap-2" onClick={() => setView("jd-scraper")}>
              <Icon name="Search" className="w-4 h-4" /> Scrape a new JD
            </Button>
          </CardContent>
        </Card>

        <Card className="lg:col-span-1 flex flex-col">
          <CardHeader>
            <CardTitle className="text-lg">3. Run the check</CardTitle>
            <CardDescription>Get your scores in ~1 second.</CardDescription>
          </CardHeader>
          <CardContent className="flex-1 flex flex-col items-center justify-center gap-3">
            <Button onClick={run} disabled={running || !resume} className="w-full bg-brand hover:bg-brand-dark text-white gap-2">
              {running ? <Icon name="Loader2" className="w-4 h-4 animate-spin" /> : <Icon name="ScanText" className="w-4 h-4" />}
              {running ? "Analyzing…" : "Run ATS check"}
            </Button>
            {!resume && <p className="text-xs text-muted-foreground text-center">Select or upload a resume to enable.</p>}
          </CardContent>
        </Card>
      </div>

      {report && (
        <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} className="grid lg:grid-cols-3 gap-6">
          {/* Score card */}
          <Card>
            <CardHeader>
              <CardTitle className="text-lg flex items-center gap-2"><Icon name="Gauge" className="w-4 h-4 text-brand" /> Overall score</CardTitle>
            </CardHeader>
            <CardContent className="flex flex-col items-center gap-4">
              <ScoreRing value={report.scores.ats} size={160} stroke={12} label="ATS Score" />
              <Badge variant={report.scores.ats >= 85 ? "success" : report.scores.ats >= 70 ? "brand" : report.scores.ats >= 50 ? "warning" : "danger"}>
                {scoreLabel(report.scores.ats).label}
              </Badge>
              {report.jdMatchPercent != null && (
                <div className="text-xs text-muted-foreground text-center">
                  JD match: <span className="font-semibold text-foreground">{report.jdMatchPercent}%</span>
                </div>
              )}
            </CardContent>
          </Card>

          {/* Score breakdown */}
          <Card className="lg:col-span-2">
            <CardHeader>
              <CardTitle className="text-lg flex items-center gap-2"><Icon name="BarChart3" className="w-4 h-4 text-brand" /> Score breakdown</CardTitle>
              <CardDescription>Six axes, weighted for real ATS systems.</CardDescription>
            </CardHeader>
            <CardContent className="space-y-3">
              {scoreRows.slice(1).map((row) => {
                const color = row.value >= 85 ? "#10B981" : row.value >= 70 ? "#1154A3" : row.value >= 50 ? "#F59E0B" : "#DC2626";
                return (
                  <div key={row.key}>
                    <div className="flex justify-between text-sm mb-1">
                      <span className="font-medium">{row.label}</span>
                      <span className="font-semibold" style={{ color }}>{row.value}/100</span>
                    </div>
                    <div className="h-2 bg-secondary rounded-full overflow-hidden">
                      <motion.div
                        className="h-full rounded-full"
                        style={{ background: color }}
                        initial={{ width: 0 }}
                        animate={{ width: `${row.value}%` }}
                        transition={{ duration: 0.6, delay: 0.1 }}
                      />
                    </div>
                  </div>
                );
              })}

              {report.missingKeywords.length > 0 && (
                <div className="mt-4 pt-4 border-t border-border">
                  <div className="text-sm font-semibold mb-2 flex items-center gap-1.5">
                    <Icon name="KeyRound" className="w-4 h-4 text-gold" /> Missing keywords
                  </div>
                  <div className="flex flex-wrap gap-1.5">
                    {report.missingKeywords.map((k) => (
                      <Badge key={k} variant="warning">{k}</Badge>
                    ))}
                  </div>
                </div>
              )}

              {report.matchedKeywords.length > 0 && (
                <div className="mt-3">
                  <div className="text-sm font-semibold mb-2 flex items-center gap-1.5">
                    <Icon name="CheckCircle2" className="w-4 h-4 text-emerald-600" /> Matched keywords
                  </div>
                  <div className="flex flex-wrap gap-1.5">
                    {report.matchedKeywords.map((k) => (
                      <Badge key={k} variant="success">{k}</Badge>
                    ))}
                  </div>
                </div>
              )}

              {report.detectedCliches && report.detectedCliches.length > 0 && (
                <div className="mt-3">
                  <div className="text-sm font-semibold mb-2 flex items-center gap-1.5">
                    <Icon name="ShieldAlert" className="w-4 h-4 text-red-500" /> Detected Clichés
                  </div>
                  <div className="flex flex-wrap gap-1.5">
                    {report.detectedCliches.map((k) => (
                      <Badge key={k} variant="danger">{k}</Badge>
                    ))}
                  </div>
                </div>
              )}
            </CardContent>
          </Card>

          {/* Recommendations */}
          <Card className="lg:col-span-3">
            <CardHeader>
              <CardTitle className="text-lg flex items-center gap-2"><Icon name="Lightbulb" className="w-4 h-4 text-gold" /> Recommendations ({report.recommendations.length})</CardTitle>
              <CardDescription>Concrete, actionable fixes — ranked by severity.</CardDescription>
            </CardHeader>
            <CardContent>
              <div className="grid sm:grid-cols-2 gap-3">
                {report.recommendations.map((rec) => {
                  const cfg: Record<string, { color: string; bg: string; icon: string }> = {
                    critical: { color: "#DC2626", bg: "#FEE2E2", icon: "AlertOctagon" },
                    warning: { color: "#F59E0B", bg: "#FEF3C7", icon: "AlertTriangle" },
                    info: { color: "#1154A3", bg: "#DBEAFE", icon: "Info" },
                    success: { color: "#10B981", bg: "#D1FAE5", icon: "CheckCircle2" },
                  };
                  const c = cfg[rec.severity] ?? cfg.info;
                  return (
                    <div key={rec.id} className="rounded-xl border border-border p-4 flex flex-col justify-between gap-3 bg-card hover:shadow-sm transition">
                      <div className="flex gap-3">
                        <div className="w-8 h-8 rounded-lg flex items-center justify-center shrink-0" style={{ background: c.bg, color: c.color }}>
                          <Icon name={c.icon} className="w-4 h-4" />
                        </div>
                        <div className="min-w-0 flex-1">
                          <div className="text-sm font-semibold">{rec.title}</div>
                          <div className="text-xs text-muted-foreground mt-0.5 text-pretty">{rec.description}</div>
                          {rec.fix && <div className="text-xs text-foreground/80 mt-2"><span className="font-semibold">Fix:</span> {rec.fix}</div>}
                        </div>
                      </div>
                      {resume && rec.category && (
                        <div className="pt-2 border-t border-border/50 flex justify-end">
                          <Button
                            size="sm"
                            variant="outline"
                            className="h-7 text-xs gap-1.5 hover:bg-brand/10 hover:text-brand border-brand/30"
                            onClick={() => {
                              const updateResume = useApp.getState().updateResume;
                              if (!resume) return;
                              let modified = { ...resume };

                              if (rec.category === "Content" || rec.title.toLowerCase().includes("bullet")) {
                                const WEAK_REPLACEMENTS: Record<string, string> = {
                                  "responsible for": "Spearheaded",
                                  "worked on": "Executed",
                                  "helped": "Facilitated",
                                  "duties included": "Delivered",
                                  "tasked with": "Orchestrated",
                                };
                                modified.experience = modified.experience.map(e => ({
                                  ...e,
                                  bullets: e.bullets.map(b => {
                                    const l = b.toLowerCase();
                                    for (const [k, v] of Object.entries(WEAK_REPLACEMENTS)) {
                                      if (l.startsWith(k)) return v + b.slice(k.length);
                                    }
                                    return b;
                                  })
                                }));
                                updateResume(resume.id, modified);
                                toast.success("Power verbs applied to bullets!");
                                run();
                              } else if (rec.category === "Summary" || rec.title.toLowerCase().includes("summary")) {
                                if (modified.summary && modified.summary.length > 500) {
                                  const sentences = modified.summary.split(/(?<=[.!?])\s+/);
                                  modified.summary = sentences.slice(0, 3).join(" ");
                                  updateResume(resume.id, modified);
                                  toast.success("Summary trimmed to concise 3 sentences!");
                                  run();
                                } else {
                                  toast.info("Summary is already optimal length.");
                                }
                              } else if (rec.category === "Formatting" && rec.title.toLowerCase().includes("phone")) {
                                if (modified.contact?.phone) {
                                  modified.contact.phone = modified.contact.phone.replace(/[\(\)\s-]/g, "").replace(/^(\+?\d{1,3})?(\d{3})(\d{3})(\d{4})$/, "+$1 $2-$3-$4").trim();
                                  updateResume(resume.id, modified);
                                  toast.success("Phone format standardized!");
                                  run();
                                }
                              } else {
                                toast.info("Suggested fix can be tuned in the Resume Builder.");
                                setView("builder");
                              }
                            }}
                          >
                            <Icon name="Wand2" className="w-3.5 h-3.5 text-brand" /> Auto-Apply Fix
                          </Button>
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            </CardContent>
          </Card>

          {/* CTA to optimizer */}
          <Card className="lg:col-span-3 gradient-brand text-white">
            <CardContent className="p-6 flex flex-col sm:flex-row items-center justify-between gap-4">
              <div>
                <h3 className="font-display text-lg font-bold">Want to fix these automatically?</h3>
                <p className="text-sm text-white/80 mt-1">The Resume Optimizer will rewrite bullets, add missing keywords, and rebalance the layout — all on one A4 page.</p>
              </div>
              <Button onClick={() => setView("optimizer")} className="bg-white text-brand hover:bg-white/90 gap-2 shrink-0">
                <Icon name="Wand2" className="w-4 h-4" /> Open Optimizer
              </Button>
            </CardContent>
          </Card>
        </motion.div>
      )}
    </div>
  );
}

src/components/app/modules/BatchOptimize:
"use client";

import { recordAI, setFlightScope } from "@/lib/ai/flight-recorder";
setFlightScope({ scope: "resume-optimizer", feature: "Batch Optimizer", module: "src.components.app.modules.BatchOptimizer" });

// Upload up to 10 resume files, pick a target JD, and process them all sequentially.
// Each file is parsed → optimized → saved to library. Finished batch exports as a ZIP.


import { useState, useRef, useCallback } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Badge, Icon } from "@/components/shared";
import { useApp, uid } from "@/lib/store";
import { callAI, extractJSON } from "@/lib/ai";
import { parseResumeFile } from "@/lib/parser";
import { toast } from "sonner";
import type { ResumeData } from "@/lib/types";

// ============================================================================
// Types
// ============================================================================

type ItemStatus =
  | "pending"
  | "parsing"
  | "optimizing"
  | "done"
  | "failed";

interface BatchItem {
  id: string;
  file: File;
  status: ItemStatus;
  statusLabel: string;
  error?: string;
  optimizedResume?: ResumeData;
}

// ============================================================================
// Helpers
// ============================================================================

/** Trigger a browser download for an arbitrary blob. */
function downloadBlob(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

/**
 * Build a simple ZIP archive entirely in-browser with no external dependencies.
 * Implements the ZIP local-file-header + central-directory format (ZIP32).
 * Supports only STORE method (no compression) which is sufficient for PDFs / text blobs.
 */
async function buildZip(entries: { name: string; data: Uint8Array }[]): Promise<Blob> {
  const enc = new TextEncoder();

  function u16(n: number) {
    const buf = new Uint8Array(2);
    buf[0] = n & 0xff;
    buf[1] = (n >> 8) & 0xff;
    return buf;
  }
  function u32(n: number) {
    const buf = new Uint8Array(4);
    buf[0] = n & 0xff;
    buf[1] = (n >> 8) & 0xff;
    buf[2] = (n >> 16) & 0xff;
    buf[3] = (n >> 24) & 0xff;
    return buf;
  }

  /** CRC-32 via lookup table */
  function crc32(data: Uint8Array): number {
    const table = (() => {
      const t = new Uint32Array(256);
      for (let i = 0; i < 256; i++) {
        let c = i;
        for (let j = 0; j < 8; j++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
        t[i] = c;
      }
      return t;
    })();
    let crc = 0xffffffff;
    for (const byte of data) crc = table[(crc ^ byte) & 0xff] ^ (crc >>> 8);
    return (crc ^ 0xffffffff) >>> 0;
  }

  function concat(...arrays: Uint8Array[]): Uint8Array {
    const total = arrays.reduce((s, a) => s + a.length, 0);
    const out = new Uint8Array(total);
    let offset = 0;
    for (const a of arrays) { out.set(a, offset); offset += a.length; }
    return out;
  }

  const localHeaders: Uint8Array[] = [];
  const centralHeaders: Uint8Array[] = [];
  let offset = 0;

  const modDate = new Date();
  const dosTime = (modDate.getHours() << 11) | (modDate.getMinutes() << 5) | Math.floor(modDate.getSeconds() / 2);
  const dosDate = ((modDate.getFullYear() - 1980) << 9) | ((modDate.getMonth() + 1) << 5) | modDate.getDate();

  for (const entry of entries) {
    const nameBytes = enc.encode(entry.name);
    const crc = crc32(entry.data);
    const size = entry.data.length;

    // Local file header (signature 0x04034b50)
    const local = concat(
      new Uint8Array([0x50, 0x4b, 0x03, 0x04]), // signature
      u16(20),           // version needed
      u16(0),            // general purpose bit flag
      u16(0),            // compression method: STORE
      u16(dosTime),
      u16(dosDate),
      u32(crc),
      u32(size),         // compressed size
      u32(size),         // uncompressed size
      u16(nameBytes.length),
      u16(0),            // extra field length
      nameBytes,
      entry.data,
    );
    localHeaders.push(local);

    // Central directory header (signature 0x02014b50)
    const central = concat(
      new Uint8Array([0x50, 0x4b, 0x01, 0x02]), // signature
      u16(20),           // version made by
      u16(20),           // version needed
      u16(0),
      u16(0),            // STORE
      u16(dosTime),
      u16(dosDate),
      u32(crc),
      u32(size),
      u32(size),
      u16(nameBytes.length),
      u16(0),            // extra length
      u16(0),            // comment length
      u16(0),            // disk number start
      u16(0),            // internal attrs
      u32(0),            // external attrs
      u32(offset),       // relative offset of local header
      nameBytes,
    );
    centralHeaders.push(central);
    offset += local.length;
  }

  const centralDir = concat(...centralHeaders);
  const centralSize = centralDir.length;
  const centralOffset = offset;

  // End of central directory (signature 0x06054b50)
  const eocd = concat(
    new Uint8Array([0x50, 0x4b, 0x05, 0x06]),
    u16(0),              // disk number
    u16(0),              // disk with central dir
    u16(entries.length),
    u16(entries.length),
    u32(centralSize),
    u32(centralOffset),
    u16(0),              // comment length
  );

  const full = concat(...localHeaders, centralDir, eocd);
  return new Blob([full as any], { type: "application/zip" });
}

/** Convert a ResumeData object to a human-readable plain-text resume */
function resumeToText(r: ResumeData): string {
  const lines: string[] = [];
  lines.push(r.name || "Resume");
  if (r.headline) lines.push(r.headline);
  const contact = r.contact || {};
  if (contact.email || contact.phone || contact.location) {
    lines.push([contact.email, contact.phone, contact.location].filter(Boolean).join(" · "));
  }
  if (contact.linkedin || contact.website) {
    lines.push([contact.linkedin, contact.website].filter(Boolean).join(" · "));
  }
  lines.push("");

  if (r.summary) {
    lines.push("PROFESSIONAL SUMMARY");
    lines.push("─".repeat(40));
    lines.push(r.summary);
    lines.push("");
  }

  if (r.experience?.length) {
    lines.push("EXPERIENCE");
    lines.push("─".repeat(40));
    for (const exp of r.experience) {
      lines.push(`${exp.title} — ${exp.company}${exp.location ? `, ${exp.location}` : ""}`);
      lines.push(`${exp.startDate} – ${exp.endDate || "Present"}`);
      for (const b of exp.bullets ?? []) lines.push(`• ${b}`);
      lines.push("");
    }
  }

  if (r.education?.length) {
    lines.push("EDUCATION");
    lines.push("─".repeat(40));
    for (const edu of r.education) {
      lines.push(`${edu.degree}${edu.field ? ` in ${edu.field}` : ""} — ${edu.institution || ""}`);
      if (edu.startDate || edu.endDate) lines.push(`${edu.startDate ?? ""} – ${edu.endDate ?? "Present"}`);
      lines.push("");
    }
  }

  if (r.skills?.length) {
    lines.push("SKILLS");
    lines.push("─".repeat(40));
    lines.push(r.skills.map((s) => s.name).join(", "));
    lines.push("");
  }

  if (r.certifications?.length) {
    lines.push("CERTIFICATIONS");
    lines.push("─".repeat(40));
    for (const c of r.certifications) {
      lines.push(`${c.name}${c.issuer ? ` — ${c.issuer}` : ""}${c.date ? ` (${c.date})` : ""}`);
    }
    lines.push("");
  }

  return lines.join("\n");
}

// ============================================================================
// Status badge helper
// ============================================================================

const STATUS_CONFIG: Record<ItemStatus, { label: string; variant: "default" | "outline" | "warning" | "success" | "danger"; icon: string }> = {
  pending: { label: "Pending", variant: "outline", icon: "Clock" },
  parsing: { label: "Parsing…", variant: "warning", icon: "Loader2" },
  optimizing: { label: "Optimizing…", variant: "warning", icon: "Loader2" },
  done: { label: "Done", variant: "success", icon: "CheckCircle2" },
  failed: { label: "Failed", variant: "danger", icon: "XCircle" },
};

// ============================================================================
// Main Component
// ============================================================================

export function BatchOptimizer() {
  const addResume = useApp((s) => s.addResume);
  const incUsage = useApp((s) => s.incUsage);
  const log = useApp((s) => s.log);

  const [items, setItems] = useState<BatchItem[]>([]);
  const [jdText, setJdText] = useState("");
  const [running, setRunning] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // ---------- File management ----------

  const addFiles = useCallback((files: FileList | File[]) => {
    const accepted = Array.from(files).filter((f) => {
      const ext = f.name.split(".").pop()?.toLowerCase();
      return ext === "pdf" || ext === "docx";
    });
    if (accepted.length === 0) {
      toast.error("Only PDF and DOCX files are supported.");
      return;
    }
    setItems((prev) => {
      const remaining = 10 - prev.length;
      if (remaining <= 0) { toast.error("Maximum 10 files per batch."); return prev; }
      const toAdd = accepted.slice(0, remaining).map((f) => ({
        id: uid("bi"),
        file: f,
        status: "pending" as ItemStatus,
        statusLabel: "Pending",
      }));
      if (accepted.length > remaining) toast.warning(`Only ${remaining} slot(s) remaining — added first ${remaining} file(s).`);
      return [...prev, ...toAdd];
    });
  }, []);

  const removeItem = (id: string) => {
    if (running) return;
    setItems((prev) => prev.filter((i) => i.id !== id));
  };

  // ---------- Drag & drop ----------

  const onDragOver = (e: React.DragEvent) => { e.preventDefault(); setIsDragging(true); };
  const onDragLeave = () => setIsDragging(false);
  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    addFiles(e.dataTransfer.files);
  };

  // ---------- Update a single item (functional update) ----------

  const patchItem = (id: string, patch: Partial<BatchItem>) =>
    setItems((prev) => prev.map((i) => (i.id === id ? { ...i, ...patch } : i)));

  // ---------- Process one resume ----------

  const processOne = async (item: BatchItem, jd: string): Promise<ResumeData | null> => {
    try {
      // Step 1 – Parse
      patchItem(item.id, { status: "parsing", statusLabel: "Parsing file…" });
      const parsed = await parseResumeFile(item.file);

      // Step 2 – Optimize via AI
      patchItem(item.id, { status: "optimizing", statusLabel: "Optimizing with AI…" });

      const optResult = await recordAI({
        systemPrompt:
          "You are a Senior ATS Optimization Expert. Optimize the resume for the job description below. " +
          "Return ONLY valid JSON with fields: name, headline, summary, skills (array of {name, category}), " +
          "experience (array of {title, company, location, startDate, endDate, bullets[]}). " +
          "NEVER fabricate experience. Improve bullets and keywords to match the JD.",
        userPrompt:
          `SOURCE RESUME:\n${JSON.stringify({
            name: parsed.name,
            headline: parsed.headline,
            summary: parsed.summary,
            experience: parsed.experience?.map((e) => ({ title: e.title, company: e.company, bullets: e.bullets })),
            skills: parsed.skills?.map((s) => s.name),
          })}\n\nTARGET JOB DESCRIPTION:\n${jd.slice(0, 2500)}\n\nReturn JSON only.`,
        maxTokens: 3000,
        temperature: 0.35,
        taskCategory: "document",
      });

      let optData: any;
      try { optData = extractJSON<any>(optResult.text); }
      catch { throw new Error("AI returned invalid JSON — could not parse optimization result."); }

      const optimized: ResumeData = {
        ...parsed,
        id: uid("r"),
        headline: optData.headline || parsed.headline,
        summary: optData.summary || parsed.summary,
        skills: (optData.skills ?? []).map((s: any) =>
          typeof s === "string" ? { id: uid("s"), name: s, category: "Skills" } : { id: uid("s"), ...s }
        ),
        experience: (optData.experience ?? []).map((e: any) => ({
          id: uid("e"),
          title: e.title || "",
          company: e.company || "",
          location: e.location || "",
          startDate: e.startDate || "",
          endDate: e.endDate || "Present",
          bullets: e.bullets ?? [],
        })),
        template: parsed.template || "ats-professional",
        source: "ai-optimized",
        fileName: `Optimized_${item.file.name}`,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      };

      // Save to library
      addResume(optimized);
      incUsage("resumesGenerated");
      log({
        actor: "you",
        action: `Batch Optimizer: processed ${item.file.name}`,
        category: "ai",
        details: `Provider: ${optResult.provider}`,
        severity: "info",
      });

      patchItem(item.id, { status: "done", statusLabel: "Done", optimizedResume: optimized });
      return optimized;
    } catch (err: any) {
      patchItem(item.id, {
        status: "failed",
        statusLabel: "Failed",
        error: err?.message || "Unknown error",
      });
      return null;
    }
  };

  // ---------- Run all sequentially ----------

  const runAll = async () => {
    if (items.length === 0) { toast.error("Add at least one resume file."); return; }
    if (!jdText.trim() || jdText.trim().length < 50) {
      toast.error("Paste a full job description (min 50 characters)."); return;
    }
    setRunning(true);

    const toProcess = items.filter((i) => i.status !== "done");
    for (const item of toProcess) {
      await processOne(item, jdText);
    }

    const doneCount = items.filter((i) => i.status === "done").length +
      toProcess.filter((i) => i.status === "done").length;

    toast.success(`Batch complete — ${doneCount} resume(s) optimized and saved to library.`);
    setRunning(false);
  };

  // ---------- ZIP download ----------

  const downloadZip = async () => {
    const ready = items.filter((i) => i.status === "done" && i.optimizedResume);
    if (ready.length === 0) { toast.error("No completed resumes to download."); return; }
    toast.info("Building ZIP archive…");

    const enc = new TextEncoder();
    const entries = ready.map((item) => ({
      name: `Optimized_${item.file.name.replace(/\.(pdf|docx)$/i, "")}.txt`,
      data: enc.encode(resumeToText(item.optimizedResume!)),
    }));

    const zip = await buildZip(entries);
    downloadBlob(zip, `BatchOptimized_Resumes_${new Date().toISOString().split("T")[0]}.zip`);
    incUsage("downloads");
    toast.success(`Downloaded ZIP with ${entries.length} resume(s).`);
  };

  // ---------- Stats ----------

  const doneCount = items.filter((i) => i.status === "done").length;
  const failedCount = items.filter((i) => i.status === "failed").length;
  const pendingCount = items.filter((i) => i.status === "pending").length;

  // ============================================================================
  // Render
  // ============================================================================

  return (
    <div className="space-y-6 p-6 max-w-5xl mx-auto">
      {/* Header */}
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Batch Resume Optimizer</h1>
        <p className="text-muted-foreground text-sm mt-1">
          Upload up to 10 resumes, provide a target job description, and let AI optimize them all — one by one. Completed resumes save automatically to your library.
        </p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* ── Left: File upload + queue ── */}
        <div className="space-y-4">
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-base flex items-center gap-2">
                <Icon name="FileStack" className="w-4 h-4 text-brand" />
                Resume Files
                <Badge variant="outline" className="ml-auto">{items.length} / 10</Badge>
              </CardTitle>
              <CardDescription>PDF or DOCX — up to 10 files, max 5 MB each.</CardDescription>
            </CardHeader>
            <CardContent className="space-y-3">
              {/* Drop zone */}
              <div
                className={`border-2 border-dashed rounded-lg p-6 text-center cursor-pointer transition-colors ${
                  isDragging
                    ? "border-brand bg-brand/5"
                    : "border-border hover:border-brand/50 hover:bg-muted/30"
                }`}
                onDragOver={onDragOver}
                onDragLeave={onDragLeave}
                onDrop={onDrop}
                onClick={() => !running && fileInputRef.current?.click()}
              >
                <Icon
                  name="UploadCloud"
                  className={`w-8 h-8 mx-auto mb-2 ${isDragging ? "text-brand" : "text-muted-foreground"}`}
                />
                <p className="text-sm font-medium">
                  {isDragging ? "Drop files here" : "Drag & drop resumes here"}
                </p>
                <p className="text-xs text-muted-foreground mt-1">or click to browse</p>
                <input
                  ref={fileInputRef}
                  type="file"
                  accept=".pdf,.docx"
                  multiple
                  className="hidden"
                  disabled={running}
                  onChange={(e) => { if (e.target.files) addFiles(e.target.files); e.target.value = ""; }}
                />
              </div>

              {/* File queue */}
              {items.length > 0 && (
                <div className="space-y-2 max-h-72 overflow-y-auto pr-1">
                  {items.map((item) => {
                    const cfg = STATUS_CONFIG[item.status];
                    return (
                      <div
                        key={item.id}
                        className="flex items-center gap-2 rounded-lg border border-border bg-secondary/30 px-3 py-2 text-sm"
                      >
                        <Icon
                          name={cfg.icon}
                          className={`w-3.5 h-3.5 shrink-0 ${
                            item.status === "parsing" || item.status === "optimizing"
                              ? "animate-spin text-brand"
                              : item.status === "done"
                              ? "text-green-500"
                              : item.status === "failed"
                              ? "text-destructive"
                              : "text-muted-foreground"
                          }`}
                        />
                        <span className="truncate flex-1 font-medium text-foreground/90">
                          {item.file.name}
                        </span>
                        <span className="text-xs text-muted-foreground shrink-0">
                          {item.statusLabel}
                        </span>
                        {!running && item.status !== "optimizing" && item.status !== "parsing" && (
                          <button
                            onClick={() => removeItem(item.id)}
                            className="shrink-0 text-muted-foreground hover:text-destructive transition-colors"
                            aria-label={`Remove ${item.file.name}`}
                          >
                            <Icon name="X" className="w-3.5 h-3.5" />
                          </button>
                        )}
                        {item.status === "failed" && item.error && (
                          <span className="text-xs text-destructive truncate max-w-[120px]" title={item.error}>
                            {item.error}
                          </span>
                        )}
                      </div>
                    );
                  })}
                </div>
              )}

              {items.length === 0 && (
                <p className="text-center text-sm text-muted-foreground py-2">
                  No files added yet.
                </p>
              )}
            </CardContent>
          </Card>

          {/* Stats row */}
          {items.length > 0 && (
            <div className="grid grid-cols-3 gap-3">
              <div className="rounded-lg border border-border bg-secondary/30 p-3 text-center">
                <div className="text-xl font-bold text-green-500">{doneCount}</div>
                <div className="text-xs text-muted-foreground">Completed</div>
              </div>
              <div className="rounded-lg border border-border bg-secondary/30 p-3 text-center">
                <div className="text-xl font-bold text-muted-foreground">{pendingCount}</div>
                <div className="text-xs text-muted-foreground">Pending</div>
              </div>
              <div className="rounded-lg border border-border bg-secondary/30 p-3 text-center">
                <div className="text-xl font-bold text-destructive">{failedCount}</div>
                <div className="text-xs text-muted-foreground">Failed</div>
              </div>
            </div>
          )}
        </div>

        {/* ── Right: JD input + actions ── */}
        <div className="space-y-4">
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-base flex items-center gap-2">
                <Icon name="FileText" className="w-4 h-4 text-brand" />
                Target Job Description
              </CardTitle>
              <CardDescription>Paste the full JD. All resumes will be optimized against this role.</CardDescription>
            </CardHeader>
            <CardContent>
              <Label htmlFor="batch-jd" className="sr-only">Job Description</Label>
              <Textarea
                id="batch-jd"
                placeholder="Paste the complete job description here…&#10;&#10;We're looking for a Senior Software Engineer…"
                className="min-h-[240px] font-mono text-xs resize-y"
                value={jdText}
                onChange={(e) => setJdText(e.target.value)}
                disabled={running}
              />
              <div className="flex items-center justify-between mt-2">
                <span className="text-xs text-muted-foreground">{jdText.trim().length} chars</span>
                {jdText.trim().length > 0 && (
                  <button
                    onClick={() => setJdText("")}
                    className="text-xs text-muted-foreground hover:text-foreground transition-colors"
                    disabled={running}
                  >
                    Clear
                  </button>
                )}
              </div>
            </CardContent>
          </Card>

          {/* Action buttons */}
          <div className="space-y-2">
            <Button
              id="batch-optimizer-run"
              className="w-full"
              disabled={running || items.length === 0}
              onClick={runAll}
            >
              {running ? (
                <>
                  <Icon name="Loader2" className="w-4 h-4 mr-2 animate-spin" />
                  Processing…
                </>
              ) : (
                <>
                  <Icon name="Wand2" className="w-4 h-4 mr-2" />
                  Optimize All ({items.filter((i) => i.status !== "done").length} remaining)
                </>
              )}
            </Button>

            <Button
              id="batch-optimizer-download"
              variant="outline"
              className="w-full"
              disabled={running || doneCount === 0}
              onClick={downloadZip}
            >
              <Icon name="Archive" className="w-4 h-4 mr-2" />
              Download All as ZIP ({doneCount} ready)
            </Button>

            {!running && items.length > 0 && (
              <Button
                variant="ghost"
                className="w-full text-muted-foreground"
                onClick={() => {
                  setItems([]);
                  setJdText("");
                }}
              >
                <Icon name="Trash2" className="w-4 h-4 mr-2" />
                Clear All
              </Button>
            )}
          </div>

          {/* Tips */}
          <Card className="bg-muted/30 border-dashed">
            <CardContent className="pt-4 space-y-2 text-xs text-muted-foreground">
              <p className="flex items-start gap-2">
                <Icon name="Info" className="w-3.5 h-3.5 mt-0.5 shrink-0 text-brand" />
                Resumes are processed one at a time to avoid API rate limits.
              </p>
              <p className="flex items-start gap-2">
                <Icon name="CheckCircle2" className="w-3.5 h-3.5 mt-0.5 shrink-0 text-green-500" />
                Only successfully optimized resumes are saved to your library.
              </p>
              <p className="flex items-start gap-2">
                <Icon name="Archive" className="w-3.5 h-3.5 mt-0.5 shrink-0 text-brand" />
                The ZIP download bundles all completed resumes as formatted text files.
              </p>
              <p className="flex items-start gap-2">
                <Icon name="RefreshCw" className="w-3.5 h-3.5 mt-0.5 shrink-0 text-muted-foreground" />
                Failed items can be retried — just click Optimize All again.
              </p>
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}

src/components/app/modules/BlueprintInte:
"use client";

import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Badge, Icon } from "@/components/shared";

/**
 * BlueprintIntegrityCard — displays whether the original resume template/blueprint
 * was preserved during optimization.
 *
 * Shows:
 *   - Whether template/blueprint was preserved
 *   - Fingerprint validity
 *   - Assembler stats (matchedBy* breakdown)
 */

export interface AssemblerStats {
  matchedById: number;
  matchedByFingerprint: number;
  matchedByTitleCompany: number;
  matchedByIndex: number;
  unmatched: number;
}

export interface BlueprintIntegrityCardProps {
  /** Whether the original template structure was preserved */
  templatePreserved: boolean;
  /** Whether experience fingerprints are valid (no fabrication) */
  fingerprintValid: boolean;
  /** Assembler matching statistics */
  assemblerStats: AssemblerStats;
}

export function BlueprintIntegrityCard({ templatePreserved, fingerprintValid, assemblerStats }: BlueprintIntegrityCardProps) {
  const totalMatched =
    assemblerStats.matchedById +
    assemblerStats.matchedByFingerprint +
    assemblerStats.matchedByTitleCompany +
    assemblerStats.matchedByIndex;

  const totalEntries = totalMatched + assemblerStats.unmatched;

  return (
    <Card>
      <CardHeader className="pb-3">
        <CardTitle className="text-sm flex items-center gap-2">
          <Icon name="FileStack" className="w-4 h-4 text-brand" />
          Blueprint Integrity
          <Badge variant={templatePreserved && fingerprintValid ? "success" : "warning"} className="ml-auto text-[10px]">
            {templatePreserved && fingerprintValid ? "INTACT" : "ISSUES DETECTED"}
          </Badge>
        </CardTitle>
        <CardDescription className="text-xs">
          Whether the original resume structure and experience were preserved
        </CardDescription>
      </CardHeader>
      <CardContent className="pt-0 space-y-4">
        {/* Template & Fingerprint status */}
        <div className="grid grid-cols-2 gap-2">
          <div className="rounded-lg bg-secondary/40 p-2.5">
            <div className="flex items-center gap-1.5">
              <Icon
                name={templatePreserved ? "CheckCircle2" : "AlertTriangle"}
                className={`w-3.5 h-3.5 shrink-0 ${templatePreserved ? "text-emerald-600" : "text-amber-600"}`}
              />
              <span className="text-xs font-medium">Template</span>
            </div>
            <div className="text-[10px] text-muted-foreground mt-0.5">
              {templatePreserved ? "Structure preserved" : "Structure modified"}
            </div>
          </div>
          <div className="rounded-lg bg-secondary/40 p-2.5">
            <div className="flex items-center gap-1.5">
              <Icon
                name={fingerprintValid ? "Fingerprint" : "AlertCircle"}
                className={`w-3.5 h-3.5 shrink-0 ${fingerprintValid ? "text-emerald-600" : "text-red-600"}`}
              />
              <span className="text-xs font-medium">Fingerprint</span>
            </div>
            <div className="text-[10px] text-muted-foreground mt-0.5">
              {fingerprintValid ? "Valid — no fabrication" : "Invalid — possible fabrication"}
            </div>
          </div>
        </div>

        {/* Assembler stats */}
        <div>
          <div className="text-xs font-semibold mb-2 flex items-center justify-between">
            <span>Assembler Matches</span>
            <span className="text-muted-foreground text-[10px]">{totalMatched}/{totalEntries} entries matched</span>
          </div>
          <div className="space-y-1.5">
            <AssemblerStatRow
              icon="Hash"
              label="Matched by ID"
              value={assemblerStats.matchedById}
              total={totalEntries}
              color="text-emerald-600"
            />
            <AssemblerStatRow
              icon="Fingerprint"
              label="Matched by Fingerprint"
              value={assemblerStats.matchedByFingerprint}
              total={totalEntries}
              color="text-blue-600"
            />
            <AssemblerStatRow
              icon="Building2"
              label="Matched by Title + Company"
              value={assemblerStats.matchedByTitleCompany}
              total={totalEntries}
              color="text-brand"
            />
            <AssemblerStatRow
              icon="ListOrdered"
              label="Matched by Index"
              value={assemblerStats.matchedByIndex}
              total={totalEntries}
              color="text-purple-600"
            />
            <AssemblerStatRow
              icon="AlertCircle"
              label="Unmatched (new entries)"
              value={assemblerStats.unmatched}
              total={totalEntries}
              color="text-amber-600"
            />
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

function AssemblerStatRow({
  icon,
  label,
  value,
  total,
  color,
}: {
  icon: string;
  label: string;
  value: number;
  total: number;
  color: string;
}) {
  const pct = total > 0 ? Math.round((value / total) * 100) : 0;
  return (
    <div className="flex items-center gap-2 text-xs">
      <Icon name={icon} className={`w-3.5 h-3.5 shrink-0 ${color}`} />
      <span className="flex-1">{label}</span>
      <span className="font-semibold">{value}</span>
      {total > 0 && (
        <div className="w-16 h-1.5 rounded-full bg-secondary/60 overflow-hidden">
          <div
            className={`h-full rounded-full ${color.replace("text-", "bg-")}`}
            style={{ width: `${pct}%` }}
          />
        </div>
      )}
    </div>
  );
}

