"use client";

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge, Icon, Logo } from "@/components/shared";
import { useApp } from "@/lib/store";
import { api as cloudApi } from "@/lib/cloud-api";
import { UnsavedBanner } from "./unsaved-changes";
import { toast } from "sonner";

export function Branding() {
  const branding = useApp((s) => s.branding);
  const updateBranding = useApp((s) => s.updateBranding);
  const log = useApp((s) => s.log);

  // Unsaved-changes tracking: any field edit marks the panel dirty until the
  // explicit save confirms D1 has the full state (same contract as the other
  // Super Admin panels). Cleared ONLY on a successful save.
  const [dirty, setDirty] = useState(false);
  const patch = (p: Parameters<typeof updateBranding>[0]) => {
    updateBranding(p);
    setDirty(true);
  };

  // Real save: explicitly pushes the full branding state to D1 (PUT
  // /api/settings/branding). Fields already persist per-keystroke via the
  // store; this button guarantees the current state is on the server and
  // gives the user a confirmed, refresh-proof save.
  const [saving, setSaving] = useState(false);
  const save = async () => {
    setSaving(true);
    try {
      await cloudApi.updateBranding(branding);
      setDirty(false);
      log({ actor: "you", action: "Branding updated", category: "admin", details: `${branding.appName} · ${branding.primaryColor}`, severity: "info" });
      toast.success("Branding saved to cloud — persists across refreshes.");
    } catch {
      toast.error("Branding save failed — check your connection and try again.");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="space-y-6">
      <div>
        <h1 className="font-display text-2xl font-bold flex items-center gap-2"><Icon name="Palette" className="w-6 h-6 text-brand" /> Branding</h1>
        <p className="text-sm text-muted-foreground mt-1">Customize the app's name, colors, logo, and email/PDF branding.</p>
      </div>

      {dirty && <UnsavedBanner saveLabel="Save branding" />}

      <div className="grid lg:grid-cols-3 gap-6">
        <Card className="lg:col-span-2">
          <CardHeader><CardTitle className="text-lg">Brand identity</CardTitle><CardDescription>Used across the app, PDFs, and emails.</CardDescription></CardHeader>
          <CardContent className="space-y-4">
            <div className="grid sm:grid-cols-2 gap-3">
              <Field label="App name"><Input value={branding.appName} onChange={(e) => patch({ appName: e.target.value })} /></Field>
              <Field label="Tagline"><Input value={branding.tagline} onChange={(e) => patch({ tagline: e.target.value })} /></Field>
            </div>
            <div className="grid sm:grid-cols-2 gap-3">
              <Field label="Primary color">
                <div className="flex gap-2">
                  <Input type="color" value={branding.primaryColor} onChange={(e) => patch({ primaryColor: e.target.value })} className="w-12 h-9 p-1" />
                  <Input value={branding.primaryColor} onChange={(e) => patch({ primaryColor: e.target.value })} />
                </div>
              </Field>
              <Field label="Accent color">
                <div className="flex gap-2">
                  <Input type="color" value={branding.accentColor} onChange={(e) => patch({ accentColor: e.target.value })} className="w-12 h-9 p-1" />
                  <Input value={branding.accentColor} onChange={(e) => patch({ accentColor: e.target.value })} />
                </div>
              </Field>
            </div>
            <Field label="Logo URL"><Input value={branding.logoUrl} onChange={(e) => patch({ logoUrl: e.target.value })} /></Field>
          </CardContent>
        </Card>

        <Card>
          <CardHeader><CardTitle className="text-lg">Live preview</CardTitle></CardHeader>
          <CardContent>
            <div className="rounded-xl p-6 text-center" style={{ background: branding.primaryColor, color: "white" }}>
              <div className="inline-flex items-center justify-center w-14 h-14 rounded-2xl bg-white/15 mb-3">
                <Logo size={36} withText={false} />
              </div>
              <div className="font-display text-xl font-bold">{branding.appName}</div>
              <div className="text-sm opacity-80 mt-1">{branding.tagline}</div>
              <div className="mt-4 inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-semibold" style={{ background: branding.accentColor, color: "#0B1F3A" }}>
                <Icon name="Sparkles" className="w-3 h-3" /> Get started
              </div>
            </div>
            <div className="mt-3 grid grid-cols-2 gap-2 text-xs">
              <Button variant="outline" size="sm" onClick={() => toast.success("Icon regeneration queued.")} className="gap-1.5"><Icon name="RefreshCcw" className="w-3.5 h-3.5" /> Regenerate icons</Button>
              <Button variant="outline" size="sm" onClick={() => toast.success("Asset bundle exported.")} className="gap-1.5"><Icon name="Package" className="w-3.5 h-3.5" /> Export assets</Button>
            </div>
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader><CardTitle className="text-lg">Email branding</CardTitle><CardDescription>Used in transactional emails and magic links.</CardDescription></CardHeader>
        <CardContent className="grid sm:grid-cols-2 gap-3">
          <Field label="From name"><Input value={branding.emailFromName} onChange={(e) => patch({ emailFromName: e.target.value })} /></Field>
          <Field label="From address"><Input value={branding.emailFromAddress} onChange={(e) => patch({ emailFromAddress: e.target.value })} /></Field>
        </CardContent>
      </Card>

      <Card>
        <CardHeader><CardTitle className="text-lg">PDF branding</CardTitle><CardDescription>Footer text on exported resumes and cover letters.</CardDescription></CardHeader>
        <CardContent>
          <Field label="PDF footer text"><Input value={branding.pdfFooterText} onChange={(e) => patch({ pdfFooterText: e.target.value })} /></Field>
        </CardContent>
      </Card>

      <div className="flex justify-end">
        <Button onClick={save} disabled={saving} className="bg-brand hover:bg-brand-dark text-white gap-2"><Icon name="Save" className="w-4 h-4" /> {saving ? "Saving…" : "Save branding"}</Button>
      </div>
    </div>
  );
}

function Field({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div className="space-y-1.5">
      <Label className="text-xs uppercase tracking-wide text-muted-foreground">{label}</Label>
      {children}
    </div>
  );
}

src/components/app/modules/CandidateExpe:
"use client";

// ============================================================================
// Phase 8.1.5 (P2) — Candidate Interview Experience (Adaptive Live Interview Hub).
//
// PRESENTATION ONLY. This module is the premium adaptive-interview launcher and
// experience hub. It does NOT execute AI and does NOT re-implement the
// per-question answer/feedback UI (that already lives in InterviewSession /
// VideoInterviewSession). Instead it:
//   1. Surfaces the adaptive-engine context (scenario = role/company, persona
//      mix, difficulty/confidence preview) for setup.
//   2. Launches the EXISTING InterviewSession for the live practice interview.
//   3. On completion, persists a lightweight InterviewSessionRecord to the
//      store (memory + records) so the Recruiter Intelligence / Explainability /
//      Flight Recorder modules can consume it — closing the candidate→recruiter
//      loop without duplicating logic.
//
// All computation is delegated to the adaptive engine (generateInterviewQuestions
// / toInterviewPackage) and the store. No scoring or analytics here.
// ============================================================================

import { useCallback, useMemo, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge, Icon, ScoreRing } from "@/components/shared";
import { useApp, uid } from "@/lib/store";
import { generateInterviewQuestions, toInterviewPackage, type GeneratedPackage } from "@/lib/interview/ai";
import { INTERVIEW_PERSONAS } from "@/lib/interview/personas";
import { InterviewSession } from "@/components/interview/InterviewSession";
import { toast } from "sonner";
import type { InterviewPackage, InterviewQuestion } from "@/lib/types";
import type { InterviewSessionRecord } from "@/hooks/interview/types";

const CATEGORIES = [
  { id: "technical", label: "Technical", icon: "Code2", color: "#1154A3" },
  { id: "behavioral", label: "Behavioral", icon: "Users", color: "#F59E0B" },
  { id: "situational", label: "Situational", icon: "GitBranch", color: "#10B981" },
  { id: "hr", label: "HR", icon: "UserCheck", color: "#8B5CF6" },
  { id: "company", label: "Company-specific", icon: "Building2", color: "#EC4899" },
] as const;

const DIFFICULTY_COLORS: Record<string, string> = {
  easy: "#10B981",
  medium: "#F59E0B",
  hard: "#DC2626",
};

export function CandidateExperience() {
  const resumes = useApp((s) => s.resumes);
  const jds = useApp((s) => s.jobDescriptions);
  const atsReports = useApp((s) => s.atsReports);
  const reviewReports = useApp((s) => s.reviewReports);
  const interviewSessions = useApp((s) => s.interviewSessions);
  const addInterviewSession = useApp((s) => s.addInterviewSession);

  const [selectedResumeId, setSelectedResumeId] = useState<string>(resumes[0]?.id ?? "");
  const [selectedJdId, setSelectedJdId] = useState<string>(jds[0]?.id ?? "");
  const [selectedPersonaIds, setSelectedPersonaIds] = useState<string[]>(
    INTERVIEW_PERSONAS.slice(0, 3).map((p) => p.id),
  );
  const [generating, setGenerating] = useState(false);
  const [livePkg, setLivePkg] = useState<InterviewPackage | null>(null);
  const [liveGenerated, setLiveGenerated] = useState<GeneratedPackage | null>(null);

  const selectedResume = resumes.find((r) => r.id === selectedResumeId) ?? resumes[0] ?? null;
  const selectedJd = jds.find((j) => j.id === selectedJdId) ?? jds[0] ?? null;

  const selectedPersonas = useMemo(
    () => INTERVIEW_PERSONAS.filter((p) => selectedPersonaIds.includes(p.id)),
    [selectedPersonaIds],
  );

  const categoryCounts = useMemo(() => {
    const counts: Record<string, number> = {};
    for (const p of selectedPersonas) {
      for (const c of p.questionProfile.emphasizeCategories) {
        counts[c] = (counts[c] ?? 0) + 1;
      }
    }
    return counts;
  }, [selectedPersonas]);

  const companyName = selectedJd?.company ?? null;
  const roleName = selectedJd?.title ?? selectedResume?.headline ?? null;

  // Confidence preview derived from the readiness score the adaptive engine
  // returns at generation time (no separate scoring here — consumed output).
  const togglePersona = useCallback((id: string) => {
    setSelectedPersonaIds((prev) =>
      prev.includes(id) ? prev.filter((p) => p !== id) : [...prev, id],
    );
  }, []);

  const startLive = useCallback(async () => {
    if (!selectedResume) {
      toast.error("Please upload or create a resume first.");
      return;
    }
    if (!selectedJd) {
      toast.error("Please add a job description first.");
      return;
    }
    setGenerating(true);
    try {
      const atsReport = atsReports.find((a) => a.resumeId === selectedResume.id);
      const reviewReport =
        reviewReports.find((r) => r.resumeId === selectedResume.id && (!r.jdId || r.jdId === selectedJd.id)) ??
        reviewReports.find((r) => r.resumeId === selectedResume.id);

      const generated = await generateInterviewQuestions({
        resume: selectedResume,
        jd: selectedJd,
        atsReport,
        reviewReport,
        personaIds: selectedPersonaIds,
        difficultyBias: "adaptive",
      });

      const pkg = toInterviewPackage(generated, {
        resume: selectedResume,
        jd: selectedJd,
        atsReport,
        reviewReport,
        personaIds: selectedPersonaIds,
        difficultyBias: "adaptive",
      });

      const questions: InterviewQuestion[] = generated.questions;
      if (!questions.length) throw new Error("AI returned no questions.");

      setLiveGenerated(generated);
      setLivePkg(pkg);
      toast.success(`${questions.length} adaptive questions ready — good luck!`);
    } catch (e: any) {
      toast.error(e?.message || "Could not start the interview.");
    } finally {
      setGenerating(false);
    }
  }, [selectedResume, selectedJd, atsReports, reviewReports, selectedPersonaIds]);

  // === Live interview in progress — delegate to the existing experience ===
  if (livePkg) {
    return (
      <InterviewSession
        pkg={livePkg}
        onClose={() => {
          // Persist a lightweight record so recruiter modules can consume it.
          const rec: InterviewSessionRecord = {
            id: uid("session"),
            resumeId: livePkg.resumeId,
            jdId: livePkg.jdId,
            company: livePkg.company,
            role: livePkg.role,
            status: "completed",
            recordings: [],
            startedAt: new Date().toISOString(),
            completedAt: new Date().toISOString(),
          };
          addInterviewSession(rec);
          setLivePkg(null);
          setLiveGenerated(null);
        }}
      />
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h1 className="font-display text-2xl font-bold flex items-center gap-2">
          <Icon name="MessagesSquare" className="w-6 h-6 text-brand" /> Live Interview Experience
        </h1>
        <p className="text-sm text-muted-foreground mt-1">
          Adaptive, scenario-driven interview practice. Pick your context, choose your interview panel, and run a live session.
        </p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
        {/* Setup: context + personas */}
        <div className="lg:col-span-2 space-y-4">
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-base flex items-center gap-2">
                <Icon name="Settings2" className="w-4 h-4 text-brand" /> Interview Setup
              </CardTitle>
              <CardDescription>Select the candidate context for this adaptive session.</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4 pt-0">
              {/* Resume + JD selectors */}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                  <label className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Resume</label>
                  <select
                    value={selectedResumeId}
                    onChange={(e) => setSelectedResumeId(e.target.value)}
                    className="mt-1 w-full rounded-md border border-border bg-background px-3 py-2 text-sm"
                  >
                    {resumes.length === 0 && <option value="">No resumes yet</option>}
                    {resumes.map((r) => (
                      <option key={r.id} value={r.id}>{r.name ?? "Untitled resume"}</option>
                    ))}
                  </select>
                </div>
                <div>
                  <label className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Job Description</label>
                  <select
                    value={selectedJdId}
                    onChange={(e) => setSelectedJdId(e.target.value)}
                    className="mt-1 w-full rounded-md border border-border bg-background px-3 py-2 text-sm"
                  >
                    {jds.length === 0 && <option value="">No job descriptions yet</option>}
                    {jds.map((j) => (
                      <option key={j.id} value={j.id}>{j.title ?? "Untitled JD"}</option>
                    ))}
                  </select>
                </div>
              </div>

              {/* Scenario / company / role context */}
              <div className="rounded-lg bg-secondary/40 p-3 flex items-center gap-3">
                <div className="w-10 h-10 rounded-lg bg-brand/10 text-brand flex items-center justify-center shrink-0">
                  <Icon name="Building2" className="w-5 h-5" />
                </div>
                <div className="min-w-0">
                  <div className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Scenario</div>
                  <div className="text-sm font-medium truncate">{roleName ?? "—"} {companyName ? `at ${companyName}` : ""}</div>
                  <div className="text-xs text-muted-foreground">Adaptive difficulty & question mix are derived from this role + JD.</div>
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Persona / panel picker */}
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-base flex items-center gap-2">
                <Icon name="UsersRound" className="w-4 h-4 text-brand" /> Interview Panel
              </CardTitle>
              <CardDescription>Choose the personas that make up your interview panel (drives question angles).</CardDescription>
            </CardHeader>
            <CardContent className="pt-0">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                {INTERVIEW_PERSONAS.map((p) => {
                  const active = selectedPersonaIds.includes(p.id);
                  return (
                    <button
                      key={p.id}
                      type="button"
                      onClick={() => togglePersona(p.id)}
                      className={`flex items-start gap-2.5 rounded-lg border p-3 text-left transition-colors ${
                        active ? "border-brand bg-brand/5" : "border-border hover:bg-secondary/40"
                      }`}
                    >
                      <div
                        className="w-8 h-8 rounded-lg flex items-center justify-center shrink-0"
                        style={{ background: `${p.accent}18`, color: p.accent }}
                      >
                        <Icon name={p.icon} className="w-4 h-4" />
                      </div>
                      <div className="min-w-0 flex-1">
                        <div className="flex items-center justify-between gap-2">
                          <span className="text-sm font-medium truncate">{p.name}</span>
                          {active && <Icon name="CheckCircle2" className="w-4 h-4 text-brand shrink-0" />}
                        </div>
                        <p className="text-xs text-muted-foreground line-clamp-2">{p.role}</p>
                      </div>
                    </button>
                  );
                })}
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Right rail: readiness + difficulty + launch */}
        <div className="space-y-4">
          <Card className="gradient-brand text-white">
            <CardContent className="p-5">
              <div className="flex items-center gap-2 mb-3">
                <Icon name="Sparkles" className="w-5 h-5 text-gold" />
                <span className="font-semibold text-sm">Adaptive Preview</span>
              </div>
              <p className="text-xs opacity-90">
                {selectedPersonas.length} panel member{selectedPersonas.length === 1 ? "" : "s"} selected. The engine calibrates
                difficulty live based on your answers and adapts question categories in real time.
              </p>
              {Object.keys(categoryCounts).length > 0 && (
                <div className="mt-3 space-y-1.5">
                  {Object.entries(categoryCounts).map(([cat, n]) => {
                    const c = CATEGORIES.find((x) => x.id === cat);
                    if (!c) return null;
                    return (
                      <div key={cat} className="flex items-center gap-2 text-xs">
                        <Icon name={c.icon} className="w-3.5 h-3.5 opacity-90" />
                        <span className="opacity-90">{c.label}</span>
                        <span className="ml-auto font-semibold">{n}</span>
                      </div>
                    );
                  })}
                </div>
              )}
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-base flex items-center gap-2">
                <Icon name="Gauge" className="w-4 h-4 text-brand" /> Confidence & Difficulty
              </CardTitle>
            </CardHeader>
            <CardContent className="pt-0 space-y-3">
              <div className="flex items-center gap-3">
                <ScoreRing value={Math.round((selectedPersonas.length / INTERVIEW_PERSONAS.length) * 100)} size={56} label="Panel" />
                <p className="text-xs text-muted-foreground">
                  A broader panel increases scenario coverage. Start with 2–3 for a balanced session.
                </p>
              </div>
              <div className="flex items-center gap-2 flex-wrap">
                <span className="text-[10px] px-2 py-0.5 rounded-full font-semibold" style={{ background: `${DIFFICULTY_COLORS.medium}20`, color: DIFFICULTY_COLORS.medium }}>
                  adaptive
                </span>
                <span className="text-[10px] px-2 py-0.5 rounded-full font-semibold bg-secondary text-muted-foreground">
                  voice + text
                </span>
                <span className="text-[10px] px-2 py-0.5 rounded-full font-semibold bg-secondary text-muted-foreground">
                  STAR feedback
                </span>
              </div>
            </CardContent>
          </Card>

          <Button
            onClick={startLive}
            disabled={generating || !selectedResume || !selectedJd}
            className="w-full bg-brand hover:bg-brand-dark text-white gap-1.5"
            size="lg"
          >
            {generating ? <Icon name="Loader2" className="w-4 h-4 animate-spin" /> : <Icon name="Play" className="w-4 h-4" />}
            {generating ? "Preparing session…" : "Start Live Interview"}
          </Button>

          {interviewSessions.length > 0 && (
            <p className="text-xs text-muted-foreground text-center">
              {interviewSessions.length} prior session{interviewSessions.length === 1 ? "" : "s"} on record — view them in Recruiter Intelligence.
            </p>
          )}
        </div>
      </div>
    </div>
  );
}

src/components/app/modules/CoverLetter.t:
"use client";

import { recordAI, setFlightScope } from "@/lib/ai/flight-recorder";
setFlightScope({ scope: "cover-letter", feature: "Cover Letter", module: "src.components.app.modules.CoverLetter" });

import { useState, useMemo } from "react";
import { motion } from "framer-motion";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge, Icon, ScoreRing } from "@/components/shared";
import { useApp, uid } from "@/lib/store";
import { callAI, extractJSON } from "@/lib/ai";
import { detectIndustry, INDUSTRY_PROFILES } from "@/lib/industry-ats";
import { exportCoverLetterPDF, exportCoverLetterDOCX, exportCoverLetterTXT } from "@/lib/exporter";
import { toast } from "sonner";
import type { CoverLetter } from "@/lib/types";

// ============================================================================
// Tone options
// ============================================================================
const TONES = [
  { id: "Professional", label: "Professional", desc: "Balanced, confident, standard business tone" },
  { id: "Executive", label: "Executive", desc: "Strategic, outcomes-led, C-suite level" },
  { id: "Friendly", label: "Friendly", desc: "Warm, approachable, human connection" },
  { id: "Formal", label: "Formal", desc: "Traditional, precise, highly structured" },
  { id: "Enthusiastic", label: "Enthusiastic", desc: "Energetic, passionate, shows excitement" },
  { id: "Balanced", label: "Balanced", desc: "Mix of professional and warm" },
] as const;

export function CoverLetter() {
  const coverLetters = useApp((s) => s.coverLetters);
  const resumes = useApp((s) => s.resumes);
  const jds = useApp((s) => s.jobDescriptions);
  const addCoverLetter = useApp((s) => s.addCoverLetter);
  const updateCoverLetter = useApp((s) => s.updateCoverLetter);
  const removeCoverLetter = useApp((s) => s.removeCoverLetter);
  const incUsage = useApp((s) => s.incUsage);
  const log = useApp((s) => s.log);

  const [activeId, setActiveId] = useState<string>(coverLetters[0]?.id ?? "");
  const [generating, setGenerating] = useState(false);
  const [selectedTone, setSelectedTone] = useState<string>("Professional");
  const [matchScore, setMatchScore] = useState<number | null>(null);
  const [keywordsUsed, setKeywordsUsed] = useState<string[]>([]);
  const [sectionsReferenced, setSectionsReferenced] = useState<string[]>([]);

  const active = coverLetters.find((c) => c.id === activeId) ?? null;

  // === Auto-detect industry from JD + resume ===
  const industryDetection = useMemo(() => {
    const resume = resumes[0];
    const jd = jds[0];
    if (!jd) return null;
    const jdText = jd.rawText ?? jd.keywords.join(" ");
    const resumeText = `${resume?.name ?? ""} ${resume?.headline ?? ""} ${resume?.summary ?? ""} ${resume?.experience.map((e) => e.title + " " + e.company).join(" ")}`;
    return detectIndustry(jdText, resumeText);
  }, [resumes, jds]);

  const industryProfile = industryDetection ? INDUSTRY_PROFILES[industryDetection.industryId] : null;

  // === Dynamic Cover Letter Generation ===
  const generate = async () => {
    const resume = resumes[0];
    const jd = jds[0];

    if (!resume) {
      toast.error("Please upload or create a resume first.");
      return;
    }
    if (!jd) {
      toast.error("Please add a job description first.");
      return;
    }

    setGenerating(true);
    setMatchScore(null);
    setKeywordsUsed([]);
    setSectionsReferenced([]);

    try {
      // Build context from optimized resume (preferred) or original
      const resumeContext = JSON.stringify({
        name: resume.name,
        headline: resume.headline,
        summary: resume.summary,
        experience: resume.experience.map((e) => ({
          title: e.title,
          company: e.company,
          location: e.location,
          startDate: e.startDate,
          endDate: e.endDate,
          bullets: e.bullets,
        })),
        skills: resume.skills.map((s) => s.name),
        education: resume.education.map((ed) => ({ degree: ed.degree, institution: ed.institution })),
        languages: resume.languages.map((l) => l.name),
        certifications: resume.certifications.map((c) => c.name),
      });

      const jdContext = jd.rawText ?? JSON.stringify({
        title: jd.title,
        company: jd.company,
        location: jd.location,
        responsibilities: jd.responsibilities,
        requiredSkills: jd.requiredSkills,
        preferredSkills: jd.preferredSkills,
        keywords: jd.keywords,
      });

      const industryContext = industryProfile ? `
INDUSTRY: ${industryProfile.label}
INDUSTRY WRITING GUIDANCE: ${industryProfile.writingGuidance}
INDUSTRY KEYWORDS: ${industryProfile.priorityKeywords.join(", ")}
` : "";

      const result = await recordAI({
        systemPrompt: `You are an Expert Cover Letter Writer, Senior Recruiter, and ATS Specialist. You write highly personalized, recruiter-grade cover letters that sound human and professional. You NEVER fabricate experience, skills, or achievements — you only use information from the candidate's resume. You adapt language to the detected industry. Always return ONLY valid JSON.

TONE: ${selectedTone}
${industryContext}

COVER LETTER STRUCTURE:
1. Professional Greeting (address the hiring manager or "Dear Hiring Manager")
2. Introduction (hook: why this role at this company excites you)
3. Why This Company (reference the company's mission/values/position if known from the job description)
4. Why This Role (connect your experience to the specific responsibilities)
5. Relevant Experience (2-3 key achievements from your resume that align with JD requirements)
6. Value Proposition (what you bring that others don't)
7. Closing Statement (confident CTA — request an interview)
8. Professional Signature

CONTENT RULES:
- Target 350-500 words (preferably ~450 words)
- One page maximum
- Sound HUMAN — avoid generic AI language ("dynamic professional", "passionate about", "track record of", "I excel in", "my professional journey", "I am confident")
- Use strong action verbs: Delivered, Implemented, Improved, Optimized, Led, Designed
- Reference SPECIFIC achievements from the resume with measurable outcomes (numbers, %, $)
- Incorporate keywords from the job description naturally (no stuffing)
- Industry-adaptive language (use industry terminology from the keyword bank)
- NEVER mention skills not present in the resume
- NEVER fabricate company information — only use what's in the JD
- ATS-friendly: include key JD keywords naturally

GROUNDING REQUIREMENTS (CRITICAL):
- You MUST reference at least 3 different resume sections in the cover letter:
  1. Professional Summary (background + years of experience)
  2. Experience (at least 2 specific achievements with metrics from actual roles)
  3. Skills (at least 3 relevant skills from the resume)
- If the resume has Languages, mention them.
- If the resume has Certifications, mention them.
- If the resume has Education relevant to the role, mention it.
- The sectionsReferenced array MUST list ALL sections you actually used.

Return JSON:
{
  "content": "The full cover letter text (plain text, no markdown)",
  "matchScore": 85,
  "keywordsUsed": ["keyword1", "keyword2"],
  "sectionsReferenced": ["Professional Summary", "Experience", "Skills", "Languages", "Certifications"]
}`,
        userPrompt: `CANDIDATE'S RESUME (primary source of truth — use ONLY this information):
${resumeContext}

JOB DESCRIPTION:
${jdContext}

COMPANY: ${jd.company || "the company"}
JOB TITLE: ${jd.title || "the role"}
INDUSTRY: ${industryProfile?.label || "Generic"}

Generate a highly personalized, recruiter-grade cover letter that aligns the candidate's experience with the job requirements. Use the candidate's REAL achievements and skills — never fabricate. Incorporate JD keywords naturally. Adapt language to the ${industryProfile?.label || "relevant"} industry.

Return ONLY valid JSON.`,
        maxTokens: 2000,
        temperature: 0.5,
        taskCategory: "document",
      });

      // Parse the AI response
      let data: { content: string; matchScore: number; keywordsUsed: string[]; sectionsReferenced: string[] };
      try {
        const raw = extractJSON<any>(result.text);
        // === NORMALIZATION: handle multiple possible key names ===
        // The AI may return { content: "..." }, { letter: "..." }, { text: "..." },
        // or just a plain string. Normalize to { content, matchScore, ... }.
        const content = raw.content || raw.letter || raw.text || raw.coverLetter || raw.body || "";
        if (content && typeof content === "string" && content.trim().length > 50) {
          data = {
            content,
            matchScore: raw.matchScore || raw.match_score || raw.score || 75,
            keywordsUsed: Array.isArray(raw.keywordsUsed) ? raw.keywordsUsed
              : Array.isArray(raw.keywords_used) ? raw.keywords_used
              : Array.isArray(raw.keywords) ? raw.keywords
              : jd.keywords.slice(0, 8),
            sectionsReferenced: Array.isArray(raw.sectionsReferenced) ? raw.sectionsReferenced
              : Array.isArray(raw.sections_referenced) ? raw.sections_referenced
              : Array.isArray(raw.sections) ? raw.sections
              : ["Professional Summary", "Experience", "Skills"],
          };
        } else {
          // JSON parsed but content is missing/empty — treat the raw text as content
          data = {
            content: result.text,
            matchScore: 75,
            keywordsUsed: jd.keywords.slice(0, 8),
            sectionsReferenced: ["Professional Summary", "Experience", "Skills"],
          };
        }
      } catch {
        // Fallback: treat the entire response as cover letter content
        data = {
          content: result.text,
          matchScore: 75,
          keywordsUsed: jd.keywords.slice(0, 8),
          sectionsReferenced: ["Summary", "Experience", "Skills"],
        };
      }

      const cl: CoverLetter = {
        id: uid("cl"),
        title: `Cover Letter — ${jd.company || "Target Company"}`,
        template: "modern",
        content: data.content || result.text,
        resumeId: resume.id,
        jdId: jd.id,
        company: jd.company,
        role: jd.title,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      };
      addCoverLetter(cl);
      setActiveId(cl.id);
      setMatchScore(data.matchScore ?? 75);
      setKeywordsUsed(data.keywordsUsed ?? []);
      setSectionsReferenced(data.sectionsReferenced ?? []);
      incUsage("coverLetters");
      log({
        actor: "you",
        action: "Cover letter generated (dynamic)",
        category: "ai",
        details: `${selectedTone} tone · ${industryProfile?.label || "Generic"} industry · ${data.matchScore ?? 75}% match via ${result.provider}`,
        severity: "info",
      });
      toast.success(`Cover letter generated — ${data.matchScore ?? 75}% match via ${result.provider}`);
    } catch (e: any) {
      toast.error(e?.message || "Generation failed. Please try again.");
    } finally {
      setGenerating(false);
    }
  };

  const updateContent = (content: string) => {
    if (!active) return;
    updateCoverLetter(active.id, { content });
  };

  // === Empty state ===
  if (!active && coverLetters.length === 0) {
    return (
      <div className="space-y-6">
        <div>
          <h1 className="font-display text-2xl font-bold flex items-center gap-2"><Icon name="Mail" className="w-6 h-6 text-brand" /> Cover Letter Generator</h1>
          <p className="text-sm text-muted-foreground mt-1">Dynamic, context-aware cover letters tailored to your optimized resume and job description.</p>
        </div>

        {/* Context summary */}
        <Card>
          <CardContent className="p-4 space-y-3">
            <div className="grid sm:grid-cols-2 gap-3 text-xs">
              <div className="rounded-lg bg-secondary/40 p-2.5 flex items-center justify-between">
                <span className="text-muted-foreground">Resume:</span>
                <span className="font-semibold">{resumes[0]?.name ?? "Not uploaded"}</span>
              </div>
              <div className="rounded-lg bg-secondary/40 p-2.5 flex items-center justify-between">
                <span className="text-muted-foreground">Job Description:</span>
                <span className="font-semibold">{jds[0]?.title ?? "Not added"}</span>
              </div>
              <div className="rounded-lg bg-secondary/40 p-2.5 flex items-center justify-between">
                <span className="text-muted-foreground">Company:</span>
                <span className="font-semibold">{jds[0]?.company ?? "Not specified"}</span>
              </div>
              <div className="rounded-lg bg-secondary/40 p-2.5 flex items-center justify-between">
                <span className="text-muted-foreground">Detected Industry:</span>
                <span className="font-semibold">{industryProfile?.label ?? "Generic"}</span>
              </div>
            </div>
            {industryDetection && industryDetection.confidence >= 15 && (
              <div className="rounded-lg bg-brand/5 dark:bg-brand/10 border border-brand/20 p-2.5 flex items-start gap-2">
                <Icon name="Info" className="w-3.5 h-3.5 text-brand shrink-0 mt-0.5" />
                <p className="text-xs text-muted-foreground">
                  Industry detected: <strong>{industryProfile?.label}</strong>. The cover letter will be tailored with {industryProfile?.label.toLowerCase()} terminology and writing style.
                </p>
              </div>
            )}
          </CardContent>
        </Card>

        {/* Tone selector */}
        <Card>
          <CardHeader><CardTitle className="text-base">Select Tone</CardTitle></CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
              {TONES.map((t) => (
                <button
                  key={t.id}
                  onClick={() => setSelectedTone(t.id)}
                  className={`flex flex-col items-start p-3 rounded-lg border-2 transition text-left ${
                    selectedTone === t.id ? "border-brand bg-brand/10" : "border-border hover:border-brand/40"
                  }`}
                >
                  <span className={`text-sm font-medium ${selectedTone === t.id ? "text-brand" : "text-foreground"}`}>{t.label}</span>
                  <span className="text-[10px] text-muted-foreground mt-0.5">{t.desc}</span>
                </button>
              ))}
            </div>
          </CardContent>
        </Card>

        {/* Generate button */}
        <Card>
          <CardContent className="p-5 sm:p-6 text-center">
            <Icon name="Sparkles" className="w-10 h-10 text-brand mx-auto" />
            <h3 className="mt-3 font-semibold text-base">Generate Your Cover Letter</h3>
            <p className="text-sm text-muted-foreground mt-1 max-w-md mx-auto">
              AI-generated from your resume and job description. Tailored to {industryProfile?.label || "your industry"} with {selectedTone.toLowerCase()} tone. Recruiter-grade, ATS-friendly, one page.
            </p>
            <Button onClick={generate} disabled={generating || !resumes[0] || !jds[0]} className="bg-brand hover:bg-brand-dark text-white gap-2 mt-4">
              {generating ? <Icon name="Loader2" className="w-4 h-4 animate-spin" /> : <Icon name="Wand2" className="w-4 h-4" />}
              {generating ? "Generating…" : "Generate Cover Letter"}
            </Button>
            {(!resumes[0] || !jds[0]) && (
              <p className="text-xs text-amber-600 mt-2">
                {!resumes[0] ? "Upload a resume first. " : ""}
                {!jds[0] ? "Add a job description first." : ""}
              </p>
            )}
          </CardContent>
        </Card>
      </div>
    );
  }

  // === Active cover letter view ===
  if (!active) return null;
  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h1 className="font-display text-2xl font-bold flex items-center gap-2"><Icon name="Mail" className="w-6 h-6 text-brand" /> Cover Letter Generator</h1>
          <p className="text-sm text-muted-foreground mt-1">Edit the draft, then export in your preferred format.</p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" size="sm" onClick={() => { removeCoverLetter(active.id); setActiveId(coverLetters.find(c => c.id !== active.id)?.id ?? ""); toast.success("Deleted."); }}>
            <Icon name="Trash2" className="w-4 h-4" />
          </Button>
          <Button variant="outline" size="sm" onClick={() => exportCoverLetterTXT(active)} className="gap-1.5"><Icon name="FileText" className="w-3.5 h-3.5" /> TXT</Button>
          <Button variant="outline" size="sm" onClick={() => { exportCoverLetterDOCX(active); incUsage("downloads"); toast.success("DOCX exported."); }} className="gap-1.5"><Icon name="FileType" className="w-3.5 h-3.5" /> DOCX</Button>
          <Button size="sm" onClick={() => { exportCoverLetterPDF(active); incUsage("downloads"); log({ actor: "you", action: "Cover letter exported (PDF)", category: "export", details: `${active.title}.pdf`, severity: "info" }); toast.success("PDF exported."); }} className="bg-brand hover:bg-brand-dark text-white gap-1.5"><Icon name="Download" className="w-3.5 h-3.5" /> PDF</Button>
        </div>
      </div>

      <div className="grid lg:grid-cols-12 gap-4">
        {/* Editor + metadata */}
        <div className="lg:col-span-7 space-y-3">
          {/* Match score + keywords */}
          {matchScore !== null && (
            <Card>
              <CardContent className="p-4">
                <div className="flex items-center gap-4 flex-wrap">
                  <ScoreRing value={matchScore} size={60} label="Match" />
                  <div className="flex-1 min-w-0 space-y-2">
                    {keywordsUsed.length > 0 && (
                      <div>
                        <div className="text-[10px] uppercase tracking-wide text-muted-foreground font-semibold mb-1">Keywords Used ({keywordsUsed.length})</div>
                        <div className="flex flex-wrap gap-1">
                          {keywordsUsed.slice(0, 12).map((k, i) => <Badge key={i} variant="success" className="text-[9px]">{k}</Badge>)}
                        </div>
                      </div>
                    )}
                    {sectionsReferenced.length > 0 && (
                      <div>
                        <div className="text-[10px] uppercase tracking-wide text-muted-foreground font-semibold mb-1">Resume Sections Referenced</div>
                        <div className="flex flex-wrap gap-1">
                          {sectionsReferenced.map((s, i) => <Badge key={i} variant="outline" className="text-[9px]">{s}</Badge>)}
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              </CardContent>
            </Card>
          )}

          <Card>
            <CardHeader>
              <div className="flex items-center justify-between">
                <CardTitle className="text-base">Edit</CardTitle>
                <Badge variant="outline">{active.company ? `${active.role ?? ""} at ${active.company}` : active.template}</Badge>
              </div>
            </CardHeader>
            <CardContent className="space-y-3">
              <div className="grid sm:grid-cols-2 gap-3">
                <Field label="Title">
                  <Input value={active.title} onChange={(e) => updateCoverLetter(active.id, { title: e.target.value })} />
                </Field>
                <Field label="Company">
                  <Input value={active.company ?? ""} onChange={(e) => updateCoverLetter(active.id, { company: e.target.value })} />
                </Field>
              </div>
              <Field label="Content">
                <Textarea
                  value={active.content}
                  onChange={(e) => updateContent(e.target.value)}
                  rows={18}
                  className="font-serif text-[15px] leading-relaxed"
                />
                <p className="text-xs text-muted-foreground mt-1">{active.content.split(/\s+/).length} words {active.content.split(/\s+/).length > 500 && <span className="text-amber-600">· exceeds 500-word target</span>}</p>
              </Field>
            </CardContent>
          </Card>

          {/* Generate another */}
          <Card>
            <CardHeader><CardTitle className="text-base">Generate Another</CardTitle></CardHeader>
            <CardContent className="space-y-3">
              <div>
                <Label className="text-[10px] uppercase tracking-wide text-muted-foreground font-semibold mb-1.5 block">Tone</Label>
                <div className="flex flex-wrap gap-1.5">
                  {TONES.map((t) => (
                    <button
                      key={t.id}
                      onClick={() => setSelectedTone(t.id)}
                      className={`text-xs px-2.5 py-1 rounded-full border transition ${
                        selectedTone === t.id ? "border-brand bg-brand/10 text-brand font-medium" : "border-border text-muted-foreground hover:text-foreground"
                      }`}
                    >
                      {t.label}
                    </button>
                  ))}
                </div>
              </div>
              <Button onClick={generate} disabled={generating} className="bg-brand hover:bg-brand-dark text-white gap-2">
                {generating ? <Icon name="Loader2" className="w-4 h-4 animate-spin" /> : <Icon name="Sparkles" className="w-4 h-4" />}
                {generating ? "Generating…" : `Generate with ${selectedTone} tone`}
              </Button>
            </CardContent>
          </Card>
        </div>

        {/* Preview */}
        <div className="lg:col-span-5">
          <div className="sticky top-20">
            <div className="rounded-xl bg-secondary/60 p-4 max-h-[calc(100vh-160px)] overflow-y-auto">
              <div className="a4-page !w-full !min-h-0 !max-h-none p-[16mm]" style={{ transformOrigin: "top" }}>
                <div className="text-[10pt] leading-relaxed text-slate-800" style={{ fontFamily: "'Inter', sans-serif" }}>
                  {/* Header mirrors the export: role @ company + date. The
                      internal title ("Cover Letter — <Company>") is a file
                      label only and is deliberately NOT rendered. */}
                  <div className="border-b-2 pb-3 mb-4" style={{ borderColor: "#1154A3" }}>
                    {active.role && active.company && <div className="text-[10pt] font-bold text-slate-900">{active.role} at {active.company}</div>}
                    <div className="text-[9pt] text-slate-500 mt-1" suppressHydrationWarning>{new Date().toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" })}</div>
                  </div>
                  {active.content.split(/\n\s*\n/).map((p, i) => (
                    <p key={i} className="mb-3 text-pretty">{p.trim()}</p>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Saved letters */}
      <Card>
        <CardHeader><CardTitle className="text-base">All cover letters ({coverLetters.length})</CardTitle></CardHeader>
        <CardContent>
          {coverLetters.length === 0 ? (
            <p className="text-sm text-muted-foreground text-center py-4">No cover letters yet. Generate one above.</p>
          ) : (
            <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-2">
              {coverLetters.map((c) => (
                <button key={c.id} onClick={() => setActiveId(c.id)} className={`text-left rounded-lg border p-3 transition ${c.id === active.id ? "border-brand bg-brand-light/40" : "border-border hover:border-brand/40"}`}>
                  <div className="font-semibold text-sm truncate">{c.title}</div>
                  <div className="text-xs text-muted-foreground mt-0.5">{c.content.split(/\s+/).length} words{c.company ? ` · ${c.company}` : ""}</div>
                </button>
              ))}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

function Field({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div className="space-y-1.5">
      <Label className="text-xs uppercase tracking-wide text-muted-foreground">{label}</Label>
      {children}
    </div>
  );
}

