"use client";

import { motion } from "framer-motion";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Icon, Badge, ScoreRing } from "@/components/shared";
import { useApp } from "@/lib/store";
import { TEMPLATES } from "@/lib/brand";
import { dueFollowUps } from "@/lib/applications-logic";

export function Dashboard() {
  const user = useApp((s) => s.user);
  const resumes = useApp((s) => s.resumes);
  const jds = useApp((s) => s.jobDescriptions);
  const coverLetters = useApp((s) => s.coverLetters);
  const interviews = useApp((s) => s.interviews);
  const atsReports = useApp((s) => s.atsReports);
  const applications = useApp((s) => s.applications);
  const setView = useApp((s) => s.setView);
  const setActiveResume = useApp((s) => s.setActiveResume);
  const providers = useApp((s) => s.providers);

  const latestReport = atsReports[0];
  const activeProviders = providers.filter((p) => p.isActive).length;
  const followUps = dueFollowUps(applications);

  const stats = [
    { label: "Resumes", value: resumes.length, icon: "FileText", color: "#1154A3", action: () => setView("resumes") },
    { label: "ATS checks", value: atsReports.length, icon: "ScanText", color: "#10B981", action: () => setView("ats-checker") },
    { label: "Applications", value: applications.length, icon: "KanbanSquare", color: "#0EA5E9", action: () => setView("app-tracker") },
    { label: "Cover letters", value: coverLetters.length, icon: "Mail", color: "#F59E0B", action: () => setView("cover-letter") },
    { label: "Interview preps", value: interviews.length, icon: "MessagesSquare", color: "#8B5CF6", action: () => setView("interview") },
  ];

  const quickActions = [
    { title: "Check ATS score", desc: "Upload your resume and get an instant ATS analysis.", icon: "ScanText", color: "#10B981", action: () => setView("ats-checker") },
    { title: "Build a new resume", desc: "Start from a template — fits one A4 page, guaranteed.", icon: "FilePlus2", color: "#1154A3", action: () => setView("builder") },
    { title: "Optimize for a job", desc: "Match your resume to a job description with AI.", icon: "Wand2", color: "#F59E0B", action: () => setView("optimizer") },
    { title: "Generate cover letter", desc: "Modern, traditional, executive, or email.", icon: "Mail", color: "#8B5CF6", action: () => setView("cover-letter") },
    { title: "Prep for interviews", desc: "Get STAR-method answers for your target role.", icon: "MessagesSquare", color: "#EC4899", action: () => setView("interview") },
    { title: "Track applications", desc: "Organize your pipeline from wishlist to offer — with follow-up reminders.", icon: "KanbanSquare", color: "#0EA5E9", action: () => setView("app-tracker") },
    { title: "Scrape a job posting", desc: "Extract keywords from any URL.", icon: "Search", color: "#0EA5E9", action: () => setView("jd-scraper") },
  ];

  return (
    <div className="space-y-6">
      {/* Welcome */}
      <motion.div
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        className="rounded-2xl gradient-brand text-white p-6 sm:p-8 relative overflow-hidden"
      >
        <div className="absolute -top-10 -right-10 w-40 h-40 rounded-full bg-white/10 blur-2xl" />
        <div className="absolute bottom-0 right-0 w-60 h-60 rounded-full bg-gold/20 blur-3xl" />
        <div className="relative">
          <Badge variant="gold"><Icon name="Sparkles" className="w-3 h-3" /> {user?.role === "super_admin" ? "Super Admin" : user?.role === "admin" ? "Admin" : "Pro"} account</Badge>
          <h1 className="font-display text-2xl sm:text-3xl font-bold mt-3">
            Welcome back, {user?.name?.split(" ")[0]}.
          </h1>
          <p className="text-white/85 mt-1 max-w-xl text-pretty">
            Your AI-powered career toolkit is ready. Pick a quick action below or jump into any module from the sidebar.
          </p>
          <div className="mt-5 flex flex-wrap gap-2">
            <Button onClick={() => setView("builder")} className="bg-white text-brand hover:bg-white/90 gap-2">
              <Icon name="FilePlus2" className="w-4 h-4" /> New resume
            </Button>
            <Button onClick={() => setView("ats-checker")} variant="outline" className="bg-transparent border-white/40 text-white hover:bg-white/10 hover:text-white gap-2">
              <Icon name="ScanText" className="w-4 h-4" /> Check ATS
            </Button>
          </div>
        </div>
      </motion.div>

      {/* Follow-ups due — application tracker reminders */}
      {followUps.length > 0 && (
        <motion.button
          initial={{ opacity: 0, y: 8 }}
          animate={{ opacity: 1, y: 0 }}
          onClick={() => setView("app-tracker")}
          className="w-full text-left rounded-xl border border-amber-300 bg-amber-50 dark:border-amber-900 dark:bg-amber-950/40 p-4 flex items-center gap-3 hover:shadow-sm transition-shadow"
        >
          <Icon name="BellRing" className="w-5 h-5 text-amber-600 shrink-0" />
          <span className="min-w-0">
            <span className="block text-sm font-medium text-amber-900 dark:text-amber-200">
              {followUps.length} application follow-up{followUps.length > 1 ? "s" : ""} due
            </span>
            <span className="block text-xs text-amber-800 dark:text-amber-300 truncate">
              Next up: {followUps[0].role || "Untitled role"} @ {followUps[0].company || "—"}
              {followUps.length > 1 ? ` · +${followUps.length - 1} more` : ""}
            </span>
          </span>
          <Icon name="ChevronRight" className="w-4 h-4 text-amber-600 ml-auto shrink-0" />
        </motion.button>
      )}

      {/* Stats */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        {stats.map((s, i) => (
          <motion.button
            key={s.label}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: i * 0.05 }}
            onClick={s.action}
            className="text-left"
          >
            <Card className="hover:shadow-premium hover:-translate-y-0.5 transition-all">
              <CardContent className="p-5">
                <div className="flex items-center justify-between">
                  <div className="w-10 h-10 rounded-lg flex items-center justify-center" style={{ background: `${s.color}14`, color: s.color }}>
                    <Icon name={s.icon} className="w-5 h-5" />
                  </div>
                  <span className="text-2xl font-bold font-display">{s.value}</span>
                </div>
                <div className="mt-2 text-sm text-muted-foreground">{s.label}</div>
              </CardContent>
            </Card>
          </motion.button>
        ))}
      </div>

      <div className="grid lg:grid-cols-3 gap-6">
        {/* Quick actions */}
        <Card className="lg:col-span-2">
          <CardHeader>
            <CardTitle className="flex items-center gap-2"><Icon name="Zap" className="w-4 h-4 text-gold" /> Quick actions</CardTitle>
            <CardDescription>Jump into the most-used tools.</CardDescription>
          </CardHeader>
          <CardContent>
            <div className="grid sm:grid-cols-2 gap-3">
              {quickActions.map((a) => (
                <button
                  key={a.title}
                  onClick={a.action}
                  className="group text-left rounded-xl border border-border bg-card p-4 hover:shadow-premium hover:-translate-y-0.5 transition-all"
                >
                  <div className="flex items-start gap-3">
                    <div className="w-10 h-10 rounded-lg flex items-center justify-center shrink-0" style={{ background: `${a.color}14`, color: a.color }}>
                      <Icon name={a.icon} className="w-5 h-5" />
                    </div>
                    <div className="min-w-0">
                      <div className="font-semibold text-sm flex items-center gap-1">
                        {a.title}
                        <Icon name="ArrowRight" className="w-3 h-3 text-muted-foreground opacity-0 group-hover:opacity-100 group-hover:translate-x-0.5 transition" />
                      </div>
                      <div className="text-xs text-muted-foreground mt-0.5 text-pretty">{a.desc}</div>
                    </div>
                  </div>
                </button>
              ))}
            </div>
          </CardContent>
        </Card>

        {/* Latest ATS + AI status */}
        <div className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2"><Icon name="Activity" className="w-4 h-4 text-brand" /> Latest ATS report</CardTitle>
            </CardHeader>
            <CardContent className="flex flex-col items-center">
              {latestReport ? (
                <>
                  <ScoreRing value={latestReport.scores.ats} size={120} label="ATS Score" />
                  <div className="mt-3 text-xs text-muted-foreground text-center">
                    {latestReport.jdMatchPercent != null ? `${latestReport.jdMatchPercent}% JD match` : "No JD comparison"}
                  </div>
                  <Button size="sm" variant="outline" className="mt-3 w-full" onClick={() => setView("ats-checker")}>
                    View report
                  </Button>
                </>
              ) : (
                <div className="text-center py-4">
                  <Icon name="ScanText" className="w-10 h-10 text-muted-foreground/40 mx-auto" />
                  <p className="text-sm text-muted-foreground mt-2">No reports yet</p>
                  <Button size="sm" className="mt-3 bg-brand hover:bg-brand-dark text-white" onClick={() => setView("ats-checker")}>
                    Run first check
                  </Button>
                </div>
              )}
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2"><Icon name="Cpu" className="w-4 h-4 text-gold" /> AI providers</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold font-display">{activeProviders} <span className="text-sm font-normal text-muted-foreground">active</span></div>
              <div className="mt-3 space-y-1.5">
                {providers.slice(0, 3).map((p) => (
                  <div key={p.id} className="flex items-center justify-between text-xs">
                    <span className="truncate">{p.name}</span>
                    <span className={`w-1.5 h-1.5 rounded-full ${p.status === "healthy" ? "bg-emerald-500" : p.status === "degraded" ? "bg-amber-500" : "bg-red-500"}`} />
                  </div>
                ))}
              </div>
              <Button size="sm" variant="outline" className="mt-3 w-full" onClick={() => setView("ai-providers")}>
                Manage providers
              </Button>
            </CardContent>
          </Card>
        </div>
      </div>

      {/* Recent resumes */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle className="flex items-center gap-2"><Icon name="FileText" className="w-4 h-4 text-brand" /> Your resumes</CardTitle>
              <CardDescription>{resumes.length} total · {jds.length} job descriptions saved</CardDescription>
            </div>
            <Button size="sm" onClick={() => setView("builder")} className="bg-brand hover:bg-brand-dark text-white gap-2">
              <Icon name="Plus" className="w-4 h-4" /> New
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-3">
            {resumes.map((r) => {
              const template = TEMPLATES.find((t) => t.id === r.template);
              return (
                <button
                  key={r.id}
                  onClick={() => { setActiveResume(r.id); setView("builder"); }}
                  className="group text-left rounded-xl border border-border bg-card p-4 hover:shadow-premium hover:-translate-y-0.5 transition-all"
                >
                  <div className="flex items-center justify-between mb-2">
                    <div className="text-sm font-semibold truncate">{r.name}</div>
                    <Badge variant="outline" className="text-[10px]">{template?.name ?? r.template}</Badge>
                  </div>
                  {r.headline && <div className="text-xs text-muted-foreground truncate">{r.headline}</div>}
                  <div className="mt-2 flex items-center gap-3 text-[10px] text-muted-foreground">
                    <span className="flex items-center gap-1"><Icon name="Briefcase" className="w-3 h-3" /> {r.experience.length} exp</span>
                    <span className="flex items-center gap-1"><Icon name="Wrench" className="w-3 h-3" /> {r.skills.length} skills</span>
                  </div>
                  <div className="mt-3 text-xs text-brand font-medium flex items-center gap-1">
                    Open builder <Icon name="ArrowRight" className="w-3 h-3 group-hover:translate-x-0.5 transition" />
                  </div>
                </button>
              );
            })}
            {resumes.length === 0 && (
              <div className="col-span-full text-center py-8">
                <p className="text-sm text-muted-foreground">No resumes yet. Start with a template.</p>
              </div>
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

src/components/app/modules/DirectiveComp:
"use client";

import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Badge, Icon, ScoreRing } from "@/components/shared";

/**
 * DirectiveComplianceCard — displays how well the output follows the OptimizationPolicy.
 *
 * Shows:
 *   - Compliance score ring
 *   - Pass/Fail status
 *   - Per-check breakdown (7 checks)
 */

export interface ComplianceCheck {
  check: string;
  passed: boolean;
  detail?: string;
}

export interface DirectiveComplianceCardProps {
  /** Compliance score (0-100) */
  complianceScore: number;
  /** Whether overall compliance passed */
  passed: boolean;
  /** Individual compliance checks */
  checks: ComplianceCheck[];
}

export function DirectiveComplianceCard({ complianceScore, passed, checks }: DirectiveComplianceCardProps) {
  const passedCount = checks.filter((c) => c.passed).length;
  const totalCount = checks.length;

  return (
    <Card>
      <CardHeader className="pb-3">
        <CardTitle className="text-sm flex items-center gap-2">
          <Icon name="FileCheck" className="w-4 h-4 text-brand" />
          Directive Compliance
          <Badge variant={passed ? "success" : "warning"} className="ml-auto text-[10px]">
            {passed ? "PASS" : "FAIL"}
          </Badge>
        </CardTitle>
        <CardDescription className="text-xs">
          How well the optimized resume follows the custom optimization policy
        </CardDescription>
      </CardHeader>
      <CardContent className="pt-0 space-y-4">
        <div className="flex items-center justify-center">
          <ScoreRing value={complianceScore} size={100} label="Compliance" />
        </div>

        {/* Summary bar */}
        <div className="text-xs text-center text-muted-foreground">
          {passedCount} / {totalCount} checks passed
        </div>

        {/* Per-check breakdown */}
        {totalCount > 0 && (
          <div className="space-y-1.5">
            {checks.map((check) => (
              <div key={check.check} className="flex items-center gap-2 text-xs">
                <Icon
                  name={check.passed ? "CheckCircle2" : "XCircle"}
                  className={`w-3.5 h-3.5 shrink-0 ${check.passed ? "text-emerald-600" : "text-red-600"}`}
                />
                <span className="font-medium">{check.check}</span>
                {check.detail && (
                  <span className="text-muted-foreground ml-auto text-[10px] truncate max-w-[140px]" title={check.detail}>
                    {check.detail}
                  </span>
                )}
              </div>
            ))}
          </div>
        )}

        {totalCount === 0 && (
          <p className="text-xs text-muted-foreground text-center py-2">No compliance checks available.</p>
        )}
      </CardContent>
    </Card>
  );
}

src/components/app/modules/Downloads.tsx:
"use client";

import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge, Icon } from "@/components/shared";
import { useApp } from "@/lib/store";
import {
  exportResumePDF, exportResumeDOCX, exportResumeTXT,
  exportCoverLetterPDF, exportCoverLetterDOCX, exportCoverLetterTXT,
  exportInterviewPDF, exportInterviewDOCX,
} from "@/lib/exporter";

export function Downloads() {
  const resumes = useApp((s) => s.resumes);
  const coverLetters = useApp((s) => s.coverLetters);
  const interviews = useApp((s) => s.interviews);
  const incUsage = useApp((s) => s.incUsage);
  const log = useApp((s) => s.log);

  const downloadResume = async (r: any, fmt: "pdf" | "docx" | "txt") => {
    if (fmt === "pdf") { const res = await exportResumePDF(r, { enforceOnePage: true }); if (!res.ok) return; }
    if (fmt === "docx") exportResumeDOCX(r);
    if (fmt === "txt") exportResumeTXT(r);
    incUsage("downloads");
    log({ actor: "you", action: `Downloaded resume (${fmt})`, category: "export", details: `${r.name}_resume.${fmt}`, severity: "info" });
  };

  const downloadCL = (c: any, fmt: "pdf" | "docx" | "txt") => {
    if (fmt === "pdf") exportCoverLetterPDF(c);
    if (fmt === "docx") exportCoverLetterDOCX(c);
    if (fmt === "txt") exportCoverLetterTXT(c);
    incUsage("downloads");
    log({ actor: "you", action: `Downloaded cover letter (${fmt})`, category: "export", details: `${c.title}.${fmt}`, severity: "info" });
  };

  const downloadIV = (p: any, fmt: "pdf" | "docx") => {
    if (fmt === "pdf") exportInterviewPDF(p);
    if (fmt === "docx") exportInterviewDOCX(p);
    incUsage("downloads");
    log({ actor: "you", action: `Downloaded interview prep (${fmt})`, category: "export", details: `${p.role}.pdf`, severity: "info" });
  };

  return (
    <div className="space-y-6">
      <div>
        <h1 className="font-display text-2xl font-bold flex items-center gap-2"><Icon name="Download" className="w-6 h-6 text-brand" /> Downloads</h1>
        <p className="text-sm text-muted-foreground mt-1">All your generated files in one place. Free, unlimited, no watermarks.</p>
      </div>

      <Card>
        <CardHeader>
          <CardTitle className="text-lg flex items-center gap-2"><Icon name="FileText" className="w-4 h-4 text-brand" /> Resumes ({resumes.length})</CardTitle>
          <CardDescription>PDF (one A4 page guaranteed) · DOCX · TXT</CardDescription>
        </CardHeader>
        <CardContent className="space-y-2">
          {resumes.map((r) => (
            <div key={r.id} className="flex items-center justify-between gap-3 p-3 rounded-lg border border-border">
              <div className="min-w-0">
                <div className="font-semibold text-sm truncate">{r.name}_resume</div>
                <div className="text-xs text-muted-foreground">{r.headline ?? r.template}</div>
              </div>
              <div className="flex gap-1.5 shrink-0">
                <Button size="sm" variant="outline" onClick={() => downloadResume(r, "pdf")} className="gap-1.5"><Icon name="Download" className="w-3.5 h-3.5" /> PDF</Button>
                <Button size="sm" variant="outline" onClick={() => downloadResume(r, "docx")} className="gap-1.5"><Icon name="FileType" className="w-3.5 h-3.5" /> DOCX</Button>
                <Button size="sm" variant="outline" onClick={() => downloadResume(r, "txt")} className="gap-1.5"><Icon name="FileText" className="w-3.5 h-3.5" /> TXT</Button>
              </div>
            </div>
          ))}
          {resumes.length === 0 && <Empty icon="FileText" label="No resumes yet" />}
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="text-lg flex items-center gap-2"><Icon name="Mail" className="w-4 h-4 text-brand" /> Cover letters ({coverLetters.length})</CardTitle>
        </CardHeader>
        <CardContent className="space-y-2">
          {coverLetters.map((c) => (
            <div key={c.id} className="flex items-center justify-between gap-3 p-3 rounded-lg border border-border">
              <div className="min-w-0">
                <div className="font-semibold text-sm truncate">{c.title}</div>
                <div className="text-xs text-muted-foreground capitalize">{c.template} · {c.content.split(/\s+/).length} words</div>
              </div>
              <div className="flex gap-1.5 shrink-0">
                <Button size="sm" variant="outline" onClick={() => downloadCL(c, "pdf")} className="gap-1.5"><Icon name="Download" className="w-3.5 h-3.5" /> PDF</Button>
                <Button size="sm" variant="outline" onClick={() => downloadCL(c, "docx")} className="gap-1.5"><Icon name="FileType" className="w-3.5 h-3.5" /> DOCX</Button>
                <Button size="sm" variant="outline" onClick={() => downloadCL(c, "txt")} className="gap-1.5"><Icon name="FileText" className="w-3.5 h-3.5" /> TXT</Button>
              </div>
            </div>
          ))}
          {coverLetters.length === 0 && <Empty icon="Mail" label="No cover letters yet" />}
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="text-lg flex items-center gap-2"><Icon name="MessagesSquare" className="w-4 h-4 text-brand" /> Interview packages ({interviews.length})</CardTitle>
        </CardHeader>
        <CardContent className="space-y-2">
          {interviews.map((p) => (
            <div key={p.id} className="flex items-center justify-between gap-3 p-3 rounded-lg border border-border">
              <div className="min-w-0">
                <div className="font-semibold text-sm truncate">{p.role ?? "Interview prep"}{p.company ? ` — ${p.company}` : ""}</div>
                <div className="text-xs text-muted-foreground">{p.questions.length} questions</div>
              </div>
              <div className="flex gap-1.5 shrink-0">
                <Button size="sm" variant="outline" onClick={() => downloadIV(p, "pdf")} className="gap-1.5"><Icon name="Download" className="w-3.5 h-3.5" /> PDF</Button>
                <Button size="sm" variant="outline" onClick={() => downloadIV(p, "docx")} className="gap-1.5"><Icon name="FileType" className="w-3.5 h-3.5" /> DOCX</Button>
              </div>
            </div>
          ))}
          {interviews.length === 0 && <Empty icon="MessagesSquare" label="No interview packages yet" />}
        </CardContent>
      </Card>

      <Card className="gradient-brand text-white">
        <CardContent className="p-5 flex items-center justify-between gap-3">
          <div className="flex items-center gap-3">
            <Icon name="Gift" className="w-6 h-6" />
            <div>
              <div className="font-semibold">All downloads are free, forever.</div>
              <div className="text-xs text-white/80">No watermarks. No usage limits. No email required.</div>
            </div>
          </div>
          <Badge variant="gold">100% Free</Badge>
        </CardContent>
      </Card>
    </div>
  );
}

function Empty({ icon, label }: { icon: string; label: string }) {
  return (
    <div className="text-center py-8">
      <Icon name={icon} className="w-8 h-8 text-muted-foreground/40 mx-auto" />
      <p className="text-sm text-muted-foreground mt-2">{label}</p>
    </div>
  );
}

src/components/app/modules/Explainabilit:
"use client";

// ============================================================================
// Phase 8.1.5 (P6) — Explainability UI.
// Renders buildExplainability(ci) evidence tree + the Decision trace from
// buildDecisionAnalytics. Read-only; no regeneration.
// ============================================================================

import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Icon } from "@/components/shared";
import { useApp } from "@/lib/store";
import { buildDecisionAnalytics } from "@/lib/recruiter/decision-analytics";
import { ExplainabilityTree } from "@/components/explainability/ExplainabilityTree";
import { useSessionIntelligence } from "@/components/recruiter/useSessionIntelligence";

export function Explainability() {
  const setView = useApp((s) => s.setView);
  const { sessions, selectedId, setSelectedId, ci } = useSessionIntelligence();

  if (sessions.length === 0 || !ci) {
    return (
      <div className="space-y-6">
        <Header onBack={() => setView("recruiter")} />
        <Card><CardContent className="p-10 text-center text-muted-foreground">
          <Icon name="ScanSearch" className="w-10 h-10 mx-auto mb-3 opacity-50" />
          <p className="text-sm">No interview to explain yet.</p>
        </CardContent></Card>
      </div>
    );
  }

  const decision = buildDecisionAnalytics({ ci });

  return (
    <div className="space-y-6">
      <Header onBack={() => setView("recruiter")} />

      {sessions.length > 1 && (
        <Card><CardContent className="p-4 flex flex-wrap gap-2">
          {sessions.map((s) => (
            <button key={s.id} onClick={() => setSelectedId(s.id)}
              className={`px-3 py-1.5 rounded-lg border text-sm ${s.id === selectedId ? "border-brand bg-brand/10" : "border-border hover:bg-accent/50"}`}>
              {s.role ?? s.company ?? "Candidate"}
            </button>
          ))}
        </CardContent></Card>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        <Card>
          <CardHeader><CardTitle className="text-base">Evidence Tree</CardTitle><CardDescription>Why every recommendation is made.</CardDescription></CardHeader>
          <CardContent><ExplainabilityTree ci={ci} /></CardContent>
        </Card>

        <Card>
          <CardHeader><CardTitle className="text-base">Decision Trace</CardTitle><CardDescription>{decision.reason}</CardDescription></CardHeader>
          <CardContent className="space-y-2">
            {decision.trace.length === 0 && <p className="text-sm text-muted-foreground">No decision trace recorded.</p>}
            {decision.trace.map((t, i) => (
              <div key={i} className="flex items-center gap-2 text-sm">
                <span className={`w-2 h-2 rounded-full ${t.triggered ? "bg-brand" : "bg-muted-foreground/40"}`} />
                <span className="font-mono text-xs">{t.ruleId}</span>
                <span className="text-xs text-muted-foreground ml-auto uppercase">{t.status}</span>
              </div>
            ))}
            {decision.rules.length > 0 && (
              <div className="pt-2 mt-2 border-t border-border space-y-1">
                {decision.rules.map((r) => (
                  <div key={r.ruleId} className="text-xs">
                    <span className="font-medium">{r.ruleId}</span> · {r.reason}
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

function Header({ onBack }: { onBack: () => void }) {
  return (
    <div className="flex items-center gap-3">
      <Button variant="ghost" size="icon" onClick={onBack} aria-label="Back to recruiter">
        <Icon name="ArrowLeft" className="w-4 h-4" />
      </Button>
      <div>
        <h1 className="font-display text-2xl font-bold">Explainability</h1>
        <p className="text-sm text-muted-foreground">Evidence, decision trace & supporting data.</p>
      </div>
    </div>
  );
}

src/components/app/modules/FallbackChain:
"use client";

import { recordAI, setFlightScope } from "@/lib/ai/flight-recorder";
setFlightScope({ scope: "resume-optimizer", feature: "Fallback Chain", module: "src.components.app.modules.FallbackChain" });

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Badge, Icon } from "@/components/shared";
import { useApp } from "@/lib/store";
import { SEED_FALLBACK_CHAIN } from "@/lib/mock-data";
import { callAI } from "@/lib/ai";
import { toast } from "sonner";
import type { FallbackChainConfig, FallbackChainEntry, AIProvider } from "@/lib/types";

export function FallbackChain() {
  const config = useApp((s) => s.fallbackChain);
  const update = useApp((s) => s.updateFallbackChain);
  const reset = useApp((s) => s.resetFallbackChain);
  const providers = useApp((s) => s.providers);

  const [draft, setDraft] = useState<FallbackChainConfig>(config);
  const [dirty, setDirty] = useState(false);
  const [testing, setTesting] = useState(false);
  const [testResults, setTestResults] = useState<Array<{ entry: string; status: "success" | "error" | "skipped"; message: string }>>([]);

  const patch = (p: Partial<FallbackChainConfig>) => {
    setDraft((d) => ({ ...d, ...p }));
    setDirty(true);
  };

  const save = () => {
    update(draft);
    setDirty(false);
    toast.success("Fallback chain saved. All pipelines, routes, and agents will use this order.");
  };

  const discard = () => {
    setDraft(config);
    setDirty(false);
    toast.info("Changes discarded.");
  };

  const resetToDefaults = () => {
    if (!confirm("Reset fallback chain to factory defaults? This cannot be undone.")) return;
    setDraft(SEED_FALLBACK_CHAIN);
    reset();
    setDirty(false);
    toast.success("Fallback chain reset to factory defaults.");
  };

  // === Entry management ===

  const addEntry = () => {
    const firstProvider = providers[0];
    if (!firstProvider) {
      toast.error("No providers configured. Add a provider first in AI Providers settings.");
      return;
    }
    const newEntry: FallbackChainEntry = {
      id: `fb_${Date.now()}`,
      providerId: firstProvider.id,
      model: firstProvider.modelName || firstProvider.enabledModels?.[0] || "",
      enabled: true,
      temperature: 0.15,
      maxTokens: 8000,
      timeoutMs: 120000,
    };
    patch({ entries: [...draft.entries, newEntry] });
  };

  const removeEntry = (id: string) => {
    patch({ entries: draft.entries.filter((e) => e.id !== id) });
  };

  const updateEntry = (id: string, p: Partial<FallbackChainEntry>) => {
    patch({
      entries: draft.entries.map((e) => (e.id === id ? { ...e, ...p } : e)),
    });
  };

  const moveEntry = (index: number, direction: "up" | "down") => {
    const entries = [...draft.entries];
    const targetIndex = direction === "up" ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= entries.length) return;
    [entries[index], entries[targetIndex]] = [entries[targetIndex], entries[index]];
    patch({ entries });
  };

  // === Test fallback chain ===

  const testChain = async () => {
    setTesting(true);
    setTestResults([]);
    const results: Array<{ entry: string; status: "success" | "error" | "skipped"; message: string }> = [];

    for (const entry of draft.entries) {
      const provider = providers.find((p) => p.id === entry.providerId);
      if (!provider) {
        results.push({ entry: entry.id, status: "error", message: `Provider "${entry.providerId}" not found` });
        continue;
      }
      if (!entry.enabled) {
        results.push({ entry: `${provider.name} (${entry.model})`, status: "skipped", message: "Entry disabled — skipped" });
        continue;
      }

      try {
        const result = await recordAI({
          systemPrompt: "You are a test assistant. Reply with exactly: OK",
          userPrompt: "Test connection. Reply with: OK",
          maxTokens: 10,
          temperature: 0,
          taskCategory: "interactive",
          timeoutMs: 15000,
        });
        if (result.text && result.text.length > 0) {
          results.push({
            entry: `${provider.name} (${entry.model})`,
            status: "success",
            message: `Response: "${result.text.slice(0, 50)}" (${result.latencyMs}ms)`,
          });
        } else {
          results.push({
            entry: `${provider.name} (${entry.model})`,
            status: "error",
            message: "Empty response",
          });
        }
      } catch (e: any) {
        results.push({
          entry: `${provider.name} (${entry.model})`,
          status: "error",
          message: e?.message || String(e),
        });
      }
    }

    setTestResults(results);
    setTesting(false);
    const successCount = results.filter((r) => r.status === "success").length;
    toast.success(`Fallback chain test complete: ${successCount}/${results.length} providers responded.`);
  };

  // === Helper: get models for a provider ===

  const getModelsForProvider = (providerId: string): string[] => {
    const provider = providers.find((p) => p.id === providerId);
    if (!provider) return [];
    const models = provider.enabledModels || [];
    if (provider.modelName && !models.includes(provider.modelName)) {
      models.unshift(provider.modelName);
    }
    return models;
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-start justify-between flex-wrap gap-3">
        <div>
          <h1 className="font-display text-2xl font-bold flex items-center gap-2">
            <Icon name="Shuffle" className="w-6 h-6 text-brand" /> Fallback Chain
          </h1>
          <p className="text-sm text-muted-foreground mt-1">
            Configure the ordered fallback chain used by ALL pipelines, routes, and agents. When the primary provider fails (rate limit, timeout, error), the chain is traversed in order. Changes are synced to D1 and take effect immediately.
          </p>
        </div>
        <div className="flex gap-2">
          {dirty && (
            <Button variant="outline" onClick={discard} className="gap-2">
              <Icon name="RotateCcw" className="w-4 h-4" /> Discard
            </Button>
          )}
          <Button variant="outline" onClick={resetToDefaults} className="gap-2 text-destructive hover:text-destructive">
            <Icon name="Trash2" className="w-4 h-4" /> Reset to defaults
          </Button>
          <Button onClick={save} disabled={!dirty} className="bg-brand hover:bg-brand-dark text-white gap-2">
            <Icon name="Save" className="w-4 h-4" /> Save chain
          </Button>
        </div>
      </div>

      {dirty && (
        <div className="rounded-lg bg-amber-50 dark:bg-amber-950/30 border border-amber-200 dark:border-amber-800 p-3 flex items-center gap-2">
          <Icon name="AlertTriangle" className="w-4 h-4 text-amber-600" />
          <span className="text-sm text-amber-800 dark:text-amber-200">You have unsaved changes. Click "Save chain" to apply them.</span>
        </div>
      )}

      {/* Chain settings */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg flex items-center gap-2"><Icon name="Settings" className="w-4 h-4 text-brand" /> Chain Settings</CardTitle>
          <CardDescription>Global settings for the fallback chain behavior.</CardDescription>
        </CardHeader>
        <CardContent className="space-y-3">
          <div className="flex items-center justify-between">
            <div>
              <Label>Enable Fallback Chain</Label>
              <p className="text-xs text-muted-foreground">When enabled, uses the user-configured chain below. When disabled, uses legacy hardcoded logic.</p>
            </div>
            <Switch checked={draft.enabled} onCheckedChange={(v) => patch({ enabled: v })} />
          </div>
          <div className="flex items-center justify-between">
            <div>
              <Label>Respect Primary Selection</Label>
              <p className="text-xs text-muted-foreground">Always try the user's selected primary model first. Only use the chain on failure.</p>
            </div>
            <Switch checked={draft.respectPrimarySelection} onCheckedChange={(v) => patch({ respectPrimarySelection: v })} />
          </div>
          <div className="flex items-center justify-between">
            <div>
              <Label>Include Puter as Last Resort</Label>
              <p className="text-xs text-muted-foreground">Try Puter.js (browser auth) before falling back to local engine.</p>
            </div>
            <Switch checked={draft.includePuterLastResort} onCheckedChange={(v) => patch({ includePuterLastResort: v })} />
          </div>
          <div className="flex items-center justify-between">
            <div>
              <Label>Include Local Engine as Last Resort</Label>
              <p className="text-xs text-muted-foreground">Fall back to local rule-based engine if all providers fail. Always produces output.</p>
            </div>
            <Switch checked={draft.includeLocalEngineLastResort} onCheckedChange={(v) => patch({ includeLocalEngineLastResort: v })} />
          </div>
        </CardContent>
      </Card>

      {/* Fallback entries */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle className="text-lg flex items-center gap-2"><Icon name="ListOrdered" className="w-4 h-4 text-brand" /> Fallback Entries</CardTitle>
              <CardDescription>Ordered list of fallback providers. Index 0 is tried first. Drag up/down to reorder.</CardDescription>
            </div>
            <div className="flex gap-2">
              <Button variant="outline" size="sm" onClick={testChain} disabled={testing} className="gap-2">
                <Icon name="FlaskConical" className="w-4 h-4" /> {testing ? "Testing..." : "Test Chain"}
              </Button>
              <Button size="sm" onClick={addEntry} className="bg-brand hover:bg-brand-dark text-white gap-2">
                <Icon name="Plus" className="w-4 h-4" /> Add Entry
              </Button>
            </div>
          </div>
        </CardHeader>
        <CardContent className="space-y-3">
          {draft.entries.length === 0 && (
            <div className="text-center py-8 text-muted-foreground">
              <Icon name="Inbox" className="w-12 h-12 mx-auto mb-2 opacity-40" />
              <p>No fallback entries configured. Click "Add Entry" to create one.</p>
            </div>
          )}
          {draft.entries.map((entry, index) => {
            const provider = providers.find((p) => p.id === entry.providerId);
            const models = getModelsForProvider(entry.providerId);
            return (
              <div
                key={entry.id}
                className={`rounded-lg border p-4 space-y-3 ${entry.enabled ? "border-border bg-card" : "border-muted bg-muted/30 opacity-70"}`}
              >
                {/* Entry header */}
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <Badge variant={index === 0 ? "brand" : "outline"} className="text-[10px]">
                      #{index + 1}
                    </Badge>
                    <span className="font-medium text-sm">
                      {provider?.name || `Unknown (${entry.providerId})`}
                    </span>
                    {entry.enabled ? (
                      <Badge variant="success" className="text-[10px]">Active</Badge>
                    ) : (
                      <Badge variant="outline" className="text-[10px]">Disabled</Badge>
                    )}
                  </div>
                  <div className="flex items-center gap-1">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => moveEntry(index, "up")}
                      disabled={index === 0}
                      className="h-8 w-8 p-0"
                    >
                      <Icon name="ChevronUp" className="w-4 h-4" />
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => moveEntry(index, "down")}
                      disabled={index === draft.entries.length - 1}
                      className="h-8 w-8 p-0"
                    >
                      <Icon name="ChevronDown" className="w-4 h-4" />
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => removeEntry(entry.id)}
                      className="h-8 w-8 p-0 text-destructive hover:text-destructive"
                    >
                      <Icon name="Trash2" className="w-4 h-4" />
                    </Button>
                  </div>
                </div>

                {/* Entry fields */}
                <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-3">
                  <div>
                    <Label className="text-xs">Provider</Label>
                    <select
                      value={entry.providerId}
                      onChange={(e) => {
                        const newProviderId = e.target.value;
                        const newModels = getModelsForProvider(newProviderId);
                        updateEntry(entry.id, {
                          providerId: newProviderId,
                          model: newModels[0] || "",
                        });
                      }}
                      className="w-full h-9 px-3 rounded-md border border-input bg-background text-sm mt-1"
                    >
                      {providers.map((p) => (
                        <option key={p.id} value={p.id}>{p.name}</option>
                      ))}
                    </select>
                  </div>
                  <div>
                    <Label className="text-xs">Model</Label>
                    <select
                      value={entry.model}
                      onChange={(e) => updateEntry(entry.id, { model: e.target.value })}
                      className="w-full h-9 px-3 rounded-md border border-input bg-background text-sm mt-1"
                    >
                      {models.length === 0 && <option value="">(no models configured)</option>}
                      {models.map((m) => (
                        <option key={m} value={m}>{m}</option>
                      ))}
                    </select>
                  </div>
                  <div>
                    <Label className="text-xs">Temperature</Label>
                    <Input
                      type="number"
                      step={0.05}
                      min={0}
                      max={2}
                      value={entry.temperature ?? 0.15}
                      onChange={(e) => updateEntry(entry.id, { temperature: parseFloat(e.target.value) || 0 })}
                      className="mt-1"
                    />
                  </div>
                  <div>
                    <Label className="text-xs">Max Tokens</Label>
                    <Input
                      type="number"
                      step={1000}
                      min={1000}
                      max={32000}
                      value={entry.maxTokens ?? 8000}
                      onChange={(e) => updateEntry(entry.id, { maxTokens: parseInt(e.target.value) || 8000 })}
                      className="mt-1"
                    />
                  </div>
                </div>

                <div className="grid sm:grid-cols-2 gap-3">
                  <div>
                    <Label className="text-xs">Timeout (ms)</Label>
                    <Input
                      type="number"
                      step={5000}
                      min={5000}
                      max={300000}
                      value={entry.timeoutMs ?? 120000}
                      onChange={(e) => updateEntry(entry.id, { timeoutMs: parseInt(e.target.value) || 120000 })}
                      className="mt-1"
                    />
                  </div>
                  <div>
                    <Label className="text-xs">Top P (optional)</Label>
                    <Input
                      type="number"
                      step={0.05}
                      min={0}
                      max={1}
                      value={entry.topP ?? ""}
                      onChange={(e) => updateEntry(entry.id, { topP: e.target.value ? parseFloat(e.target.value) : undefined })}
                      className="mt-1"
                      placeholder="(default)"
                    />
                  </div>
                </div>

                {/* Enable toggle */}
                <div className="flex items-center justify-between pt-2 border-t">
                  <Label className="text-xs">Enabled</Label>
                  <Switch
                    checked={entry.enabled}
                    onCheckedChange={(v) => updateEntry(entry.id, { enabled: v })}
                  />
                </div>
              </div>
            );
          })}
        </CardContent>
      </Card>

      {/* Test results */}
      {testResults.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle className="text-lg flex items-center gap-2"><Icon name="FlaskConical" className="w-4 h-4 text-brand" /> Test Results</CardTitle>
            <CardDescription>Results from testing each fallback entry.</CardDescription>
          </CardHeader>
          <CardContent className="space-y-2">
            {testResults.map((result, i) => (
              <div
                key={i}
                className={`rounded-md p-3 flex items-start gap-3 ${
                  result.status === "success"
                    ? "bg-green-50 dark:bg-green-950/30 border border-green-200 dark:border-green-800"
                    : result.status === "error"
                    ? "bg-red-50 dark:bg-red-950/30 border border-red-200 dark:border-red-800"
                    : "bg-muted/50 border border-muted"
                }`}
              >
                <Icon
                  name={result.status === "success" ? "CheckCircle" : result.status === "error" ? "XCircle" : "SkipForward"}
                  className={`w-5 h-5 mt-0.5 ${
                    result.status === "success" ? "text-green-600" : result.status === "error" ? "text-red-600" : "text-muted-foreground"
                  }`}
                />
                <div className="flex-1">
                  <div className="font-medium text-sm">{result.entry}</div>
                  <div className="text-xs text-muted-foreground mt-0.5">{result.message}</div>
                </div>
                <Badge
                  variant={result.status === "success" ? "success" : result.status === "error" ? "danger" : "outline"}
                  className="text-[10px]"
                >
                  {result.status.toUpperCase()}
                </Badge>
              </div>
            ))}
          </CardContent>
        </Card>
      )}

      {/* Info card */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg flex items-center gap-2"><Icon name="Info" className="w-4 h-4 text-brand" /> How It Works</CardTitle>
        </CardHeader>
        <CardContent className="space-y-2 text-sm text-muted-foreground">
          <p>1. The user's selected primary provider is ALWAYS tried first.</p>
          <p>2. If the primary fails (rate limit, timeout, error), the chain is traversed in order (index 0 → 1 → 2 → ...).</p>
          <p>3. Each entry uses its configured model and generation parameters (temperature, maxTokens, timeout).</p>
          <p>4. Disabled entries are skipped. Entries with invalid API keys are skipped.</p>
          <p>5. If "Include Puter as Last Resort" is enabled, Puter.js is tried after all chain entries.</p>
          <p>6. If "Include Local Engine as Last Resort" is enabled, the local rule-based engine produces output if everything fails.</p>
          <p>7. Changes are synced to D1 and take effect immediately — no restart required.</p>
        </CardContent>
      </Card>

      {/* Save bar at bottom */}
      {dirty && (
        <div className="sticky bottom-4 z-10">
          <Card className="bg-brand text-white border-brand shadow-premium">
            <CardContent className="p-4 flex items-center justify-between gap-3">
              <span className="text-sm font-medium flex items-center gap-2">
                <Icon name="AlertTriangle" className="w-4 h-4" /> You have unsaved changes
              </span>
              <div className="flex gap-2">
                <Button variant="ghost" size="sm" onClick={discard} className="text-white hover:bg-white/10">Discard</Button>
                <Button size="sm" onClick={save} className="bg-white text-brand hover:bg-white/90 gap-2">
                  <Icon name="Save" className="w-4 h-4" /> Save chain
                </Button>
              </div>
            </CardContent>
          </Card>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Switch } from "@/components/ui/switch";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge, Icon } from "@/components/shared";
import { useApp } from "@/lib/store";
import { api as cloudApi } from "@/lib/cloud-api";
import { UnsavedBanner } from "./unsaved-changes";
import { toast } from "sonner";
import type { FeatureFlags as Flags } from "@/lib/types";

// Default seed values to allow "Reset to Defaults"
const DEFAULT_SEED_FLAGS: Record<keyof Flags, boolean> = {
  enableResumeBuilder: true,
  enableATSChecker: true,
  enableOptimizer: true,
  enableCoverLetter: true,
  enableInterviewPrep: true,
  enableJDScraper: true,
  enableAIFailover: true,
  enableDonations: true,
  enableAds: false,
  maintenanceMode: false,
  pipeline_websocket_enabled: false,
  enableAIGuardian: true,
  enableSelfHealing: true,
  enableModelArena: true,
  enableDurablePipeline: true,
  enableRateGovernor: true,
};

const FLAGS: { key: keyof Flags; label: string; desc: string; icon: string; severity: "safe" | "feature" | "danger" }[] = [
  { key: "enableResumeBuilder", label: "Resume Builder", desc: "Allow users to create and edit resumes.", icon: "FilePlus2", severity: "feature" },
  { key: "enableATSChecker", label: "ATS Checker", desc: "Enable the ATS scoring engine.", icon: "ScanText", severity: "feature" },
  { key: "enableOptimizer", label: "Resume Optimizer", desc: "Enable AI-powered resume optimization.", icon: "Wand2", severity: "feature" },
  { key: "enableCoverLetter", label: "Cover Letter Generator", desc: "Enable cover letter creation.", icon: "Mail", severity: "feature" },
  { key: "enableInterviewPrep", label: "Interview Prep", desc: "Enable interview question generation.", icon: "MessagesSquare", severity: "feature" },
  { key: "enableJDScraper", label: "Job Description Scraper", desc: "Allow URL-based JD scraping.", icon: "Search", severity: "feature" },
  { key: "enableAIFailover", label: "AI Failover", desc: "Automatically switch providers on failure.", icon: "RefreshCcw", severity: "safe" },
  { key: "enableDonations", label: "Donations", desc: "Show optional donation prompts.", icon: "Heart", severity: "safe" },
  { key: "enableAds", label: "Advertisements", desc: "Non-intrusive ads. Must never block features.", icon: "Megaphone", severity: "safe" },
  { key: "pipeline_websocket_enabled", label: "WebSocket Pipeline", desc: "Enable real-time WebSocket connection to the pipeline worker.", icon: "Network", severity: "safe" },
  { key: "enableAIGuardian", label: "AI Guardian Auditor", desc: "Enforce honesty via the Guardian Agent to filter fact fabrications.", icon: "ShieldAlert", severity: "safe" },
  { key: "enableSelfHealing", label: "Autonomous Self-Healing", desc: "Automatically schedule self-healing scripts to repair API nodes on failures.", icon: "Activity", severity: "safe" },
  { key: "enableModelArena", label: "Multi-Model Variant Arena", desc: "Run optimization variants in parallel on different providers and choose the highest-scoring layout/ATS output.", icon: "Swords", severity: "safe" },
  { key: "enableDurablePipeline", label: "Durable Pipeline Queue", desc: "Run optimizer stages as durable D1 jobs (resumable, retry with backoff on rate limits, stage checkpoints). Falls back to the inline pipeline on any failure.", icon: "DatabaseZap", severity: "safe" },
  { key: "enableRateGovernor", label: "Rate Governor", desc: "Proactively pace AI calls per provider (token bucket + Retry-After) so parallel agents avoid hitting provider 429 limits.", icon: "Gauge", severity: "safe" },
  { key: "maintenanceMode", label: "Maintenance Mode", desc: "Take the entire app offline for users.", icon: "Wrench", severity: "danger" },
];

export function FeatureFlags() {
  const flags = useApp((s) => s.flags);
  const updateFlag = useApp((s) => s.updateFlag);
  const log = useApp((s) => s.log);

  const [search, setSearch] = useState("");
  const [filter, setFilter] = useState<"all" | "feature" | "safe" | "danger">("all");
  const [savingAll, setSavingAll] = useState(false);
  // Unsaved-changes tracking (same contract as the other Super Admin panels):
  // toggles/reset mark the panel dirty until the explicit save-all confirms
  // every flag reached D1. Cleared only on a fully successful save.
  const [dirty, setDirty] = useState(false);
  const toggleFlag = (key: keyof Flags, val: boolean) => {
    updateFlag(key, val);
    setDirty(true);
  };

  const filteredFlags = FLAGS.filter((f) => {
    const matchesSearch = f.label.toLowerCase().includes(search.toLowerCase()) || 
                          f.desc.toLowerCase().includes(search.toLowerCase());
    const matchesFilter = filter === "all" || f.severity === filter;
    return matchesSearch && matchesFilter;
  });

  // Explicit Save button — persists EVERY flag to D1 (PUT /api/settings/flags/:key)
  // so the whole flag set is guaranteed refresh-proof even if an individual
  // fire-and-forget toggle sync failed earlier. Toggles still apply instantly;
  // this button is the authoritative "commit to server" affordance.
  const handleSaveAll = async () => {
    setSavingAll(true);
    try {
      const entries = Object.entries(flags) as [keyof Flags, boolean][];
      const results = await Promise.allSettled(entries.map(([k, v]) => cloudApi.updateFlag(k, v)));
      const failed = results.filter((r) => r.status === "rejected").length;
      if (failed === 0) {
        setDirty(false);
        log({ actor: "you", action: "All feature flags saved to cloud", category: "admin", details: `${entries.length} flags persisted`, severity: "info" });
        toast.success("All feature flags saved — they survive refresh now.");
      } else {
        log({ actor: "you", action: "Feature flag save partially failed", category: "admin", details: `${failed}/${entries.length} failed`, severity: "warning" });
        toast.error(`${failed} flag(s) failed to save — check your connection and retry.`);
      }
    } finally {
      setSavingAll(false);
    }
  };

  const handleResetDefaults = () => {
    Object.entries(DEFAULT_SEED_FLAGS).forEach(([key, val]) => {
      toggleFlag(key as keyof Flags, val);
    });
    log({ actor: "you", action: "Reset all flags to defaults", category: "admin", details: "All flags", severity: "warning" });
    toast.success("All feature flags reset to system defaults.");
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div>
          <h1 className="font-display text-2xl font-bold flex items-center gap-2"><Icon name="Flag" className="w-6 h-6 text-brand" /> Feature Flags</h1>
          <p className="text-sm text-muted-foreground mt-1">Toggle features on or off instantly, without redeploying.</p>
        </div>
        <div className="flex gap-2">
          <Button onClick={handleSaveAll} disabled={savingAll} size="sm" className="gap-1.5 text-xs bg-brand hover:bg-brand-dark text-white">
            <Icon name="Save" className="w-3.5 h-3.5" />
            {savingAll ? "Saving…" : "Save All Flags"}
          </Button>
          <Button onClick={handleResetDefaults} variant="outline" size="sm" className="gap-1.5 text-xs">
            <Icon name="RotateCcw" className="w-3.5 h-3.5" />
            Reset to Defaults
          </Button>
        </div>
      </div>

      {dirty && (
        <UnsavedBanner saveLabel="Save All Flags">
          You have unsaved flags. Click &quot;Save All Flags&quot; to confirm them on the server.
        </UnsavedBanner>
      )}

      {/* Search and Filters */}
      <div className="flex flex-wrap gap-2 items-center">
        <Input
          placeholder="Search flags..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="max-w-xs h-9 text-xs"
        />
        <div className="flex gap-1.5 border border-border rounded-lg p-0.5 bg-secondary/20">
          {(["all", "feature", "safe", "danger"] as const).map((t) => (
            <Button
              key={t}
              onClick={() => setFilter(t)}
              variant={filter === t ? "secondary" : "ghost"}
              className="h-7 px-2.5 text-[10px] uppercase font-semibold tracking-wider rounded-md"
            >
              {t}
            </Button>
          ))}
        </div>
      </div>

      <div className="grid sm:grid-cols-2 gap-3">
        {filteredFlags.map((f) => {
          const on = flags[f.key];
          return (
            <Card key={f.key} className={`${on ? "" : "opacity-75"} border border-border/80 transition-all hover:border-brand/35`}>
              <CardContent className="p-4 flex items-start gap-3">
                <div className={`w-10 h-10 rounded-lg flex items-center justify-center shrink-0 ${f.severity === "danger" ? "bg-red-100 text-red-700 dark:bg-red-400/10 dark:text-red-300" : f.severity === "feature" ? "bg-brand-light text-brand dark:bg-brand/15" : "bg-amber-100 text-amber-700 dark:bg-amber-400/10 dark:text-amber-300"}`}>
                  <Icon name={f.icon} className="w-5 h-5" />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <div className="font-semibold text-sm">{f.label}</div>
                    {f.severity === "danger" && <Badge variant="danger" className="text-[10px]">Danger</Badge>}
                  </div>
                  <div className="text-xs text-muted-foreground mt-0.5">{f.desc}</div>
                </div>
                <Switch
                  checked={!!on}
                  onCheckedChange={(v) => {
                    toggleFlag(f.key, v);
                    log({ actor: "you", action: `Flag ${f.key} ${v ? "ON" : "OFF"}`, category: "admin", details: f.label, severity: v ? "info" : "warning" });
                    toast.success(`${f.label} ${v ? "enabled" : "disabled"}.`);
                  }}
                />
              </CardContent>
            </Card>
          );
        })}
        {filteredFlags.length === 0 && (
          <div className="col-span-full text-center py-10 text-xs text-muted-foreground">
            No feature flags found matching the filters.
          </div>
        )}
      </div>

      <Card className="bg-amber-100/40 dark:bg-amber-400/5 border-amber-300/50">
        <CardContent className="p-4 flex items-start gap-3">
          <Icon name="AlertTriangle" className="w-5 h-5 text-amber-600 shrink-0 mt-0.5" />
          <div className="text-sm">
            <div className="font-semibold">Use with care</div>
            <div className="text-xs text-muted-foreground mt-1">Disabling core features will immediately hide them from all users. Maintenance mode blocks all non-admin access.</div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

