"use client";

// ============================================================================
// Phase 8.1.5 (P4) — Flight Recorder Console.
//
// Lists in-session FlightRecords (captured via the AfterPersist sink in
// store.ts), filterable/searchable with the EXISTING pure helper
// matchesFlightFilter. Detail panel replays timeline + prompt versions +
// provider/model/latency/cost/tokens + reflection/qa/validation/decision.
// PRESENTATION ONLY — no AI, no recomputation.
// ============================================================================

import { useMemo, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge, Icon } from "@/components/shared";
import { useApp } from "@/lib/store";
import { matchesFlightFilter, type FlightRecord, type FlightFilter } from "@/lib/ai/flight-recorder";
import { FlightTimeline } from "@/components/flight/FlightTimeline";

export function FlightRecorderConsole() {
  const flightRecords = useApp((s) => s.flightRecords);
  const clearFlightLog = useApp((s) => s.clearFlightLog);

  const [query, setQuery] = useState("");
  const [providerFilter, setProviderFilter] = useState("");
  const [onlyErrors, setOnlyErrors] = useState(false);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const filtered = useMemo(() => {
    const f: FlightFilter = {};
    if (providerFilter) f.provider = providerFilter;
    if (onlyErrors) f.hasErrors = true;
    return (flightRecords || [])
      .filter((r) => r && matchesFlightFilter(r, f))
      .filter((r) => {
        if (!query) return true;
        const q = query.toLowerCase();
        return (
          (r.executionId || "").toLowerCase().includes(q) ||
          (r.feature ?? "").toLowerCase().includes(q) ||
          (r.module ?? "").toLowerCase().includes(q) ||
          (r.provider || "").toLowerCase().includes(q) ||
          (r.model || "").toLowerCase().includes(q) ||
          (r.scope || "").toLowerCase().includes(q)
        );
      });
  }, [flightRecords, query, providerFilter, onlyErrors]);

  const selected = filtered.find((r) => r.executionId === selectedId) ?? filtered[0] ?? null;
  const providers = useMemo(
    () => Array.from(new Set((flightRecords || []).map((r) => r.provider).filter(Boolean))).sort(),
    [flightRecords]
  );

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between gap-3 flex-wrap">
        <div>
          <h1 className="font-display text-2xl font-bold">Flight Recorder Console</h1>
          <p className="text-sm text-muted-foreground">{(flightRecords || []).length} executions captured this session.</p>
        </div>
        <Button variant="outline" size="sm" onClick={clearFlightLog} disabled={!(flightRecords || []).length}>
          <Icon name="Trash2" className="w-4 h-4 mr-2" /> Clear log
        </Button>
      </div>

      {/* Filters */}
      <Card>
        <CardContent className="p-4 flex flex-wrap items-center gap-3">
          <div className="relative flex-1 min-w-[200px]">
            <Icon name="Search" className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
            <Input
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search execution id / feature / provider / scope…"
              className="pl-9"
              aria-label="Search executions"
            />
          </div>
          <select
            value={providerFilter}
            onChange={(e) => setProviderFilter(e.target.value)}
            className="h-9 rounded-md border border-border bg-card px-3 text-sm"
            aria-label="Filter by provider"
          >
            <option value="">All providers</option>
            {providers.map((p) => <option key={p} value={p}>{p}</option>)}
          </select>
          <label className="flex items-center gap-2 text-sm">
            <input type="checkbox" checked={onlyErrors} onChange={(e) => setOnlyErrors(e.target.checked)} />
            Errors only
          </label>
        </CardContent>
      </Card>

      {(flightRecords || []).length === 0 ? (
        <Card>
          <CardContent className="p-10 text-center text-muted-foreground">
            <Icon name="Plane" className="w-10 h-10 mx-auto mb-3 opacity-50" />
            <p className="text-sm">No executions captured yet.</p>
            <p className="text-xs mt-1">Run any AI feature (interview, optimizer, etc.) and its Flight Record will appear here.</p>
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
          {/* List */}
          <Card className="lg:col-span-1">
            <CardHeader><CardTitle className="text-base">Executions ({filtered.length})</CardTitle></CardHeader>
            <CardContent className="space-y-1.5 max-h-[560px] overflow-auto">
              {filtered.map((r) => {
                const active = r.executionId === selected?.executionId;
                return (
                  <button
                    key={r.executionId}
                    onClick={() => setSelectedId(r.executionId)}
                    className={`w-full text-left p-2.5 rounded-lg border text-sm transition-colors ${
                      active ? "border-brand bg-brand/10" : "border-border hover:bg-accent/50"
                    }`}
                  >
                    <div className="flex items-center justify-between gap-2">
                      <span className="font-medium truncate">{r.feature ?? r.scope}</span>
                      {(r.errors?.length ?? 0) > 0 && <Badge className="bg-red-500/10 text-red-500 border-red-500/40">err</Badge>}
                    </div>
                    <div className="text-xs text-muted-foreground truncate">{r.provider} · {r.model} · {r.latencyMs ?? 0}ms</div>
                  </button>
                );
              })}
            </CardContent>
          </Card>

          {/* Detail */}
          <div className="lg:col-span-2 space-y-4">
            {selected && <FlightDetail record={selected} />}
          </div>
        </div>
      )}
    </div>
  );
}

function FlightDetail({ record: r }: { record: FlightRecord }) {
  return (
    <>
      <Card>
        <CardHeader>
          <CardTitle className="text-base">{r.feature ?? r.scope}</CardTitle>
          <CardDescription className="font-mono text-xs">{r.executionId}</CardDescription>
        </CardHeader>
        <CardContent className="grid grid-cols-2 sm:grid-cols-4 gap-3">
          <Stat label="Provider" value={r.provider || "unknown"} />
          <Stat label="Model" value={r.model || "unknown"} />
          <Stat label="Latency" value={`${r.latencyMs ?? 0}ms`} />
          <Stat label="Duration" value={`${r.durationMs ?? 0}ms`} />
          <Stat label="Tokens" value={String(r.tokenUsage ?? 0)} />
          <Stat label="Cost" value={`$${(r.cost?.estimatedCost ?? 0).toFixed(4)}`} />
          <Stat label="Prompt ver" value={r.promptVersion || "1.0"} />
          <Stat label="Retries" value={String(r.retryCount ?? 0)} />
        </CardContent>
      </Card>

      <Card>
        <CardHeader><CardTitle className="text-base">Execution Timeline</CardTitle></CardHeader>
        <CardContent><FlightTimeline spans={r.timeline || []} /></CardContent>
      </Card>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <EngineCard title="Reflection" present={!!r.reflection} rows={r.reflection && [
          ["Outcome", r.reflection.outcome || "unknown"], ["Score", String(r.reflection.score ?? 0)],
          ["Confidence", String(r.reflection.confidence ?? 0)], ["Retry", String(r.reflection.retryRecommended ?? false)],
        ]} />
        <EngineCard title="QA" present={!!r.qa} rows={r.qa && [
          ["Outcome", r.qa.outcome || "unknown"], ["Score", String(r.qa.score ?? 0)],
          ["Findings", String(r.qa.findings?.length ?? 0)], ["Fail rec", String(r.qa.failRecommended ?? false)],
        ]} />
        <EngineCard title="Validation" present={!!r.validation} rows={r.validation && [
          ["Outcome", r.validation.outcome || "unknown"], ["Score", String(r.validation.score ?? 0)],
          ["Critical", String(r.validation.criticalFailures ?? 0)], ["Profile", r.validation.profile || "none"],
        ]} />
        <EngineCard title="Decision" present={!!r.decision} rows={r.decision && [
          ["Status", r.decision.status || "unknown"], ["Confidence", String(r.decision.confidence ?? 0)],
          ["Rules", String(r.decision.rules?.length ?? 0)], ["Reason", r.decision.reason || "none"],
        ]} />
      </div>

      {(((r.errors?.length ?? 0) > 0) || ((r.warnings?.length ?? 0) > 0)) && (
        <Card>
          <CardHeader><CardTitle className="text-base">Diagnostics</CardTitle></CardHeader>
          <CardContent className="space-y-1 text-sm">
            {(r.errors || []).map((e, i) => <div key={`e${i}`} className="text-red-500">✕ {e}</div>)}
            {(r.warnings || []).map((w, i) => <div key={`w${i}`} className="text-amber-500">⚠ {w}</div>)}
          </CardContent>
        </Card>
      )}
    </>
  );
}

function Stat({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-lg border border-border bg-card p-2.5">
      <div className="text-xs text-muted-foreground">{label}</div>
      <div className="text-sm font-medium truncate">{value}</div>
    </div>
  );
}

function EngineCard({ title, present, rows }: { title: string; present: boolean; rows?: [string, string][] | null | false }) {
  return (
    <Card>
      <CardHeader><CardTitle className="text-sm flex items-center gap-2">
        <span className={`w-2 h-2 rounded-full ${present ? "bg-emerald-500" : "bg-muted-foreground/40"}`} /> {title}
      </CardTitle></CardHeader>
      <CardContent>
        {present && rows ? (
          <dl className="grid grid-cols-2 gap-x-3 gap-y-1 text-xs">
            {rows.map(([k, v]) => (
              <div key={k} className="contents">
                <dt className="text-muted-foreground">{k}</dt>
                <dd className="font-medium truncate">{v}</dd>
              </div>
            ))}
          </dl>
        ) : (
          <p className="text-xs text-muted-foreground">Not run for this execution.</p>
        )}
      </CardContent>
    </Card>
  );
}

src/components/app/modules/GuardianScore:
"use client";

import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Badge, Icon, ScoreRing } from "@/components/shared";

/**
 * GuardianScoreCard — displays the Structure Guardian validation result.
 *
 * Shows:
 *   - Score ring (0-100 with color coding: red < 60, yellow < 80, green >= 80)
 *   - Status badge: PASS / REQUIRES_MANUAL_REVIEW / BLOCKED
 *   - List of checks that passed/failed
 */

export interface GuardianCheck {
  name: string;
  passed: boolean;
  detail?: string;
}

export interface GuardianScoreCardProps {
  /** Guardian validation score (0-100) */
  score: number;
  /** Overall guardian status */
  status: "PASS" | "REQUIRES_MANUAL_REVIEW" | "BLOCKED";
  /** Individual checks from the guardian */
  checks: GuardianCheck[];
}

export function GuardianScoreCard({ score, status, checks }: GuardianScoreCardProps) {
  const passedCount = checks.filter((c) => c.passed).length;
  const failedCount = checks.length - passedCount;

  const statusVariant =
    status === "PASS" ? "success" :
    status === "REQUIRES_MANUAL_REVIEW" ? "warning" : "danger";

  return (
    <Card>
      <CardHeader className="pb-3">
        <CardTitle className="text-sm flex items-center gap-2">
          <Icon name="Shield" className="w-4 h-4 text-brand" />
          Structure Guardian
          <Badge variant={statusVariant} className="ml-auto text-[10px]">
            {status === "PASS" ? "PASS" :
             status === "REQUIRES_MANUAL_REVIEW" ? "REQUIRES REVIEW" : "BLOCKED"}
          </Badge>
        </CardTitle>
        <CardDescription className="text-xs">
          Validates final resume for corruption, duplicates, and malformed fragments
        </CardDescription>
      </CardHeader>
      <CardContent className="pt-0 space-y-4">
        <div className="flex items-center justify-center">
          <ScoreRing value={score} size={100} label="Guardian Score" />
        </div>

        {/* Summary stats */}
        <div className="grid grid-cols-2 gap-2 text-xs text-center">
          <div className="rounded-lg bg-emerald-50 dark:bg-emerald-950/20 p-2">
            <div className="text-lg font-bold text-emerald-600">{passedCount}</div>
            <div className="text-muted-foreground">Passed</div>
          </div>
          <div className="rounded-lg bg-red-50 dark:bg-red-950/20 p-2">
            <div className="text-lg font-bold text-red-600">{failedCount}</div>
            <div className="text-muted-foreground">Failed</div>
          </div>
        </div>

        {/* Check list */}
        {checks.length > 0 && (
          <div className="space-y-1.5">
            {checks.map((check) => (
              <div key={check.name} className="flex items-center gap-2 text-xs">
                <Icon
                  name={check.passed ? "CheckCircle2" : "AlertCircle"}
                  className={`w-3.5 h-3.5 shrink-0 ${check.passed ? "text-emerald-600" : "text-amber-600"}`}
                />
                <span className="font-medium">{check.name}</span>
                {check.detail && (
                  <span className="text-muted-foreground ml-auto text-[10px]">{check.detail}</span>
                )}
              </div>
            ))}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

