"use client";

import { useState, useCallback, useMemo } from "react";
import { motion } from "framer-motion";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Badge, Icon, ScoreRing } from "@/components/shared";
import { useApp, uid } from "@/lib/store";
import { detectIndustry, INDUSTRY_PROFILES } from "@/lib/industry-ats";
import { exportInterviewPDF, exportInterviewDOCX, exportInterviewJSON, exportInterviewMarkdown } from "@/lib/exporter";
import { InterviewSession, InterviewSkeleton } from "@/components/interview/InterviewSession";
import { VideoInterviewSession } from "@/components/interview/VideoInterviewSession";
import { VoiceInterviewSession } from "@/components/interview/VoiceInterviewSession";
import {
  generateInterviewQuestions,
  toInterviewPackage,
  buildInterviewMatchScore,
  type GeneratedPackage,
  type InterviewMatchScore,
} from "@/lib/interview/ai";
import { INTERVIEW_PERSONAS } from "@/lib/interview/personas";
import { setFlightRecordSink } from "@/lib/ai/flight-recorder";
import { toast } from "sonner";
import type { InterviewPackage, InterviewQuestion } from "@/lib/types";
import type { InterviewSessionRecord } from "@/hooks/interview/types";
import type { InterviewFinalReport } from "@/lib/interview/ai";
import { AviationAcademy } from "@/components/interview/AviationAcademy";
import { DeviceCheck } from "@/components/interview/DeviceCheck";

const CATEGORIES = [
  { id: "technical", label: "Technical", icon: "Code2", color: "#1154A3" },
  { id: "behavioral", label: "Behavioral", icon: "Users", color: "#F59E0B" },
  { id: "situational", label: "Situational", icon: "GitBranch", color: "#10B981" },
  { id: "hr", label: "HR", icon: "UserCheck", color: "#8B5CF6" },
  { id: "company", label: "Company-specific", icon: "Building2", color: "#EC4899" },
] as const;

const SUB_TYPE_LABELS: Record<string, string> = {
  "hr": "HR",
  "behavioral": "Behavioral",
  "star": "STAR",
  "technical": "Technical",
  "situational": "Situational",
  "company-fit": "Company Fit",
  "leadership": "Leadership",
  "problem-solving": "Problem Solving",
  "resume-specific": "Resume-Specific",
  "jd-specific": "JD-Specific",
};

const DIFFICULTY_COLORS: Record<string, string> = { easy: "#10B981", medium: "#F59E0B", hard: "#DC2626", adaptive: "#3B82F6" };

export function Interview() {
  const interviews = useApp((s) => s.interviews);
  const resumes = useApp((s) => s.resumes);
  const jds = useApp((s) => s.jobDescriptions);
  const atsReports = useApp((s) => s.atsReports);
  const reviewReports = useApp((s) => s.reviewReports);
  const interviewSessions = useApp((s) => s.interviewSessions);
  const addInterview = useApp((s) => s.addInterview);
  const removeInterview = useApp((s) => s.removeInterview);
  const addInterviewSession = useApp((s) => s.addInterviewSession);
  const removeInterviewSession = useApp((s) => s.removeInterviewSession);
  const incUsage = useApp((s) => s.incUsage);
  const log = useApp((s) => s.log);
  const setView = useApp((s) => s.setView);

  const [generating, setGenerating] = useState(false);
  const [expanded, setExpanded] = useState<string | null>(null);
  const [practiceSession, setPracticeSession] = useState<InterviewPackage | null>(null);
  // `simSession` is the package currently being interviewed in the Sonru simulator.
  // `simMode` distinguishes between video (camera+mic) and voice (mic-only) — both
  // reuse the same package but render a different session component.
  const [simSession, setSimSession] = useState<InterviewPackage | null>(null);
  const [simMode, setSimMode] = useState<"video" | "voice">("video");
  const [videoGenerated, setVideoGenerated] = useState<GeneratedPackage | null>(null);
  const [selectedResumeId, setSelectedResumeId] = useState<string>(resumes[0]?.id ?? "");
  const [selectedJdId, setSelectedJdId] = useState<string>(jds[0]?.id ?? "");
  const [selectedPersonaIds, setSelectedPersonaIds] = useState<string[]>(["hr", "hiring-manager", "cabin-crew-manager", "chief-purser", "safety-trainer", "panel"]);
  const [activeSubTab, setActiveSubTab] = useState<"standard" | "aviation-academy">("standard");
  const [deviceCheckOpen, setDeviceCheckOpen] = useState(false);
  const [completedQuestions, setCompletedQuestions] = useState<Set<string>>(new Set());
  const [readinessData, setReadinessData] = useState<{ score: number; strengths: string[]; weaknesses: string[]; topicsToReview: string[]; skillsToReview: string[]; focusAreas: string[] } | null>(null);

  // === Auto-detect context ===
  const selectedResume = resumes.find((r) => r.id === selectedResumeId) ?? resumes[0] ?? null;
  const selectedJd = jds.find((j) => j.id === selectedJdId) ?? jds[0] ?? null;

  const industryDetection = useMemo(() => {
    if (!selectedJd) return null;
    const jdText = selectedJd.rawText ?? selectedJd.keywords.join(" ");
    const resumeText = `${selectedResume?.name ?? ""} ${selectedResume?.headline ?? ""} ${selectedResume?.summary ?? ""} ${selectedResume?.experience.map((e) => e.title + " " + e.company).join(" ")}`;
    return detectIndustry(jdText, resumeText);
  }, [selectedJd, selectedResume]);

  const industryProfile = industryDetection ? INDUSTRY_PROFILES[industryDetection.industryId] : null;

  // === Generate interview prep package ===
  const generate = async () => {
    if (!selectedResume) {
      toast.error("Please upload or create a resume first.");
      return;
    }
    if (!selectedJd) {
      toast.error("Please add a job description first.");
      return;
    }

    setGenerating(true);
    setReadinessData(null);
    try {
      // Find the ATS analysis + review report that match this resume+JD pair,
      // so the generator can adapt questions to missing skills & competencies.
      const atsReport = atsReports.find((a) => a.resumeId === selectedResume.id);
      const reviewReport = reviewReports.find((r) => r.resumeId === selectedResume.id && (!r.jdId || r.jdId === selectedJd.id)) ?? reviewReports.find((r) => r.resumeId === selectedResume.id);

      const generated = await generateInterviewQuestions({
        resume: selectedResume,
        jd: selectedJd,
        atsReport,
        reviewReport,
        personaIds: selectedPersonaIds,
        difficultyBias: "adaptive",
      });

      const pkg = toInterviewPackage(generated, {
        resume: selectedResume,
        jd: selectedJd,
        atsReport,
        reviewReport,
        personaIds: selectedPersonaIds,
        difficultyBias: "adaptive",
      });

      const questions: InterviewQuestion[] = generated.questions;
      if (!questions.length) throw new Error("AI returned no questions.");

      addInterview(pkg);
      setReadinessData({
        score: generated.readinessScore ?? 75,
        strengths: generated.strengths ?? [],
        weaknesses: generated.weaknesses ?? [],
        topicsToReview: generated.topicsToReview ?? [],
        skillsToReview: generated.skillsToReview ?? [],
        focusAreas: generated.focusAreas ?? [],
      });
      setCompletedQuestions(new Set());
      incUsage("interviewPreps");
      log({
        actor: "you",
        action: "Interview prep generated (dynamic, adaptive)",
        category: "ai",
        details: `${questions.length} questions · ${industryProfile?.label ?? "Generic"} · readiness ${generated.readinessScore ?? 75}/100` + (generated.adaptationNote ? ` · ${generated.adaptationNote}` : ""),
        severity: "info",
      });
      toast.success(`${questions.length} questions generated — readiness ${generated.readinessScore ?? 75}/100`);
    } catch (e: any) {
      toast.error(e?.message || "Generation failed.");
    } finally {
      setGenerating(false);
    }
  };

  const toggleCompleted = (qId: string) => {
    setCompletedQuestions((prev) => {
      const next = new Set(prev);
      if (next.has(qId)) next.delete(qId);
      else next.add(qId);
      return next;
    });
  };

  const grouped = (pkg: InterviewPackage) => {
    const g: Record<string, InterviewQuestion[]> = {};
    for (const q of (pkg.questions ?? [])) (g[q.category] ||= []).push(q);
    return g;
  };

  const latestPkg = interviews[0] ?? null;
  const latestQuestions = latestPkg?.questions ?? [];
  const prepPercent = latestQuestions.length > 0
    ? Math.round((completedQuestions.size / latestQuestions.length) * 100)
    : 0;

  // === Match score (Resume ↔ JD) — surfaced on the Interview Prep page ===
  // Reuses the existing ATS report + review report when available. Pure function,
  // no AI call. Memoized on the resume/JD ids to avoid recompute on every render.
  const matchScore: InterviewMatchScore | null = useMemo(() => {
    if (!selectedResume) return null;
    const ats = atsReports.find((a) => a.resumeId === selectedResume.id);
    const rev = reviewReports.find((r) => r.resumeId === selectedResume.id && (!r.jdId || r.jdId === selectedJd?.id)) ?? reviewReports.find((r) => r.resumeId === selectedResume.id);
    return buildInterviewMatchScore(selectedResume, selectedJd ?? null, ats ?? null, rev ?? null);
  }, [selectedResume, selectedJd, atsReports, reviewReports]);

  // === Sonru simulator (video OR voice) ===
  if (simSession) {
    const handleSimComplete = (
      sessionId: string,
      records: InterviewSessionRecord["recordings"],
      finalReport?: InterviewFinalReport
    ) => {
      const rec: InterviewSessionRecord = {
        id: sessionId,
        resumeId: simSession.resumeId,
        jdId: simSession.jdId,
        company: simSession.company,
        role: simSession.role,
        status: "completed",
        recordings: records,
        startedAt: new Date().toISOString(),
        completedAt: new Date().toISOString(),
        // Persist the final report blob alongside the session metadata so the
        // "Previous Video Interviews" history can surface hiring recommendations.
        reportRef: finalReport ? JSON.stringify(finalReport).slice(0, 4000) : undefined,
      };
      addInterviewSession(rec);
      const verdictLabel = finalReport?.verdictLabel ?? "";
      toast.success(
        `${simMode === "video" ? "Video" : "Voice"} interview saved — ${records.length} recordings${verdictLabel ? ` · ${verdictLabel}` : ""}.`
      );
    };
    if (simMode === "voice") {
      return (
        <VoiceInterviewSession
          pkg={simSession}
          resume={selectedResume ?? undefined}
          jd={selectedJd ?? undefined}
          generated={videoGenerated ?? undefined}
          onClose={() => { setSimSession(null); setVideoGenerated(null); }}
          onComplete={handleSimComplete}
        />
      );
    }
    return (
      <VideoInterviewSession
        pkg={simSession}
        resume={selectedResume ?? undefined}
        jd={selectedJd ?? undefined}
        generated={videoGenerated ?? undefined}
        onClose={() => { setSimSession(null); setVideoGenerated(null); }}
        onComplete={handleSimComplete}
      />
    );
  }

  // === Practice session mode (text/voice) ===
  if (practiceSession) {
    return <InterviewSession pkg={practiceSession} onClose={() => setPracticeSession(null)} />;
  }

  // === No resume state ===
  if (resumes.length === 0) {
    return (
      <div className="space-y-6">
        <div>
          <h1 className="font-display text-2xl font-bold flex items-center gap-2"><Icon name="MessagesSquare" className="w-6 h-6 text-brand" /> Interview Prep</h1>
          <p className="text-sm text-muted-foreground mt-1">Dynamic, context-aware interview preparation tailored to your resume and job description.</p>
        </div>
        <Card>
          <CardContent className="py-12 text-center">
            <Icon name="FileText" className="w-10 h-10 text-muted-foreground/40 mx-auto" />
            <h3 className="mt-3 font-semibold">Optimize a resume first</h3>
            <p className="text-sm text-muted-foreground mt-1 max-w-md mx-auto">Upload and optimize a resume to generate personalized interview preparation with tailored questions and answers.</p>
            <Button onClick={() => setView("optimizer")} className="bg-brand hover:bg-brand-dark text-white gap-2 mt-4">
              <Icon name="Wand2" className="w-4 h-4" /> Go to Resume Optimizer
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-center justify-between gap-3 border-b border-border pb-4">
        <div>
          <h1 className="font-display text-2xl font-bold flex items-center gap-2"><Icon name="MessagesSquare" className="w-6 h-6 text-brand" /> Interview Prep</h1>
          <p className="text-sm text-muted-foreground mt-1">Dynamic, context-aware interview preparation tailored to your resume and job description.</p>
        </div>
        
        <div className="flex items-center gap-2">
          <div className="flex bg-secondary/60 rounded-lg p-0.5 border border-border">
            <button
              onClick={() => setActiveSubTab("standard")}
              className={`px-3 py-1.5 text-xs font-medium rounded-md transition-all ${
                activeSubTab === "standard"
                  ? "bg-background text-foreground shadow-sm font-semibold"
                  : "text-muted-foreground hover:text-foreground"
              }`}
            >
              Standard Prep
            </button>
            <button
              onClick={() => setActiveSubTab("aviation-academy")}
              className={`px-3 py-1.5 text-xs font-medium rounded-md transition-all flex items-center gap-1.5 ${
                activeSubTab === "aviation-academy"
                  ? "bg-background text-brand shadow-sm font-semibold"
                  : "text-muted-foreground hover:text-foreground"
              }`}
            >
              <Icon name="Plane" className="w-3.5 h-3.5 text-brand" /> Aviation Academy
            </button>
          </div>

          {activeSubTab === "standard" && (
            <div className="flex items-center gap-2 flex-wrap">
              <Button onClick={generate} disabled={generating || !selectedResume || !selectedJd} className="bg-brand hover:bg-brand-dark text-white gap-2">
                {generating ? <Icon name="Loader2" className="w-4 h-4 animate-spin" /> : <Icon name="Sparkles" className="w-4 h-4" />}
                {generating ? "Generating…" : "Generate package"}
              </Button>

              {/* Mode selector: Video (Sonru-style camera+mic) vs Voice (mic-only). */}
              <div className="flex bg-secondary/60 rounded-lg p-0.5 border border-border" role="group" aria-label="Simulator mode">
                <button
                  type="button"
                  onClick={() => setSimMode("video")}
                  className={`px-2.5 py-1 text-xs font-medium rounded-md transition-all flex items-center gap-1 ${
                    simMode === "video" ? "bg-background text-brand shadow-sm font-semibold" : "text-muted-foreground hover:text-foreground"
                  }`}
                  title="Sonru-style video interview (camera + microphone)"
                >
                  <Icon name="Video" className="w-3.5 h-3.5" /> Video
                </button>
                <button
                  type="button"
                  onClick={() => setSimMode("voice")}
                  className={`px-2.5 py-1 text-xs font-medium rounded-md transition-all flex items-center gap-1 ${
                    simMode === "voice" ? "bg-background text-brand shadow-sm font-semibold" : "text-muted-foreground hover:text-foreground"
                  }`}
                  title="Sonru-style voice-only interview (microphone)"
                >
                  <Icon name="Mic" className="w-3.5 h-3.5" /> Voice
                </button>
              </div>

              <Button
                variant="outline"
                onClick={() => {
                  if (!latestPkg) {
                    toast.error("Generate a package first, then start the simulator.");
                    return;
                  }
                  setVideoGenerated(null);
                  setSimSession(latestPkg);
                }}
                disabled={!latestPkg}
                className="gap-2 border-brand text-brand hover:bg-brand-light"
                title={`Start a Sonru-style ${simMode} interview`}
              >
                <Icon name={simMode === "video" ? "Video" : "Mic"} className="w-4 h-4" />
                Start {simMode === "video" ? "Video" : "Voice"} Interview
              </Button>
              <Dialog open={deviceCheckOpen} onOpenChange={setDeviceCheckOpen}>
                <Button
                  variant="ghost"
                  size="sm"
                  className="gap-1.5"
                  title="Check your camera & microphone"
                  onClick={() => setDeviceCheckOpen(true)}
                >
                  <Icon name="Camera" className="w-4 h-4" /> Device Check
                </Button>
                <DialogContent className="max-w-2xl">
                  <DialogHeader>
                    <DialogTitle>Device Check</DialogTitle>
                    <DialogDescription>Verify your camera and microphone before starting an interview.</DialogDescription>
                  </DialogHeader>
                  <DeviceCheck />
                </DialogContent>
              </Dialog>
            </div>
          )}
        </div>
      </div>

      {activeSubTab === "aviation-academy" ? (
        <AviationAcademy jobDescription={selectedJd} />
      ) : (
        <>

      {/* === Context selection === */}
      <Card>
        <CardContent className="p-4 space-y-3">
          <div className="grid sm:grid-cols-3 gap-3">
            <div className="space-y-1.5">
              <label className="text-[10px] uppercase tracking-wide text-muted-foreground font-semibold">Select Resume</label>
              <select value={selectedResumeId} onChange={(e) => setSelectedResumeId(e.target.value)} className="w-full h-9 px-2 rounded-md border border-input bg-background text-sm">
                {resumes.map((r) => <option key={r.id} value={r.id}>{r.name}{r.headline ? ` — ${r.headline}` : ""}</option>)}
              </select>
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] uppercase tracking-wide text-muted-foreground font-semibold">Select Target Job</label>
              <select value={selectedJdId} onChange={(e) => setSelectedJdId(e.target.value)} className="w-full h-9 px-2 rounded-md border border-input bg-background text-sm">
                <option value="">No job selected</option>
                {jds.map((j) => <option key={j.id} value={j.id}>{j.title}{j.company ? ` — ${j.company}` : ""}</option>)}
              </select>
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] uppercase tracking-wide text-muted-foreground font-semibold">Interviewer Personas</label>
              <div className="flex flex-wrap gap-1.5">
                {INTERVIEW_PERSONAS.map((p) => {
                  const active = selectedPersonaIds.includes(p.id);
                  return (
                    <button
                      key={p.id}
                      type="button"
                      onClick={() =>
                        setSelectedPersonaIds((prev) =>
                          prev.includes(p.id) ? prev.filter((id) => id !== p.id) : [...prev, p.id]
                        )
                      }
                      className="text-xs px-2 py-1 rounded-full border flex items-center gap-1 transition-colors"
                      style={{
                        borderColor: active ? p.accent : "var(--border)",
                        background: active ? `${p.accent}1A` : "transparent",
                        color: active ? p.accent : "var(--muted-foreground)",
                      }}
                    >
                      <Icon name={p.icon as any} className="w-3.5 h-3.5" />
                      {p.name}
                    </button>
                  );
                })}
              </div>
            </div>
          </div>
          {industryDetection && industryDetection.confidence >= 15 && (
            <div className="grid sm:grid-cols-3 gap-2 text-xs">
              <div className="rounded-lg bg-secondary/40 p-2 flex items-center justify-between">
                <span className="text-muted-foreground">Company:</span>
                <span className="font-semibold">{selectedJd?.company ?? "N/A"}</span>
              </div>
              <div className="rounded-lg bg-secondary/40 p-2 flex items-center justify-between">
                <span className="text-muted-foreground">Industry:</span>
                <span className="font-semibold">{industryProfile?.label ?? "Generic"}</span>
              </div>
              <div className="rounded-lg bg-secondary/40 p-2 flex items-center justify-between">
                <span className="text-muted-foreground">Role:</span>
                <span className="font-semibold">{selectedJd?.title ?? "N/A"}</span>
              </div>
            </div>
          )}
          {(!selectedResume || !selectedJd) && (
            <p className="text-xs text-amber-600">
              {!selectedResume ? "Select a resume. " : ""}
              {!selectedJd ? "Add and select a job description for tailored questions." : ""}
            </p>
          )}
        </CardContent>
      </Card>

      {/* === Readiness Dashboard === */}
      {readinessData && (
        <Card>
          <CardContent className="p-4 sm:p-5">
            <div className="flex items-center gap-4 flex-wrap mb-4">
              <ScoreRing value={readinessData.score} size={80} label="Readiness" />
              <div className="flex-1 min-w-0">
                <h3 className="font-semibold text-sm">Interview Readiness Dashboard</h3>
                <p className="text-xs text-muted-foreground mt-0.5">
                  {readinessData.score >= 80 ? "Excellent — you're well-prepared!" : readinessData.score >= 60 ? "Good — review the topics below." : "Needs work — focus on the areas below."}
                </p>
              </div>
              {latestPkg && (
                <div className="text-right">
                  <div className="text-xs font-semibold text-brand">{completedQuestions.size}/{latestPkg.questions.length}</div>
                  <div className="text-[10px] text-muted-foreground">completed</div>
                </div>
              )}
            </div>
            <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-3">
              {readinessData.strengths.length > 0 && (
                <div><div className="text-[10px] font-semibold uppercase tracking-wide text-emerald-600 mb-1">Strengths</div>
                <ul className="space-y-0.5">{readinessData.strengths.map((s, i) => <li key={i} className="text-xs flex gap-1"><span className="text-emerald-600">✓</span> {s}</li>)}</ul></div>
              )}
              {readinessData.weaknesses.length > 0 && (
                <div><div className="text-[10px] font-semibold uppercase tracking-wide text-amber-600 mb-1">Weaknesses</div>
                <ul className="space-y-0.5">{readinessData.weaknesses.map((w, i) => <li key={i} className="text-xs flex gap-1"><span className="text-amber-600">→</span> {w}</li>)}</ul></div>
              )}
              {readinessData.focusAreas.length > 0 && (
                <div><div className="text-[10px] font-semibold uppercase tracking-wide text-brand mb-1">Focus Areas</div>
                <div className="flex flex-wrap gap-1">{readinessData.focusAreas.map((f, i) => <Badge key={i} variant="outline" className="text-[9px]">{f}</Badge>)}</div></div>
              )}
              {readinessData.topicsToReview.length > 0 && (
                <div><div className="text-[10px] font-semibold uppercase tracking-wide text-amber-500 mb-1">Topics To Review</div>
                <div className="flex flex-wrap gap-1">{readinessData.topicsToReview.map((t, i) => <Badge key={i} variant="warning" className="text-[9px]">{t}</Badge>)}</div></div>
              )}
              {readinessData.skillsToReview.length > 0 && (
                <div><div className="text-[10px] font-semibold uppercase tracking-wide text-red-500 mb-1">Skills To Review</div>
                <div className="flex flex-wrap gap-1">{readinessData.skillsToReview.map((s, i) => <Badge key={i} variant="warning" className="text-[9px]">{s}</Badge>)}</div></div>
              )}
            </div>
          </CardContent>
        </Card>
      )}

      {/* === Resume / Job / Match-score summary cards === */}
      {/* Spec requirement: "Resume summary", "Job summary", "Match score" must
          be visible on the Interview Prep page. These are pure functions of
          the selected resume + JD; no AI call. */}
      {selectedResume && (
        <div className="grid lg:grid-cols-3 gap-4">
          {/* Resume summary */}
          <Card>
            <CardContent className="p-4 space-y-2">
              <div className="flex items-center gap-2 mb-1">
                <Icon name="FileText" className="w-4 h-4 text-brand" />
                <h3 className="text-sm font-semibold">Resume Summary</h3>
              </div>
              <div className="text-sm font-medium truncate">{selectedResume.name}</div>
              {selectedResume.headline && <div className="text-xs text-muted-foreground truncate">{selectedResume.headline}</div>}
              <div className="space-y-1 text-[11px] text-muted-foreground">
                <div><span className="font-semibold text-foreground/80">Experience:</span> {(selectedResume.experience ?? []).length} role(s)</div>
                <div><span className="font-semibold text-foreground/80">Skills:</span> {(selectedResume.skills ?? []).slice(0, 8).map((s) => typeof s === "string" ? s : s.name).join(", ")}{(selectedResume.skills ?? []).length > 8 ? "…" : ""}</div>
                <div><span className="font-semibold text-foreground/80">Education:</span> {(selectedResume.education ?? []).length ? (selectedResume.education ?? []).map((e) => e.degree).filter(Boolean).join(", ") : "Not specified"}</div>
                {(selectedResume.certifications ?? []).length > 0 && (
                  <div><span className="font-semibold text-foreground/80">Certs:</span> {(selectedResume.certifications ?? []).slice(0, 3).map((c) => c.name).join(", ")}{(selectedResume.certifications ?? []).length > 3 ? "…" : ""}</div>
                )}
                {(selectedResume.languages ?? []).length > 0 && (
                  <div><span className="font-semibold text-foreground/80">Languages:</span> {(selectedResume.languages ?? []).map((l) => l.name).join(", ")}</div>
                )}
              </div>
            </CardContent>
          </Card>

          {/* Job summary */}
          <Card>
            <CardContent className="p-4 space-y-2">
              <div className="flex items-center gap-2 mb-1">
                <Icon name="Briefcase" className="w-4 h-4 text-brand" />
                <h3 className="text-sm font-semibold">Job Summary</h3>
              </div>
              <div className="text-sm font-medium truncate">{selectedJd?.title ?? "No job selected"}</div>
              {selectedJd?.company && <div className="text-xs text-muted-foreground truncate">{selectedJd.company}</div>}
              <div className="space-y-1 text-[11px] text-muted-foreground">
                <div><span className="font-semibold text-foreground/80">Industry:</span> {industryProfile?.label ?? "Generic"}</div>
                <div><span className="font-semibold text-foreground/80">Experience:</span> {selectedJd?.experienceYears ?? "Not specified"}</div>
                <div><span className="font-semibold text-foreground/80">Education:</span> {selectedJd?.education ?? "Not specified"}</div>
                <div><span className="font-semibold text-foreground/80">Employment:</span> {selectedJd?.employmentType ?? "Not specified"}</div>
                {(selectedJd?.requiredSkills ?? []).length > 0 && (
                  <div><span className="font-semibold text-foreground/80">Required Skills:</span> {(selectedJd?.requiredSkills ?? []).slice(0, 6).join(", ")}{(selectedJd?.requiredSkills ?? []).length > 6 ? "…" : ""}</div>
                )}
                {(selectedJd?.keywords ?? []).length > 0 && (
                  <div className="flex items-start gap-1"><span className="font-semibold text-foreground/80 shrink-0">ATS Keywords:</span> <span className="flex flex-wrap gap-1">{(selectedJd?.keywords ?? []).slice(0, 6).map((k, i) => <Badge key={i} variant="outline" className="text-[9px]">{k}</Badge>)}</span></div>
                )}
              </div>
            </CardContent>
          </Card>

          {/* Match score */}
          {matchScore && (
            <Card>
              <CardContent className="p-4 space-y-2">
                <div className="flex items-center justify-between mb-1">
                  <div className="flex items-center gap-2">
                    <Icon name="Target" className="w-4 h-4 text-brand" />
                    <h3 className="text-sm font-semibold">Match Score</h3>
                  </div>
                  <ScoreRing value={matchScore.overall} size={48} label="Match" />
                </div>
                <div className="space-y-1 text-[11px]">
                  <MatchRow label="Skills" value={matchScore.skillMatch} />
                  <MatchRow label="ATS Keywords" value={matchScore.keywordMatch} />
                  <MatchRow label="Experience" value={matchScore.experienceMatch} />
                  <MatchRow label="Education" value={matchScore.educationMatch} />
                  <MatchRow label="Industry" value={matchScore.industryMatch} />
                </div>
                <div className="flex items-center justify-between text-[10px] text-muted-foreground pt-1 border-t border-border">
                  <span className="capitalize">Seniority: <span className="font-semibold text-foreground/80">{matchScore.seniority}</span></span>
                  <span>Industry: <span className="font-semibold text-foreground/80">{matchScore.industry}</span></span>
                </div>
                {matchScore.missingSkills.length > 0 && (
                  <div className="text-[10px]"><span className="font-semibold text-amber-600">Missing skills: </span><span className="text-muted-foreground">{matchScore.missingSkills.join(", ")}</span></div>
                )}
              </CardContent>
            </Card>
          )}
        </div>
      )}

      {/* === Progress tracker === */}
      {latestPkg && prepPercent > 0 && (
        <Card>
          <CardContent className="p-3">
            <div className="flex items-center justify-between text-xs mb-1.5">
              <span className="font-medium text-muted-foreground">Preparation Progress</span>
              <span className="font-bold text-brand">{prepPercent}%</span>
            </div>
            <div className="h-2 bg-secondary rounded-full overflow-hidden">
              <div className="h-full bg-gradient-to-r from-brand to-emerald-500 rounded-full transition-all" style={{ width: `${prepPercent}%` }} />
            </div>
          </CardContent>
        </Card>
      )}

      {/* === Loading skeleton === */}
      {generating && <InterviewSkeleton />}

      {/* === Empty state === */}
      {!generating && interviews.length === 0 && (
        <Card>
          <CardContent className="py-12 text-center">
            <Icon name="MessagesSquare" className="w-10 h-10 text-muted-foreground/40 mx-auto" />
            <h3 className="mt-3 font-semibold">No interview packages yet</h3>
            <p className="text-sm text-muted-foreground mt-1 max-w-md mx-auto">
              {selectedResume && selectedJd
                ? "Click \"Generate package\" to create personalized interview questions with tailored answers."
                : "Select a resume and job description above, then generate."}
            </p>
          </CardContent>
        </Card>
      )}

      {/* === Interview packages === */}
      {!generating && interviews.map((pkg) => {
        const g = grouped(pkg);
        return (
          <Card key={pkg.id}>
            <CardHeader>
              <div className="flex items-center justify-between flex-wrap gap-2">
                <div>
                  <CardTitle className="text-lg flex items-center gap-2">
                    <Icon name="Package" className="w-4 h-4 text-brand" />
                    {pkg.role ?? "Interview Prep"}{pkg.company ? ` at ${pkg.company}` : ""}
                  </CardTitle>
                  <CardDescription>{(pkg.questions ?? []).length} questions · generated {new Date(pkg.createdAt).toLocaleDateString()}</CardDescription>
                </div>
                <div className="flex gap-2 flex-wrap">
                  <Button size="sm" variant="outline" onClick={() => setPracticeSession(pkg)} className="gap-1.5 border-brand text-brand hover:bg-brand-light" title="Start interactive practice session">
                    <Icon name="Play" className="w-3.5 h-3.5" /> Practice
                  </Button>
                  <Button size="sm" variant="outline" onClick={() => { exportInterviewDOCX(pkg); incUsage("downloads"); toast.success("DOCX exported."); }} className="gap-1.5"><Icon name="FileType" className="w-3.5 h-3.5" /> DOCX</Button>
                  <Button size="sm" variant="outline" onClick={() => { exportInterviewMarkdown(pkg); incUsage("downloads"); toast.success("Markdown exported."); }} className="gap-1.5"><Icon name="FileText" className="w-3.5 h-3.5" /> MD</Button>
                  <Button size="sm" variant="outline" onClick={() => { exportInterviewJSON(pkg); incUsage("downloads"); toast.success("JSON exported."); }} className="gap-1.5"><Icon name="Braces" className="w-3.5 h-3.5" /> JSON</Button>
                  <Button size="sm" onClick={() => { exportInterviewPDF(pkg); incUsage("downloads"); log({ actor: "you", action: "Interview prep exported (PDF)", category: "export", details: `${pkg.role}.pdf`, severity: "info" }); toast.success("PDF exported."); }} className="bg-brand hover:bg-brand-dark text-white gap-1.5"><Icon name="Download" className="w-3.5 h-3.5" /> PDF</Button>
                  <Button size="sm" variant="ghost" className="text-destructive" onClick={() => { removeInterview(pkg.id); toast.success("Deleted."); }}><Icon name="Trash2" className="w-3.5 h-3.5" /></Button>
                </div>
              </div>
            </CardHeader>
            <CardContent>
              {/* Category summary */}
              <div className="flex flex-wrap gap-2 mb-4">
                {CATEGORIES.map((c) => {
                  const n = g[c.id]?.length ?? 0;
                  if (!n) return null;
                  return (
                    <div key={c.id} className="flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium" style={{ background: `${c.color}15`, color: c.color }}>
                      <Icon name={c.icon} className="w-3.5 h-3.5" /> {c.label}: <span className="font-bold">{n}</span>
                    </div>
                  );
                })}
              </div>

              <div className="space-y-3">
                {(pkg.questions ?? []).map((q, i) => {
                  const cat = CATEGORIES.find((c) => c.id === q.category) ?? CATEGORIES[0];
                  const isOpen = expanded === q.id;
                  const isCompleted = completedQuestions.has(q.id);
                  return (
                    <div key={q.id} className={`rounded-xl border overflow-hidden transition ${isCompleted ? "border-emerald-300 bg-emerald-50/30 dark:bg-emerald-950/10" : "border-border"}`}>
                      <div className="flex items-stretch">
                        <button
                          onClick={() => toggleCompleted(q.id)}
                          className="shrink-0 w-8 flex items-center justify-center hover:bg-secondary/50 transition"
                          title={isCompleted ? "Mark as not completed" : "Mark as completed"}
                        >
                          <Icon name={isCompleted ? "CheckCircle2" : "Circle"} className={`w-4 h-4 ${isCompleted ? "text-emerald-600" : "text-muted-foreground"}`} />
                        </button>
                        <button onClick={() => setExpanded(isOpen ? null : q.id)} className="flex-1 flex items-start gap-3 p-4 text-left hover:bg-secondary/50 transition min-w-0">
                          <div className="w-8 h-8 rounded-lg flex items-center justify-center shrink-0" style={{ background: `${cat.color}15`, color: cat.color }}>
                            <Icon name={cat.icon} className="w-4 h-4" />
                          </div>
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2 mb-1 flex-wrap">
                              <span className="text-[10px] uppercase tracking-wide font-semibold" style={{ color: cat.color }}>{cat.label}</span>
                              {q.subType && SUB_TYPE_LABELS[q.subType] && (
                                <span className="text-[10px] px-1.5 py-0.5 rounded-full font-semibold bg-brand/10 text-brand" title="Sonru question family">{SUB_TYPE_LABELS[q.subType]}</span>
                              )}
                              <span className="text-[10px] px-1.5 py-0.5 rounded-full font-semibold" style={{ background: `${DIFFICULTY_COLORS[q.difficulty] ?? "#888"}20`, color: DIFFICULTY_COLORS[q.difficulty] ?? "#888" }}>{q.difficulty}</span>
                              {q.personaName && <span className="text-[10px] text-muted-foreground flex items-center gap-0.5"><Icon name="User" className="w-2.5 h-2.5" /> {q.personaName}</span>}
                              {isCompleted && <span className="text-[10px] text-emerald-600 font-medium">✓ completed</span>}
                            </div>
                            <div className={`font-semibold text-sm text-pretty ${isCompleted ? "line-through opacity-60" : ""}`}>{i + 1}. {q.question}</div>
                          </div>
                          <Icon name="ChevronDown" className={`w-4 h-4 text-muted-foreground shrink-0 transition-transform ${isOpen ? "rotate-180" : ""}`} />
                        </button>
                      </div>
                      {isOpen && (
                        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} className="overflow-hidden">
                          <div className="p-4 pt-0 space-y-3 text-sm">
                            <div>
                              <div className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-1">Recommended Answer</div>
                              <p className="text-foreground/90 text-pretty">{q.recommendedAnswer}</p>
                            </div>
                            {q.talkingPoints?.length > 0 && (
                              <div>
                                <div className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-1">Talking Points</div>
                                <ul className="space-y-0.5">{q.talkingPoints.map((t, j) => <li key={j} className="flex gap-2"><span className="text-brand">›</span> <span>{t}</span></li>)}</ul>
                              </div>
                            )}
                            {q.starExample && (
                              <div>
                                <div className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-1">STAR Example</div>
                                <div className="rounded-lg bg-secondary p-3 space-y-1 text-xs">
                                  <div><span className="font-semibold text-brand">Situation:</span> {q.starExample.situation}</div>
                                  <div><span className="font-semibold text-brand">Task:</span> {q.starExample.task}</div>
                                  <div><span className="font-semibold text-brand">Action:</span> {q.starExample.action}</div>
                                  <div><span className="font-semibold text-brand">Result:</span> {q.starExample.result}</div>
                                </div>
                              </div>
                            )}
                            {q.followUps?.length > 0 && (
                              <div>
                                <div className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-1">Follow-Up Questions</div>
                                <ul className="space-y-0.5">{q.followUps.map((f, j) => <li key={j} className="flex gap-2 text-xs"><span className="text-gold">?</span> <span>{f}</span></li>)}</ul>
                              </div>
                            )}
                          </div>
                        </motion.div>
                      )}
                    </div>
                  );
                })}
              </div>
            </CardContent>
          </Card>
        );
      })}

      {/* === Previous Simulator Sessions (Sonru-style history) === */}
      {!generating && interviewSessions.length > 0 && (
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-sm flex items-center gap-2"><Icon name="History" className="w-4 h-4 text-brand" /> Previous Simulator Sessions</CardTitle>
            <CardDescription>Recordings are stored locally on this device. Final reports are summarised below.</CardDescription>
          </CardHeader>
          <CardContent className="space-y-2">
            {interviewSessions.map((sess) => {
              // The persisted `reportRef` field carries a serialized
              // InterviewFinalReport (capped at 4KB). Try to parse it for
              // display; if missing or invalid, fall back to recording count.
              let parsedReport: { overallScore?: number; verdictLabel?: string; atsReadiness?: number } | null = null;
              if (sess.reportRef) {
                try {
                  parsedReport = JSON.parse(sess.reportRef);
                } catch {
                  parsedReport = null;
                }
              }
              return (
                <div key={sess.id} className="flex items-center justify-between gap-2 rounded-lg border border-border px-3 py-2">
                  <div className="min-w-0">
                    <div className="text-sm font-medium truncate">{sess.role ?? "Simulator Session"}{sess.company ? ` at ${sess.company}` : ""}</div>
                    <div className="text-[10px] text-muted-foreground flex items-center gap-1.5 flex-wrap">
                      <span>{new Date(sess.startedAt).toLocaleDateString()}</span>
                      <span>·</span>
                      <span>{sess.recordings.length} recording{sess.recordings.length === 1 ? "" : "s"}</span>
                      <span>·</span>
                      <span className="capitalize">{sess.status}</span>
                      {parsedReport?.verdictLabel && (
                        <>
                          <span>·</span>
                          <span className="font-semibold text-brand">{parsedReport.verdictLabel.split("—")[0].trim()}</span>
                        </>
                      )}
                      {typeof parsedReport?.overallScore === "number" && (
                        <>
                          <span>·</span>
                          <span>Score {parsedReport.overallScore}</span>
                        </>
                      )}
                    </div>
                  </div>
                  <div className="flex items-center gap-1.5 shrink-0">
                    <Button size="sm" variant="ghost" className="text-destructive" onClick={() => { removeInterviewSession(sess.id); toast.success("Session removed."); }}>
                      <Icon name="Trash2" className="w-3.5 h-3.5" />
                    </Button>
                  </div>
                </div>
              );
            })}
          </CardContent>
        </Card>
      )}
        </>
      )}
    </div>
  );
}

// ----------------------------------------------------------------------------
// Match-row helper — a labeled 0-100 bar shown inside the Match Score card.
// Pure presentational component; no state.
// ----------------------------------------------------------------------------

function MatchRow({ label, value }: { label: string; value: number }) {
  const color = value >= 70 ? "#10B981" : value >= 50 ? "#F59E0B" : "#DC2626";
  return (
    <div className="flex items-center gap-2">
      <span className="w-24 shrink-0 text-muted-foreground">{label}</span>
      <div className="flex-1 h-1.5 bg-secondary rounded-full overflow-hidden">
        <div className="h-full rounded-full" style={{ width: `${value}%`, background: color }} />
      </div>
      <span className="w-7 text-right font-semibold">{value}</span>
    </div>
  );
}

src/components/app/modules/InterviewAnal:
"use client";

// ============================================================================
// Phase 8.1.5 (P5) — Interview Analytics Visualizations.
// Consumes CandidateIntelligence + benchmarkCandidates + computeDecisionMetrics.
// Pure presentation — all numbers come from src/lib/recruiter + src/lib/ai/*.
// ============================================================================

import { useMemo } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Icon } from "@/components/shared";
import { useApp } from "@/lib/store";
import { buildCompetencyAnalytics } from "@/lib/recruiter/competency-analytics";
import { benchmarkCandidates } from "@/lib/recruiter/benchmark";
import { computeDecisionMetrics } from "@/lib/ai/decision-metrics";
import { CompetencyRadar } from "@/components/analytics/CompetencyRadar";
import { CompetencyHeatmap } from "@/components/analytics/CompetencyHeatmap";
import { DecisionDistribution } from "@/components/analytics/DecisionDistribution";
import { BenchmarkChart } from "@/components/analytics/BenchmarkChart";
import { useSessionIntelligence } from "@/components/recruiter/useSessionIntelligence";

export function InterviewAnalytics() {
  const setView = useApp((s) => s.setView);
  const flightRecords = useApp((s) => s.flightRecords);
  const { sessions, selectedId, setSelectedId, activeSession, ci } = useSessionIntelligence();

  const analytics = useMemo(() => (ci ? buildCompetencyAnalytics(ci) : null), [ci]);
  const benchmark = useMemo(
    () => (ci ? benchmarkCandidates([ci], "company") : null),
    [ci],
  );
  const metrics = useMemo(() => computeDecisionMetrics(flightRecords), [flightRecords]);

  if (sessions.length === 0 || !ci) {
    return (
      <div className="space-y-6">
        <Header onBack={() => setView("recruiter")} />
        <Card>
          <CardContent className="p-10 text-center text-muted-foreground">
            <Icon name="BarChart3" className="w-10 h-10 mx-auto mb-3 opacity-50" />
            <p className="text-sm">No interview data to visualize yet.</p>
            <Button className="mt-4" onClick={() => setView("interview")}>
              <Icon name="MessagesSquare" className="w-4 h-4 mr-2" /> Go to Interview Prep
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <Header onBack={() => setView("recruiter")} />

      {sessions.length > 1 && (
        <Card>
          <CardContent className="p-4 flex flex-wrap gap-2">
            {sessions.map((s) => (
              <button
                key={s.id}
                onClick={() => setSelectedId(s.id)}
                className={`px-3 py-1.5 rounded-lg border text-sm ${s.id === selectedId ? "border-brand bg-brand/10" : "border-border hover:bg-accent/50"}`}
              >
                {s.role ?? s.company ?? "Candidate"}
              </button>
            ))}
          </CardContent>
        </Card>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        <Card>
          <CardHeader><CardTitle className="text-base">Competency Radar</CardTitle></CardHeader>
          <CardContent><CompetencyRadar ci={ci} /></CardContent>
        </Card>
        <Card>
          <CardHeader><CardTitle className="text-base">Competency Heatmap</CardTitle></CardHeader>
          <CardContent><CompetencyHeatmap ci={ci} /></CardContent>
        </Card>
        <Card>
          <CardHeader><CardTitle className="text-base">Decision Distribution (session)</CardTitle><CardDescription>{metrics.totalDecisions} executions</CardDescription></CardHeader>
          <CardContent><DecisionDistribution metrics={metrics} /></CardContent>
        </Card>
        <Card>
          <CardHeader><CardTitle className="text-base">Benchmark vs Cohort</CardTitle><CardDescription>Grouped by company</CardDescription></CardHeader>
          <CardContent>{benchmark && <BenchmarkChart result={benchmark} />}</CardContent>
        </Card>
      </div>

      {analytics && (
        <Card>
          <CardHeader><CardTitle className="text-base">Score Distribution</CardTitle></CardHeader>
          <CardContent>
            <div className="flex gap-2 flex-wrap">
              {analytics.scoreDistribution.map((b, i) => (
                <div key={i} className="rounded-lg border border-border px-3 py-2 text-center">
                  <div className="text-lg font-bold">{b}</div>
                  <div className="text-xs text-muted-foreground">{(i * 20) + 1}–{(i + 1) * 20}</div>
                </div>
              ))}
            </div>
            <p className="text-xs text-muted-foreground mt-3">
              Strongest: {analytics.strongest.join(", ") || "—"} · Weakest: {analytics.weakest.join(", ") || "—"}
            </p>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

function Header({ onBack }: { onBack: () => void }) {
  return (
    <div className="flex items-center gap-3">
      <Button variant="ghost" size="icon" onClick={onBack} aria-label="Back to recruiter">
        <Icon name="ArrowLeft" className="w-4 h-4" />
      </Button>
      <div>
        <h1 className="font-display text-2xl font-bold">Competency Analytics</h1>
        <p className="text-sm text-muted-foreground">Interview intelligence visualizations.</p>
      </div>
    </div>
  );
}

src/components/app/modules/InterviewRepo:
"use client";

// ============================================================================
// Phase 8.1.5 (P7) — Executive Recruiter Report + Export UI.
// generateExecutiveReport(ci) -> renderReportMarkdown(report). Export to
// PDF (jsPDF) / Word (docx) / Markdown / Print / Download / Share.
// PRESENTATION ONLY — no AI, no recomputation.
// ============================================================================

import { useMemo, useState } from "react";
import jsPDF from "jspdf";
import { Document, Packer, Paragraph, HeadingLevel, TextRun } from "docx";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Icon } from "@/components/shared";
import { useApp } from "@/lib/store";
import { generateExecutiveReport, renderReportMarkdown } from "@/lib/recruiter/executive-report";
import { useSessionIntelligence } from "@/components/recruiter/useSessionIntelligence";

function download(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

function safeName(s?: string) {
  return (s ?? "candidate").replace(/\s+/g, "_").toLowerCase();
}

export function InterviewReports() {
  const setView = useApp((s) => s.setView);
  const { sessions, selectedId, setSelectedId, ci } = useSessionIntelligence();
  const [copied, setCopied] = useState(false);

  const report = useMemo(() => (ci ? generateExecutiveReport(ci) : null), [ci]);
  const markdown = useMemo(() => (report ? renderReportMarkdown(report) : ""), [report]);

  if (sessions.length === 0 || !report) {
    return (
      <div className="space-y-6">
        <Header onBack={() => setView("recruiter")} />
        <Card><CardContent className="p-10 text-center text-muted-foreground">
          <Icon name="FileText" className="w-10 h-10 mx-auto mb-3 opacity-50" />
          <p className="text-sm">No interview report available yet.</p>
        </CardContent></Card>
      </div>
    );
  }

  const exportPDF = () => {
    const doc = new jsPDF({ unit: "pt", format: "a4" });
    doc.setFontSize(10);
    let y = 48;
    for (const rawLine of markdown.split("\n")) {
      // wrap long lines to page width (~90 chars at 10pt)
      const wrapped = doc.splitTextToSize(rawLine || " ", 515) as string[];
      for (const line of wrapped) {
        if (y > 800) { doc.addPage(); y = 48; }
        doc.text(line, 40, y);
        y += 14;
      }
    }
    doc.save(`${safeName(report.candidate.name)}_executive_report.pdf`);
  };

  const exportWord = async () => {
    const doc = new Document({
      sections: [{
        children: markdown.split("\n").map((line) =>
          line.startsWith("# ") || line.startsWith("## ")
            ? new Paragraph({ text: line.replace(/^#+\s/, ""), heading: HeadingLevel.HEADING_1 })
            : new Paragraph({ children: [new TextRun(line || " ")] }),
        ),
      }],
    });
    const blob = await Packer.toBlob(doc);
    download(blob, `${safeName(report.candidate.name)}_executive_report.docx`);
  };

  const exportMarkdown = () => download(new Blob([markdown], { type: "text/markdown" }), `${safeName(report.candidate.name)}_executive_report.md`);

  const share = async () => {
    if (navigator.share) {
      try { await navigator.share({ title: "Executive Recruiter Report", text: markdown }); } catch { /* user cancelled */ }
    } else {
      await navigator.clipboard.writeText(markdown);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <div className="space-y-6">
      <Header onBack={() => setView("recruiter")} />

      <div className="flex items-center justify-between gap-3 flex-wrap">
        <div>
          <h2 className="font-display text-xl font-bold">{report.candidate.name ?? "Candidate"}</h2>
          <p className="text-sm text-muted-foreground">Recommendation: {report.hiringRecommendation.replace("_", " ").toUpperCase()}</p>
        </div>
        <div className="flex gap-2 flex-wrap">
          <Button size="sm" onClick={exportPDF}><Icon name="FileDown" className="w-4 h-4 mr-2" /> PDF</Button>
          <Button size="sm" onClick={exportWord}><Icon name="FileText" className="w-4 h-4 mr-2" /> Word</Button>
          <Button size="sm" variant="outline" onClick={exportMarkdown}><Icon name="Download" className="w-4 h-4 mr-2" /> Markdown</Button>
          <Button size="sm" variant="outline" onClick={() => window.print()}><Icon name="Printer" className="w-4 h-4 mr-2" /> Print</Button>
          <Button size="sm" variant="outline" onClick={share}><Icon name={copied ? "Check" : "Share2"} className="w-4 h-4 mr-2" /> {copied ? "Copied" : "Share"}</Button>
        </div>
      </div>

      {sessions.length > 1 && (
        <Card><CardContent className="p-4 flex flex-wrap gap-2">
          {sessions.map((s) => (
            <button key={s.id} onClick={() => setSelectedId(s.id)}
              className={`px-3 py-1.5 rounded-lg border text-sm ${s.id === selectedId ? "border-brand bg-brand/10" : "border-border hover:bg-accent/50"}`}>
              {s.role ?? s.company ?? "Candidate"}
            </button>
          ))}
        </CardContent></Card>
      )}

      <Tabs defaultValue="preview">
        <TabsList>
          <TabsTrigger value="preview">Preview</TabsTrigger>
          <TabsTrigger value="markdown">Markdown</TabsTrigger>
        </TabsList>
        <TabsContent value="preview" className="mt-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <Section title="Executive Summary" body={report.executiveSummary} />
            <Section title="Candidate Summary" body={report.candidateSummary} />
            <Section title="Interview Overview" body={report.interviewOverview} />
            <Section title="Risk Assessment" body={report.riskAssessment} />
            <Card className="md:col-span-2">
              <CardHeader><CardTitle className="text-base">Competencies</CardTitle></CardHeader>
              <CardContent className="space-y-1.5">
                {report.competencies.map((c) => (
                  <div key={c.label} className="flex items-center gap-3 text-sm">
                    <span className="w-44 truncate">{c.label}</span>
                    <span className="font-medium w-10">{c.score}</span>
                    {c.risk && <span className="text-xs text-red-500">risk</span>}
                  </div>
                ))}
              </CardContent>
            </Card>
            <ListSection title="Strengths" items={report.strengths} />
            <ListSection title="Weaknesses" items={report.weaknesses} />
            <ListSection title="Follow-up Questions" items={report.followUpQuestions} />
            <ListSection title="Training Plan" items={report.trainingPlan} />
          </div>
        </TabsContent>
        <TabsContent value="markdown" className="mt-4">
          <Card><CardContent>
            <pre className="text-xs whitespace-pre-wrap max-h-[600px] overflow-auto">{markdown}</pre>
          </CardContent></Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

function Section({ title, body }: { title: string; body: string }) {
  return (
    <Card><CardHeader><CardTitle className="text-base">{title}</CardTitle></CardHeader>
      <CardContent><p className="text-sm text-pretty">{body}</p></CardContent></Card>
  );
}

function ListSection({ title, items }: { title: string; items: string[] }) {
  return (
    <Card><CardHeader><CardTitle className="text-base">{title}</CardTitle></CardHeader>
      <CardContent><ul className="list-disc pl-5 space-y-1 text-sm">{items.map((i, k) => <li key={k}>{i}</li>)}</ul></CardContent></Card>
  );
}

function Header({ onBack }: { onBack: () => void }) {
  return (
    <div className="flex items-center gap-3">
      <Button variant="ghost" size="icon" onClick={onBack} aria-label="Back to recruiter">
        <Icon name="ArrowLeft" className="w-4 h-4" />
      </Button>
      <div>
        <h1 className="font-display text-2xl font-bold">Executive Reports</h1>
        <p className="text-sm text-muted-foreground">Structured recruiter reports with export.</p>
      </div>
    </div>
  );
}

