"use client";

import { recordAI, setFlightScope } from "@/lib/ai/flight-recorder";
setFlightScope({ scope: "job-intelligence", feature: "JD Scraper", module: "src.components.app.modules.JDScraper" });

import { useState } from "react";
import { motion } from "framer-motion";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Badge, Icon } from "@/components/shared";
import { useApp, uid } from "@/lib/store";
import { callAI, extractJSON } from "@/lib/ai";
import { processAIResponse } from "@/lib/ai-response-processor";
import { toast } from "sonner";
import type { JobDescription } from "@/lib/types";

const SAMPLE_URLS = [
  "https://www.linkedin.com/jobs/view/1234567890/",
  "https://www.indeed.com/viewjob?jk=abc123",
  "https://www.glassdoor.com/job-listing/senior-engineer",
];

export function JDScraper() {
  const jds = useApp((s) => s.jobDescriptions);
  const addJD = useApp((s) => s.addJD);
  const removeJD = useApp((s) => s.removeJD);
  const setActiveJD = useApp((s) => s.setActiveJD);
  const setView = useApp((s) => s.setView);
  const log = useApp((s) => s.log);

  const [url, setUrl] = useState("");
  const [rawText, setRawText] = useState("");
  const [scraping, setScraping] = useState(false);
  const [extracting, setExtracting] = useState(false);
  const [logLines, setLogLines] = useState<string[]>([]);

  const scrapeUrl = async () => {
    if (!url || !/^https?:\/\//.test(url)) {
      toast.error("Please enter a valid URL (including https://).");
      return;
    }
    setScraping(true);
    setLogLines([`Fetching ${url}…`]);
    // Abort the request after 20s so the spinner never spins forever.
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 20000);
    try {
      const res = await fetch("/api/jd-scrape", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ url }),
        signal: controller.signal,
      });

      // Safely parse JSON — handle empty/non-JSON responses
      const text = await res.text();
      let data: any;
      try {
        data = JSON.parse(text);
      } catch {
        throw new Error(`Server returned a non-JSON response (${res.status} ${res.statusText}). The site may be blocking our scraper.`);
      }

      if (!res.ok) throw new Error(data.error || `Fetch failed (${res.status})`);

      if (!data.text || data.text.trim().length < 30) {
        throw new Error("The page was fetched but no readable text was found. The site may use JavaScript rendering. Please paste the JD text manually.");
      }

      setLogLines((l) => [...l, `Retrieved ${data.text.length} chars.`, "Page text ready for AI extraction."]);
      setRawText(data.text);
      toast.success(`Scraped ${data.title || url}`);
    } catch (e: any) {
      const msg = e?.name === "AbortError"
        ? "The scrape request timed out after 20 seconds. The site may be slow or blocking our request — please paste the JD text manually below."
        : (e?.message || "Unknown error");
      setLogLines((l) => [...l, `⚠ ${msg}`, "Falling back: paste the JD text manually below."]);
      toast.error(msg.includes("paste") ? msg : "Couldn't fetch the URL. Please paste the JD text manually below — same AI extraction.");
    } finally {
      clearTimeout(timeout);
      setScraping(false);
    }
  };

  const extract = async () => {
    if (rawText.trim().length < 30) {
      toast.error("Please paste at least 30 characters of job description text.");
      return;
    }
    setExtracting(true);
    setLogLines((l) => [...l, "Calling AI to extract structure…"]);
    try {
      const result = await recordAI({
        systemPrompt: "You are a job description parser. Extract structured data. Return ONLY valid JSON.",
        userPrompt: `Extract from this job description:\n\n${rawText}\n\nReturn JSON with keys: title, company, location, employmentType, salary, responsibilities (array of strings), requiredSkills (array), preferredSkills (array), technologies (array), experienceYears, education, keywords (array of 8-15 most important).`,
        maxTokens: 2000,
        taskCategory: "document",
      });

      // === DIAGNOSTICS ===
      console.group("Job URL Parsing");
      console.log("Provider:", result.provider);
      console.log("Raw Text Length:", rawText.length);
      console.log("AI Response Length:", result.text?.length ?? 0);
      console.log("AI Response Preview:", result.text?.slice(0, 200) ?? "(empty)");
      console.groupEnd();

      // Process through the AI Response Processing Layer — this catches
      // errors, repairs JSON, strips leaks, and validates safety
      const processed = processAIResponse<any>(result.text, result.provider, { expectJson: true });

      // === MORE DIAGNOSTICS ===
      console.log("Parsed JD:", processed.data);
      console.log("JD Description Length:", processed.data?.description?.length ?? "N/A");
      console.log("Keywords Extracted:", processed.data?.keywords?.length ?? 0);

      if (!processed.data) {
        // JSON parsing failed even after repair — use heuristic fallback
        setLogLines((l) => [...l, "⚠ AI did not return valid JSON — using heuristic fallback extraction."]);
        const words = rawText.toLowerCase().match(/\b[a-z][a-z0-9+#.]+\b/g) ?? [];
        const freq: Record<string, number> = {};
        for (const w of words) if (w.length > 2) freq[w] = (freq[w] || 0) + 1;
        const keywords = Object.entries(freq).sort((a, b) => b[1] - a[1]).slice(0, 12).map(([k]) => k);
        const jd: JobDescription = {
          id: uid("jd"),
          title: "Parsed role",
          keywords,
          responsibilities: [],
          requiredSkills: [],
          preferredSkills: [],
          technologies: [],
          rawText,
          source: url ? "url" : "text",
          url: url || undefined,
          createdAt: new Date().toISOString(),
        };
        addJD(jd);
        toast.success(`Extracted ${keywords.length} keywords (heuristic fallback).`);
        setExtracting(false);
        return;
      }

      const data = processed.data;
      // === NORMALIZE: flatten any object values to strings ===
      const flattenLoc = (v: any): string | undefined => {
        if (!v) return undefined;
        if (typeof v === "string") return v;
        if (typeof v === "object") {
          const parts = [v.city, v.state, v.region, v.country, v.address].filter((x: any) => x && typeof x === "string");
          if (parts.length > 0) return parts.join(", ");
          return Object.values(v).filter(Boolean).join(", ");
        }
        return String(v);
      };
      const flattenStr = (v: any): string | undefined => {
        if (v === null || v === undefined) return undefined;
        if (typeof v === "string") return v;
        if (typeof v === "number" || typeof v === "boolean") return String(v);
        if (typeof v === "object") return JSON.stringify(v);
        return String(v);
      };
      const flattenArray = (v: any): string[] => {
        if (!Array.isArray(v)) return [];
        return v.map((x: any) => typeof x === "string" ? x : (typeof x === "object" ? JSON.stringify(x) : String(x))).filter(Boolean);
      };
      const jd: JobDescription = {
        id: uid("jd"),
        title: flattenStr(data.title) || "Untitled role",
        company: flattenStr(data.company),
        location: flattenLoc(data.location),
        employmentType: flattenStr(data.employmentType),
        salary: flattenStr(data.salary),
        responsibilities: flattenArray(data.responsibilities),
        requiredSkills: flattenArray(data.requiredSkills),
        preferredSkills: flattenArray(data.preferredSkills),
        technologies: flattenArray(data.technologies),
        experienceYears: flattenStr(data.experienceYears),
        education: flattenStr(data.education),
        keywords: flattenArray(data.keywords),
        rawText,
        source: url ? "url" : "text",
        url: url || undefined,
        createdAt: new Date().toISOString(),
      };
      addJD(jd);
      // Background Speculative Pre-Fetching
      try {
        const activeResumeId = useApp.getState().activeResumeId;
        const activeResume = useApp.getState().resumes.find(r => r.id === activeResumeId);
        if (activeResume) {
          import("@/lib/agents/prefetch").then(({ startSpeculativePrefetch }) => {
            startSpeculativePrefetch(activeResume, jd);
          }).catch(err => {
            console.warn("[Prefetch] Dynamic import failed:", err);
          });
        }
      } catch (e) {
        console.warn("[Prefetch] Failed to trigger pre-fetch:", e);
      }
      log({ actor: "you", action: "JD scraped & extracted", category: "ai", details: `${jd.title} at ${jd.company ?? "—"}`, severity: "info" });
      setLogLines((l) => [...l, `✓ Extracted ${jd.keywords.length} keywords, ${jd.requiredSkills.length} required skills.`, `Saved to library via ${result.provider}.`]);
      toast.success(`Extracted: ${jd.title}`);
      setUrl("");
      setRawText("");
    } catch (e: any) {
      setLogLines((l) => [...l, `⚠ ${e?.message}`, "Falling back to heuristic extraction."]);
      // Heuristic fallback
      const words = rawText.toLowerCase().match(/\b[a-z][a-z0-9+#.]+\b/g) ?? [];
      const freq: Record<string, number> = {};
      for (const w of words) if (w.length > 2) freq[w] = (freq[w] || 0) + 1;
      const keywords = Object.entries(freq).sort((a, b) => b[1] - a[1]).slice(0, 12).map(([k]) => k);
      const jd: JobDescription = {
        id: uid("jd"),
        title: "Parsed role",
        keywords,
        responsibilities: [],
        requiredSkills: [],
        preferredSkills: [],
        technologies: [],
        rawText,
        source: url ? "url" : "text",
        url: url || undefined,
        createdAt: new Date().toISOString(),
      };
      addJD(jd);
      toast.success(`Extracted ${keywords.length} keywords (heuristic).`);
    } finally {
      setExtracting(false);
    }
  };

  return (
    <div className="space-y-6">
      <div>
        <h1 className="font-display text-2xl font-bold flex items-center gap-2"><Icon name="Search" className="w-6 h-6 text-brand" /> Job Description Scraper</h1>
        <p className="text-sm text-muted-foreground mt-1">Drop in any URL — LinkedIn, Indeed, Glassdoor, or a company careers page. We'll fetch, parse, and extract structured data.</p>
      </div>

      <div className="grid lg:grid-cols-2 gap-4">
        {/* URL scrape */}
        <Card>
          <CardHeader>
            <CardTitle className="text-lg flex items-center gap-2"><Icon name="Link" className="w-4 h-4 text-brand" /> From a URL</CardTitle>
            <CardDescription>Works with LinkedIn, Indeed, Glassdoor, or any public job posting.</CardDescription>
          </CardHeader>
          <CardContent className="space-y-3">
            <div className="flex gap-2">
              <Input value={url} onChange={(e) => setUrl(e.target.value)} placeholder="https://..." className="flex-1" onKeyDown={(e) => e.key === "Enter" && scrapeUrl()} />
              <Button onClick={scrapeUrl} disabled={scraping} className="bg-brand hover:bg-brand-dark text-white gap-2">
                {scraping ? <Icon name="Loader2" className="w-4 h-4 animate-spin" /> : <Icon name="Download" className="w-4 h-4" />} Scrape
              </Button>
            </div>
            <div className="flex flex-wrap gap-1.5">
              {SAMPLE_URLS.map((u) => (
                <button key={u} onClick={() => setUrl(u)} className="text-[10px] px-2 py-1 rounded-md bg-secondary hover:bg-secondary/70 text-muted-foreground truncate max-w-[180px]">
                  {u}
                </button>
              ))}
            </div>
            <p className="text-xs text-muted-foreground">Note: some sites block server-side scraping. If that happens, paste the text instead — same AI extraction.</p>
          </CardContent>
        </Card>

        {/* Text paste */}
        <Card>
          <CardHeader>
            <CardTitle className="text-lg flex items-center gap-2"><Icon name="ClipboardPaste" className="w-4 h-4 text-brand" /> From pasted text</CardTitle>
            <CardDescription>Copy-paste the JD and let the AI extract the structure.</CardDescription>
          </CardHeader>
          <CardContent className="space-y-3">
            <Textarea
              value={rawText}
              onChange={(e) => setRawText(e.target.value)}
              rows={6}
              placeholder="Paste the full job description here…"
            />
            <Button onClick={extract} disabled={extracting || rawText.length < 30} className="w-full bg-brand hover:bg-brand-dark text-white gap-2">
              {extracting ? <Icon name="Loader2" className="w-4 h-4 animate-spin" /> : <Icon name="Sparkles" className="w-4 h-4" />}
              {extracting ? "Extracting…" : "Extract with AI"}
            </Button>
          </CardContent>
        </Card>
      </div>

      {/* Log */}
      {logLines.length > 0 && (
        <Card>
          <CardContent className="p-4">
            <div className="text-xs font-mono space-y-1 max-h-40 overflow-y-auto">
              {logLines.map((l, i) => (
                <div key={i} className="flex items-center gap-2">
                  <span className="text-brand">›</span> <span className={l.startsWith("⚠") ? "text-amber-600" : l.startsWith("✓") ? "text-emerald-600" : ""}>{l}</span>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Saved JDs */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle className="text-lg flex items-center gap-2"><Icon name="Library" className="w-4 h-4 text-brand" /> Saved job descriptions ({jds.length})</CardTitle>
              <CardDescription>Click any to use in the ATS checker or optimizer.</CardDescription>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          <div className="grid sm:grid-cols-2 gap-3">
            {jds.map((j) => (
              <motion.div key={j.id} initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} className="rounded-xl border border-border p-4 hover:shadow-premium transition">
                <div className="flex items-start justify-between mb-2">
                  <div className="min-w-0">
                    <div className="font-semibold text-sm truncate">{j.title}</div>
                    {j.company && <div className="text-xs text-muted-foreground">{j.company}{j.location ? ` · ${j.location}` : ""}</div>}
                  </div>
                  <Badge variant="outline" className="text-[10px] capitalize shrink-0 ml-2">{j.source}</Badge>
                </div>
                <div className="flex flex-wrap gap-1 mb-3">
                  {j.keywords.slice(0, 6).map((k) => <Badge key={k} variant="brand" className="text-[10px]">{k}</Badge>)}
                  {j.keywords.length > 6 && <Badge variant="outline" className="text-[10px]">+{j.keywords.length - 6}</Badge>}
                </div>
                <div className="flex gap-1.5">
                  <Button size="sm" variant="outline" className="flex-1" onClick={() => { setActiveJD(j.id); setView("ats-checker"); }}>
                    <Icon name="ScanText" className="w-3.5 h-3.5 mr-1" /> ATS check
                  </Button>
                  <Button size="sm" variant="outline" className="flex-1" onClick={() => { setActiveJD(j.id); setView("optimizer"); }}>
                    <Icon name="Wand2" className="w-3.5 h-3.5 mr-1" /> Optimize
                  </Button>
                  <Button size="sm" variant="ghost" className="text-destructive" onClick={() => { removeJD(j.id); toast.success("Deleted."); }}>
                    <Icon name="Trash2" className="w-3.5 h-3.5" />
                  </Button>
                </div>
              </motion.div>
            ))}
            {jds.length === 0 && (
              <div className="col-span-full text-center py-8">
                <Icon name="Library" className="w-10 h-10 text-muted-foreground/40 mx-auto" />
                <p className="text-sm text-muted-foreground mt-2">No saved JDs yet. Scrape or paste one above.</p>
              </div>
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

src/components/app/modules/Logs.tsx:
"use client";

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge, Icon } from "@/components/shared";
import { useApp } from "@/lib/store";
import { toast } from "sonner";

const CATEGORIES = ["auth", "ai", "resume", "admin", "system", "export"] as const;
const SEVERITIES = ["info", "warning", "error"] as const;

export function Logs() {
  const logs = useApp((s) => s.logs);
  const clearLogs = useApp((s) => s.clearLogs);

  const [q, setQ] = useState("");
  const [cat, setCat] = useState<string>("all");
  const [sev, setSev] = useState<string>("all");

  const filtered = logs.filter((l) => {
    if (cat !== "all" && l.category !== cat) return false;
    if (sev !== "all" && l.severity !== sev) return false;
    if (q && !(`${l.action} ${l.details} ${l.actor}`.toLowerCase().includes(q.toLowerCase()))) return false;
    return true;
  });

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h1 className="font-display text-2xl font-bold flex items-center gap-2"><Icon name="ScrollText" className="w-6 h-6 text-brand" /> Audit Logs</h1>
          <p className="text-sm text-muted-foreground mt-1">Full audit trail. Last 500 events kept in browser storage.</p>
        </div>
        <Button variant="outline" onClick={() => { if (confirm("Clear all logs?")) { clearLogs(); toast.success("Logs cleared."); } }} className="text-destructive gap-2">
          <Icon name="Trash2" className="w-4 h-4" /> Clear all
        </Button>
      </div>

      <Card>
        <CardContent className="p-4">
          <div className="flex flex-wrap items-center gap-2">
            <div className="relative flex-1 min-w-[200px]">
              <Icon name="Search" className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
              <Input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search logs…" className="pl-9 h-9" />
            </div>
            <select value={cat} onChange={(e) => setCat(e.target.value)} className="h-9 px-3 rounded-md border border-input bg-background text-sm">
              <option value="all">All categories</option>
              {CATEGORIES.map((c) => <option key={c} value={c} className="capitalize">{c}</option>)}
            </select>
            <select value={sev} onChange={(e) => setSev(e.target.value)} className="h-9 px-3 rounded-md border border-input bg-background text-sm">
              <option value="all">All severities</option>
              {SEVERITIES.map((s) => <option key={s} value={s} className="capitalize">{s}</option>)}
            </select>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader><CardTitle className="text-base">{filtered.length} events</CardTitle></CardHeader>
        <CardContent className="p-0">
          <div className="max-h-[60vh] overflow-y-auto">
            <table className="w-full text-sm">
              <thead className="sticky top-0 bg-card border-b border-border">
                <tr className="text-left text-xs uppercase tracking-wide text-muted-foreground">
                  <th className="px-4 py-2 font-semibold">Time</th>
                  <th className="px-4 py-2 font-semibold">Severity</th>
                  <th className="px-4 py-2 font-semibold">Category</th>
                  <th className="px-4 py-2 font-semibold">Actor</th>
                  <th className="px-4 py-2 font-semibold">Action</th>
                  <th className="px-4 py-2 font-semibold">Details</th>
                </tr>
              </thead>
              <tbody>
                {filtered.map((l) => {
                  const sevColor = l.severity === "info" ? "brand" : l.severity === "warning" ? "warning" : "danger";
                  return (
                    <tr key={l.id} className="border-b border-border hover:bg-secondary/30">
                      <td className="px-4 py-2 text-xs text-muted-foreground whitespace-nowrap">{new Date(l.timestamp).toLocaleString()}</td>
                      <td className="px-4 py-2"><Badge variant={sevColor as any} className="text-[10px] capitalize">{l.severity}</Badge></td>
                      <td className="px-4 py-2 text-xs capitalize">{l.category}</td>
                      <td className="px-4 py-2 text-xs">{l.actor}</td>
                      <td className="px-4 py-2 text-xs font-medium">{l.action}</td>
                      <td className="px-4 py-2 text-xs text-muted-foreground">{l.details}</td>
                    </tr>
                  );
                })}
                {filtered.length === 0 && (
                  <tr><td colSpan={6} className="text-center py-8 text-sm text-muted-foreground">No matching logs.</td></tr>
                )}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

src/components/app/modules/MyResumes.tsx:
"use client";

import { useState, useRef } from "react";
import { motion } from "framer-motion";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge, Icon } from "@/components/shared";
import { useApp, uid } from "@/lib/store";
import { parseResumeFile, blankResume } from "@/lib/parser";
import { toast } from "sonner";
import type { ResumeData } from "@/lib/types";

export function MyResumes() {
  const resumes = useApp((s) => s.resumes);
  const addResume = useApp((s) => s.addResume);
  const removeResume = useApp((s) => s.removeResume);
  const setActiveResume = useApp((s) => s.setActiveResume);
  const setView = useApp((s) => s.setView);
  const incUsage = useApp((s) => s.incUsage);
  const log = useApp((s) => s.log);

  const fileRef = useRef<HTMLInputElement>(null);
  const [uploading, setUploading] = useState(false);
  const [dragOver, setDragOver] = useState(false);

  const onFiles = async (files: FileList | null) => {
    if (!files || !files.length) return;
    const file = files[0];
    if (file.size > 20 * 1024 * 1024) {
      toast.error("File too large. Maximum 20MB.");
      return;
    }
    setUploading(true);
    try {
      const parsed = await parseResumeFile(file);
      addResume(parsed);
      incUsage("resumesGenerated");
      log({ actor: "you", action: `Uploaded resume: ${file.name}`, category: "resume", details: `${parsed.experience.length} experiences parsed`, severity: "info" });
      toast.success(`Parsed ${file.name}. ${parsed.experience.length} experiences, ${parsed.skills.length} skills extracted.`);
      setActiveResume(parsed.id);
      setView("builder");
    } catch (e: any) {
      toast.error(e?.message || "Failed to parse file.");
    } finally {
      setUploading(false);
      if (fileRef.current) fileRef.current.value = "";
    }
  };

  const startBlank = () => {
    const r = blankResume();
    addResume(r);
    setActiveResume(r.id);
    setView("builder");
    toast.success("Started a new resume from scratch.");
  };

  return (
    <div className="space-y-6">
      <div className="flex items-end justify-between flex-wrap gap-3">
        <div>
          <h1 className="font-display text-2xl font-bold flex items-center gap-2">
            <Icon name="FileText" className="w-6 h-6 text-brand" /> My Resumes
          </h1>
          <p className="text-sm text-muted-foreground mt-1">Upload an existing resume or start from a template. All parsing happens in your browser.</p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" onClick={startBlank} className="gap-2">
            <Icon name="Plus" className="w-4 h-4" /> Blank resume
          </Button>
          <Button onClick={() => fileRef.current?.click()} className="bg-brand hover:bg-brand-dark text-white gap-2">
            <Icon name="Upload" className="w-4 h-4" /> Upload resume
          </Button>
          <input
            ref={fileRef}
            type="file"
            accept=".pdf,.doc,.docx,.txt"
            className="hidden"
            onChange={(e) => onFiles(e.target.files)}
          />
        </div>
      </div>

      {/* Upload dropzone */}
      <Card>
        <CardContent className="p-0">
          <div
            onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
            onDragLeave={() => setDragOver(false)}
            onDrop={(e) => { e.preventDefault(); setDragOver(false); onFiles(e.dataTransfer.files); }}
            onClick={() => fileRef.current?.click()}
            className={`rounded-xl border-2 border-dashed m-4 p-10 text-center cursor-pointer transition ${dragOver ? "border-brand bg-brand-light/40" : "border-border hover:border-brand/50 hover:bg-secondary/40"}`}
          >
            {uploading ? (
              <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex flex-col items-center gap-3">
                <Icon name="Loader2" className="w-10 h-10 text-brand animate-spin" />
                <div className="font-medium">Parsing your resume…</div>
                <div className="text-xs text-muted-foreground">Extracting text, contacts, experience, skills, education</div>
              </motion.div>
            ) : (
              <div className="flex flex-col items-center gap-3">
                <div className="w-14 h-14 rounded-2xl gradient-brand text-white flex items-center justify-center shadow-glow">
                  <Icon name="Upload" className="w-6 h-6" />
                </div>
                <div className="font-semibold">Drop your resume here, or click to browse</div>
                <div className="text-xs text-muted-foreground">Supports PDF, DOC, DOCX, TXT — up to 20 MB</div>
                <div className="flex gap-2 mt-2">
                  <Badge variant="brand"><Icon name="ShieldCheck" className="w-3 h-3" /> Parsed in-browser</Badge>
                  <Badge variant="gold"><Icon name="Lock" className="w-3 h-3" /> Never uploaded to a server</Badge>
                </div>
              </div>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Resumes list */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">All resumes ({resumes.length})</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-3">
            {resumes.map((r) => (
              <div key={r.id} className="rounded-xl border border-border bg-card p-4 hover:shadow-premium transition">
                <div className="flex items-start justify-between mb-2">
                  <div className="min-w-0">
                    <div className="font-semibold truncate">{r.name}</div>
                    {r.headline && <div className="text-xs text-muted-foreground truncate">{r.headline}</div>}
                  </div>
                  <Badge variant={r.source === "upload" ? "brand" : "outline"} className="text-[10px] capitalize shrink-0 ml-2">
                    {r.source?.replace("-", " ")}
                  </Badge>
                </div>
                <div className="grid grid-cols-3 gap-2 my-3 text-center">
                  <div className="rounded-lg bg-secondary p-2">
                    <div className="text-sm font-bold">{r.experience.length}</div>
                    <div className="text-[10px] text-muted-foreground">Jobs</div>
                  </div>
                  <div className="rounded-lg bg-secondary p-2">
                    <div className="text-sm font-bold">{r.skills.length}</div>
                    <div className="text-[10px] text-muted-foreground">Skills</div>
                  </div>
                  <div className="rounded-lg bg-secondary p-2">
                    <div className="text-sm font-bold">{r.education.length}</div>
                    <div className="text-[10px] text-muted-foreground">Edu</div>
                  </div>
                </div>
                <div className="flex gap-1.5">
                  <Button size="sm" variant="outline" className="flex-1" onClick={() => { setActiveResume(r.id); setView("builder"); }}>
                    <Icon name="Pencil" className="w-3.5 h-3.5 mr-1" /> Edit
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    title="Duplicate as Tailored Variant"
                    onClick={() => {
                      const variant: ResumeData = {
                        ...r,
                        id: uid("res"),
                        name: `${r.name} (Tailored Variant)`,
                        headline: r.headline ? `${r.headline} - Tailored` : "Tailored Variant",
                        source: "ai-optimized" as const,
                        createdAt: new Date().toISOString(),
                        updatedAt: new Date().toISOString(),
                      };
                      addResume(variant);
                      setActiveResume(variant.id);
                      toast.success(`Created tailored variant: "${variant.name}"`);
                    }}
                  >
                    <Icon name="Copy" className="w-3.5 h-3.5" />
                  </Button>
                  <Button size="sm" variant="outline" title="Run ATS Check" onClick={() => { setActiveResume(r.id); setView("ats-checker"); }}>
                    <Icon name="ScanText" className="w-3.5 h-3.5" />
                  </Button>
                  <Button size="sm" variant="ghost" className="text-destructive hover:text-destructive hover:bg-destructive/10" onClick={() => { removeResume(r.id); toast.success("Resume deleted"); }}>
                    <Icon name="Trash2" className="w-3.5 h-3.5" />
                  </Button>
                </div>
              </div>
            ))}
            {resumes.length === 0 && (
              <div className="col-span-full text-center py-8">
                <Icon name="FileText" className="w-10 h-10 text-muted-foreground/40 mx-auto" />
                <p className="text-sm text-muted-foreground mt-2">No resumes yet. Upload one above or start from blank.</p>
              </div>
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

src/components/app/modules/PersonaManage:
"use client";

// ============================================================================
// Phase 8.1.5 (P8) — Persona Management (Super Admin).
// Renders the interviewer personas in an editable grid. The live list lives
// in the store and persists to D1 via the branding admin-settings blob
// (saveInterviewPersonas → PUT /api/settings/branding) so edits survive
// refresh; the view never re-implements interview logic.
// ============================================================================

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge, Icon } from "@/components/shared";
import { useApp } from "@/lib/store";
import { api as cloudApi } from "@/lib/cloud-api";
import { INTERVIEW_PERSONAS, type InterviewPersona } from "@/lib/interview/personas";
import { toast } from "sonner";

export function PersonaManagement() {
  const setView = useApp((s) => s.setView);
  const savedPersonas = useApp((s) => s.interviewPersonas);
  const saveInterviewPersonas = useApp((s) => s.saveInterviewPersonas);
  // Local working copy — "Save Personas" commits it to the store + D1.
  const [personas, setPersonas] = useState<InterviewPersona[]>(savedPersonas);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);

  const dirty = JSON.stringify(personas) !== JSON.stringify(savedPersonas);

  const update = (id: string, patch: Partial<InterviewPersona>) =>
    setPersonas((ps) => ps.map((p) => (p.id === id ? { ...p, ...patch } : p)));

  const handleSave = async () => {
    setSaving(true);
    try {
      // Awaited PUT — the toast only shows once D1 actually has the data.
      await cloudApi.updateBranding({ interviewPersonas: personas });
      saveInterviewPersonas(personas); // store state (+ idempotent fire-and-forget sync)
      toast.success("Personas saved — they survive refresh now.");
    } catch {
      toast.error("Save failed — check your connection and try again.");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-3">
        <Button variant="ghost" size="icon" onClick={() => setView("super-admin")} aria-label="Back">
          <Icon name="ArrowLeft" className="w-4 h-4" />
        </Button>
        <div>
          <h1 className="font-display text-2xl font-bold">Persona Management</h1>
          <p className="text-sm text-muted-foreground">{personas.length} interviewer personas · click "Save Personas" to persist.</p>
        </div>
        <Button
          onClick={handleSave}
          disabled={!dirty || saving}
          className="bg-brand hover:bg-brand-dark text-white gap-2"
        >
          <Icon name="Save" className="w-4 h-4" /> {saving ? "Saving…" : "Save Personas"}
        </Button>
      </div>
      {dirty && (
        <div className="flex items-center gap-2 rounded-lg border border-amber-300/50 bg-amber-100/40 px-3 py-2 text-sm text-amber-800 dark:bg-amber-400/5 dark:text-amber-200">
          <Icon name="AlertTriangle" className="w-4 h-4 shrink-0" />
          You have unsaved changes. Click "Save Personas" to apply them everywhere.
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {personas.map((p) => {
          const editing = editingId === p.id;
          return (
            <Card key={p.id}>
              <CardHeader className="flex-row items-center gap-3 space-y-0">
                <span className="w-9 h-9 rounded-lg flex items-center justify-center" style={{ background: `${p.accent}1a`, color: p.accent }}>
                  <Icon name={p.icon as any} className="w-5 h-5" />
                </span>
                <div className="min-w-0">
                  <CardTitle className="text-base truncate">{p.name}</CardTitle>
                  <CardDescription className="truncate">{p.role}</CardDescription>
                </div>
              </CardHeader>
              <CardContent className="space-y-2">
                <div className="flex flex-wrap gap-1">
                  <Badge>{p.category}</Badge>
                  {p.focusAreas.slice(0, 3).map((f) => <Badge key={f} variant="outline">{f}</Badge>)}
                </div>
                {editing ? (
                  <>
                    <label className="text-xs text-muted-foreground">Role</label>
                    <Input value={p.role} onChange={(e) => update(p.id, { role: e.target.value })} />
                    <label className="text-xs text-muted-foreground">Focus areas (comma separated)</label>
                    <Input
                      value={p.focusAreas.join(", ")}
                      onChange={(e) => update(p.id, { focusAreas: e.target.value.split(",").map((s) => s.trim()).filter(Boolean) })}
                    />
                    <Button size="sm" className="w-full" onClick={() => setEditingId(null)}>Done</Button>
                  </>
                ) : (
                  <Button size="sm" variant="outline" className="w-full" onClick={() => setEditingId(p.id)}>
                    <Icon name="Pencil" className="w-4 h-4 mr-2" /> Edit
                  </Button>
                )}
              </CardContent>
            </Card>
          );
        })}
      </div>
    </div>
  );
}

src/components/app/modules/PipelineProfi:
"use client";

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Badge, Icon } from "@/components/shared";
import { useApp } from "@/lib/store";
import { SEED_PIPELINE_PROFILES } from "@/lib/pipeline-orchestration-seeds";
import { UnsavedBanner } from "./unsaved-changes";
import { toast } from "sonner";
import type { PipelineProfile, PipelineProfileType } from "@/lib/pipeline-orchestration-types";

export function PipelineProfiles() {
  const profiles = useApp((s) => s.pipelineProfiles);
  const selectedProfileId = useApp((s) => s.selectedProfileId);
  const selectProfile = useApp((s) => s.selectPipelineProfile);
  const updateProfile = useApp((s) => s.updatePipelineProfile);
  const addProfile = useApp((s) => s.addPipelineProfile);
  const removeProfile = useApp((s) => s.removePipelineProfile);
  const reset = useApp((s) => s.resetPipelineOrchestration);

  const [editingProfile, setEditingProfile] = useState<PipelineProfile | null>(null);

  const selectedProfile = profiles.find((p) => p.id === selectedProfileId);

  // The profile editor works on a local copy; nothing reaches the store (and
  // from there D1) until "Save Profile" commits it. Snapshot-compare against
  // the stored version so the indicator only appears once a field changes.
  const profileDirty = !!editingProfile &&
    JSON.stringify(editingProfile) !== JSON.stringify(profiles.find((p) => p.id === editingProfile.id));

  const handleSelect = (id: string) => {
    selectProfile(id);
    const profile = profiles.find((p) => p.id === id);
    toast.success(`Pipeline profile changed to "${profile?.name}". All pipelines will now use this profile.`);
  };

  const handleCreateCustom = () => {
    const newProfile: PipelineProfile = {
      id: `profile-custom-${Date.now()}`,
      name: "Custom Profile",
      description: "User-defined pipeline profile with full manual configuration.",
      type: "custom" as PipelineProfileType,
      enabledAgents: selectedProfile?.enabledAgents || [],
      parallelGroups: selectedProfile?.parallelGroups || [],
      enableV3PostOptimization: true,
      useLockedPipeline: true,
      enableTargetedRegeneration: true,
      matchingStrategy: "hybrid",
      hybridMatchingThreshold: 75,
      maxRetries: 4,
      validationThresholds: selectedProfile?.validationThresholds || {
        minAtsScore: 70, minFactualConsistency: 95, minKeywordCoverage: 65,
        minHtmlValidation: 90, minGrammarScore: 90, minRecruiterReadability: 85,
        minSemanticSimilarity: 80, minConfidenceScore: 80, minQualityScore: 85,
        enforceOnePage: true,
      },
      isBuiltIn: false,
      isDefault: false,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };
    addProfile(newProfile);
    setEditingProfile(newProfile);
    toast.success("Custom profile created. Edit the fields below and save.");
  };

  const handleSaveEdit = () => {
    if (!editingProfile) return;
    updateProfile(editingProfile.id, editingProfile);
    setEditingProfile(null);
    toast.success("Profile saved.");
  };

  const handleReset = () => {
    if (!confirm("Reset ALL pipeline orchestration to factory defaults? This includes profiles, agent configs, and prompt versions.")) return;
    reset();
    setEditingProfile(null);
    toast.success("Pipeline orchestration reset to factory defaults.");
  };

  const profileTypeColors: Record<string, string> = {
    "legacy-v2": "#6B7280",
    "legacy-v3": "#0EA5E9",
    "locked": "#10B981",
    "hybrid": "#6366F1",
    "agentic-turbo": "#F97316",
    "agentic-sentinel": "#8B5CF6",
    "custom": "#F59E0B",
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-start justify-between flex-wrap gap-3">
        <div>
          <h1 className="font-display text-2xl font-bold flex items-center gap-2">
            <Icon name="Workflow" className="w-6 h-6 text-brand" /> Pipeline Profiles
          </h1>
          <p className="text-sm text-muted-foreground mt-1">
            Select a predefined orchestration strategy or create a custom profile. The Supervisor Agent loads the selected profile at runtime and builds the execution plan dynamically.
          </p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" onClick={handleReset} className="gap-2 text-destructive hover:text-destructive">
            <Icon name="Trash2" className="w-4 h-4" /> Reset All
          </Button>
          <Button onClick={handleCreateCustom} className="bg-brand hover:bg-brand-dark text-white gap-2">
            <Icon name="Plus" className="w-4 h-4" /> Create Custom
          </Button>
        </div>
      </div>

      {/* Profile cards */}
      <div className="grid gap-4 md:grid-cols-2">
        {profiles.map((profile) => (
          <Card
            key={profile.id}
            className={`cursor-pointer transition-all hover:shadow-premium ${
              selectedProfileId === profile.id ? "ring-2 ring-brand border-brand" : ""
            }`}
            onClick={() => handleSelect(profile.id)}
          >
            <CardHeader>
              <div className="flex items-start justify-between">
                <div>
                  <CardTitle className="text-lg flex items-center gap-2">
                    {profile.name}
                    {selectedProfileId === profile.id && (
                      <Badge variant="brand" className="text-[10px]">ACTIVE</Badge>
                    )}
                    {profile.isDefault && (
                      <Badge variant="outline" className="text-[10px]">RECOMMENDED</Badge>
                    )}
                  </CardTitle>
                  <CardDescription className="mt-1">{profile.description}</CardDescription>
                </div>
                <div
                  className="w-3 h-3 rounded-full mt-1"
                  style={{ backgroundColor: profileTypeColors[profile.type] || "#6B7280" }}
                />
              </div>
            </CardHeader>
            <CardContent className="space-y-2">
              <div className="flex flex-wrap gap-1.5">
                <Badge variant="outline" className="text-[10px]">
                  {profile.useLockedPipeline ? "Locked Pipeline" : "Legacy Pipeline"}
                </Badge>
                <Badge variant="outline" className="text-[10px]">
                  V3: {profile.enableV3PostOptimization ? "ON" : "OFF"}
                </Badge>
                <Badge variant="outline" className="text-[10px]">
                  Regeneration: {profile.enableTargetedRegeneration ? "ON" : "OFF"}
                </Badge>
                <Badge variant="outline" className="text-[10px]">
                  Matching: {profile.matchingStrategy}
                </Badge>
                <Badge variant="outline" className="text-[10px]">
                  Retries: {profile.maxRetries}
                </Badge>
              </div>
              <div className="flex items-center justify-between pt-2">
                <span className="text-xs text-muted-foreground">
                  {profile.enabledAgents.length} agents · {profile.parallelGroups.length} stages
                </span>
                {!profile.isBuiltIn && (
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={(e) => {
                      e.stopPropagation();
                      setEditingProfile(profile);
                    }}
                    className="h-7 text-xs"
                  >
                    <Icon name="Pencil" className="w-3 h-3 mr-1" /> Edit
                  </Button>
                )}
                {/* Clone: built-in profiles are read-only by design, but the info
                    card promises they "can be cloned to create custom profiles".
                    This is that entry point — deep-copies the profile as a new
                    custom one and opens the editor. */}
                {profile.isBuiltIn && (
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={(e) => {
                      e.stopPropagation();
                      const clone: PipelineProfile = JSON.parse(JSON.stringify(profile));
                      clone.id = `profile-custom-${Date.now()}`;
                      clone.name = `${profile.name} (Custom)`;
                      clone.description = `Custom copy of "${profile.name}". Fully editable.`;
                      clone.isBuiltIn = false;
                      clone.isDefault = false;
                      clone.createdAt = new Date().toISOString();
                      clone.updatedAt = new Date().toISOString();
                      addProfile(clone);
                      setEditingProfile(clone);
                      toast.success(`"${profile.name}" cloned as a custom profile. Edit and save below.`);
                    }}
                    className="h-7 text-xs"
                  >
                    <Icon name="Copy" className="w-3 h-3 mr-1" /> Clone
                  </Button>
                )}
                {!profile.isBuiltIn && (
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={(e) => {
                      e.stopPropagation();
                      removeProfile(profile.id);
                      toast.success("Custom profile removed.");
                    }}
                    className="h-7 text-xs text-destructive hover:text-destructive"
                  >
                    <Icon name="Trash2" className="w-3 h-3" />
                  </Button>
                )}
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Edit modal for custom profiles */}
      {editingProfile && (
        <Card className="border-brand">
          <CardHeader>
            <CardTitle className="text-lg flex items-center gap-2">
              <Icon name="Pencil" className="w-4 h-4 text-brand" /> Edit: {editingProfile.name}
            </CardTitle>
            <CardDescription>Configure the custom pipeline profile.</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {profileDirty && (
              <UnsavedBanner saveLabel="Save Profile">
                You have unsaved profile changes — click &quot;Save Profile&quot; to commit them, or &quot;Cancel&quot; to discard.
              </UnsavedBanner>
            )}
            <div className="grid sm:grid-cols-2 gap-3">
              <div>
                <Label>Profile Name</Label>
                <Input
                  value={editingProfile.name}
                  onChange={(e) => setEditingProfile({ ...editingProfile, name: e.target.value })}
                  className="mt-1"
                />
              </div>
              <div>
                <Label>Description</Label>
                <Input
                  value={editingProfile.description}
                  onChange={(e) => setEditingProfile({ ...editingProfile, description: e.target.value })}
                  className="mt-1"
                />
              </div>
            </div>

            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <div>
                  <Label>Use Locked Pipeline</Label>
                  <p className="text-xs text-muted-foreground">Bullet-only optimizer + Resume Assembler. LLM cannot generate full resume.</p>
                </div>
                <Switch
                  checked={editingProfile.useLockedPipeline}
                  onCheckedChange={(v) => setEditingProfile({ ...editingProfile, useLockedPipeline: v })}
                />
              </div>
              <div className="flex items-center justify-between">
                <div>
                  <Label>Enable V3 Post-Optimization</Label>
                  <p className="text-xs text-muted-foreground">Keyword Embedding, Fact Verification, Layout Optimization agents.</p>
                </div>
                <Switch
                  checked={editingProfile.enableV3PostOptimization}
                  onCheckedChange={(v) => setEditingProfile({ ...editingProfile, enableV3PostOptimization: v })}
                />
              </div>
              <div className="flex items-center justify-between">
                <div>
                  <Label>Enable Targeted Regeneration</Label>
                  <p className="text-xs text-muted-foreground">Re-run only failed sections instead of the entire resume.</p>
                </div>
                <Switch
                  checked={editingProfile.enableTargetedRegeneration}
                  onCheckedChange={(v) => setEditingProfile({ ...editingProfile, enableTargetedRegeneration: v })}
                />
              </div>
            </div>

            <div className="grid sm:grid-cols-2 gap-3">
              <div>
                <Label>Matching Strategy</Label>
                <select
                  value={editingProfile.matchingStrategy}
                  onChange={(e) => setEditingProfile({ ...editingProfile, matchingStrategy: e.target.value as any })}
                  className="w-full h-9 px-3 rounded-md border border-input bg-background text-sm mt-1"
                >
                  <option value="strict">Strict (ID only)</option>
                  <option value="hybrid">Hybrid (ID → fingerprint → title/company)</option>
                  <option value="fuzzy">Fuzzy (includes index fallback)</option>
                </select>
              </div>
              <div>
                <Label>Hybrid Matching Threshold: {editingProfile.hybridMatchingThreshold}</Label>
                <input
                  type="range"
                  min={50}
                  max={100}
                  step={5}
                  value={editingProfile.hybridMatchingThreshold}
                  onChange={(e) => setEditingProfile({ ...editingProfile, hybridMatchingThreshold: parseInt(e.target.value) })}
                  className="w-full mt-3"
                />
              </div>
            </div>

            <div>
              <Label>Max Retries: {editingProfile.maxRetries}</Label>
              <input
                type="range"
                min={1}
                max={6}
                step={1}
                value={editingProfile.maxRetries}
                onChange={(e) => setEditingProfile({ ...editingProfile, maxRetries: parseInt(e.target.value) })}
                className="w-full mt-2"
              />
            </div>

            <div className="flex justify-end gap-2 pt-2">
              <Button variant="outline" onClick={() => setEditingProfile(null)}>Cancel</Button>
              <Button onClick={handleSaveEdit} className="bg-brand hover:bg-brand-dark text-white gap-2">
                <Icon name="Save" className="w-4 h-4" /> Save Profile
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Info card */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg flex items-center gap-2"><Icon name="Info" className="w-4 h-4 text-brand" /> How Profiles Work</CardTitle>
        </CardHeader>
        <CardContent className="space-y-2 text-sm text-muted-foreground">
          <p>1. The Supervisor Agent loads the selected profile at the start of each pipeline run.</p>
          <p>2. The profile is LIVE — it decides the locked pipeline, optimizer retry attempts, V3 post-optimization agents, targeted regeneration, assembler matching strategy, and the QA reflection threshold.</p>
          <p>3. Built-in profiles (Legacy V2, Legacy V3, Locked, Hybrid, Agentic Turbo, Agentic Sentinel) are read-only but can be cloned to create custom profiles.</p>
          <p>4. Custom profiles are fully editable and persisted to D1.</p>
          <p>5. Changes take effect immediately — no restart required. The profile (and its updatedAt) is part of the Supervisor's result-cache key, so edits always apply to the next run.</p>
          <p>6. Per-agent configuration (provider, model, temperature, prompts, retry, fallback) is available in the Agent Configuration Center.</p>
          <p className="flex items-start gap-1.5 pt-1 text-foreground">
            <Icon name="ShieldCheck" className="w-4 h-4 text-brand shrink-0 mt-0.5" />
            <span><span className="font-semibold">AI governance:</span> during Resume Optimization the provider+model are decided exclusively by the AI Readiness Gate lock (TEST FIRST → SELECT BEST → LOCK); the profile governs pipeline architecture, and per-agent provider/model preferences from the Agent Configuration Center apply only to non-locked runs.</span>
          </p>
        </CardContent>
      </Card>
    </div>
  );
}

