/**
 * Task 27 — AI Providers table must auto-fit its frame layer (no horizontal scroll).
 *
 * Live evidence (2026-08-31 user report): the 10-column provider table inside
 * AIProviders.tsx required horizontal scrolling on every desktop width because
 * (a) the table used auto layout with an unwrappable badge row, (b) every cell
 * carried px-4 padding, (c) 6 icon action buttons, and (d) no column was
 * breakpoint-gated. The app frame caps at ~1352px (main max-w-[1400px] − p-6),
 * while the table's natural min-width was ~1550px → permanent inner scroll.
 *
 * The fix contract (pure module provider-table-layout.ts):
 *  1. table-fixed layout — the table can NEVER exceed its container width.
 *  2. Breakpoint column disclosure — low-priority columns appear only when the
 *     frame is wide enough (xl = 1280, 2xl = 1536 viewport).
 *  3. A width budget that is verified arithmetically: fixed columns + cell
 *     padding + minimum flexible shares must fit the frame cap at every
 *     breakpoint where the visible set is shown.
 */

import { describe, it, expect } from "vitest";
import {
  PROVIDER_TABLE_COLUMNS,
  PROVIDER_TABLE_CELL_PADDING_PX,
  PROVIDER_TABLE_FRAME_CAP_PX,
  PROVIDER_TABLE_FLEXIBLE_MIN_PX,
  providerTableWidthBudget,
} from "./provider-table-layout";

const ALL_KEYS = [
  "provider",
  "type",
  "baseUrl",
  "model",
  "status",
  "priority",
  "concurrency",
  "requests",
  "lastUsed",
  "actions",
] as const;

describe("provider table layout contract (Task 27: auto-fit, no horizontal scroll)", () => {
  it("declares exactly the 10 columns in display order", () => {
    expect(PROVIDER_TABLE_COLUMNS.map((c) => c.key)).toEqual([...ALL_KEYS]);
  });

  it("keeps the 5 core columns visible at every viewport width", () => {
    const alwaysVisible = PROVIDER_TABLE_COLUMNS.filter((c) => c.visibleFrom === null);
    expect(alwaysVisible.map((c) => c.key).sort()).toEqual(
      ["actions", "concurrency", "model", "provider", "status"].sort()
    );
  });

  it("gates wide/low-priority columns behind xl and 2xl breakpoints", () => {
    const byKey = Object.fromEntries(PROVIDER_TABLE_COLUMNS.map((c) => [c.key, c]));
    // Priority + usage trivia appear from xl (1280px viewport)
    expect(byKey.priority.visibleFrom).toBe("xl");
    expect(byKey.requests.visibleFrom).toBe("xl");
    expect(byKey.lastUsed.visibleFrom).toBe("xl");
    // Widest reference columns appear only from 2xl (1536px viewport)
    expect(byKey.type.visibleFrom).toBe("2xl");
    expect(byKey.baseUrl.visibleFrom).toBe("2xl");
  });

  it("every gated column carries a `hidden …:table-cell` visibility class for th AND td", () => {
    for (const col of PROVIDER_TABLE_COLUMNS) {
      if (col.visibleFrom === null) {
        expect(col.thVisibilityClass, col.key).toBe("");
        expect(col.tdVisibilityClass, col.key).toBe("");
      } else {
        expect(col.thVisibilityClass, col.key).toBe(`hidden ${col.visibleFrom}:table-cell`);
        expect(col.tdVisibilityClass, col.key).toBe(`hidden ${col.visibleFrom}:table-cell`);
      }
    }
  });

  it("action column is wide enough for 6 icon buttons (24px) + gaps + cell padding", () => {
    const actions = PROVIDER_TABLE_COLUMNS.find((c) => c.key === "actions")!;
    // 6 × 24px buttons + 5 × 2px gaps (gap-0.5) + 24px cell padding (px-3)
    const required = 6 * 24 + 5 * 2 + PROVIDER_TABLE_CELL_PADDING_PX;
    expect(actions.fixedWidthPx).toBeGreaterThanOrEqual(required);
  });

  it("arithmetic budget: fixed columns + padding + minimum flexible shares fit the frame cap at every tier", () => {
    for (const viewport of ["base", "xl", "2xl"] as const) {
      const budget = providerTableWidthBudget(viewport);
      const needed =
        budget.fixedPx + budget.paddingPx + budget.flexibleColumns * 0 + PROVIDER_TABLE_FLEXIBLE_MIN_PX.provider + PROVIDER_TABLE_FLEXIBLE_MIN_PX.model;
      expect(
        needed,
        `${viewport}: fixed ${budget.fixedPx} + padding ${budget.paddingPx} + flexible minimums ${PROVIDER_TABLE_FLEXIBLE_MIN_PX.provider + PROVIDER_TABLE_FLEXIBLE_MIN_PX.model} must be ≤ frame cap ${PROVIDER_TABLE_FRAME_CAP_PX}`
      ).toBeLessThanOrEqual(PROVIDER_TABLE_FRAME_CAP_PX);
    }
  });

  it("arithmetic budget: flexible columns keep a usable share at the xl tier (8 visible columns)", () => {
    const budget = providerTableWidthBudget("xl");
    expect(budget.visibleColumns).toBe(8);
    const flexibleShare =
      PROVIDER_TABLE_FRAME_CAP_PX - budget.fixedPx - budget.paddingPx -
      PROVIDER_TABLE_FLEXIBLE_MIN_PX.provider - PROVIDER_TABLE_FLEXIBLE_MIN_PX.model;
    // At xl the two flexible columns must still have their minimums covered
    expect(flexibleShare).toBeGreaterThanOrEqual(0);
  });

  it("base tier shows only the 5 core columns (tablet / half-split windows stay compact)", () => {
    const budget = providerTableWidthBudget("base");
    expect(budget.visibleColumns).toBe(5);
  });
});

/**
 * Task 27 — AI Providers table responsive auto-fit contract.
 *
 * Problem (user report 2026-08-31): the 10-column provider table required
 * horizontal scrolling inside its card frame at every desktop width. The app
 * frame is capped: `main` = max-w-[1400px] with p-6 → ~1352px of usable table
 * width at most, while the table's natural min-width (10 × px-4 cells, an
 * unwrappable name+badge row, six 28px action buttons, unclamped URLs) was
 * ~1550px — so `overflow-x-auto` scrolled forever.
 *
 * Fix strategy (pure, testable contract consumed by AIProviders.tsx):
 *  1. `table-fixed w-full` on the <table> — the table can never exceed the
 *     container; over-long cell content truncates (with `title` tooltips)
 *     instead of pushing columns wider.
 *  2. Breakpoint column disclosure — the widest / least-critical columns are
 *     hidden below Tailwind xl (1280px) and 2xl (1536px) viewports:
 *       - always (5 core): provider, model, status, concurrency, actions
 *       - xl+ (+3): priority, requests, last used
 *       - 2xl+ (+2): type, base URL (full 10-column table)
 *  3. Verified width budget — fixed column widths + cell padding + minimum
 *     flexible shares for provider/model must fit the 1352px frame cap at
 *     every tier; `providerTableWidthBudget()` makes that arithmetic
 *     checkable (see provider-table-layout.test.ts).
 */

/** Horizontal padding of every td/th: Tailwind px-3 = 12px per side. */
export const PROVIDER_TABLE_CELL_PADDING_PX = 24;

/**
 * Usable table width cap: `main` max-w-[1400px] minus its p-6 horizontal
 * padding (48px). The table can never be wider than this in the app shell.
 */
export const PROVIDER_TABLE_FRAME_CAP_PX = 1400 - 48;

/** Minimum usable widths for the two flexible (no fixed width) columns. */
export const PROVIDER_TABLE_FLEXIBLE_MIN_PX = { provider: 160, model: 150 } as const;

export type ProviderColumnKey =
  | "provider"
  | "type"
  | "baseUrl"
  | "model"
  | "status"
  | "priority"
  | "concurrency"
  | "requests"
  | "lastUsed"
  | "actions";

export type ProviderColumnVisibility = "xl" | "2xl" | null;

export interface ProviderTableColumn {
  key: ProviderColumnKey;
  label: string;
  /**
   * Visibility utility classes. Applied verbatim to the <th> and to the
   * matching <td> so both disappear together below the breakpoint.
   */
  thVisibilityClass: string;
  tdVisibilityClass: string;
  /** Fixed width in px for table-fixed layout; null = flexible (shares the remaining space with the other flexible column). */
  fixedWidthPx: number | null;
  /** Literal Tailwind width utility applied to the <th> (table-fixed reads widths from the header row). Empty for flexible columns. */
  widthClass: string;
  /** Viewport breakpoint from which the column is visible; null = always visible. */
  visibleFrom: ProviderColumnVisibility;
}

/**
 * Column layout for the AI Providers table, in display order.
 * Widths are hand-budgeted against PROVIDER_TABLE_FRAME_CAP_PX — see
 * providerTableWidthBudget() and the arithmetic tests.
 */
export const PROVIDER_TABLE_COLUMNS: ProviderTableColumn[] = [
  {
    key: "provider",
    label: "Provider",
    thVisibilityClass: "",
    tdVisibilityClass: "",
    fixedWidthPx: null, // flexible
    widthClass: "",
    visibleFrom: null,
  },
  {
    key: "type",
    label: "Type",
    thVisibilityClass: "hidden 2xl:table-cell",
    tdVisibilityClass: "hidden 2xl:table-cell",
    fixedWidthPx: 72,
    widthClass: "w-[72px]",
    visibleFrom: "2xl",
  },
  {
    key: "baseUrl",
    label: "Base URL",
    thVisibilityClass: "hidden 2xl:table-cell",
    tdVisibilityClass: "hidden 2xl:table-cell",
    fixedWidthPx: 160,
    widthClass: "w-[160px]",
    visibleFrom: "2xl",
  },
  {
    key: "model",
    label: "Model",
    thVisibilityClass: "",
    tdVisibilityClass: "",
    fixedWidthPx: null, // flexible
    widthClass: "",
    visibleFrom: null,
  },
  {
    key: "status",
    label: "Status",
    thVisibilityClass: "",
    tdVisibilityClass: "",
    fixedWidthPx: 80,
    widthClass: "w-20",
    visibleFrom: null,
  },
  {
    key: "priority",
    label: "Priority",
    thVisibilityClass: "hidden xl:table-cell",
    tdVisibilityClass: "hidden xl:table-cell",
    fixedWidthPx: 56,
    widthClass: "w-14",
    visibleFrom: "xl",
  },
  {
    key: "concurrency",
    label: "Concurrency",
    thVisibilityClass: "",
    tdVisibilityClass: "",
    fixedWidthPx: 112,
    widthClass: "w-28",
    visibleFrom: null,
  },
  {
    key: "requests",
    label: "Requests",
    thVisibilityClass: "hidden xl:table-cell",
    tdVisibilityClass: "hidden xl:table-cell",
    fixedWidthPx: 64,
    widthClass: "w-16",
    visibleFrom: "xl",
  },
  {
    key: "lastUsed",
    label: "Last used",
    thVisibilityClass: "hidden xl:table-cell",
    tdVisibilityClass: "hidden xl:table-cell",
    fixedWidthPx: 72,
    widthClass: "w-[72px]",
    visibleFrom: "xl",
  },
  {
    key: "actions",
    label: "Actions",
    thVisibilityClass: "",
    tdVisibilityClass: "",
    // 6 × 24px icon buttons + 5 × 2px gaps (gap-0.5) + 24px cell padding
    fixedWidthPx: 184,
    widthClass: "w-[184px]",
    visibleFrom: null,
  },
];

export type ProviderTableTier = "base" | "xl" | "2xl";

/** Tailwind viewport widths for the disclosure breakpoints. */
const TIER_VIEWPORT_PX: Record<Exclude<ProviderColumnVisibility, null>, number> = {
  xl: 1280,
  "2xl": 1536,
};

/**
 * Width budget for a disclosure tier. `base` models any viewport below xl —
 * the conservative case (narrowest realistic desktop frame ≈ 1024px minus
 * sidebar, but the arithmetic below checks against the frame cap, which is
 * only reached at 2xl; smaller viewports simply show fewer columns and
 * table-fixed clamps the rest).
 */
export function providerTableWidthBudget(tier: ProviderTableTier): {
  visibleColumns: number;
  fixedPx: number;
  paddingPx: number;
  flexibleColumns: number;
} {
  // A column is visible in this tier when its breakpoint ≤ the tier's viewport
  // (base = 0 → only the always-visible core set).
  const tierViewport = tier === "base" ? 0 : TIER_VIEWPORT_PX[tier];
  const visibleColumns = PROVIDER_TABLE_COLUMNS.filter(
    (c) => c.visibleFrom === null || TIER_VIEWPORT_PX[c.visibleFrom] <= tierViewport
  );
  const fixedPx = visibleColumns.reduce((sum, c) => sum + (c.fixedWidthPx ?? 0), 0);
  return {
    visibleColumns: visibleColumns.length,
    fixedPx,
    paddingPx: visibleColumns.length * PROVIDER_TABLE_CELL_PADDING_PX,
    flexibleColumns: visibleColumns.filter((c) => c.fixedWidthPx === null).length,
  };
}

src/components/app/modules/ProviderAnaly:
"use client";

import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Badge, Icon } from "@/components/shared";
import { useApp } from "@/lib/store";
import { ProviderManager } from "@/lib/ai/services";
import {
  AreaChart, Area, BarChart, Bar, PieChart, Pie, Cell,
  XAxis, YAxis, Tooltip, ResponsiveContainer, Legend,
} from "recharts";

const PROVIDER_COLORS = ["#1154A3", "#F59E0B", "#10B981", "#8B5CF6", "#EC4899", "#0EA5E9", "#DC2626", "#94A3B8"];

export function ProviderAnalytics() {
  const providers = useApp((s) => s.providers);
  const logs = useApp((s) => s.providerLogs);

  const agg = ProviderManager.aggregateUsage();

  // Build chart data
  const requestsPerProvider = providers
    .filter((p) => p.usage.requests > 0)
    .map((p) => ({ name: p.name.split(" ")[0], requests: p.usage.requests, tokens: p.usage.tokens, errors: p.usage.errors, cost: p.usage.cost, color: PROVIDER_COLORS[providers.indexOf(p) % PROVIDER_COLORS.length] }));

  // Success vs error pie
  const successErrors = [
    { name: "Success", value: agg.requests - agg.errors, color: "#10B981" },
    { name: "Errors", value: agg.errors, color: "#DC2626" },
  ].filter((d) => d.value > 0);

  // Latency per provider
  const latencyPerProvider = providers
    .filter((p) => p.usage.requests > 0)
    .map((p) => ({ name: p.name.split(" ")[0], latency: p.usage.avgLatencyMs }));

  // Token usage over last logs (last 7 days)
  const last7Days = Array.from({ length: 7 }).map((_, i) => {
    const d = new Date();
    d.setDate(d.getDate() - (6 - i));
    const dayLogs = logs.filter((l) => {
      const ld = new Date(l.createdAt);
      return ld.toDateString() === d.toDateString();
    });
    return {
      name: d.toLocaleDateString("en-US", { weekday: "short" }),
      requests: dayLogs.length,
      tokens: dayLogs.reduce((n, l) => n + (l.inputTokens ?? 0) + (l.outputTokens ?? 0), 0),
    };
  });

  return (
    <div className="space-y-6">
      {/* KPIs */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
        {[
          { label: "Total requests", value: agg.requests.toLocaleString(), icon: "Activity", color: "#1154A3" },
          { label: "Success rate", value: `${agg.successRate.toFixed(1)}%`, icon: "CheckCircle2", color: "#10B981" },
          { label: "Error rate", value: `${agg.errorRate.toFixed(1)}%`, icon: "AlertCircle", color: "#DC2626" },
          { label: "Avg latency", value: `${agg.avgLatencyMs}ms`, icon: "Timer", color: "#F59E0B" },
          { label: "Total tokens", value: agg.tokens.toLocaleString(), icon: "Coins", color: "#8B5CF6" },
          { label: "Est. cost", value: `$${agg.cost.toFixed(4)}`, icon: "DollarSign", color: "#EC4899" },
        ].map((s) => (
          <Card key={s.label}>
            <CardContent className="p-4 flex items-center gap-3">
              <div className="w-9 h-9 rounded-lg flex items-center justify-center shrink-0" style={{ background: `${s.color}15`, color: s.color }}>
                <Icon name={s.icon} className="w-4 h-4" />
              </div>
              <div className="min-w-0">
                <div className="text-lg font-bold font-display truncate">{s.value}</div>
                <div className="text-xs text-muted-foreground truncate">{s.label}</div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      <div className="grid lg:grid-cols-2 gap-6">
        {/* Requests per provider */}
        <Card>
          <CardHeader><CardTitle className="text-base">Requests per provider</CardTitle><CardDescription>Total requests by provider.</CardDescription></CardHeader>
          <CardContent>
            {requestsPerProvider.length > 0 ? (
              <div style={{ width: "100%", height: 240 }}>
                <ResponsiveContainer>
                  <BarChart data={requestsPerProvider} margin={{ top: 5, right: 5, bottom: 0, left: -20 }}>
                    <XAxis dataKey="name" tick={{ fontSize: 11 }} stroke="#94A3B8" />
                    <YAxis tick={{ fontSize: 11 }} stroke="#94A3B8" />
                    <Tooltip contentStyle={{ borderRadius: 8, fontSize: 12 }} />
                    <Bar dataKey="requests" radius={[4, 4, 0, 0]}>
                      {requestsPerProvider.map((d, i) => <Cell key={i} fill={d.color} />)}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </div>
            ) : <EmptyChart />}
          </CardContent>
        </Card>

        {/* Success vs error */}
        <Card>
          <CardHeader><CardTitle className="text-base">Success vs errors</CardTitle><CardDescription>Across all providers.</CardDescription></CardHeader>
          <CardContent>
            {successErrors.length > 0 ? (
              <div style={{ width: "100%", height: 240 }}>
                <ResponsiveContainer>
                  <PieChart>
                    <Pie data={successErrors} dataKey="value" nameKey="name" innerRadius={50} outerRadius={80} paddingAngle={2}>
                      {successErrors.map((d) => <Cell key={d.name} fill={d.color} />)}
                    </Pie>
                    <Tooltip contentStyle={{ borderRadius: 8, fontSize: 12 }} />
                    <Legend wrapperStyle={{ fontSize: 12 }} />
                  </PieChart>
                </ResponsiveContainer>
              </div>
            ) : <EmptyChart />}
          </CardContent>
        </Card>

        {/* Latency per provider */}
        <Card>
          <CardHeader><CardTitle className="text-base">Average latency per provider</CardTitle><CardDescription>Milliseconds — lower is better.</CardDescription></CardHeader>
          <CardContent>
            {latencyPerProvider.length > 0 ? (
              <div style={{ width: "100%", height: 240 }}>
                <ResponsiveContainer>
                  <BarChart data={latencyPerProvider} layout="vertical" margin={{ top: 5, right: 5, bottom: 0, left: 30 }}>
                    <XAxis type="number" tick={{ fontSize: 11 }} stroke="#94A3B8" unit="ms" />
                    <YAxis type="category" dataKey="name" tick={{ fontSize: 11 }} stroke="#94A3B8" width={80} />
                    <Tooltip contentStyle={{ borderRadius: 8, fontSize: 12 }} />
                    <Bar dataKey="latency" fill="#1154A3" radius={[0, 4, 4, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            ) : <EmptyChart />}
          </CardContent>
        </Card>

        {/* Token usage 7 days */}
        <Card>
          <CardHeader><CardTitle className="text-base">Token usage (last 7 days)</CardTitle><CardDescription>From request logs.</CardDescription></CardHeader>
          <CardContent>
            <div style={{ width: "100%", height: 240 }}>
              <ResponsiveContainer>
                <AreaChart data={last7Days} margin={{ top: 5, right: 5, bottom: 0, left: -10 }}>
                  <defs>
                    <linearGradient id="tok" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="0%" stopColor="#8B5CF6" stopOpacity={0.4} />
                      <stop offset="100%" stopColor="#8B5CF6" stopOpacity={0} />
                    </linearGradient>
                  </defs>
                  <XAxis dataKey="name" tick={{ fontSize: 11 }} stroke="#94A3B8" />
                  <YAxis tick={{ fontSize: 11 }} stroke="#94A3B8" />
                  <Tooltip contentStyle={{ borderRadius: 8, fontSize: 12 }} />
                  <Area type="monotone" dataKey="tokens" stroke="#8B5CF6" fill="url(#tok)" strokeWidth={2} />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Per-provider breakdown table */}
      <Card>
        <CardHeader><CardTitle className="text-base">Per-provider breakdown</CardTitle></CardHeader>
        <CardContent className="p-0">
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="border-b border-border bg-secondary/40">
                <tr className="text-left text-xs uppercase tracking-wide text-muted-foreground">
                  <th className="px-4 py-2 font-semibold">Provider</th>
                  <th className="px-4 py-2 font-semibold text-right">Requests</th>
                  <th className="px-4 py-2 font-semibold text-right">Tokens</th>
                  <th className="px-4 py-2 font-semibold text-right">Errors</th>
                  <th className="px-4 py-2 font-semibold text-right">Avg latency</th>
                  <th className="px-4 py-2 font-semibold text-right">Cost</th>
                </tr>
              </thead>
              <tbody>
                {providers.map((p) => (
                  <tr key={p.id} className="border-b border-border hover:bg-secondary/30">
                    <td className="px-4 py-2 font-medium">{p.name}</td>
                    <td className="px-4 py-2 text-right font-mono">{p.usage.requests.toLocaleString()}</td>
                    <td className="px-4 py-2 text-right font-mono">{p.usage.tokens.toLocaleString()}</td>
                    <td className="px-4 py-2 text-right font-mono text-red-600">{p.usage.errors.toLocaleString()}</td>
                    <td className="px-4 py-2 text-right font-mono">{p.usage.avgLatencyMs}ms</td>
                    <td className="px-4 py-2 text-right font-mono">${p.usage.cost.toFixed(4)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

function EmptyChart() {
  return (
    <div className="h-[240px] flex items-center justify-center text-sm text-muted-foreground">
      <div className="text-center">
        <Icon name="BarChart3" className="w-10 h-10 mx-auto text-muted-foreground/40" />
        <p className="mt-2">No usage data yet</p>
      </div>
    </div>
  );
}

src/components/app/modules/ProviderAuthC:
// ResumeAI Pro — Provider Auth Card
// UI component for Puter.js and Z.ai Direct OAuth authentication.
// Shows connection status, account info, models, session expiry,
// and provides Login/Refresh/Disconnect actions.
// Supports both Google OAuth and API Key authentication for Z.ai.

"use client";

import { useState, useEffect, useCallback } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Badge, Icon } from "@/components/shared";
import { toast } from "sonner";
import type { ProviderAuthStatus } from "@/lib/providers/interface";

interface ProviderAuthCardProps {
  /** Provider identifier */
  providerId: "puter" | "zai-direct";
  /** Display name */
  providerName: string;
  /** Icon name from lucide-react */
  iconName: string;
  /** Brand color for accents */
  brandColor: string;
  /** Description text */
  description: string;
  /** Available models when connected */
  models: string[];
  /** Current auth status */
  status: ProviderAuthStatus;
  /** Sign in handler */
  onLogin: () => Promise<void>;
  /** Google OAuth sign-in handler (optional, only for Z.ai) */
  onLoginWithGoogle?: () => Promise<void>;
  /** Complete Google login with API key handler */
  onCompleteGoogleLogin?: (apiKey: string) => Promise<void>;
  /** Get pending Google user info */
  pendingGoogleUser?: { email: string; sub: string; picture?: string } | null;
  /** Clear pending Google user */
  onClearPendingGoogleUser?: () => void;
  /** Refresh session handler */
  onRefresh: () => Promise<void>;
  /** Disconnect handler */
  onLogout: () => Promise<void>;
  /** Toggle shared admin account */
  onToggleShared?: (enabled: boolean) => Promise<void>;
}

export function ProviderAuthCard({
  providerId,
  providerName,
  iconName,
  brandColor,
  description,
  models,
  status,
  onLogin,
  onLoginWithGoogle,
  onCompleteGoogleLogin,
  pendingGoogleUser,
  onClearPendingGoogleUser,
  onRefresh,
  onLogout,
  onToggleShared,
}: ProviderAuthCardProps) {
  const [loading, setLoading] = useState<string | null>(null);
  const [googleApiKeyInput, setGoogleApiKeyInput] = useState("");
  const [showGoogleKeyPrompt, setShowGoogleKeyPrompt] = useState(false);

  // Show the Google API key prompt when there's a pending Google user
  useEffect(() => {
    if (pendingGoogleUser && !status.authenticated) {
      setShowGoogleKeyPrompt(true);
    }
  }, [pendingGoogleUser, status.authenticated]);

  const handleLogin = useCallback(async () => {
    setLoading("login");
    try {
      await onLogin();
      toast.success(`${providerName} connected successfully!`);
    } catch (e: any) {
      // Check if this is the special "Google auth succeeded, need API key" error
      if (e?.message?.startsWith("GOOGLE_AUTH_SUCCESS_NEED_API_KEY:")) {
        toast.info("Google sign-in successful! Now paste your Z.ai API key to complete the connection.", { duration: 6000 });
      } else {
        toast.error(e?.message || `Failed to connect ${providerName}`);
      }
    } finally {
      setLoading(null);
    }
  }, [onLogin, providerName]);

  const handleGoogleLogin = useCallback(async () => {
    if (!onLoginWithGoogle) return;
    setLoading("google");
    try {
      await onLoginWithGoogle();
      toast.success(`${providerName} connected via Google!`);
    } catch (e: any) {
      // Check if this is the special "need API key" error
      if (e?.message?.startsWith("GOOGLE_AUTH_SUCCESS_NEED_API_KEY:")) {
        toast.info("Google sign-in successful! Now paste your Z.ai API key below to complete the connection.", { duration: 8000 });
      } else {
        toast.error(e?.message || `Failed to sign in with Google for ${providerName}`);
      }
    } finally {
      setLoading(null);
    }
  }, [onLoginWithGoogle, providerName]);

  const handleCompleteGoogleLogin = useCallback(async () => {
    if (!onCompleteGoogleLogin || !googleApiKeyInput.trim()) {
      toast.error("Please paste your Z.ai API key.");
      return;
    }
    setLoading("google-complete");
    try {
      await onCompleteGoogleLogin(googleApiKeyInput.trim());
      toast.success(`${providerName} connected via Google OAuth! Your API key is now linked to your Google account for future auto-login.`);
      setGoogleApiKeyInput("");
      setShowGoogleKeyPrompt(false);
    } catch (e: any) {
      toast.error(e?.message || "Failed to connect Z.ai with Google.");
    } finally {
      setLoading(null);
    }
  }, [onCompleteGoogleLogin, googleApiKeyInput, providerName]);

  const handleRefresh = useCallback(async () => {
    setLoading("refresh");
    try {
      await onRefresh();
      toast.success(`${providerName} session refreshed.`);
    } catch (e: any) {
      toast.error(e?.message || `Failed to refresh ${providerName} session.`);
    } finally {
      setLoading(null);
    }
  }, [onRefresh, providerName]);

  const handleLogout = useCallback(async () => {
    if (!confirm(`Disconnect ${providerName}? You will need to sign in again to use it.`)) return;
    setLoading("logout");
    try {
      await onLogout();
      toast.success(`${providerName} disconnected.`);
      setShowGoogleKeyPrompt(false);
    } catch (e: any) {
      toast.error(e?.message || `Failed to disconnect ${providerName}.`);
    } finally {
      setLoading(null);
    }
  }, [onLogout, providerName]);

  const isConnected = status.connected && status.authenticated;
  const isExpired = status.expiresAt ? Date.now() >= status.expiresAt : false;
  const isExpiringSoon = status.expiresAt
    ? !isExpired && Date.now() >= status.expiresAt - 5 * 60 * 1000
    : false;

  // Format expiry time
  const expiryText = status.expiresAt
    ? new Date(status.expiresAt).toLocaleString([], {
        month: "short",
        day: "numeric",
        hour: "2-digit",
        minute: "2-digit",
      })
    : null;

  // Time until expiry
  const timeUntilExpiry = status.expiresAt
    ? (() => {
        const diff = status.expiresAt - Date.now();
        if (diff <= 0) return "Expired";
        if (diff < 60 * 1000) return `${Math.floor(diff / 1000)}s`;
        if (diff < 60 * 60 * 1000) return `${Math.floor(diff / 60 / 1000)}m`;
        if (diff < 24 * 60 * 60 * 1000) return `${Math.floor(diff / 60 / 60 / 1000)}h`;
        return `${Math.floor(diff / 24 / 60 / 60 / 1000)}d`;
      })()
    : null;

  return (
    <Card className={`overflow-hidden border-2 transition-colors ${isConnected ? "border-green-500/30" : "border-border"}`}>
      {/* Top accent bar */}
      <div className="h-1" style={{ background: isConnected ? "#10B981" : brandColor }} />

      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <CardTitle className="flex items-center gap-2 text-base">
            <div
              className="w-9 h-9 rounded-lg flex items-center justify-center shrink-0"
              style={{ background: `${brandColor}15`, color: brandColor }}
            >
              <Icon name={iconName} className="w-5 h-5" />
            </div>
            <div>
              <div className="font-display">{providerName}</div>
              <div className="text-xs font-normal text-muted-foreground">{description}</div>
            </div>
          </CardTitle>
          <div className="flex items-center gap-2">
            {/* Auth method badge */}
            {isConnected && status.authMethod && (
              <Badge variant="outline" className="text-[9px] gap-1">
                <Icon name={status.authMethod === "google_oauth" ? "Shield" : "Key"} className="w-2.5 h-2.5" />
                {status.authMethod === "google_oauth" ? "Google" : status.authMethod === "puter_oauth" ? "OAuth" : "API Key"}
              </Badge>
            )}
            {/* Status indicator */}
            <div className="flex items-center gap-1.5">
              <div
                className={`w-2.5 h-2.5 rounded-full ${
                  isConnected && !isExpired
                    ? "bg-green-500 shadow-[0_0_6px_rgba(16,185,129,0.5)]"
                    : isExpired
                      ? "bg-amber-500"
                      : "bg-muted-foreground/30"
                }`}
              />
              <span className="text-xs font-medium">
                {!isConnected ? "Not Connected" : isExpired ? "Session Expired" : isExpiringSoon ? "Expiring Soon" : "Connected"}
              </span>
            </div>
          </div>
        </div>
      </CardHeader>

      <CardContent className="space-y-4 pt-0">
        {/* Account info (when connected) */}
        {isConnected && (
          <div className="space-y-3">
            {/* Account email + Google avatar */}
            <div className="flex items-center gap-2 text-sm">
              {status.googlePicture ? (
                <img src={status.googlePicture} alt="" className="w-4 h-4 rounded-full" referrerPolicy="no-referrer" />
              ) : (
                <Icon name="User" className="w-4 h-4 text-muted-foreground" />
              )}
              <span className="text-muted-foreground">Account:</span>
              <span className="font-medium">{status.email || "Connected"}</span>
            </div>

            {/* Session expiry */}
            {expiryText && (
              <div className="flex items-center gap-2 text-sm">
                <Icon name="Clock" className="w-4 h-4 text-muted-foreground" />
                <span className="text-muted-foreground">Session expires:</span>
                <span className={`font-medium ${isExpired ? "text-red-500" : isExpiringSoon ? "text-amber-500" : ""}`}>
                  {expiryText}
                  {timeUntilExpiry && !isExpired && (
                    <span className="text-muted-foreground font-normal ml-1">({timeUntilExpiry} remaining)</span>
                  )}
                </span>
              </div>
            )}

            {/* Available models */}
            {models.length > 0 && (
              <div className="space-y-1.5">
                <div className="flex items-center gap-2 text-sm">
                  <Icon name="Layers" className="w-4 h-4 text-muted-foreground" />
                  <span className="text-muted-foreground">Available models:</span>
                </div>
                <div className="flex flex-wrap gap-1.5 ml-6">
                  {models.slice(0, 6).map((m) => (
                    <Badge key={m} variant="outline" className="text-[10px] font-mono">
                      {m}
                    </Badge>
                  ))}
                  {models.length > 6 && (
                    <Badge variant="outline" className="text-[10px]">
                      +{models.length - 6} more
                    </Badge>
                  )}
                </div>
              </div>
            )}

            {/* Shared admin account toggle */}
            {onToggleShared && (
              <div className="flex items-center gap-3 pt-1 border-t border-border">
                <Switch
                  id={`shared-${providerId}`}
                  checked={status.sharedAdminAccount}
                  onCheckedChange={async (checked) => {
                    try {
                      await onToggleShared(checked);
                      toast.success(checked ? "Shared admin account enabled." : "Shared admin account disabled.");
                    } catch {
                      toast.error("Failed to toggle shared account mode.");
                    }
                  }}
                />
                <label htmlFor={`shared-${providerId}`} className="text-xs text-muted-foreground cursor-pointer leading-tight">
                  Use this account for all users
                  <span className="block text-[10px] text-muted-foreground/70 mt-0.5">
                    When enabled, all optimization requests use this authenticated session
                  </span>
                </label>
              </div>
            )}
          </div>
        )}

        {/* Not connected state */}
        {!isConnected && !showGoogleKeyPrompt && (
          <div className="py-4 text-center">
            <div
              className="w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-3"
              style={{ background: `${brandColor}08` }}
            >
              <Icon name={iconName} className="w-8 h-8" style={{ color: `${brandColor}40` }} />
            </div>
            <p className="text-sm text-muted-foreground mb-1">
              {providerName} is not connected
            </p>
            <p className="text-xs text-muted-foreground/70">
              Sign in to use {providerName} as an AI provider for optimizations
            </p>
          </div>
        )}

        {/* Google OAuth API key prompt — shown after Google auth succeeds but before API key is linked */}
        {showGoogleKeyPrompt && pendingGoogleUser && (
          <div className="p-3 bg-blue-50 dark:bg-blue-950/20 rounded-lg border border-blue-200 dark:border-blue-800 space-y-3">
            <div className="flex items-center gap-2">
              {pendingGoogleUser.picture ? (
                <img src={pendingGoogleUser.picture} alt="" className="w-6 h-6 rounded-full" referrerPolicy="no-referrer" />
              ) : (
                <div className="w-6 h-6 rounded-full bg-green-500 flex items-center justify-center">
                  <Icon name="Check" className="w-3.5 h-3.5 text-white" />
                </div>
              )}
              <div>
                <p className="text-xs font-medium text-green-700 dark:text-green-400">
                  Signed in as {pendingGoogleUser.email}
                </p>
                <p className="text-[10px] text-muted-foreground">
                  Now paste your Z.ai API key to complete the connection
                </p>
              </div>
            </div>
            <div className="flex gap-2">
              <Input
                type="password"
                placeholder="Paste your Z.ai API key..."
                value={googleApiKeyInput}
                onChange={(e) => setGoogleApiKeyInput(e.target.value)}
                className="h-8 text-xs font-mono"
                onKeyDown={(e) => {
                  if (e.key === "Enter" && googleApiKeyInput.trim()) {
                    handleCompleteGoogleLogin();
                  }
                }}
              />
              <Button
                size="sm"
                className="h-8 gap-1.5 shrink-0"
                style={{ background: "#1154A3" }}
                disabled={loading !== null || !googleApiKeyInput.trim()}
                onClick={handleCompleteGoogleLogin}
              >
                {loading === "google-complete" ? (
                  <div className="w-3.5 h-3.5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                ) : (
                  <Icon name="Plug" className="w-3.5 h-3.5" />
                )}
                Link
              </Button>
            </div>
            <p className="text-[9px] text-muted-foreground">
              Your API key will be linked to your Google account. Next time you sign in with Google, you won&apos;t need to enter it again.
            </p>
            <button
              className="text-[10px] text-muted-foreground hover:text-foreground underline"
              onClick={() => {
                setShowGoogleKeyPrompt(false);
                setGoogleApiKeyInput("");
                onClearPendingGoogleUser?.();
              }}
            >
              Cancel
            </button>
          </div>
        )}

        {/* Action buttons */}
        <div className="flex gap-2 pt-2 border-t border-border">
          {!isConnected && !showGoogleKeyPrompt ? (
            <>
              {/* Google OAuth button (for Z.ai) — always show, disabled with setup hint if not configured */}
              {providerId === "zai-direct" && (
                <Button
                  onClick={onLoginWithGoogle ? handleGoogleLogin : undefined}
                  disabled={loading !== null || !onLoginWithGoogle}
                  className="gap-2 flex-1 bg-white hover:bg-gray-50 text-gray-700 border border-gray-300 shadow-sm dark:bg-gray-800 dark:hover:bg-gray-700 dark:text-gray-200 dark:border-gray-600 disabled:opacity-70 disabled:cursor-not-allowed"
                  title={!onLoginWithGoogle ? "Set NEXT_PUBLIC_GOOGLE_CLIENT_ID in .env to enable Google sign-in" : undefined}
                >
                  {loading === "google" ? (
                    <>
                      <div className="w-4 h-4 border-2 border-gray-300 border-t-gray-600 rounded-full animate-spin" />
                      Connecting…
                    </>
                  ) : (
                    <>
                      {/* Google "G" logo */}
                      <svg className="w-4 h-4" viewBox="0 0 24 24">
                        <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92a5.06 5.06 0 0 1-2.2 3.32v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.1z" fill="#4285F4"/>
                        <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853"/>
                        <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" fill="#FBBC05"/>
                        <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335"/>
                      </svg>
                      {onLoginWithGoogle ? "Sign in with Google" : "Google (Setup Required)"}
                    </>
                  )}
                </Button>
              )}
              {/* API Key button (fallback) */}
              <Button
                onClick={handleLogin}
                disabled={loading !== null}
                className={`gap-2 ${onLoginWithGoogle ? "" : "flex-1"}`}
                variant={onLoginWithGoogle ? "outline" : "default"}
                style={!onLoginWithGoogle ? { background: brandColor, borderColor: brandColor } : undefined}
              >
                {loading === "login" ? (
                  <>
                    <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                    Connecting…
                  </>
                ) : (
                  <>
                    <Icon name="Key" className="w-4 h-4" />
                    API Key
                  </>
                )}
              </Button>
            </>
          ) : isConnected ? (
            <>
              <Button
                variant="outline"
                onClick={handleRefresh}
                disabled={loading !== null}
                className="gap-1.5"
                size="sm"
              >
                {loading === "refresh" ? (
                  <div className="w-3.5 h-3.5 border-2 border-muted-foreground/30 border-t-muted-foreground rounded-full animate-spin" />
                ) : (
                  <Icon name="RefreshCw" className="w-3.5 h-3.5" />
                )}
                Refresh Session
              </Button>
              <Button
                variant="outline"
                onClick={handleLogout}
                disabled={loading !== null}
                className="gap-1.5 text-red-600 hover:text-red-700 hover:bg-red-50 dark:text-red-400 dark:hover:bg-red-950/30"
                size="sm"
              >
                {loading === "logout" ? (
                  <div className="w-3.5 h-3.5 border-2 border-red-300 border-t-red-500 rounded-full animate-spin" />
                ) : (
                  <Icon name="LogOut" className="w-3.5 h-3.5" />
                )}
                Disconnect
              </Button>
            </>
          ) : null}

        {/* Auth required warning when expired */}
        {isConnected && isExpired && (
          <div className="flex items-start gap-2 p-3 bg-amber-50 dark:bg-amber-950/20 rounded-lg border border-amber-200 dark:border-amber-800">
            <Icon name="AlertTriangle" className="w-4 h-4 text-amber-600 shrink-0 mt-0.5" />
            <div>
              <p className="text-xs font-medium text-amber-700 dark:text-amber-400">Session expired</p>
              <p className="text-[11px] text-amber-600/80 dark:text-amber-500/80">
                Your {providerName} session has expired. Click "Refresh Session" to reconnect, or "Disconnect" and sign in again.
              </p>
            </div>
          </div>
        )}
      </div>
      </CardContent>
    </Card>
  );
}

src/components/app/modules/ProviderHealt:
"use client";

// ============================================================================
// Provider Health Panel — Auto-Heal + Manual Heal UI (directives #7–#20).
//
// Shared, self-contained surface mounted on BOTH the "AI Providers" page and
// the "AI Models" page so the healing controls are ALWAYS visible where
// providers are managed:
//   [Run Benchmark Ping] [HEAL PROVIDERS] [AUTO-HEAL PROVIDERS toggle]
//   + per-provider health strip (status chip incl. COOLDOWN countdown,
//     per-provider [HEALTH CHECK] / [HEAL])
//   + provider-aware benchmark results (resolved model per provider,
//     Technical Details expandable)
//   + heal report (Problem / Diagnosis / Action / Result) + heal history.
// ============================================================================

import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge, Icon } from "@/components/shared";
import { useApp } from "@/lib/store";
import { toast } from "sonner";
import { runProviderAwareBenchmark, type BenchmarkReport, type BenchmarkRow } from "@/lib/ai/healing/benchmark";
import { ProviderHealer, providerInCooldown, cooldownRemainingSeconds, type HealReportEntry } from "@/lib/ai/healing/provider-healer";
import { getHealHistory, clearHealHistory, type HealEvent } from "@/lib/ai/healing/heal-history";
import { classifyProviderFailure } from "@/lib/ai/healing/error-classifier";
import { getProviderCooldownSnapshot, formatCooldownRemaining, type ProviderCooldownClass } from "@/lib/provider-cooldown";
import { getProviderConcurrencySnapshot, ADAPTIVE_CAP_RECOVER_THRESHOLD } from "@/lib/provider-concurrency";

export function ProviderHealthPanel() {
  const providers = useApp((s) => s.providers);
  const providerSettings = useApp((s) => s.providerSettings);
  const updateProviderSettings = useApp((s) => s.updateProviderSettings);
  const autoHealOn = providerSettings?.autoHealProviders !== false;

  const [benchmarking, setBenchmarking] = useState(false);
  const [benchReport, setBenchReport] = useState<BenchmarkReport | null>(null);
  const [expandedTech, setExpandedTech] = useState<Record<string, boolean>>({});
  const [healing, setHealing] = useState(false);
  const [healReports, setHealReports] = useState<HealReportEntry[] | null>(null);
  const [healHistory, setHealHistory] = useState<HealEvent[]>([]);
  const [showHistory, setShowHistory] = useState(false);

  // Task 22 — live traffic-control countdowns: cooldown windows and the
  // adaptive cap live outside the store (sessionStorage/localStorage + module
  // state), so tick lightly to keep the strip's chips current.
  const [, setTrafficTick] = useState(0);
  useEffect(() => {
    const t = setInterval(() => setTrafficTick((n) => n + 1), 2000);
    return () => clearInterval(t);
  }, []);

  // Refresh heal history on mount + after operations
  useEffect(() => { setHealHistory(getHealHistory()); }, [benchReport, healReports]);

  /**
   * PROVIDER-AWARE BENCHMARK (directive #11): every provider is pinged with
   * ITS OWN resolved model — never one global model id propagated everywhere.
   * Failures are classified, health is updated, and safe Auto-Heal runs when
   * enabled (followed by a re-ping of the repaired configuration).
   */
  const runBenchmarkPing = async (providerIds?: string[]) => {
    setBenchmarking(true);
    setHealReports(null);
    try {
      const report = await runProviderAwareBenchmark({ providerIds });
      setBenchReport(report);
      const passed = report.rows.filter((r) => r.ok).length;
      const healed = report.rows.filter((r) => r.status === "healed").length;
      if (passed === report.rows.length && report.rows.length > 0) {
        toast.success(`Benchmark passed for all ${passed} provider${passed === 1 ? "" : "s"}.`);
      } else if (report.allFailed) {
        toast.error(`All ${report.rows.length} providers failed — click HEAL PROVIDERS for diagnosis + recovery.`);
      } else {
        toast.info(`Benchmark: ${passed}/${report.rows.length} passed${healed ? ` · ${healed} auto-healed` : ""}.`, { duration: 5000 });
      }
    } catch (e: any) {
      toast.error(e?.message || "Benchmark failed");
    } finally {
      setBenchmarking(false);
    }
  };

  /** HEAL ALL — manual recovery sweep (directive #7): diagnose → repair → validate → report. */
  const healAll = async () => {
    setHealing(true);
    try {
      const reports = await ProviderHealer.healAllProviders("manual");
      setHealReports(reports);
      setHealHistory(getHealHistory());
      const recovered = reports.filter((r) => r.result === "recovered").length;
      if (reports.length === 0) toast.info("All providers are healthy — nothing to heal.");
      else if (recovered === reports.length) toast.success(`Healing complete: ${recovered}/${reports.length} provider(s) recovered.`);
      else toast.warning(`Healing complete: ${recovered}/${reports.length} recovered — see the heal report for the rest.`, { duration: 6000 });
      // Directive #20: re-run the benchmark after healing so results reflect repairs.
      await runBenchmarkPing();
    } catch (e: any) {
      toast.error(e?.message || "Healing failed");
    } finally {
      setHealing(false);
    }
  };

  /** Per-provider HEAL — only affects that provider (directive #9). */
  const healOne = async (pid: string) => {
    setHealing(true);
    try {
      const report = await ProviderHealer.healProvider(pid, "manual");
      setHealReports([report]);
      setHealHistory(getHealHistory());
      if (report.result === "recovered") toast.success(`${report.providerName}: healed — ${report.action}`);
      else toast.warning(`${report.providerName}: ${report.result.replace("_", " ")} — ${report.action}`, { duration: 7000 });
    } catch (e: any) {
      toast.error(e?.message || "Heal failed");
    } finally {
      setHealing(false);
    }
  };

  /** Single-provider health check — same engine, one provider. */
  const healthCheckOne = async (pid: string) => {
    await runBenchmarkPing([pid]);
  };

  const stripProviders = providers.filter((p) => p.isActive && p.type !== "puter");

  return (
    <Card className="border-brand/20" data-provider-health-panel>
      <CardHeader>
        <CardTitle className="text-base flex items-center gap-2">
          <Icon name="Activity" className="w-4 h-4 text-brand" /> Provider Health — Auto-Heal &amp; Manual Heal
        </CardTitle>
        <CardDescription className="text-xs">
          Each provider is pinged with its own provider-compatible model — never one shared model id. Failures are classified, safely auto-repaired where possible, and validated before a provider is marked healthy.
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4 text-xs">
        {/* Auto-Heal toggle + primary actions */}
        <div className="flex flex-wrap items-center gap-2">
          <Button
            onClick={() => runBenchmarkPing()}
            disabled={benchmarking}
            className="h-8 font-semibold"
          >
            {benchmarking ? (
              <><Icon name="Loader2" className="w-3.5 h-3.5 mr-1.5 animate-spin" /> Benchmarking…</>
            ) : (
              <><Icon name="Gauge" className="w-3.5 h-3.5 mr-1.5" /> Run Benchmark Ping</>
            )}
          </Button>
          <Button
            onClick={healAll}
            disabled={healing || benchmarking}
            className="h-8 font-semibold bg-amber-600 hover:bg-amber-700 text-white"
          >
            {healing ? (
              <><Icon name="Loader2" className="w-3.5 h-3.5 mr-1.5 animate-spin" /> Healing…</>
            ) : (
              <><Icon name="HeartPulse" className="w-3.5 h-3.5 mr-1.5" /> HEAL PROVIDERS</>
            )}
          </Button>
          <button
            onClick={() => updateProviderSettings({ autoHealProviders: !autoHealOn })}
            className={`ml-auto flex items-center gap-1.5 px-2.5 h-8 rounded-md border text-[11px] font-medium ${autoHealOn ? "bg-emerald-500/10 border-emerald-500/30 text-emerald-600" : "bg-secondary/40 border-border text-muted-foreground"}`}
            title="When ON, provider failures automatically trigger safe diagnosis + repair + validation"
          >
            <Icon name={autoHealOn ? "ToggleRight" : "ToggleLeft"} className="w-4 h-4" />
            AUTO-HEAL PROVIDERS: {autoHealOn ? "ON" : "OFF"}
          </button>
        </div>

        {/* Per-provider health strip (directive #17) */}
        <div className="rounded-lg border border-border/60 divide-y divide-border/60">
          {stripProviders.length === 0 && (
            <div className="px-2.5 py-2 text-[11px] text-muted-foreground">
              No active API providers. Add or activate a provider to see its live health here.
            </div>
          )}
          {stripProviders.map((p) => {
            const inCd = providerInCooldown(p);
            const cdSecs = inCd ? cooldownRemainingSeconds(p) : 0;
            const cdSnap = getProviderCooldownSnapshot(p.id || p.name || p.type);
            const capSnap = getProviderConcurrencySnapshot(p.id, p.concurrencyCap);
            const cls = p.health?.lastError ? classifyProviderFailure(p.health.lastError, { providerType: p.type }) : null;
            const chip: string = inCd
              ? "COOLDOWN"
              : p.health?.healState && p.health.healState !== "untested"
                ? p.health.healState.toUpperCase().replace("_", " ")
                : cls && !cls.temporary
                  ? cls.kind.toUpperCase().replace("_", " ")
                  : p.status === "healthy" ? "HEALTHY" : p.status.toUpperCase();
            const chipCls =
              chip === "HEALTHY" || chip === "RECOVERED" ? "bg-emerald-500/10 text-emerald-600 border-emerald-500/30"
              : chip === "COOLDOWN" ? "bg-amber-500/10 text-amber-600 border-amber-500/30"
              : chip === "MODEL ERROR" || chip === "ENDPOINT ERROR" || chip === "AUTH ERROR" || chip === "CONFIGURATION ERROR" ? "bg-orange-500/10 text-orange-600 border-orange-500/30"
              : chip === "HEALING" ? "bg-sky-500/10 text-sky-600 border-sky-500/30"
              : "bg-red-500/10 text-red-600 border-red-500/30";
            // Task 22 — class-aware cooldown detail: the WHY (quota vs 429 vs
            // auth vs timeout), a human-readable window, and whether the S1
            // localStorage mirror backs it (survives tab close).
            const cdClassLabel: Record<ProviderCooldownClass, string> = {
              quota: "QUOTA", "429": "RATE-LIMIT", "401": "AUTH", timeout: "TIMEOUT", endpoint: "ENDPOINT", unknown: "COOLDOWN",
            };
            const cdDetail = inCd
              ? `${cdSnap.class ? ` · ${cdClassLabel[cdSnap.class]}` : ""} ${formatCooldownRemaining(cdSecs * 1000)}${cdSnap.persisted ? " · saved" : ""}`
              : "";
            return (
              <div key={p.id} className="flex items-center gap-2 px-2.5 py-1.5">
                <span className={`inline-flex items-center gap-1 px-1.5 py-0.5 rounded-full border text-[10px] font-semibold ${chipCls}`}
                  title={inCd && cdSnap.class
                    ? `${cdClassLabel[cdSnap.class]} cooldown — ${formatCooldownRemaining(cdSecs * 1000)} remaining${cdSnap.persisted ? " (persisted: survives a page reload / tab close)" : ""}. Traffic skips this provider until the window ends or evidence clears it.`
                    : undefined}
                >
                  <span className="w-1.5 h-1.5 rounded-full bg-current" /> {chip}{cdDetail}
                </span>
                {capSnap.tightened && (
                  <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded-full border text-[10px] font-semibold bg-amber-500/10 text-amber-600 border-amber-500/30"
                    title={`Adaptive concurrency cap self-tightened to ${capSnap.effectiveCap} of the configured ceiling ${capSnap.configuredCap} after rate-limit evidence. Recovers +1 per ${ADAPTIVE_CAP_RECOVER_THRESHOLD} clean successes (now ${capSnap.consecutiveSuccesses}/${ADAPTIVE_CAP_RECOVER_THRESHOLD}). Reset it on the Providers table.`}
                  >
                    <Icon name="Gauge" className="w-3 h-3" /> CAP {capSnap.effectiveCap}/{capSnap.configuredCap} AUTO
                  </span>
                )}
                <span className="font-medium truncate max-w-[140px]">{p.name}</span>
                <span className="font-mono text-[10px] text-muted-foreground truncate max-w-[160px]">{p.modelName || "—"}</span>
                {p.health?.lastDiagnosis && <span className="text-[10px] text-muted-foreground truncate flex-1 hidden sm:inline">{p.health.lastDiagnosis}</span>}
                <div className="ml-auto flex items-center gap-1 shrink-0">
                  <Button variant="outline" size="sm" className="h-6 px-2 text-[10px]" disabled={benchmarking} onClick={() => healthCheckOne(p.id)}>
                    <Icon name="Stethoscope" className="w-3 h-3 mr-0.5" /> HEALTH CHECK
                  </Button>
                  <Button variant="outline" size="sm" className="h-6 px-2 text-[10px]" disabled={healing} onClick={() => healOne(p.id)}>
                    <Icon name="Wrench" className="w-3 h-3 mr-0.5" /> HEAL
                  </Button>
                </div>
              </div>
            );
          })}
        </div>

        {/* Benchmark results table (directive #11) */}
        {benchReport && (
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <span className="font-semibold flex items-center gap-1.5">
                <Icon name="ListChecks" className="w-3.5 h-3.5 text-brand" /> Benchmark Results
              </span>
              <span className="text-[10px] text-muted-foreground">{new Date(benchReport.at).toLocaleTimeString()} · {benchReport.totalMs}ms total</span>
            </div>
            <div className="rounded-lg border border-border/60 divide-y divide-border/60">
              {benchReport.rows.map((r: BenchmarkRow) => (
                <div key={r.providerId} className="px-2.5 py-2 space-y-1.5">
                  <div className="flex flex-wrap items-center gap-2">
                    <Badge variant={r.ok ? (r.status === "healed" ? "warning" : "success") : r.status === "cooldown" ? "warning" : "danger"}>
                      {r.chip}
                    </Badge>
                    <span className="font-semibold">{r.providerName}</span>
                    <span className="font-mono text-[10px] text-muted-foreground">model: {r.resolvedModel}</span>
                    <Badge variant="outline" className="text-[9px]">{r.modelSource === "configured" ? "CONFIGURED MODEL" : r.modelSource === "enabled" ? "FROM ENABLED" : r.modelSource === "catalog" ? "FROM CATALOG" : "NO MODEL"}</Badge>
                    {r.ok && <Badge variant="success" className="text-[9px]">{r.latencyMs}ms</Badge>}
                    {r.autoHeal?.repaired && <Badge variant="warning" className="text-[9px]"><Icon name="Wrench" className="w-3 h-3 mr-0.5" /> AUTO-HEALED</Badge>}
                  </div>
                  {r.reply && r.ok && <div className="font-mono text-[10px] text-emerald-600">reply: &quot;{r.reply}&quot;</div>}
                  {r.diagnosis && !r.ok && <div className="text-[11px] text-amber-700">{r.diagnosis}</div>}
                  {r.error && (
                    <div>
                      <button className="text-[10px] text-muted-foreground underline flex items-center gap-1" onClick={() => setExpandedTech((s) => ({ ...s, [r.providerId]: !s[r.providerId] }))}>
                        <Icon name={expandedTech[r.providerId] ? "ChevronDown" : "ChevronRight"} className="w-3 h-3" /> Technical Details
                      </button>
                      {expandedTech[r.providerId] && (
                        <pre className="mt-1 whitespace-pre-wrap break-all rounded bg-slate-900 text-slate-100 p-2 font-mono text-[10px] max-h-24 overflow-y-auto">{r.error}</pre>
                      )}
                    </div>
                  )}
                </div>
              ))}
            </div>
            {benchReport.allFailed && (
              <div className="rounded-lg bg-red-500/5 border border-red-500/20 p-2.5 text-[11px] text-red-600">
                All providers failed AFTER model resolution, cooldown handling and safe auto-healing. This is a genuine outage or a configuration problem — review the diagnoses above, then run HEAL PROVIDERS or fix the flagged configuration.
              </div>
            )}
          </div>
        )}

        {/* Heal report (directive #10) */}
        {healReports && healReports.length > 0 && (
          <div className="space-y-2">
            <span className="font-semibold flex items-center gap-1.5">
              <Icon name="HeartPulse" className="w-3.5 h-3.5 text-amber-600" /> Provider Heal Report
            </span>
            {healReports.map((r, i) => (
              <div key={i} className="rounded-lg border border-border/60 p-2.5 space-y-1">
                <div className="flex items-center gap-2">
                  <span className="font-semibold">{r.providerName}</span>
                  <Badge variant={r.result === "recovered" ? "success" : r.result === "cooldown" ? "warning" : r.result === "failed" ? "danger" : "outline"}>{r.result.replace("_", " ").toUpperCase()}</Badge>
                  <Badge variant="outline" className="text-[9px]">{r.mode === "auto" ? "AUTO-HEAL" : "MANUAL"}</Badge>
                </div>
                <div className="text-[11px] space-y-0.5 text-muted-foreground">
                  <div><strong className="text-foreground">Problem:</strong> {r.problem}</div>
                  <div><strong className="text-foreground">Diagnosis:</strong> {r.diagnosis}</div>
                  <div><strong className="text-foreground">Action:</strong> {r.action}</div>
                  {r.previousModel && r.newModel && <div><strong className="text-foreground">Model:</strong> <span className="font-mono">{r.previousModel}</span> → <span className="font-mono">{r.newModel}</span></div>}
                  {r.previousEndpoint && r.newEndpoint && <div><strong className="text-foreground">Endpoint:</strong> <span className="font-mono">{r.previousEndpoint}</span> → <span className="font-mono">{r.newEndpoint}</span></div>}
                </div>
                {r.technical && (
                  <pre className="whitespace-pre-wrap break-all rounded bg-slate-900 text-slate-100 p-2 font-mono text-[10px] max-h-20 overflow-y-auto">{r.technical}</pre>
                )}
              </div>
            ))}
          </div>
        )}

        {/* Heal history (directive #19) */}
        {healHistory.length > 0 && (
          <div>
            <button className="font-semibold flex items-center gap-1.5 text-muted-foreground hover:text-foreground" onClick={() => setShowHistory((s) => !s)}>
              <Icon name={showHistory ? "ChevronDown" : "ChevronRight"} className="w-3.5 h-3.5" />
              <Icon name="History" className="w-3.5 h-3.5" /> Heal History ({healHistory.length})
            </button>
            {showHistory && (
              <div className="mt-2 rounded-lg border border-border/60 divide-y divide-border/60 max-h-48 overflow-y-auto">
                {healHistory.map((e) => (
                  <div key={e.id} className="px-2.5 py-1.5 flex flex-wrap items-center gap-2 text-[10px]">
                    <span className="text-muted-foreground">{new Date(e.at).toLocaleString()}</span>
                    <span className="font-semibold">{e.providerName}</span>
                    <span>{e.failureKind}</span>
                    {e.previousModel && e.newModel && <span className="font-mono">{e.previousModel} → {e.newModel}</span>}
                    <Badge variant={e.result === "recovered" ? "success" : e.result === "cooldown" ? "warning" : "outline"} className="text-[9px]">{e.result.replace("_", " ")}</Badge>
                    <Badge variant="outline" className="text-[9px]">{e.mode === "auto" ? "AUTO" : "MANUAL"}</Badge>
                  </div>
                ))}
                <div className="px-2.5 py-1.5">
                  <button className="text-[10px] text-muted-foreground underline" onClick={() => { clearHealHistory(); setHealHistory([]); }}>Clear history</button>
                </div>
              </div>
            )}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

src/components/app/modules/ProviderLogsT:
"use client";

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge, Icon } from "@/components/shared";
import { useApp } from "@/lib/store";
import { ProviderManager } from "@/lib/ai/services";
import { toast } from "sonner";

const STATUS_COLORS: Record<string, "success" | "warning" | "danger" | "outline"> = {
  success: "success",
  error: "danger",
  timeout: "warning",
  rate_limited: "warning",
};

export function ProviderLogsTable() {
  const logs = useApp((s) => s.providerLogs);
  const providers = useApp((s) => s.providers);
  const [q, setQ] = useState("");
  const [providerFilter, setProviderFilter] = useState<string>("all");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [expanded, setExpanded] = useState<string | null>(null);

  const filtered = logs.filter((l) => {
    if (providerFilter !== "all" && l.providerId !== providerFilter) return false;
    if (statusFilter !== "all" && l.status !== statusFilter) return false;
    if (q && !(`${l.providerName} ${l.errorMessage ?? ""} ${l.requestPreview ?? ""}`.toLowerCase().includes(q.toLowerCase()))) return false;
    return true;
  });

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between flex-wrap gap-3">
          <CardTitle className="text-base">AI Provider Logs ({filtered.length})</CardTitle>
          <div className="flex gap-2 flex-wrap">
            <select value={providerFilter} onChange={(e) => setProviderFilter(e.target.value)} className="h-9 px-3 rounded-md border border-input bg-background text-sm">
              <option value="all">All providers</option>
              {providers.map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}
            </select>
            <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)} className="h-9 px-3 rounded-md border border-input bg-background text-sm">
              <option value="all">All statuses</option>
              <option value="success">Success</option>
              <option value="error">Error</option>
              <option value="timeout">Timeout</option>
              <option value="rate_limited">Rate limited</option>
            </select>
            <div className="relative w-full sm:w-56">
              <Icon name="Search" className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
              <Input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search logs…" className="pl-9 h-9" />
            </div>
            <Button variant="outline" size="sm" onClick={() => { if (confirm("Clear all logs?")) { ProviderManager.clearLogs(); toast.success("Logs cleared."); } }} className="text-destructive gap-1.5">
              <Icon name="Trash2" className="w-3.5 h-3.5" /> Clear
            </Button>
          </div>
        </div>
      </CardHeader>
      <CardContent className="p-0">
        <div className="max-h-[60vh] overflow-y-auto">
          <table className="w-full text-sm">
            <thead className="sticky top-0 bg-card border-b border-border">
              <tr className="text-left text-xs uppercase tracking-wide text-muted-foreground">
                <th className="px-4 py-2 font-semibold">Time</th>
                <th className="px-4 py-2 font-semibold">Provider</th>
                <th className="px-4 py-2 font-semibold">Type</th>
                <th className="px-4 py-2 font-semibold">Model</th>
                <th className="px-4 py-2 font-semibold">Status</th>
                <th className="px-4 py-2 font-semibold text-right">Latency</th>
                <th className="px-4 py-2 font-semibold text-right">Tokens</th>
                <th className="px-4 py-2 font-semibold">Error / Response</th>
              </tr>
            </thead>
            <tbody>
              {filtered.map((l) => (
                <>
                  <tr key={l.id} className="border-b border-border hover:bg-secondary/30 cursor-pointer" onClick={() => setExpanded(expanded === l.id ? null : l.id)}>
                    <td className="px-4 py-2 text-xs text-muted-foreground whitespace-nowrap">{new Date(l.createdAt).toLocaleString([], { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" })}</td>
                    <td className="px-4 py-2 text-xs font-medium truncate max-w-[160px]">{l.providerName}</td>
                    <td className="px-4 py-2"><Badge variant="outline" className="text-[10px] capitalize">{l.requestType}</Badge></td>
                    <td className="px-4 py-2 text-xs font-mono">{l.modelName ?? "—"}</td>
                    <td className="px-4 py-2"><Badge variant={STATUS_COLORS[l.status]} className="text-[10px] capitalize">{l.status.replace("_", " ")}</Badge></td>
                    <td className="px-4 py-2 text-right text-xs font-mono">{l.latencyMs}ms</td>
                    <td className="px-4 py-2 text-right text-xs font-mono">{(l.inputTokens ?? 0) + (l.outputTokens ?? 0) > 0 ? `${l.inputTokens ?? 0}+${l.outputTokens ?? 0}` : "—"}</td>
                    <td className="px-4 py-2 text-xs text-muted-foreground truncate max-w-[260px]">
                      {l.errorMessage ?? l.responsePreview ?? "—"}
                      <Icon name={expanded === l.id ? "ChevronUp" : "ChevronDown"} className="w-3 h-3 inline ml-1" />
                    </td>
                  </tr>
                  {expanded === l.id && (
                    <tr className="bg-secondary/20">
                      <td colSpan={8} className="px-4 py-3">
                        <div className="grid sm:grid-cols-2 gap-3 text-xs">
                          <div>
                            <div className="font-semibold text-muted-foreground mb-1">Request preview</div>
                            <pre className="bg-card border border-border rounded p-2 whitespace-pre-wrap font-mono text-[11px] max-h-32 overflow-y-auto">{l.requestPreview ?? "(empty)"}</pre>
                          </div>
                          <div>
                            <div className="font-semibold text-muted-foreground mb-1">{l.status === "success" ? "Response preview" : "Error message"}</div>
                            <pre className={`bg-card border border-border rounded p-2 whitespace-pre-wrap font-mono text-[11px] max-h-32 overflow-y-auto ${l.status !== "success" ? "text-red-600" : ""}`}>{l.errorMessage ?? l.responsePreview ?? "(empty)"}</pre>
                          </div>
                        </div>
                      </td>
                    </tr>
                  )}
                </>
              ))}
              {filtered.length === 0 && (
                <tr><td colSpan={8} className="text-center py-12 text-muted-foreground">No logs match your filters.</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </CardContent>
    </Card>
  );
}

src/components/app/modules/PuterAuthCard:
import { useState, useEffect } from "react";
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { Badge, Icon } from "@/components/shared";
import { toast } from "sonner";
import { getPuterProvider } from "@/lib/providers/puter-provider";

export function PuterAuthCard({ status, onRefreshStatus }: { status: any, onRefreshStatus: () => void }) {
  const [loading, setLoading] = useState(false);
  const puter = getPuterProvider();

  // Listen to live auto-rotation and status-change events
  useEffect(() => {
    const handleRotated = (e: any) => {
      const { fromEmail, toEmail, reason } = e?.detail || {};
      toast.info(`[Puter] Auto-rotated from ${fromEmail || "previous"} to ${toEmail || "next"} (${reason || "quota limit"})`);
      onRefreshStatus();
    };
    const handleStatusChange = (e: any) => {
      const restored = e?.detail?.restored ?? 0;
      if (restored > 0) {
        toast.success(`[Puter] Proactive probe: ${restored} account(s) recovered to healthy status!`);
        onRefreshStatus();
      }
    };
    if (typeof window !== "undefined") {
      window.addEventListener("puter:rotated", handleRotated);
      window.addEventListener("puter:status_change", handleStatusChange);

      // Periodically probe rate-limited accounts (every 5 minutes)
      const probeInterval = setInterval(() => {
        puter.probeRateLimitedAccounts().catch(() => {});
      }, 5 * 60 * 1000);

      return () => {
        window.removeEventListener("puter:rotated", handleRotated);
        window.removeEventListener("puter:status_change", handleStatusChange);
        clearInterval(probeInterval);
      };
    }
  }, [onRefreshStatus, puter]);
  
  const handleAddAccount = async () => {
    setLoading(true);
    try {
      await puter.login();
      toast.success("Account added and saved successfully.");
      onRefreshStatus();
    } catch (e: any) {
      toast.error(e.message || "Failed to add account");
    } finally {
      setLoading(false);
    }
  };

  const handleSwitch = async (id: string) => {
    setLoading(true);
    try {
      await puter.setActiveAccount(id);
      toast.success("Account switched.");
      onRefreshStatus();
    } catch (e: any) {
      toast.error(e.message || "Failed to switch account");
    } finally {
      setLoading(false);
    }
  };

  const handleRemove = async (id: string) => {
    setLoading(true);
    try {
      await puter.removeAccount(id);
      toast.success("Account removed.");
      onRefreshStatus();
    } catch (e: any) {
      toast.error(e.message || "Failed to remove account");
    } finally {
      setLoading(false);
    }
  };

  const handleRefreshTokens = async () => {
    setLoading(true);
    try {
      await puter.refresh();
      toast.success("Sessions refreshed.");
      onRefreshStatus();
    } catch (e: any) {
      toast.error(e.message || "Failed to refresh");
    } finally {
      setLoading(false);
    }
  };

  const handleTestAutoRotate = async () => {
    setLoading(true);
    try {
      const rotated = await puter.rotateToNextHealthyAccount();
      if (rotated) {
        toast.success("Auto-rotation successful: switched to next account.");
        onRefreshStatus();
      } else {
        toast.info("No alternate healthy account available to rotate to.");
      }
    } catch (e: any) {
      toast.error(e.message || "Rotation failed");
    } finally {
      setLoading(false);
    }
  };

  const accounts = status.accounts || [];

  return (
    <Card className="border-amber-500/20 overflow-hidden flex flex-col h-full bg-card shadow-sm hover:shadow-md transition-shadow">
      <CardHeader className="bg-amber-500/5 pb-4 border-b border-amber-500/10">
        <CardTitle className="text-base flex justify-between items-center">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-lg flex items-center justify-center bg-amber-500/20 text-amber-600 dark:text-amber-500">
              <Icon name="Sparkles" className="w-4 h-4" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <span>Puter.js</span>
                {accounts.length > 1 && (
                  <Badge variant={status.autoRotate ? "success" : "outline"} className="text-[10px] px-1.5 py-0">
                    {status.autoRotate ? `Auto-Rotate Active (${accounts.length})` : "Rotation Paused"}
                  </Badge>
                )}
              </div>
              <p className="text-xs font-normal text-muted-foreground mt-0.5">Free browser-auth with Google OAuth</p>
            </div>
          </div>
          <div className="flex gap-2">
            <Button size="sm" variant="outline" onClick={handleRefreshTokens} disabled={loading} title="Refresh">
              <Icon name="RefreshCw" className="w-3.5 h-3.5" />
            </Button>
            <Button size="sm" onClick={handleAddAccount} disabled={loading} className="bg-amber-600 hover:bg-amber-700 text-white gap-1.5">
              {loading ? <Icon name="Loader2" className="w-3.5 h-3.5 animate-spin" /> : <Icon name="Plus" className="w-3.5 h-3.5" />}
              Add Account
            </Button>
          </div>
        </CardTitle>
      </CardHeader>
      <CardContent className="p-0 flex-1 flex flex-col">
        <div className="p-4 space-y-4">
          <div className="flex items-center justify-between border-b border-border pb-2">
            <span className="text-sm font-medium text-foreground">Connected Accounts</span>
            {accounts.length > 1 && status.autoRotate && (
              <Button size="sm" variant="ghost" className="h-6 text-xs text-amber-600 dark:text-amber-400 gap-1 px-2" onClick={handleTestAutoRotate} disabled={loading}>
                <Icon name="RotateCw" className="w-3 h-3" />
                Test Next Rotation
              </Button>
            )}
          </div>
          
          {accounts.length === 0 ? (
             <div className="text-sm text-muted-foreground text-center py-4">No accounts connected. Click &quot;Add Account&quot; to sign in with Google or Puter.</div>
          ) : (
            <div className="space-y-3">
              {accounts.map((acc: any) => (
                <div key={acc.id} className={`p-3 rounded-lg border ${acc.active ? 'border-amber-500 bg-amber-50 dark:bg-amber-500/10' : 'border-border bg-secondary/30'} flex flex-col gap-2`}>
                   <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <div className={`w-2 h-2 rounded-full ${acc.status === 'healthy' ? 'bg-emerald-500' : acc.status === 'rate_limited' ? 'bg-amber-500' : 'bg-red-500'}`} />
                        <span className="font-medium text-sm">{acc.email}</span>
                        {acc.active && <span className="text-[10px] uppercase font-bold tracking-wider px-1.5 py-0.5 rounded bg-amber-500/20 text-amber-700 dark:text-amber-400">Active</span>}
                      </div>
                      <div className="flex gap-1.5">
                        {!acc.active && (
                          <Button size="sm" variant="outline" className="h-7 text-xs px-2" onClick={() => handleSwitch(acc.id)} disabled={loading}>Switch</Button>
                        )}
                        <Button size="sm" variant="ghost" className="h-7 text-xs px-2 text-red-600 hover:text-red-700 hover:bg-red-50" onClick={() => handleRemove(acc.id)} disabled={loading}>Remove</Button>
                      </div>
                   </div>
                   <div className="text-xs text-muted-foreground grid grid-cols-2 gap-1">
                      <div>Curated: claude-sonnet-4-5, gpt-4o, gemini-2.5-flash</div>
                      <div>Status: <span className={acc.status === "healthy" ? "text-emerald-600 dark:text-emerald-400 font-medium" : acc.status === "rate_limited" ? "text-amber-600 dark:text-amber-400 font-medium" : "text-red-600 dark:text-red-400"}>{acc.status === "healthy" ? "Healthy" : acc.status === "rate_limited" ? "Rate Limited (Cooling Down)" : "Expired"}</span></div>
                   </div>
                </div>
              ))}
            </div>
          )}
        </div>
        
        {accounts.length > 0 && (
          <div className="mt-auto border-t border-border bg-secondary/20 p-4 space-y-3">
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label className="text-sm font-medium">Auto-rotate accounts</Label>
                <p className="text-xs text-muted-foreground">Automatically switches to next healthy account when quota limit or 429 is reached</p>
              </div>
              <Switch checked={status.autoRotate} onCheckedChange={async (v) => { await puter.setAutoRotate(v); onRefreshStatus(); }} disabled={loading} />
            </div>
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label className="text-sm font-medium">Use selected account globally</Label>
                <p className="text-xs text-muted-foreground">Force this account for all generation tasks</p>
              </div>
              <Switch checked={status.useGlobally} onCheckedChange={async (v) => { await puter.setUseGlobally(v); onRefreshStatus(); }} disabled={loading} />
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

src/components/app/modules/RecruiterInte:
"use client";

// ============================================================================
// Phase 8.1.5 (P3) — Recruiter Intelligence Dashboard.
//
// PRESENTATION ONLY. Consumes the existing read-model:
//   buildCandidateIntelligence(input) + buildRecruiterDashboard(ci)
// under src/lib/recruiter/. No AI, no scoring, no competency recomputation.
// ============================================================================

import { useApp } from "@/lib/store";
import { buildRecruiterDashboard } from "@/lib/recruiter/candidate-intelligence";
import type { HiringRecommendation } from "@/lib/recruiter/recruiter-types";
import { CompetencyRadar } from "@/components/analytics/CompetencyRadar";
import { BehaviorBars } from "@/components/analytics/BehaviorBars";
import { ExplainabilityTree } from "@/components/explainability/ExplainabilityTree";
import { useSessionIntelligence } from "@/components/recruiter/useSessionIntelligence";
import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Skeleton } from "@/components/ui/skeleton";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Icon } from "@/components/shared";

const RECO_COLOR: Record<HiringRecommendation, string> = {
  strong_hire: "#10B981",
  hire: "#22C55E",
  lean_hire: "#84CC16",
  hold: "#F59E0B",
  reject: "#DC2626",
};

export function RecruiterIntelligence() {
  const setView = useApp((s) => s.setView);
  const { sessions, selectedId, setSelectedId, activeSession, ci } = useSessionIntelligence();

  if (sessions.length === 0) {
    return (
      <div className="space-y-6">
        <Header onBack={() => setView("interview")} />
        <Card>
          <CardContent className="p-10 text-center text-muted-foreground">
            <Icon name="Inbox" className="w-10 h-10 mx-auto mb-3 opacity-50" />
            <p className="text-sm">No completed interviews yet.</p>
            <p className="text-xs mt-1">Run an interview session — its scored memory will appear here for recruiter review.</p>
            <Button className="mt-4" onClick={() => setView("interview")}>
              <Icon name="MessagesSquare" className="w-4 h-4 mr-2" /> Go to Interview Prep
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (!ci || !activeSession) {
    return (
      <div className="space-y-6">
        <Header onBack={() => setView("interview")} />
        <Skeleton className="h-64 w-full rounded-2xl" />
      </div>
    );
  }

  const dash = buildRecruiterDashboard(ci);
  const reco = dash.hiringRecommendation;

  return (
    <div className="space-y-6">
      <Header onBack={() => setView("interview")} />

      {/* Candidate list */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base">Candidates ({sessions.length})</CardTitle>
          <CardDescription>Completed interview sessions with scored memory.</CardDescription>
        </CardHeader>
        <CardContent className="flex flex-wrap gap-2">
          {sessions.map((s) => {
            const active = s.id === selectedId;
            return (
              <button
                key={s.id}
                onClick={() => setSelectedId(s.id)}
                className={`px-3 py-2 rounded-xl border text-left text-sm transition-colors ${
                  active ? "border-brand bg-brand/10" : "border-border hover:bg-accent/50"
                }`}
              >
                <div className="font-medium">{s.role ?? s.company ?? "Candidate"}</div>
                <div className="text-xs text-muted-foreground">{s.company ?? "—"}</div>
              </button>
            );
          })}
        </CardContent>
      </Card>

      {/* Top-line dashboard */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Card className="md:col-span-2">
          <CardContent className="p-6">
            <div className="flex items-center justify-between gap-4 flex-wrap">
              <div>
                <h2 className="font-display text-xl font-bold">{ci.candidate.name ?? activeSession?.role ?? "Candidate"}</h2>
                <p className="text-sm text-muted-foreground">
                  {ci.candidate.role ?? activeSession?.role} · {ci.candidate.company ?? activeSession?.company ?? "—"}
                </p>
              </div>
              <span
                className="px-2.5 py-1 rounded-full text-xs font-semibold border"
                style={{ background: `${RECO_COLOR[reco]}1a`, color: RECO_COLOR[reco], borderColor: `${RECO_COLOR[reco]}55` }}
              >
                {reco.replace("_", " ").toUpperCase()}
              </span>
            </div>
            <p className="text-sm mt-3 text-pretty">{dash.candidateOverview}</p>
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mt-5">
              <Metric label="Overall" value={ci.overall} suffix="/100" />
              <Metric label="Interview" value={dash.interviewScore} suffix="/100" />
              <Metric label="Resume" value={dash.resumeScore} suffix="/100" />
              <Metric label="ATS Match" value={dash.atsMatch} suffix="/100" />
              <Metric label="Company" value={dash.companyMatch} suffix="/100" />
              <Metric label="Confidence" value={dash.hiringConfidence} suffix="%" />
              <Metric label="Risk" value={dash.overallRisk} suffix="/100" />
              <Metric label="Employer Pass" value={ci.employerPassLikelihood} suffix="/100" />
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="text-base">Decision</CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            <DecisionPill status={ci.decision.status} />
            <div className="text-xs text-muted-foreground">
              <div>Confidence: {(ci.decision.confidence != null ? Math.round(ci.decision.confidence * 100) : 0)}%</div>
              <div className="mt-1">{ci.decision.reason || "No decision recorded."}</div>
            </div>
            <Button variant="outline" size="sm" className="w-full" onClick={() => setView("explainability")}>
              <Icon name="ScanSearch" className="w-4 h-4 mr-2" /> Explainability
            </Button>
            <Button variant="outline" size="sm" className="w-full" onClick={() => setView("interview-reports")}>
              <Icon name="FileText" className="w-4 h-4 mr-2" /> Executive Report
            </Button>
          </CardContent>
        </Card>
      </div>

      {/* Detail tabs */}
      <Tabs defaultValue="competencies">
        <TabsList className="flex-wrap">
          <TabsTrigger value="competencies">Competencies</TabsTrigger>
          <TabsTrigger value="behavior">Behavior</TabsTrigger>
          <TabsTrigger value="match">Company / ATS</TabsTrigger>
          <TabsTrigger value="explain">Explainability</TabsTrigger>
        </TabsList>

        <TabsContent value="competencies" className="mt-4">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
            <Card>
              <CardHeader><CardTitle className="text-base">Competency Radar</CardTitle></CardHeader>
              <CardContent><CompetencyRadar ci={ci} /></CardContent>
            </Card>
            <Card>
              <CardHeader><CardTitle className="text-base">Competency Detail</CardTitle></CardHeader>
              <CardContent className="space-y-2 max-h-[360px] overflow-auto">
                {Object.entries(ci.competencySummary).map(([key, c]) => (
                  <div key={key} className="flex items-center gap-3">
                    <div className="w-40 text-sm truncate">{key}</div>
                    <div className="flex-1 h-2 rounded-full bg-secondary overflow-hidden">
                      <div className="h-full rounded-full bg-brand" style={{ width: `${c.score}%` }} />
                    </div>
                    <div className="w-10 text-right text-sm font-medium">{c.score}</div>
                  </div>
                ))}
              </CardContent>
            </Card>
          </div>
        </TabsContent>

        <TabsContent value="behavior" className="mt-4">
          <Card>
            <CardHeader><CardTitle className="text-base">Behavioral Intelligence (16 dimensions)</CardTitle></CardHeader>
            <CardContent><BehaviorBars behavior={ci.behavior} /></CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="match" className="mt-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <Card>
              <CardHeader><CardTitle className="text-base">Company Match</CardTitle></CardHeader>
              <CardContent>
                {ci.companyMatch ? (
                  <div className="space-y-2">
                    <div className="text-2xl font-bold">{ci.companyMatch.overallCompanyReadiness}/100</div>
                    <div className="text-sm text-muted-foreground">{ci.companyMatch.reasoning}</div>
                  </div>
                ) : (
                  <p className="text-sm text-muted-foreground">No company profile supplied.</p>
                )}
              </CardContent>
            </Card>
            <Card>
              <CardHeader><CardTitle className="text-base">ATS Match</CardTitle></CardHeader>
              <CardContent>
                <div className="text-2xl font-bold">{ci.ats.atsScore ?? ci.ats.jdMatchPercent ?? 0}/100</div>
                <p className="text-sm text-muted-foreground mt-1">
                  {ci.ats.weakSections.length
                    ? `Weak sections: ${ci.ats.weakSections.join(", ")}`
                    : "No weak sections flagged."}
                </p>
              </CardContent>
            </Card>
          </div>
        </TabsContent>

        <TabsContent value="explain" className="mt-4">
          <Card>
            <CardHeader><CardTitle className="text-base">Evidence & Explainability</CardTitle></CardHeader>
            <CardContent><ExplainabilityTree ci={ci} /></CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

function Header({ onBack }: { onBack: () => void }) {
  return (
    <div className="flex items-center gap-3">
      <Button variant="ghost" size="icon" onClick={onBack} aria-label="Back to interview">
        <Icon name="ArrowLeft" className="w-4 h-4" />
      </Button>
      <div>
        <h1 className="font-display text-2xl font-bold">Recruiter Intelligence</h1>
        <p className="text-sm text-muted-foreground">Candidate read-model · built from interview execution data.</p>
      </div>
    </div>
  );
}

function Metric({ label, value, suffix = "" }: { label: string; value: number; suffix?: string }) {
  return (
    <div className="rounded-xl border border-border bg-card p-3">
      <div className="text-xs text-muted-foreground">{label}</div>
      <div className="text-lg font-bold">{value}{suffix}</div>
    </div>
  );
}

function DecisionPill({ status }: { status?: string }) {
  const color = status === "accept" ? "#10B981" : status === "reject" || status === "escalate" ? "#DC2626" : status === "retry" ? "#F59E0B" : "#6B7280";
  return (
    <span className="inline-flex items-center gap-1.5 text-sm font-medium" style={{ color }}>
      <span className="w-2 h-2 rounded-full" style={{ background: color }} />
      {status ? status.toUpperCase() : "NO DECISION"}
    </span>
  );
}

src/components/app/modules/ResumeReviewP:
"use client";

import { recordAI, setFlightScope } from "@/lib/ai/flight-recorder";
setFlightScope({ scope: "resume-optimizer", feature: "Resume Review Platform", module: "src.components.app.modules.ResumeReviewPlatform" });

/**
 * ResumeReviewPlatform — Advanced AI Resume Review Platform
 *
 * EVOLUTIONARY UPGRADE of the legacy AiResumeReview component.
 * The legacy component (in CareerTools.tsx) is preserved untouched; this new
 * platform is wired in via AppShell.tsx so the same nav entry ("AI Resume
 * Review") now opens the full 10-module experience.
 *
 * Modules:
 *   1. ATS Review — score, keyword match, parsing risks, pass probability
 *   2. Recruiter Review — per-section strengths/weaknesses/recommendations
 *   3. Job Match Review — match % across 5 axes + missing skills/keywords/certs
 *   4. Industry Benchmark — readiness score vs. industry averages
 *   5. Resume Improvements — better summary/headlines/skills/bullets
 *   6. Priority Action Plan — critical/high/optional fixes + expected ATS gain
 *   7. One-Click Fixes — Fix Summary, Fix Skills, Fix Experience, etc.
 *   8. Interview Readiness — likely questions, weak areas, talking points
 *   9. Visual Dashboard — radar chart, progress bars, heat-map style
 *  10. Persistence — localStorage backup + store; survives refresh/logout/login
 *
 * Exports: JSON / PDF (print) / DOCX (via clipboard-friendly text).
 *
 * All AI generation is LIVE — no demo data, no hardcoded scores, no
 * placeholders. Every recommendation is dynamically generated from the
 * resume content, optimized resume (if any), job description (if any),
 * company information (if any), and industry profile (auto-detected).
 */

import { useEffect, useMemo, useRef, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge, Icon } from "@/components/shared";
import { useApp, uid } from "@/lib/store";
import { callAI, extractJSON } from "@/lib/ai";
import { detectIndustry, INDUSTRY_PROFILES } from "@/lib/industry-ats";
import { toast } from "sonner";
import type { ResumeData, ResumeReviewReport, JobDescription } from "@/lib/types";

// ============================================================================
// Helpers
// ============================================================================

const scoreColor = (s: number, inverted = false) => {
  // inverted=true means LOWER is better (e.g. missing keywords count)
  if (inverted) return s === 0 ? "#10B981" : s <= 3 ? "#F59E0B" : "#DC2626";
  if (s >= 80) return "#10B981";
  if (s >= 60) return "#1154A3";
  if (s >= 40) return "#F59E0B";
  return "#DC2626";
};

const scoreLabel = (s: number) => {
  if (s >= 85) return "Excellent";
  if (s >= 70) return "Good";
  if (s >= 50) return "Needs Work";
  return "Critical";
};

/** Build a compact JSON snapshot of a resume for the AI prompt. */
function resumeSnapshot(r: ResumeData | undefined | null): string {
  if (!r) return "(no resume)";
  return JSON.stringify({
    name: r.name,
    headline: r.headline,
    summary: r.summary,
    contact: r.contact,
    experience: r.experience.map((e) => ({
      title: e.title, company: e.company, location: e.location,
      startDate: e.startDate, endDate: e.endDate,
      bullets: e.bullets,
    })),
    education: r.education.map((e) => ({
      institution: e.institution, degree: e.degree, field: e.field,
    })),
    skills: r.skills.map((s) => s.name),
    projects: r.projects,
    certifications: r.certifications,
    languages: r.languages,
    achievements: r.achievements,
  });
}

/** Build a compact JD snapshot. */
function jdSnapshot(jd: JobDescription | undefined | null): string {
  if (!jd) return "(no job description)";
  return JSON.stringify({
    title: jd.title,
    company: jd.company,
    location: jd.location,
    responsibilities: jd.responsibilities,
    requiredSkills: jd.requiredSkills,
    preferredSkills: jd.preferredSkills,
    technologies: jd.technologies,
    experienceYears: jd.experienceYears,
    education: jd.education,
    keywords: jd.keywords,
    rawText: jd.rawText?.slice(0, 2500),
  });
}

// ============================================================================
// Main component
// ============================================================================

type ModuleTab =
  | "dashboard"
  | "ats"
  | "recruiter"
  | "job-match"
  | "benchmark"
  | "improvements"
  | "action-plan"
  | "fixes"
  | "interview"
  | "history";

export function ResumeReviewPlatform() {
  const resumes = useApp((s) => s.resumes);
  const jds = useApp((s) => s.jobDescriptions);
  const reviewReports = useApp((s) => s.reviewReports);
  const addReviewReport = useApp((s) => s.addReviewReport);
  const removeReviewReport = useApp((s) => s.removeReviewReport);
  const updateResume = useApp((s) => s.updateResume);
  const addResume = useApp((s) => s.addResume);
  const setActiveResume = useApp((s) => s.setActiveResume);
  const setActiveJD = useApp((s) => s.setActiveJD);
  const setView = useApp((s) => s.setView);
  const user = useApp((s) => s.user);
  const log = useApp((s) => s.log);
  const incUsage = useApp((s) => s.incUsage);

  // === Multi-source input state ===
  // Auto-detect the most recent resume and JD as defaults.
  const [resumeId, setResumeId] = useState("");
  const [optimizedResumeId, setOptimizedResumeId] = useState("");
  const [jdId, setJdId] = useState("");
  const [companyName, setCompanyName] = useState("");

  // Auto-select defaults on mount / when resumes arrive
  useEffect(() => {
    if (!resumeId && resumes.length > 0) {
      // Pick the most recently updated resume that's NOT marked as optimized
      const original = resumes.find((r) => r.source !== "ai-optimized") ?? resumes[0];
      setResumeId(original.id);
    }
    if (!jdId && jds.length > 0) setJdId(jds[0].id);
  }, [resumes, jds, resumeId, jdId]);

  const resume = useMemo(() => resumes.find((r) => r.id === resumeId) ?? null, [resumes, resumeId]);
  const optimizedResume = useMemo(() => resumes.find((r) => r.id === optimizedResumeId) ?? null, [resumes, optimizedResumeId]);
  const jd = useMemo(() => jds.find((j) => j.id === jdId) ?? null, [jds, jdId]);

  // Auto-detect industry from JD + resume
  const industryDetection = useMemo(() => {
    if (!resume) return null;
    const jdText = jd?.rawText || jd?.keywords?.join(" ") || "";
    const resumeText = `${resume.name} ${resume.headline ?? ""} ${resume.summary ?? ""} ${resume.experience.map((e) => e.title + " " + e.company).join(" ")}`;
    return detectIndustry(jdText, resumeText);
  }, [resume, jd]);
  const industryProfile = industryDetection ? INDUSTRY_PROFILES[industryDetection.industryId] : null;

  // Auto-populate company name from JD
  useEffect(() => {
    if (jd?.company && !companyName) setCompanyName(jd.company);
  }, [jd, companyName]);

  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<ModuleTab>("dashboard");
  const [report, setReport] = useState<ResumeReviewReport | null>(null);
  const [fixLoading, setFixLoading] = useState<string | null>(null);

  // ============================================================================
  // MAIN REVIEW — calls AI once with a comprehensive prompt that returns the
  // full multi-module JSON. This avoids 10 separate round-trips and keeps
  // the experience fast even on slow providers.
  // ============================================================================
  const runReview = async () => {
    if (!resume) { toast.error("Select a resume to review."); return; }
    setLoading(true);
    setReport(null);
    setActiveTab("dashboard");
    try {
      const industryLabel = industryProfile?.label ?? "Generic";
      // keywordBank is a single string of comma/newline-separated keywords — split it.
      const industryKeywordsRaw = industryProfile?.keywordBank ?? "";
      const industryKeywords = industryKeywordsRaw
        .split(/[\n,]/)
        .map((k) => k.trim())
        .filter((k) => k.length > 0)
        .slice(0, 60);

      const systemPrompt = `You are an elite Resume Review Platform combining the expertise of a Senior Recruiter, ATS Engineer, Industry Benchmark Analyst, and Career Coach. You analyze resumes holistically and produce a comprehensive multi-module review. NEVER fabricate information — only reference real content from the resume. Return ONLY valid JSON matching the requested schema. No prose, no markdown fences.`;

      const userPrompt = `# RESUME REVIEW REQUEST

## Context
- Industry: ${industryLabel}
- Industry Keywords: ${industryKeywords.join(", ")}
- Company: ${companyName || "(not specified)"}
- Has Optimized Resume: ${optimizedResume ? "yes" : "no"}
- Has Job Description: ${jd ? "yes" : "no"}

## ORIGINAL RESUME
${resumeSnapshot(resume)}

${optimizedResume ? `## OPTIMIZED RESUME (also review this)\n${resumeSnapshot(optimizedResume)}` : ""}

${jd ? `## JOB DESCRIPTION\n${jdSnapshot(jd)}` : ""}

## TASK
Generate a comprehensive review covering all 10 modules. Return JSON with EXACTLY this shape:

{
  "ats": {
    "atsScore": <0-100>,
    "keywordMatch": <0-100>,
    "missingKeywords": ["..."],
    "formattingIssues": ["..."],
    "sectionDetection": [{"section":"Contact","detected":true,"confidence":95}, ...],
    "parsingRisks": ["..."],
    "graphicsRisks": ["..."],
    "tablesRisks": ["..."],
    "fileCompatibility": ["PDF: ✓", "DOCX: ✓", "ATS-friendly: ✓"],
    "passProbability": <0-100>,
    "recommendations": ["..."]
  },
  "recruiter": {
    "overallScore": <0-10>,
    "sections": [
      {"section":"Headline","score":<0-10>,"strengths":["..."],"weaknesses":["..."],"recommendations":["..."]},
      {"section":"Summary","score":<0-10>,"strengths":["..."],"weaknesses":["..."],"recommendations":["..."]},
      {"section":"Experience","score":<0-10>,"strengths":["..."],"weaknesses":["..."],"recommendations":["..."]},
      {"section":"Skills","score":<0-10>,"strengths":["..."],"weaknesses":["..."],"recommendations":["..."]},
      {"section":"Education","score":<0-10>,"strengths":["..."],"weaknesses":["..."],"recommendations":["..."]},
      {"section":"Projects","score":<0-10>,"strengths":["..."],"weaknesses":["..."],"recommendations":["..."]},
      {"section":"Certifications","score":<0-10>,"strengths":["..."],"weaknesses":["..."],"recommendations":["..."]},
      {"section":"Achievements","score":<0-10>,"strengths":["..."],"weaknesses":["..."],"recommendations":["..."]},
      {"section":"Languages","score":<0-10>,"strengths":["..."],"weaknesses":["..."],"recommendations":["..."]}
    ]
  },
  "jobMatch": ${jd ? `{
    "overallMatch": <0-100>,
    "atsMatch": <0-100>,
    "experienceMatch": <0-100>,
    "skillMatch": <0-100>,
    "educationMatch": <0-100>,
    "industryMatch": <0-100>,
    "missingSkills": ["..."],
    "missingKeywords": ["..."],
    "missingCertifications": ["..."]
  }` : `null`},
  "benchmark": {
    "industry": "${industryLabel}",
    "role": "<detected role>",
    "seniority": "<Entry|Mid|Senior|Lead|Executive>",
    "country": "<detected or 'Global'>",
    "industryReadinessScore": <0-100>,
    "benchmarkComparisons": [
      {"metric":"Years of Experience","candidate":<n>,"industryAverage":<n>,"topPercentile":<n>},
      {"metric":"Skills Count","candidate":<n>,"industryAverage":<n>,"topPercentile":<n>},
      {"metric":"Quantified Bullets %","candidate":<n>,"industryAverage":<n>,"topPercentile":<n>}
    ],
    "insights": ["..."]
  },
  "improvements": {
    "betterSummary": "<a stronger 2-3 sentence summary>",
    "betterHeadlines": ["<alt headline 1>","<alt headline 2>","<alt headline 3>"],
    "betterSkills": ["<skill to add 1>","<skill to add 2>"],
    "betterBulletPoints": [{"original":"<weak bullet>","improved":"<strong bullet with metric>"}],
    "betterAchievements": ["..."],
    "actionVerbs": ["Led","Built","Shipped","..."],
    "metrics": ["<suggested metric to add>"],
    "highValueKeywords": ["..."]
  },
  "actionPlan": {
    "criticalFixes": [{"fix":"...","impact":"..."}],
    "highPriorityFixes": [{"fix":"...","impact":"..."}],
    "optionalImprovements": [{"fix":"...","impact":"..."}],
    "expectedAtsIncrease": <number of ATS points>
  },
  "interviewReadiness": {
    "likelyQuestions": ["..."],
    "weakAreas": ["..."],
    "talkingPoints": ["..."],
    "preparationAdvice": ["..."]
  }
}

Rules:
- All scores must be REALISTIC and derived from the actual resume content. NEVER use placeholder scores.
- Section scores should reflect actual content quality (empty sections get 0, not 5).
- Missing keywords must come from the JD or industry keyword bank.
- Bullet improvements must rewrite ACTUAL bullets from the resume, not invent new ones.
- Be honest — a weak resume should get low scores, not generic 7/10s.`;

      const result = await recordAI({
        systemPrompt,
        userPrompt,
        maxTokens: 4500,
        temperature: 0.3,
        taskCategory: "document",
      });

      let data: any;
      try { data = extractJSON<any>(result.text); }
      catch { throw new Error("AI did not return valid JSON. Please try again."); }

      // Validate minimum shape
      if (!data.ats || !data.recruiter || !data.benchmark || !data.improvements || !data.actionPlan || !data.interviewReadiness) {
        throw new Error("AI response missing required modules. Please try again.");
      }

      // === DEFENSIVE NORMALIZATION ===
      // The AI may return array elements as objects (e.g. {goal, actions, resources})
      // instead of plain strings, which crashes React with error #31
      // ("Objects are not valid as a React child") when we render {item} inside
      // <li>/<Badge>. Coerce every array field to string[] and every scalar to
      // its expected type so the render is always safe.
      const toArray = (v: any): string[] => {
        if (!Array.isArray(v)) {
          if (typeof v === "string" && v.trim()) return v.split(/[,\n]/).map((s) => s.trim()).filter(Boolean);
          return [];
        }
        return v.map((item) => {
          if (item === null || item === undefined) return "";
          if (typeof item === "string") return item;
          if (typeof item === "number" || typeof item === "boolean") return String(item);
          try {
            const vals = Object.values(item as any);
            if (vals.length > 0 && vals.every((x) => typeof x === "string" || typeof x === "number")) {
              return vals.map(String).join(" — ");
            }
            return JSON.stringify(item);
          } catch { return String(item); }
        }).filter((s) => s.length > 0);
      };
      const toStr = (v: any): string => {
        if (v === null || v === undefined) return "";
        if (typeof v === "string") return v;
        if (typeof v === "number" || typeof v === "boolean") return String(v);
        try { return JSON.stringify(v); } catch { return String(v); }
      };
      const toNum = (v: any): number => {
        const n = Number(v);
        return Number.isFinite(n) ? n : 0;
      };
      // Preserve object-shaped array elements (like betterBulletPoints {original, improved}
      // and benchmarkComparisons {metric, candidate, ...}) but only if they're objects.
      const toObjArray = <T,>(v: any): T[] => Array.isArray(v) ? v.filter((x) => x && typeof x === "object") : [];
      // Section detection array — each item is {section, detected, confidence}
      const toSectionArray = (v: any) => {
        if (!Array.isArray(v)) return [];
        return v.map((item) => ({
          section: toStr(item?.section),
          detected: !!item?.detected,
          confidence: toNum(item?.confidence),
        }));
      };
      // Fix items — each is {fix, impact}
      const toFixArray = (v: any) => {
        if (!Array.isArray(v)) return [];
        return v.map((item) => ({
          fix: toStr(item?.fix),
          impact: toStr(item?.impact),
        }));
      };
      // Section feedback — each is {section, score, strengths[], weaknesses[], recommendations[]}
      const toSectionFeedback = (v: any) => {
        if (!Array.isArray(v)) return [];
        return v.map((item) => ({
          section: toStr(item?.section),
          score: toNum(item?.score),
          strengths: toArray(item?.strengths),
          weaknesses: toArray(item?.weaknesses),
          recommendations: toArray(item?.recommendations),
        }));
      };

      // Normalize each module
      const normAts = {
        atsScore: toNum(data.ats.atsScore),
        keywordMatch: toNum(data.ats.keywordMatch),
        missingKeywords: toArray(data.ats.missingKeywords),
        formattingIssues: toArray(data.ats.formattingIssues),
        sectionDetection: toSectionArray(data.ats.sectionDetection),
        parsingRisks: toArray(data.ats.parsingRisks),
        graphicsRisks: toArray(data.ats.graphicsRisks),
        tablesRisks: toArray(data.ats.tablesRisks),
        fileCompatibility: toArray(data.ats.fileCompatibility),
        passProbability: toNum(data.ats.passProbability),
        recommendations: toArray(data.ats.recommendations),
      };
      const normRecruiter = {
        overallScore: toNum(data.recruiter.overallScore),
        sections: toSectionFeedback(data.recruiter.sections),
      };
      const normJobMatch = data.jobMatch ? {
        overallMatch: toNum(data.jobMatch.overallMatch),
        atsMatch: toNum(data.jobMatch.atsMatch),
        experienceMatch: toNum(data.jobMatch.experienceMatch),
        skillMatch: toNum(data.jobMatch.skillMatch),
        educationMatch: toNum(data.jobMatch.educationMatch),
        industryMatch: toNum(data.jobMatch.industryMatch),
        missingSkills: toArray(data.jobMatch.missingSkills),
        missingKeywords: toArray(data.jobMatch.missingKeywords),
        missingCertifications: toArray(data.jobMatch.missingCertifications),
      } : null;
      const normBenchmark = {
        industry: toStr(data.benchmark.industry),
        role: toStr(data.benchmark.role),
        seniority: toStr(data.benchmark.seniority),
        country: toStr(data.benchmark.country),
        industryReadinessScore: toNum(data.benchmark.industryReadinessScore),
        benchmarkComparisons: toObjArray<any>(data.benchmark.benchmarkComparisons).map((b) => ({
          metric: toStr(b.metric),
          candidate: toNum(b.candidate),
          industryAverage: toNum(b.industryAverage),
          topPercentile: toNum(b.topPercentile),
        })),
        insights: toArray(data.benchmark.insights),
      };
      const normImprovements = {
        betterSummary: toStr(data.improvements.betterSummary),
        betterHeadlines: toArray(data.improvements.betterHeadlines),
        betterSkills: toArray(data.improvements.betterSkills),
        betterBulletPoints: toObjArray<any>(data.improvements.betterBulletPoints).map((b) => ({
          original: toStr(b.original),
          improved: toStr(b.improved),
        })),
        betterAchievements: toArray(data.improvements.betterAchievements),
        actionVerbs: toArray(data.improvements.actionVerbs),
        metrics: toArray(data.improvements.metrics),
        highValueKeywords: toArray(data.improvements.highValueKeywords),
      };
      const normActionPlan = {
        criticalFixes: toFixArray(data.actionPlan.criticalFixes),
        highPriorityFixes: toFixArray(data.actionPlan.highPriorityFixes),
        optionalImprovements: toFixArray(data.actionPlan.optionalImprovements),
        expectedAtsIncrease: toNum(data.actionPlan.expectedAtsIncrease),
      };
      const normInterview = {
        likelyQuestions: toArray(data.interviewReadiness.likelyQuestions),
        weakAreas: toArray(data.interviewReadiness.weakAreas),
        talkingPoints: toArray(data.interviewReadiness.talkingPoints),
        preparationAdvice: toArray(data.interviewReadiness.preparationAdvice),
      };

      // Compute dashboard aggregate scores
      const formattingScore = normAts.formattingIssues.length > 0
        ? Math.max(0, 100 - normAts.formattingIssues.length * 8)
        : normAts.atsScore;
      const readabilityScore = Math.round(
        (normRecruiter.sections.find((s) => s.section === "Summary")?.score ?? 5) * 10
      );
      const recruiterScore = normRecruiter.overallScore;

      const newReport: ResumeReviewReport = {
        id: uid("rr"),
        userId: user?.id || "anonymous",
        resumeId: resume.id,
        optimizedResumeId: optimizedResume?.id,
        jdId: jd?.id,
        companyName: companyName || jd?.company || undefined,
        industryProfile: industryProfile?.label ?? "Generic",
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
        ats: normAts,
        recruiter: normRecruiter,
        jobMatch: normJobMatch,
        benchmark: normBenchmark,
        improvements: normImprovements,
        actionPlan: normActionPlan,
        interviewReadiness: normInterview,
        dashboard: {
          atsScore: normAts.atsScore,
          recruiterScore,
          jobMatch: normJobMatch?.overallMatch ?? null,
          formattingScore,
          readabilityScore,
          industryBenchmark: normBenchmark.industryReadinessScore,
        },
      };

      setReport(newReport);
      addReviewReport(newReport);
      incUsage("atsChecks");
      log({
        actor: user?.email || "you",
        action: "AI Resume Review generated",
        category: "ai",
        details: `ATS ${newReport.dashboard.atsScore}/100 · Recruiter ${newReport.dashboard.recruiterScore}/10 · Industry ${newReport.dashboard.industryBenchmark}/100 via ${result.provider}`,
        severity: "info",
      });
      toast.success(`Review complete — ATS ${newReport.dashboard.atsScore}/100 · Recruiter ${newReport.dashboard.recruiterScore}/10`);
    } catch (e: any) {
      toast.error(e?.message || "Review failed. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  // ============================================================================
  // ONE-CLICK FIXES — Module 7
  // Each fix calls AI to rewrite a specific section and applies it to the
  // resume via updateResume() (or creates an optimized copy via addResume()).
  // ============================================================================
  const runOneClickFix = async (fixType: "summary" | "skills" | "experience" | "ats" | "all") => {
    if (!resume) { toast.error("Select a resume first."); return; }
    if (!report) { toast.error("Run a review first to get recommendations."); return; }
    setFixLoading(fixType);
    try {
      const fixPrompts: Record<string, string> = {
        summary: `Rewrite ONLY the summary section of this resume. Use the review's recommendations and the suggested betterSummary. Return JSON: {"summary": "..."}.\n\nRESUME:\n${resumeSnapshot(resume)}\n\nREVIEW SUMMARY RECOMMENDATIONS:\n${JSON.stringify(report.recruiter.sections.find((s) => s.section === "Summary"))}\n\nSUGGESTED BETTER SUMMARY:\n${report.improvements.betterSummary}`,
        skills: `Improve ONLY the skills section. Add the suggested missing skills, remove redundant ones, and reorganize by category. Return JSON: {"skills": [{"name":"...","category":"..."}]}.\n\nRESUME:\n${resumeSnapshot(resume)}\n\nSUGGESTED SKILLS TO ADD:\n${JSON.stringify(report.improvements.betterSkills)}`,
        experience: `Rewrite ONLY the experience bullets to be more impactful. Apply the betterBulletPoints suggestions. Return JSON: {"experience": [{"title":"...","company":"...","location":"...","startDate":"...","endDate":"...","bullets":["..."]}]}.\n\nRESUME:\n${resumeSnapshot(resume)}\n\nBULLET IMPROVEMENTS:\n${JSON.stringify(report.improvements.betterBulletPoints)}`,
        ats: `Optimize this resume for maximum ATS score by embedding the missing keywords naturally and applying all action verbs. NEVER fabricate experience. Return the FULL optimized resume as JSON matching the resume schema.\n\nRESUME:\n${resumeSnapshot(resume)}\n\nMISSING KEYWORDS:\n${JSON.stringify(report.ats.missingKeywords)}\n\nACTION VERBS:\n${JSON.stringify(report.improvements.actionVerbs)}`,
        all: `Fully optimize this resume by applying ALL recommendations from the review: better summary, better headlines, better skills, better bullets, missing keywords. NEVER fabricate experience. Return the FULL optimized resume as JSON matching the resume schema with keys: name, headline, summary, contact, experience, education, skills, projects, certifications, languages, achievements.\n\nRESUME:\n${resumeSnapshot(resume)}\n\nFULL REVIEW:\n${JSON.stringify({ improvements: report.improvements, ats: report.ats, actionPlan: report.actionPlan })}`,
      };

      const result = await recordAI({
        systemPrompt: "You are an expert resume optimizer. Apply the requested fixes precisely. Return ONLY valid JSON. NEVER fabricate experience or metrics not present in the original resume.",
        userPrompt: fixPrompts[fixType],
        maxTokens: fixType === "all" || fixType === "ats" ? 3500 : 1500,
        temperature: 0.4,
        taskCategory: "document",
      });

      let data: any;
      try { data = extractJSON<any>(result.text); }
      catch { throw new Error("AI did not return valid JSON for the fix."); }

      if (fixType === "all" || fixType === "ats") {
        // Create an optimized copy as a new resume
        const optimized: ResumeData = {
          ...resume,
          id: uid("r"),
          headline: data.headline || resume.headline,
          summary: data.summary || resume.summary,
          skills: (data.skills ?? resume.skills).map((s: any) => typeof s === "string" ? { id: uid("s"), name: s, category: "Skills" } : { id: uid("s"), ...s }),
          experience: (data.experience ?? resume.experience).map((e: any) => ({
            id: uid("e"), title: e.title || "", company: e.company || "", location: e.location || "",
            startDate: e.startDate || "", endDate: e.endDate || "Present",
            bullets: e.bullets ?? [],
          })),
          template: resume.template,
          accentColor: resume.accentColor,
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
          source: "ai-optimized",
          fileName: `${resume.name.replace(/\s+/g, "_")}_optimized.pdf`,
        };
        addResume(optimized);
        toast.success(`Optimized resume created — "${optimized.name} (Optimized)" added to your library.`);
      } else {
        // Patch the existing resume
        const patch: Partial<ResumeData> = {};
        if (fixType === "summary" && data.summary) patch.summary = data.summary;
        if (fixType === "skills" && data.skills) {
          patch.skills = data.skills.map((s: any) => typeof s === "string" ? { id: uid("s"), name: s, category: "Skills" } : { id: uid("s"), ...s });
        }
        if (fixType === "experience" && data.experience) {
          patch.experience = data.experience.map((e: any) => ({
            id: uid("e"), title: e.title || "", company: e.company || "", location: e.location || "",
            startDate: e.startDate || "", endDate: e.endDate || "Present",
            bullets: e.bullets ?? [],
          }));
        }
        updateResume(resume.id, patch);
        toast.success(`${fixType.charAt(0).toUpperCase() + fixType.slice(1)} updated — review the changes in My Resumes.`);
      }
      log({
        actor: user?.email || "you",
        action: `One-click fix applied: ${fixType}`,
        category: "ai",
        details: `Resume: ${resume.name} via ${result.provider}`,
        severity: "info",
      });
    } catch (e: any) {
      toast.error(e?.message || "Fix failed.");
    } finally {
      setFixLoading(null);
    }
  };

  // ============================================================================
  // OPTIMIZE RESUME CTA — navigate to the Resume Optimizer with the current
  // review's resume + JD pre-selected so the user can immediately run the
  // 5-agent optimization pipeline. The optimizer will pick up the active
  // resume + active JD from the store.
  // ============================================================================
  const goToOptimizer = () => {
    if (!resume) { toast.error("No resume selected."); return; }
    // Set the active resume + JD so the Optimizer picks them up automatically.
    // IMPORTANT: always set BOTH — if no JD is selected, explicitly clear
    // activeJdId so the Optimizer doesn't pick up a stale JD from a previous
    // navigation (which would auto-load the wrong job description).
    setActiveResume(resume.id);
    if (jd) {
      setActiveJD(jd.id);
    } else {
      setActiveJD(null);
    }
    log({
      actor: user?.email || "you",
      action: "Optimize Resume clicked from AI Resume Review",
      category: "ai",
      details: `Resume: ${resume.name}${jd ? ` · JD: ${jd.title}` : ""} · Review ATS: ${report?.dashboard.atsScore ?? "?"}/100`,
      severity: "info",
    });
    toast.success("Opening Resume Optimizer…");
    setView("optimizer");
  };

  // ============================================================================
  // EXPORTS
  // ============================================================================
  const exportJSON = () => {
    if (!report) return;
    const blob = new Blob([JSON.stringify(report, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `resume-review-${resume?.name?.replace(/\s+/g, "_") ?? "report"}-${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
    URL.revokeObjectURL(url);
    toast.success("JSON report exported.");
  };

  const exportPDF = () => {
    if (!report) return;
    // Use the browser's print dialog — user can save as PDF.
    // This is the most reliable cross-browser approach on Cloudflare Free.
    window.print();
    toast.info("Use your browser's print dialog to save as PDF.");
  };

  const exportDOCX = () => {
    if (!report) return;
    // Build a plain-text version that pastes cleanly into Word/Google Docs.
    const lines: string[] = [];
    lines.push("AI RESUME REVIEW REPORT");
    lines.push("========================");
    lines.push(`Generated: ${new Date(report.createdAt).toLocaleString()}`);
    lines.push(`Resume: ${resume?.name ?? "N/A"}`);
    if (optimizedResume) lines.push(`Optimized Resume: ${optimizedResume.name}`);
    if (jd) lines.push(`Job: ${jd.title} at ${jd.company || "N/A"}`);
    lines.push(`Industry: ${report.industryProfile}`);
    lines.push("");
    lines.push("DASHBOARD");
    lines.push("---------");
    lines.push(`ATS Score: ${report.dashboard.atsScore}/100`);
    lines.push(`Recruiter Score: ${report.dashboard.recruiterScore}/10`);
    if (report.dashboard.jobMatch !== null) lines.push(`Job Match: ${report.dashboard.jobMatch}%`);
    lines.push(`Formatting Score: ${report.dashboard.formattingScore}/100`);
    lines.push(`Readability Score: ${report.dashboard.readabilityScore}/100`);
    lines.push(`Industry Benchmark: ${report.dashboard.industryBenchmark}/100`);
    lines.push("");
    lines.push("MODULE 1 — ATS REVIEW");
    lines.push("---------------------");
    lines.push(`ATS Score: ${report.ats.atsScore}/100`);
    lines.push(`Keyword Match: ${report.ats.keywordMatch}/100`);
    lines.push(`Pass Probability: ${report.ats.passProbability}%`);
    lines.push(`Missing Keywords: ${report.ats.missingKeywords.join(", ") || "none"}`);
    lines.push(`Formatting Issues: ${report.ats.formattingIssues.join("; ") || "none"}`);
    lines.push(`Parsing Risks: ${report.ats.parsingRisks.join("; ") || "none"}`);
    lines.push(`Recommendations: ${report.ats.recommendations.join("; ") || "none"}`);
    lines.push("");
    lines.push("MODULE 2 — RECRUITER REVIEW");
    lines.push("---------------------------");
    lines.push(`Overall: ${report.recruiter.overallScore}/10`);
    for (const s of report.recruiter.sections) {
      lines.push(`  ${s.section} (${s.score}/10)`);
      lines.push(`    Strengths: ${s.strengths.join("; ")}`);
      lines.push(`    Weaknesses: ${s.weaknesses.join("; ")}`);
      lines.push(`    Recommendations: ${s.recommendations.join("; ")}`);
    }
    lines.push("");
    if (report.jobMatch) {
      lines.push("MODULE 3 — JOB MATCH REVIEW");
      lines.push("---------------------------");
      lines.push(`Overall Match: ${report.jobMatch.overallMatch}%`);
      lines.push(`ATS Match: ${report.jobMatch.atsMatch}%`);
      lines.push(`Experience Match: ${report.jobMatch.experienceMatch}%`);
      lines.push(`Skill Match: ${report.jobMatch.skillMatch}%`);
      lines.push(`Education Match: ${report.jobMatch.educationMatch}%`);
      lines.push(`Industry Match: ${report.jobMatch.industryMatch}%`);
      lines.push(`Missing Skills: ${report.jobMatch.missingSkills.join(", ") || "none"}`);
      lines.push(`Missing Keywords: ${report.jobMatch.missingKeywords.join(", ") || "none"}`);
      lines.push(`Missing Certifications: ${report.jobMatch.missingCertifications.join(", ") || "none"}`);
      lines.push("");
    }
    lines.push("MODULE 4 — INDUSTRY BENCHMARK");
    lines.push("------------------------------");
    lines.push(`Industry: ${report.benchmark.industry}`);
    lines.push(`Role: ${report.benchmark.role}`);
    lines.push(`Seniority: ${report.benchmark.seniority}`);
    lines.push(`Country: ${report.benchmark.country}`);
    lines.push(`Industry Readiness Score: ${report.benchmark.industryReadinessScore}/100`);
    for (const b of report.benchmark.benchmarkComparisons) {
      lines.push(`  ${b.metric}: candidate=${b.candidate}, industry avg=${b.industryAverage}, top percentile=${b.topPercentile}`);
    }
    lines.push(`Insights: ${report.benchmark.insights.join("; ")}`);
    lines.push("");
    lines.push("MODULE 5 — RESUME IMPROVEMENTS");
    lines.push("------------------------------");
    lines.push(`Better Summary: ${report.improvements.betterSummary}`);
    lines.push(`Better Headlines: ${report.improvements.betterHeadlines.join(" | ")}`);
    lines.push(`Skills to Add: ${report.improvements.betterSkills.join(", ") || "none"}`);
    lines.push(`Better Bullets:`);
    for (const b of report.improvements.betterBulletPoints) {
      lines.push(`  - "${b.original}" → "${b.improved}"`);
    }
    lines.push(`Action Verbs: ${report.improvements.actionVerbs.join(", ")}`);
    lines.push(`Suggested Metrics: ${report.improvements.metrics.join(", ")}`);
    lines.push(`High-Value Keywords: ${report.improvements.highValueKeywords.join(", ")}`);
    lines.push("");
    lines.push("MODULE 6 — PRIORITY ACTION PLAN");
    lines.push("------------------------------");
    lines.push(`Expected ATS Increase: +${report.actionPlan.expectedAtsIncrease} points`);
    lines.push(`Critical Fixes:`);
    for (const f of report.actionPlan.criticalFixes) lines.push(`  - ${f.fix} (impact: ${f.impact})`);
    lines.push(`High Priority Fixes:`);
    for (const f of report.actionPlan.highPriorityFixes) lines.push(`  - ${f.fix} (impact: ${f.impact})`);
    lines.push(`Optional Improvements:`);
    for (const f of report.actionPlan.optionalImprovements) lines.push(`  - ${f.fix} (impact: ${f.impact})`);
    lines.push("");
    lines.push("MODULE 8 — INTERVIEW READINESS");
    lines.push("-----------------------------");
    lines.push(`Likely Questions:`);
    for (const q of report.interviewReadiness.likelyQuestions) lines.push(`  - ${q}`);
    lines.push(`Weak Areas: ${report.interviewReadiness.weakAreas.join(", ")}`);
    lines.push(`Talking Points: ${report.interviewReadiness.talkingPoints.join("; ")}`);
    lines.push(`Preparation Advice: ${report.interviewReadiness.preparationAdvice.join("; ")}`);

    const blob = new Blob([lines.join("\n")], { type: "text/plain" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `resume-review-${resume?.name?.replace(/\s+/g, "_") ?? "report"}-${new Date().toISOString().slice(0, 10)}.docx.txt`;
    a.click();
    URL.revokeObjectURL(url);
    toast.success("DOCX-compatible text exported (opens in Word/Google Docs).");
  };

  // ============================================================================
  // Render
  // ============================================================================

  const tabs: { id: ModuleTab; label: string; icon: string; disabled?: boolean }[] = [
    { id: "dashboard", label: "Dashboard", icon: "LayoutDashboard" },
    { id: "ats", label: "ATS Review", icon: "ShieldCheck" },
    { id: "recruiter", label: "Recruiter Review", icon: "Users" },
    { id: "job-match", label: "Job Match", icon: "Target", disabled: !report?.jobMatch },
    { id: "benchmark", label: "Industry Benchmark", icon: "BarChart3" },
    { id: "improvements", label: "Improvements", icon: "Sparkles" },
    { id: "action-plan", label: "Action Plan", icon: "ListChecks" },
    { id: "fixes", label: "One-Click Fixes", icon: "Wand2" },
    { id: "interview", label: "Interview Readiness", icon: "MessageSquare" },
    { id: "history", label: "History", icon: "History" },
  ];

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <h1 className="font-display text-2xl font-bold flex items-center gap-2">
            <Icon name="FileSearch" className="w-6 h-6 text-brand" /> AI Resume Review Platform
          </h1>
          <p className="text-sm text-muted-foreground mt-1">
            Recruiter-grade review · ATS analysis · Industry benchmark · Job match · One-click fixes · Interview readiness
          </p>
        </div>
        {report && (
          <div className="flex gap-2 flex-wrap">
            <Button size="sm" variant="outline" onClick={exportJSON} className="gap-1.5"><Icon name="Braces" className="w-3.5 h-3.5" /> JSON</Button>
            <Button size="sm" variant="outline" onClick={exportDOCX} className="gap-1.5"><Icon name="FileType" className="w-3.5 h-3.5" /> DOCX</Button>
            <Button size="sm" variant="outline" onClick={exportPDF} className="gap-1.5"><Icon name="Printer" className="w-3.5 h-3.5" /> PDF</Button>
          </div>
        )}
      </div>

      {/* Multi-source input */}
      <Card><CardContent className="p-4 space-y-4">
        <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-3">
          <div>
            <Label>Original Resume</Label>
            <select value={resumeId} onChange={(e) => setResumeId(e.target.value)} className="w-full h-9 px-3 rounded-md border border-input bg-background text-sm mt-1">
              <option value="">Select...</option>
              {resumes.map((r) => <option key={r.id} value={r.id}>{r.name}{r.source === "ai-optimized" ? " (optimized)" : ""}</option>)}
            </select>
          </div>
          <div>
            <Label>Optimized Resume <span className="text-muted-foreground text-[10px]">(optional)</span></Label>
            <select value={optimizedResumeId} onChange={(e) => setOptimizedResumeId(e.target.value)} className="w-full h-9 px-3 rounded-md border border-input bg-background text-sm mt-1">
              <option value="">None</option>
              {resumes.filter((r) => r.id !== resumeId).map((r) => <option key={r.id} value={r.id}>{r.name}</option>)}
            </select>
          </div>
          <div>
            <Label>Job Description <span className="text-muted-foreground text-[10px]">(optional)</span></Label>
            <select value={jdId} onChange={(e) => setJdId(e.target.value)} className="w-full h-9 px-3 rounded-md border border-input bg-background text-sm mt-1">
              <option value="">None</option>
              {jds.map((j) => <option key={j.id} value={j.id}>{j.title}{j.company ? ` — ${j.company}` : ""}</option>)}
            </select>
          </div>
          <div>
            <Label>Company <span className="text-muted-foreground text-[10px]">(auto-detected)</span></Label>
            <Input value={companyName} onChange={(e) => setCompanyName(e.target.value)} placeholder="e.g. Emirates" className="mt-1" />
          </div>
        </div>

        {/* Auto-detected context badges */}
        <div className="flex flex-wrap gap-2 items-center text-xs">
          {industryProfile && <Badge variant="brand" className="gap-1"><Icon name="Building2" className="w-3 h-3" /> Industry: {industryProfile.label}</Badge>}
          {industryDetection && industryDetection.confidence >= 30 && <Badge variant="outline">Confidence: {industryDetection.confidence}%</Badge>}
          {resume && <Badge variant="outline">Resume: {resume.name}</Badge>}
          {optimizedResume && <Badge variant="success">Optimized: {optimizedResume.name}</Badge>}
          {jd && <Badge variant="warning">JD: {jd.title}</Badge>}
          {!jd && <Badge variant="outline">No JD — Job Match module will be skipped</Badge>}
        </div>

        <Button onClick={runReview} disabled={loading || !resume} className="bg-brand hover:bg-brand-dark text-white gap-2 w-full sm:w-auto">
          <Icon name={loading ? "Loader2" : "FileSearch"} className={`w-4 h-4 ${loading ? "animate-spin" : ""}`} />
          {loading ? "Running multi-module review..." : "Run Full Review"}
        </Button>
        {!resume && <p className="text-xs text-amber-600 mt-1">⚠ Create or upload a resume first to enable the review.</p>}
      </CardContent></Card>

      {/* Loading state */}
      {loading && (
        <Card><CardContent className="p-4">
          <div className="flex items-center gap-2 mb-2">
            <Icon name="Loader2" className="w-4 h-4 animate-spin text-brand" />
            <span className="text-sm text-muted-foreground">Running 10-module review — this may take 15-30 seconds…</span>
          </div>
          <div className="grid grid-cols-2 sm:grid-cols-5 gap-2 text-[10px] text-muted-foreground">
            {["ATS", "Recruiter", "Job Match", "Benchmark", "Improvements", "Action Plan", "Fixes", "Interview", "Dashboard", "Persistence"].map((m, i) => (
              <div key={m} className="flex items-center gap-1"><span className="text-brand">✓</span> {m}</div>
            ))}
          </div>
        </CardContent></Card>
      )}

      {/* Empty state */}
      {!loading && !report && reviewReports.length === 0 && (
        <Card><CardContent className="py-12 text-center">
          <Icon name="FileSearch" className="w-12 h-12 text-muted-foreground/30 mx-auto" />
          <h3 className="mt-3 font-semibold">No reviews yet</h3>
          <p className="text-sm text-muted-foreground mt-1 max-w-md mx-auto">
            Select a resume above and click <strong>Run Full Review</strong> to generate a comprehensive 10-module analysis — ATS score, recruiter feedback, industry benchmark, job match, one-click fixes, and interview readiness.
          </p>
        </CardContent></Card>
      )}

      {/* Tabs + content */}
      {report && !loading && (
        <>
          {/* Tab strip */}
          <div className="flex gap-1 overflow-x-auto pb-1 border-b border-border">
            {tabs.map((t) => (
              <button
                key={t.id}
                disabled={t.disabled}
                onClick={() => setActiveTab(t.id)}
                className={`flex items-center gap-1.5 px-3 py-2 text-xs font-medium whitespace-nowrap border-b-2 transition-colors ${
                  activeTab === t.id
                    ? "border-brand text-brand"
                    : t.disabled
                      ? "border-transparent text-muted-foreground/40 cursor-not-allowed"
                      : "border-transparent text-muted-foreground hover:text-foreground"
                }`}
              >
                <Icon name={t.icon} className="w-3.5 h-3.5" /> {t.label}
              </button>
            ))}
          </div>

          <AnimatePresence mode="wait">
            <motion.div key={activeTab} initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -8 }} transition={{ duration: 0.15 }}>
              {activeTab === "dashboard" && <DashboardModule report={report} />}
              {activeTab === "ats" && <ATSModule report={report} />}
              {activeTab === "recruiter" && <RecruiterModule report={report} />}
              {activeTab === "job-match" && report.jobMatch && <JobMatchModule report={report} />}
              {activeTab === "benchmark" && <BenchmarkModule report={report} />}
              {activeTab === "improvements" && <ImprovementsModule report={report} />}
              {activeTab === "action-plan" && <ActionPlanModule report={report} />}
              {activeTab === "fixes" && <FixesModule report={report} onFix={runOneClickFix} loading={fixLoading} />}
              {activeTab === "interview" && <InterviewModule report={report} />}
              {activeTab === "history" && (
                <HistoryModule
                  reports={reviewReports}
                  resumes={resumes}
                  currentReportId={report.id}
                  onSelect={(r) => setReport(r)}
                  onDelete={(id) => { removeReviewReport(id); if (id === report.id) setReport(null); }}
                />
              )}
            </motion.div>
          </AnimatePresence>

          {/* === OPTIMIZE RESUME CTA ===
              Prominent action banner shown after every review tab (except
              History) so the user can immediately act on the review's
              recommendations by jumping to the 5-agent Resume Optimizer
              with the current resume + JD pre-selected. */}
          {activeTab !== "history" && (
            <motion.div
              initial={{ opacity: 0, y: 12 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.2, duration: 0.3 }}
            >
              <Card className="border-2 border-brand/40 bg-gradient-to-br from-brand/5 to-emerald-500/5 dark:from-brand/10 dark:to-emerald-500/10">
                <CardContent className="p-5">
                  <div className="flex flex-col sm:flex-row items-start sm:items-center gap-4">
                    <div className="w-12 h-12 rounded-xl bg-brand/15 flex items-center justify-center shrink-0">
                      <Icon name="Wand2" className="w-6 h-6 text-brand" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <h3 className="font-display font-bold text-base flex items-center gap-2 flex-wrap">
                        Ready to optimize this resume?
                        {report.dashboard.atsScore < 85 && (
                          <Badge variant="warning" className="text-[10px] gap-1">
                            <Icon name="TrendingUp" className="w-3 h-3" /> +{report.actionPlan.expectedAtsIncrease} pts available
                          </Badge>
                        )}
                      </h3>
                      <p className="text-xs text-muted-foreground mt-1">
                        Jump to the <strong>Resume Optimizer</strong> with this resume{jd ? " and job description" : ""} pre-loaded. The 5-agent pipeline will rewrite bullets, embed missing keywords, and maximize your ATS score.
                      </p>
                      <div className="flex flex-wrap gap-1.5 mt-2">
                        {report.ats.missingKeywords.slice(0, 5).map((k, i) => (
                          <span key={i} className="text-[10px] px-1.5 py-0.5 rounded bg-red-100 text-red-700 dark:bg-red-950/40 dark:text-red-300">{k}</span>
                        ))}
                        {report.ats.missingKeywords.length > 5 && (
                          <span className="text-[10px] px-1.5 py-0.5 rounded bg-muted text-muted-foreground">+{report.ats.missingKeywords.length - 5} more</span>
                        )}
                      </div>
                    </div>
                    <div className="flex flex-col gap-2 shrink-0 w-full sm:w-auto">
                      <Button onClick={goToOptimizer} className="bg-brand hover:bg-brand-dark text-white gap-2 h-10 px-5">
                        <Icon name="Wand2" className="w-4 h-4" /> Optimize Resume
                        <Icon name="ArrowRight" className="w-4 h-4" />
                      </Button>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => setActiveTab("fixes")}
                        className="gap-1.5 text-xs h-7"
                      >
                        <Icon name="Zap" className="w-3 h-3" /> Or try One-Click Fixes
                      </Button>
                    </div>
                  </div>
                </CardContent>
              </Card>
            </motion.div>
          )}
        </>
      )}

      {/* If no current report but history exists, show history list */}
      {!report && !loading && reviewReports.length > 0 && (
        <HistoryModule
          reports={reviewReports}
          resumes={resumes}
          currentReportId={null}
          onSelect={(r) => { setReport(r); setActiveTab("dashboard"); }}
          onDelete={(id) => removeReviewReport(id)}
        />
      )}
    </div>
  );
}

// ============================================================================
// MODULE 9 — VISUAL DASHBOARD
// ============================================================================

function DashboardModule({ report }: { report: ResumeReviewReport }) {
  const scores = [
    { label: "ATS Score", value: report.dashboard.atsScore, max: 100, color: scoreColor(report.dashboard.atsScore) },
    { label: "Recruiter Score", value: report.dashboard.recruiterScore * 10, max: 100, color: scoreColor(report.dashboard.recruiterScore * 10) },
    { label: "Formatting", value: report.dashboard.formattingScore, max: 100, color: scoreColor(report.dashboard.formattingScore) },
    { label: "Readability", value: report.dashboard.readabilityScore, max: 100, color: scoreColor(report.dashboard.readabilityScore) },
    { label: "Industry Benchmark", value: report.dashboard.industryBenchmark, max: 100, color: scoreColor(report.dashboard.industryBenchmark) },
  ];
  if (report.dashboard.jobMatch !== null) {
    scores.push({ label: "Job Match", value: report.dashboard.jobMatch, max: 100, color: scoreColor(report.dashboard.jobMatch) });
  }

  // Radar chart — SVG-based (no external dependency, works on Cloudflare Free)
  const radarValues = scores.slice(0, 6);
  const radarSize = 220;
  const radarCenter = radarSize / 2;
  const radarRadius = radarSize / 2 - 30;
  const radarPoints = radarValues.map((s, i) => {
    const angle = (Math.PI * 2 * i) / radarValues.length - Math.PI / 2;
    const r = (s.value / s.max) * radarRadius;
    return [radarCenter + r * Math.cos(angle), radarCenter + r * Math.sin(angle)];
  });
  const radarPath = radarPoints.map((p) => p.join(",")).join(" ");
  const radarLabels = radarValues.map((s, i) => {
    const angle = (Math.PI * 2 * i) / radarValues.length - Math.PI / 2;
    const labelR = radarRadius + 18;
    return {
      label: s.label,
      value: Math.round(s.value),
      x: radarCenter + labelR * Math.cos(angle),
      y: radarCenter + labelR * Math.sin(angle),
    };
  });

  return (
    <div className="space-y-4">
      <div className="grid lg:grid-cols-2 gap-4">
        {/* Radar Chart */}
        <Card>
          <CardHeader className="pb-2"><CardTitle className="text-sm flex items-center gap-2"><Icon name="Radar" className="w-4 h-4 text-brand" /> Performance Radar</CardTitle></CardHeader>
          <CardContent className="flex justify-center pt-2">
            <svg width={radarSize} height={radarSize} className="max-w-full">
              {/* Grid circles */}
              {[0.25, 0.5, 0.75, 1].map((f) => (
                <circle key={f} cx={radarCenter} cy={radarCenter} r={radarRadius * f} fill="none" stroke="currentColor" strokeWidth="0.5" className="text-muted-foreground/30" />
              ))}
              {/* Grid lines */}
              {radarValues.map((_, i) => {
                const angle = (Math.PI * 2 * i) / radarValues.length - Math.PI / 2;
                return <line key={i} x1={radarCenter} y1={radarCenter} x2={radarCenter + radarRadius * Math.cos(angle)} y2={radarCenter + radarRadius * Math.sin(angle)} stroke="currentColor" strokeWidth="0.5" className="text-muted-foreground/30" />;
              })}
              {/* Score polygon */}
              <polygon points={radarPath} fill="rgba(17, 84, 163, 0.25)" stroke="#1154A3" strokeWidth="2" />
              {/* Score points */}
              {radarPoints.map((p, i) => <circle key={i} cx={p[0]} cy={p[1]} r="3" fill="#1154A3" />)}
              {/* Labels */}
              {radarLabels.map((l, i) => (
                <g key={i}>
                  <text x={l.x} y={l.y} textAnchor="middle" dominantBaseline="middle" className="text-[9px] fill-muted-foreground font-medium">{l.label}</text>
                  <text x={l.x} y={l.y + 10} textAnchor="middle" dominantBaseline="middle" className="text-[10px] font-bold" fill={scoreColor(l.value)}>{l.value}</text>
                </g>
              ))}
            </svg>
          </CardContent>
        </Card>

        {/* Progress bars */}
        <Card>
          <CardHeader className="pb-2"><CardTitle className="text-sm flex items-center gap-2"><Icon name="BarChart3" className="w-4 h-4 text-brand" /> Score Breakdown</CardTitle></CardHeader>
          <CardContent className="space-y-3 pt-2">
            {scores.map((s) => (
              <div key={s.label}>
                <div className="flex justify-between text-xs mb-1">
                  <span className="font-medium">{s.label}</span>
                  <span className="font-bold" style={{ color: s.color }}>{Math.round(s.value)}<span className="text-muted-foreground text-[10px]">/{s.max}</span></span>
                </div>
                <div className="h-2 bg-secondary rounded-full overflow-hidden">
                  <motion.div
                    initial={{ width: 0 }}
                    animate={{ width: `${(s.value / s.max) * 100}%` }}
                    transition={{ duration: 0.6, ease: "easeOut" }}
                    className="h-full rounded-full"
                    style={{ background: s.color }}
                  />
                </div>
              </div>
            ))}
            <div className="pt-2 border-t border-border flex items-center justify-between text-xs">
              <span className="text-muted-foreground">Overall verdict</span>
              <Badge variant={report.dashboard.atsScore >= 70 ? "success" : report.dashboard.atsScore >= 50 ? "warning" : "danger"}>
                {scoreLabel(report.dashboard.atsScore)}
              </Badge>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Heat-map style section scores */}
      <Card>
        <CardHeader className="pb-2"><CardTitle className="text-sm flex items-center gap-2"><Icon name="Grid3x3" className="w-4 h-4 text-brand" /> Section Heat Map</CardTitle></CardHeader>
        <CardContent className="pt-2">
          <div className="grid grid-cols-3 sm:grid-cols-5 lg:grid-cols-9 gap-2">
            {report.recruiter.sections.map((s) => {
              const pct = (s.score / 10) * 100;
              const color = pct >= 80 ? "#10B981" : pct >= 60 ? "#1154A3" : pct >= 40 ? "#F59E0B" : "#DC2626";
              return (
                <div key={s.section} className="rounded-lg p-2 text-center border" style={{ borderColor: color + "40", background: color + "10" }}>
                  <div className="text-[9px] uppercase text-muted-foreground truncate">{s.section}</div>
                  <div className="text-lg font-bold" style={{ color }}>{s.score}<span className="text-[10px] text-muted-foreground">/10</span></div>
                </div>
              );
            })}
          </div>
        </CardContent>
      </Card>

      {/* Top critical fixes preview */}
      {report.actionPlan.criticalFixes.length > 0 && (
        <Card>
          <CardHeader className="pb-2"><CardTitle className="text-sm flex items-center gap-2 text-red-600"><Icon name="AlertTriangle" className="w-4 h-4" /> Critical Fixes Preview</CardTitle></CardHeader>
          <CardContent className="pt-2 space-y-2">
            {report.actionPlan.criticalFixes.slice(0, 3).map((f, i) => (
              <div key={i} className="flex items-start gap-2 text-xs">
                <span className="text-red-500 font-bold mt-0.5">{i + 1}.</span>
                <div><span className="font-medium">{f.fix}</span> <span className="text-muted-foreground">— {f.impact}</span></div>
              </div>
            ))}
            <div className="pt-2 border-t border-border flex items-center justify-between text-xs">
              <span className="text-muted-foreground">Expected ATS increase after all fixes</span>
              <Badge variant="success" className="gap-1"><Icon name="TrendingUp" className="w-3 h-3" /> +{report.actionPlan.expectedAtsIncrease} pts</Badge>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

// ============================================================================
// MODULE 1 — ATS REVIEW
// ============================================================================

function ATSModule({ report }: { report: ResumeReviewReport }) {
  const a = report.ats;
  return (
    <div className="space-y-4">
      <div className="grid sm:grid-cols-3 gap-4">
        <Card><CardContent className="p-4 text-center">
          <div className="text-3xl font-bold font-display" style={{ color: scoreColor(a.atsScore) }}>{a.atsScore}</div>
          <div className="text-[10px] text-muted-foreground uppercase mt-1">ATS Score / 100</div>
        </CardContent></Card>
        <Card><CardContent className="p-4 text-center">
          <div className="text-3xl font-bold font-display" style={{ color: scoreColor(a.keywordMatch) }}>{a.keywordMatch}%</div>
          <div className="text-[10px] text-muted-foreground uppercase mt-1">Keyword Match</div>
        </CardContent></Card>
        <Card><CardContent className="p-4 text-center">
          <div className="text-3xl font-bold font-display" style={{ color: scoreColor(a.passProbability) }}>{a.passProbability}%</div>
          <div className="text-[10px] text-muted-foreground uppercase mt-1">Pass Probability</div>
        </CardContent></Card>
      </div>

      <div className="grid md:grid-cols-2 gap-4">
        <Card><CardHeader className="pb-2"><CardTitle className="text-sm text-red-600 flex items-center gap-2"><Icon name="KeyRound" className="w-4 h-4" /> Missing Keywords ({a.missingKeywords.length})</CardTitle></CardHeader>
          <CardContent className="pt-0">
            {a.missingKeywords.length > 0 ? (
              <div className="flex flex-wrap gap-1">{a.missingKeywords.map((k, i) => <Badge key={i} variant="danger" className="text-[10px]">{k}</Badge>)}</div>
            ) : <p className="text-xs text-muted-foreground">None — all keywords matched ✓</p>}
          </CardContent>
        </Card>
        <Card><CardHeader className="pb-2"><CardTitle className="text-sm text-amber-600 flex items-center gap-2"><Icon name="AlertCircle" className="w-4 h-4" /> Formatting Issues ({a.formattingIssues.length})</CardTitle></CardHeader>
          <CardContent className="pt-0">
            {a.formattingIssues.length > 0 ? (
              <ul className="space-y-1 text-xs">{a.formattingIssues.map((f, i) => <li key={i} className="flex gap-1.5"><span className="text-amber-500">!</span> {f}</li>)}</ul>
            ) : <p className="text-xs text-muted-foreground">No formatting issues ✓</p>}
          </CardContent>
        </Card>
      </div>

      <div className="grid md:grid-cols-3 gap-4">
        <Card><CardHeader className="pb-2"><CardTitle className="text-xs">Section Detection</CardTitle></CardHeader>
          <CardContent className="pt-0 space-y-1">
            {a.sectionDetection.map((s, i) => (
              <div key={i} className="flex items-center justify-between text-xs">
                <span>{s.section}</span>
                <span className={s.detected ? "text-emerald-600" : "text-red-500"}>{s.detected ? `✓ ${s.confidence}%` : "✗ missing"}</span>
              </div>
            ))}
          </CardContent>
        </Card>
        <Card><CardHeader className="pb-2"><CardTitle className="text-xs">Parsing Risks</CardTitle></CardHeader>
          <CardContent className="pt-0">
            {a.parsingRisks.length > 0 ? <ul className="space-y-1 text-xs">{a.parsingRisks.map((r, i) => <li key={i} className="flex gap-1.5"><span className="text-amber-500">!</span> {r}</li>)}</ul> : <p className="text-xs text-emerald-600">No parsing risks ✓</p>}
          </CardContent>
        </Card>
        <Card><CardHeader className="pb-2"><CardTitle className="text-xs">File Compatibility</CardTitle></CardHeader>
          <CardContent className="pt-0 space-y-1">
            {a.fileCompatibility.map((f, i) => <div key={i} className="text-xs">{f}</div>)}
            {a.graphicsRisks.length > 0 && <div className="mt-2 pt-2 border-t border-border"><div className="text-[10px] uppercase text-muted-foreground mb-1">Graphics Risks</div>{a.graphicsRisks.map((r, i) => <div key={i} className="text-xs text-amber-600">⚠ {r}</div>)}</div>}
            {a.tablesRisks.length > 0 && <div className="mt-2 pt-2 border-t border-border"><div className="text-[10px] uppercase text-muted-foreground mb-1">Tables Risks</div>{a.tablesRisks.map((r, i) => <div key={i} className="text-xs text-amber-600">⚠ {r}</div>)}</div>}
          </CardContent>
        </Card>
      </div>

      <Card><CardHeader className="pb-2"><CardTitle className="text-sm flex items-center gap-2"><Icon name="Lightbulb" className="w-4 h-4 text-brand" /> ATS Recommendations</CardTitle></CardHeader>
        <CardContent className="pt-0"><ul className="space-y-1.5 text-xs">{a.recommendations.map((r, i) => <li key={i} className="flex gap-1.5"><span className="text-brand">→</span> {r}</li>)}</ul></CardContent>
      </Card>
    </div>
  );
}

// ============================================================================
// MODULE 2 — RECRUITER REVIEW
// ============================================================================

function RecruiterModule({ report }: { report: ResumeReviewReport }) {
  return (
    <div className="space-y-4">
      <Card><CardContent className="p-4 flex items-center gap-4">
        <div className="text-center">
          <div className="text-4xl font-bold font-display" style={{ color: scoreColor(report.recruiter.overallScore * 10) }}>{report.recruiter.overallScore}</div>
          <div className="text-[10px] text-muted-foreground uppercase">Overall / 10</div>
        </div>
        <div className="flex-1 text-sm text-muted-foreground">
          A senior recruiter's honest assessment of each resume section. Scores reflect real content quality — empty or weak sections get low scores, not generic 7/10s.
        </div>
      </CardContent></Card>

      <div className="grid md:grid-cols-2 gap-4">
        {report.recruiter.sections.map((s, i) => {
          const pct = (s.score / 10) * 100;
          const color = pct >= 80 ? "#10B981" : pct >= 60 ? "#1154A3" : pct >= 40 ? "#F59E0B" : "#DC2626";
          return (
            <Card key={i}>
              <CardHeader className="pb-2">
                <div className="flex items-center justify-between">
                  <CardTitle className="text-sm">{s.section}</CardTitle>
                  <span className="inline-flex items-center rounded-full px-2 py-0.5 text-[10px] font-bold" style={{ background: color + "20", color }}>{s.score}/10</span>
                </div>
              </CardHeader>
              <CardContent className="pt-0 space-y-2 text-xs">
                {s.strengths.length > 0 && <div><div className="font-semibold text-emerald-600 mb-0.5">✓ Strengths</div><ul className="space-y-0.5">{s.strengths.map((x, j) => <li key={j} className="flex gap-1"><span className="text-emerald-500">+</span> {x}</li>)}</ul></div>}
                {s.weaknesses.length > 0 && <div><div className="font-semibold text-red-600 mb-0.5 mt-2">✗ Weaknesses</div><ul className="space-y-0.5">{s.weaknesses.map((x, j) => <li key={j} className="flex gap-1"><span className="text-red-500">−</span> {x}</li>)}</ul></div>}
                {s.recommendations.length > 0 && <div><div className="font-semibold text-brand mb-0.5 mt-2">→ Recommendations</div><ul className="space-y-0.5">{s.recommendations.map((x, j) => <li key={j} className="flex gap-1"><span className="text-brand">›</span> {x}</li>)}</ul></div>}
              </CardContent>
            </Card>
          );
        })}
      </div>
    </div>
  );
}

// ============================================================================
// MODULE 3 — JOB MATCH REVIEW
// ============================================================================

function JobMatchModule({ report }: { report: ResumeReviewReport }) {
  if (!report.jobMatch) return null;
  const jm = report.jobMatch;
  const axes = [
    { label: "Overall Match", val: jm.overallMatch },
    { label: "ATS Match", val: jm.atsMatch },
    { label: "Experience Match", val: jm.experienceMatch },
    { label: "Skill Match", val: jm.skillMatch },
    { label: "Education Match", val: jm.educationMatch },
    { label: "Industry Match", val: jm.industryMatch },
  ];
  return (
    <div className="space-y-4">
      <Card><CardContent className="p-4 flex items-center gap-4">
        <div className="text-center">
          <div className="text-4xl font-bold font-display" style={{ color: scoreColor(jm.overallMatch) }}>{jm.overallMatch}%</div>
          <div className="text-[10px] text-muted-foreground uppercase">Overall Match</div>
        </div>
        <div className="flex-1 grid grid-cols-2 sm:grid-cols-3 gap-2">
          {axes.slice(1).map((a) => (
            <div key={a.label}>
              <div className="text-[10px] uppercase text-muted-foreground">{a.label}</div>
              <div className="h-1.5 bg-secondary rounded-full overflow-hidden mt-0.5"><div className="h-full rounded-full" style={{ width: `${a.val}%`, background: scoreColor(a.val) }} /></div>
              <div className="text-[10px] font-bold mt-0.5" style={{ color: scoreColor(a.val) }}>{a.val}%</div>
            </div>
          ))}
        </div>
      </CardContent></Card>

      <div className="grid md:grid-cols-3 gap-4">
        <Card><CardHeader className="pb-2"><CardTitle className="text-sm text-red-600">Missing Skills</CardTitle></CardHeader>
          <CardContent className="pt-0">{jm.missingSkills.length > 0 ? <div className="flex flex-wrap gap-1">{jm.missingSkills.map((s, i) => <Badge key={i} variant="danger" className="text-[10px]">{s}</Badge>)}</div> : <p className="text-xs text-emerald-600">All skills matched ✓</p>}</CardContent>
        </Card>
        <Card><CardHeader className="pb-2"><CardTitle className="text-sm text-amber-600">Missing Keywords</CardTitle></CardHeader>
          <CardContent className="pt-0">{jm.missingKeywords.length > 0 ? <div className="flex flex-wrap gap-1">{jm.missingKeywords.map((s, i) => <Badge key={i} variant="warning" className="text-[10px]">{s}</Badge>)}</div> : <p className="text-xs text-emerald-600">All keywords matched ✓</p>}</CardContent>
        </Card>
        <Card><CardHeader className="pb-2"><CardTitle className="text-sm text-blue-600">Missing Certifications</CardTitle></CardHeader>
          <CardContent className="pt-0">{jm.missingCertifications.length > 0 ? <ul className="space-y-0.5 text-xs">{jm.missingCertifications.map((s, i) => <li key={i} className="flex gap-1"><span className="text-blue-500">+</span> {s}</li>)}</ul> : <p className="text-xs text-emerald-600">No required certs missing ✓</p>}</CardContent>
        </Card>
      </div>
    </div>
  );
}

// ============================================================================
// MODULE 4 — INDUSTRY BENCHMARK
// ============================================================================

function BenchmarkModule({ report }: { report: ResumeReviewReport }) {
  const b = report.benchmark;
  return (
    <div className="space-y-4">
      <Card><CardContent className="p-4 flex items-center gap-4 flex-wrap">
        <div className="text-center">
          <div className="text-4xl font-bold font-display" style={{ color: scoreColor(b.industryReadinessScore) }}>{b.industryReadinessScore}</div>
          <div className="text-[10px] text-muted-foreground uppercase">Industry Readiness / 100</div>
        </div>
        <div className="flex-1 grid grid-cols-2 sm:grid-cols-4 gap-2 text-xs">
          <div><div className="text-[10px] uppercase text-muted-foreground">Industry</div><div className="font-semibold">{b.industry}</div></div>
          <div><div className="text-[10px] uppercase text-muted-foreground">Role</div><div className="font-semibold">{b.role}</div></div>
          <div><div className="text-[10px] uppercase text-muted-foreground">Seniority</div><div className="font-semibold">{b.seniority}</div></div>
          <div><div className="text-[10px] uppercase text-muted-foreground">Country</div><div className="font-semibold">{b.country}</div></div>
        </div>
      </CardContent></Card>

      <Card>
        <CardHeader className="pb-2"><CardTitle className="text-sm flex items-center gap-2"><Icon name="BarChart3" className="w-4 h-4 text-brand" /> Benchmark vs. Industry</CardTitle></CardHeader>
        <CardContent className="pt-0 space-y-3">
          {b.benchmarkComparisons.map((c, i) => {
            const maxVal = Math.max(c.candidate, c.industryAverage, c.topPercentile, 1);
            return (
              <div key={i}>
                <div className="flex justify-between text-xs mb-1">
                  <span className="font-medium">{c.metric}</span>
                  <span className="text-muted-foreground">You: <span className="font-bold" style={{ color: scoreColor((c.candidate / maxVal) * 100) }}>{c.candidate}</span> · Avg: {c.industryAverage} · Top: {c.topPercentile}</span>
                </div>
                <div className="space-y-0.5">
                  <div className="h-2 bg-secondary rounded-full overflow-hidden"><div className="h-full rounded-full bg-brand" style={{ width: `${(c.candidate / maxVal) * 100}%` }} /></div>
