"use client";

import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge, Icon, ScoreRing } from "@/components/shared";
import { useApp } from "@/lib/store";

export function SuperAdmin() {
  const setView = useApp((s) => s.setView);
  const providers = useApp((s) => s.providers);
  const prompts = useApp((s) => s.prompts);
  const logs = useApp((s) => s.logs);
  const flags = useApp((s) => s.flags);

  const activeProviders = providers.filter((p) => p.isActive).length;
  const activePrompts = prompts.filter((p) => p.isActive).length;
  // Real health: count providers whose runtime status proves they work
  // ("healthy") or hasn't failed yet ("untested"). This reflects actual
  // serviceability rather than just the toggle count. A provider marked
  // "down"/"degraded" after a live connection test is excluded.
  const healthyProviders = providers.filter(
    (p) => p.status === "healthy" || p.status === "untested"
  ).length;
  const systemHealth = Math.round(
    ((healthyProviders / Math.max(1, providers.length)) * 0.5 +
    (activePrompts / Math.max(1, prompts.length)) * 0.2 +
    (flags.maintenanceMode ? 0 : 0.3)) * 100
  );

  const quickLinks = [
    { label: "AI Providers", desc: `${activeProviders} active of ${providers.length}`, icon: "Cpu", view: "ai-providers", color: "#1154A3" },
    { label: "Pipeline Profiles", desc: "Orchestration strategy selector", icon: "Workflow", view: "pipeline-profiles", color: "#6366F1" },
    { label: "Agent Config Center", desc: "Per-agent provider, model, prompt", icon: "Bot", view: "agent-config", color: "#0EA5E9" },
    { label: "Fallback Chain", desc: "Configure ordered provider fallback", icon: "Shuffle", view: "fallback-chain", color: "#10B981" },
    { label: "Optimizer Directive", desc: "Per-agent behavior & layout", icon: "SlidersHorizontal", view: "optimizer-directive", color: "#F59E0B" },
    { label: "Prompt Library", desc: `${prompts.length} templates · ${activePrompts} active`, icon: "Brain", view: "prompts", color: "#8B5CF6" },
    { label: "Orchestration & Workers", desc: "Monitor queues & background jobs", icon: "Activity", view: "workers", color: "#EC4899" },
    { label: "Branding", desc: "Customize logo, colors, email", icon: "Palette", view: "branding", color: "#EC4899" },
    { label: "Feature Flags", desc: `${Object.values(flags).filter(Boolean).length}/${Object.keys(flags).length} enabled`, icon: "Flag", view: "feature-flags", color: "#F59E0B" },
    { label: "Audit Logs", desc: `${logs.length} recent events`, icon: "ScrollText", view: "logs", color: "#10B981" },
    { label: "Users", desc: "Manage accounts & roles", icon: "Users", view: "users", color: "#0EA5E9" },
    { label: "Analytics", desc: "Platform metrics & funnel", icon: "BarChart3", view: "analytics", color: "#1154A3" },
    { label: "Admin Overview", desc: "KPIs & usage", icon: "ShieldCheck", view: "admin", color: "#10B981" },
  ];

  return (
    <div className="space-y-6">
      <div>
        <h1 className="font-display text-2xl font-bold flex items-center gap-2"><Icon name="Crown" className="w-6 h-6 text-gold" /> Super Admin Overview</h1>
        <p className="text-sm text-muted-foreground mt-1">Full system control. Configure AI providers, branding, prompts, flags, and audit logs.</p>
      </div>

      <div className="grid lg:grid-cols-3 gap-6">
        {/* System health */}
        <Card className="gradient-brand text-white">
          <CardContent className="p-6 flex flex-col items-center justify-center text-center">
            <div className="relative">
              <ScoreRing value={Math.min(100, systemHealth)} size={120} label="Health" />
            </div>
            <div className="mt-3 font-semibold">System health</div>
            <div className="text-xs text-white/70 mt-1">
              {flags.maintenanceMode ? "Maintenance mode ON" : "All systems operational"}
            </div>
          </CardContent>
        </Card>

        {/* Stats */}
        <div className="lg:col-span-2 grid sm:grid-cols-2 gap-4">
          {[
            { label: "AI providers", value: `${activeProviders}/${providers.length}`, icon: "Cpu", color: "#1154A3" },
            { label: "Active prompts", value: `${activePrompts}/${prompts.length}`, icon: "Brain", color: "#8B5CF6" },
            { label: "Audit logs (24h)", value: logs.length, icon: "ScrollText", color: "#10B981" },
            { label: "Flags enabled", value: `${Object.values(flags).filter(Boolean).length}/${Object.keys(flags).length}`, icon: "Flag", color: "#F59E0B" },
          ].map((s) => (
            <Card key={s.label}>
              <CardContent className="p-5 flex items-center gap-3">
                <div className="w-10 h-10 rounded-lg flex items-center justify-center" style={{ background: `${s.color}15`, color: s.color }}>
                  <Icon name={s.icon} className="w-5 h-5" />
                </div>
                <div>
                  <div className="text-xl font-bold font-display">{s.value}</div>
                  <div className="text-xs text-muted-foreground">{s.label}</div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      </div>

      {/* Quick links */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Super admin tools</CardTitle>
          <CardDescription>Jump directly to any control panel.</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-3">
            {quickLinks.map((q) => (
              <button key={q.label} onClick={() => setView(q.view as any)} className="group text-left rounded-xl border border-border p-4 hover:shadow-premium hover:-translate-y-0.5 transition-all">
                <div className="w-10 h-10 rounded-lg flex items-center justify-center mb-3" style={{ background: `${q.color}15`, color: q.color }}>
                  <Icon name={q.icon} className="w-5 h-5" />
                </div>
                <div className="font-semibold text-sm flex items-center gap-1">
                  {q.label}
                  <Icon name="ArrowRight" className="w-3 h-3 text-muted-foreground opacity-0 group-hover:opacity-100 group-hover:translate-x-0.5 transition" />
                </div>
                <div className="text-xs text-muted-foreground mt-0.5">{q.desc}</div>
              </button>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Recent logs */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle className="text-lg">Recent audit events</CardTitle>
            <Button size="sm" variant="outline" onClick={() => setView("logs")}>View all</Button>
          </div>
        </CardHeader>
        <CardContent>
          <div className="space-y-2 max-h-80 overflow-y-auto">
            {logs.slice(0, 10).map((l) => {
              const sevColor = l.severity === "info" ? "brand" : l.severity === "warning" ? "warning" : "danger";
              return (
                <div key={l.id} className="flex items-start gap-3 p-2 rounded-lg hover:bg-secondary/40">
                  <Badge variant={sevColor as any} className="text-[10px] capitalize shrink-0">{l.severity}</Badge>
                  <div className="flex-1 min-w-0">
                    <div className="text-sm font-medium truncate">{l.action}</div>
                    <div className="text-xs text-muted-foreground truncate">{l.details}</div>
                  </div>
                  <div className="text-xs text-muted-foreground shrink-0 whitespace-nowrap">{new Date(l.timestamp).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}</div>
                </div>
              );
            })}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

src/components/app/modules/TestConnectio:
"use client";

import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { Button } from "@/components/ui/button";
import { Badge, Icon } from "@/components/shared";
import { ProviderManager } from "@/lib/ai/services";
import type { AIProvider } from "@/lib/types";

interface TestResult {
  ok: boolean;
  latencyMs: number;
  message: string;
  response?: string;
  inputTokens?: number;
  outputTokens?: number;
  /** HTTP 429 — provider reachable + key accepted, but rate/quota limited */
  rateLimited?: boolean;
}

export function TestConnectionModal({ provider, onClose }: { provider: AIProvider; onClose: () => void }) {
  const [status, setStatus] = useState<"idle" | "running" | "done">("idle");
  const [result, setResult] = useState<TestResult | null>(null);
  const [testPrompt, setTestPrompt] = useState("Reply with exactly: OK");
  const [steps, setSteps] = useState<string[]>([]);

  const runTest = async () => {
    setStatus("running");
    setSteps([]);
    setResult(null);

    setSteps((s) => [...s, `Resolving adapter for type "${provider.type}"…`]);
    await new Promise((r) => setTimeout(r, 200));
    setSteps((s) => [...s, `Building config (baseUrl=${provider.baseUrl || provider.apiUrl || "—"}, model=${provider.modelName || "—"})…`]);
    await new Promise((r) => setTimeout(r, 200));
    setSteps((s) => [...s, `Sending test prompt: "${testPrompt.slice(0, 60)}${testPrompt.length > 60 ? "…" : ""}"`]);

    const t0 = performance.now();
    const res = await ProviderManager.testConnection(provider);
    const totalMs = Math.round(performance.now() - t0);

    setSteps((s) => [...s, `Received response in ${res.latencyMs}ms (total ${totalMs}ms including overhead).`]);
    setResult(res);
    setStatus("done");
  };

  const hasAlternateKeys = (provider.alternateApiKeys || []).length > 0;

  const runTestWithRotation = async () => {
    setStatus("running");
    setSteps([]);
    setResult(null);

    setSteps((s) => [...s, `Testing primary key: ${provider.apiKey ? `${provider.apiKey.slice(0, 8)}…` : "(empty)"}`]);
    const res = await ProviderManager.testConnection(provider);
    if (res.ok) {
      setSteps((s) => [...s, `Primary key succeeded in ${res.latencyMs}ms.`]);
      setResult(res);
      setStatus("done");
      return;
    }

    setSteps((s) => [...s, `Primary key returned: ${res.message}`]);
    const altKeys = provider.alternateApiKeys || [];
    if (altKeys.length === 0) {
      setSteps((s) => [...s, "No alternate keys configured to rotate to."]);
      setResult(res);
      setStatus("done");
      return;
    }

    setSteps((s) => [...s, `Triggering rotation simulation: trying ${altKeys.length} alternate key(s)...`]);
    let rotatedSuccess = false;
    for (let i = 0; i < altKeys.length; i++) {
      const altKey = altKeys[i];
      setSteps((s) => [...s, `Testing Alternate Key #${i + 1}: ${altKey.slice(0, 8)}…`]);
      const altRes = await ProviderManager.testConnection({ ...provider, apiKey: altKey });
      if (altRes.ok) {
        setSteps((s) => [...s, `✓ Alternate Key #${i + 1} succeeded in ${altRes.latencyMs}ms! Rotation is operational.`]);
        setResult({
          ok: true,
          latencyMs: altRes.latencyMs,
          message: `Rotation verified: Primary key failed (${res.message}), but Alternate Key #${i + 1} succeeded!`,
          response: altRes.response,
        });
        rotatedSuccess = true;
        break;
      } else {
        setSteps((s) => [...s, `✗ Alternate Key #${i + 1} failed: ${altRes.message}`]);
      }
    }
    if (!rotatedSuccess) {
      setResult(res);
    }
    setStatus("done");
  };

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="fixed inset-0 z-50 bg-background/80 backdrop-blur-sm flex items-center justify-center p-4"
      onClick={onClose}
    >
      <motion.div
        initial={{ y: 20, opacity: 0, scale: 0.97 }}
        animate={{ y: 0, opacity: 1, scale: 1 }}
        exit={{ y: 20, opacity: 0, scale: 0.97 }}
        transition={{ type: "spring", damping: 26, stiffness: 280 }}
        className="bg-card rounded-2xl border border-border shadow-premium w-full max-w-2xl max-h-[90vh] overflow-y-auto"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="sticky top-0 bg-card border-b border-border p-4 flex items-center justify-between">
          <h3 className="font-display font-bold text-lg flex items-center gap-2">
            <Icon name="Zap" className="w-5 h-5 text-gold" />
            Test Connection — {provider.name}
          </h3>
          <Button variant="ghost" size="icon" onClick={onClose}><Icon name="X" className="w-4 h-4" /></Button>
        </div>

        <div className="p-5 space-y-4">
          {/* Demoted provider banner (Task 17) — set expectations before the user reads a 429 verdict */}
          {provider.isActive === false && (
            <div className="rounded-lg bg-amber-100 dark:bg-amber-400/10 border border-amber-300 p-3 text-xs text-amber-800 dark:text-amber-300 flex gap-2">
              <Icon name="PauseCircle" className="w-4 h-4 mt-0.5 shrink-0" />
              <span>
                This provider is <strong>demoted</strong> (isActive = 0) — it is excluded from the live routing chain, so normal chats never send it traffic. Diagnostics still run so you can inspect its raw upstream response. Note: its free-tier quota is per-IP on shared egress infrastructure, so a &quot;Rate-limited&quot; verdict here does not mean you exhausted it yourself.
              </span>
            </div>
          )}

          {/* Provider summary */}
          <div className="rounded-lg bg-secondary/50 p-3 grid grid-cols-2 sm:grid-cols-4 gap-2 text-xs">
            <div><div className="text-muted-foreground">Type</div><div className="font-medium capitalize">{provider.type.replace("-", " ")}</div></div>
            <div><div className="text-muted-foreground">Model</div><div className="font-medium font-mono truncate">{provider.modelName || "—"}</div></div>
            <div><div className="text-muted-foreground">Base URL</div><div className="font-mono truncate">{provider.baseUrl || provider.apiUrl || "—"}</div></div>
            <div><div className="text-muted-foreground">Timeout</div><div className="font-medium">{provider.timeout}ms</div></div>
          </div>

          {/* Test prompt editor */}
          <div className="space-y-1.5">
            <label className="text-xs uppercase tracking-wide text-muted-foreground">Test prompt</label>
            <input
              value={testPrompt}
              onChange={(e) => setTestPrompt(e.target.value)}
              disabled={status === "running"}
              className="w-full h-9 px-3 rounded-md border border-input bg-background text-sm disabled:opacity-50"
            />
          </div>

          {/* Run button */}
          <div className="flex flex-col sm:flex-row gap-2">
            <Button
              onClick={runTest}
              disabled={status === "running"}
              className="flex-1 bg-brand hover:bg-brand-dark text-white gap-2"
            >
              {status === "running" ? (
                <><Icon name="Loader2" className="w-4 h-4 animate-spin" /> Running test…</>
              ) : (
                <><Icon name="Play" className="w-4 h-4" /> Run test connection</>
              )}
            </Button>
            {hasAlternateKeys && (
              <Button
                onClick={runTestWithRotation}
                disabled={status === "running"}
                variant="outline"
                className="gap-2 border-brand/40 hover:bg-brand/10 text-brand dark:text-brand-light"
              >
                <Icon name="RotateCw" className="w-4 h-4" />
                Test With Key Rotation ({(provider.alternateApiKeys || []).length} alts)
              </Button>
            )}
          </div>
          <p className="text-[11px] text-muted-foreground leading-relaxed">
            {hasAlternateKeys ? (
              <span>
                <strong>{(provider.alternateApiKeys || []).length} alternate API key(s) configured.</strong> During live chat or resume generation, if the primary key hits HTTP 429 or quota limits, the router automatically fails over to the alternate keys in sequence and swaps the winning key into the primary slot. Use &quot;Test With Key Rotation&quot; above to simulate and verify this failover.
              </span>
            ) : (
              <span>
                This test sends a single raw request with exactly this provider&apos;s key, model and base URL — no retries or rotation — so you see the provider&apos;s true response. Regular chats go through the rotator: on 429 they retry, rotate alternate keys/models, and fail over to your fallback providers.
              </span>
            )}
          </p>

          {/* Steps log */}
          {steps.length > 0 && (
            <div className="rounded-lg bg-slate-900 text-slate-100 p-3 font-mono text-xs space-y-1 max-h-40 overflow-y-auto">
              {steps.map((s, i) => (
                <div key={i} className="flex items-start gap-2">
                  <span className="text-emerald-400">›</span>
                  <span>{s}</span>
                </div>
              ))}
              {status === "running" && <div className="flex items-center gap-2 text-amber-300"><span className="animate-pulse">●</span> Awaiting response…</div>}
            </div>
          )}

          {/* Result — ok = green, rateLimited = amber (reachable but quota/rate limited), else red */}
          {status === "done" && result && (
            <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} className="space-y-3">
              <div className={`rounded-lg p-4 ${result.ok ? "bg-emerald-100 dark:bg-emerald-400/10 border border-emerald-300" : result.rateLimited ? "bg-amber-100 dark:bg-amber-400/10 border border-amber-300" : "bg-red-100 dark:bg-red-400/10 border border-red-300"}`}>
                <div className="flex items-center gap-2">
                  <Icon name={result.ok ? "CheckCircle2" : result.rateLimited ? "AlertTriangle" : "XCircle"} className={`w-5 h-5 ${result.ok ? "text-emerald-600" : result.rateLimited ? "text-amber-600" : "text-red-600"}`} />
                  <span className={`font-semibold ${result.ok ? "text-emerald-800 dark:text-emerald-300" : result.rateLimited ? "text-amber-800 dark:text-amber-300" : "text-red-800 dark:text-red-300"}`}>
                    {result.ok ? "Connection successful" : result.rateLimited ? "Rate-limited — provider reachable" : "Connection failed"}
                  </span>
                  <Badge variant={result.ok ? "success" : result.rateLimited ? "warning" : "danger"} className="ml-auto">{result.latencyMs}ms</Badge>
                </div>
                <div className={`mt-2 text-sm ${result.ok ? "text-emerald-700 dark:text-emerald-400" : result.rateLimited ? "text-amber-700 dark:text-amber-400" : "text-red-700 dark:text-red-400"}`}>{result.message}</div>
              </div>

              {result.response && (
                <div>
                  <div className="text-xs font-semibold uppercase text-muted-foreground mb-1">Response</div>
                  <pre className="rounded-lg border border-border bg-secondary/50 p-3 text-xs font-mono whitespace-pre-wrap max-h-40 overflow-y-auto">{result.response}</pre>
                </div>
              )}

              <div className="grid grid-cols-3 gap-2 text-xs">
                <div className="rounded-md bg-secondary p-2"><div className="text-muted-foreground">Latency</div><div className="font-mono font-semibold">{result.latencyMs}ms</div></div>
                <div className="rounded-md bg-secondary p-2"><div className="text-muted-foreground">Input tokens</div><div className="font-mono font-semibold">{result.inputTokens ?? "—"}</div></div>
                <div className="rounded-md bg-secondary p-2"><div className="text-muted-foreground">Output tokens</div><div className="font-mono font-semibold">{result.outputTokens ?? "—"}</div></div>
              </div>
            </motion.div>
          )}
        </div>

        <div className="sticky bottom-0 bg-card border-t border-border p-4 flex justify-end gap-2">
          <Button variant="outline" onClick={onClose}>Close</Button>
          {status === "done" && <Button onClick={runTest} className="bg-brand hover:bg-brand-dark text-white gap-2"><Icon name="RotateCcw" className="w-4 h-4" /> Run again</Button>}
        </div>
      </motion.div>
    </motion.div>
  );
}

src/components/app/modules/unsaved-chang:
"use client";

// ============================================================================
// Shared unsaved-changes affordances for Super Admin panels.
//
// Every editable admin surface must tell the admin when the in-memory state
// differs from the last CONFIRMED save (the explicit Save button). This uses
// the same amber treatment as OptimizerDirective / FallbackChain /
// PersonaManagement / AgentConfigCenter so the behavior is identical
// everywhere: edit -> amber indicator appears -> Save -> indicator clears.
//
// The explicit Save buttons on the batch panels (Providers / Models / Prompts /
// Flags / Branding) intentionally stay enabled even when the indicator is
// hidden: they double as a repair/confirm path for the store's fire-and-forget
// per-edit sync, which can silently fail offline.
// ============================================================================

import { Icon } from "@/components/shared";

export function UnsavedBanner({
  saveLabel,
  children,
}: {
  /** Label of the button that commits the change, e.g. "Save branding". */
  saveLabel?: string;
  /** Custom message overrides the default "unsaved changes" wording. */
  children?: React.ReactNode;
}) {
  return (
    <div
      data-testid="unsaved-banner"
      className="rounded-lg bg-amber-50 dark:bg-amber-950/30 border border-amber-200 dark:border-amber-800 p-3 flex items-center gap-2"
      role="status"
    >
      <Icon name="AlertTriangle" className="w-4 h-4 text-amber-600 shrink-0" />
      <span className="text-sm text-amber-800 dark:text-amber-200">
        {children ?? (
          <>
            You have unsaved changes. Click &quot;{saveLabel}&quot; to apply them.
          </>
        )}
      </span>
    </div>
  );
}

src/components/app/modules/UserApprovals:
"use client";

import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge, Icon } from "@/components/shared";
import { useApp } from "@/lib/store";
import { refreshUsers } from "@/lib/cloud-api";
import { toast } from "sonner";
import { useState, useEffect } from "react";

export function UserApprovals() {
  const users = useApp((s) => s.users);
  const approveUser = useApp((s) => s.approveUser);
  const deleteUser = useApp((s) => s.deleteUser);
  const [q, setQ] = useState("");

  // === BUG FIX: Force-refresh users from D1 on mount ===
  useEffect(() => {
    refreshUsers(useApp);
  }, []);

  const pending = users.filter((u) => u.status === "pending");
  const filtered = pending.filter((u) => `${u.name} ${u.email} ${u.username ?? ""}`.toLowerCase().includes(q.toLowerCase()));

  const handleApprove = (id: string, name: string) => {
    approveUser(id);
    toast.success(`${name} has been approved. They can now access all features.`);
  };

  const handleReject = (id: string, name: string) => {
    if (confirm(`Reject and delete ${name}'s account?`)) {
      deleteUser(id);
      toast.success(`${name}'s account has been deleted.`);
    }
  };

  return (
    <div className="space-y-6">
      <div>
        <h1 className="font-display text-2xl font-bold flex items-center gap-2">
          <Icon name="UserCheck" className="w-6 h-6 text-brand" /> User Approvals
        </h1>
        <p className="text-sm text-muted-foreground mt-1">Review and approve new user registrations. Pending users cannot access any features until approved.</p>
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
        <Card><CardContent className="p-4"><div className="text-2xl font-bold font-display text-amber-600">{pending.length}</div><div className="text-xs text-muted-foreground">Pending</div></CardContent></Card>
        <Card><CardContent className="p-4"><div className="text-2xl font-bold font-display text-emerald-600">{users.filter((u) => u.status === "approved").length}</div><div className="text-xs text-muted-foreground">Approved</div></CardContent></Card>
        <Card><CardContent className="p-4"><div className="text-2xl font-bold font-display text-red-600">{users.filter((u) => u.status === "suspended").length}</div><div className="text-xs text-muted-foreground">Suspended</div></CardContent></Card>
      </div>

      <Card>
        <CardHeader>
          <div className="flex items-center justify-between gap-3 flex-wrap">
            <CardTitle className="text-lg">Pending Approvals ({filtered.length})</CardTitle>
            <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search…" className="h-9 px-3 rounded-md border border-input bg-background text-sm w-full sm:w-64" />
          </div>
        </CardHeader>
        <CardContent>
          {filtered.length === 0 ? (
            <div className="text-center py-12">
              <Icon name="CheckCircle2" className="w-10 h-10 text-emerald-500 mx-auto" />
              <p className="text-sm text-muted-foreground mt-2">No pending approvals. You're all caught up!</p>
            </div>
          ) : (
            <div className="space-y-3">
              {filtered.map((u) => (
                <div key={u.id} className="flex items-center justify-between gap-3 p-4 rounded-lg border border-border">
                  <div className="min-w-0">
                    <div className="font-semibold text-sm flex items-center gap-2">
                      {u.name}
                      <Badge variant="warning" className="text-[9px]">PENDING</Badge>
                    </div>
                    <div className="text-xs text-muted-foreground">{u.email}</div>
                    <div className="text-xs text-muted-foreground mt-0.5">
                      {u.provider} · registered {new Date(u.createdAt).toLocaleDateString()}
                    </div>
                  </div>
                  <div className="flex gap-1.5 shrink-0">
                    <Button size="sm" onClick={() => handleApprove(u.id, u.name)} className="bg-emerald-600 hover:bg-emerald-700 text-white gap-1.5">
                      <Icon name="Check" className="w-3.5 h-3.5" /> Approve
                    </Button>
                    <Button size="sm" variant="outline" onClick={() => handleReject(u.id, u.name)} className="text-destructive gap-1.5">
                      <Icon name="X" className="w-3.5 h-3.5" /> Reject
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

src/components/app/modules/UserDetailMod:
"use client";

import { useState } from "react";
import { motion } from "framer-motion";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Badge, Icon } from "@/components/shared";
import { useApp } from "@/lib/store";
import { toast } from "sonner";
import type { Role } from "@/lib/types";

export interface ManagedUser {
  id: string;
  name: string;
  email: string;
  role: Role;
  status: "active" | "suspended";
  resumes: number;
  lastActive: string;
  provider: string;
  createdAt: string;
  avatarColor: string;
}

export function UserDetailModal({ user, onClose }: { user: ManagedUser; onClose: () => void }) {
  const currentUser = useApp((s) => s.user);
  const log = useApp((s) => s.log);

  const [name, setName] = useState(user.name);
  const [email, setEmail] = useState(user.email);
  const [role, setRole] = useState<Role>(user.role);
  const [status, setStatus] = useState<"active" | "suspended">(user.status);
  const [saving, setSaving] = useState(false);

  const isSelf = currentUser?.email === user.email;
  const canEditRole = currentUser?.role === "super_admin" && !isSelf;
  const canSuspend = currentUser?.role === "super_admin" && !isSelf;

  const save = async () => {
    setSaving(true);
    await new Promise((r) => setTimeout(r, 400));
    setSaving(false);
    log({
      actor: currentUser?.email ?? "admin",
      action: "User updated",
      category: "admin",
      details: `${user.email}: name="${name}", role=${role}, status=${status}`,
      severity: "info",
    });
    toast.success(`Changes saved for ${user.name}.`);
    onClose();
  };

  const resetPassword = () => {
    if (!confirm(`Send a password-reset email to ${user.email}?`)) return;
    log({
      actor: currentUser?.email ?? "admin",
      action: "Password reset triggered",
      category: "auth",
      details: `Reset email sent to ${user.email}`,
      severity: "warning",
    });
    toast.success(`Password-reset email sent to ${user.email}.`);
  };

  const initials = user.name.split(/\s+/).slice(0, 2).map((s) => s[0]?.toUpperCase()).join("");

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="fixed inset-0 z-50 bg-background/80 backdrop-blur-sm flex items-center justify-center p-0 sm:p-4"
      onClick={onClose}
    >
      <motion.div
        initial={{ y: 20, opacity: 0, scale: 0.97 }}
        animate={{ y: 0, opacity: 1, scale: 1 }}
        exit={{ y: 20, opacity: 0, scale: 0.97 }}
        transition={{ type: "spring", damping: 26, stiffness: 280 }}
        className="bg-card rounded-t-2xl sm:rounded-2xl border border-border shadow-premium w-full sm:max-w-xl max-h-[95vh] overflow-y-auto"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="sticky top-0 bg-card border-b border-border p-4 flex items-center justify-between">
          <h3 className="font-display font-bold text-lg flex items-center gap-2">
            <Icon name="User" className="w-5 h-5 text-brand" /> User details
          </h3>
          <Button variant="ghost" size="icon" onClick={onClose}><Icon name="X" className="w-4 h-4" /></Button>
        </div>

        <div className="p-5 space-y-5">
          {/* Avatar + identity */}
          <div className="flex items-center gap-4">
            <div className="w-16 h-16 rounded-full flex items-center justify-center text-white font-bold text-xl shrink-0" style={{ background: user.avatarColor }}>
              {initials || "?"}
            </div>
            <div className="min-w-0">
              <div className="font-semibold text-lg flex items-center gap-2">
                {user.name}
                {isSelf && <Badge variant="brand" className="text-[10px]">YOU</Badge>}
              </div>
              <div className="text-sm text-muted-foreground truncate">{user.email}</div>
              <div className="flex flex-wrap gap-1.5 mt-1">
                <Badge variant={user.role === "super_admin" ? "gold" : user.role === "admin" ? "brand" : "outline"} className="capitalize text-[10px]">{user.role.replace("_", " ")}</Badge>
                <Badge variant={user.status === "active" ? "success" : "danger"} className="capitalize text-[10px]">{user.status}</Badge>
                <Badge variant="outline" className="capitalize text-[10px]">{user.provider}</Badge>
              </div>
            </div>
          </div>

          {/* Stats */}
          <div className="grid grid-cols-3 gap-2">
            <div className="rounded-lg bg-secondary p-3 text-center">
              <div className="text-xl font-bold font-display">{user.resumes}</div>
              <div className="text-xs text-muted-foreground">Resumes</div>
            </div>
            <div className="rounded-lg bg-secondary p-3 text-center">
              <div className="text-xl font-bold font-display">{user.lastActive}</div>
              <div className="text-xs text-muted-foreground">Last active</div>
            </div>
            <div className="rounded-lg bg-secondary p-3 text-center">
              <div className="text-xl font-bold font-display">{new Date(user.createdAt).getFullYear()}</div>
              <div className="text-xs text-muted-foreground">Joined</div>
            </div>
          </div>

          {/* Editable fields */}
          <div className="grid sm:grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label className="text-xs uppercase tracking-wide text-muted-foreground">Display name</Label>
              <Input value={name} onChange={(e) => setName(e.target.value)} disabled={isSelf ? false : !canEditRole} />
            </div>
            <div className="space-y-1.5">
              <Label className="text-xs uppercase tracking-wide text-muted-foreground">Email</Label>
              <Input value={email} onChange={(e) => setEmail(e.target.value)} disabled />
              <p className="text-[11px] text-muted-foreground flex items-center gap-1"><Icon name="Lock" className="w-3 h-3" /> Email changes require user verification.</p>
            </div>
            <div className="space-y-1.5">
              <Label className="text-xs uppercase tracking-wide text-muted-foreground">Role</Label>
              <select
                value={role}
                onChange={(e) => setRole(e.target.value as Role)}
                disabled={!canEditRole}
                className="w-full h-9 px-3 rounded-md border border-input bg-background text-sm disabled:opacity-50"
              >
                <option value="user">User</option>
                <option value="admin">Admin</option>
                <option value="super_admin">Super Admin</option>
              </select>
              {!canEditRole && <p className="text-[11px] text-muted-foreground">{isSelf ? "You can't change your own role." : "Only Super Admins can change roles."}</p>}
            </div>
            <div className="space-y-1.5">
              <Label className="text-xs uppercase tracking-wide text-muted-foreground">Account status</Label>
              <div className="flex items-center justify-between gap-3 p-2 rounded-md border border-input h-9">
                <span className="text-sm">{status === "active" ? "Active" : "Suspended"}</span>
                <Switch checked={status === "active"} onCheckedChange={(v) => setStatus(v ? "active" : "suspended")} disabled={!canSuspend} />
              </div>
              {!canSuspend && <p className="text-[11px] text-muted-foreground">{isSelf ? "You can't suspend your own account." : "Only Super Admins can suspend users."}</p>}
            </div>
          </div>

          {/* Actions */}
          <div className="rounded-lg border border-border p-3 space-y-2">
            <div className="text-sm font-medium">Account actions</div>
            <div className="flex flex-wrap gap-2">
              <Button size="sm" variant="outline" onClick={resetPassword} className="gap-1.5">
                <Icon name="Mail" className="w-3.5 h-3.5" /> Send password reset
              </Button>
              <Button
                size="sm"
                variant="outline"
                onClick={() => {
                  log({ actor: currentUser?.email ?? "admin", action: "User data exported", category: "admin", details: user.email, severity: "info" });
                  toast.success(`Data export queued for ${user.email}.`);
                }}
                className="gap-1.5"
              >
                <Icon name="Download" className="w-3.5 h-3.5" /> Export user data
              </Button>
              {canSuspend && status === "active" ? (
                <Button size="sm" variant="outline" className="text-destructive gap-1.5" onClick={() => { setStatus("suspended"); toast.info("Mark as suspended, then Save to apply."); }}>
                  <Icon name="UserX" className="w-3.5 h-3.5" /> Suspend
                </Button>
              ) : canSuspend && status === "suspended" ? (
                <Button size="sm" variant="outline" className="text-emerald-600 gap-1.5" onClick={() => { setStatus("active"); toast.info("Mark as active, then Save to apply."); }}>
                  <Icon name="UserCheck" className="w-3.5 h-3.5" /> Reactivate
                </Button>
              ) : null}
            </div>
          </div>
        </div>

        <div className="sticky bottom-0 bg-card border-t border-border p-4 flex justify-end gap-2">
          <Button variant="outline" onClick={onClose}>Cancel</Button>
          <Button onClick={save} disabled={saving} className="bg-brand hover:bg-brand-dark text-white gap-2">
            {saving ? <Icon name="Loader2" className="w-4 h-4 animate-spin" /> : <Icon name="Save" className="w-4 h-4" />}
            Save changes
          </Button>
        </div>
      </motion.div>
    </motion.div>
  );
}

src/components/app/modules/Users.tsx:
"use client";

import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge, Icon } from "@/components/shared";
import { useApp } from "@/lib/store";
import { refreshUsers } from "@/lib/cloud-api";
import { toast } from "sonner";
import { UserDetailModal, type ManagedUser } from "./UserDetailModal";
import { validatePassword } from "@/lib/auth-utils";

const AVATAR_COLORS = ["#1154A3", "#F59E0B", "#10B981", "#8B5CF6", "#EC4899", "#0EA5E9", "#DC2626", "#0B1F3A"];

export function Users() {
  const users = useApp((s) => s.users);
  const currentUser = useApp((s) => s.user);
  const approveUser = useApp((s) => s.approveUser);
  const suspendUser = useApp((s) => s.suspendUser);
  const unsuspendUser = useApp((s) => s.unsuspendUser);
  const deleteUser = useApp((s) => s.deleteUser);
  const promoteToAdmin = useApp((s) => s.promoteToAdmin);
  const demoteToUser = useApp((s) => s.demoteToUser);
  const resetUserPassword = useApp((s) => s.resetUserPassword);
  const log = useApp((s) => s.log);

  // === BUG FIX: Force-refresh users from D1 on mount ===
  // This ensures the admin always sees the latest users including Puter
  // users that were created since the last sync.
  useEffect(() => {
    refreshUsers(useApp);
  }, []);

  const [q, setQ] = useState("");
  const [roleFilter, setRoleFilter] = useState("all");
  const [statusFilter, setStatusFilter] = useState("all");
  const [selected, setSelected] = useState<ManagedUser | null>(null);
  const [resetTarget, setResetTarget] = useState<ManagedUser | null>(null);
  const [newPassword, setNewPassword] = useState("");

  const filtered = users.filter((u) => {
    if (roleFilter !== "all" && u.role !== roleFilter) return false;
    if (statusFilter !== "all" && u.status !== statusFilter) return false;
    if (q && !`${u.name} ${u.email} ${u.username ?? ""}`.toLowerCase().includes(q.toLowerCase())) return false;
    return true;
  });

  const stats = {
    total: users.length,
    approved: users.filter((u) => u.status === "approved").length,
    pending: users.filter((u) => u.status === "pending").length,
    suspended: users.filter((u) => u.status === "suspended").length,
    deleted: users.filter((u) => u.status === "deleted").length,
  };

  const toManaged = (u: any): ManagedUser => ({
    id: u.id,
    name: u.name,
    email: u.email,
    role: u.role,
    status: u.status === "suspended" ? "suspended" : "active",
    resumes: u.usage?.resumesGenerated ?? 0,
    lastActive: u.lastActiveAt ? new Date(u.lastActiveAt).toLocaleDateString() : "Never",
    provider: u.provider || "email",
    createdAt: u.createdAt,
    avatarColor: AVATAR_COLORS[users.indexOf(u) % AVATAR_COLORS.length],
  });

  const handleAction = (action: string, user: any) => {
    const isSelf = user.email === currentUser?.email;
    if (isSelf && action !== "view") {
      toast.error("You cannot perform this action on your own account.");
      return;
    }
    switch (action) {
      case "approve": approveUser(user.id); toast.success(`${user.name} approved.`); break;
      case "suspend": suspendUser(user.id); toast.success(`${user.name} suspended.`); break;
      case "unsuspend": unsuspendUser(user.id); toast.success(`${user.name} reactivated.`); break;
      case "delete": if (confirm(`Delete ${user.name}? (soft delete — data preserved)`)) { deleteUser(user.id); toast.success(`${user.name} deleted.`); } break;
      case "promote": promoteToAdmin(user.id); toast.success(`${user.name} promoted to admin.`); break;
      case "demote": demoteToUser(user.id); toast.success(`${user.name} demoted to user.`); break;
      case "reset": setResetTarget(toManaged(user)); setNewPassword(""); break;
    }
  };

  const handleResetPassword = () => {
    if (!resetTarget) return;
    const check = validatePassword(newPassword);
    if (!check.valid) {
      toast.error(`Password requirements: ${check.errors.join(", ")}`);
      return;
    }
    // Find the user by email
    const targetUser = users.find((u) => u.id === resetTarget.id);
    if (targetUser) {
      resetUserPassword(targetUser.id, newPassword);
      toast.success(`Password reset for ${resetTarget.name}.`);
    }
    setResetTarget(null);
    setNewPassword("");
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h1 className="font-display text-2xl font-bold flex items-center gap-2"><Icon name="Users" className="w-6 h-6 text-brand" /> User Management</h1>
          <p className="text-sm text-muted-foreground mt-1">Manage users, roles, and status. Approve, suspend, promote, or delete accounts.</p>
        </div>
      </div>

      <div className="grid grid-cols-2 lg:grid-cols-5 gap-4">
        {[
          { label: "Total", value: stats.total, icon: "Users", color: "#1154A3" },
          { label: "Approved", value: stats.approved, icon: "CheckCircle2", color: "#10B981" },
          { label: "Pending", value: stats.pending, icon: "Clock", color: "#F59E0B" },
          { label: "Suspended", value: stats.suspended, icon: "Ban", color: "#DC2626" },
          { label: "Deleted", value: stats.deleted, icon: "Trash2", color: "#6B7280" },
        ].map((s) => (
          <Card key={s.label}>
            <CardContent className="p-4 flex items-center gap-3">
              <div className="w-9 h-9 rounded-lg flex items-center justify-center" style={{ background: `${s.color}15`, color: s.color }}>
                <Icon name={s.icon} className="w-4 h-4" />
              </div>
              <div><div className="text-lg font-bold font-display">{s.value}</div><div className="text-xs text-muted-foreground">{s.label}</div></div>
            </CardContent>
          </Card>
        ))}
      </div>

      <Card>
        <CardHeader>
          <div className="flex items-center justify-between gap-3 flex-wrap">
            <CardTitle className="text-lg">All Users ({filtered.length})</CardTitle>
            <div className="flex flex-wrap gap-2">
              <select value={roleFilter} onChange={(e) => setRoleFilter(e.target.value)} className="h-9 px-3 rounded-md border border-input bg-background text-sm">
                <option value="all">All roles</option>
                <option value="user">User</option>
                <option value="admin">Admin</option>
                <option value="super_admin">Super Admin</option>
              </select>
              <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)} className="h-9 px-3 rounded-md border border-input bg-background text-sm">
                <option value="all">All statuses</option>
                <option value="approved">Approved</option>
                <option value="pending">Pending</option>
                <option value="suspended">Suspended</option>
                <option value="deleted">Deleted</option>
              </select>
              <div className="relative w-full sm:w-64">
                <Icon name="Search" className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                <Input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search…" className="pl-9 h-9" />
              </div>
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-0">
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="border-b border-border bg-secondary/50">
                <tr className="text-left text-xs uppercase tracking-wide text-muted-foreground">
                  <th className="px-4 py-2 font-semibold">User</th>
                  <th className="px-4 py-2 font-semibold">Role</th>
                  <th className="px-4 py-2 font-semibold">Provider</th>
                  <th className="px-4 py-2 font-semibold">Status</th>
                  <th className="px-4 py-2 font-semibold">Registered</th>
                  <th className="px-4 py-2 font-semibold">Last Login</th>
                  <th className="px-4 py-2 font-semibold text-right">Actions</th>
                </tr>
              </thead>
              <tbody>
                {filtered.map((u, idx) => {
                  const isSelf = u.email === currentUser?.email;
                  const canManage = currentUser?.role === "super_admin" && !isSelf;
                  return (
                    <tr key={u.id} className="border-b border-border hover:bg-secondary/30">
                      <td className="px-4 py-3">
                        <div className="flex items-center gap-2">
                          <div className="w-8 h-8 rounded-full flex items-center justify-center text-white text-xs font-semibold shrink-0" style={{ background: AVATAR_COLORS[idx % AVATAR_COLORS.length] }}>
                            {u.name.split(/\s+/).slice(0, 2).map((s) => s[0]?.toUpperCase()).join("")}
                          </div>
                          <div className="min-w-0">
                            <div className="font-medium flex items-center gap-1.5">{u.name}{isSelf && <Badge variant="brand" className="text-[9px]">YOU</Badge>}</div>
                            <div className="text-xs text-muted-foreground truncate">{u.email}</div>
                          </div>
                        </div>
                      </td>
                      <td className="px-4 py-3"><Badge variant={u.role === "super_admin" ? "gold" : u.role === "admin" ? "brand" : "outline"} className="capitalize text-[10px]">{u.role.replace("_", " ")}</Badge></td>
                      <td className="px-4 py-3 text-xs capitalize text-muted-foreground">{u.provider}</td>
                      <td className="px-4 py-3"><Badge variant={u.status === "approved" ? "success" : u.status === "pending" ? "warning" : u.status === "suspended" ? "danger" : "outline"} className="capitalize text-[10px]">{u.status}</Badge></td>
                      <td className="px-4 py-3 text-xs text-muted-foreground">{new Date(u.createdAt).toLocaleDateString()}</td>
                      <td className="px-4 py-3 text-xs text-muted-foreground">{u.lastLoginAt ? new Date(u.lastLoginAt).toLocaleDateString() : "Never"}</td>
                      <td className="px-4 py-3">
                        <div className="flex gap-0.5 justify-end flex-wrap">
                          {u.status === "pending" && <IconBtn icon="Check" label="Approve" color="#10B981" onClick={() => handleAction("approve", u)} disabled={!canManage} />}
                          {u.status === "approved" && <IconBtn icon="Ban" label="Suspend" color="#DC2626" onClick={() => handleAction("suspend", u)} disabled={!canManage} />}
                          {u.status === "suspended" && <IconBtn icon="UserCheck" label="Unsuspend" color="#10B981" onClick={() => handleAction("unsuspend", u)} disabled={!canManage} />}
                          {u.role === "user" && <IconBtn icon="ArrowUp" label="Promote to admin" color="#1154A3" onClick={() => handleAction("promote", u)} disabled={!canManage} />}
                          {u.role === "admin" && <IconBtn icon="ArrowDown" label="Demote to user" color="#64748B" onClick={() => handleAction("demote", u)} disabled={!canManage} />}
                          <IconBtn icon="KeyRound" label="Reset password" color="#F59E0B" onClick={() => handleAction("reset", u)} disabled={!canManage} />
                          <IconBtn icon="Eye" label="View details" onClick={() => setSelected(toManaged(u))} />
                          {u.status !== "deleted" && <IconBtn icon="Trash2" label="Delete" color="#DC2626" onClick={() => handleAction("delete", u)} disabled={!canManage} />}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>

      {selected && <UserDetailModal user={selected} onClose={() => setSelected(null)} />}
      {resetTarget && (
        <div className="fixed inset-0 z-50 bg-background/80 backdrop-blur-sm flex items-center justify-center p-4" onClick={() => setResetTarget(null)}>
          <div className="bg-card rounded-2xl border border-border shadow-premium w-full max-w-md p-6 space-y-4" onClick={(e) => e.stopPropagation()}>
            <h3 className="font-display font-bold text-lg flex items-center gap-2"><Icon name="KeyRound" className="w-5 h-5 text-brand" /> Reset Password</h3>
            <p className="text-sm text-muted-foreground">Set a new password for <strong>{resetTarget.name}</strong> ({resetTarget.email})</p>
            <Input type="password" value={newPassword} onChange={(e) => setNewPassword(e.target.value)} placeholder="Min 12 chars, Aa1!" />
            {newPassword && <p className="text-xs text-muted-foreground">Password must have 12+ chars, uppercase, lowercase, number, special char</p>}
            <div className="flex gap-2 justify-end">
              <Button variant="outline" onClick={() => setResetTarget(null)}>Cancel</Button>
              <Button onClick={handleResetPassword} className="bg-brand hover:bg-brand-dark text-white">Reset password</Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function IconBtn({ icon, label, onClick, color, disabled }: { icon: string; label: string; onClick: () => void; color?: string; disabled?: boolean }) {
  return (
    <button onClick={onClick} title={label} aria-label={label} disabled={disabled} className="w-7 h-7 rounded-md hover:bg-secondary flex items-center justify-center text-muted-foreground hover:text-foreground transition disabled:opacity-30 disabled:cursor-not-allowed" style={color ? { color } : undefined}>
      <Icon name={icon} className="w-3.5 h-3.5" />
    </button>
  );
}

src/components/app/modules/VoiceMockInte:
"use client";

// ============================================================================
// VoiceMockInterview — real-time AI voice mock interview (recommendation #4).
//
// The missing piece between two existing surfaces:
//   • AiMockInterview — conversational AI, but TEXT-only answers.
//   • VoiceInterviewSession — speech I/O, but a fixed Sonru-style question
//     package evaluated after the fact, not a conversation.
//
// Here the AI asks questions OUT LOUD (browser speechSynthesis, chunked to
// dodge Chrome's long-utterance cutoff), the candidate answers by speaking
// (live Web Speech ASR with interim captions), and after every answer the AI
// gives one sentence of feedback plus the next question. Local delivery
// metrics (pace / fillers / substance) accrue per answer and roll up into a
// final report alongside an AI coaching summary.
//
// Reuses: useSpeechRecognition + useSpeechSynthesis (hooks/interview),
// analyzeFillerWords (via voice-conversation), recordAI routing (document
// task category — API providers, proven to follow the interview prompts),
// and the INTERVIEW_TOPICS config exported from CareerTools.
// ============================================================================

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge, Icon, ScoreRing } from "@/components/shared";
import { toast } from "sonner";
import { recordAI } from "@/lib/ai/flight-recorder";
import { useSpeechRecognition, useSpeechSynthesis } from "@/hooks/interview";
import {
  buildFirstQuestionPrompt,
  buildNextQuestionPrompt,
  buildSummaryPrompt,
  buildVoiceReport,
  computeAnswerMetrics,
  parseInterviewerTurn,
  splitForSpeech,
  type InterviewTopicContext,
  type VoiceTurn,
  type VoiceReportConfig,
} from "@/lib/interview/voice-conversation";
import { INTERVIEW_TOPICS, POSITION_PRESETS, TOPIC_QUESTION_EXAMPLES } from "./CareerTools";

type Phase = "setup" | "session" | "report";
type SessionBusy = "idle" | "thinking" | "listening" | "evaluating";

const QUESTION_COUNTS = [3, 5, 8] as const;
const MIN_ANSWER_WORDS = 3;

export function VoiceMockInterview() {
  // ── setup state ────────────────────────────────────────────────────────────
  const [phase, setPhase] = useState<Phase>("setup");
  const [topic, setTopic] = useState<string>("cabin-crew");
  const [position, setPosition] = useState<string>("");
  const [customPosition, setCustomPosition] = useState<string>("");
  const [targetQuestions, setTargetQuestions] = useState<number>(5);
  const [voiceURI, setVoiceURI] = useState<string>("");
  const [rate, setRate] = useState<number>(1);

  // ── session state ──────────────────────────────────────────────────────────
  const [turns, setTurns] = useState<VoiceTurn[]>([]);
  const [busy, setBusy] = useState<SessionBusy>("idle");
  const [currentQuestion, setCurrentQuestion] = useState<string>("");
  const [questionIndex, setQuestionIndex] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [autoSpeak, setAutoSpeak] = useState(true);
  const [sessionEnded, setSessionEnded] = useState(false);

  // ── report state ───────────────────────────────────────────────────────────
  const [report, setReport] = useState<ReturnType<typeof buildVoiceReport> | null>(null);
  const [summary, setSummary] = useState<string>("");
  const [summaryLoading, setSummaryLoading] = useState(false);

  const speech = useSpeechRecognition({ continuous: true, interimResults: true });
  const tts = useSpeechSynthesis();

  const answerStartRef = useRef<number>(0);
  const scrollRef = useRef<HTMLDivElement>(null);
  const turnsRef = useRef<VoiceTurn[]>([]);
  turnsRef.current = turns;

  // Mirror the recognizer state into refs so async handlers (which capture a
  // render-time closure) can read the LATEST transcript after stop()+delay.
  const transcriptRef = useRef("");
  const interimRef = useRef("");
  useEffect(() => {
    transcriptRef.current = speech.transcript;
    interimRef.current = speech.interimTranscript;
  }, [speech.transcript, speech.interimTranscript]);

  const selectedTopic = INTERVIEW_TOPICS.find((t) => t.id === topic);
  const positionPresets = POSITION_PRESETS[topic] ?? [];
  const effectivePosition = customPosition.trim() || position || (selectedTopic?.label ?? "the role");

  const topicContext: InterviewTopicContext = useMemo(
    () => ({
      topicLabel: selectedTopic?.label ?? "General",
      topicDescription: selectedTopic?.description,
      position: effectivePosition,
      questionExamples: TOPIC_QUESTION_EXAMPLES[topic] ?? [],
    }),
    [selectedTopic, effectivePosition, topic],
  );

  const reportConfig: VoiceReportConfig = useMemo(
    () => ({ position: effectivePosition, topicLabel: selectedTopic?.label ?? "General", targetQuestions }),
    [effectivePosition, selectedTopic, targetQuestions],
  );

  const englishVoices = useMemo(
    () => tts.voices.filter((v) => v.lang?.toLowerCase().startsWith("en")),
    [tts.voices],
  );

  const scrollToBottom = useCallback(() => {
    requestAnimationFrame(() => {
      scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: "smooth" });
    });
  }, []);

  /** Speak a question aloud (unless muted / unsupported). */
  const speakQuestion = useCallback(
    (text: string) => {
      if (!autoSpeak || !tts.supported) return;
      tts.speak(splitForSpeech(text), { voiceURI: voiceURI || undefined, rate });
    },
    [autoSpeak, tts, voiceURI, rate],
  );

  // ── session flow ───────────────────────────────────────────────────────────

  const askAI = useCallback(
    async (pair: { systemPrompt: string; userPrompt: string }): Promise<string> => {
      const res = await recordAI({
        systemPrompt: pair.systemPrompt,
        userPrompt: pair.userPrompt,
        maxTokens: 500,
        taskCategory: "document", // API providers — proven prompt followers
        temperature: 0.9,
      });
      return res.text ?? "";
    },
    [],
  );

  const startInterview = async () => {
    setPhase("session");
    setTurns([]);
    setError(null);
    setQuestionIndex(0);
    setSessionEnded(false);
    setReport(null);
    setSummary("");
    setBusy("thinking");
    try {
      const raw = await askAI(buildFirstQuestionPrompt(topicContext));
      const parsed = parseInterviewerTurn(raw);
      const q = parsed.question ?? raw;
      setTurns([{ role: "interviewer", text: raw, question: q, feedback: parsed.feedback, at: new Date().toISOString() }]);
      setCurrentQuestion(q);
      setQuestionIndex(1);
      scrollToBottom();
      speakQuestion(q);
    } catch (e: any) {
      setError(e?.message || "Failed to start the interview. Please try again.");
      toast.error(e?.message || "Failed to start the interview.");
      setPhase("setup");
    } finally {
      setBusy("idle");
    }
  };

  const beginAnswer = () => {
    if (busy !== "idle" || !speech.supported) return;
    tts.cancel();
    speech.reset();
    answerStartRef.current = Date.now();
    speech.start();
    setBusy("listening");
  };

  const finishAnswer = async () => {
    if (busy !== "listening") return;
    speech.stop();
    setBusy("evaluating");

    // Give the recognizer a beat to flush its final result after stop(), then
    // read the ref mirrors (state captured in this closure would be stale).
    await new Promise((r) => setTimeout(r, 500));
    const flushed = [transcriptRef.current.trim(), interimRef.current.trim()].filter(Boolean).join(" ");
    const transcript = flushed.trim();
    const durationMs = Date.now() - answerStartRef.current;

    // Nothing usable captured → let the user retry without advancing.
    if (transcript.split(/\s+/).filter(Boolean).length < MIN_ANSWER_WORDS) {
      speech.reset();
      setBusy("idle");
      toast.error("I didn't catch that — hold the mic and answer again.");
      return;
    }

    const metrics = computeAnswerMetrics(transcript, durationMs);
    const nextTurns: VoiceTurn[] = [
      ...turnsRef.current,
      { role: "candidate", text: transcript, metrics, at: new Date().toISOString() },
    ];
    setTurns(nextTurns);
    scrollToBottom();
    speech.reset();

    // Last question reached → wrap up into the report.
    if (questionIndex >= targetQuestions) {
      await endSession(nextTurns);
      return;
    }

    try {
      const raw = await askAI(
        buildNextQuestionPrompt(
          topicContext,
          nextTurns.map((t) => ({ role: t.role, text: t.text })),
          transcript,
        ),
      );
      const parsed = parseInterviewerTurn(raw);
      const q = parsed.question ?? raw;
      setTurns([...nextTurns, { role: "interviewer", text: raw, question: q, feedback: parsed.feedback, at: new Date().toISOString() }]);
      setCurrentQuestion(q);
      setQuestionIndex((i) => i + 1);
      scrollToBottom();
      speakQuestion(q);
    } catch (e: any) {
      setError(e?.message || "The interviewer lost the thread — try again.");
      toast.error(e?.message || "Failed to get the next question.");
    } finally {
      setBusy("idle");
    }
  };

  const skipQuestion = async () => {
    if (busy !== "idle") return;
    const nextTurns: VoiceTurn[] = [
      ...turnsRef.current,
      { role: "candidate", text: "", skipped: true, at: new Date().toISOString() },
    ];
    setTurns(nextTurns);
    if (questionIndex >= targetQuestions) {
      await endSession(nextTurns);
      return;
    }
    setBusy("thinking");
    try {
      const raw = await askAI(
        buildNextQuestionPrompt(
          topicContext,
          nextTurns.map((t) => ({ role: t.role, text: t.text || "(skipped)" })),
          "(The candidate skipped this question.)",
        ),
      );
      const parsed = parseInterviewerTurn(raw);
      const q = parsed.question ?? raw;
      setTurns([...nextTurns, { role: "interviewer", text: raw, question: q, feedback: parsed.feedback, at: new Date().toISOString() }]);
      setCurrentQuestion(q);
      setQuestionIndex((i) => i + 1);
      scrollToBottom();
      speakQuestion(q);
    } catch (e: any) {
      toast.error(e?.message || "Failed to move on.");
    } finally {
      setBusy("idle");
    }
  };

  const endSession = async (finalTurns?: VoiceTurn[]) => {
    tts.cancel();
    speech.stop();
    const allTurns = finalTurns ?? turnsRef.current;
    const rep = buildVoiceReport(allTurns, reportConfig);
    setReport(rep);
    setPhase("report");
    setSessionEnded(true);

    // AI coaching summary runs in the background — the metrics report shows first.
    setSummaryLoading(true);
    try {
      const text = await askAI(
        buildSummaryPrompt(
          topicContext,
          allTurns.map((t) => ({ role: t.role, text: t.text })),
        ),
      );
      setSummary(text.trim());
    } catch {
      setSummary(""); // metrics report still stands on its own
    } finally {
      setSummaryLoading(false);
    }
  };

  const downloadReport = () => {
    if (!report) return;
    const payload = {
      app: "ResumeAI Pro — Voice Mock Interview",
      generatedAt: new Date().toISOString(),
      config: { ...reportConfig, targetQuestions },
      turns: turns.map((t) => ({ role: t.role, text: t.text, skipped: t.skipped, metrics: t.metrics })),
      report,
      aiSummary: summary,
    };
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `voice-interview-report-${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
    URL.revokeObjectURL(url);
    toast.success("Report downloaded.");
  };

  const copyTranscript = () => {
    const text = turns
      .map((t) => `${t.role === "interviewer" ? "Q" : "A"}: ${t.text}`)
      .join("\n\n");
    navigator.clipboard.writeText(text).then(
      () => toast.success("Transcript copied."),
      () => toast.error("Copy failed."),
    );
  };

  const testVoice = () => {
    tts.speak(splitForSpeech("This is how your interviewer will sound. Ready when you are."), {
      voiceURI: voiceURI || undefined,
      rate,
    });
  };

  // ── Setup screen ───────────────────────────────────────────────────────────
  if (phase === "setup") {
    const voiceReady = speech.supported && tts.supported;
    return (
      <div className="space-y-6">
        <div>
          <h1 className="font-display text-2xl font-bold flex items-center gap-2">
            <Icon name="AudioLines" className="w-6 h-6 text-brand" /> Voice Mock Interview
          </h1>
          <p className="text-sm text-muted-foreground mt-1">
            A real AI interviewer speaks questions aloud — you answer by voice. Live captions, delivery
            metrics, and a coaching report at the end.
          </p>
        </div>

        {!voiceReady && (
          <Card>
            <CardContent className="p-4 flex items-start gap-3">
              <Icon name="AlertTriangle" className="w-5 h-5 text-amber-500 shrink-0 mt-0.5" />
              <div className="text-sm space-y-1">
                <p className="font-semibold">Voice features need a compatible browser</p>
                <p className="text-muted-foreground text-xs leading-relaxed">
                  {!speech.supported && "Speech recognition (answering by voice) is unavailable here — Chrome or Edge on desktop works best. "}
                  {!tts.supported && "Speech synthesis (spoken questions) is unavailable here. "}
                  The AI mock interview still works with typed answers.
                </p>
              </div>
            </CardContent>
          </Card>
        )}

        <Card>
          <CardContent className="p-4 sm:p-5 space-y-4">
            <div className="grid sm:grid-cols-2 gap-3">
              <div>
                <label className="text-xs font-semibold text-muted-foreground mb-1 block">Topic</label>
                <select
                  value={topic}
                  onChange={(e) => { setTopic(e.target.value); setPosition(""); setCustomPosition(""); }}
                  className="w-full h-9 px-2 rounded border border-input bg-background text-sm"
                >
                  {INTERVIEW_TOPICS.map((t) => (
                    <option key={t.id} value={t.id}>{t.label}</option>
                  ))}
                </select>
              </div>
              <div>
                <label className="text-xs font-semibold text-muted-foreground mb-1 block">Position</label>
                <select
                  value={position}
                  onChange={(e) => { setPosition(e.target.value); setCustomPosition(""); }}
                  className="w-full h-9 px-2 rounded border border-input bg-background text-sm"
                >
                  <option value="">Custom / default</option>
                  {positionPresets.map((p) => (
                    <option key={p} value={p}>{p}</option>
                  ))}
                </select>
              </div>
            </div>
            <div>
              <label className="text-xs font-semibold text-muted-foreground mb-1 block">Custom position (optional)</label>
              <Input value={customPosition} onChange={(e) => setCustomPosition(e.target.value)} placeholder={effectivePosition} />
            </div>

            <div className="grid sm:grid-cols-2 gap-4">
              <div>
                <label className="text-xs font-semibold text-muted-foreground mb-1.5 block">Questions</label>
                <div className="flex gap-2">
                  {QUESTION_COUNTS.map((n) => (
                    <button
                      key={n}
                      onClick={() => setTargetQuestions(n)}
                      className={`px-3 py-1.5 rounded-lg text-xs font-semibold border transition ${targetQuestions === n ? "bg-brand text-white border-brand" : "bg-background border-border hover:bg-secondary"}`}
                    >
                      {n}
                    </button>
                  ))}
                </div>
              </div>
              <div>
                <label className="text-xs font-semibold text-muted-foreground mb-1.5 block">Interviewer voice</label>
                <div className="flex gap-2">
                  <select
                    value={voiceURI}
                    onChange={(e) => setVoiceURI(e.target.value)}
                    className="flex-1 h-9 px-2 rounded border border-input bg-background text-xs"
                  >
                    <option value="">Default voice</option>
                    {englishVoices.map((v) => (
                      <option key={v.voiceURI} value={v.voiceURI}>{v.name}</option>
                    ))}
                  </select>
                  <Button size="sm" variant="outline" onClick={testVoice} disabled={!tts.supported} className="h-9 gap-1.5">
                    <Icon name="Volume2" className="w-3.5 h-3.5" /> Test
                  </Button>
                </div>
                <div className="flex items-center gap-2 mt-2">
                  <span className="text-[10px] text-muted-foreground shrink-0">Speed {rate.toFixed(1)}×</span>
                  <input
                    type="range" min={0.7} max={1.5} step={0.1} value={rate}
                    onChange={(e) => setRate(parseFloat(e.target.value))}
                    className="flex-1 accent-[hsl(var(--brand))]"
                  />
                </div>
              </div>
            </div>

            <Button onClick={startInterview} disabled={!voiceReady} className="w-full gap-2">
              <Icon name="Mic" className="w-4 h-4" /> Start voice interview
            </Button>
            <p className="text-[11px] text-muted-foreground text-center">
              {targetQuestions} questions · answers spoken aloud · transcription happens in your browser
            </p>
          </CardContent>
        </Card>
      </div>
    );
  }

  // ── Report screen ──────────────────────────────────────────────────────────
  if (phase === "report" && report) {
    return (
      <div className="space-y-6">
        <div className="flex items-center justify-between gap-3 flex-wrap">
          <div>
            <h1 className="font-display text-2xl font-bold flex items-center gap-2">
              <Icon name="ClipboardCheck" className="w-6 h-6 text-brand" /> Interview Report
            </h1>
            <p className="text-sm text-muted-foreground mt-1">
              {reportConfig.position} · {reportConfig.topicLabel} · {report.totals.answered}/{report.totals.questions} answered
            </p>
          </div>
          <div className="flex gap-2">
            <Button variant="outline" size="sm" onClick={copyTranscript} className="gap-1.5"><Icon name="Copy" className="w-3.5 h-3.5" /> Transcript</Button>
            <Button variant="outline" size="sm" onClick={downloadReport} className="gap-1.5"><Icon name="Download" className="w-3.5 h-3.5" /> JSON</Button>
            <Button size="sm" onClick={() => setPhase("setup")} className="gap-1.5"><Icon name="RotateCcw" className="w-3.5 h-3.5" /> New session</Button>
          </div>
        </div>

        <div className="grid lg:grid-cols-3 gap-4">
          <Card>
            <CardContent className="p-5 flex flex-col items-center gap-2">
              <ScoreRing value={report.delivery.score} size={110} stroke={9} label="Delivery" />
              <p className="text-xs text-muted-foreground text-center leading-relaxed">{report.delivery.verdict}</p>
            </CardContent>
          </Card>
          <Card className="lg:col-span-2">
            <CardContent className="p-5 space-y-3">
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                {[
                  { label: "Avg pace", value: `${report.delivery.avgWpm} wpm`, icon: "Gauge" },
                  { label: "Filler words", value: String(report.delivery.totalFillers), icon: "MessageSquareX" },
                  { label: "Talk time", value: `${Math.round(report.totals.talkTimeMs / 1000)}s`, icon: "Timer" },
                  { label: "Skipped", value: String(report.totals.skipped), icon: "SkipForward" },
                ].map((s) => (
                  <div key={s.label} className="rounded-xl border border-border p-3 text-center">
                    <Icon name={s.icon} className="w-4 h-4 text-brand mx-auto mb-1" />
                    <div className="text-lg font-bold">{s.value}</div>
                    <div className="text-[10px] text-muted-foreground">{s.label}</div>
                  </div>
                ))}
              </div>
              <div className="rounded-xl bg-secondary/30 border border-border p-3">
                <div className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wide mb-1.5">AI coaching summary</div>
                {summaryLoading ? (
                  <p className="text-xs text-muted-foreground flex items-center gap-2"><Icon name="Loader2" className="w-3.5 h-3.5 animate-spin" /> Reviewing your transcript…</p>
                ) : summary ? (
                  <pre className="text-xs whitespace-pre-wrap font-sans leading-relaxed">{summary}</pre>
                ) : (
                  <p className="text-xs text-muted-foreground">Summary unavailable — the delivery metrics above still apply.</p>
                )}
              </div>
            </CardContent>
          </Card>
        </div>

        <Card>
          <CardContent className="p-5 space-y-2">
            <h3 className="text-xs font-bold text-foreground flex items-center gap-1.5 mb-2">
              <Icon name="ListChecks" className="w-4 h-4 text-brand" /> Question-by-question
            </h3>
            {report.perQuestion.map((q) => (
              <div key={q.index} className="rounded-xl border border-border p-3 space-y-1.5">
                <div className="flex items-start justify-between gap-3">
                  <p className="text-xs font-semibold text-foreground">{q.index}. {q.question}</p>
                  <Badge variant={q.skipped ? "outline" : q.score >= 85 ? "success" : q.score >= 60 ? "warning" : "danger"} className="text-[10px] shrink-0">
                    {q.skipped ? "skipped" : `${q.score}/100`}
                  </Badge>
                </div>
                <p className="text-[11px] text-muted-foreground leading-relaxed">“{q.answerPreview}”</p>
                {!q.skipped && (
                  <p className="text-[10px] text-muted-foreground font-mono">{q.wpm} wpm · {q.fillers} filler{q.fillers === 1 ? "" : "s"}</p>
                )}
              </div>
            ))}
          </CardContent>
        </Card>
      </div>
    );
  }

  // ── Session screen ─────────────────────────────────────────────────────────
  const listening = busy === "listening";
  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between gap-3 flex-wrap">
        <div>
          <h1 className="font-display text-xl font-bold flex items-center gap-2">
            <Icon name="AudioLines" className="w-5 h-5 text-brand" /> Voice Interview
            <Badge variant="outline" className="text-[10px] font-mono">{questionIndex}/{targetQuestions}</Badge>
          </h1>
          <p className="text-xs text-muted-foreground mt-0.5">{reportConfig.position} · {reportConfig.topicLabel}</p>
        </div>
        <div className="flex items-center gap-2">
          <label className="flex items-center gap-1.5 text-[11px] cursor-pointer select-none">
            <input type="checkbox" checked={autoSpeak} onChange={(e) => { setAutoSpeak(e.target.checked); if (!e.target.checked) tts.cancel(); }} className="rounded border-input" />
            <Icon name="Volume2" className="w-3.5 h-3.5" /> Read aloud
          </label>
          <Button variant="outline" size="sm" onClick={() => speakQuestion(currentQuestion)} disabled={tts.speaking || !currentQuestion} className="h-8 gap-1.5">
            <Icon name="Repeat" className="w-3.5 h-3.5" /> Repeat
          </Button>
          <Button variant="outline" size="sm" onClick={() => endSession()} className="h-8 gap-1.5">
            <Icon name="PhoneOff" className="w-3.5 h-3.5" /> End &amp; report
          </Button>
        </div>
      </div>

      {error && (
        <div className="rounded-lg border border-destructive/30 bg-destructive/10 px-3 py-2 text-xs text-destructive flex items-center gap-2">
          <Icon name="AlertCircle" className="w-4 h-4" /> {error}
        </div>
      )}

      {/* Conversation */}
      <div ref={scrollRef} className="rounded-xl border border-border bg-card p-4 space-y-3 overflow-y-auto scrollbar-thin" style={{ maxHeight: "calc(100vh - 340px)" }}>
        {turns.map((t, i) =>
          t.role === "interviewer" ? (
            <div key={i} className="flex items-start gap-2.5">
              <div className="w-8 h-8 rounded-full bg-brand/10 flex items-center justify-center shrink-0">
                <Icon name="Bot" className="w-4 h-4 text-brand" />
              </div>
              <div className="rounded-2xl rounded-tl-sm bg-secondary/50 border border-border px-3.5 py-2.5 max-w-[85%]">
                {t.feedback && <p className="text-[11px] text-emerald-600 dark:text-emerald-400 mb-1">{t.feedback}</p>}
                <p className="text-sm text-foreground leading-relaxed">{t.question ?? t.text}</p>
              </div>
            </div>
          ) : (
            <div key={i} className="flex items-start gap-2.5 justify-end">
              <div className={`rounded-2xl rounded-tr-sm px-3.5 py-2.5 max-w-[85%] border ${t.skipped ? "bg-secondary/20 border-dashed border-border" : "bg-brand/10 border-brand/20"}`}>
                <p className="text-sm text-foreground leading-relaxed">{t.skipped ? <em className="text-muted-foreground">— skipped —</em> : t.text}</p>
                {t.metrics && (
                  <p className="text-[10px] text-muted-foreground font-mono mt-1">
                    {t.metrics.wpm} wpm · {t.metrics.fillerCount} filler{t.metrics.fillerCount === 1 ? "" : "s"} · {t.metrics.score}/100
                  </p>
                )}
              </div>
              <div className="w-8 h-8 rounded-full bg-secondary flex items-center justify-center shrink-0">
                <Icon name="User" className="w-4 h-4 text-muted-foreground" />
              </div>
            </div>
          ),
        )}

        {busy === "thinking" && (
          <div className="flex items-center gap-2 text-xs text-muted-foreground pl-11">
            <Icon name="Loader2" className="w-3.5 h-3.5 animate-spin" /> The interviewer is thinking…
          </div>
        )}
        {tts.speaking && (
          <div className="flex items-center gap-2 text-xs text-brand pl-11">
            <Icon name="Volume2" className="w-3.5 h-3.5 animate-pulse" /> Speaking — your mic is paused.
          </div>
        )}
        {listening && speech.interimTranscript && (
          <div className="flex justify-end">
            <div className="rounded-2xl rounded-tr-sm bg-secondary/30 border border-dashed border-border px-3.5 py-2.5 max-w-[85%]">
              <p className="text-sm text-muted-foreground italic">{speech.interimTranscript}…</p>
            </div>
          </div>
        )}
      </div>

      {/* Mic controls */}
      <div className="rounded-xl border border-border bg-card p-4 flex items-center justify-between gap-3 flex-wrap">
        <div className="text-xs text-muted-foreground flex items-center gap-2 min-w-0">
          {listening ? (
            <><span className="w-2 h-2 rounded-full bg-red-500 animate-pulse shrink-0" /> Listening — answer out loud, then press stop.</>
          ) : busy === "evaluating" ? (
            <><Icon name="Loader2" className="w-3.5 h-3.5 animate-spin" /> Checking your answer…</>
          ) : (
            <><Icon name="Mic" className="w-3.5 h-3.5" /> Press the mic, answer, then press stop.</>
          )}
        </div>
        <div className="flex items-center gap-2">
          <Button variant="outline" size="sm" onClick={skipQuestion} disabled={busy !== "idle"} className="h-9 gap-1.5">
            <Icon name="SkipForward" className="w-3.5 h-3.5" /> Skip
          </Button>
          {listening ? (
            <Button size="sm" onClick={finishAnswer} className="h-9 gap-1.5 bg-red-600 hover:bg-red-700 text-white">
              <Icon name="Square" className="w-3.5 h-3.5" /> Stop answer
            </Button>
          ) : (
            <Button size="sm" onClick={beginAnswer} disabled={busy !== "idle" || !speech.supported || tts.speaking} className="h-9 gap-1.5">
              <Icon name="Mic" className="w-3.5 h-3.5" /> Answer
            </Button>
          )}
        </div>
      </div>
    </div>
  );
}

