      <div className="h-1.5 bg-secondary rounded-full overflow-hidden">
        <div className="h-full rounded-full" style={{ width: `${value}%`, background: value >= 70 ? "#10B981" : value >= 50 ? "#F59E0B" : "#DC2626" }} />
      </div>
