"use client";

import { useEffect, useRef, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Button } from "@/components/ui/button";
import { Icon } from "@/components/shared";
import { toast } from "sonner";

/**
 * PWAInstaller — registers the service worker and shows an install prompt
 * when the browser fires `beforeinstallprompt` (Chrome/Edge/Android).
 *
 * On iOS Safari, `beforeinstallprompt` never fires — iOS users must manually
 * tap Share → "Add to Home Screen". We detect iOS and show a one-time
 * instruction toast instead.
 *
 * The install banner appears:
 *   - After the user has used the app for at least 30 seconds (engagement heuristic)
 *   - Only once per session (localStorage flag `pwa-install-dismissed`)
 *   - Dismissible (X button) — won't show again until cleared
 */
export function PWAInstaller() {
  // Lazy initializers — compute once on first render instead of in useEffect
  // (avoids the React 19 "setState in effect" warning and the resulting
  // cascading-render performance penalty).
  const [isInstalled, setIsInstalled] = useState<boolean>(() => {
    if (typeof window === "undefined") return false;
    return (
      window.matchMedia("(display-mode: standalone)").matches ||
      (window.navigator as any).standalone === true
    );
  });
  const [isIOS, setIsIOS] = useState<boolean>(() => {
    if (typeof navigator === "undefined") return false;
    return (
      /iPad|iPhone|iPod/.test(navigator.userAgent) ||
      (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1)
    );
  });
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [showBanner, setShowBanner] = useState(false);

  // Refs for proper listener cleanup (prevents memory leaks on unmount)
  const swMessageHandlerRef = useRef<((e: MessageEvent) => void) | null>(null);
  const swControllerChangeHandlerRef = useRef<(() => void) | null>(null);
  const beforeInstallHandlerRef = useRef<((e: Event) => void) | null>(null);
  const appInstalledHandlerRef = useRef<(() => void) | null>(null);

  useEffect(() => {
    if (typeof window === "undefined") return;

    // Trackers for proper cleanup (avoids memory leaks when component unmounts)
    let updateInterval: ReturnType<typeof setInterval> | null = null;
    let bannerTimeout: ReturnType<typeof setTimeout> | null = null;

    // === Register the service worker ===
    if ("serviceWorker" in navigator) {
      navigator.serviceWorker
        .register("/sw.js", { scope: "/" })
        .then((registration) => {
          // Check for updates every 60 seconds
          updateInterval = setInterval(() => {
            registration.update().catch((e) => { console.warn("[PWA] SW update check failed:", e instanceof Error ? e.message : e); });
          }, 60000);
        })
        .catch((e) => { console.warn("[PWA] SW registration failed:", e instanceof Error ? e.message : e); });

      // === Listen for SW update messages ===
      const handleMessage = (event: MessageEvent) => {
        if (event.data?.type === "SW_UPDATED" || event.data?.type === "CONTENT_UPDATED") {
          // New content available — show a toast with a reload action
          toast.info("Update available", {
            duration: 10000,
            description: "A new version of ResumeAI Pro is available.",
            action: {
              label: "Reload",
              onClick: () => {
                // Clear all caches before reload
                if ("caches" in window) {
                  caches.keys().then((names) => {
                    names.forEach((name) => caches.delete(name));
                  });
                }
                window.location.reload();
              },
            },
          });
        }
      };
      navigator.serviceWorker.addEventListener("message", handleMessage);

      // === Listen for controller change (new SW took over) ===
      const handleControllerChange = () => {
        // The new SW has taken control — if we haven't shown a toast yet,
        // reload the page to get the new content
        if (!sessionStorage.getItem("sw-reloaded")) {
          sessionStorage.setItem("sw-reloaded", "1");
          window.location.reload();
        }
      };
      navigator.serviceWorker.addEventListener("controllerchange", handleControllerChange);

      // Store handlers for cleanup
      swMessageHandlerRef.current = handleMessage;
      swControllerChangeHandlerRef.current = handleControllerChange;
    }

    // === Detect if already installed (standalone mode) ===
    // (isInstalled was already computed in the lazy useState initializer —
    // no need to call setIsInstalled(true) here, which would trigger the
    // React 19 "setState in effect" cascading-render warning.)
    if (!isInstalled) {
      // === Listen for beforeinstallprompt (Chrome/Edge/Android) ===
      // (isIOS was already computed in the lazy useState initializer.)
      void isIOS; // referenced for completeness; UI uses it directly

      const handleBeforeInstallPrompt = (e: Event) => {
        e.preventDefault(); // Prevent the default browser mini-infobar
        setDeferredPrompt(e);

        // Check if the user previously dismissed the banner
        const dismissed = localStorage.getItem("pwa-install-dismissed") === "true";
        if (!dismissed) {
          // Show the banner after a short engagement delay (30s).
          // Store the timeout ID so it can be cleared on unmount (otherwise
          // it fires after unmount and calls setState on an unmounted component).
          bannerTimeout = setTimeout(() => setShowBanner(true), 30000);
        }
      };
      window.addEventListener("beforeinstallprompt", handleBeforeInstallPrompt);

      // === Listen for successful install ===
      const handleAppInstalled = () => {
        setIsInstalled(true);
        setShowBanner(false);
        setDeferredPrompt(null);
        toast.success("ResumeAI Pro installed! Find it on your home screen.");
        console.info("[PWA] App installed successfully");
      };
      window.addEventListener("appinstalled", handleAppInstalled);

      beforeInstallHandlerRef.current = handleBeforeInstallPrompt;
      appInstalledHandlerRef.current = handleAppInstalled;
    }

    return () => {
      // === Cleanup all intervals + listeners to prevent memory leaks ===
      if (updateInterval) clearInterval(updateInterval);
      if (bannerTimeout) clearTimeout(bannerTimeout);
      if (typeof navigator !== "undefined" && "serviceWorker" in navigator) {
        if (swMessageHandlerRef.current) {
          navigator.serviceWorker.removeEventListener("message", swMessageHandlerRef.current);
        }
        if (swControllerChangeHandlerRef.current) {
          navigator.serviceWorker.removeEventListener("controllerchange", swControllerChangeHandlerRef.current);
        }
      }
      if (beforeInstallHandlerRef.current) {
        window.removeEventListener("beforeinstallprompt", beforeInstallHandlerRef.current);
      }
      if (appInstalledHandlerRef.current) {
        window.removeEventListener("appinstalled", appInstalledHandlerRef.current);
      }
    };
  }, [isInstalled]);

  // === iOS instruction toast (one-time) ===
  useEffect(() => {
    if (!isIOS || isInstalled) return;
    const iosInstructed = localStorage.getItem("pwa-ios-instructed") === "true";
    if (iosInstructed) return;
    const timer = setTimeout(() => {
      toast.info("Install ResumeAI Pro as an app", {
        duration: 8000,
        description: "Tap the Share button in Safari, then 'Add to Home Screen' for the full app experience.",
        action: {
          label: "Got it",
          onClick: () => localStorage.setItem("pwa-ios-instructed", "true"),
        },
      });
      localStorage.setItem("pwa-ios-instructed", "true");
    }, 45000); // After 45s of engagement
    return () => clearTimeout(timer);
  }, [isIOS, isInstalled]);

  const handleInstall = async () => {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    const { outcome } = await deferredPrompt.userChoice;
    if (outcome === "accepted") {
      console.info("[PWA] User accepted the install prompt");
    } else {
      console.info("[PWA] User dismissed the install prompt");
      localStorage.setItem("pwa-install-dismissed", "true");
    }
    setDeferredPrompt(null);
    setShowBanner(false);
  };

  const handleDismiss = () => {
    setShowBanner(false);
    localStorage.setItem("pwa-install-dismissed", "true");
  };

  if (isInstalled) return null;

  return (
    <AnimatePresence>
      {showBanner && (
        <motion.div
          initial={{ opacity: 0, y: 100 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: 100 }}
          transition={{ type: "spring", stiffness: 300, damping: 30 }}
          className="fixed bottom-4 left-4 right-4 sm:left-auto sm:right-4 sm:w-96 z-50"
        >
          <div className="bg-card border border-border rounded-2xl shadow-premium p-4 flex items-start gap-3">
            <div className="w-10 h-10 rounded-xl bg-brand/10 flex items-center justify-center shrink-0">
              <Icon name="Download" className="w-5 h-5 text-brand" />
            </div>
            <div className="flex-1 min-w-0">
              <h3 className="font-semibold text-sm">Install ResumeAI Pro</h3>
              <p className="text-xs text-muted-foreground mt-0.5">
                Add to your home screen for quick access and offline use. No app store needed.
              </p>
              <div className="flex gap-2 mt-3">
                <Button size="sm" onClick={handleInstall} className="bg-brand hover:bg-brand-dark text-white gap-1.5 h-7 text-xs">
                  <Icon name="Download" className="w-3.5 h-3.5" /> Install
                </Button>
                <Button size="sm" variant="ghost" onClick={handleDismiss} className="h-7 text-xs">
                  Not now
                </Button>
              </div>
            </div>
            <button
              onClick={handleDismiss}
              className="text-muted-foreground hover:text-foreground shrink-0"
              aria-label="Dismiss"
            >
              <Icon name="X" className="w-4 h-4" />
            </button>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

src/components/recruiter/useSessionIntel:
"use client";

// ============================================================================
// Phase 8.1.5 — shared UI hook that assembles InterviewIntelligenceInput from
// the store and returns CandidateIntelligence via the EXISTING builder.
// This centralizes the (presentational) assembly so recruiter / analytics /
// reports / explainability views don't duplicate it. NO business logic —
// buildCandidateIntelligence owns all computation.
// ============================================================================

import { useMemo, useState } from "react";
import { useApp } from "@/lib/store";
import { buildCandidateIntelligence } from "@/lib/recruiter/candidate-intelligence";
import type { CandidateIntelligence, InterviewIntelligenceInput } from "@/lib/recruiter/recruiter-types";
import type { InterviewMemory } from "@/lib/interview/adaptive";
import type { FlightRecord } from "@/lib/ai/flight-recorder";
import type { InterviewSessionRecord } from "@/hooks/interview/types";

export interface SessionIntelligence {
  sessions: InterviewSessionRecord[];
  selectedId: string | null;
  setSelectedId: (id: string) => void;
  activeSession: InterviewSessionRecord | null;
  ci: CandidateIntelligence | null;
}

export function useSessionIntelligence(): SessionIntelligence {
  const interviewSessions = useApp((s) => s.interviewSessions);
  const atsReports = useApp((s) => s.atsReports);
  const reviewReports = useApp((s) => s.reviewReports);
  const flightRecords = useApp((s) => s.flightRecords);

  const sessions = useMemo(
    () => interviewSessions.filter((s) => s.status === "completed" && s.memory),
    [interviewSessions],
  );

  const [selectedId, setSelectedId] = useState<string | null>(sessions[0]?.id ?? null);
  const activeSession = sessions.find((s) => s.id === selectedId) ?? sessions[0] ?? null;

  const ci = useMemo(() => {
    if (!activeSession) return null;
    const memory = activeSession.memory as InterviewMemory | undefined;
    const sessionRecords = (activeSession.records ?? []) as FlightRecord[];
    const records = [...sessionRecords, ...flightRecords];
    const resumeId = activeSession.resumeId;
    const atsReport = atsReports.find((a) => a.resumeId === resumeId) ?? null;
    const reviewReport =
      reviewReports.find((r) => r.resumeId === resumeId && (!r.jdId || r.jdId === activeSession.jdId)) ??
      reviewReports.find((r) => r.resumeId === resumeId) ??
      null;
    const companyProfile = (memory as unknown as { companyProfile?: InterviewIntelligenceInput["companyProfile"] } | undefined)?.companyProfile ?? null;
    const input: InterviewIntelligenceInput = {
      memory,
      records: records.length ? records : undefined,
      atsReport,
      reviewReport,
      companyProfile,
      scenario: activeSession.company,
      persona: activeSession.role,
      position: activeSession.role,
    };
    return buildCandidateIntelligence(input);
  }, [activeSession, atsReports, reviewReports, flightRecords]);

  return { sessions, selectedId: activeSession?.id ?? null, setSelectedId, activeSession, ci };
}

src/components/resume/A4Preview.tsx:
"use client";

import { forwardRef, useMemo, useRef, useState, useEffect } from "react";
import type { ResumeData, RenderDocument } from "@/lib/types";
import { useApp } from "@/lib/store";
import { RenderDocumentPreview } from "./RenderDocumentPreview";
import { toRenderDocument } from "@/lib/render-document";

import { renderHighlightedText, safeRender } from "@/lib/ats-highlighter";
import { computeShrinkZoom } from "@/lib/preview-shrink";

interface A4PreviewProps {
  resume: ResumeData;
  scale?: number;
  className?: string;
  /**
   * When true, uses RenderDocument (SSOT) pipeline — same data as DOCX/PDF export.
   * When false (default), uses legacy per-template rendering.
   * Set true everywhere for consistent output across all renderers.
   */
  useRenderDocument?: boolean;
  showHeatmap?: boolean;
  onOverflowChange?: (overflows: boolean) => void;
}

/**
 * Pixel-accurate A4 preview rendered as a div sized 210mm × 297mm.
 * Used in the Builder, Optimizer, and Downloads modules.
 * Real PDF export uses jsPDF — this is the visual representation.
 *
 * IMPORTANT — mobile responsiveness:
 * CSS `transform: scale()` only affects visual rendering, NOT the layout box.
 * So a 210mm (794px) wide A4 page scaled to 0.4 still occupies 794px of layout
 * space, causing horizontal overflow on mobile screens. To fix this, we wrap
 * the scaled A4 page in an outer container whose width matches the SCALED
 * width (210mm × scale) and whose height matches the SCALED height (297mm × scale).
 * The inner div is then scaled with transformOrigin: 'top left' so it fills
 * the wrapper exactly. This way the parent layout sees a correctly-sized box.
 */
export const A4Preview = forwardRef<HTMLDivElement, A4PreviewProps>(function A4Preview(
  { resume, scale = 1, className, useRenderDocument = false, showHeatmap = false, onOverflowChange },
  ref
) {
  const accent = resume.accentColor || "#1154A3";
  const Template = TEMPLATE_MAP[resume.template] ?? ATSProfessionalTemplate;

  // Auto Shrink to Fit (1 Page): subscribe to the optimizer directive so a
  // directive patch re-renders the preview. Only the legacy per-template
  // path needs the zoom translation — infohas-pro reads the directive
  // natively and the RenderDocument pipeline already matches export.
  const directiveConfig = useApp((s) => s.optimizerDirective);

  const atsReports = useApp((s) => s.atsReports);
  const latestReport = atsReports.find((r) => r.resumeId === resume.id);

  const innerRef = useRef<HTMLDivElement>(null);
  const [overflows, setOverflows] = useState(false);
  const [fillPercent, setFillPercent] = useState(0);

  useEffect(() => {
    const el = innerRef.current;
    if (!el) return;

    const checkHeight = () => {
      const a4HeightPx = 297 * 3.7795275591;
      const actualHeight = el.scrollHeight || el.clientHeight || el.offsetHeight;
      const percent = (actualHeight / a4HeightPx) * 100;
      setFillPercent(Math.round(percent));
      const hasOverflow = actualHeight > a4HeightPx + 2;
      setOverflows(hasOverflow); // 2px tolerance
      if (onOverflowChange) onOverflowChange(hasOverflow);
    };

    checkHeight();
    const observer = new MutationObserver(checkHeight);
    observer.observe(el, { childList: true, subtree: true, characterData: true });
    return () => observer.disconnect();
  }, [resume]);

  // Compute the scaled dimensions in mm so the wrapper occupies the correct
  // layout space (prevents horizontal overflow on mobile).
  const scaledWidthMm = 210 * scale;
  const scaledHeightMm = 297 * scale;

  // When useRenderDocument is true, convert to RenderDocument (SSOT) and render
  // from it — matching the exact same pipeline as DOCX/PDF export.
  if (useRenderDocument) {
    return <RenderDocumentA4Preview resume={resume} scale={scale} className={className} ref={ref} />;
  }

  // Auto Shrink to Fit (1 Page) — translate the directive's bodyFontSizePt
  // knob into a uniform zoom for every template that does not natively
  // consume the directive (all but infohas-pro). zoom: 1 renders no wrapper
  // style at all, so untouched directives keep the preview pixel-identical.
  // The zoom wrapper scales fonts, line boxes, paddings, margins, and section
  // gaps proportionally — the exact contract of the Auto Shrink button — and
  // the width compensation (100 / zoom %) preserves line-wrapping so the
  // preview reflows like the exported document (export honors the same knob
  // via applyUserLayoutOverrides).
  const shrinkZoom = resume.template === "infohas-pro" ? 1 : computeShrinkZoom(directiveConfig, resume.template);

  // Helper to attach forwarded ref + local measuring ref
  const handleRef = (node: HTMLDivElement | null) => {
    (innerRef as any).current = node;
    if (typeof ref === "function") {
      ref(node);
    } else if (ref) {
      (ref as any).current = node;
    }
  };

  return (
    <div
      // Outer wrapper — occupies the SCALED layout space so the parent
      // container sees a correctly-sized box (no horizontal overflow).
      style={{
        width: `${scaledWidthMm}mm`,
        height: `${scaledHeightMm}mm`,
        position: "relative",
        overflow: "hidden",
      }}
    >
      <div
        ref={handleRef}
        className={`a4-page origin-top-left ${className ?? ""}`}
        style={{
          transform: `scale(${scale})`,
          transformOrigin: "top left",
          position: "absolute",
          top: 0,
          left: 0,
        }}
      >
        {shrinkZoom !== 1 ? (
          <div style={{ zoom: shrinkZoom, width: `${100 / shrinkZoom}%` } as React.CSSProperties}>
            <Template resume={resume} accent={accent} showHeatmap={showHeatmap} latestReport={latestReport} />
          </div>
        ) : (
          <Template resume={resume} accent={accent} showHeatmap={showHeatmap} latestReport={latestReport} />
        )}

        {/* ============ Page-Break Indicator Line ============ */}
        {overflows && (
          <div
            style={{
              position: "absolute",
              top: "297mm",
              left: 0,
              width: "100%",
              borderTop: "2px dashed #EF4444",
              zIndex: 49,
              pointerEvents: "none",
            }}
          />
        )}
      </div>

      {/* ============ Interactive Overflows Warning Badge ============ */}
      {overflows && (
        <div
          style={{
            position: "absolute",
            bottom: "8px",
            left: "50%",
            transform: "translateX(-50%)",
            backgroundColor: "rgba(239, 68, 68, 0.95)",
            color: "white",
            fontSize: "11px",
            fontWeight: "bold",
            padding: "4px 10px",
            borderRadius: "9999px",
            boxShadow: "0 4px 12px rgba(0, 0, 0, 0.15)",
            zIndex: 50,
            pointerEvents: "none",
            border: "1px solid rgb(248, 113, 113)",
            fontFamily: "sans-serif",
          }}
        >
          ⚠️ OVERFLOWS PAGE ({fillPercent}%)
        </div>
      )}
      {!overflows && fillPercent > 90 && (
        <div
          style={{
            position: "absolute",
            bottom: "8px",
            left: "50%",
            transform: "translateX(-50%)",
            backgroundColor: "rgba(245, 158, 11, 0.95)",
            color: "white",
            fontSize: "11px",
            fontWeight: "bold",
            padding: "4px 10px",
            borderRadius: "9999px",
            boxShadow: "0 4px 12px rgba(0, 0, 0, 0.15)",
            zIndex: 50,
            pointerEvents: "none",
            border: "1px solid rgb(251, 191, 36)",
            fontFamily: "sans-serif",
          }}
        >
          📏 FITS PAGE ({fillPercent}%)
        </div>
      )}
    </div>
  );
});

/**
 * Inner A4Preview that converts ResumeData → RenderDocument and delegates
 * to RenderDocumentPreview. This uses the exact same data pipeline as
 * DOCX and PDF exports, guaranteeing consistent output.
 */
const RenderDocumentA4Preview = forwardRef<HTMLDivElement, A4PreviewProps>(function RenderDocumentA4Preview(
  { resume, scale, className },
  ref
) {
  const rd: RenderDocument = useMemo(() => toRenderDocument(resume), [resume]);
  return (
    <div ref={ref}>
      <RenderDocumentPreview rd={rd} scale={scale} className={className} />
    </div>
  );
});

const TEMPLATE_MAP: Record<string, React.FC<{ resume: ResumeData; accent: string; showHeatmap?: boolean; latestReport?: any }>> = {
  "ats-professional": ATSProfessionalTemplate,
  executive: ExecutiveTemplate,
  modern: ModernTemplate,
  corporate: ATSProfessionalTemplate,
  europass: ATSProfessionalTemplate,
  creative: ModernTemplate,
  minimal: ATSProfessionalTemplate,
  "infohas-pro": InfohasProTemplate,
  compact: CompactTemplate,
  tech: TechTemplate,
  academic: AcademicTemplate,
  consulting: ConsultingTemplate,
  startup: StartupTemplate,
  classic: ClassicTemplate,
};

/**
 * Returns true when the headline field is just a reformatted copy of the
 * contact fields already shown in the contact row — suppresses duplicate
 * display across all templates.
 */
function headlineIsDuplicateContact(headline: string, contact: ResumeData["contact"]): boolean {
  if (!headline || !contact) return false;
  const hl = headline.toLowerCase();
  if (contact.email && hl.includes(contact.email.toLowerCase())) return true;
  if (contact.phone) {
    const digits = contact.phone.replace(/\D/g, "");
    if (digits.length >= 5 && hl.includes(digits)) return true;
  }
  if (contact.location && hl === contact.location.toLowerCase()) return true;
  return false;
}

// ---- InfoHAS Pro template ----
// Matches the OUSSAMA EL FATIMI reference PDF exactly:
//   - Times New Roman throughout
//   - Top-left header: NAME in dark maroon (#660033), then headline + contact lines + DOB
//   - Blue rule (#0563C1) under header text
//   - Top-right: portrait photo frame ~54×81mm (2:3 ratio)
//   - Body: single column; PROFESSIONAL SUMMARY wraps left of the photo frame
//   - Section headers: UPPERCASE, blue, bold, with blue underline
//   - Sections in order: Summary → Core Competencies & Skills → Experience → Education → Languages
function InfohasProTemplate({ resume, accent }: { resume: ResumeData; accent: string }) {
  const config = useApp((s) => s.optimizerDirective);

  const L = {
    fontFamily: config?.fontFamily || "'Times New Roman', 'Georgia', 'Cambria', serif",
    bodyFontSizePt: config?.bodyFontSizePt ?? 10.5,
    lineHeight: config?.lineHeight ?? 1.2,
    marginTopMm: config?.marginTopMm ?? 6.35,
    marginBottomMm: config?.marginBottomMm ?? 6.35,
    marginLeftMm: config?.marginLeftMm ?? 8.89,
    marginRightMm: config?.marginRightMm ?? 8.89,
    nameSizePt: config?.nameSizePt ?? 14,
    sectionTitleSizePt: config?.sectionTitleSizePt ?? 12,
    nameColor: config?.nameColor || "#8B0000",
    sectionTitleColor: config?.sectionTitleColor || "#8B0000",
    bodyTextColor: config?.bodyTextColor || "#000000",
    sectionGapMm: config?.sectionGapMm ?? 3,
    bulletIndentMm: config?.bulletIndentMm ?? 6.4,
    contactSpacing: config?.contactSpacing ?? "stacked",
    bodyAlignment: config?.bodyAlignment ?? "justify",
    sectionAlignment: config?.sectionAlignment ?? {},
  };
  const alignFor = (section: string): "left" | "center" | "justify" => {
    const per = (L.sectionAlignment as Record<string, string> | undefined)?.[section];
    if (per === "left" || per === "center" || per === "justify") return per;
    return L.bodyAlignment ?? "justify";
  };


  const BLACK = L.bodyTextColor;

  return (
    <div
      className="relative"
      style={{
        fontFamily: L.fontFamily,
        fontSize: `${L.bodyFontSizePt}pt`,
        lineHeight: L.lineHeight,
        padding: `${L.marginTopMm}mm ${L.marginRightMm}mm ${L.marginBottomMm}mm ${L.marginLeftMm}mm`,
        minHeight: "297mm",
        color: BLACK,
      }}
    >
      {/* ============ HEADER ============ */}
      <header className="relative" style={{ paddingRight: resume.photoUrl ? "36mm" : 0, minHeight: resume.photoUrl ? "42mm" : "auto" }}>
        {/* Photo — top-right, 30x40mm. Only render if photoUrl exists (no placeholder per master layout). */}
        {resume.photoUrl && (
          <div
            style={{
              position: "absolute",
              top: 0,
              right: 0,
              width: "30mm",
              height: "40mm",
              border: "0.5pt solid #999",
              background: "transparent",
              overflow: "hidden",
              boxSizing: "border-box",
            }}
          >
            <img
              src={resume.photoUrl}
              alt={resume.name}
              style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: "center top" }}
            />
          </div>
        )}

        {/* Name — bold, uppercase */}
        <div
          style={{
            color: L.nameColor,
            fontWeight: 700,
            fontSize: `${L.nameSizePt}pt`,
            letterSpacing: "0.3pt",
            marginBottom: "0.5mm",
            lineHeight: 1.1,
            textTransform: "uppercase",
          }}
        >
          {(resume.name || "YOUR NAME").toUpperCase()}
        </div>

        {/* Headline */}
        {resume.headline && (
          <div style={{ fontSize: `${L.bodyFontSizePt}pt`, color: BLACK, marginBottom: "0.3mm", lineHeight: 1.2 }}>
            {resume.headline}
          </div>
        )}

        {/* Contact lines */}
        {L.contactSpacing === "single-line" ? (
          <div style={{ fontSize: `${L.bodyFontSizePt}pt`, color: BLACK, marginBottom: "0.3mm", lineHeight: 1.2 }}>
            {[
              resume.contact.location,
              resume.contact.phone,
              resume.contact.email,
              resume.dateOfBirth ? `DOB: ${resume.dateOfBirth}` : ""
            ].filter(Boolean).join(" | ")}
          </div>
        ) : (
          <>
            <div style={{ fontSize: `${L.bodyFontSizePt}pt`, color: BLACK, marginBottom: "0.3mm", lineHeight: 1.2 }}>
              {[resume.contact.location, resume.contact.phone].filter(Boolean).join(" | ")}
            </div>
            {resume.contact.email && (
              <div style={{ fontSize: `${L.bodyFontSizePt}pt`, color: BLACK, marginBottom: "0.3mm", lineHeight: 1.2 }}>
                {resume.contact.email}
              </div>
            )}
            {resume.dateOfBirth && (
              <div style={{ fontSize: `${L.bodyFontSizePt}pt`, color: BLACK, marginBottom: "0.3mm", lineHeight: 1.2 }}>
                Date Of Birth : {resume.dateOfBirth}
              </div>
            )}
          </>
        )}
      </header>

      {/* ============ BODY ============ */}
      <div style={{ marginTop: "3mm" }}>
        {/* PROFESSIONAL PROFILE (matching target format) */}
        {resume.summary && (
          <InfohasSection title="PROFESSIONAL PROFILE" titleColor={L.sectionTitleColor} titleSize={`${L.sectionTitleSizePt}pt`} gap={`${L.sectionGapMm}mm`}>
            <p style={{ margin: 0, textAlign: alignFor("professionalProfile"), color: BLACK }}>{resume.summary}</p>
          </InfohasSection>
        )}

        {/* PROFESSIONAL EXPERIENCE */}
        {resume.experience.length > 0 && (
          <InfohasSection title="PROFESSIONAL EXPERIENCE" titleColor={L.sectionTitleColor} titleSize={`${L.sectionTitleSizePt}pt`} gap={`${L.sectionGapMm}mm`}>
            <div style={{ display: "flex", flexDirection: "column", gap: "2mm" }}>
              {resume.experience.map((e) => (
                <div key={e.id}>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: "0.5mm", gap: "2mm" }}>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <span style={{ fontWeight: 700, color: BLACK }}>{e.title}</span>{" "}
                      <span style={{ color: BLACK }}>{e.company}</span>
                      {e.location && <span style={{ color: BLACK }}> | {e.location}</span>}
                    </div>
                    <span style={{ color: BLACK, whiteSpace: "nowrap", flexShrink: 0 }}>{fmtDateInfohas(e.startDate)} – {fmtDateInfohas(e.endDate)}</span>
                  </div>
                  <ul style={{ margin: 0, paddingLeft: `${L.bulletIndentMm}mm`, listStyleType: "•" }}>
                    {e.bullets.map((b, i) => (
                      <li key={i} style={{ marginBottom: "0.5mm", color: BLACK, textAlign: alignFor("professionalExperience") }}>{b}</li>
                    ))}
                  </ul>
                </div>
              ))}
            </div>
          </InfohasSection>
        )}

        {/* EDUCATION */}
        {resume.education.length > 0 && (
          <InfohasSection title="EDUCATION" titleColor={L.sectionTitleColor} titleSize={`${L.sectionTitleSizePt}pt`} gap={`${L.sectionGapMm}mm`}>
            <div style={{ display: "flex", flexDirection: "column", gap: "1.5mm" }}>
              {resume.education.map((ed) => (
                <div key={ed.id}>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: "0.5mm", gap: "2mm" }}>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <span style={{ fontWeight: 700, color: BLACK }}>{ed.degree}</span>
                      {ed.institution && <span style={{ color: BLACK }}> | {ed.institution}</span>}
                      {ed.location && <span style={{ color: BLACK }}> | {ed.location}</span>}
                    </div>
                    {(ed.startDate || ed.endDate) && (
                      <span style={{ color: BLACK, whiteSpace: "nowrap", flexShrink: 0 }}>
                        {fmtDateInfohas(ed.startDate)} – {fmtDateInfohas(ed.endDate)}
                      </span>
                    )}
                  </div>
                  {ed.highlights && ed.highlights.length > 0 && (() => {
                    // Parse highlights: split "Modules: X, Y, Z" into individual bullet items
                    const allBullets: string[] = [];
                    for (const h of ed.highlights) {
                      const cleaned = h.replace(/^Modules:\s*/i, "").trim();
                      if (cleaned.includes(",")) {
                        cleaned.split(",").map((s: string) => s.trim()).filter(Boolean).forEach((m: string) => allBullets.push(m));
                      } else if (cleaned) {
                        allBullets.push(cleaned);
                      }
                    }
                    if (allBullets.length === 0) return null;
                    return (
                      <ul style={{ margin: "0.5mm 0 0 0", paddingLeft: `${L.bulletIndentMm}mm`, listStyleType: "•" }}>
                        {allBullets.map((m: string, i: number) => (
                          <li key={i} style={{ color: BLACK }}>{m}</li>
                        ))}
                      </ul>
                    );
                  })()}
                </div>
              ))}
            </div>
          </InfohasSection>
        )}

        {/* KEY COMPETENCIES (moved after Education to match target format) */}
        {resume.skills.length > 0 && (
          <InfohasSection title="KEY COMPETENCIES" titleColor={L.sectionTitleColor} titleSize={`${L.sectionTitleSizePt}pt`} gap={`${L.sectionGapMm}mm`}>
            <ul style={{ margin: 0, paddingLeft: `${L.bulletIndentMm}mm`, listStyleType: "•" }}>
              {groupSkillsByCategory(resume.skills).map((g, i) => (
                <li key={i} style={{ marginBottom: "1mm", color: BLACK }}>
                  <span style={{ fontWeight: 700 }}>{g.category}:</span>{" "}
                  <span>{g.items.join(", ")}.</span>
                </li>
              ))}
            </ul>
          </InfohasSection>
        )}

        {/* LANGUAGES */}
        {resume.languages.length > 0 && (
          <InfohasSection title="LANGUAGES" titleColor={L.sectionTitleColor} titleSize={`${L.sectionTitleSizePt}pt`} gap={`${L.sectionGapMm}mm`}>
            <div style={{ color: BLACK }}>
              • {resume.languages.map((l) => l.name).join(", ")}
            </div>
          </InfohasSection>
        )}

        {/* DYNAMIC SECTIONS */}
        {(resume.dynamicSections || []).map((ds) => (
          <InfohasSection key={ds.id} title={ds.title} titleColor={L.sectionTitleColor} titleSize={`${L.sectionTitleSizePt}pt`} gap={`${L.sectionGapMm}mm`}>
            <div style={{ color: BLACK }}>
              {ds.content && <p style={{ margin: "0 0 1mm 0", textAlign: alignFor("dynamicSections") }}>{ds.content}</p>}
              {ds.bullets && ds.bullets.length > 0 && (
                <ul style={{ margin: 0, paddingLeft: `${L.bulletIndentMm}mm`, listStyleType: "•" }}>
                  {ds.bullets.map((b, i) => (
                    <li key={i} style={{ marginBottom: "0.5mm", textAlign: alignFor("dynamicSections") }}>{b}</li>
                  ))}
                </ul>
              )}
            </div>
          </InfohasSection>
        ))}

        {/* ADDITIONAL INFORMATION */}
        {resume.additionalInfo && (
          <InfohasSection title="ADDITIONAL INFORMATION" titleColor={L.sectionTitleColor} titleSize={`${L.sectionTitleSizePt}pt`} gap={`${L.sectionGapMm}mm`}>
            <div style={{ color: BLACK, whiteSpace: "pre-wrap", textAlign: alignFor("additionalInformation") }}>
              {resume.additionalInfo}
            </div>
          </InfohasSection>
        )}
      </div>
    </div>
  );
}

/** Infohas section header - per master layout:
 * 12pt BOLD UPPERCASE configured color, no underline, compact spacing. */
function InfohasSection({
  title,
  titleColor,
  titleSize,
  gap,
  children,
}: {
  title: string;
  titleColor: string;
  titleSize: string;
  gap: string;
  children: React.ReactNode;
}) {
  return (
    <section style={{ marginBottom: gap }}>
      <h2
        style={{
          color: titleColor,
          fontWeight: 700,
          fontSize: titleSize,
          letterSpacing: "0.3pt",
          margin: "0 0 1mm 0",
          paddingBottom: 0,
          borderBottom: "none",
          textTransform: "uppercase",
          lineHeight: 1.2,
        }}
      >
        {title}
      </h2>
      <div style={{ fontSize: "inherit", lineHeight: "inherit" }}>{children}</div>
    </section>
  );
}

function groupSkillsByCategory(skills: ResumeData["skills"]): { category: string; items: string[] }[] {
  const map = new Map<string, string[]>();
  for (const s of skills) {
    const cat = s.category || "General";
    if (!map.has(cat)) map.set(cat, []);
    map.get(cat)!.push(s.name);
  }
  return Array.from(map.entries()).map(([category, items]) => ({ category, items }));
}

function fmtDateInfohas(d?: string): string {
  if (!d) return "";
  if (/present/i.test(d)) return "Present";
  // "2024-05" → "May 2024"
  const m = d.match(/^(\d{4})-(\d{2})$/);
  if (m) {
    const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    return `${months[parseInt(m[2]) - 1] ?? m[2]} ${m[1]}`;
  }
  // "2024" alone
  if (/^\d{4}$/.test(d)) return d;
  return d;
}

function fmtDate(d?: string) {
  if (!d) return "";
  if (/present/i.test(d)) return "Present";
  const m = d.match(/^(\d{4})-(\d{2})$/);
  if (m) {
    const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    return `${months[parseInt(m[2]) - 1] ?? m[2]} ${m[1]}`;
  }
  return d;
}

function ATSProfessionalTemplate({
  resume,
  accent,
  showHeatmap = false,
  latestReport
}: {
  resume: ResumeData;
  accent: string;
  showHeatmap?: boolean;
  latestReport?: any;
}) {
  const renderHText = (textVal: any) => {
    const raw = safeRender(textVal);
    return renderHighlightedText(raw, showHeatmap, latestReport?.matchedKeywords || [], latestReport?.detectedCliches || []) as any;
  };

  // Suppress the headline when it merely duplicates contact fields
  // already shown in the contact row below (prevents triple-printing).
  const showHeadline =
    !!resume.headline &&
    !headlineIsDuplicateContact(resume.headline, resume.contact) &&
    !/[|]/.test(resume.headline); // also hide pipe-delimited inline contact strings
  return (
    <div className="p-[14mm] text-[10pt] leading-snug text-slate-800" style={{ fontFamily: "'Inter', 'Helvetica', sans-serif" }}>
      <header className="mb-3">
        <h1 className="text-[22pt] font-bold text-slate-900 leading-tight">{resume.name}</h1>
        {showHeadline && <div className="text-[11pt] mt-0.5" style={{ color: accent }}>{resume.headline}</div>}
        <div className="text-[8.5pt] text-slate-500 mt-1.5 flex flex-wrap gap-x-2 gap-y-0.5">
          {resume.contact.email && <span>{resume.contact.email}</span>}
          {resume.contact.phone && <span>• {resume.contact.phone}</span>}
          {resume.contact.location && <span>• {resume.contact.location}</span>}
          {resume.contact.linkedin && <span>• {resume.contact.linkedin}</span>}
          {resume.contact.github && <span>• {resume.contact.github}</span>}
          {resume.contact.website && <span>• {resume.contact.website}</span>}
        </div>
        <div className="mt-2 h-px" style={{ background: accent }} />
      </header>

      {resume.summary && (
        <Section title="PROFESSIONAL SUMMARY" accent={accent}>
          <p className="text-[9.5pt] text-slate-700">{renderHText(resume.summary)}</p>
        </Section>
      )}

      {resume.experience.length > 0 && (
        <Section title="PROFESSIONAL EXPERIENCE" accent={accent}>
          <div className="space-y-2">
            {resume.experience.map((e) => (
              <div key={e.id}>
                <div className="flex justify-between items-baseline gap-2">
                  <div className="font-semibold text-[10pt] text-slate-900 flex-1 min-w-0">
                    {e.title}{e.company && <span className="font-normal text-slate-700"> — {e.company}</span>}
                  </div>
                  <div className="text-[8.5pt] text-slate-500 italic shrink-0 whitespace-nowrap">{fmtDate(e.startDate)} – {fmtDate(e.endDate)}</div>
                </div>
                <ul className="mt-1 space-y-0.5">
                  {e.bullets.map((b, i) => (
                    <li key={i} className="text-[9.5pt] text-slate-700 pl-3 relative">
                      <span className="absolute left-0 top-2 w-1 h-1 rounded-full" style={{ background: accent }} />
                      {renderHText(b)}
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </div>
        </Section>
      )}

      {resume.education.length > 0 && (
        <Section title="EDUCATION" accent={accent}>
          <div className="space-y-1.5">
            {resume.education.map((ed) => (
              <div key={ed.id} className="flex justify-between items-baseline gap-2">
                <div className="flex-1 min-w-0">
                  <div className="font-semibold text-[10pt] text-slate-900 truncate">
                    {ed.degree}{ed.field && <span className="font-normal text-slate-700"> in {ed.field}</span>}
                  </div>
                  <div className="text-[9pt] text-slate-600 truncate">{ed.institution}</div>
                </div>
                <div className="text-[8.5pt] text-slate-500 italic shrink-0 whitespace-nowrap">{fmtDate(ed.startDate)} – {fmtDate(ed.endDate)}</div>
              </div>
            ))}
          </div>
        </Section>
      )}

      {resume.skills.length > 0 && (
        <Section title="SKILLS" accent={accent}>
          <div className="text-[9.5pt] text-slate-700 flex flex-wrap gap-x-2 gap-y-1">
            {resume.skills.map((s, i) => (
              <span key={s.id}>
                {renderHText(s.name)}{i < resume.skills.length - 1 && <span className="text-slate-400"> •</span>}
              </span>
            ))}
          </div>
        </Section>
      )}

      {resume.projects.length > 0 && (
        <Section title="PROJECTS" accent={accent}>
          <div className="space-y-1">
            {resume.projects.slice(0, 2).map((p) => (
              <div key={p.id}>
                <div className="font-semibold text-[10pt] text-slate-900">{p.name}</div>
                {p.description && <div className="text-[9pt] text-slate-600">{p.description}</div>}
              </div>
            ))}
          </div>
        </Section>
      )}

      {resume.certifications.length > 0 && (
        <Section title="CERTIFICATIONS" accent={accent}>
          <ul className="space-y-0.5">
            {resume.certifications.slice(0, 4).map((c) => (
              <li key={c.id} className="text-[9.5pt] text-slate-700 pl-3 relative">
