"use client";

// ResumeAI Pro — Local QR code renderer
//
// Generates QR codes IN THE BROWSER via the `qrcode` package. This replaces
// the previous external api.qrserver.com <img> integration: resume URLs (and
// historically, resume data embedded in those URLs) must never be sent to a
// third-party service just to draw a QR code.

import { useEffect, useState } from "react";

interface QrCodeProps {
  /** The payload to encode (usually a share URL). */
  text: string;
  /** Rendered image width/height in px (default 200). */
  size?: number;
  className?: string;
  /** Accessible label for the image. */
  alt?: string;
  /** When set, the QR is wrapped in an <a download> so it can be saved. */
  downloadName?: string;
}

export function QrCode({ text, size = 200, className, alt = "QR code", downloadName }: QrCodeProps) {
  const [dataUrl, setDataUrl] = useState<string | null>(null);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    let cancelled = false;
    setDataUrl(null);
    setFailed(false);
    if (!text) { setFailed(true); return; }
    // Lazy import keeps the QR encoder out of every chunk that mounts QrCode
    // consumers only conditionally — and out of SSR entirely.
    import("qrcode")
      .then((QR) =>
        QR.toDataURL(text, {
          width: size,
          margin: 1,
          errorCorrectionLevel: "M",
          color: { dark: "#111827", light: "#FFFFFF" },
        }),
      )
      .then((url) => { if (!cancelled) setDataUrl(url); })
      .catch(() => { if (!cancelled) setFailed(true); });
    return () => { cancelled = true; };
  }, [text, size]);

  if (failed) {
    return (
      <div
        className={`flex items-center justify-center rounded-md border border-dashed border-border text-[10px] text-muted-foreground ${className || ""}`}
        style={{ width: size, height: size }}
      >
        QR unavailable
      </div>
    );
  }

  if (!dataUrl) {
    return (
      <div
        className={`flex items-center justify-center rounded-md border border-border bg-muted/40 animate-pulse ${className || ""}`}
        style={{ width: size, height: size }}
      />
    );
  }

  const img = <img src={dataUrl} alt={alt} width={size} height={size} className={className} />;
  if (downloadName) {
    return (
      <a href={dataUrl} download={downloadName} title="Click to download the QR code" className="inline-block">
        {img}
      </a>
    );
  }
  return img;
}

src/components/shared/RegionalNormsPanel:
"use client";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge, Icon } from "@/components/shared";
import type { ContactInfo, ResumeData, ResumeRegion } from "@/lib/types";
import {
  REGION_NORMS,
  REGION_OPTIONS,
  computeRegionalNormReport,
  buildRegionalFixPatch,
  getResumeRegion,
  type RegionalFieldNorm,
  type RegionalNormIssue,
} from "@/lib/regional-norms";

// ─── Props ───────────────────────────────────────────────────────────────────

interface RegionalNormsPanelProps {
  resume: ResumeData;
  /** Builder's patch fn — merges a Partial<ResumeData> into the resume. */
  onPatch: (p: Partial<ResumeData>) => void;
  /** full = Basics tab (selector + inputs + fixes + advice); compact = ATS-audit strip. */
  variant?: "full" | "compact";
  /** Compact mode CTA — jumps to the Basics tab when a region must be set / fields added. */
  onOpenBasics?: () => void;
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

function scoreTier(score: number): { label: string; text: string; bar: string } {
  if (score >= 85) return { label: "Compliant", text: "text-emerald-600 dark:text-emerald-400", bar: "bg-emerald-500" };
  if (score >= 60) return { label: "Needs Work", text: "text-amber-600 dark:text-amber-400", bar: "bg-amber-500" };
  return { label: "At Risk", text: "text-red-600 dark:text-red-400", bar: "bg-red-500" };
}

const STANCE_BADGE: Record<RegionalFieldNorm["stance"], { label: string; cls: string }> = {
  expected: { label: "Expected", cls: "border-emerald-200 bg-emerald-50/60 text-emerald-700 dark:border-emerald-500/30 dark:bg-emerald-500/10 dark:text-emerald-300" },
  optional: { label: "Optional", cls: "border-border bg-secondary/50 text-secondary-foreground" },
  discouraged: { label: "Discouraged", cls: "border-amber-200 bg-amber-50/60 text-amber-700 dark:border-amber-500/30 dark:bg-amber-500/10 dark:text-amber-300" },
  avoid: { label: "Avoid", cls: "border-red-200 bg-red-50/60 text-red-700 dark:border-red-500/30 dark:bg-red-500/10 dark:text-red-300" },
};

// ─── Component ───────────────────────────────────────────────────────────────

export function RegionalNormsPanel({ resume, onPatch, variant = "full", onOpenBasics }: RegionalNormsPanelProps) {
  const region = getResumeRegion(resume);
  const report = computeRegionalNormReport(resume);

  const setRegion = (value: string) => {
    const contact = { ...(resume.contact || {}) } as ContactInfo;
    if (value) {
      contact.region = value as ResumeRegion;
    } else {
      delete contact.region;
    }
    onPatch({ contact });
  };

  const applyFix = (issue: RegionalNormIssue) => {
    const patch = buildRegionalFixPatch(resume, issue);
    if (patch) onPatch(patch);
  };

  const setPersonalDetail = (label: string, value: string) => {
    const contact = (resume.contact || {}) as ContactInfo;
    const pd = { ...(contact.personalDetails || {}) };
    pd[label] = value;
    onPatch({ contact: { ...contact, personalDetails: pd } });
  };

  const pdValue = (label: string): string => {
    const pd = (resume.contact as ContactInfo | undefined)?.personalDetails;
    if (!pd) return "";
    const hit = Object.keys(pd).find((k) => k.trim().toLowerCase() === label.trim().toLowerCase());
    return hit ? pd[hit] ?? "" : "";
  };

  // ── Region selector (full variant only) ────────────────────────────────────
  const selector = (
    <select
      value={region ?? ""}
      onChange={(e) => setRegion(e.target.value)}
      className="w-full h-8 px-2 rounded border border-input bg-background text-xs"
      aria-label="Target market / regional format"
    >
      {REGION_OPTIONS.map((o) => (
        <option key={o.value} value={o.value}>{o.label}</option>
      ))}
    </select>
  );

  // ── Dormant state ──────────────────────────────────────────────────────────
  if (!region) {
    if (variant === "compact") {
      return (
        <div className="flex items-center justify-between gap-2 rounded-lg border border-dashed border-border bg-secondary/20 px-3 py-2">
          <span className="text-[10px] text-muted-foreground">
            <Icon name="Globe" className="w-3 h-3 inline mr-1 -mt-0.5" />
            No target market set — regional format checks are off.
          </span>
          {onOpenBasics && (
            <Button size="sm" variant="outline" className="h-6 text-[10px] shrink-0" onClick={onOpenBasics}>
              Set market
            </Button>
          )}
        </div>
      );
    }
    return (
      <div className="rounded-xl border border-border p-3 space-y-2 bg-secondary/10">
        <div className="flex items-center justify-between">
          <h4 className="text-xs font-semibold flex items-center gap-1.5">
            <Icon name="Globe" className="w-3.5 h-3.5 text-brand" /> Regional format
          </h4>
        </div>
        {selector}
        <p className="text-[10px] text-muted-foreground leading-relaxed">
          Pick a target market to enable region-aware personal-data checks — a photo is standard on Gulf
          CVs but a liability in North America; nationality and visa status are Gulf screening fields.
        </p>
      </div>
    );
  }

  const tier = scoreTier(report.score);
  const norms = REGION_NORMS[region];
  const removes = report.issues.filter((i) => i.kind === "remove");
  const adds = report.issues.filter((i) => i.kind === "add");

  // ── Issue row (shared by both variants) ────────────────────────────────────
  const renderIssue = (issue: RegionalNormIssue) => (
    <div key={issue.id} className="flex items-start justify-between gap-2 rounded-lg border border-border bg-background px-2.5 py-2">
      <div className="min-w-0">
        <div className="flex items-center gap-1.5">
          <Icon name={issue.kind === "remove" ? "XCircle" : "PlusCircle"} className={`w-3.5 h-3.5 shrink-0 ${issue.severity === "warning" ? "text-amber-500" : "text-blue-500"}`} />
          <span className="text-[11px] font-semibold text-foreground">
            {issue.kind === "remove" ? `Remove ${issue.label.toLowerCase()}` : `Add ${issue.label.toLowerCase()}`}
          </span>
        </div>
        <p className="text-[10px] text-muted-foreground leading-relaxed mt-0.5">{issue.message}</p>
      </div>
      {issue.kind === "remove" ? (
        <Button size="sm" variant="outline" className="h-6 text-[10px] shrink-0" onClick={() => applyFix(issue)}>
          Remove
        </Button>
      ) : (
        onOpenBasics && variant === "compact" && (
          <Button size="sm" variant="outline" className="h-6 text-[10px] shrink-0" onClick={onOpenBasics}>
            Add
          </Button>
        )
      )}
    </div>
  );

  // ── Compact strip (ATS Audit tab) ──────────────────────────────────────────
  if (variant === "compact") {
    return (
      <div className="rounded-lg border border-border bg-secondary/10 px-3 py-2 space-y-2">
        <div className="flex items-center justify-between">
          <span className="text-xs font-bold text-foreground flex items-center gap-1.5">
            <Icon name="Globe" className="w-3.5 h-3.5 text-brand" /> Regional format — {norms.label}
          </span>
          <Badge variant={report.score >= 85 ? "success" : report.score >= 60 ? "warning" : "danger"} className="text-[10px] font-mono">
            {report.score}/100
          </Badge>
        </div>
        <div className="h-1 rounded-full bg-secondary overflow-hidden">
          <div className={`h-full rounded-full transition-all duration-500 ${tier.bar}`} style={{ width: `${report.score}%` }} />
        </div>
        {report.issues.length === 0 ? (
          <p className="text-[10px] text-emerald-600 dark:text-emerald-400 flex items-center gap-1">
            <Icon name="CheckCircle2" className="w-3.5 h-3.5" /> Matches {norms.label} conventions.
          </p>
        ) : (
          <div className="space-y-1.5">{report.issues.map(renderIssue)}</div>
        )}
      </div>
    );
  }

  // ── Full panel (Basics tab) ────────────────────────────────────────────────
  return (
    <div className="rounded-xl border border-border p-3 space-y-3 bg-secondary/10">
      <div className="flex items-center justify-between">
        <h4 className="text-xs font-semibold flex items-center gap-1.5">
          <Icon name="Globe" className="w-3.5 h-3.5 text-brand" /> Regional format
        </h4>
        <span className="text-[10px] text-muted-foreground">{norms.tagline}</span>
      </div>
      {selector}

      {/* Compliance header */}
      <div className="flex items-center gap-2">
        <Badge variant={report.score >= 85 ? "success" : report.score >= 60 ? "warning" : "danger"} className="text-[10px] font-mono shrink-0">
          {report.score}/100
        </Badge>
        <span className={`text-[11px] font-semibold ${tier.text}`}>{tier.label}</span>
        <span className="text-[10px] text-muted-foreground">
          {report.issues.length === 0 ? "matches regional conventions" : `${report.issues.length} fixable issue${report.issues.length > 1 ? "s" : ""}`}
        </span>
      </div>
      <div className="h-1 rounded-full bg-secondary overflow-hidden">
        <div className={`h-full rounded-full transition-all duration-500 ${tier.bar}`} style={{ width: `${report.score}%` }} />
      </div>

      {/* Issues + quick fixes */}
      {removes.length > 0 && <div className="space-y-1.5">{removes.map(renderIssue)}</div>}
      {adds.length > 0 && <div className="space-y-1.5">{adds.map(renderIssue)}</div>}

      {/* Field inputs — every norm field of the region gets an editor */}
      <div className="space-y-2 pt-1">
        <div className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wide">Personal data for this market</div>
        {report.fields.map((f) => {
          const stance = STANCE_BADGE[f.stance];
          if (f.key === "photo") {
            const hasPhoto = !!resume.photoUrl?.trim();
            return (
              <div key={f.key} className="flex items-center justify-between gap-2">
                <div className="min-w-0">
                  <span className="text-[11px] font-medium">{f.label}</span>{" "}
                  <span className={`text-[9px] px-1 py-0.5 rounded border ${stance.cls}`}>{stance.label}</span>
                  <p className="text-[10px] text-muted-foreground leading-snug">{hasPhoto ? "Photo attached (set it in Design)." : "No photo attached."}</p>
                </div>
                {hasPhoto && f.stance !== "expected" && f.stance !== "optional" && (
                  <Button size="sm" variant="outline" className="h-6 text-[10px] shrink-0" onClick={() => onPatch({ photoUrl: "" })}>
                    Remove
                  </Button>
                )}
              </div>
            );
          }
          if (f.key === "dateOfBirth") {
            return (
              <div key={f.key}>
                <div className="flex items-center gap-1.5 mb-1">
                  <span className="text-[11px] font-medium">{f.label}</span>
                  <span className={`text-[9px] px-1 py-0.5 rounded border ${stance.cls}`}>{stance.label}</span>
                </div>
                <Input
                  value={resume.dateOfBirth ?? ""}
                  onChange={(e) => onPatch({ dateOfBirth: e.target.value })}
                  placeholder="YYYY-MM-DD"
                  className="h-7 text-xs"
                />
              </div>
            );
          }
          return (
            <div key={f.key}>
              <div className="flex items-center gap-1.5 mb-1">
                <span className="text-[11px] font-medium">{f.label}</span>
                <span className={`text-[9px] px-1 py-0.5 rounded border ${stance.cls}`}>{stance.label}</span>
              </div>
              <Input
                value={pdValue(f.label)}
                onChange={(e) => setPersonalDetail(f.label, e.target.value)}
                placeholder={f.key === "visaStatus" ? "e.g. UAE residence visa — transferable" : f.key === "nationality" ? "e.g. Moroccan" : ""}
                className="h-7 text-xs"
              />
            </div>
          );
        })}
      </div>

      {/* Market advice */}
      <div className="rounded-lg bg-background border border-border p-2.5 space-y-1">
        <div className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wide">{norms.label} conventions</div>
        <ul className="space-y-0.5">
          {report.advice.map((a) => (
            <li key={a} className="text-[10px] text-muted-foreground flex items-start gap-1.5">
              <Icon name="Check" className="w-3 h-3 text-brand shrink-0 mt-0.5" /> {a}
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

src/components/shared/SmartTextarea.tsx:
"use client";

import { useState, useRef, useCallback, useEffect } from "react";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";
import { Badge, Icon } from "@/components/shared";
import { toast } from "sonner";
import type { ResumeData } from "@/lib/types";

interface SmartTextareaProps {
  value: string;
  onChange: (value: string) => void;
  section: "summary" | "bullet" | "skill" | "education" | "language";
  placeholder?: string;
  className?: string;
  resume?: ResumeData | null;
  jobDescriptionText?: string;
  context?: string;
  rows?: number;
  disabled?: boolean;
  onFocus?: () => void;
}

type SuggestStatus = "idle" | "loading" | "error";

function sectionLabel(s: string) {
  const m: Record<string,string> = { summary:"Summary", bullet:"Bullet", skill:"Skill", education:"Education", language:"Language" };
  return m[s]||s;
}

/**
 * Build a context snippet for AI prompts — resume name, current role, JD keywords.
 */
function buildContext(resume?: ResumeData | null, jdText?: string): string {
  const parts: string[] = [];
  if (resume?.name) parts.push(`Candidate: ${resume.name}`);
  if (resume?.headline) parts.push(`Target role: ${resume.headline}`);
  if (resume?.summary) parts.push(`Current summary (context): ${resume.summary.slice(0, 200)}`);
  if (resume?.experience?.[0]) {
    const e = resume.experience[0];
    parts.push(`Recent role: ${e.title} at ${e.company}`);
    if (e.bullets.length > 0) parts.push(`Existing bullets: ${e.bullets.slice(0, 3).join(" | ")}`);
  }
  if (jdText) parts.push(`Job description keywords: ${jdText.slice(0, 300)}`);
  return parts.join("\n");
}

export function SmartTextarea({ value, onChange, section, placeholder, className, resume, jobDescriptionText, context, rows=3, disabled, onFocus }: SmartTextareaProps) {
  const [suggestion, setSuggestion] = useState("");
  const [variants, setVariants] = useState<string[]>([]);
  const [currentVariant, setCurrentVariant] = useState(0);
  const [status, setStatus] = useState<SuggestStatus>("idle");
  const [showPopover, setShowPopover] = useState(false);
  const [selection, setSelection] = useState<{ start: number; end: number; text: string; top: number; left: number } | null>(null);
  const debRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const textareaRef = useRef<HTMLDivElement>(null);

  const handleSelectionChange = (e: React.SyntheticEvent<HTMLTextAreaElement>) => {
    const target = e.currentTarget;
    const start = target.selectionStart;
    const end = target.selectionEnd;
    if (start !== end) {
      const text = target.value.substring(start, end).trim();
      if (text.length > 0) {
        setSelection({ start, end, text, top: -45, left: Math.max(10, target.clientWidth / 2 - 110) });
        return;
      }
    }
    setSelection(null);
  };

  const optimizeSelection = async (action: "rewrite" | "star") => {
    if (!selection) return;
    setStatus("loading");
    const text = selection.text;
    
    let prompt = "";
    if (action === "rewrite") {
      prompt = (ctxMemo ? `Context:\n${ctxMemo}\n\n` : "") +
        `Rewrite this selected phrase to make it highly professional, active, and ATS-friendly: "${text}". Keep same length. Return ONLY the rewritten phrase.`;
    } else {
      prompt = (ctxMemo ? `Context:\n${ctxMemo}\n\n` : "") +
        `Upgrade this selected resume bullet point to follow the STAR methodology, injecting a strong action verb and an estimated quantitative metric (e.g. percentages, values, time saved): "${text}". Return ONLY the rewritten bullet.`;
    }
    
    const optimized = await callAI(prompt);
    if (optimized) {
      const before = value.substring(0, selection.start);
      const after = value.substring(selection.end);
      onChange(before + optimized + after);
      toast.success("Selection updated successfully!");
    }
    setSelection(null);
    setStatus("idle");
  };

  // Build full context for AI prompts
  const ctxMemo = buildContext(resume, jobDescriptionText);

  const callAI = async (prompt: string) => {
    try {
      // Route through the universal recorded pipeline (no direct ProviderRouter
      // bypass) so Smart Textarea executions are observed like every other feature.
      const { recordAI } = await import("@/lib/ai/flight-recorder");
      const r = await recordAI(
        {
          systemPrompt: "You are a professional resume writer. Return ONLY the requested text.",
          userPrompt: prompt,
          maxTokens: 200,
          temperature: 0.7,
        },
        { scope: "resume-copilot", feature: "Smart Textarea", module: "src.components.shared.SmartTextarea" }
      );
      return (r.text || "").replace(/^["']|["']$/g, "").trim();
    } catch { return ""; }
  };

  /**
   * Fetch multiple suggestion variants from the AI.
   */
  const fetchVariants = useCallback(async (text: string, count = 3): Promise<string[]> => {
    const prompt = ctxMemo
      ? `Context:\n${ctxMemo}\n\n`
      : "";
    if (section === "summary") {
      return callAI(
        prompt + `I need to complete this resume summary: "${text}". ` +
        `Suggest ${count} different completions (15-25 words each) that are impactful and keyword-rich. ` +
        `Return as a JSON array of strings, NO markdown, NO numbering.`
      ).then(r => {
        try { const arr = JSON.parse(r); return Array.isArray(arr) ? arr.slice(0, count) : [r]; }
        catch { return r ? [r] : []; }
      });
    }
    if (section === "bullet") {
      return callAI(
        prompt + `I need to complete this resume bullet point: "${text}". ` +
        `Suggest ${count} different completions (10-20 words each) starting with an action verb. ` +
        `Return as a JSON array of strings, NO markdown, NO numbering.`
      ).then(r => {
        try { const arr = JSON.parse(r); return Array.isArray(arr) ? arr.slice(0, count) : [r]; }
        catch { return r ? [r] : []; }
      });
    }
    return callAI(
      `Complete this ${section} entry: "${text}". ` +
      `Suggest ${count} short completions. ` +
      `Return as a JSON array of strings, NO markdown.`
    ).then(r => {
      try { const arr = JSON.parse(r); return Array.isArray(arr) ? arr.slice(0, count) : [r]; }
      catch { return r ? [r] : []; }
    });
  }, [section, ctxMemo]);

  /**
   * Auto-complete: debounced, context-aware, multi-variant.
   */
  const onType = useCallback((text: string) => {
    onChange(text);
    setSuggestion("");
    setVariants([]);
    setShowPopover(false);
    if (debRef.current) clearTimeout(debRef.current);
    if (text.length < 15) return;
    debRef.current = setTimeout(async () => {
      setStatus("loading");
      const sug = await callAI(
        (ctxMemo ? `Context:\n${ctxMemo}\n\n` : "") +
        (section === "summary"
          ? `Complete this resume summary: "${text}". Add 10-20 more words. Return ONLY the completion.`
          : section === "bullet"
          ? `Complete this achievement bullet: "${text}". Add an action verb continuation with a metric. Return ONLY the completion.`
          : `Suggest completion for: "${text}". Return ONLY the completion.`)
      );
      if (sug && sug !== text) {
        setSuggestion(sug);
        setStatus("idle");
      } else {
        setStatus("idle");
      }
    }, 1200);
  }, [onChange, section, ctxMemo]);

  const acceptSug = () => {
    if (suggestion) {
      onChange(suggestion);
      setSuggestion("");
      setVariants([]);
      setShowPopover(false);
    }
  };

  const acceptVariant = (v: string) => {
    onChange(v);
    setSuggestion("");
    setVariants([]);
    setShowPopover(false);
  };

  /**
   * Generate new content from scratch (context-aware).
   */
  const onGenerate = async () => {
    setStatus("loading");
    const ctx = ctxMemo || (resume ? `Name: ${resume.name||''}. Role: ${resume.experience?.[0]?.title||''}` : '');
    if (section === "summary") {
      const gen = await callAI(
        (ctx ? `Context:\n${ctx}\n\n` : "") +
        `Generate a professional resume summary (60-80 words) for the candidate. ` +
        (jobDescriptionText ? `Naturally weave in relevant keywords and skills from the target job description. ` : "") +
        `Highlight years of experience, key skills, and measurable outcomes. Return ONLY the summary.`
      );
      if (gen) { onChange(gen); toast.success("Summary generated"); }
    } else if (section === "bullet") {
      const gen = await callAI(
        (ctx ? `Context:\n${ctx}\n\n` : "") +
        `Generate an achievement bullet for: "${context||''}". ` +
        (jobDescriptionText ? `Naturally weave in relevant keywords and skills from the target job description. ` : "") +
        `Start with a strong action verb, include a specific metric, 10-20 words. Return ONLY the bullet.`
      );
      if (gen) { onChange(gen); toast.success("Bullet generated"); }
    } else {
      const gen = await callAI(
        `Generate content for ${section} section. ${ctx}. ` +
        (jobDescriptionText ? `Make it highly relevant to the target job description. ` : "") +
        `Return ONLY the text.`
      );
      if (gen) { onChange(gen); toast.success(`${sectionLabel(section)} generated`); }
    }
    setStatus("idle");
  };

  /**
   * Regenerate with a fresh AI call (context-aware).
   */
  const onRegen = async () => {
    if (!value) return;
    setStatus("loading");
    const gen = await callAI(
      (ctxMemo ? `Context:\n${ctxMemo}\n\n` : "") +
      `Rewrite this to be more impactful and ATS-friendly: "${value}". ` +
      (jobDescriptionText ? `Naturally weave in relevant keywords and skills from the target job description. ` : "") +
      `Keep same length. Use active voice and specific metrics. Return ONLY the rewritten text.`
    );
    if (gen) { onChange(gen); toast.success(`${sectionLabel(section)} regenerated`); }
    setStatus("idle");
  };

  /**
   * Fix grammar, spelling, and autocomplete incomplete phrases.
   */
  const onFixAndPolish = async () => {
    if (!value) return;
    setStatus("loading");
    const gen = await callAI(
      (ctxMemo ? `Context:\n${ctxMemo}\n\n` : "") +
      `Fix any grammar, spelling, or sentence structure issues in this text: "${value}". ` +
      `If the text is incomplete or written as a shorthand note, complete it into a professional, high-impact resume statement. ` +
      (jobDescriptionText ? `Naturally weave in relevant keywords and skills from the target job description. ` : "") +
      `Ensure it starts with a strong action verb (if it is a bullet point) and has a clean, professional tone. Return ONLY the polished text.`
    );
    if (gen) {
      onChange(gen);
      toast.success("Phrase polished and completed!");
    }
    setStatus("idle");
  };

  /**
   * Show suggestion popover with variants.
   */
  const onShowSuggestions = async () => {
    if (!value || value.length < 10) {
      toast.info("Type at least 10 characters for suggestions");
      return;
    }
    if (showPopover) { setShowPopover(false); return; }
    setStatus("loading");
    const vs = await fetchVariants(value);
    if (vs.length > 0) {
      setVariants(vs);
      setCurrentVariant(0);
      setShowPopover(true);
      setStatus("idle");
    } else {
      setStatus("idle");
      toast.error("No suggestions generated");
    }
  };

  // Keyboard handler
  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    // Tab → accept auto-complete suggestion
    if (e.key === "Tab" && suggestion) {
      e.preventDefault();
      acceptSug();
      return;
    }
    // Escape → dismiss popover/suggestion
    if (e.key === "Escape") {
      if (showPopover) { setShowPopover(false); return; }
      if (suggestion) { setSuggestion(""); return; }
    }
    // Ctrl+Space → show suggestions popover
    if (e.key === " " && (e.ctrlKey || e.metaKey)) {
      e.preventDefault();
      onShowSuggestions();
      return;
    }
  };

  // Close popover on outside click
  useEffect(() => {
    if (!showPopover) return;
    const handler = (e: MouseEvent) => {
      if (textareaRef.current && !textareaRef.current.contains(e.target as Node)) {
        // Check if click was inside popover
        const popover = document.getElementById("smart-textarea-popover");
        if (popover && !popover.contains(e.target as Node)) {
          setShowPopover(false);
        }
      }
    };
    // Delay to avoid immediate close from trigger button
    const timer = setTimeout(() => document.addEventListener("mousedown", handler), 0);
    return () => {
      clearTimeout(timer);
      document.removeEventListener("mousedown", handler);
    };
  }, [showPopover]);

  return (
    <div className="relative group" ref={textareaRef}>
      <Textarea
        value={value}
        onChange={e => onType(e.target.value)}
        onKeyDown={handleKeyDown}
        onFocus={onFocus}
        onMouseUp={handleSelectionChange}
        onKeyUp={handleSelectionChange}
        onSelect={handleSelectionChange}
        placeholder={placeholder || ''}
        rows={rows}
        disabled={disabled}
        className={className}
      />

      {selection && (
        <div
          className="absolute z-[60] flex items-center gap-1.5 p-1.5 rounded-lg border border-brand/20 bg-card/90 backdrop-blur-md shadow-lg animate-in fade-in slide-in-from-bottom-2 duration-200"
          style={{
            top: `${selection.top}px`,
            left: `${selection.left}px`,
          }}
        >
          <button
            onClick={() => optimizeSelection("rewrite")}
            className="text-[10px] px-2.5 py-1 rounded bg-secondary hover:bg-brand hover:text-white font-semibold transition flex items-center gap-1"
          >
            <Icon name="Sparkles" className="w-3.5 h-3.5 text-brand hover:text-inherit" />
            Rewrite Selected
          </button>
          <button
            onClick={() => optimizeSelection("star")}
            className="text-[10px] px-2.5 py-1 rounded bg-secondary hover:bg-brand hover:text-white font-semibold transition flex items-center gap-1"
          >
            <Icon name="TrendingUp" className="w-3.5 h-3.5 text-emerald-500 hover:text-inherit" />
            STAR Metric
          </button>
          <button
            onClick={() => setSelection(null)}
            className="p-1 rounded hover:bg-destructive/10 text-muted-foreground hover:text-destructive"
          >
            <Icon name="X" className="w-3.5 h-3.5" />
          </button>
        </div>
      )}

      {/* Auto-complete suggestion hint (inline, below text) */}
      {suggestion && status === "idle" && !showPopover && (
        <div
          className="absolute bottom-2 left-3 right-12 flex items-center gap-2 cursor-pointer z-10"
          onClick={acceptSug}
          role="button"
          tabIndex={0}
          onKeyDown={e => { if (e.key === "Enter") acceptSug(); }}
        >
          <span className="text-muted-foreground/50 text-sm truncate italic">{suggestion}</span>
          <Badge variant="outline" className="text-[9px] shrink-0">Tab ↵</Badge>
        </div>
      )}

      {/* Suggestion popover with multiple variants */}
      {showPopover && variants.length > 0 && (
        <div
          id="smart-textarea-popover"
          className="absolute bottom-full left-0 right-0 mb-1 z-50 rounded-lg border border-border bg-popover shadow-lg overflow-hidden"
        >
          <div className="p-2 space-y-1">
            <div className="flex items-center justify-between px-1 mb-1">
              <span className="text-[9px] uppercase text-muted-foreground font-semibold">
                Suggestions ({currentVariant + 1}/{variants.length})
              </span>
              <div className="flex gap-1">
                <Button
                  variant="ghost"
                  size="sm"
                  className="h-5 w-5 p-0"
                  disabled={currentVariant === 0}
                  onClick={() => setCurrentVariant(v => Math.max(0, v - 1))}
                >
                  <Icon name="ChevronLeft" className="w-3 h-3" />
                </Button>
                <Button
                  variant="ghost"
                  size="sm"
                  className="h-5 w-5 p-0"
                  disabled={currentVariant === variants.length - 1}
                  onClick={() => setCurrentVariant(v => Math.min(variants.length - 1, v + 1))}
                >
                  <Icon name="ChevronRight" className="w-3 h-3" />
                </Button>
              </div>
            </div>
            <div className="rounded-md bg-muted/50 p-2 text-xs text-foreground/90 leading-relaxed">
              {variants[currentVariant]}
            </div>
            <div className="flex items-center justify-end gap-1.5 pt-1">
              <Button
                variant="ghost"
                size="sm"
                className="h-6 text-[10px]"
                onClick={() => setShowPopover(false)}
              >
                Dismiss
              </Button>
              <Button
                variant="default"
                size="sm"
                className="h-6 text-[10px] gap-1"
                onClick={() => acceptVariant(variants[currentVariant])}
              >
                <Icon name="Check" className="w-3 h-3" /> Accept
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* Action buttons (top-right corner) */}
      <div className="absolute top-1 right-1 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
        {/* Smart suggestions trigger */}
        {value && value.length >= 10 && (
          <Button
            variant="ghost"
            size="sm"
            onClick={onShowSuggestions}
            disabled={status === "loading"}
            className="h-6 px-1.5 text-[10px] gap-1"
            title="Suggestions (Ctrl+Space)"
          >
            <Icon name="Lightbulb" className="w-3 h-3" />
          </Button>
        )}
        {/* Generate (when empty) */}
        {!value && (
          <Button
            variant="ghost"
            size="sm"
            onClick={onGenerate}
            disabled={status === "loading"}
            className="h-6 px-2 text-[10px] gap-1 text-brand"
            title="AI generate"
          >
            {status === "loading"
              ? <Icon name="Loader2" className="w-3 h-3 animate-spin" />
              : <Icon name="Sparkles" className="w-3 h-3" />
            }
            Generate
          </Button>
        )}
        {/* Fix & Polish (when has value) */}
        {value && (
          <Button
            variant="ghost"
            size="sm"
            onClick={onFixAndPolish}
            disabled={status === "loading"}
            className="h-6 px-1.5 text-[10px] gap-1 text-emerald-600 hover:text-emerald-700 hover:bg-emerald-50 dark:hover:bg-emerald-950/20"
            title="Fix grammar, spelling & autocomplete phrase"
          >
            {status === "loading"
              ? <Icon name="Loader2" className="w-3 h-3 animate-spin" />
              : <Icon name="CheckCheck" className="w-3 h-3" />
            }
          </Button>
        )}
        {/* Regenerate (when has value) */}
        {value && (
          <Button
            variant="ghost"
            size="sm"
            onClick={onRegen}
            disabled={status === "loading"}
            className="h-6 px-1.5 text-[10px] gap-1"
            title="Regenerate"
          >
            {status === "loading"
              ? <Icon name="Loader2" className="w-3 h-3 animate-spin" />
              : <Icon name="RefreshCw" className="w-3 h-3" />
            }
          </Button>
        )}
      </div>
    </div>
  );
}

