"use client";

import { useState, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Card, CardContent, CardHeader, CardTitle, CardFooter } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge, Icon } from "@/components/shared";
import { type SectionSpelling, scanResume, totalMisspelled } from "@/lib/spellchecker";
import type { ResumeData } from "@/lib/types";

interface Props {
  resume: ResumeData;
  onFixWord?: (path: string, oldWord: string, newWord: string) => void;
  open: boolean;
  onToggle: () => void;
}

/**
 * SpellCheckPanel — scans the entire resume for spelling mistakes and
 * presents them in a searchable, actionable panel. Each issue shows the
 * misspelled word in context with clickable suggestions.
 */
export function SpellCheckPanel({ resume, onFixWord, open, onToggle }: Props) {
  const [sections] = useState<SectionSpelling[]>(() => scanResume(resume));
  const total = totalMisspelled(sections);

  if (!open) {
    // Just the badge button
    return (
      <Button
        variant={total > 0 ? "outline" : "ghost"}
        size="sm"
        onClick={onToggle}
        className={`gap-1.5 h-8 relative ${total > 0 ? "border-amber-400 text-amber-600 hover:bg-amber-50" : ""}`}
        title={total > 0 ? `${total} spelling issue${total > 1 ? "s" : ""} found` : "No spelling issues found"}
      >
        <Icon name="SpellCheck2" className="w-3.5 h-3.5" />
        <span className="hidden sm:inline">Spelling</span>
        {total > 0 && (
          <span className="inline-flex items-center justify-center w-5 h-5 rounded-full bg-amber-400 text-white text-[10px] font-bold leading-none">
            {total}
          </span>
        )}
        {total === 0 && (
          <Icon name="Check" className="w-3 h-3 text-emerald-500" />
        )}
      </Button>
    );
  }

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0, height: 0 }}
        animate={{ opacity: 1, height: "auto" }}
        exit={{ opacity: 0, height: 0 }}
        className="overflow-hidden"
      >
        <Card className="border-amber-200 bg-amber-50/30">
          <CardHeader className="pb-2 flex flex-row items-center justify-between gap-2">
            <div>
              <CardTitle className="text-sm font-semibold flex items-center gap-2">
                <Icon name="SpellCheck2" className="w-4 h-4 text-amber-600" />
                Spell Check
                {total > 0 ? (
                  <Badge variant="danger" className="text-[10px]">
                    {total} issue{total > 1 ? "s" : ""}
                  </Badge>
                ) : (
                  <Badge variant="default" className="text-[10px] bg-emerald-500">
                    All clear
                  </Badge>
                )}
              </CardTitle>
              {total > 0 && (
                <p className="text-xs text-muted-foreground mt-0.5">
                  Click a suggestion to replace the word. Re-run after editing.
                </p>
              )}
            </div>
            <div className="flex gap-1">
              <Button variant="ghost" size="sm" className="h-7 text-xs" onClick={() => {
                // Re-scan (force re-mount by toggling)
                onToggle();
                setTimeout(() => onToggle(), 50);
              }}>
                <Icon name="RefreshCw" className="w-3 h-3 mr-1" /> Re-scan
              </Button>
              <Button variant="ghost" size="sm" className="h-7 text-xs" onClick={onToggle}>
                <Icon name="X" className="w-3 h-3" />
              </Button>
            </div>
          </CardHeader>
          <CardContent className="pt-2">
            {total === 0 ? (
              <div className="flex items-center gap-2 py-3 text-sm text-emerald-600">
                <Icon name="CheckCircle2" className="w-4 h-4" />
                No spelling issues found. Your resume looks great!
              </div>
            ) : (
              <div className="space-y-2 max-h-[400px] overflow-y-auto pr-1">
                {sections.map((section, si) => (
                  <div key={si}>
                    <div className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider mb-1 mt-2 first:mt-0">
                      {section.label}
                    </div>
                    {section.issues.map((issue, ii) => (
                      <div
                        key={ii}
                        className="flex items-start gap-2 py-1.5 px-2 rounded hover:bg-amber-100/50 group"
                      >
                        <div className="min-w-0 flex-1">
                          <span className="text-sm font-mono bg-red-100 text-red-700 px-1 rounded line-through">
                            {issue.word}
                          </span>
                          <span className="text-xs text-muted-foreground ml-2 italic truncate block sm:inline">
                            {issue.context}
                          </span>
                        </div>
                        <div className="flex gap-1 flex-shrink-0 flex-wrap">
                          {issue.suggestions.length > 0 ? (
                            issue.suggestions.slice(0, 3).map((sug) => (
                              <button
                                key={sug}
                                className="text-xs px-2 py-0.5 rounded bg-white border border-emerald-200 text-emerald-700 hover:bg-emerald-50 hover:border-emerald-400 transition-colors whitespace-nowrap"
                                onClick={() => {
                                  if (onFixWord && issue.path) {
                                    onFixWord(issue.path, issue.word, sug);
                                  }
                                }}
                                title={`Replace "${issue.word}" with "${sug}"`}
                              >
                                {sug}
                              </button>
                            ))
                          ) : (
                            <span className="text-[10px] text-muted-foreground italic">No suggestions</span>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                ))}
              </div>
            )}
          </CardContent>
          {total > 0 && (
            <CardFooter className="pt-2 pb-3 px-4">
              <p className="text-[10px] text-muted-foreground">
                Suggestion quality is based on word-level checks — proper nouns, brand names, and technical
                terms may be flagged. Use your judgment when accepting suggestions.
              </p>
            </CardFooter>
          )}
        </Card>
      </motion.div>
    </AnimatePresence>
  );
}

src/components/shared/UndoRedoPanel.tsx:
"use client";

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Card, CardContent, CardHeader, CardTitle, CardFooter } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge, Icon } from "@/components/shared";
import type { UndoRedoEntry } from "@/lib/builder-persistence";

interface Props {
  undoStack: UndoRedoEntry[];
  canUndo: boolean;
  canRedo: boolean;
  totalUndos: number;
  totalRedos: number;
  onUndo: () => boolean;
  onRedo: () => boolean;
  onSnapshot: (label?: string) => void;
  onJump: (index: number) => boolean;
  open: boolean;
  onToggle: () => void;
}

/**
 * UndoRedoPanel — shows the full edit history with session grouping,
 * undo/redo buttons, snapshot creation, and jump-to-any-point.
 */
export function UndoRedoPanel({
  undoStack,
  canUndo,
  canRedo,
  totalUndos,
  totalRedos,
  onUndo,
  onRedo,
  onSnapshot,
  onJump,
  open,
  onToggle,
}: Props) {
  const [snapshotLabel, setSnapshotLabel] = useState("");

  // Group entries by session (contiguous entries within same minute)
  const sessions: Array<{ label: string; entries: UndoRedoEntry[]; indices: number[] }> = [];
  let currentSession: typeof sessions[0] | null = null;

  undoStack.forEach((entry, i) => {
    const sessionGroup = entry.sessionId || `sess-${Math.floor(entry.timestamp / 60000)}`;
    if (!currentSession || currentSession.label !== sessionGroup) {
      currentSession = { label: sessionGroup, entries: [], indices: [] };
      sessions.push(currentSession);
    }
    currentSession.entries.push(entry);
    currentSession.indices.push(i);
  });

  const formatTime = (ts: number) => {
    const d = new Date(ts);
    const now = new Date();
    const isToday = d.toDateString() === now.toDateString();
    const time = d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" });
    return isToday ? time : `${d.toLocaleDateString([], { month: "short", day: "numeric" })} ${time}`;
  };

  if (!open) {
    return (
      <Button
        variant="outline"
        size="sm"
        onClick={onToggle}
        className="gap-1.5 h-8 relative"
        title="Edit history"
      >
        <Icon name="History" className="w-3.5 h-3.5" />
        <span className="hidden sm:inline">History</span>
      </Button>
    );
  }

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0, height: 0 }}
        animate={{ opacity: 1, height: "auto" }}
        exit={{ opacity: 0, height: 0 }}
        className="overflow-hidden"
      >
        <Card className="border-muted">
          <CardHeader className="pb-2 flex flex-row items-center justify-between gap-2">
            <div>
              <CardTitle className="text-sm font-semibold flex items-center gap-2">
                <Icon name="History" className="w-4 h-4" />
                Edit History
                <Badge variant="outline" className="text-[10px]">
                  {undoStack.length} entries
                </Badge>
              </CardTitle>
            </div>
            <div className="flex gap-1">
              <Button
                variant="ghost"
                size="sm"
                className="h-7 text-xs"
                disabled={!canUndo}
                onClick={onUndo}
                title="Undo (Ctrl+Z)"
              >
                <Icon name="Undo2" className="w-3 h-3 mr-1" /> Undo
              </Button>
              <Button
                variant="ghost"
                size="sm"
                className="h-7 text-xs"
                disabled={!canRedo}
                onClick={onRedo}
                title="Redo (Ctrl+Shift+Z)"
              >
                <Icon name="Redo2" className="w-3 h-3 mr-1" /> Redo
              </Button>
              <Button variant="ghost" size="sm" className="h-7 text-xs" onClick={onToggle}>
                <Icon name="X" className="w-3 h-3" />
              </Button>
            </div>
          </CardHeader>
          <CardContent className="pt-2">
            {/* Snapshot creation */}
            <div className="flex gap-2 mb-3">
              <input
                type="text"
                placeholder="Snapshot label (e.g. 'Before major edit')..."
                value={snapshotLabel}
                onChange={(e) => setSnapshotLabel(e.target.value)}
                className="flex-1 h-8 px-2 text-xs rounded border border-input bg-background"
                onKeyDown={(e) => {
                  if (e.key === "Enter") {
                    onSnapshot(snapshotLabel || undefined);
                    setSnapshotLabel("");
                  }
                }}
              />
              <Button
                variant="outline"
                size="sm"
                className="h-8 text-xs gap-1"
                onClick={() => {
                  onSnapshot(snapshotLabel || undefined);
                  setSnapshotLabel("");
                }}
              >
                <Icon name="Camera" className="w-3 h-3" /> Snapshot
              </Button>
            </div>

            {/* History list */}
            {undoStack.length === 0 ? (
              <div className="text-center py-6 text-muted-foreground text-sm">
                <Icon name="FileEdit" className="w-8 h-8 mx-auto mb-2 opacity-40" />
                No edits yet. Start editing your resume to build history.
              </div>
            ) : (
              <div className="space-y-1 max-h-[300px] overflow-y-auto pr-1">
                {[...undoStack].reverse().map((entry, reverseI) => {
                  const actualIndex = undoStack.length - 1 - reverseI;
                  const isLast = actualIndex === undoStack.length - 1;
                  return (
                    <div
                      key={`${entry.timestamp}-${actualIndex}`}
                      className={`flex items-center gap-2 py-1.5 px-2 rounded text-xs cursor-pointer
                        ${isLast ? "bg-brand/5 border border-brand/20" : "hover:bg-muted/50"}
                        transition-colors`}
                      onClick={() => onJump(actualIndex)}
                      title="Jump to this point in history"
                    >
                      <Icon
                        name={entry.label ? "Bookmark" : "FileEdit"}
                        className="w-3 h-3 flex-shrink-0 text-muted-foreground"
                      />
                      <span className="flex-1 truncate">
                        {entry.label || `Edit #${actualIndex + 1}`}
                      </span>
                      <span className="text-muted-foreground flex-shrink-0 ml-auto">
                        {formatTime(entry.timestamp)}
                      </span>
                      {entry.label && (
                        <Badge variant="default" className="text-[9px] bg-emerald-500">
                          Snapshot
                        </Badge>
                      )}
                    </div>
                  );
                })}
              </div>
            )}
          </CardContent>
          <CardFooter className="pt-2 pb-3 px-4 flex justify-between text-[10px] text-muted-foreground">
            <span>
              Undos: {totalUndos} &middot; Redos: {totalRedos}
            </span>
            <span>
              History persists across page refreshes (IndexedDB)
            </span>
          </CardFooter>
        </Card>
      </motion.div>
    </AnimatePresence>
  );
}

src/components/shared.tsx:
// Shared UI primitives & helpers for ResumeAI Pro
"use client";

import * as React from "react";
import * as Lucide from "lucide-react";
import { cn } from "@/lib/utils";

/** Render a lucide icon by name (string). Falls back to a circle. */
export function Icon({ name, className, ...props }: { name: string } & React.ComponentProps<typeof Lucide.Circle>) {
  const C = (Lucide as any)[name] as React.ComponentType<any> | undefined;
  const Comp = C ?? Lucide.Circle;
  return <Comp className={className} {...props} />;
}

export function Logo({ size = 32, withText = true, className }: { size?: number; withText?: boolean; className?: string }) {
  return (
    <div className={cn("flex items-center gap-2.5 select-none", className)}>
      <div
        className="relative rounded-xl overflow-hidden shadow-sm"
        style={{ width: size, height: size }}
        aria-hidden
      >
        <img src="/brand/logo.png" alt="" width={size} height={size} className="w-full h-full object-cover" />
      </div>
      {withText && (
        <div className="leading-none">
          <span className="font-display font-extrabold tracking-tight text-[1.05em] text-foreground">
            Resume<span className="gradient-text">AI</span>
          </span>
          <span className="ml-1 font-display font-bold text-[0.7em] text-gold">PRO</span>
        </div>
      )}
    </div>
  );
}

export function Badge({ children, variant = "default", className }: { children: React.ReactNode; variant?: "default" | "brand" | "gold" | "outline" | "success" | "warning" | "danger"; className?: string }) {
  const variants: Record<string, string> = {
    default: "bg-secondary text-secondary-foreground",
    brand: "bg-brand-light text-brand dark:bg-brand/15 dark:text-brand",
    gold: "bg-amber-100 text-amber-700 dark:bg-amber-400/10 dark:text-amber-300",
    outline: "border border-border text-foreground",
    success: "bg-emerald-100 text-emerald-700 dark:bg-emerald-400/10 dark:text-emerald-300",
    warning: "bg-orange-100 text-orange-700 dark:bg-orange-400/10 dark:text-orange-300",
    danger: "bg-red-100 text-red-700 dark:bg-red-400/10 dark:text-red-300",
  };
  return <span className={cn("inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium", variants[variant], className)}>{children}</span>;
}

interface Particle {
  id: number;
  x: number;
  y: number;
  size: number;
  color: string;
}

export function ScoreRing({ value, size = 120, stroke = 10, label }: { value: number; size?: number; stroke?: number; label?: string }) {
  const [displayValue, setDisplayValue] = React.useState(0);
  const [particles, setParticles] = React.useState<Particle[]>([]);
  const prevValueRef = React.useRef(0);

  // Numeric count-up/down animation
  React.useEffect(() => {
    let start = displayValue;
    const end = value;
    if (start === end) return;
    
    // Trigger particle burst if score increased
    if (end > prevValueRef.current && prevValueRef.current > 0) {
      const colors = ["#10B981", "#3B82F6", "#F59E0B", "#8B5CF6", "#EC4899"];
      const newParticles = Array.from({ length: 14 }).map((_, i) => {
        const angle = (i / 14) * 2 * Math.PI + (Math.random() - 0.5) * 0.3;
        const distance = size / 2 + Math.random() * 20;
        return {
          id: Math.random() + i,
          x: Math.cos(angle) * distance,
          y: Math.sin(angle) * distance,
          size: 4 + Math.random() * 5,
          color: colors[Math.floor(Math.random() * colors.length)]
        };
      });
      setParticles(newParticles);
      setTimeout(() => setParticles([]), 800);
    }
    prevValueRef.current = end;

    const duration = 800; // ms
    const startTime = performance.now();

    let animId: number;
    const step = (now: number) => {
      const progress = Math.min((now - startTime) / duration, 1);
      // Ease out quad
      const easeProgress = progress * (2 - progress);
      const current = Math.round(start + (end - start) * easeProgress);
      setDisplayValue(current);

      if (progress < 1) {
        animId = requestAnimationFrame(step);
      }
    };
    animId = requestAnimationFrame(step);
    return () => cancelAnimationFrame(animId);
  }, [value, size]);

  const radius = (size - stroke) / 2;
  const circ = 2 * Math.PI * radius;
  const off = circ - (displayValue / 100) * circ;
  const color = displayValue >= 85 ? "#10B981" : displayValue >= 70 ? "#1154A3" : displayValue >= 50 ? "#F59E0B" : "#DC2626";

  return (
    <div className="relative inline-flex items-center justify-center" style={{ width: size, height: size }}>
      <style>{`
        @keyframes particle-fly-fade {
          0% {
            transform: translate(0px, 0px) scale(1);
            opacity: 1;
          }
          100% {
            opacity: 0;
            transform: translate(var(--x, 0px), var(--y, 0px)) scale(0.2);
          }
        }
      `}</style>
      
      {/* Particle Burst Overlay */}
      {particles.map((p) => (
        <span
          key={p.id}
          className="absolute rounded-full pointer-events-none"
          style={{
            width: p.size,
            height: p.size,
            backgroundColor: p.color,
            boxShadow: `0 0 8px ${p.color}`,
            "--x": `${p.x}px`,
            "--y": `${p.y}px`,
            animation: "particle-fly-fade 0.8s forwards cubic-bezier(0.1, 0.8, 0.3, 1)",
            zIndex: 10
          } as React.CSSProperties}
        />
      ))}

      {/* SVG score circle */}
      <svg width={size} height={size} className="-rotate-90">
        <circle cx={size / 2} cy={size / 2} r={radius} fill="none" stroke="currentColor" className="text-muted/20" strokeWidth={stroke} />
        <circle
          cx={size / 2} cy={size / 2} r={radius} fill="none" stroke={color} strokeWidth={stroke}
          strokeDasharray={circ} strokeDashoffset={off} strokeLinecap="round"
          style={{ transition: "stroke-dashoffset 0.1s ease" }}
        />
      </svg>
      <div className="absolute inset-0 flex flex-col items-center justify-center">
        <span className="text-2xl font-bold font-display" style={{ color }}>{displayValue}</span>
        {label && <span className="text-[9px] uppercase tracking-wide text-muted-foreground font-semibold">{label}</span>}
      </div>
    </div>
  );
}

export function SectionTitle({ eyebrow, title, subtitle, center = true }: { eyebrow?: string; title: React.ReactNode; subtitle?: string; center?: boolean }) {
  return (
    <div className={cn("flex flex-col gap-3 max-w-2xl", center && "mx-auto text-center items-center")}>
      {eyebrow && (
        <span className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-brand-light text-brand text-xs font-semibold dark:bg-brand/15">
          {eyebrow}
        </span>
      )}
      <h2 className="font-display text-3xl sm:text-4xl font-bold tracking-tight text-balance">{title}</h2>
      {subtitle && <p className="text-muted-foreground text-base sm:text-lg text-pretty">{subtitle}</p>}
    </div>
  );
}

/**
 * Deterministic seeded pseudo-random generator.
 * Same seed → same sequence, so server and client produce identical output
 * (no React hydration mismatch). Uses a simple mulberry32 algorithm.
 */
function seededRandom(seed: number): () => number {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6D2B79F5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function Sparkles({ count = 12, className }: { count?: number; className?: string }) {
  // Generate sparkle properties deterministically (seeded by index) so the server
  // and client produce identical HTML — avoids React hydration mismatches.
  // We use a fixed seed so the layout is stable across reloads too.
  const items = React.useMemo(() => {
    const rand = seededRandom(42); // fixed seed for stable output
    return Array.from({ length: count }).map(() => {
      const sizeRoll = rand();
      const topRoll = rand();
      const leftRoll = rand();
      const colorRoll = rand();
      const opacityRoll = rand();
      const durRoll = rand();
      const delayRoll = rand();
      return {
        width: 2 + sizeRoll * 3,
        height: 2 + sizeRoll * 3, // use same roll for w/h so sparkles are round
        top: `${topRoll * 100}%`,
        left: `${leftRoll * 100}%`,
        background: colorRoll > 0.5 ? "var(--brand)" : "var(--gold)",
        opacity: 0.4 + opacityRoll * 0.4,
        animation: `float-up ${1 + durRoll * 2}s ease-out ${delayRoll * 2}s both`,
      };
    });
  }, [count]);

  return (
    <div className={cn("pointer-events-none absolute inset-0 overflow-hidden", className)} aria-hidden>
      {items.map((s, i) => (
        <span
          key={i}
          className="absolute rounded-full"
          style={s}
        />
      ))}
    </div>
  );
}

export function StatPill({ icon, label, value }: { icon: string; label: string; value: string }) {
  return (
    <div className="flex items-center gap-2 px-3 py-2 rounded-lg bg-card border border-border shadow-card">
      <Icon name={icon} className="w-4 h-4 text-brand" />
      <div className="leading-none">
        <div className="text-sm font-semibold">{value}</div>
        <div className="text-[10px] uppercase tracking-wide text-muted-foreground">{label}</div>
      </div>
    </div>
  );
}

export { AICopilotPanel } from "./shared/AICopilotPanel";
export { AgentConsole } from "./shared/AgentConsole";
export { QrCode } from "./shared/QrCode";
export { RegionalNormsPanel } from "./shared/RegionalNormsPanel";

