// ============================================================================
// Unit tests for the Sonru speech/filler helpers.
// Pure functions — no React, no AI, no mocks needed.
// ============================================================================

import { describe, it, expect } from "vitest";
import {
  analyzeFillerWords,
  normalizeWpmToScore,
  normalizeFillerCountToScore,
  FILLER_WORDS,
} from "@/hooks/interview/useFillerWordDetector";

describe("analyzeFillerWords", () => {
  it("returns zero stats for empty transcript", () => {
    const r = analyzeFillerWords("", 60_000);
    expect(r.count).toBe(0);
    expect(r.fillers).toEqual([]);
    expect(r.wordCount).toBe(0);
    expect(r.wpm).toBe(0);
    expect(r.density).toBe(0);
  });

  it("returns 0 wpm when duration is 0", () => {
    const r = analyzeFillerWords("hello world this is a test", 0);
    expect(r.wordCount).toBe(6);
    expect(r.wpm).toBe(0);
  });

  it("counts single-word fillers correctly", () => {
    const text = "um I uh think like we actually need to go";
    const r = analyzeFillerWords(text, 60_000);
    // "um", "uh", "like", "actually" → 4 fillers (note: "I" is not in the list)
    expect(r.count).toBe(4);
    expect(r.fillers).toEqual(expect.arrayContaining(["um", "uh", "like", "actually"]));
  });

  it("counts multi-word fillers correctly", () => {
    const text = "you know I was like, sort of, I mean, it was kind of hard";
    const r = analyzeFillerWords(text, 60_000);
    // "you know", "like", "sort of", "I mean", "kind of" → 5 fillers
    expect(r.count).toBeGreaterThanOrEqual(4);
    expect(r.fillers).toContain("you know");
    expect(r.fillers).toContain("like");
  });

  it("computes WPM correctly for a 1-minute transcript", () => {
    // 150 words in 60 seconds → 150 WPM (ideal conversational pace)
    const words = Array.from({ length: 150 }, (_, i) => `word${i}`).join(" ");
    const r = analyzeFillerWords(words, 60_000);
    expect(r.wpm).toBe(150);
    expect(r.wordCount).toBe(150);
  });

  it("density is fillers/words", () => {
    const text = "um hello uh world";
    const r = analyzeFillerWords(text, 60_000);
    // 2 fillers / 4 words = 0.5
    expect(r.density).toBeCloseTo(0.5, 5);
  });

  it("is case-insensitive", () => {
    const text = "UM Uh LiKe";
    const r = analyzeFillerWords(text, 60_000);
    expect(r.count).toBe(3);
  });

  it("does not match substrings (word boundaries respected)", () => {
    // "summer" contains "um" but should NOT be counted; "umbrella" same;
    // "humbly" contains "uh"... actually it doesn't — "humbly" has no "uh".
    // "uh" inside "dough" or "tough" should NOT match.
    const text = "summer umbrella dough tough";
    const r = analyzeFillerWords(text, 60_000);
    expect(r.count).toBe(0);
  });

  it("FILLER_WORDS list is non-empty and includes core disfluencies", () => {
    expect(FILLER_WORDS.length).toBeGreaterThan(10);
    expect(FILLER_WORDS).toContain("um");
    expect(FILLER_WORDS).toContain("uh");
    expect(FILLER_WORDS).toContain("like");
    expect(FILLER_WORDS).toContain("you know");
  });
});

describe("normalizeWpmToScore", () => {
  it("returns 100 at the ideal 150 WPM", () => {
    expect(normalizeWpmToScore(150)).toBe(100);
  });

  it("returns null when wpm is 0 or negative", () => {
    expect(normalizeWpmToScore(0)).toBeNull();
    expect(normalizeWpmToScore(-10)).toBeNull();
    expect(normalizeWpmToScore(NaN)).toBeNull();
  });

  it("decreases monotonically as WPM deviates from 150", () => {
    const at150 = normalizeWpmToScore(150)!;
    const at180 = normalizeWpmToScore(180)!;
    const at120 = normalizeWpmToScore(120)!;
    const at250 = normalizeWpmToScore(250)!;
    expect(at150).toBeGreaterThan(at180);
    expect(at150).toBeGreaterThan(at120);
    expect(at180).toBeGreaterThan(at250);
  });

  it("clamps to 0-100", () => {
    expect(normalizeWpmToScore(500)).toBeGreaterThanOrEqual(0);
    expect(normalizeWpmToScore(500)).toBeLessThanOrEqual(100);
  });
});

describe("normalizeFillerCountToScore", () => {
  it("returns 100 when there are 0 fillers", () => {
    expect(normalizeFillerCountToScore(0, 100)).toBe(100);
  });

  it("returns null when wordCount is 0", () => {
    expect(normalizeFillerCountToScore(0, 0)).toBeNull();
    expect(normalizeFillerCountToScore(5, 0)).toBeNull();
  });

  it("decreases as filler density increases", () => {
    const zeroFillers = normalizeFillerCountToScore(0, 100)!;
    const fiveFillers = normalizeFillerCountToScore(5, 100)!;
    const twentyFillers = normalizeFillerCountToScore(20, 100)!;
    expect(zeroFillers).toBeGreaterThan(fiveFillers);
    expect(fiveFillers).toBeGreaterThan(twentyFillers);
  });

  it("clamps to 0", () => {
    // 50% filler density → very low score, possibly 0
    expect(normalizeFillerCountToScore(50, 100)).toBeGreaterThanOrEqual(0);
    expect(normalizeFillerCountToScore(50, 100)).toBeLessThanOrEqual(100);
  });
});

// ============================================================================
// useFillerWordDetector — count filler words in a transcript and estimate WPM.
//
// Pure utility. The "filler word" set covers the most common English disfluencies.
// WPM (words per minute) is derived from the transcript length and the recording
// duration. Both feed into `evaluateAnswer`'s `videoMetrics` so the AI gets
// real signals for the `speakingSpeed` and `fillerWords` dimensions.
// ============================================================================

import { useMemo } from "react";

/** Common English filler words. Case-insensitive, word-boundary matched. */
export const FILLER_WORDS: readonly string[] = [
  "um",
  "uh",
  "umm",
  "uhh",
  "er",
  "err",
  "ah",
  "ahh",
  "like",
  "you know",
  "actually",
  "basically",
  "literally",
  "so",
  "right",
  "okay",
  "ok",
  "well",
  "i mean",
  "sort of",
  "kind of",
  "you see",
];

export interface FillerStats {
  /** Total filler-word occurrences in the transcript. */
  count: number;
  /** Each individual filler occurrence (useful for surfacing in UI). */
  fillers: string[];
  /** Words-per-minute estimate. 0 when durationMs is 0. */
  wpm: number;
  /** Total word count. */
  wordCount: number;
  /** Filler density = count / max(wordCount,1). */
  density: number;
}

/**
 * Count filler words in `transcript` and derive WPM from `durationMs`.
 *
 * Pure function — also exported for unit tests.
 */
export function analyzeFillerWords(
  transcript: string,
  durationMs: number
): FillerStats {
  const text = (transcript ?? "").toLowerCase();
  const wordCount = text ? text.trim().split(/\s+/).filter(Boolean).length : 0;
  const fillers: string[] = [];
  if (text) {
    for (const f of FILLER_WORDS) {
      // Escape regex special chars (defensive; current set has none).
      const escaped = f.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      const re = new RegExp(`\\b${escaped}\\b`, "g");
      const matches = text.match(re);
      if (matches) fillers.push(...matches);
    }
  }
  const count = fillers.length;
  const minutes = durationMs > 0 ? durationMs / 60_000 : 0;
  const wpm = minutes > 0 ? Math.round(wordCount / minutes) : 0;
  const density = wordCount > 0 ? count / wordCount : 0;
  return { count, fillers, wpm, wordCount, density };
}

/**
 * React hook variant. Recomputes whenever `transcript` or `durationMs` change.
 */
export function useFillerWordDetector(
  transcript: string,
  durationMs: number
): FillerStats {
  return useMemo(
    () => analyzeFillerWords(transcript, durationMs),
    [transcript, durationMs]
  );
}

/**
 * Map a raw WPM value to a 0-100 normalized score. Ideal conversational WPM is
 * ~140-160; faster or slower reduces the score. Returns null when wpm <= 0.
 */
export function normalizeWpmToScore(wpm: number): number | null {
  if (!Number.isFinite(wpm) || wpm <= 0) return null;
  const ideal = 150;
  const deviation = Math.abs(wpm - ideal);
  // 0 deviation = 100; 100 deviation = ~0
  const score = Math.max(0, Math.round(100 - deviation * 1.0));
  return Math.min(100, Math.max(0, score));
}

/**
 * Map a raw filler-count to a 0-100 score. 0 fillers = 100; degrades
 * gracefully so a long answer with 5 fillers still scores ~70.
 */
export function normalizeFillerCountToScore(
  count: number,
  wordCount: number
): number | null {
  if (!Number.isFinite(count) || count < 0) return null;
  if (wordCount <= 0) return null;
  // Density-based: 0% = 100; 5% = ~50; 10%+ = 0.
  const density = count / wordCount;
  const score = Math.max(0, Math.round(100 - density * 1000));
  return Math.min(100, Math.max(0, score));
}

src/hooks/interview/useMediaRecorder.ts:
"use client";

// ============================================================================
// useMediaRecorder — record the active camera+mic MediaStream with MediaRecorder.
// Supports: start / pause / resume / stop / restart, max-duration auto-stop,
// elapsed-time tracking, and MIME-type negotiation. Pure browser API.
//
// The recorder does NOT own the stream — it receives it from useDeviceCheck
// (or any other source) so the same preview stream is reused for recording.
// ============================================================================

import { useCallback, useEffect, useRef, useState } from "react";
import type { RecorderSnapshot, RecorderState } from "./types";
import { useAudioMeter } from "./useAudioMeter";

function pickMimeType(stream?: MediaStream | null): string {
  if (typeof window === "undefined" || !("MediaRecorder" in window)) return "";
  // Detect audio-only streams so we pick an audio-only MIME type (avoids a
  // Safari quirk where a video MIME with no video track fails to start).
  const hasVideo = !!stream?.getVideoTracks().length;
  const candidates = hasVideo
    ? [
        "video/webm;codecs=vp9,opus",
        "video/webm;codecs=vp8,opus",
        "video/webm",
        "video/mp4",
      ]
    : [
        "audio/webm;codecs=opus",
        "audio/webm",
        "audio/ogg;codecs=opus",
        "audio/mp4",
        "video/webm", // last-resort fallback
      ];
  for (const c of candidates) {
    try {
      if (MediaRecorder.isTypeSupported(c)) return c;
    } catch {
      /* ignore */
    }
  }
  return "";
}

export interface UseMediaRecorderOptions {
  /** Auto-stop after this many ms (Sonru "Maximum Recording Time"). */
  maxDurationMs?: number;
  /** Called when a recording is finalized (manually or by max-duration). */
  onComplete?: (blob: Blob, mimeType: string, durationMs: number) => void;
}

export interface UseMediaRecorderResult extends RecorderSnapshot {
  level: number;
  peak: number;
  micActive: boolean;
  start: (stream: MediaStream) => void;
  pause: () => void;
  resume: () => void;
  stop: () => void;
  restart: (stream: MediaStream) => void;
  clear: () => void;
}

export function useMediaRecorder(options: UseMediaRecorderOptions = {}): UseMediaRecorderResult {
  const { maxDurationMs = null, onComplete } = options;

  // Keep the latest onComplete in a ref so finalize() always calls the current
  // closure (the component's handler depends on changing state like currentIndex).
  const onCompleteRef = useRef(onComplete);
  onCompleteRef.current = onComplete;

  const [snapshot, setSnapshot] = useState<RecorderSnapshot>(() => ({
    state: "idle",
    elapsedMs: 0,
    maxDurationMs,
    blob: null,
    mimeType: "",
    error: null,
    supported: typeof window !== "undefined" && "MediaRecorder" in window,
  }));

  const recorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<BlobPart[]>([]);
  const streamRef = useRef<MediaStream | null>(null);
  const startTsRef = useRef<number>(0);
  const accumulatedRef = useRef<number>(0);
  const rafRef = useRef<number | null>(null);
  const maxTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const meter = useAudioMeter();

  const tick = useCallback(() => {
    const base = accumulatedRef.current;
    const inc = startTsRef.current ? performance.now() - startTsRef.current : 0;
    setSnapshot((s) => ({ ...s, elapsedMs: base + inc }));
    rafRef.current = requestAnimationFrame(tick);
  }, []);

  const stopRaf = useCallback(() => {
    if (rafRef.current != null) {
      cancelAnimationFrame(rafRef.current);
      rafRef.current = null;
    }
  }, []);

  const clearMaxTimer = useCallback(() => {
    if (maxTimerRef.current != null) {
      clearTimeout(maxTimerRef.current);
      maxTimerRef.current = null;
    }
  }, []);

  const finalize = useCallback(
    (recorder: MediaRecorder, mimeType: string) => {
      const blob = new Blob(chunksRef.current, { type: mimeType || "video/webm" });
      stopRaf();
      clearMaxTimer();
      meter.stop();
      setSnapshot((s) => ({
        ...s,
        state: "stopped",
        blob,
        mimeType: mimeType || s.mimeType,
        elapsedMs: accumulatedRef.current,
      }));
      onCompleteRef.current?.(blob, mimeType || "video/webm", accumulatedRef.current);
    },
    [clearMaxTimer, meter, stopRaf]
  );

  const start = useCallback(
    (stream: MediaStream) => {
      if (typeof window === "undefined" || !("MediaRecorder" in window)) {
        setSnapshot((s) => ({
          ...s,
          error: "MediaRecorder is not supported in this browser.",
          state: "error",
        }));
        return;
      }
      // Tear down any prior recorder.
      const prior = recorderRef.current;
      if (prior && prior.state !== "inactive") prior.stop();
      chunksRef.current = [];
      accumulatedRef.current = 0;

      // PRE-FLIGHT: verify audio tracks are present, live, and enabled.
      // If audio is missing or stopped the MediaRecorder will still run but
      // produce a silent Blob. We catch and report it here so the UI can
      // surface a meaningful error instead of a confusing silent recording.
      const audioTracks = stream.getAudioTracks();
      if (audioTracks.length === 0) {
        setSnapshot((s) => ({
          ...s,
          error: "The media stream has no audio track. Check microphone permissions and retry.",
          state: "error",
        }));
        return;
      }
      // Re-enable any track that was accidentally disabled and surface
      // a warning for tracks that have already ended.
      for (const t of audioTracks) {
        if (!t.enabled) t.enabled = true;
        if (t.readyState === "ended") {
          setSnapshot((s) => ({
            ...s,
            error: "The microphone track has ended. Please close and re-open the session to request a fresh stream.",
            state: "error",
          }));
          return;
        }
      }

      const mimeType = pickMimeType(stream);
      let recorder: MediaRecorder;
      try {
        // Always pass explicit bitrate options so the browser encoder uses a
        // predictable audio quality regardless of MIME-type negotiation.
        // Note: passing bare `new MediaRecorder(stream)` with no options lets
        // the browser pick its own (often lower) audio quality, which can
        // manifest as apparent silence on slow-clocked devices.
        const recorderOptions: MediaRecorderOptions = mimeType
          ? { mimeType, videoBitsPerSecond: 2_500_000, audioBitsPerSecond: 128_000 }
          : { audioBitsPerSecond: 128_000 };
        recorder = new MediaRecorder(stream, recorderOptions);
      } catch (e: any) {
        setSnapshot((s) => ({ ...s, error: `Could not start recorder: ${e?.message || e}`, state: "error" }));
        return;
      }

      recorderRef.current = recorder;
      streamRef.current = stream;

      recorder.ondataavailable = (ev) => {
        if (ev.data && ev.data.size > 0) chunksRef.current.push(ev.data);
      };
      recorder.onstop = () => {
        const mime = recorder.mimeType || mimeType;
        finalize(recorder, mime);
      };
      recorder.onerror = (ev: any) => {
        const msg = ev?.error?.message || "Recording error.";
        stopRaf();
        clearMaxTimer();
        meter.stop();
        setSnapshot((s) => ({ ...s, error: msg, state: "error" }));
      };

      startTsRef.current = performance.now();
      // 250 ms timeslice: guarantees ondataavailable fires at least 4×/sec,
      // so the final chunk is never more than 250 ms of audio away from stop().
      recorder.start(250);
      setSnapshot((s) => ({
        ...s,
        state: "recording",
        blob: null,
        mimeType,
        error: null,
        elapsedMs: 0,
        maxDurationMs,
      }));
      rafRef.current = requestAnimationFrame(tick);
      meter.start(stream);

      if (maxDurationMs && maxDurationMs > 0) {
        clearMaxTimer();
        maxTimerRef.current = setTimeout(() => {
          if (recorderRef.current && recorderRef.current.state === "recording") {
            recorderRef.current.stop();
          }
        }, maxDurationMs);
      }
    },
    [finalize, maxDurationMs, meter, tick]
  );

  const pause = useCallback(() => {
    const r = recorderRef.current;
    if (r && r.state === "recording") {
      accumulatedRef.current += performance.now() - startTsRef.current;
      r.pause();
      stopRaf();
      meter.stop();
      setSnapshot((s) => ({ ...s, state: "paused", elapsedMs: accumulatedRef.current }));
    }
  }, [meter, stopRaf]);

  const resume = useCallback(() => {
    const r = recorderRef.current;
    if (r && r.state === "paused") {
      startTsRef.current = performance.now();
      r.resume();
      rafRef.current = requestAnimationFrame(tick);
      if (streamRef.current) meter.start(streamRef.current);
      setSnapshot((s) => ({ ...s, state: "recording" }));
    }
  }, [meter, tick]);

  const stop = useCallback(() => {
    const r = recorderRef.current;
    if (r && r.state !== "inactive") {
      accumulatedRef.current += startTsRef.current ? performance.now() - startTsRef.current : 0;
      r.stop();
    }
  }, []);

  const restart = useCallback(
    (stream: MediaStream) => {
      // Reset and start fresh on the same stream.
      chunksRef.current = [];
      accumulatedRef.current = 0;
      start(stream);
    },
    [start]
  );

  const clear = useCallback(() => {
    stopRaf();
    clearMaxTimer();
    meter.stop();
    chunksRef.current = [];
    accumulatedRef.current = 0;
    recorderRef.current = null;
    streamRef.current = null;
    setSnapshot((s) => ({ ...s, state: "idle", blob: null, error: null, elapsedMs: 0 }));
  }, [clearMaxTimer, meter, stopRaf]);

  useEffect(
    () => () => {
      stopRaf();
      clearMaxTimer();
      meter.stop();
      try {
        const r = recorderRef.current;
        if (r && r.state !== "inactive") r.stop();
      } catch {
        /* ignore */
      }
    },
    [clearMaxTimer, meter, stopRaf]
  );

  return {
    ...snapshot,
    level: meter.level,
    peak: meter.peak,
    micActive: meter.active,
    start,
    pause,
    resume,
    stop,
    restart,
    clear,
  };
}

src/hooks/interview/useSpeechRecognition:
"use client";

// ============================================================================
// useSpeechRecognition — thin Web Speech API wrapper (SpeechRecognition).
//
// Reused by both the video session (VideoInterviewSession.tsx) and the voice
// session (VoiceInterviewSession.tsx) to produce a live transcript that is
// then fed into `evaluateAnswer` as `answerText` and into the filler-word /
// WPM helpers in `useFillerWordDetector`.
//
// Pure browser API. Server-safe: returns `supported=false` on the server and
// when the Web Speech API is missing (Firefox does not yet ship it). Non-fatal
// error handling: "no-speech" / "aborted" are silently suppressed.
// ============================================================================

import { useCallback, useEffect, useRef, useState } from "react";

export interface UseSpeechRecognitionOptions {
  /** Locale for recognition. Default "en-US". */
  lang?: string;
  /** Whether to return interim (non-final) results. Default false (final only). */
  interimResults?: boolean;
  /** Whether to keep listening after a result. Default true. */
  continuous?: boolean;
  /** Called when a final result arrives. */
  onResult?: (finalTranscript: string) => void;
}

export interface UseSpeechRecognitionResult {
  /** Whether the Web Speech API is available in this browser. */
  supported: boolean;
  /** Whether recognition is currently active. */
  listening: boolean;
  /** Accumulated final transcript (cleared on `reset()`). */
  transcript: string;
  /** Most recent interim (in-progress) transcript. */
  interimTranscript: string;
  /** Last error message (e.g. "Audio capture failed"). Empty when healthy. */
  error: string | null;
  /** Start listening. No-op if already listening or unsupported. */
  start: () => void;
  /** Stop listening. Safe to call when not listening. */
  stop: () => void;
  /** Reset the accumulated transcript. */
  reset: () => void;
}

// Minimum type surface for the vendor-prefixed Web Speech API. We do not depend
// on the @types/speech-recognition package to keep the bundle slim.
interface SpeechRecognitionResultLike {
  isFinal: boolean;
  0: { transcript: string };
}
interface SpeechRecognitionEventLike {
  resultIndex: number;
  results: { length: number; [index: number]: SpeechRecognitionResultLike };
}
interface SpeechRecognitionErrorEventLike {
  error: string;
  message?: string;
}
interface SpeechRecognitionLike {
  lang: string;
  continuous: boolean;
  interimResults: boolean;
  maxAlternatives: number;
  start: () => void;
  stop: () => void;
  abort: () => void;
  onresult: ((ev: SpeechRecognitionEventLike) => void) | null;
  onerror: ((ev: SpeechRecognitionErrorEventLike) => void) | null;
  onend: (() => void) | null;
  onstart: (() => void) | null;
}
type SpeechRecognitionCtor = new () => SpeechRecognitionLike;

function getSpeechRecognitionCtor(): SpeechRecognitionCtor | null {
  if (typeof window === "undefined") return null;
  const w = window as any;
  return (w.SpeechRecognition || w.webkitSpeechRecognition) ?? null;
}

export function useSpeechRecognition(
  options: UseSpeechRecognitionOptions = {}
): UseSpeechRecognitionResult {
  const {
    lang = "en-US",
    interimResults = false,
    continuous = true,
    onResult,
  } = options;

  const ctorRef = useRef<SpeechRecognitionCtor | null>(null);
  const recRef = useRef<SpeechRecognitionLike | null>(null);
  const onResultRef = useRef(onResult);
  // Update the ref in an effect (NOT during render) so the recognition
  // callback always uses the latest closure without re-subscribing.
  useEffect(() => {
    onResultRef.current = onResult;
  }, [onResult]);

  const [supported, setSupported] = useState(false);
  const [listening, setListening] = useState(false);
  const [transcript, setTranscript] = useState("");
  const [interimTranscript, setInterimTranscript] = useState("");
  const [error, setError] = useState<string | null>(null);
  const shouldListenRef = useRef(false);

  useEffect(() => {
    const ctor = getSpeechRecognitionCtor();
    ctorRef.current = ctor;
    setSupported(!!ctor);
    return () => {
      try {
        recRef.current?.abort();
      } catch {
        /* ignore */
      }
      recRef.current = null;
    };
  }, []);

  const start = useCallback(() => {
    if (!ctorRef.current) {
      setError("Speech recognition is not supported in this browser. The interview will continue, but live transcription will be unavailable.");
      return;
    }
    if (recRef.current) {
      // Already started.
      return;
    }
    try {
      const rec = new ctorRef.current();
      rec.lang = lang;
      rec.continuous = continuous;
      rec.interimResults = interimResults;
      rec.maxAlternatives = 1;
      rec.onstart = () => {
        setListening(true);
        setError(null);
      };
      rec.onresult = (ev: SpeechRecognitionEventLike) => {
        let interim = "";
        for (let i = ev.resultIndex; i < ev.results.length; i++) {
          const r = ev.results[i];
          if (r.isFinal) {
            const text = r[0]?.transcript ?? "";
            setTranscript((prev) => (prev ? prev + " " : "") + text.trim());
            if (onResultRef.current) onResultRef.current(text.trim());
          } else {
            interim += r[0]?.transcript ?? "";
          }
        }
        setInterimTranscript(interim);
      };
      rec.onerror = (ev: SpeechRecognitionErrorEventLike) => {
        // Suppress benign errors that fire constantly during normal use.
        if (ev.error === "no-speech" || ev.error === "aborted" || ev.error === "audio-capture") {
          return;
        }
        // "not-allowed" / "service-not-allowed" indicate a permission denial.
        if (ev.error === "not-allowed" || ev.error === "service-not-allowed") {
          setError("Microphone permission denied for speech recognition.");
          shouldListenRef.current = false;
          return;
        }
        setError(ev.message || ev.error || "Speech recognition error.");
      };
      rec.onend = () => {
        setListening(false);
        // Auto-restart if the user hasn't explicitly stopped. Web Speech API
        // stops on its own after a few seconds of silence; we want to keep
        // going for the full recording duration.
        if (shouldListenRef.current) {
          try {
            rec.start();
          } catch {
            /* may throw if restarted too quickly; ignore */
          }
        }
      };
      shouldListenRef.current = true;
      rec.start();
      recRef.current = rec;
    } catch (e: any) {
      setError(e?.message || "Could not start speech recognition.");
    }
  }, [lang, continuous, interimResults]);

  const stop = useCallback(() => {
    shouldListenRef.current = false;
    const rec = recRef.current;
    recRef.current = null;
    if (rec) {
      try {
        rec.stop();
      } catch {
        /* ignore */
      }
    }
    setListening(false);
    setInterimTranscript("");
  }, []);

  const reset = useCallback(() => {
    setTranscript("");
    setInterimTranscript("");
    setError(null);
  }, []);

  return {
    supported,
    listening,
    transcript,
    interimTranscript,
    error,
    start,
    stop,
    reset,
  };
}

src/hooks/interview/useSpeechSynthesis.t:
"use client";

// ============================================================================
// useSpeechSynthesis — thin Web Speech API wrapper (speechSynthesis).
//
// The TTS counterpart of useSpeechRecognition: speaks the interviewer's
// questions aloud during the voice mock interview. Pure browser API — no
// Puter auth, no network dependency, works with the OS voice pack.
//
// Chrome reliably CUTS OFF utterances longer than ~15s, so consumers should
// pass text through splitForSpeech() (see lib/interview/voice-conversation)
// and call speak() per chunk — this hook queues chunks in order and tracks
// overall speaking state until the queue drains.
//
// Server-safe: supported=false on the server / when the API is missing.
// ============================================================================

import { useCallback, useEffect, useRef, useState } from "react";

export interface SpeakOptions {
  /** Preferred voice by voiceURI (falls back to the first matching lang). */
  voiceURI?: string;
  /** Locale tag, e.g. "en-US". Default "en-US". */
  lang?: string;
  /** 0.1–2. Default 1. */
  rate?: number;
  /** 0–2. Default 1. */
  pitch?: number;
}

export interface UseSpeechSynthesisResult {
  /** Whether speechSynthesis exists in this browser. */
  supported: boolean;
  /** True while any queued utterance is still speaking. */
  speaking: boolean;
  /** Available system voices (populated async — Chrome fires voiceschanged). */
  voices: Array<{ voiceURI: string; name: string; lang: string; default: boolean }>;
  /** Speak a chunk (or an array of chunks) in order. Cancels any prior speech. */
  speak: (text: string | string[], options?: SpeakOptions) => void;
  /** Stop immediately and clear the queue. */
  cancel: () => void;
}

function listVoices(): SpeechSynthesisVoice[] {
  if (typeof window === "undefined" || !("speechSynthesis" in window)) return [];
  try {
    return window.speechSynthesis.getVoices() ?? [];
  } catch {
    return [];
  }
}

export function useSpeechSynthesis(): UseSpeechSynthesisResult {
  const supported = typeof window !== "undefined" && "speechSynthesis" in window;
  const [speaking, setSpeaking] = useState(false);
  const [voices, setVoices] = useState<SpeechSynthesisVoice[]>(() => listVoices());
  // Monotonic token — increments per speak() call so stale onend callbacks
  // from a cancelled queue can never flip `speaking` back to false early.
  const queueToken = useRef(0);

  useEffect(() => {
    if (!supported) return;
    const synth = window.speechSynthesis;

    // Chrome populates voices asynchronously.
    const refresh = () => setVoices(listVoices());
    refresh();
    synth.addEventListener?.("voiceschanged", refresh);
    // Some browsers need a tick after mount before getVoices() is non-empty.
    const t = window.setTimeout(refresh, 250);

    // Safety: never leave speech running after unmount.
    return () => {
      synth.removeEventListener?.("voiceschanged", refresh);
      window.clearTimeout(t);
      try {
        synth.cancel();
      } catch {
        /* noop */
      }
    };
  }, [supported]);

  const cancel = useCallback(() => {
    if (!supported) return;
    queueToken.current += 1;
    try {
      window.speechSynthesis.cancel();
    } catch {
      /* noop */
    }
    setSpeaking(false);
  }, [supported]);

  const speak = useCallback(
    (text: string | string[], options?: SpeakOptions) => {
      if (!supported) return;
      const chunks = (Array.isArray(text) ? text : [text]).map((c) => (c ?? "").trim()).filter(Boolean);
      if (chunks.length === 0) return;

      // New utterance always replaces whatever is queued/playing.
      cancel();
      const token = queueToken.current;
      const synth = window.speechSynthesis;

      const allVoices = voices.length ? voices : listVoices();
      const lang = options?.lang ?? "en-US";
      const chosen =
        allVoices.find((v) => options?.voiceURI && v.voiceURI === options.voiceURI) ??
        allVoices.find((v) => v.lang?.toLowerCase() === lang.toLowerCase()) ??
        allVoices.find((v) => v.lang?.toLowerCase().startsWith(lang.slice(0, 2).toLowerCase())) ??
        null;

      setSpeaking(true);
      let done = 0;
      chunks.forEach((chunk) => {
        const u = new SpeechSynthesisUtterance(chunk);
        if (chosen) u.voice = chosen;
        u.lang = chosen?.lang ?? lang;
        u.rate = Math.min(2, Math.max(0.1, options?.rate ?? 1));
        u.pitch = Math.min(2, Math.max(0, options?.pitch ?? 1));
        u.onend = () => {
          done += 1;
          if (done >= chunks.length && queueToken.current === token) setSpeaking(false);
        };
        u.onerror = () => {
          done += 1;
          if (done >= chunks.length && queueToken.current === token) setSpeaking(false);
        };
        try {
          synth.speak(u);
        } catch {
          done += 1;
          if (done >= chunks.length && queueToken.current === token) setSpeaking(false);
        }
      });
    },
    [supported, voices, cancel],
  );

  return { supported, speaking, voices: voices.map((v) => ({ voiceURI: v.voiceURI, name: v.name, lang: v.lang, default: v.default })), speak, cancel };
}

