"use client";

// ============================================================================
// usePipelineWebSocket — DEPRECATED.
//
// This hook previously used WebSocket + Durable Objects for real-time pipeline
// updates. That required the Cloudflare Workers Paid plan.
//
// The platform now runs entirely on the Cloudflare Free plan using:
//   D1 + Polling (every 2 seconds)
//
// This hook is kept for backward compatibility but now uses polling internally.
// New code should use useTaskPolling() directly.
//
// See: src/hooks/useTaskPolling.ts
// ============================================================================

import { useTaskPolling, createTask, updateTaskProgress, type TaskState } from "./useTaskPolling";

export type { TaskState };
export type PipelineWebSocketState = {
  snapshot: TaskState | null;
  isConnected: boolean;
  reconnectAttempts: number;
  isPolling: boolean;
  error: string | null;
};

/**
 * @deprecated Use useTaskPolling() directly.
 *
 * This hook now uses D1 polling internally (no WebSockets, no Durable Objects).
 */
export function usePipelineWebSocket(
  pipelineId: string | null,
  options?: { enabled?: boolean },
): PipelineWebSocketState & {
  requestSnapshot: () => void;
} {
  const { task, isLoading, error, isTerminal, refetch } = useTaskPolling(pipelineId);

  return {
    snapshot: task,
    isConnected: !isLoading && !!task,
    reconnectAttempts: 0,
    isPolling: !isTerminal && !!pipelineId,
    error,
    requestSnapshot: refetch,
  };
}

export { createTask, updateTaskProgress };

src/hooks/useTaskPolling.ts:
"use client";

// ============================================================================
// useTaskPolling — a React hook that polls D1 for task status updates.
//
// Replaces the WebSocket-based usePipelineWebSocket hook. Works entirely on
// the Cloudflare Free plan — no Durable Objects, no WebSockets required.
//
// Architecture:
//   1. Frontend creates a task: POST /api/tasks/create → { task: { id } }
//   2. Frontend polls: GET /api/tasks/:id/status every 2 seconds
//   3. Polling auto-stops when status ∈ {completed, failed, cancelled}
//   4. (Optional) SSE: GET /api/tasks/:id/events — if available, replaces polling
//
// Usage:
//   const { task, isLoading, error, cancel } = useTaskPolling(taskId);
//
// Or create + track in one call:
//   const { task, createTask } = useTaskPolling();
//   await createTask({ type: "optimization", message: "Optimizing resume..." });
// ============================================================================

import { useState, useEffect, useCallback, useRef } from "react";

const API_BASE = "https://resumeai-pro-api.rachidelsabah.workers.dev";
const POLL_INTERVAL_MS = 2000;

export type TaskStatus = "queued" | "running" | "completed" | "failed" | "cancelled";

export interface TaskState {
  id: string;
  status: TaskStatus;
  progress: number;
  message: string | null;
  error: string | null;
  updated_at: number;
}

export interface UseTaskPollingResult {
  /** The current task state (null if not yet created or not found). */
  task: TaskState | null;
  /** True while the initial fetch is in progress. */
  isLoading: boolean;
  /** Error message if the fetch failed (null otherwise). */
  error: string | null;
  /** Whether the task is in a terminal state (completed/failed/cancelled). */
  isTerminal: boolean;
  /** Cancel the task (POST /api/tasks/:id/cancel). */
  cancel: () => Promise<boolean>;
  /** Manually refetch the task status. */
  refetch: () => void;
}

/**
 * Check if a status is terminal (polling should stop).
 */
function isTerminalStatus(status: TaskStatus | undefined | null): boolean {
  return status === "completed" || status === "failed" || status === "cancelled";
}

/**
 * Hook that polls a task's status every 2 seconds.
 * Auto-stops when the task reaches a terminal status.
 */
export function useTaskPolling(taskId: string | null): UseTaskPollingResult {
  const [task, setTask] = useState<TaskState | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const taskRef = useRef<TaskState | null>(null);

  const fetchStatus = useCallback(async () => {
    if (!taskId) return;

    try {
      const res = await fetch(`${API_BASE}/api/tasks/${taskId}/status`);
      if (!res.ok) {
        if (res.status === 404) {
          setError("Task not found");
          setTask(null);
        } else {
          setError(`HTTP ${res.status}`);
        }
        return;
      }

      const data = (await res.json()) as any;
      if (data.ok) {
        setTask({
            id: data.id,
            status: data.status,
            progress: data.progress,
            message: data.message,
            error: data.error,
            updated_at: data.updated_at,
          });
          taskRef.current = {
            id: data.id,
            status: data.status,
            progress: data.progress,
            message: data.message,
            error: data.error,
            updated_at: data.updated_at,
          };
          setError(null);
      } else {
        setError(data.error || "Failed to fetch task status");
      }
    } catch (e: any) {
      // Don't set error on network failures — just keep polling.
      // The next poll will likely succeed.
      console.warn("[useTaskPolling] Fetch failed (will retry):", e?.message);
    }
  }, [taskId]);

  // Start polling when taskId is set
  useEffect(() => {
    if (!taskId) {
      setTask(null);
      setError(null);
      return;
    }

    setIsLoading(true);
    fetchStatus().finally(() => setIsLoading(false));

    // Set up the 2s polling interval
    intervalRef.current = setInterval(() => {
      // Read latest status from a ref to keep the updater pure (no side effects)
      if (isTerminalStatus(taskRef.current?.status)) {
        // Stop polling
        if (intervalRef.current) {
          clearInterval(intervalRef.current);
          intervalRef.current = null;
        }
        return;
      }
      // Continue polling
      fetchStatus();
    }, POLL_INTERVAL_MS);

    // Cleanup on unmount or taskId change
    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
    };
  }, [taskId, fetchStatus]);

  // Stop polling when task reaches terminal status
  useEffect(() => {
    if (isTerminalStatus(task?.status) && intervalRef.current) {
      clearInterval(intervalRef.current);
      intervalRef.current = null;
    }
  }, [task?.status]);

  const cancel = useCallback(async (): Promise<boolean> => {
    if (!taskId) return false;
    try {
      const res = await fetch(`${API_BASE}/api/tasks/${taskId}/cancel`, { method: "POST" });
      if (res.ok) {
        // Immediately update local state
        setTask((prev) => prev ? { ...prev, status: "cancelled", message: "Cancelled by user" } : prev);
        return true;
      }
      return false;
    } catch {
      return false;
    }
  }, [taskId]);

  const refetch = useCallback(() => {
    fetchStatus();
  }, [fetchStatus]);

  return {
    task,
    isLoading,
    error,
    isTerminal: isTerminalStatus(task?.status),
    cancel,
    refetch,
  };
}

// ============================================================================
// Task creation helper
// ============================================================================

export interface CreateTaskInput {
  type: string;
  message?: string;
}

export interface CreateTaskResult {
  ok: boolean;
  task?: { id: string; type: string; status: string; progress: number; message: string };
  error?: string;
}

/**
 * Create a new task in D1. Returns the task ID for polling.
 */
export async function createTask(input: CreateTaskInput): Promise<CreateTaskResult> {
  try {
    const res = await fetch(`${API_BASE}/api/tasks/create`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(input),
    });
    const data = (await res.json()) as any;
    if (data.ok) {
      return { ok: true, task: data.task };
    }
    return { ok: false, error: data.error || "Failed to create task" };
  } catch (e: any) {
    return { ok: false, error: e?.message || "Network error" };
  }
}

/**
 * Update a task's progress (called from the client-side worker that runs the task).
 * In a typical flow, the client creates the task, then runs the work locally,
 * updating progress via this function.
 */
export async function updateTaskProgress(
  taskId: string,
  update: {
    status?: TaskStatus;
    progress?: number;
    message?: string;
    result?: any;
    error?: string;
  },
): Promise<boolean> {
  try {
    const res = await fetch(`${API_BASE}/api/tasks/${taskId}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(update),
    });
    return res.ok;
  } catch {
    return false;
  }
}

/**
 * Get the full task record (including result_json) — call this when the task
 * is completed to fetch the result.
 */
export async function getTaskResult(taskId: string): Promise<any | null> {
  try {
    const res = await fetch(`${API_BASE}/api/tasks/${taskId}`);
    if (!res.ok) return null;
    const data = (await res.json()) as any;
    if (data.ok && data.task) {
      return data.task.result;
    }
    return null;
  } catch {
    return null;
  }
}

src/hooks/useTrajectory.ts:
"use client";

// ============================================================================
// useTrajectory — React binding for the agent event bus (item #10).
//
// The globalEventBus has been emit-only since introduction; this hook is its
// FIRST UI consumer: it subscribes via useSyncExternalStore and returns the
// (capped) event history + live stats so observability panels re-render on
// every pipeline node/agent event.
// ============================================================================

import { useSyncExternalStore, useCallback } from "react";
import { globalEventBus, type AgentEvent, type EventBusStats } from "@/lib/agent-event-bus";

function snapshot(): AgentEvent[] {
  return globalEventBus.getHistory();
}

function subscribe(onChange: () => void): () => void {
  // The bus emits per event; React batches the re-renders.
  return globalEventBus.subscribe(onChange);
}

/**
 * Live trajectory of agent/pipeline events (newest first for display).
 * `limit` bounds the returned slice (default 80).
 */
export function useTrajectory(limit = 80): {
  events: AgentEvent[];
  eventsNewestFirst: AgentEvent[];
  stats: EventBusStats;
} {
  const events = useSyncExternalStore(subscribe, snapshot, snapshot);
  const stats = globalEventBus.getStats();
  const eventsNewestFirst = events.slice(-limit).reverse();

  return { events, eventsNewestFirst, stats };
}

/** Clear the bus history (also clears the panel). */
export function useClearTrajectory(): () => void {
  return useCallback(() => globalEventBus.clearHistory(), []);
}

src/lib/a4-autotuner.ts:
/**
 * ============================================================================
 * A4 Page Density Autotuner Engine (`a4-autotuner.ts`)
 * ============================================================================
 * 
 * Provides exact A4 visual density measurement and automated Content Balancing
 * to ensure every optimized resume fills EXACTLY 100% of a single A4 page —
 * neither underfilled (75%) nor overflowing (101%+).
 * 
 * Capabilities:
 *   1. getA4FillPercentage(resume) — returns visual density (e.g., 98.4%)
 *   2. autotuneA4Density(resume, jd, callbacks) — runs multi-step tuning loop:
 *      - If underfilled (<95%), expands bullets, summary & education modules
 *      - If overflowing (>100%), micro-condenses bullet wording to fit 100%
 *      - Guaranteed 1-page A4 precision
 * ============================================================================
 */

"use client";

import type { ResumeData, JobDescription } from "@/lib/types";
import { simulateLayoutHeight } from "@/lib/layout-simulator";
import { recordAI } from "@/lib/ai/flight-recorder";
import { getOptimizerDirective } from "@/lib/ai";

export interface AutotuneResult {
  resume: ResumeData;
  initialFillPercent: number;
  finalFillPercent: number;
  iterations: number;
  changes: string[];
}

/**
 * Calculates the visual fill percentage of a resume on an A4 page (0% to 120%+).
 * Target optimal range: 95.0% - 100.0%.
 */
export function getA4FillPercentage(resume: ResumeData): number {
  const sim = simulateLayoutHeight(resume);
  const printableHeight = sim.pageHeightPt - sim.marginHeightPt;
  const ratio = sim.contentHeightPt / printableHeight;
  return Math.min(125, Math.round(ratio * 1000) / 10);
}

/**
 * Autotunes a resume's content density to achieve ~98-100% single A4 page filling.
 */
export async function autotuneA4Density(
  resume: ResumeData,
  jd?: JobDescription | null,
  onProgress?: (message: string, fillPercent: number) => void
): Promise<AutotuneResult> {
  let currentResume = JSON.parse(JSON.stringify(resume)) as ResumeData;
  const initialFill = getA4FillPercentage(currentResume);
  const changes: string[] = [];
  let iterations = 0;
  const maxIterations = 3;

  onProgress?.(`Initial visual density: ${initialFill}% A4 page height`, initialFill);

  // Ideal target range: 94.0% to 98.0% (leaves 2-4% safety buffer for Word/DOCX line heights)
  // NOTE: getA4FillPercentage (layout-simulator) tends to over-report fill, so we
  // additionally check the accurate visible-char metric. Expand if EITHER says
  // we are under 94% (so genuinely thin resumes get filled), only stop on overflow.
  const { validatePageFill } = await import("./agents/page-balancer");
  let visibleUsage = 100;
  try {
    visibleUsage = validatePageFill(resume, null).pageUsage;
  } catch { /* non-fatal */ }
  if ((initialFill >= 94.0 && initialFill <= 98.0) || (visibleUsage >= 94.0 && visibleUsage <= 98.0)) {
    onProgress?.(`Resume is already perfectly tuned at ${Math.max(initialFill, visibleUsage)}% A4 density!`, initialFill);
    return {
      resume: currentResume,
      initialFillPercent: initialFill,
      finalFillPercent: initialFill,
      iterations: 0,
      changes: ["Already optimal A4 page density"],
    };
  }

  const jdContext = jd
    ? `Target Role: ${jd.title} at ${jd.company || "Employer"}. Keywords: ${(jd.keywords || []).slice(0, 15).join(", ")}`
    : "General Senior Professional";

  const directive = getOptimizerDirective();

  while (iterations < maxIterations) {
    const currentFill = getA4FillPercentage(currentResume);
    iterations++;

    if (currentFill >= 94.0 && currentFill <= 98.0) {
      onProgress?.(`Target density reached: ${currentFill}% A4 page height!`, currentFill);
      break;
    }

    if (currentFill < 94.0) {
      // Underfilled: Expand content to reach 95-98% density
      const deficitPercent = Math.round(96 - currentFill);
      onProgress?.(`Underfilled (${currentFill}%). Deficit: +${deficitPercent}%. Expanding content...`, currentFill);

      const prompt = `You are an elite ATS resume architect. The candidate's resume is underfilling the single A4 page (currently ${currentFill}% full, needs to be 98-100% full).

TASK: Expand the content to reach 98-100% A4 visual density.
${jdContext}

OPTIMIZATION DIRECTIVE:
${directive}

CURRENT RESUME DATA:
${JSON.stringify({
  summary: currentResume.summary,
  experience: currentResume.experience.map((e) => ({ id: e.id, title: e.title, company: e.company, bullets: e.bullets })),
  education: currentResume.education.map((e) => ({ id: e.id, degree: e.degree, institution: e.institution, highlights: e.highlights })),
})}

EXPANSION INSTRUCTIONS:
1. Deepen and enrich existing experience bullets by articulating candidate accomplishments and impact based STRICTLY on their actual role and company. NEVER invent duties or responsibilities from the job description (e.g. do not add airport ground handling duties to a medical laboratory or retail role).
2. NEVER invent fake percentages, metrics, or numbers unless already in the candidate's bullets.
3. Expand summary to 4-5 well-structured, factual sentences aligning candidate skills with the target domain.
4. Ensure education entries have comprehensive module highlights relevant to the candidate's actual field of study.
5. Keep all existing company names, degree titles, and employment dates strictly UNCHANGED.
6. Return ONLY a valid JSON object matching this schema:
{
  "summary": "expanded summary text...",
  "experience": [{"id":"...","bullets":["...","..."]}],
  "education": [{"id":"...","highlights":["Module1, Module2, Module3, ..."]}]
}`;

      try {
        const res = await recordAI({
          systemPrompt: "You are a professional resume writer. Return ONLY valid JSON.",
          userPrompt: prompt,
          maxTokens: 3500,
          temperature: 0.3,
          taskCategory: "document",
          agentType: "optimizer",
        });

        const jsonStr = (res.text || "").replace(/```json|```/g, "").trim();
        const data = JSON.parse(jsonStr);

        if (data) {
          if (data.summary) currentResume.summary = data.summary;
          if (Array.isArray(data.experience)) {
            currentResume.experience = currentResume.experience.map((e) => {
              const match = data.experience.find((x: any) => x.id === e.id);
              return match ? { ...e, bullets: match.bullets } : e;
            });
          }
          if (Array.isArray(data.education)) {
            currentResume.education = currentResume.education.map((e) => {
              const match = data.education.find((x: any) => x.id === e.id);
              return match ? { ...e, highlights: match.highlights } : e;
            });
          }
          changes.push(`Expanded content density (+${deficitPercent}%)`);
        }
      } catch (err: any) {
        onProgress?.(`Expansion attempt failed: ${err.message}`, currentFill);
        break;
      }
    } else {
      // Overflowing (>98%): Micro-condense to fit single A4 page
      const excessPercent = Math.round(currentFill - 96);
      onProgress?.(`Overflowing (${currentFill}%). Excess: -${excessPercent}%. Micro-condensing to fit 1 page...`, currentFill);

      const prompt = `You are an elite ATS resume architect. The candidate's resume slightly overflows 1 A4 page (currently ${currentFill}% full).

TASK: Condense wording by ~10-15% to guarantee it fits on EXACTLY 1 A4 page (98-100% full).
${jdContext}

CURRENT RESUME DATA:
${JSON.stringify({
  summary: currentResume.summary,
  experience: currentResume.experience.map((e) => ({ id: e.id, title: e.title, company: e.company, bullets: e.bullets })),
})}

CONDENSING INSTRUCTIONS:
1. Trim wordy introductory phrases while preserving ALL metrics, numbers, and key facts.
2. Keep bullet counts intact, but make each bullet 15-20% tighter.
3. Return ONLY a valid JSON object:
{
  "summary": "tightened summary...",
  "experience": [{"id":"...","bullets":["...","..."]}]
}`;

      try {
        const res = await recordAI({
          systemPrompt: "You are a professional resume writer. Return ONLY valid JSON.",
          userPrompt: prompt,
          maxTokens: 2500,
          temperature: 0.2,
          taskCategory: "document",
          agentType: "optimizer",
        });

        const jsonStr = (res.text || "").replace(/```json|```/g, "").trim();
        const data = JSON.parse(jsonStr);

        if (data) {
          if (data.summary) currentResume.summary = data.summary;
          if (Array.isArray(data.experience)) {
            currentResume.experience = currentResume.experience.map((e) => {
              const match = data.experience.find((x: any) => x.id === e.id);
              return match ? { ...e, bullets: match.bullets } : e;
            });
          }
          changes.push(`Micro-condensed text to fit single A4 page (-${excessPercent}%)`);
        }
      } catch (err: any) {
        onProgress?.(`Condensing attempt failed: ${err.message}`, currentFill);
        break;
      }
    }
  }

  const finalFill = getA4FillPercentage(currentResume);
  onProgress?.(`Autotune complete: ${initialFill}% → ${finalFill}% A4 visual density`, finalFill);

  return {
    resume: currentResume,
    initialFillPercent: initialFill,
    finalFillPercent: finalFill,
    iterations,
    changes,
  };
}

