// ============================================================================
// MemoryAgent — persists a user's career profile + history across sessions.
//
// Stores:
//   - skills, certifications, industries, target roles, preferred locations,
//     languages, salary expectations
//   - application history, optimization history, interview history
//
// Persistence:
//   - localStorage (`resumeai-memory-profile`) — survives refresh/logout/login
//   - Best-effort sync to D1 via the existing cloud API (future enhancement)
//
// The Supervisor and other agents read this profile to personalize their
// recommendations (e.g. the Career Coach recommends certifications aligned
// with the user's target roles; the Salary Agent uses the user's salary
// expectation as a baseline).
// ============================================================================

export interface UserProfile {
  // === Career profile (aggregated from all resumes + JDs the user has ever uploaded) ===
  skills: string[]; // unique, sorted by frequency
  certifications: string[];
  industries: string[]; // industries the user has worked in or applied to
  targetRoles: string[]; // roles the user is actively targeting
  preferredLocations: string[];
  languages: string[];
  salaryExpectations: { role: string; min: number; mid: number; max: number; currency: string }[];

  // === History ===
  applicationHistory: ApplicationEntry[];
  optimizationHistory: OptimizationEntry[];
  interviewHistory: InterviewEntry[];

  // === Writing Style Preferences ===
  manualOverrides?: { original: string; edited: string; timestamp: string }[];

  // === Metadata ===
  updatedAt: string;
}

export interface ApplicationEntry {
  id: string;
  company: string;
  role: string;
  status: "saved" | "applied" | "interview" | "assessment" | "offer" | "rejected" | "ghosted";
  appliedAt: string;
  notes?: string;
}

export interface OptimizationEntry {
  id: string;
  resumeName: string;
  jobTitle: string;
  company: string;
  atsBefore: number;
  atsAfter: number;
  createdAt: string;
}

export interface InterviewEntry {
  id: string;
  company: string;
  role: string;
  score: number;
  createdAt: string;
}

const MEMORY_KEY = "resumeai-memory-profile";

// ============================================================================
// Load / save
// ============================================================================

export function loadUserProfile(): UserProfile {
  if (typeof localStorage === "undefined") return createEmptyProfile();
  try {
    const raw = localStorage.getItem(MEMORY_KEY);
    if (!raw) return createEmptyProfile();
    const parsed = JSON.parse(raw);
    return { ...createEmptyProfile(), ...parsed };
  } catch {
    return createEmptyProfile();
  }
}

export function saveUserProfile(profile: UserProfile): void {
  if (typeof localStorage === "undefined") return;
  try {
    profile.updatedAt = new Date().toISOString();
    localStorage.setItem(MEMORY_KEY, JSON.stringify(profile));
  } catch (e) {
    console.warn("[MemoryAgent] Failed to save profile:", e);
  }
}

export function createEmptyProfile(): UserProfile {
  return {
    skills: [],
    certifications: [],
    industries: [],
    targetRoles: [],
    preferredLocations: [],
    languages: [],
    salaryExpectations: [],
    applicationHistory: [],
    optimizationHistory: [],
    interviewHistory: [],
    manualOverrides: [],
    updatedAt: new Date().toISOString(),
  };
}

// ============================================================================
// Aggregation — called whenever a resume is uploaded or a JD is parsed
// ============================================================================

/**
 * Merge skills/certs/languages from a resume into the user profile.
 * Deduplicates and sorts skills by frequency (most-used first).
 */
export function ingestResumeIntoMemory(profile: UserProfile, resume: { skills?: any[]; certifications?: any[]; languages?: any[]; name?: string }): UserProfile {
  const next = { ...profile };
  const skillFreq: Record<string, number> = {};
  for (const s of next.skills) skillFreq[s] = (skillFreq[s] || 0) + 1;
  for (const s of (resume.skills ?? [])) {
    const name = typeof s === "string" ? s : s?.name;
    if (name && typeof name === "string") skillFreq[name] = (skillFreq[name] || 0) + 1;
  }
  next.skills = Object.entries(skillFreq)
    .sort((a, b) => b[1] - a[1])
    .map(([s]) => s);

  const certSet = new Set(next.certifications);
  for (const c of (resume.certifications ?? [])) {
    const name = typeof c === "string" ? c : c?.name;
    if (name && typeof name === "string") certSet.add(name);
  }
  next.certifications = Array.from(certSet);

  const langSet = new Set(next.languages);
  for (const l of (resume.languages ?? [])) {
    const name = typeof l === "string" ? l : l?.name;
    if (name && typeof name === "string") langSet.add(name);
  }
  next.languages = Array.from(langSet);

  saveUserProfile(next);
  return next;
}

/**
 * Merge industry/company/role from a JD into the user profile.
 */
export function ingestJobIntoMemory(profile: UserProfile, jd: { title?: string; company?: string; location?: string }): UserProfile {
  const next = { ...profile };
  if (jd.title && !next.targetRoles.includes(jd.title)) {
    next.targetRoles = [jd.title, ...next.targetRoles].slice(0, 20);
  }
  if (jd.location && !next.preferredLocations.includes(jd.location)) {
    next.preferredLocations = [jd.location, ...next.preferredLocations].slice(0, 10);
  }
  saveUserProfile(next);
  return next;
}

/**
 * Record an optimization run in the user's history.
 */
export function recordOptimization(profile: UserProfile, entry: OptimizationEntry): UserProfile {
  const next = { ...profile, optimizationHistory: [entry, ...profile.optimizationHistory].slice(0, 50) };
  saveUserProfile(next);
  return next;
}

/**
 * Record an application in the user's history.
 */
export function recordApplication(profile: UserProfile, entry: ApplicationEntry): UserProfile {
  const next = { ...profile, applicationHistory: [entry, ...profile.applicationHistory].slice(0, 100) };
  saveUserProfile(next);
  return next;
}

/**
 * Record an interview in the user's history.
 */
export function recordInterview(profile: UserProfile, entry: InterviewEntry): UserProfile {
  const next = { ...profile, interviewHistory: [entry, ...profile.interviewHistory].slice(0, 50) };
  saveUserProfile(next);
  return next;
}

/**
 * RED TEST — Truthful optimizer failure diagnosis.
 *
 * Production trace (HEAD 0de936c): a real optimization run failed with the
 * USELESS nested message:
 *   "Optimization could not be completed after 4 validated attempts …
 *    Last error: Optimization could not be completed after 3 validated
 *    attempt(s) (bounded auto-heal ran between attempts). The original
 *    resume was NOT substituted as the result."
 *
 * Root cause: the locked pipeline throws OptimizerUnrecoverableError carrying
 * `attemptErrors: string[]` (one truthful diagnosis per inner attempt —
 * Guardian blocks, output-validation failures, provider classes…), but the
 * orchestrator's catch block stores only `e.message` (the generic wrapper)
 * and the final exhausted block reports THAT. The per-attempt diagnoses are
 * never surfaced — the UI (and the user) cannot see WHY the run failed.
 *
 * The fix composes the final failure report from the inner attemptErrors:
 * the LAST inner diagnosis (most recent, most relevant) becomes the reported
 * error; the fixed "AI providers unavailable" progress string is replaced by
 * a truthful one. These tests pin that behaviour.
 */
import { describe, it, expect } from "vitest";
import { composeOptimizerFailureReport } from "./optimizer-failure-report";

describe("composeOptimizerFailureReport", () => {
  it("surfaces the LAST inner attempt diagnosis instead of the generic nested message", () => {
    const report = composeOptimizerFailureReport({
      maxOptimizeAttempts: 4,
      optimizeError:
        "Optimization could not be completed after 3 validated attempt(s) (bounded auto-heal ran between attempts). The original resume was NOT substituted as the result.",
      lastFailureReason: null,
      innerAttemptErrors: [
        "Guardian BLOCKED: Experience section is empty",
        "Output validation failed: summary missing required sections",
        "All providers rate-limited (429) — no eligible engine in chain",
      ],
    });

    // The reported error is the most recent INNER diagnosis, not the generic wrapper.
    expect(report.lastErr).toContain("All providers rate-limited (429)");
    expect(report.lastErr).toContain("2 earlier inner attempt failure(s)");
    // Full message keeps the established format but ends with the REAL reason.
    expect(report.message).toContain("after 4 validated attempts");
    expect(report.message).toContain("Original resume NOT substituted");
    expect(report.message).toContain("Last error: All providers rate-limited (429)");
  });

  it("reports a single inner diagnosis without the 'earlier failures' suffix", () => {
    const report = composeOptimizerFailureReport({
      maxOptimizeAttempts: 4,
      optimizeError: "generic inner wrapper message",
      lastFailureReason: null,
      innerAttemptErrors: ["Guardian BLOCKED: Experience section is empty"],
    });

    expect(report.lastErr).toBe("Guardian BLOCKED: Experience section is empty");
    expect(report.lastErr).not.toContain("earlier inner attempt");
  });

  it("falls back to the caught error message when no inner diagnoses exist", () => {
    const report = composeOptimizerFailureReport({
      maxOptimizeAttempts: 4,
      optimizeError: "Guardian BLOCKED (standard path): Experience section is empty",
      lastFailureReason: null,
      innerAttemptErrors: [],
    });

    expect(report.lastErr).toBe("Guardian BLOCKED (standard path): Experience section is empty");
  });

  it("falls back to lastFailureReason when optimizeError is null", () => {
    const report = composeOptimizerFailureReport({
      maxOptimizeAttempts: 4,
      optimizeError: null,
      lastFailureReason: "content too short (412 chars)",
      innerAttemptErrors: [],
    });

    expect(report.lastErr).toBe("content too short (412 chars)");
  });

  it("never reports 'unknown error' when any diagnosis source is non-empty", () => {
    const report = composeOptimizerFailureReport({
      maxOptimizeAttempts: 4,
      optimizeError: null,
      lastFailureReason: null,
      innerAttemptErrors: ["", "  ", "provider timeout after 60s"],
    });

    // Blank strings are filtered; the real diagnosis survives.
    expect(report.lastErr).toContain("provider timeout after 60s");
    expect(report.lastErr).not.toBe("unknown error");
  });

  it("reports 'unknown error' only when every source is empty", () => {
    const report = composeOptimizerFailureReport({
      maxOptimizeAttempts: 4,
      optimizeError: null,
      lastFailureReason: null,
      innerAttemptErrors: [],
    });

    expect(report.lastErr).toBe("unknown error");
  });

  it("progress is truthful — never the fixed 'AI providers unavailable' string", () => {
    const withInner = composeOptimizerFailureReport({
      maxOptimizeAttempts: 4,
      optimizeError: "generic wrapper",
      lastFailureReason: null,
      innerAttemptErrors: ["Structure Guardian found 1 critical issue(s): Experience section is empty"],
    });
    expect(withInner.progress).toContain("Structure Guardian");
    expect(withInner.progress).not.toMatch(/AI providers? unavailable/i);

    const withoutInner = composeOptimizerFailureReport({
      maxOptimizeAttempts: 4,
      optimizeError: "provider chain exhausted",
      lastFailureReason: null,
      innerAttemptErrors: [],
    });
    expect(withoutInner.progress).toContain("provider chain exhausted");
    expect(withoutInner.progress).not.toMatch(/AI providers? unavailable/i);
  });
});

/**
 * Truthful optimizer failure report — pure composition helper.
 *
 * Production trace (HEAD 0de936c): a real optimization run failed with the
 * USELESS nested message:
 *   "Optimization could not be completed after 4 validated attempts …
 *    Last error: Optimization could not be completed after 3 validated
 *    attempt(s) (bounded auto-heal ran between attempts). The original
 *    resume was NOT substituted as the result."
 *
 * Why: the locked pipeline throws OptimizerUnrecoverableError carrying
 * `attemptErrors: string[]` — one truthful diagnosis per inner attempt
 * (Guardian blocks, output-validation failures, provider classes…) — but
 * the orchestrator's catch block stored only `e.message` (the generic
 * wrapper). The per-attempt diagnoses were never surfaced, so neither the
 * UI nor the user could see WHY the run failed.
 *
 * This helper composes the final failure report from every available
 * diagnosis source, most-recent-first in relevance:
 *   1. the LAST inner attempt diagnosis (most recent, most relevant),
 *      with a count of earlier inner failures (full list goes to console),
 *   2. else the caught error message,
 *   3. else the tracked failure reason,
 *   4. else "unknown error".
 *
 * It also produces a truthful progress string — replacing the stale fixed
 * "AI providers unavailable" emit that showed for Guardian/parser failures
 * and misled users into thinking their quota was exhausted.
 */

export interface ComposeOptimizerFailureReportInput {
  /** Outer orchestrator attempt budget (from the selected Pipeline Profile). */
  maxOptimizeAttempts: number;
  /** Message of the last error caught by the outer attempt loop. */
  optimizeError: string | null;
  /** Tracked failure reason from the previous attempt (strategy feedback). */
  lastFailureReason: string | null;
  /**
   * Per-attempt diagnoses captured from OptimizerUnrecoverableError thrown
   * by the locked pipeline (one entry per inner attempt, in order).
   */
  innerAttemptErrors: string[];
}

export interface OptimizerFailureReport {
  /** The single most informative diagnosis to report as "Last error". */
  lastErr: string;
  /** Full message for the typed recoverable error (established format). */
  message: string;
  /** Truthful progress-banner text (never a fixed provider-unavailable string). */
  progress: string;
}

const PROGRESS_MAX_CHARS = 200;

export function composeOptimizerFailureReport(
  input: ComposeOptimizerFailureReportInput,
): OptimizerFailureReport {
  const inner = (input.innerAttemptErrors ?? [])
    .map((s) => (typeof s === "string" ? s.trim() : ""))
    .filter((s) => s.length > 0);

  let lastErr: string;
  if (inner.length > 0) {
    const lastInner = inner[inner.length - 1];
    const earlierCount = inner.length - 1;
    lastErr =
      earlierCount > 0
        ? `${lastInner} (plus ${earlierCount} earlier inner attempt failure(s) — full list in console)`
        : lastInner;
  } else {
    lastErr = input.optimizeError || input.lastFailureReason || "unknown error";
  }

  const message =
    `Optimization could not be completed after ${input.maxOptimizeAttempts} validated attempts ` +
    `(auto-heal + strategy feedback between attempts). Original resume NOT substituted. ` +
    `Last error: ${lastErr}`;

  const fullProgress = `Optimization incomplete — last diagnosis: ${lastErr}`;
  const progress =
    fullProgress.length > PROGRESS_MAX_CHARS
      ? `${fullProgress.slice(0, PROGRESS_MAX_CHARS)}…`
      : fullProgress;

  return { lastErr, message, progress };
}

