// ============================================================================
// Provider Platform — cross-provider routing and execution layer.
//
// Provides a clean interface for pipeline agents to make AI calls with:
//   - Provider priority routing (primary → fallback chain)
//   - Circuit-breaker integration (skip unhealthy providers)
//   - Task-category-based provider filtering
//   - Execution metrics per provider
//
// Wraps callAI() — the existing provider dispatch layer. This module adds
// the routing rules, circuit-breaker awareness, and provider selection
// that pipeline agents need.
// ============================================================================

import { callAI, type AICallOptions, type AICallResult } from "../ai";
import { isProviderAvailable } from "../circuit-breaker";
import { useApp } from "../store";
import type { AIProvider } from "../types";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface ProviderRoute {
  providerId: string;
  modelName: string;
  isFallback: boolean;
}

export interface RoutedCallResult extends AICallResult {
  /** The provider that was actually used */
  usedProvider: ProviderRoute;
  /** All providers that were tried (in order) */
  attemptedRoutes: ProviderRoute[];
}

export interface ProviderPlatformConfig {
  /** Priority-ordered list of provider IDs to attempt */
  priorityOrder?: string[];
  /** Task category for provider filtering */
  taskCategory?: AICallOptions["taskCategory"];
  /** Circuit breaker: skip unhealthy providers */
  useCircuitBreaker?: boolean;
  /** Per-call timeout in ms */
  timeoutMs?: number;
}

// ---------------------------------------------------------------------------
// Provider Selection
// ---------------------------------------------------------------------------

/**
 * Build a priority-ordered list of provider routes.
 *
 * Priority:
 *   1. User's default provider
 *   2. Configured fallback providers (in order)
 *   3. Any other available providers
 *
 * Respects circuit breaker state when useCircuitBreaker=true.
 */
export function buildProviderRoutes(
  config?: ProviderPlatformConfig,
): ProviderRoute[] {
  const appState = useApp.getState();
  const settings = appState?.providerSettings;
  const providers: AIProvider[] = appState?.providers ?? [];
  const priorityOrder = config?.priorityOrder;
  const useCircuitBreaker = config?.useCircuitBreaker ?? true;

  const routes: ProviderRoute[] = [];

  // Helper: add a provider if available (respecting circuit breaker)
  const tryAdd = (providerId: string, isFallback: boolean) => {
    if (useCircuitBreaker && !isProviderAvailable(providerId)) return;
    if (routes.some((r) => r.providerId === providerId)) return; // dedupe

    const prov = providers.find((p) => p.id === providerId);
    if (!prov) return;

    routes.push({
      providerId: prov.id,
      modelName: prov.modelName ?? "",
      isFallback,
    });
  };

  // 1. Explicit priority order
  if (priorityOrder && priorityOrder.length > 0) {
    for (const pid of priorityOrder) tryAdd(pid, false);
    if (routes.length > 0) return routes;
  }

  // 2. User's default provider
  const defaultId = settings?.defaultProviderId;
  if (defaultId) tryAdd(defaultId, false);

  // 3. Fallback providers
  const fallbackIds: string[] = settings?.fallbackProviderIds ?? [];
  for (const fid of fallbackIds) tryAdd(fid, true);

  // 4. All other providers (as last resort fallbacks)
  for (const p of providers) {
    if (!routes.some((r) => r.providerId === p.id)) {
      tryAdd(p.id, true);
    }
  }

  return routes;
}

// ---------------------------------------------------------------------------
// Provider Call
// ---------------------------------------------------------------------------

/**
 * Make an AI call through the provider platform.
 *
 * Tries providers in priority order, falling back on failure.
 * Respects circuit breaker state and task category.
 *
 * @returns RoutedCallResult with the successful call and attempted routes
 * @throws If all providers fail
 */
export async function callWithRouting(
  prompt: { systemPrompt?: string; userPrompt: string },
  opts?: {
    maxTokens?: number;
    temperature?: number;
    /** Override the provider priority order */
    priorityOrder?: string[];
    /** Task category for provider filtering (defaults to "document") */
    taskCategory?: AICallOptions["taskCategory"];
    /** Skip circuit-breaker check */
    skipCircuitBreaker?: boolean;
    /** Per-call timeout */
    timeoutMs?: number;
    /** If true, this is the optimizer call (validates directive integrity) */
    isOptimizerCall?: boolean;
  },
): Promise<RoutedCallResult> {
  const routes = buildProviderRoutes({
    priorityOrder: opts?.priorityOrder,
    taskCategory: opts?.taskCategory ?? "document",
    useCircuitBreaker: !opts?.skipCircuitBreaker,
    timeoutMs: opts?.timeoutMs,
  });

  if (routes.length === 0) {
    throw new Error("No providers available");
  }

  const attemptedRoutes: ProviderRoute[] = [];
  let lastError: Error | undefined;

  for (const route of routes) {
    attemptedRoutes.push(route);

    try {
      // ROUTE PINNING FIX (directives #12/#16): the advertised route is the
      // route that must execute. Previously the providerId/model were NOT
      // passed to callAI — every iteration silently re-ran the ENTIRE router
      // chain, so attempts and usedProvider were misattributed and each
      // "route" multiplied into a full-chain attempt. The call is now pinned
      // to the exact provider (+ its declared model) per iteration.
      const result = await callAI({
        systemPrompt: prompt.systemPrompt,
        userPrompt: prompt.userPrompt,
        providerId: route.providerId,
        modelOverride: route.modelName || undefined,
        maxTokens: opts?.maxTokens,
        temperature: opts?.temperature,
        taskCategory: opts?.taskCategory ?? "document",
        timeoutMs: opts?.timeoutMs,
        isOptimizerCall: opts?.isOptimizerCall,
      });

      return {
        ...result,
        usedProvider: route,
        attemptedRoutes,
      };
    } catch (err) {
      lastError = err instanceof Error ? err : new Error(String(err));
      // Continue to next provider
    }
  }

  throw lastError ?? new Error("All providers failed");
}

/**
 * Make an AI call through the preferred/default provider (no fallback).
 * Useful for non-critical calls where failure is acceptable.
 */
export async function callDefaultProvider(
  prompt: { systemPrompt?: string; userPrompt: string },
  opts?: {
    maxTokens?: number;
    temperature?: number;
    timeoutMs?: number;
    taskCategory?: AICallOptions["taskCategory"];
    isOptimizerCall?: boolean;
  },
): Promise<RoutedCallResult> {
  const routes = buildProviderRoutes({ useCircuitBreaker: true });
  const primary = routes[0];

  if (!primary) {
    throw new Error("No provider available");
  }

  const result = await callAI({
    systemPrompt: prompt.systemPrompt,
    userPrompt: prompt.userPrompt,
    maxTokens: opts?.maxTokens,
    temperature: opts?.temperature,
    taskCategory: opts?.taskCategory ?? "document",
    timeoutMs: opts?.timeoutMs,
    isOptimizerCall: opts?.isOptimizerCall,
  });

  return {
    ...result,
    usedProvider: primary,
    attemptedRoutes: [primary],
  };
}

src/lib/agents/qa-agent.ts:
// ============================================================================
// Quality Assurance Agent — validates optimized resume output.
//
// Evolutionary upgrade of src/lib/output-validator.ts (runValidationPipeline).
// Adds:
//   - Factual consistency check (compares optimized resume against original
//     to detect fabricated employers, dates, metrics)
//   - Export quality check (verifies PDF render succeeds + 1 page)
//   - Professional tone check (wires in isProfessionalResume)
//   - Unified leak-pattern source (uses leak-patterns.ts)
//
// This module RE-EXPORTS the original runValidationPipeline for backward
// compatibility, and adds a new runQA() function with the richer checks.
// ============================================================================

import type { ResumeData, JobDescription } from "../types";
import type { JobIntelligence } from "../job-intelligence";
import { runValidationPipeline, type PipelineResult, type ValidationCheck } from "../output-validator";
import { isProfessionalResume, validateResumeForExport } from "../ai-response-processor";
import { validateResumeContent } from "../ai-error-filter";
import { detectLeaks, isClean } from "../leak-patterns";
import { isForbiddenSection } from "../keyword-banks";
import { exportResumePDF } from "../exporter";
import { formatPolicyForPrompt, type OptimizationPolicy, checkPolicyCompliance } from "../directive-policy";
import { validateSTAR, type STARValidationResult } from "../star-validator";

// ============================================================================
// Types
// ============================================================================

export interface QAResult extends PipelineResult {
  /** Factual consistency check — detects fabrication by comparing optimized vs original */
  factualConsistency?: FactualConsistencyResult;
  /** Export quality check — verifies PDF render succeeds + page count */
  exportQuality?: ExportQualityResult;
  /** Professional tone check — detects analysis artifacts in resume content */
  professionalTone?: ProfessionalToneResult;
  /** Directive compliance score — how well the output follows the OptimizationPolicy */
  directiveCompliance?: DirectiveComplianceResult;
  /** Programmatic STAR method validation — bullets, active verbs, metrics, entity protection */
  starValidation?: STARValidationResult;
  /** Overall confidence score (0-100) — used by the Reflection Agent trigger */
  confidence: number;
  /** Whether the Reflection Agent should be triggered */
  shouldReflect: boolean;
}

export interface FactualConsistencyResult {
  passed: boolean;
  /** Employers in the optimized resume that don't appear in the original (potential fabrication) */
  fabricatedEmployers: string[];
  /** Degrees/institutions in the optimized resume that don't appear in the original */
  fabricatedEducation: string[];
  /** Metrics/numbers in the optimized resume that don't appear in the original (potential fabrication) */
  fabricatedMetrics: string[];
  /** Certifications in the optimized resume that don't appear in the original */
  fabricatedCertifications: string[];
  /** Total issues found */
  issueCount: number;
  /** Explanation for the UI */
  explanation: string;
}

export interface ExportQualityResult {
  passed: boolean;
  /** Whether the PDF export succeeded */
  pdfExportSucceeded: boolean;
  /** Number of pages in the exported PDF (should be 1) */
  pageCount: number;
  /** Error message if export failed */
  error?: string;
  /** Explanation for the UI */
  explanation: string;
}

export interface ProfessionalToneResult {
  passed: boolean;
  /** Analysis artifacts detected (e.g. "The original resume lacks…", "ATS score") */
  artifactsFound: string[];
  /** Forbidden sections detected */
  forbiddenSectionsFound: string[];
  /** Leak patterns detected */
  leaksFound: string[];
  /** Explanation for the UI */
  explanation: string;
}

export interface DirectiveComplianceResult {
  complianceScore: number;
  passed: boolean;
  checks: { check: string; passed: boolean; detail?: string }[];
}

// ============================================================================
// Main entry point
// ============================================================================

/**
 * Run the full QA pipeline on an optimized resume.
 *
 * @param optimizedResume The AI-optimized resume to validate
 * @param jd Optional job description (for ATS + relevance checks)
 * @param ji Optional job intelligence (for relevance checks)
 * @param originalResume Optional original resume (for factual consistency check)
 * @param options { checkExport?: boolean, reflectionThreshold?: number } — whether to run the export quality
 *        check (default: false, slow); and the QA confidence below which the
 *        Reflection Agent triggers (default: 75; wired from the selected
 *        Pipeline Profile's validationThresholds.minConfidenceScore).
 */
export async function runQA(
  optimizedResume: ResumeData,
  jd?: JobDescription | null,
  ji?: JobIntelligence | null,
  originalResume?: ResumeData | null,
  options?: { checkExport?: boolean; reflectionThreshold?: number },
  optimizationPolicy?: OptimizationPolicy | null,
): Promise<QAResult> {
  // === Run the existing validation pipeline (7 checks) ===
  const basePipeline = runValidationPipeline(optimizedResume, jd ?? null, ji ?? null);

  // === Factual consistency (new — only if original resume provided) ===
  const factualConsistency = originalResume
    ? checkFactualConsistency(originalResume, optimizedResume)
    : undefined;

  // Diagnostic: log specific fabricated items so we can see exactly what
  // the AI hallucinated. This helps diagnose why the pipeline rejects results.
  if (factualConsistency && factualConsistency.issueCount > 0) {
    console.warn(
      `[QA] Factual consistency FAILED — ${factualConsistency.issueCount} issues:\n` +
      `  - Fabricated employers: [${factualConsistency.fabricatedEmployers.join(", ")}]\n` +
      `  - Fabricated education: [${factualConsistency.fabricatedEducation.join(", ")}]\n` +
      `  - Fabricated certifications: [${factualConsistency.fabricatedCertifications.join(", ")}]\n` +
      `  - Fabricated metrics: [${factualConsistency.fabricatedMetrics.join(", ")}]\n` +
      `  - Fabricated locations: [${(factualConsistency as any).fabricatedLocations?.join(", ") ?? ""}]\n` +
      `  - Fabricated languages: [${(factualConsistency as any).fabricatedLanguages?.join(", ") ?? ""}]\n` +
      `  - Contact changes: [${(factualConsistency as any).fabricatedContact?.join(", ") ?? ""}]`
    );
  }

  // === Professional tone (new — wires in isProfessionalResume + leak detection) ===
  const professionalTone = checkProfessionalTone(optimizedResume);

  // === Directive compliance (new — checks output against OptimizationPolicy) ===
  const directiveCompliance: DirectiveComplianceResult | undefined = optimizationPolicy && originalResume
    ? (() => {
        const { complianceScore, checks } = checkPolicyCompliance(optimizedResume, originalResume, optimizationPolicy);
        const passed = complianceScore >= 90;
        console.info(`[QA] Directive compliance score: ${complianceScore}/100${passed ? "" : " (BELOW THRESHOLD)"}`);
        if (!passed) console.warn("[QA] Policy violations:", checks.filter((c) => !c.passed).map((c) => `  - ${c.check}: ${c.detail ?? "failed"}`).join("\n"));
        return { complianceScore, passed, checks };
      })()
    : undefined;

  // === Export quality (new — optional, slow because it renders a PDF) ===
  const exportQuality = options?.checkExport
    ? await checkExportQuality(optimizedResume)
    : undefined;

  // === Build the combined checks list ===
  const checks: ValidationCheck[] = [...basePipeline.checks];

  // Add the new checks to the list
  if (factualConsistency) {
    checks.push({
      name: "Factual Consistency",
      passed: factualConsistency.passed,
      score: factualConsistency.issueCount === 0 ? 100 : Math.max(0, 100 - factualConsistency.issueCount * 15),
      details: factualConsistency.explanation,
      errors: factualConsistency.issueCount === 0 ? undefined : [
        ...factualConsistency.fabricatedEmployers.map((e) => `Fabricated employer: ${e}`),
        ...factualConsistency.fabricatedEducation.map((e) => `Fabricated education: ${e}`),
        ...factualConsistency.fabricatedMetrics.map((m) => `Fabricated metric: ${m}`),
        ...factualConsistency.fabricatedCertifications.map((c) => `Fabricated certification: ${c}`),
      ],
    });
  }

  if (professionalTone) {
    checks.push({
      name: "Professional Tone",
      passed: professionalTone.passed,
      score: professionalTone.passed ? 100 : Math.max(0, 100 - (professionalTone.artifactsFound.length + professionalTone.forbiddenSectionsFound.length + professionalTone.leaksFound.length) * 20),
      details: professionalTone.explanation,
      errors: professionalTone.passed ? undefined : [
        ...professionalTone.artifactsFound,
        ...professionalTone.forbiddenSectionsFound,
        ...professionalTone.leaksFound,
      ],
    });
  }

  if (exportQuality) {
    checks.push({
      name: "Export Quality",
      passed: exportQuality.passed,
      score: exportQuality.passed ? 100 : 0,
      details: exportQuality.explanation,
      errors: exportQuality.error ? [exportQuality.error] : undefined,
    });
  }

  if (directiveCompliance) {
    checks.push({
      name: "Directive Compliance",
      passed: directiveCompliance.passed,
      score: directiveCompliance.complianceScore,
      details: `Compliance score: ${directiveCompliance.complianceScore}/100 (threshold: 90). ${directiveCompliance.checks.filter((c) => !c.passed).length} check(s) failed.`,
      errors: directiveCompliance.checks.filter((c) => !c.passed).map((c) => c.detail ?? `${c.check} failed`),
    });
  }

  // === Programmatic STAR Validation (new — deterministic, no AI required) ===
  const starValidation: STARValidationResult = validateSTAR(optimizedResume, originalResume);
  if (starValidation.totalBullets > 0) {
    checks.push({
      name: "STAR Method Validation",
      passed: starValidation.passed,
      score: starValidation.score,
      details: starValidation.explanation,
      errors: starValidation.errors.length > 0 ? starValidation.errors : undefined,
    });
    if (!starValidation.passed) {
      console.warn(
        `[QA] STAR validation FAILED — ${starValidation.totalBullets - starValidation.passingBullets}/${starValidation.totalBullets} bullet(s) failed.\n` +
        `  - Passive/weak verbs: ${starValidation.passiveVerbCount}\n` +
        `  - Missing metrics: ${starValidation.noMetricCount}\n` +
        `  - Entity violations: ${starValidation.entityViolationCount}`
      );
    }
  }

  // === Compute overall confidence (0-100) ===
  // Confidence is the average of all check scores, weighted by importance
  const weights: Record<string, number> = {
    "Layout": 1,
    "Content Validation": 1.5,
    "Grammar": 1,
    "ATS Compatibility": 2,
    "Job Relevance": 1.5,
    "AI Leak Prevention": 2,
    "Page Fit": 1.5,
    "Factual Consistency": 2.5,
    "Professional Tone": 2,
    "Export Quality": 1.5,
    "Directive Compliance": 2.5,
    "STAR Method Validation": 2.5,
  };

  let totalWeight = 0;
  let weightedScore = 0;
  for (const check of checks) {
    const weight = weights[check.name] ?? 1;
    totalWeight += weight;
    weightedScore += (check.score ?? (check.passed ? 100 : 0)) * weight;
  }
  const confidence = totalWeight > 0 ? Math.round(weightedScore / totalWeight) : 0;

  // === Determine if Reflection Agent should trigger ===
  // Trigger if confidence < threshold OR any critical check failed.
  // The threshold comes from the selected Pipeline Profile
  // (validationThresholds.minConfidenceScore) — default 75 (pre-profile
  // behavior). Reflection should only run when there's a real quality
  // concern, not on every request.
  const reflectionThreshold = typeof options?.reflectionThreshold === "number" && Number.isFinite(options.reflectionThreshold)
    ? Math.min(100, Math.max(0, options.reflectionThreshold))
    : 75;
  const criticalFailures = checks.filter((c) => !c.passed && (weights[c.name] ?? 1) >= 2);
  const shouldReflect = confidence < reflectionThreshold || criticalFailures.length > 0;

  const allPassed = checks.every((c) => c.passed);

  return {
    ...basePipeline,
    checks,
    allPassed,
    factualConsistency,
    exportQuality,
    professionalTone,
    directiveCompliance,
    starValidation: starValidation.totalBullets > 0 ? starValidation : undefined,
    confidence,
    shouldReflect,
  };
}

// ============================================================================
// Factual Consistency Check
// ============================================================================

/**
 * Compare the optimized resume against the original to detect fabrication.
 *
 * Checks:
 *   - Employers in optimized that don't appear (fuzzy) in original
 *   - Degrees/institutions in optimized that don't appear in original
 *   - Metrics/numbers in optimized that don't appear in original
 *   - Certifications in optimized that don't appear in original
 *
 * This is the "preserve factual information, never invent" constraint from the spec.
 */
export function checkFactualConsistency(
  original: ResumeData,
  optimized: ResumeData
): FactualConsistencyResult {
  // === Build sets of original values (lowercased for fuzzy matching) ===
  const originalEmployers = new Set(
    original.experience.map((e) => e.company.toLowerCase().trim()).filter(Boolean)
  );
  const originalInstitutions = new Set(
    original.education.map((e) => e.institution.toLowerCase().trim()).filter(Boolean)
  );
  const originalDegrees = new Set(
    original.education.map((e) => e.degree.toLowerCase().trim()).filter(Boolean)
  );
  const originalCertifications = new Set(
    original.certifications.map((c) => c.name.toLowerCase().trim()).filter(Boolean)
  );
  // === NEW: locked fields — locations, languages, contact info ===
  const originalLocations = new Set(
    [
      original.contact.location?.toLowerCase().trim(),
      ...original.experience.map((e) => e.location?.toLowerCase().trim()),
      ...original.education.map((e) => e.location?.toLowerCase().trim()),
    ].filter(Boolean)
  );
  const originalLanguages = new Set(
    original.languages.map((l) => l.name.toLowerCase().trim()).filter(Boolean)
  );
  const originalEmail = original.contact.email?.toLowerCase().trim();
  const originalPhone = original.contact.phone?.toLowerCase().trim();
  const originalName = original.name?.toLowerCase().trim();

  // Extract all numbers/metrics from original (e.g. "40M+", "23%", "$1.2M", "200+")
  const originalText = JSON.stringify(original);
  const originalMetrics = new Set(
    (originalText.match(/\d+(?:\.\d+)?[%×xMKB+]?/g) ?? []).map((m) => m.toLowerCase())
  );

  // === Check optimized values against original sets ===
  const fabricatedEmployers: string[] = [];
  for (const e of optimized.experience) {
    const employer = e.company.toLowerCase().trim();
    if (!employer) continue;
    const found = Array.from(originalEmployers).some(
      (orig) => orig.includes(employer) || employer.includes(orig) || levenshtein(employer, orig) <= 3
    );
    if (!found) fabricatedEmployers.push(e.company);
  }

  const fabricatedEducation: string[] = [];
  for (const ed of optimized.education) {
    const institution = ed.institution.toLowerCase().trim();
    const degree = ed.degree.toLowerCase().trim();
    if (institution && !Array.from(originalInstitutions).some((o) => o.includes(institution) || institution.includes(o))) {
      fabricatedEducation.push(ed.institution);
    }
    if (degree && !Array.from(originalDegrees).some((o) => o.includes(degree) || degree.includes(o))) {
      fabricatedEducation.push(ed.degree);
    }
  }

  const fabricatedCertifications: string[] = [];
  for (const c of optimized.certifications) {
    const name = c.name.toLowerCase().trim();
    if (!name) continue;
    const found = Array.from(originalCertifications).some(
      (orig) => orig.includes(name) || name.includes(orig)
    );
    if (!found) fabricatedCertifications.push(c.name);
  }

  // === NEW: Check locations ===
  const fabricatedLocations: string[] = [];
  const optLocations = [
    optimized.contact.location?.toLowerCase().trim(),
    ...optimized.experience.map((e) => e.location?.toLowerCase().trim()),
    ...optimized.education.map((e) => e.location?.toLowerCase().trim()),
  ].filter(Boolean);
  for (const loc of optLocations) {
    if (!loc) continue;
    const found = Array.from(originalLocations).some(
      (orig) => typeof orig === "string" && (orig.includes(loc) || loc.includes(orig))
    );
    if (!found) fabricatedLocations.push(loc);
  }

  // === NEW: Check languages ===
  const fabricatedLanguages: string[] = [];
  for (const l of optimized.languages) {
    const name = l.name.toLowerCase().trim();
    if (!name) continue;
    if (!originalLanguages.has(name)) {
      fabricatedLanguages.push(l.name);
    }
  }

  // === NEW: Check contact info ===
  const fabricatedContact: string[] = [];
  if (optimized.contact.email && originalEmail && optimized.contact.email.toLowerCase().trim() !== originalEmail) {
    fabricatedContact.push(`Email changed: ${originalEmail} → ${optimized.contact.email}`);
  }
  if (optimized.contact.phone && originalPhone && optimized.contact.phone.toLowerCase().trim() !== originalPhone) {
    fabricatedContact.push(`Phone changed: ${originalPhone} → ${optimized.contact.phone}`);
  }
  if (optimized.name && originalName && optimized.name.toLowerCase().trim() !== originalName) {
    fabricatedContact.push(`Name changed: ${originalName} → ${optimized.name}`);
  }

  // Check optimized bullets for metrics not in original
  const fabricatedMetrics: string[] = [];
  const optimizedText = JSON.stringify(optimized);
  const optimizedMetricMatches = optimizedText.match(/\d+(?:\.\d+)?[%×xMKB+]?/g) ?? [];
  for (const metric of optimizedMetricMatches) {
    const lower = metric.toLowerCase();
    if (/^\d{4}$/.test(metric)) continue; // year
    if (parseInt(metric) < 5) continue; // small count
    if (!originalMetrics.has(lower)) {
      const found = Array.from(originalMetrics).some((o) => o.includes(lower) || lower.includes(o));
      if (!found) fabricatedMetrics.push(metric);
    }
  }
  const uniqueFabricatedMetrics = [...new Set(fabricatedMetrics)].slice(0, 10);

  const issueCount =
    fabricatedEmployers.length +
    fabricatedEducation.length +
    fabricatedCertifications.length +
    uniqueFabricatedMetrics.length +
    fabricatedLocations.length +
    fabricatedLanguages.length +
    fabricatedContact.length;

  const passed = issueCount === 0;

  let explanation: string;
  if (passed) {
    explanation = "All employers, education, certifications, metrics, locations, languages, and contact info in the optimized resume match the original. No fabrication detected.";
  } else {
    const parts: string[] = [];
    if (fabricatedEmployers.length) parts.push(`${fabricatedEmployers.length} employer(s): ${fabricatedEmployers.join(", ")}`);
    if (fabricatedEducation.length) parts.push(`${fabricatedEducation.length} education: ${fabricatedEducation.join(", ")}`);
    if (fabricatedCertifications.length) parts.push(`${fabricatedCertifications.length} cert(s): ${fabricatedCertifications.join(", ")}`);
    if (fabricatedLocations.length) parts.push(`${fabricatedLocations.length} location(s): ${fabricatedLocations.join(", ")}`);
    if (fabricatedLanguages.length) parts.push(`${fabricatedLanguages.length} language(s): ${fabricatedLanguages.join(", ")}`);
    if (fabricatedContact.length) parts.push(`${fabricatedContact.length} contact: ${fabricatedContact.join("; ")}`);
    if (uniqueFabricatedMetrics.length) parts.push(`${uniqueFabricatedMetrics.length} metric(s): ${uniqueFabricatedMetrics.join(", ")}`);
    explanation = `Hallucination detected: ${parts.join("; ")}`;
  }

  return {
    passed,
    fabricatedEmployers,
    fabricatedEducation,
    fabricatedMetrics: uniqueFabricatedMetrics,
    fabricatedCertifications,
    issueCount,
    explanation,
  };
}

// ============================================================================
// Professional Tone Check
// ============================================================================

/**
 * Check the resume for analysis artifacts, forbidden sections, and AI error leaks.
 *
 * Wires together:
 *   - isProfessionalResume (from ai-response-processor)
 *   - validateResumeContent (from ai-error-filter)
 *   - detectLeaks (from leak-patterns)
 *   - isForbiddenSection (from keyword-banks)
 */
export function checkProfessionalTone(resume: ResumeData): ProfessionalToneResult {
  const artifactsFound: string[] = [];
  const forbiddenSectionsFound: string[] = [];
  const leaksFound: string[] = [];

  // === Check professional tone ===
  const profCheck = isProfessionalResume(resume);
  if (!profCheck.professional) {
    artifactsFound.push(...profCheck.issues);
  }

  // === Check for AI error leaks ===
  const leakCheck = validateResumeContent(resume);
  if (!leakCheck.valid && leakCheck.errors) {
    leaksFound.push(...leakCheck.errors);
  }

  // === Check all text fields for leak patterns ===
  const allText = [
    resume.name, resume.headline, resume.summary,
    ...resume.experience.flatMap((e) => [e.title, e.company, e.location, ...e.bullets]),
    ...resume.education.flatMap((e) => [e.degree, e.institution, ...(e.highlights ?? [])]),
    ...resume.skills.map((s) => s.name),
    ...resume.languages.map((l) => l.name),
    ...resume.certifications.map((c) => c.name),
    ...resume.projects.map((p) => p.name + " " + (p.description ?? "")),
  ].filter(Boolean) as string[];

  for (const text of allText) {
    const leaks = detectLeaks(text);
    if (leaks.length > 0) {
      leaksFound.push(...leaks.slice(0, 2)); // limit per field
    }
  }

  // === Check section names for forbidden sections ===
  // The resume doesn't have explicit section objects, but we check the summary
  // and any text that looks like a section header
  const sectionLikeTexts = [
    resume.summary,
    resume.headline,
    ...resume.experience.map((e) => e.title),
    ...resume.education.map((e) => e.degree),
  ].filter(Boolean) as string[];

  for (const text of sectionLikeTexts) {
    if (isForbiddenSection(text)) {
      forbiddenSectionsFound.push(text);
    }
  }

  const issueCount = artifactsFound.length + forbiddenSectionsFound.length + leaksFound.length;
  const passed = issueCount === 0;

  let explanation: string;
  if (passed) {
    explanation = "Resume content is professional, clean, and free of analysis artifacts or AI error leaks.";
  } else {
    const parts: string[] = [];
    if (artifactsFound.length) parts.push(`${artifactsFound.length} analysis artifact(s)`);
    if (forbiddenSectionsFound.length) parts.push(`${forbiddenSectionsFound.length} forbidden section(s)`);
    if (leaksFound.length) parts.push(`${leaksFound.length} AI leak(s)`);
    explanation = `Professional tone issues detected: ${parts.join(", ")}. The resume contains content that should not appear in a professional document.`;
  }

  return {
    passed,
    artifactsFound,
    forbiddenSectionsFound,
    leaksFound,
    explanation,
  };
}

// ============================================================================
// Export Quality Check
// ============================================================================

/**
 * Verify the resume can be exported as a single-page PDF.
 *
 * This check actually calls the PDF exporter and verifies:
 *   - Export succeeds (no errors)
 *   - Page count is exactly 1
 *
 * This is slow (renders a PDF) so it's optional.
 */
export async function checkExportQuality(resume: ResumeData): Promise<ExportQualityResult> {
  try {
    const result = await exportResumePDF(resume, { enforceOnePage: true });

    if (!result.ok) {
      return {
        passed: false,
        pdfExportSucceeded: false,
        pageCount: result.pages,
        error: result.error,
        explanation: `PDF export failed: ${result.error ?? "unknown error"}. The resume cannot be exported in its current state.`,
      };
    }

    const passed = result.pages === 1;
    return {
      passed,
      pdfExportSucceeded: true,
      pageCount: result.pages,
      explanation: passed
        ? "PDF export succeeded — resume fits on exactly 1 A4 page."
        : `PDF export succeeded but produced ${result.pages} pages. The resume should fit on 1 page.`,
    };
  } catch (e: any) {
    return {
      passed: false,
      pdfExportSucceeded: false,
      pageCount: 0,
      error: e?.message ?? "Unknown export error",
      explanation: `PDF export threw an exception: ${e?.message ?? "unknown error"}.`,
    };
  }
}

// ============================================================================
// Helper: Levenshtein distance (for fuzzy string matching)
// ============================================================================

/**
 * Compute the Levenshtein distance between two strings.
 * Used for fuzzy employer/institution matching (e.g. "Google" vs "Google LLC").
 */
function levenshtein(a: string, b: string): number {
  if (a === b) return 0;
  if (!a.length) return b.length;
  if (!b.length) return a.length;

  const matrix: number[][] = [];
  for (let i = 0; i <= b.length; i++) matrix[i] = [i];
  for (let j = 0; j <= a.length; j++) matrix[0][j] = j;

  for (let i = 1; i <= b.length; i++) {
    for (let j = 1; j <= a.length; j++) {
      if (b.charAt(i - 1) === a.charAt(j - 1)) {
        matrix[i][j] = matrix[i - 1][j - 1];
      } else {
        matrix[i][j] = Math.min(
          matrix[i - 1][j - 1] + 1, // substitution
          matrix[i][j - 1] + 1,     // insertion
          matrix[i - 1][j] + 1       // deletion
        );
      }
    }
  }

  return matrix[b.length][a.length];
}

// ============================================================================
// Re-export the original pipeline for backward compatibility
// ============================================================================

export { runValidationPipeline, type PipelineResult, type ValidationCheck } from "../output-validator";

