import { describe, it, expect } from "vitest";
import { PromptBuilder, buildPrompt, toAICallOptions, serializePrompt } from "./prompt-builder";

describe("PromptBuilder", () => {
  it("composes system + user into AICallOptions-shaped output", () => {
    const built = new PromptBuilder({ scope: "cover-letter", feature: "Cover Letter" })
      .system("You are a writer.")
      .user("Write a letter.")
      .build();
    expect(built.systemPrompt).toBe("You are a writer.");
    expect(built.userPrompt).toBe("Write a letter.");
    expect(built.promptVersion).toBe("8.1.3.2A");
    expect(built.size).toBeGreaterThan(0);
    expect(built.assemblyMs).toBeGreaterThanOrEqual(0);
    expect(built.source).toBe("PromptBuilder");
  });

  it("does NOT change prompt wording", () => {
    const sys = "System: keep this exact text. {curly braces} and @@@ markers";
    const usr = "User: also exact. With {{placeholders}} that must remain literal.";
    const built = new PromptBuilder().system(sys).user(usr).build();
    expect(built.systemPrompt).toBe(sys);
    expect(built.userPrompt).toBe(usr);
  });

  it("interpolates only when variables are provided", () => {
    const built = new PromptBuilder({ variables: { name: "Ada" } })
      .system("Hello {{name}}")
      .user("Hi {{name}}")
      .build();
    expect(built.systemPrompt).toBe("Hello Ada");
    expect(built.userPrompt).toBe("Hi Ada");

    // Without variables, braces are preserved verbatim (no accidental mutation).
    const literal = new PromptBuilder().user("Hi {{name}}").build();
    expect(literal.userPrompt).toBe("Hi {{name}}");
  });

  it("folds developer role into system on assembly", () => {
    const built = new PromptBuilder()
      .system("SYS")
      .developer("DEV")
      .user("USR")
      .build();
    expect(built.systemPrompt).toBe("SYS\n\nDEV");
    expect(built.userPrompt).toBe("USR");
  });

  it("produces multi-turn messages when requested", () => {
    const built = new PromptBuilder()
      .system("SYS")
      .user("first")
      .assistant("reply")
      .user("second")
      .asMessages()
      .build();
    expect(built.messages?.map((m) => m.role)).toEqual(["system", "user", "assistant", "user"]);
    expect(built.messages?.[1].content).toBe("first");
  });

  it("validates structure and reports warnings", () => {
    const empty = new PromptBuilder();
    const v = empty.validate();
    expect(v.ok).toBe(false);
    expect(v.warnings.length).toBeGreaterThan(0);

    const ok = new PromptBuilder().user("hi").validate();
    expect(ok.ok).toBe(true);
  });

  it("produces a stable hash for identical content", () => {
    const a = buildPrompt("S", "U");
    const b = buildPrompt("S", "U");
    expect(a.promptHash).toBe(b.promptHash);
    const c = buildPrompt("S", "U2");
    expect(c.promptHash).not.toBe(a.promptHash);
  });

  it("maps onto AICallOptions via toAICallOptions", () => {
    const built = new PromptBuilder().user("x").build();
    const opts = toAICallOptions(built);
    expect(opts.userPrompt).toBe("x");
  });

  it("serializes without secrets", () => {
    const built = new PromptBuilder({ scope: "resume-builder", tags: ["t1"] }).user("x").build();
    const s = serializePrompt(built);
    expect(s).not.toContain("x"); // payload content not in the diagnostic summary
    expect(s).toContain(built.promptHash);
  });
});

src/lib/ai/prompt-builder.ts:
// ============================================================================
// Shared Prompt Builder — Phase 8.1.3.2A
//
// ONE reusable prompt-assembly abstraction for the Enterprise AI Core.
//
// MANDATE:
//   - This standardizes prompt ASSEMBLY only. It NEVER changes prompt wording.
//   - Feature-specific prompt templates remain the caller's responsibility;
//     this builder just composes the pieces (system/user/developer/fragments)
//     into the shape `recordAI`/`callAIRaw` already consume.
//   - It performs NO AI execution and NO business logic.
//   - It is additive and opt-in: existing inline prompt construction keeps
//     working unchanged. Features may migrate to this builder incrementally.
//
// Output contract: `build()` returns an object whose `systemPrompt`/`userPrompt`/
// `messages` map 1:1 onto `AICallOptions`, so a feature can do:
//     const p = new PromptBuilder({ scope: "cover-letter" }).system(...).user(...).build();
//     await recordAI({ ...p.toAICallOptions(), ...config });
// ============================================================================

import { hashString } from "./flight-recorder";
import type { FlightScope } from "./flight-recorder";
import type { AICallOptions } from "@/lib/ai";

// ----------------------------------------------------------------------------
// Types
// ----------------------------------------------------------------------------

export type PromptRole = "system" | "developer" | "user" | "assistant";

/** A single composable piece of a prompt. */
export interface PromptFragment {
  role: PromptRole;
  content: string;
  /** Optional label for diagnostics (e.g. "directive", "resume-context"). */
  tag?: string;
}

export interface PromptBuilderOptions {
  /** Feature scope — mirrors the Flight Recorder scope enum. */
  scope?: FlightScope;
  /** Human feature label, e.g. "Cover Letter". */
  feature?: string;
  /** Pinned prompt version so replay can detect drift. */
  version?: string;
  /** Free-form tags for diagnostics/filtering. */
  tags?: string[];
  /**
   * Variables available for interpolation via `{{name}}` placeholders.
   * Interpolation is OPT-IN per fragment (call `.interpolate()` or pass
   * `interpolate: true`). By default NO substitution happens, so existing
   * literal prompts (which may legitimately contain braces) are untouched.
   */
  variables?: Record<string, string | number | boolean>;
}

/** The assembled, immutable result. */
export interface BuiltPrompt {
  systemPrompt?: string;
  /** "developer" role is folded into the system prompt for providers that
   *  don't support a separate developer role (all current adapters). It is
   *  appended AFTER the system content, separated by a blank line. */
  userPrompt: string;
  messages?: AICallOptions["messages"];
  // Diagnostics (internal only)
  promptVersion: string;
  promptHash: string;
  scope?: FlightScope;
  feature?: string;
  tags: string[];
  fragments: PromptFragment[];
  /** Total assembled character length. */
  size: number;
  /** Wall-clock assembly time in ms. */
  assemblyMs: number;
  source: "PromptBuilder";
}

const DEFAULT_VERSION = "8.1.3.2A";

// ----------------------------------------------------------------------------
// Builder
// ----------------------------------------------------------------------------

export class PromptBuilder {
  private fragments: PromptFragment[] = [];
  private opts: PromptBuilderOptions;
  private useMessages = false;

  constructor(opts: PromptBuilderOptions = {}) {
    this.opts = opts;
  }

  /** Add a system-role fragment. */
  system(content: string, tag = "system"): this {
    return this.add({ role: "system", content, tag });
  }

  /** Add a developer-role fragment (folded into system on assembly). */
  developer(content: string, tag = "developer"): this {
    return this.add({ role: "developer", content, tag });
  }

  /** Add a user-role fragment. */
  user(content: string, tag = "user"): this {
    return this.add({ role: "user", content, tag });
  }

  /** Add an assistant-role fragment (only meaningful in messages mode). */
  assistant(content: string, tag = "assistant"): this {
    this.useMessages = true;
    return this.add({ role: "assistant", content, tag });
  }

  /** Add an arbitrary fragment. */
  add(fragment: PromptFragment): this {
    this.fragments.push(fragment);
    return this;
  }

  /** Compose fragments from another builder or a fragment list. */
  compose(other: PromptBuilder | PromptFragment[]): this {
    const frags = Array.isArray(other) ? other : other.fragments;
    this.fragments.push(...frags);
    if (!Array.isArray(other) && other.useMessages) this.useMessages = true;
    return this;
  }

  /** Force multi-turn message output (preserves assistant turns). */
  asMessages(): this {
    this.useMessages = true;
    return this;
  }

  /**
   * Interpolate `{{name}}` placeholders using the builder's `variables`.
   * OPT-IN — only affects fragments added before this call is applied at build.
   */
  private interpolate(text: string): string {
    const vars = this.opts.variables;
    if (!vars) return text;
    return text.replace(/\{\{\s*([a-zA-Z0-9_]+)\s*\}\}/g, (m, key) =>
      key in vars ? String(vars[key]) : m,
    );
  }

  /** Validate the prompt before assembly. Throws on structural problems. */
  validate(): { ok: boolean; warnings: string[] } {
    const warnings: string[] = [];
    if (this.fragments.length === 0) warnings.push("No fragments added.");
    const hasUser = this.fragments.some((f) => f.role === "user");
    if (!hasUser) warnings.push("No user-role fragment — most providers require a user turn.");
    for (const f of this.fragments) {
      if (typeof f.content !== "string") warnings.push(`Fragment "${f.tag}" content is not a string.`);
    }
    return { ok: warnings.length === 0, warnings };
  }

  /** Assemble into an immutable BuiltPrompt. */
  build(): BuiltPrompt {
    const t0 = performance.now();
    const doInterp = !!this.opts.variables;
    const frags = this.fragments.map((f) =>
      doInterp ? { ...f, content: this.interpolate(f.content) } : f,
    );

    let systemPrompt: string | undefined;
    let userPrompt = "";
    let messages: AICallOptions["messages"] | undefined;

    if (this.useMessages) {
      // Multi-turn: map developer→system, keep order.
      messages = frags.map((f) => ({
        role: (f.role === "developer" ? "system" : f.role) as "system" | "user" | "assistant",
        content: f.content,
      }));
      userPrompt = frags.filter((f) => f.role === "user").map((f) => f.content).join("\n").trim();
    } else {
      const systemParts = frags.filter((f) => f.role === "system").map((f) => f.content);
      const devParts = frags.filter((f) => f.role === "developer").map((f) => f.content);
      const userParts = frags.filter((f) => f.role === "user").map((f) => f.content);
      const sysAll = [...systemParts, ...devParts].filter(Boolean);
      systemPrompt = sysAll.length ? sysAll.join("\n\n") : undefined;
      userPrompt = userParts.join("\n\n");
    }

    const assembled = (systemPrompt ?? "") + "�" + (messages ? JSON.stringify(messages) : userPrompt);
    const t1 = performance.now();

    return {
      systemPrompt,
      userPrompt,
      messages,
      promptVersion: this.opts.version ?? DEFAULT_VERSION,
      promptHash: hashString(assembled),
      scope: this.opts.scope,
      feature: this.opts.feature,
      tags: this.opts.tags ?? [],
      fragments: frags,
      size: assembled.length - 1, // minus the � separator
      assemblyMs: t1 - t0,
      source: "PromptBuilder",
    };
  }
}

// ----------------------------------------------------------------------------
// Convenience: map a BuiltPrompt onto AICallOptions fields.
// ----------------------------------------------------------------------------

export function toAICallOptions(built: BuiltPrompt): Pick<AICallOptions, "systemPrompt" | "userPrompt" | "messages"> {
  if (built.messages) {
    return { messages: built.messages, userPrompt: built.userPrompt };
  }
  return { systemPrompt: built.systemPrompt, userPrompt: built.userPrompt };
}

/** One-liner for the common system+user case. */
export function buildPrompt(
  systemPrompt: string | undefined,
  userPrompt: string,
  opts: PromptBuilderOptions = {},
): BuiltPrompt {
  const b = new PromptBuilder(opts);
  if (systemPrompt) b.system(systemPrompt);
  b.user(userPrompt);
  return b.build();
}

/** Serialize a BuiltPrompt for diagnostics/replay (no secrets). */
export function serializePrompt(built: BuiltPrompt): string {
  return JSON.stringify({
    version: built.promptVersion,
    hash: built.promptHash,
    scope: built.scope,
    feature: built.feature,
    tags: built.tags,
    size: built.size,
    fragmentTags: built.fragments.map((f) => `${f.role}:${f.tag ?? ""}`),
  });
}

