// ============================================================================
// Task 17 — DirectProbePolicy unit tests.
//
// The policy gates ProviderManager.testConnection's "direct client IP probe"
// (browser fetch straight to the provider URL when the /api/providers/test
// proxy reports 429). Regression context: testing the DEMOTED opencode zen
// row spammed the console with unavoidable CORS preflight errors — the probe
// can never succeed against opencode.ai (no Access-Control-Allow-Origin) and
// demoted providers are excluded from the live chain anyway.
// ============================================================================

import { describe, it, expect, vi, afterEach } from "vitest";
import {
  shouldAttemptDirectProbe,
  extractProbeHost,
  safeLocalStorage,
  loadBlockedProbeHosts,
  rememberBlockedProbeHost,
  clearBlockedProbeHost,
  DIRECT_PROBE_BLOCK_TTL_MS,
} from "./direct-probe-policy";

afterEach(() => {
  delete (globalThis as any).window;
  vi.restoreAllMocks();
});

const baseCtx = (overrides: Partial<Parameters<typeof shouldAttemptDirectProbe>[0]> = {}) => ({
  rateLimited: true,
  providerIsActive: true,
  baseUrl: "https://api.example.com/v1",
  isBrowser: true,
  blockedHosts: new Set<string>(),
  ...overrides,
});

describe("extractProbeHost", () => {
  it("extracts the hostname from a normal base URL", () => {
    expect(extractProbeHost("https://opencode.ai/zen/v1")).toBe("opencode.ai");
    expect(extractProbeHost("https://api.mistral.ai/v1/")).toBe("api.mistral.ai");
  });

  it("normalizes case", () => {
    expect(extractProbeHost("https://OpenCode.AI/zen/v1")).toBe("opencode.ai");
  });

  it("returns null for missing / unparseable URLs", () => {
    expect(extractProbeHost(undefined)).toBeNull();
    expect(extractProbeHost("")).toBeNull();
    expect(extractProbeHost("ht tp://broken")).toBeNull();
  });

  it("accepts bare host:port forms", () => {
    expect(extractProbeHost("api.example.com/v1")).toBe("api.example.com");
  });
});

describe("shouldAttemptDirectProbe", () => {
  it("probes only when the proxy reported 429", () => {
    expect(shouldAttemptDirectProbe(baseCtx({ rateLimited: false }))).toBe(false);
    expect(shouldAttemptDirectProbe(baseCtx())).toBe(true);
  });

  it("never probes outside a browser", () => {
    expect(shouldAttemptDirectProbe(baseCtx({ isBrowser: false }))).toBe(false);
  });

  it("REGRESSION: never probes a demoted (isActive = false) provider — the opencode zen CORS-noise case", () => {
    expect(shouldAttemptDirectProbe(baseCtx({ providerIsActive: false }))).toBe(false);
  });

  it("treats isActive undefined (legacy rows) as active", () => {
    expect(shouldAttemptDirectProbe(baseCtx({ providerIsActive: undefined as any }))).toBe(true);
  });

  it("refuses to probe without a usable baseUrl", () => {
    expect(shouldAttemptDirectProbe(baseCtx({ baseUrl: undefined }))).toBe(false);
  });

  it("never probes localhost — same-machine endpoints need no IP rescue", () => {
    expect(shouldAttemptDirectProbe(baseCtx({ baseUrl: "http://localhost:11434/v1" }))).toBe(false);
    expect(shouldAttemptDirectProbe(baseCtx({ baseUrl: "http://127.0.0.1:8080/v1" }))).toBe(false);
  });

  it("skips hosts remembered as CORS/network-hostile", () => {
    expect(shouldAttemptDirectProbe(baseCtx({ blockedHosts: new Set(["api.example.com"]) }))).toBe(false);
  });
});

describe("blocked-host memory (localStorage, TTL)", () => {
  it("has a bounded TTL (24h)", () => {
    expect(DIRECT_PROBE_BLOCK_TTL_MS).toBe(24 * 60 * 60 * 1000);
  });

  it("returns an empty set without storage or with empty storage", () => {
    expect(loadBlockedProbeHosts(null)).toEqual(new Set());
    const empty = fakeStorage();
    expect(loadBlockedProbeHosts(empty)).toEqual(new Set());
  });

  it("keeps entries inside the TTL and drops expired ones", () => {
    const store = fakeStorage();
    const now = 1_700_000_000_000;
    store.setItem(
      "directProbe.corsBlockedHosts",
      JSON.stringify({ "fresh.example.com": now - 1000, "stale.example.com": now - DIRECT_PROBE_BLOCK_TTL_MS - 1000 })
    );
    expect(loadBlockedProbeHosts(store, now)).toEqual(new Set(["fresh.example.com"]));
  });

  it("treats corrupt JSON and non-numeric timestamps as empty", () => {
    const store = fakeStorage();
    store.setItem("directProbe.corsBlockedHosts", "{not json");
    expect(loadBlockedProbeHosts(store)).toEqual(new Set());
    store.setItem("directProbe.corsBlockedHosts", JSON.stringify({ "bad.example.com": "oops" }));
    expect(loadBlockedProbeHosts(store)).toEqual(new Set());
  });

  it("rememberBlockedProbeHost merges and persists; clearBlockedProbeHost removes", () => {
    const store = fakeStorage();
    const now = 1_700_000_000_000;
    rememberBlockedProbeHost(store, "opencode.ai", now);
    rememberBlockedProbeHost(store, "Other.Example.COM", now + 5);
    expect(loadBlockedProbeHosts(store, now + 10)).toEqual(new Set(["opencode.ai", "other.example.com"]));

    clearBlockedProbeHost(store, "opencode.ai");
    expect(loadBlockedProbeHosts(store, now + 10)).toEqual(new Set(["other.example.com"]));

    // clearing an absent host is a no-op; null storage never throws
    expect(() => clearBlockedProbeHost(store, "absent.example.com")).not.toThrow();
    expect(() => rememberBlockedProbeHost(null, "x.example.com")).not.toThrow();
    expect(() => clearBlockedProbeHost(null, "x.example.com")).not.toThrow();
  });

  it("overwrites a corrupt payload instead of throwing", () => {
    const store = fakeStorage();
    store.setItem("directProbe.corsBlockedHosts", "{corrupt");
    const now = 1_700_000_000_000;
    expect(() => rememberBlockedProbeHost(store, "opencode.ai", now)).not.toThrow();
    expect(loadBlockedProbeHosts(store, now + 1000)).toEqual(new Set(["opencode.ai"]));
  });

  it("safeLocalStorage returns null without a window and works when one exists", () => {
    expect(safeLocalStorage()).toBeNull();
    (globalThis as any).window = { localStorage: fakeStorage() };
    expect(safeLocalStorage()).toBe((globalThis as any).window.localStorage);
  });
});

// ---------------------------------------------------------------------------
// Minimal in-memory Storage
// ---------------------------------------------------------------------------
function fakeStorage(): Storage {
  const map = new Map<string, string>();
  return {
    get length() { return map.size; },
    clear: () => map.clear(),
    getItem: (k: string) => (map.has(k) ? map.get(k)! : null),
    key: (i: number) => Array.from(map.keys())[i] ?? null,
    removeItem: (k: string) => { map.delete(k); },
    setItem: (k: string, v: string) => { map.set(k, String(v)); },
  } as Storage;
}

// DirectProbePolicy — decides whether ProviderManager.testConnection may
// attempt the "direct client IP probe" fallback (a browser fetch straight to
// the provider URL) when the /api/providers/test proxy reports HTTP 429.
//
// WHY THIS EXISTS
// The proxy egresses from shared Cloudflare Pages IPs whose free-tier quotas
// are drained by other tenants; a browser probe uses the USER's residential
// IP and can succeed for CORS-enabled providers (e.g. Google Generative
// Language API). Commit 5ff64b42 introduced it for exactly that rescue path.
//
// THE PROBLEM IT CAUSES
// For CORS-hostile providers (opencode.ai returns no Access-Control-Allow-
// Origin) the probe can NEVER succeed, and every failed preflight is logged
// BY THE BROWSER ITSELF — noise that cannot be suppressed from JavaScript.
// Users testing a provider row then see alarming `net::ERR_FAILED` +
// "blocked by CORS policy" stacks for a fallback that was always destined
// to fail.
//
// THE RULES (pure, testable)
// 1. Only probe when the proxy explicitly reported rateLimited (429).
// 2. Only probe in a real browser (the code path is client-only anyway).
// 3. NEVER probe a demoted provider (isActive = false) — it is excluded from
//    the live routing chain, so a residential-IP rescue is pointless noise.
// 4. Never probe localhost (same-machine endpoints don't need an IP rescue).
// 5. Never re-probe a host that already failed with a network/CORS error:
//    failures are remembered in localStorage with a TTL, so the console
//    noise happens at most once per host per window. A successful probe
//    clears the memory so a provider that later ships CORS headers is
//    rescued again.

/** How long a failed-probe host stays remembered. 24h bounds the damage of
 * mis-remembering a host that merely had a transient outage (a network
 * failure and a CORS rejection are indistinguishable TypeError("Failed to
 * fetch") from the caller's perspective). */
export const DIRECT_PROBE_BLOCK_TTL_MS = 24 * 60 * 60 * 1000;

const STORAGE_KEY = "directProbe.corsBlockedHosts";

export interface DirectProbeContext {
  /** The /api/providers/test proxy reported HTTP 429 (rateLimited). */
  rateLimited: boolean;
  /** provider.isActive — undefined counts as active (legacy rows). */
  providerIsActive: boolean;
  /** provider.baseUrl — the host the probe would hit. */
  baseUrl?: string;
  /** typeof window !== "undefined". */
  isBrowser: boolean;
  /** Hosts remembered as CORS/network-hostile (not yet expired). */
  blockedHosts: ReadonlySet<string>;
}

/** Extract the hostname from a base URL; null when absent/unparseable. */
export function extractProbeHost(baseUrl?: string): string | null {
  if (!baseUrl || typeof baseUrl !== "string") return null;
  try {
    const url = new URL(baseUrl.includes("://") ? baseUrl : `https://${baseUrl}`);
    return url.hostname.toLowerCase() || null;
  } catch {
    return null;
  }
}

/** The full go / no-go decision for the browser-direct probe. */
export function shouldAttemptDirectProbe(ctx: DirectProbeContext): boolean {
  if (!ctx.rateLimited) return false;
  if (!ctx.isBrowser) return false;
  // Demoted providers are excluded from the live chain — probing them from
  // the user's residential IP cannot change any runtime outcome, and for
  // CORS-hostile upstreams (opencode.ai) it only spams the console.
  if (ctx.providerIsActive === false) return false;
  const host = extractProbeHost(ctx.baseUrl);
  if (!host) return false;
  if (host === "localhost" || host === "127.0.0.1" || host === "[::1]") return false;
  if (ctx.blockedHosts.has(host)) return false;
  return true;
}

// ---------------------------------------------------------------------------
// localStorage memory (injected Storage so tests stay pure)
// ---------------------------------------------------------------------------

interface BlockedHostEntry {
  [host: string]: number; // epoch ms when the probe failed
}

/** localStorage can throw (privacy mode, disabled storage) — never let the
 * diagnostics path crash over a cache. */
export function safeLocalStorage(): Storage | null {
  try {
    if (typeof window === "undefined") return null;
    const s = window.localStorage;
    // Touch it — some environments hand out a storage object that throws on use.
    s.getItem(STORAGE_KEY);
    return s;
  } catch {
    return null;
  }
}

/** Load remembered hosts, dropping expired entries. Corrupt payloads are
 * treated as empty (and left alone — the next remember() overwrites). */
export function loadBlockedProbeHosts(storage: Storage | null, now = Date.now()): Set<string> {
  const out = new Set<string>();
  if (!storage) return out;
  try {
    const raw = storage.getItem(STORAGE_KEY);
    if (!raw) return out;
    const parsed = JSON.parse(raw) as BlockedHostEntry;
    if (!parsed || typeof parsed !== "object") return out;
    for (const [host, failedAt] of Object.entries(parsed)) {
      if (typeof failedAt !== "number" || !Number.isFinite(failedAt)) continue;
      if (now - failedAt > DIRECT_PROBE_BLOCK_TTL_MS) continue; // expired
      out.add(host.toLowerCase());
    }
  } catch {
    // corrupt JSON → treat as empty
  }
  return out;
}

/** Remember a host whose direct probe failed (CORS or network), TTL-bounded. */
export function rememberBlockedProbeHost(storage: Storage | null, host: string, now = Date.now()): void {
  if (!storage || !host) return;
  try {
    const key = host.toLowerCase();
    let parsed: BlockedHostEntry = {};
    const raw = storage.getItem(STORAGE_KEY);
    if (raw) {
      try {
        const p = JSON.parse(raw) as BlockedHostEntry;
        if (p && typeof p === "object") parsed = p;
      } catch {
        parsed = {};
      }
    }
    parsed[key] = now;
    storage.setItem(STORAGE_KEY, JSON.stringify(parsed));
  } catch {
    // quota / privacy mode — diagnostics must never crash over a cache
  }
}

/** Clear a host's memory (probe succeeded — the host speaks CORS again). */
export function clearBlockedProbeHost(storage: Storage | null, host: string): void {
  if (!storage || !host) return;
  try {
    const key = host.toLowerCase();
    const raw = storage.getItem(STORAGE_KEY);
    if (!raw) return;
    const parsed = JSON.parse(raw) as BlockedHostEntry;
    if (!parsed || typeof parsed !== "object" || !(key in parsed)) return;
    delete parsed[key];
    storage.setItem(STORAGE_KEY, JSON.stringify(parsed));
  } catch {
    // ignore
  }
}

