// ============================================================================
// ZEN FREE-MODEL REGISTRY — single source of truth for OpenCode Zen free
// models (types: opencode / opencode-zen / zencode, baseUrl
// https://opencode.ai/zen/v1).
//
// WHY THIS EXISTS (live evidence, 2026-08-30):
//   1. Free-model availability churns constantly — ids vanish from
//      /zen/v1/models and reappear (hy3-free is gone; big-pickle returned).
//      A stale static list makes the UI offer models the API no longer serves.
//   2. The free-usage limiter is keyed to the REQUESTER'S IP, not the API key
//      (FreeUsageLimitError fires keyless; upstream issue anomalyco/opencode
//      #33318) — and per-model upstream routes fail independently ("Model is
//      unavailable" / 503 on one sibling while another answers 200 from the
//      same IP). A fresh key or new account does NOT lift the limit.
//   3. Region locks exist per model (muse-spark-1.2-contributor-free → 403
//      RegionError) and some free models are only served on the /responses
//      endpoint family, not the OpenAI-compatible /chat/completions route the
//      app uses — so they must never be shipped as chat defaults.
//
// The preflight gate + router rotate through enabledModels siblings on
// quota/model errors; this registry keeps those lists honest and the default
// pointed at a model that was verified ANSWERING at verification time.
// ============================================================================

/** Date of the last live probe of https://opencode.ai/zen/v1 (UTC). */
export const ZEN_VERIFICATION_DATE = "2026-08-30";

/**
 * Model ids that no longer exist on /zen/v1/models (or consistently 401
 * "Model not supported"). Never ship these in enabledModels / defaults.
 */
export const ZEN_DEAD_MODEL_IDS: readonly string[] = [
  "hy3-free",
  "hy3-free-stealth",
  "north-mini-code-free",
  "minimax-m2.5-free",
  "nemotron-3-super-free",
  "qwen3-30b-a3b-free",
  "gemma-3-27b-free",
  "llama-4-maverick-free",
  "llama-4-scout-free",
];

/**
 * Models that answer only outside this app's route family (region-locked
 * and/or served exclusively on the /responses or /messages endpoint family,
 * not the OpenAI-compatible /chat/completions the app uses).
 */
export const ZEN_REGION_LOCKED_MODEL_IDS: readonly string[] = [
  "muse-spark-1.2-contributor-free",
];

/**
 * Free models verified ANSWERING (HTTP 200, real completion) at
 * ZEN_VERIFICATION_DATE, best-first. Models that are valid ids but currently
 * limited/unavailable from the probe network (big-pickle, mimo-v2.5-free,
 * deepseek-v4-flash-free, ling-3.0-flash-fin-free) stay usable via rotation —
 * they are NOT listed here because "verified working" means observed 200.
 */
export const ZEN_VERIFIED_WORKING_FREE_MODELS: readonly string[] = [
  "nemotron-3-ultra-free",
  "nemotron-3.5-lightning-free",
  "laguna-s-2.1-free",
];

/** The default free model — head of the verified-working list. */
export const ZEN_PREFERRED_DEFAULT = ZEN_VERIFIED_WORKING_FREE_MODELS[0];

const UNUSABLE_ZEN_IDS = new Set<string>([...ZEN_DEAD_MODEL_IDS, ...ZEN_REGION_LOCKED_MODEL_IDS]);

/**
 * Filter an enabledModels list for Zen: drop dead/region-locked ids, trim,
 * drop empties, dedupe, preserve order. Unknown ids pass through —
 * availability churns and the catalog must not silently swallow new models.
 */
export function sanitizeZenEnabledModels(models: unknown): string[] {
  if (!Array.isArray(models)) return [];
  const seen = new Set<string>();
  const out: string[] = [];
  for (const m of models) {
    if (typeof m !== "string") continue;
    const id = m.trim();
    if (id === "" || UNUSABLE_ZEN_IDS.has(id) || seen.has(id)) continue;
    seen.add(id);
    out.push(id);
  }
  return out;
}

/**
 * Pick the default Zen model from an enabled list: first usable id
 * (dead/region-locked skipped), else the verified preferred default.
 */
export function pickZenDefaultModel(
  enabledModels: unknown,
  fallback: string = ZEN_PREFERRED_DEFAULT
): string {
  const usable = sanitizeZenEnabledModels(enabledModels);
  return usable[0] ?? fallback;
}

// ============================================================================
// Rate Governor — unit tests (Option 1: proactive pacing).
// Uses fake timers to verify bucket refill, AIMD reshaping, Retry-After
// parking, FIFO ticketing order, and the hard-wait ceiling.
// ============================================================================

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { RateGovernor, DEFAULT_RPM, MAX_BURST, MAX_WAIT_MS } from "../rate-governor";

describe("RateGovernor", () => {
  beforeEach(() => {
    vi.useFakeTimers();
  });
  afterEach(() => {
    vi.useRealTimers();
  });

  it("acquire resolves immediately while burst capacity is available", async () => {
    const g = new RateGovernor();
    const t0 = Date.now();
    await g.acquire("prov", "model-x");
    await g.acquire("prov", "model-x");
    expect(Date.now() - t0).toBeLessThan(50);
  });

  it("paces calls once the burst is exhausted (token refill at RPM)", async () => {
    const g = new RateGovernor();
    // Drain the initial burst.
    for (let i = 0; i < MAX_BURST; i++) await g.acquire("p", "m");
    // The next call must wait for a refill (DEFAULT_RPM → 1 token / 6s).
    const p = g.acquire("p", "m");
    let resolved = false;
    p.then(() => { resolved = true; });
    await vi.advanceTimersByTimeAsync(3_000);
    expect(resolved).toBe(false); // only half a token yet
    await vi.advanceTimersByTimeAsync(3_500);
    expect(resolved).toBe(true); // refilled past 1 token
    await p;
  });

  it("a rate-limit failure halves the burst and parks the provider", async () => {
    const g = new RateGovernor();
    const before = g.burstOf("p", "m");
    g.reportFailure("p", "m", { statusCode: 429, message: "Too many requests" });
    expect(g.burstOf("p", "m")).toBe(Math.max(1, Math.floor(before / 2)));
    // First 429 of a streak → 60s bounded backoff (same curve as the tracker).
    expect(g.parkedFor("p", "m")).toBeGreaterThan(55_000);
    expect(g.parkedFor("p", "m")).toBeLessThanOrEqual(60_000);
  });

  it("honors an explicit Retry-After surfaced by the adapter", async () => {
    const g = new RateGovernor();
    g.reportFailure("p", "m", { statusCode: 429, retryAfterSeconds: 7 });
    expect(g.parkedFor("p", "m")).toBeGreaterThan(6_000);
    expect(g.parkedFor("p", "m")).toBeLessThanOrEqual(7_000);
  });

  it("ignores non-rate-limit errors (no quota signal)", async () => {
    const g = new RateGovernor();
    g.reportFailure("p", "m", new Error("validation failed: too short"));
    expect(g.parkedFor("p", "m")).toBe(0);
    expect(g.burstOf("p", "m")).toBe(MAX_BURST);
  });

  it("success recovers burst capacity (additive increase) and clears the streak", async () => {
    const g = new RateGovernor();
    g.reportFailure("p", "m", { statusCode: 429 });
    const halved = g.burstOf("p", "m");
    g.reportSuccess("p", "m");
    g.reportSuccess("p", "m");
    expect(g.burstOf("p", "m")).toBeGreaterThan(halved);
  });

  it("is disabled cleanly (no pacing, no parking effect on acquire)", async () => {
    const g = new RateGovernor({ enabled: false });
    g.reportFailure("p", "m", { statusCode: 429 });
    const t0 = Date.now();
    await g.acquire("p", "m");
    expect(Date.now() - t0).toBeLessThan(50);
  });

  it("serves FIFO waiters in ticket order when capacity frees", async () => {
    const g = new RateGovernor({ enabled: true });
    for (let i = 0; i < MAX_BURST; i++) await g.acquire("p", "m"); // drain burst
    const order: number[] = [];
    const w1 = g.acquire("p", "m").then(() => { order.push(1); });
    const w2 = g.acquire("p", "m").then(() => { order.push(2); });
    // Refill exactly one token → only w1 (head of the FIFO) may proceed.
    await vi.advanceTimersByTimeAsync(6_500);
    await w1;
    expect(order).toEqual([1]);
    // Second token → w2 proceeds.
    await vi.advanceTimersByTimeAsync(6_500);
    await w2;
    expect(order).toEqual([1, 2]);
  });

  it("never waits longer than MAX_WAIT_MS even when parked (best-effort proceed)", async () => {
    const g = new RateGovernor();
    g.reportFailure("p", "m", { statusCode: 429, retryAfterSeconds: 3600 }); // 1h park
    const p = g.acquire("p", "m");
    let resolved = false;
    p.then(() => { resolved = true; });
    await vi.advanceTimersByTimeAsync(MAX_WAIT_MS + 1_000);
    expect(resolved).toBe(true); // gave up waiting, proceeded best-effort
    await p;
  });

  it("resolveRpm prefers the configured cap, else the conservative default", () => {
    const g = new RateGovernor();
    expect(g.resolveRpm("p", 42)).toBe(42);
    expect(g.resolveRpm("p", undefined)).toBe(DEFAULT_RPM);
    expect(g.resolveRpm("p", 0)).toBe(DEFAULT_RPM);
  });
});

