    expect(html).toContain("<h3>EXPERIENCE</h3>");
    expect(html).toContain("<h3>EDUCATION</h3>");
    expect(html).toContain("<h3>SKILLS</h3>");
  });

  it("formats experience entries on one line with strong tags", () => {
