    // Name is uppercased then escaped — so <SCRIPT> becomes &lt;SCRIPT&gt;
    expect(html).not.toContain("<script>");
    expect(html).not.toContain("<SCRIPT>");
    expect(html.toLowerCase()).toContain("&lt;script&gt;");
