"use client";

import { recordAI, setFlightScope } from "@/lib/ai/flight-recorder";
import { PromptBuilder } from "@/lib/ai/prompt-builder";
setFlightScope({ scope: "resume-copilot", feature: "Debug Chat", module: "src.lib.debug-chat" });

// Conversational Debug Chat Interface
//
// Interactive chat window connected to the AI Provider Registry.
// User types a prompt → wrapped in Hermes context + system_health logs →
// sent via selected D1 provider → response rendered with actionable
// inline buttons ([Apply Patch], [Run Query], [Rollback]).
//
// The UI component lives in src/components/app/modules/DebugChat.tsx
// This file provides the service layer.
// ============================================================================


import { callAI } from "./ai";
import { getMetricsSnapshot } from "./metrics-service";
import { getRecentIncidents } from "./incident-service";
import { getTelemetrySnapshot } from "./telemetry";
import { audit } from "./audit-service";

export interface ChatMessage {
  id: string;
  role: "user" | "assistant" | "system";
  content: string;
  timestamp: string;
  actions?: ChatAction[];
  provider?: string;
}

export interface ChatAction {
  id: string;
  label: string;
  type: "apply-patch" | "run-query" | "rollback" | "sync-providers" | "run-health-check" | "clear-cache";
  payload: any;
}

/**
 * Build the system context for the debug chat.
 * Includes current system health, recent incidents, and telemetry.
 */
export function buildSystemContext(): string {
  const metrics = getMetricsSnapshot();
  const incidents = getRecentIncidents(5);
  const telemetry = getTelemetrySnapshot();

  const incidentText = incidents.length > 0
    ? incidents.map((i) => `- [${i.severity}] ${i.rootCause} (${i.timestamp})`).join("\n")
    : "No recent incidents";

  return `You are Hermes, the autonomous debug agent for ResumeAI Pro.

CURRENT SYSTEM STATE:
- Overall health: ${metrics.health.overall ? "HEALTHY" : "ISSUES"}
- Providers: ${metrics.providers.trippedCount} tripped, ${metrics.providers.providerFailures} failures
- Pipeline: ${metrics.pipeline.totalOptimizations} optimizations, ${metrics.pipeline.totalFailures} failures
- Repairs: ${metrics.repairs.totalRepairs} total (${metrics.repairs.repairSuccessRate}% success rate)
- Incidents: ${metrics.incidents.total} total (${metrics.incidents.critical} critical)
- Memory: ${metrics.health.memoryUsedMB}MB

RECENT INCIDENTS:
${incidentText}

TELEMETRY:
- Avg optimizer duration: ${telemetry.performance.avgOptimizerDurationMs}ms
- Avg QA confidence: ${telemetry.performance.avgQAConfidence}/100
- Avg ATS score: ${telemetry.performance.avgAtsScore}/100
- Provider failures: ${telemetry.providerFailures.length}
- Pipeline failures: ${telemetry.pipelineFailures.length}

When you suggest fixes, format them as actionable items that the user can click to execute.
Available actions: [Apply Patch], [Run Query], [Rollback], [Sync Providers], [Run Health Check], [Clear Cache]`;
}

/**
 * Send a debug chat message to the selected AI provider.
 * Wraps the user prompt in the Hermes system context + system health.
 */
export async function sendDebugMessage(
  userPrompt: string,
  providerId?: string,
): Promise<ChatMessage> {
  const systemContext = buildSystemContext();

  audit({
    actor: "user",
    action: "debug-chat.send",
    category: "admin",
    details: userPrompt.slice(0, 200),
    severity: "info",
  });

  try {
    // Phase 8.1.3.2A — assemble the prompt through the shared Prompt Builder.
    // The wording is byte-identical to before; the builder only composes the
    // system + user fragments into the shape recordAI already consumes.
    const built = new PromptBuilder({ scope: "resume-copilot", feature: "Debug Chat", version: "hermes-debug" })
      .system(systemContext)
      .user(`DEBUG REQUEST: ${userPrompt}

Analyze the issue, identify the root cause, and suggest a fix.
If you recommend code changes, format them as a patch.
If you recommend a database query, format it as SQL.
If you recommend a rollback, specify what to roll back.

Format your response with clear sections:
1. DIAGNOSIS
2. ROOT CAUSE
3. RECOMMENDED FIX
4. ACTION ITEMS (if any)`)
      .build();

    const result = await recordAI({
      systemPrompt: built.systemPrompt,
      userPrompt: built.userPrompt,
      maxTokens: 2000,
      temperature: 0.3,
      taskCategory: "development",
      timeoutMs: 60000,
      // Pin the user-selected provider so the selector actually routes the call.
      ...(providerId ? { providerId } : {}),
    });

    // Extract actionable items from the response
    const actions = extractActions(result.text, userPrompt);

    return {
      id: `msg_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      role: "assistant",
      content: result.text,
      timestamp: new Date().toISOString(),
      actions,
      provider: result.provider,
    };
  } catch (e: any) {
    return {
      id: `msg_err_${Date.now()}`,
      role: "assistant",
      content: `Debug request failed: ${e?.message ?? "Unknown error"}. The system is still operational — please try again or check the health monitor.`,
      timestamp: new Date().toISOString(),
      actions: [],
    };
  }
}

/**
 * Extract actionable buttons from the AI response.
 * Looks for keywords like "apply", "rollback", "query", "sync", etc.
 */
function extractActions(response: string, originalPrompt: string): ChatAction[] {
  const actions: ChatAction[] = [];
  const lower = response.toLowerCase();

  if (lower.includes("patch") || lower.includes("apply") || lower.includes("fix")) {
    actions.push({
      id: `act_patch_${Date.now()}`,
      label: "Apply Patch",
      type: "apply-patch",
      payload: { response, prompt: originalPrompt },
    });
  }

  if (lower.includes("rollback") || lower.includes("revert")) {
    actions.push({
      id: `act_rollback_${Date.now()}`,
      label: "Rollback",
      type: "rollback",
      payload: { response, prompt: originalPrompt },
    });
  }

  if (lower.includes("query") || lower.includes("sql") || lower.includes("select")) {
    actions.push({
      id: `act_query_${Date.now()}`,
      label: "Run Query",
      type: "run-query",
      payload: { response },
    });
  }

  if (lower.includes("sync") || lower.includes("provider")) {
    actions.push({
      id: `act_sync_${Date.now()}`,
      label: "Sync Providers",
      type: "sync-providers",
      payload: {},
    });
  }

  if (lower.includes("health") || lower.includes("check")) {
    actions.push({
      id: `act_health_${Date.now()}`,
      label: "Run Health Check",
      type: "run-health-check",
      payload: {},
    });
  }

  if (lower.includes("cache") || lower.includes("clear")) {
    actions.push({
      id: `act_cache_${Date.now()}`,
      label: "Clear Cache",
      type: "clear-cache",
      payload: {},
    });
  }

  return actions;
}

/**
 * Execute a chat action.
 * Routes to the appropriate service based on action type.
 */
export async function executeAction(action: ChatAction): Promise<{ success: boolean; message: string }> {
  audit({
    actor: "user",
    action: `debug-chat.execute.${action.type}`,
    category: "admin",
    details: action.label,
    severity: "info",
  });

  switch (action.type) {
    case "sync-providers": {
      try {
        const { syncProviderConfigs } = await import("./provider-sync");
        const { useApp } = await import("./store");
        const providers = useApp.getState().providers as any[];
        const { result } = syncProviderConfigs(providers);
        return { success: true, message: `Providers synced: ${result.repaired} repaired, ${result.backfilled} backfilled` };
      } catch (e: any) {
        return { success: false, message: `Sync failed: ${e?.message}` };
      }
    }

    case "run-health-check": {
      try {
        const { runHealthCheck } = await import("./health-monitor");
        const result = await runHealthCheck();
        return {
          success: result.overall,
          message: result.overall
            ? "All systems healthy"
            : `Issues found: ${result.providers.issues.join(", ")}`,
        };
      } catch (e: any) {
        return { success: false, message: `Health check failed: ${e?.message}` };
      }
    }

    case "clear-cache": {
      try {
        const { invalidateAllCaches } = await import("./provider-cache");
        invalidateAllCaches();
        return { success: true, message: "All caches cleared" };
      } catch (e: any) {
        return { success: false, message: `Cache clear failed: ${e?.message}` };
      }
    }

    case "rollback": {
      try {
        const { rollbackToLastValidSnapshot } = await import("./agents/pipeline-context");
        const result = rollbackToLastValidSnapshot();
        return {
          success: result !== null,
          message: result ? "Rolled back to last valid snapshot" : "No valid snapshot to roll back to",
        };
      } catch (e: any) {
        return { success: false, message: `Rollback failed: ${e?.message}` };
      }
    }

    case "apply-patch":
      return { success: true, message: "Patch noted — review the AI response for implementation details" };

    case "run-query":
      return { success: true, message: "Query noted — execute in the D1 console" };

    default:
      return { success: false, message: `Unknown action type: ${action.type}` };
  }
}

src/lib/debug-persistence.ts:
// ============================================================================
// Debug Persistence
//
// Persists intermediate pipeline artifacts for debugging and diff analysis.
// In production, these are stored in memory (or optionally to D1).
//
// Artifacts persisted:
//   1. sourceResume.json — the parsed source resume
//   2. lockedEntities.json — the locked entities (fingerprint map)
//   3. optimizerInput.json — the input sent to the LLM
//   4. providerResponse.json — the raw LLM response
//   5. optimizerOutput.json — the parsed optimizer output
//   6. assembledResume.json — the assembled resume (before final validation)
//   7. finalResume.json — the final resume (after validation)
//   8. experienceDiff.json — per-experience before/after diff
//
// All artifacts are also logged to console for debugging.
// ============================================================================

"use client";

import type { ResumeData } from "./types";
import type { OptimizerOutput } from "./resume-assembler";
import { computeExperienceFingerprint } from "./experience-fingerprint";

export interface DebugArtifacts {
  sourceResume: ResumeData;
  optimizerInput: { systemPrompt: string; userPrompt: string };
  providerResponse: string;
  optimizerOutput: OptimizerOutput;
  assembledResume: ResumeData;
  finalResume: ResumeData;
  experienceDiff: ExperienceDiff[];
  timestamp: string;
}

export interface ExperienceDiff {
  id: string;
  title: string;
  company: string;
  startDate: string;
  endDate: string;
  fingerprint: string;
  bulletsChanged: boolean;
  bulletsBefore: string[];
  bulletsAfter: string[];
  bulletCountBefore: number;
  bulletCountAfter: number;
}

/**
 * Compute the per-experience diff between source and final resume.
 */
export function computeExperienceDiff(source: ResumeData, final: ResumeData): ExperienceDiff[] {
  const diffs: ExperienceDiff[] = [];

  for (const srcExp of source.experience) {
    // Find matching final entry by ID
    const finalExp = final.experience.find((e) => e.id === srcExp.id);

    if (!finalExp) {
      // Entry was dropped — record as a diff with empty "after"
      diffs.push({
        id: srcExp.id,
        title: srcExp.title,
        company: srcExp.company,
        startDate: srcExp.startDate,
        endDate: srcExp.endDate,
        fingerprint: computeExperienceFingerprint(srcExp),
        bulletsChanged: true,
        bulletsBefore: srcExp.bullets,
        bulletsAfter: [],
        bulletCountBefore: srcExp.bullets.length,
        bulletCountAfter: 0,
      });
      continue;
    }

    const bulletsChanged = JSON.stringify(srcExp.bullets) !== JSON.stringify(finalExp.bullets);

    diffs.push({
      id: srcExp.id,
      title: finalExp.title,
      company: finalExp.company,
      startDate: finalExp.startDate,
      endDate: finalExp.endDate,
      fingerprint: computeExperienceFingerprint(finalExp),
      bulletsChanged,
      bulletsBefore: srcExp.bullets,
      bulletsAfter: finalExp.bullets,
      bulletCountBefore: srcExp.bullets.length,
      bulletCountAfter: finalExp.bullets.length,
    });
  }

  return diffs;
}

/**
 * Persist debug artifacts to console (and optionally to storage).
 *
 * In production, this is a no-op except for console logging.
 * In development, this can be extended to write to localStorage or D1.
 */
export function persistDebugArtifacts(artifacts: DebugArtifacts): void {
  const summary = {
    timestamp: artifacts.timestamp,
    sourceExperienceCount: artifacts.sourceResume.experience.length,
    finalExperienceCount: artifacts.finalResume.experience.length,
    bulletsChanged: artifacts.experienceDiff.filter((d) => d.bulletsChanged).length,
    bulletsUnchanged: artifacts.experienceDiff.filter((d) => !d.bulletsChanged).length,
    providerResponseLength: artifacts.providerResponse.length,
    optimizerOutputExperiences: artifacts.optimizerOutput.experiences?.length ?? 0,
    optimizerOutputSkills: artifacts.optimizerOutput.skills?.length ?? 0,
  };

  console.group("[Debug Artifacts]");
  console.log("Summary:", summary);
  console.log("Experience Diff:");
  for (const diff of artifacts.experienceDiff) {
    const status = diff.bulletsChanged
      ? `CHANGED (${diff.bulletCountBefore}→${diff.bulletCountAfter} bullets)`
      : `unchanged (${diff.bulletCountBefore} bullets)`;
    console.log(`  [${diff.id}] ${diff.title} at ${diff.company}: ${status}`);
  }
  console.groupEnd();
}

/**
 * Create a debug artifacts object from pipeline stages.
 */
export function createDebugArtifacts(
  sourceResume: ResumeData,
  optimizerInput: { systemPrompt: string; userPrompt: string },
  providerResponse: string,
  optimizerOutput: OptimizerOutput,
  assembledResume: ResumeData,
  finalResume: ResumeData,
): DebugArtifacts {
  return {
    sourceResume,
    optimizerInput,
    providerResponse,
    optimizerOutput,
    assembledResume,
    finalResume,
    experienceDiff: computeExperienceDiff(sourceResume, finalResume),
    timestamp: new Date().toISOString(),
  };
}

