// ============================================================================
// LayoutEngine — page layout, overflow detection, positioning
// ============================================================================
// Responsibilities:
//   - Calculate page dimensions from theme
//   - Position RenderNodes within pages
//   - Detect overflow and trigger compaction
//   - Widow/orphan control for section titles

import type { RenderNode, RenderNodePosition, ResumeTheme, PageLayout, LayoutResult, RenderNodeStyle } from "./types-phase3";

/** A4 dimensions in mm */
const A4_WIDTH_MM = 210;
const A4_HEIGHT_MM = 297;

/** Letter dimensions in mm */
const LETTER_WIDTH_MM = 215.9;
const LETTER_HEIGHT_MM = 279.4;

/** Estimated line height contribution for one character */
const CHARS_PER_LINE = 75; // average for 10pt on A4

/**
 * Get page dimensions for a given page size.
 */
export function getPageDimensionsMm(pageSize: "A4" | "Letter"): { widthMm: number; heightMm: number } {
  return pageSize === "A4"
    ? { widthMm: A4_WIDTH_MM, heightMm: A4_HEIGHT_MM }
    : { widthMm: LETTER_WIDTH_MM, heightMm: LETTER_HEIGHT_MM };
}

/**
 * Create an initial PageLayout from theme values.
 */
export function createPageLayout(
  pageNumber: number,
  theme: ResumeTheme,
): PageLayout {
  const { widthMm, heightMm } = getPageDimensionsMm(theme.pageSize);
  return {
    pageNumber,
    widthMm,
    heightMm,
    marginTopMm: theme.marginTopMm,
    marginBottomMm: theme.marginBottomMm,
    marginLeftMm: theme.marginLeftMm,
    marginRightMm: theme.marginRightMm,
    usableWidthMm: widthMm - theme.marginLeftMm - theme.marginRightMm,
    usableHeightMm: heightMm - theme.marginTopMm - theme.marginBottomMm,
    currentY: 0,
    remainingHeightMm: heightMm - theme.marginTopMm - theme.marginBottomMm,
    overflow: false,
  };
}

/**
 * Estimate the rendered height of a RenderNode in mm.
 * Used by the layout engine to position nodes before actual rendering.
 */
export function estimateNodeHeightMm(
  node: RenderNode,
  usableWidthMm: number,
  theme: ResumeTheme,
): number {
  const lineHeightMm = theme.lineHeightMm || 4.2;
  const baseFontSize = theme.bodyFontSizePt || 10;
  const avgCharWidthMm = usableWidthMm / CHARS_PER_LINE;

  // Base size for different node types
  switch (node.type) {
    case "section-title":
      return lineHeightMm * 1.4;
    case "text-line":
    case "contact-line":
      return lineHeightMm;
    case "bullet-item": {
      const charsPerLine = Math.floor(usableWidthMm / avgCharWidthMm) - 4; // indent
      const lines = Math.ceil(node.content.length / Math.max(charsPerLine, 1));
      return lines * lineHeightMm;
    }
    case "table-row":
      return lineHeightMm;
    case "table-cell":
      return lineHeightMm;
    case "divider":
      return 1.5;
    default:
      return lineHeightMm;
  }
}

/**
 * Calculate total estimated height for a list of nodes.
 */
export function estimateTotalHeightMm(
  nodes: RenderNode[],
  usableWidthMm: number,
  theme: ResumeTheme,
): number {
  let total = 0;
  for (const node of nodes) {
    total += estimateNodeHeightMm(node, usableWidthMm, theme);
    // Add margins
    if (node.style.marginTopMm) total += node.style.marginTopMm;
    if (node.style.marginBottomMm) total += node.style.marginBottomMm;
  }
  return total;
}

/**
 * Position a list of RenderNodes across pages.
 * Assigns page number and y-offset to each node.
 */
export function layoutNodes(
  nodes: RenderNode[],
  theme: ResumeTheme,
): LayoutResult {
  const pages: PageLayout[] = [];
  let currentPage = createPageLayout(0, theme);
  pages.push(currentPage);

  const positionedNodes: RenderNode[] = [];

  for (const node of nodes) {
    const estimatedHeight = estimateNodeHeightMm(node, currentPage.usableWidthMm, theme);
    const marginTop = node.style.marginTopMm || 0;
    const marginBottom = node.style.marginBottomMm || 0;
    const totalHeight = estimatedHeight + marginTop + marginBottom;

    // Check if node fits on current page
    if (currentPage.remainingHeightMm < totalHeight && currentPage.currentY > 0) {
      // Start a new page
      currentPage = createPageLayout(pages.length, theme);
      pages.push(currentPage);
    }

    // Position the node
    const position: RenderNodePosition = {
      page: currentPage.pageNumber,
      order: currentPage.currentY > 0
        ? positionedNodes.filter((n) => n.position?.page === currentPage.pageNumber).length
        : 0,
      xMm: theme.marginLeftMm,
      yMm: theme.marginTopMm + currentPage.currentY + marginTop,
      widthMm: currentPage.usableWidthMm,
      heightMm: estimatedHeight,
    };

    currentPage.currentY += totalHeight;
    currentPage.remainingHeightMm -= totalHeight;

    const positionedNode: RenderNode = {
      ...node,
      position,
    };
    positionedNodes.push(positionedNode);
  }

  // Check overflow
  const hasOverflow = currentPage.currentY > (currentPage.heightMm - currentPage.marginTopMm - currentPage.marginBottomMm);

  return {
    pages: pages.map((p) => ({
      ...p,
      overflow: p.remainingHeightMm < 0,
    })),
    nodes: positionedNodes,
    totalPages: pages.length,
    hasOverflow,
  };
}

/**
 * Detect if content overflows a single page.
 */
export function detectOverflow(estimatedTotalMm: number, theme: ResumeTheme): boolean {
  const { heightMm } = getPageDimensionsMm(theme.pageSize);
  const usableHeight = heightMm - theme.marginTopMm - theme.marginBottomMm;
  return estimatedTotalMm > usableHeight;
}

/**
 * Suggest compression steps when content overflows.
 * Never removes content — only adjusts spacing and font sizes.
 */
export function suggestCompression(
  overflowMm: number,
  theme: ResumeTheme,
): string[] {
  const steps: string[] = [];

  // Step 1: reduce line spacing
  if (theme.lineHeightMm > 3.2) {
    steps.push("reduce-line-spacing");
  }

  // Step 2: reduce section gap
  if (theme.sectionGapMm > 1.5) {
    steps.push("reduce-section-gap");
  }

  // Step 3: reduce margins
  if (theme.marginTopMm > 4) {
    steps.push("reduce-margins");
  }

  // Step 4: reduce body font size
  if (theme.bodyFontSizePt > 9) {
    steps.push("reduce-font-size");
  }

  return steps;
}

src/lib/layout-simulator.ts:
import { ResumeData } from "./types";

interface LayoutDimensions {
  fontFamily: string;
  bodyFontSizePt: number;
  lineHeight: number;
  marginTopMm: number;
  marginBottomMm: number;
  marginLeftMm: number;
  marginRightMm: number;
  sectionTitleSizePt: number;
  sectionSpacingMm: number;
  entrySpacingMm: number;
  bulletSpacingMm: number;
  bulletIndentMm: number;
}

const DEFAULT_DIMENSIONS: LayoutDimensions = {
  fontFamily: "Inter",
  bodyFontSizePt: 10,
  lineHeight: 1.4,
  marginTopMm: 15,
  marginBottomMm: 15,
  marginLeftMm: 15,
  marginRightMm: 15,
  sectionTitleSizePt: 12,
  sectionSpacingMm: 5,
  entrySpacingMm: 4,
  bulletSpacingMm: 2,
  bulletIndentMm: 5,
};

// Conversions
const MM_TO_PT = 2.83465;

// Approximate character width factors (relative to font size) for standard fonts
const CHAR_WIDTH_FACTORS: Record<string, number> = {
  serif: 0.38,
  "times new roman": 0.38,
  georgia: 0.4,
  sans: 0.41,
  inter: 0.41,
  roboto: 0.41,
  helvetica: 0.42,
  arial: 0.42,
  mono: 0.6,
  monospace: 0.6,
  default: 0.41,
};

function getCharWidthFactor(fontFamily: string): number {
  const normalized = fontFamily.toLowerCase();
  for (const key of Object.keys(CHAR_WIDTH_FACTORS)) {
    if (normalized.includes(key)) {
      return CHAR_WIDTH_FACTORS[key];
    }
  }
  return CHAR_WIDTH_FACTORS.default;
}

/**
 * Deterministically simulates the layout height of a resume on an A4 page (595 x 842 pt).
 */
export function simulateLayoutHeight(resume: ResumeData, dimensions: Partial<LayoutDimensions> = {}): {
  totalHeightPt: number;
  contentHeightPt: number;
  pageHeightPt: number;
  marginHeightPt: number;
  overflows: boolean;
  scaleFactor: number;
  recommendation: string;
} {
  const d = { ...DEFAULT_DIMENSIONS, ...dimensions };
  const pageHeightPt = 842;
  const pageWidthPt = 595;

  const topMarginPt = d.marginTopMm * MM_TO_PT;
  const bottomMarginPt = d.marginBottomMm * MM_TO_PT;
  const leftMarginPt = d.marginLeftMm * MM_TO_PT;
  const rightMarginPt = d.marginRightMm * MM_TO_PT;
  const marginHeightPt = topMarginPt + bottomMarginPt;
  const printableWidthPt = pageWidthPt - (leftMarginPt + rightMarginPt);
  const printableHeightPt = pageHeightPt - marginHeightPt;

  const charFactor = getCharWidthFactor(d.fontFamily);
  const avgCharWidthPt = d.bodyFontSizePt * charFactor;

  let currentY = 0;

  // 1. Header (Name, contact details)
  // Name
  currentY += d.bodyFontSizePt * 2.2; // roughly 22pt height for large name
  currentY += 6; // Spacing after name
  
  // Contact line
  const contactText = [resume.contact?.email, resume.contact?.phone, resume.contact?.location, resume.dateOfBirth].filter(Boolean).join("  |  ");
  const contactLines = Math.ceil((contactText.length * avgCharWidthPt) / printableWidthPt);
  currentY += contactLines * d.bodyFontSizePt * 1.2 + 8; // spacing

  // Helper to wrap text and add height
  const addTextHeight = (text: string, fontSize: number, spacingAfter: number = 0) => {
    const textWidthFactor = fontSize * charFactor;
    const charsPerLine = Math.floor(printableWidthPt / textWidthFactor);
    // Simple line wrap simulation based on word boundaries
    const words = text.split(/\s+/);
    let linesCount = 1;
    let currentLineLength = 0;
    for (const word of words) {
      if (currentLineLength + word.length + 1 > charsPerLine) {
        linesCount++;
        currentLineLength = word.length;
      } else {
        currentLineLength += word.length + 1;
      }
    }
    currentY += linesCount * fontSize * d.lineHeight + spacingAfter;
  };

  // Helper to add section title height
  const addSectionTitleHeight = () => {
    currentY += d.sectionSpacingMm * MM_TO_PT;
    currentY += d.sectionTitleSizePt * 1.3; // Section title text height
    currentY += 4; // spacing below title
  };

  // 2. Summary
  if (resume.summary) {
    addSectionTitleHeight();
    addTextHeight(resume.summary, d.bodyFontSizePt, 8);
  }

  // 3. Experience
  if (resume.experience && resume.experience.length > 0) {
    addSectionTitleHeight();
    for (const exp of resume.experience) {
      // Role Title & Company header line
      const headerText = `${exp.title} - ${exp.company} (${exp.startDate} - ${exp.endDate})`;
      addTextHeight(headerText, d.bodyFontSizePt, 4);

      // Bullets
      if (exp.bullets && exp.bullets.length > 0) {
        const bulletWidthPt = printableWidthPt - (d.bulletIndentMm * MM_TO_PT);
        for (const bullet of exp.bullets) {
          const bulletCharsPerLine = Math.floor(bulletWidthPt / avgCharWidthPt);
          const lines = Math.ceil(bullet.length / bulletCharsPerLine) || 1;
          currentY += lines * d.bodyFontSizePt * d.lineHeight + (d.bulletSpacingMm * MM_TO_PT);
        }
      }
      currentY += d.entrySpacingMm * MM_TO_PT;
    }
  }

  // 4. Skills
  if (resume.skills && resume.skills.length > 0) {
    addSectionTitleHeight();
    // Group skills by category
    const categories: Record<string, string[]> = {};
    for (const s of resume.skills) {
      const cat = s.category || "General";
      if (!categories[cat]) categories[cat] = [];
      categories[cat].push(s.name);
    }

    for (const [cat, items] of Object.entries(categories)) {
      const skillLineText = `${cat}: ${items.join(", ")}`;
      addTextHeight(skillLineText, d.bodyFontSizePt, 3);
    }
  }

  // 5. Education
  if (resume.education && resume.education.length > 0) {
    addSectionTitleHeight();
    for (const edu of resume.education) {
      const eduText = `${edu.degree} in ${edu.field || ""} - ${edu.institution} (${edu.startDate} - ${edu.endDate})`;
      addTextHeight(eduText, d.bodyFontSizePt, 4);
      if (edu.highlights && edu.highlights.length > 0) {
        for (const h of edu.highlights) {
          addTextHeight(`• ${h}`, d.bodyFontSizePt, 2);
        }
      }
      currentY += d.entrySpacingMm * MM_TO_PT;
    }
  }

  // 6. Languages
  if (resume.languages && resume.languages.length > 0) {
    addSectionTitleHeight();
    const langText = resume.languages.map(l => `${l.name} (${l.proficiency})`).join(", ");
    addTextHeight(langText, d.bodyFontSizePt, 4);
  }

  // 7. Certifications
  if (resume.certifications && resume.certifications.length > 0) {
    addSectionTitleHeight();
    for (const cert of resume.certifications) {
      const certText = `${cert.name} - ${cert.issuer} (${cert.date || ""})`;
      addTextHeight(certText, d.bodyFontSizePt, 3);
    }
  }

  const contentHeightPt = currentY;
  const totalHeightPt = contentHeightPt + marginHeightPt;
  const overflows = totalHeightPt > pageHeightPt;

  // Recommend a scale factor to fit exactly 1 page
  const scaleFactor = Number((printableHeightPt / contentHeightPt).toFixed(2));

  let recommendation = "Layout is perfectly balanced for a single page.";
  if (overflows) {
    recommendation = `Reduce font size, line spacing, or margins to scale layout down to ${Math.round(scaleFactor * 100)}% to fit A4.`;
  } else if (totalHeightPt < 700) {
    recommendation = `Increase font size, line spacing, or margins to scale layout up to ${Math.round(scaleFactor * 100)}% to fill the page beautifully.`;
  }

  return {
    totalHeightPt,
    contentHeightPt,
    pageHeightPt,
    marginHeightPt,
    overflows,
    scaleFactor,
    recommendation,
  };
}

src/lib/layout-validator.ts:
// ============================================================================
// Layout Validator — A4 page validation + section enforcement
//
// Validates that a resume:
//   - Has exactly 1 A4 page (2500-3800 chars)
//   - Has all required sections (Header, Summary, Skills, Experience, Education, Languages)
//   - Has 85-100% page utilization
//   - No half-empty pages, no overflow, no orphan sections
// ============================================================================

"use client";

import type { ResumeData } from "./types";

export interface LayoutValidationResult {
  valid: boolean;
  charCount: number;
  pageUtilization: number; // 0-100
  sections: { name: string; present: boolean; charCount: number }[];
  issues: string[];
  recommendations: string[];
}

const REQUIRED_SECTIONS = [
  { name: "Header", check: (r: ResumeData) => !!(r.name || r.headline) },
  { name: "Professional Summary", check: (r: ResumeData) => !!(r.summary && r.summary.length > 50) },
  { name: "Core Competencies", check: (r: ResumeData) => !!(r.skills && r.skills.length > 0) },
  { name: "Professional Experience", check: (r: ResumeData) => !!(r.experience && r.experience.length > 0) },
  { name: "Education", check: (r: ResumeData) => !!(r.education && r.education.length > 0) },
  { name: "Languages", check: (r: ResumeData) => !!(r.languages && r.languages.length > 0) },
];

const MIN_CHARS = 2500;
const MAX_CHARS = 3800;
const TARGET_MIN = 2700;
const TARGET_MAX = 3200;
const MIN_PAGE_FILL = 85; // %

/**
 * Calculate the visible character count of a resume (not JSON structure).
 * This is the single source of truth for "how full is the page" — the
 * page-balancer's computeResumeCharCount delegates to it so the optimizer
 * and the export gate agree on the same metric.
 */
export function getVisibleCharCount(resume: ResumeData): number {
  const parts: string[] = [];
  parts.push(resume.name || "");
  parts.push(resume.headline || "");
  parts.push(resume.summary || "");
  for (const exp of resume.experience || []) {
    parts.push(exp.title || "");
    parts.push(exp.company || "");
    parts.push(exp.location || "");
    parts.push(...(exp.bullets || []));
  }
  for (const edu of resume.education || []) {
    parts.push(edu.degree || "");
    parts.push(edu.institution || "");
    parts.push(...(edu.highlights || []));
  }
  for (const skill of resume.skills || []) {
    parts.push(skill.name || "");
  }
  for (const lang of resume.languages || []) {
    parts.push(lang.name || "");
  }
  for (const cert of resume.certifications || []) {
    parts.push(cert.name || "");
  }
  return parts.join(" ").length;
}

/**
 * Validate a resume against A4 page layout requirements.
 */
export function validateLayout(resume: ResumeData): LayoutValidationResult {
  const charCount = getVisibleCharCount(resume);
  const pageUtilization = Math.min(100, Math.round((charCount / TARGET_MAX) * 100));
  const issues: string[] = [];
  const recommendations: string[] = [];

  // Check character count
  if (charCount < MIN_CHARS) {
    issues.push(`Content too short: ${charCount} chars (minimum ${MIN_CHARS})`);
    recommendations.push("Expand summary, add more experience bullets, add skills");
  } else if (charCount > MAX_CHARS) {
    issues.push(`Content too long: ${charCount} chars (maximum ${MAX_CHARS})`);
    recommendations.push("Shorten summary, reduce bullets, merge skills");
  }

  // Check page utilization
  if (pageUtilization < MIN_PAGE_FILL) {
    issues.push(`Page utilization low: ${pageUtilization}% (minimum ${MIN_PAGE_FILL}%)`);
    recommendations.push("Add more content to fill the A4 page");
  }

  // Check required sections
  const sections = REQUIRED_SECTIONS.map((section) => {
    const present = section.check(resume);
    let sectionCharCount = 0;

    switch (section.name) {
      case "Header":
        sectionCharCount = (resume.name || "").length + (resume.headline || "").length;
        break;
      case "Professional Summary":
        sectionCharCount = (resume.summary || "").length;
        break;
      case "Core Competencies":
        sectionCharCount = (resume.skills || []).reduce((sum, s) => sum + (s.name || "").length, 0);
        break;
      case "Professional Experience":
        sectionCharCount = (resume.experience || []).reduce((sum, e) =>
          sum + (e.title || "").length + (e.company || "").length +
            (e.bullets || []).reduce((bs, b) => bs + (b || "").length, 0), 0);
        break;
      case "Education":
        sectionCharCount = (resume.education || []).reduce((sum, e) =>
          sum + (e.degree || "").length + (e.institution || "").length, 0);
        break;
      case "Languages":
        sectionCharCount = (resume.languages || []).reduce((sum, l) => sum + (l.name || "").length, 0);
        break;
    }

    if (!present) {
      issues.push(`Missing section: ${section.name}`);
      recommendations.push(`Add ${section.name} section`);
    }

    return { name: section.name, present, charCount: sectionCharCount };
  });

  // Check experience bullet count
  for (const exp of resume.experience || []) {
    if (!exp.bullets || exp.bullets.length < 2) {
      issues.push(`Experience "${exp.title}" has fewer than 2 bullets`);
      recommendations.push(`Add more bullets to ${exp.title} at ${exp.company}`);
    }
  }

  const valid = issues.length === 0;

  if (valid) {
    console.info(`[Layout Validator] Valid — ${charCount} chars, ${pageUtilization}% utilization, all sections present`);
  } else {
    console.warn(`[Layout Validator] Invalid — ${issues.length} issue(s): ${issues.join("; ")}`);
  }

  return {
    valid,
    charCount,
    pageUtilization,
    sections,
    issues,
    recommendations,
  };
}

/**
 * Quick check — is the resume valid for export?
 */
export function isExportReady(resume: ResumeData): boolean {
  return validateLayout(resume).valid;
}

src/lib/leak-patterns.ts:
// ============================================================================
// Leak Patterns — unified source of truth for AI error leak detection.
//
// Previously there were two parallel lists:
//   - ai-error-filter.ts: ERROR_LEAK_PATTERNS (43 patterns)
//   - ai-response-processor.ts: LEAK_PATTERNS (80+ patterns, superset)
//
// They had drifted. This module unifies them into one list, adds missing
// provider names (Gemini, Mistral, Cohere, Groq, OpenRouter, Together,
// HuggingFace, Ollama), and is re-exported from both original modules so
// existing imports keep working.
//
// These patterns prevent AI provider errors, debug messages, and analysis
// artifacts from ever leaking into resume content or exported PDFs.
// ============================================================================

export const LEAK_PATTERNS: RegExp[] = [
  // --- Provider / API errors ---
  /api\s?key\s?(invalid|missing|wrong|expired|unauthorized|revoked)/i,
  /rate\s?limit\s?(exceeded|reached|hit)/i,
