  /ssl\s?(certificate\s?error|handshake\s?failed)/i,
  /cors\s?(error|blocked|failed)/i,
  /503\s?service\s?unavailable/i,
  /502\s?bad\s?gateway/i,
  /500\s?internal\s?server\s?error/i,
  /429\s?too\s?many\s?requests/i,
