  /\b(perplexity|sonar|pplx)\b/i,
  /\b(xai|grok|grok-2|grok-3|grok-4)\b/i,

  // --- JSON / parsing errors ---
  /unexpected\s?token\s?['"]?[A-Za-z]/i,
  /unexpected\s?end\s?of\s?(json|input|string)/i,
  /json\s?(parse\s?)?error/i,
  /syntax\s?error/i,
  /invalid\s?json/i,
  /malformed\s?json/i,
  /unable\s?to\s?parse/i,
  /parse\s?failed/i,
