  // --- AI fallback / retry messages ---
  /falling\s?back\s?to/i,
  /fallback\s?(mode|activated|engaged)/i,
  /retrying/i,
  /please\s?try\s?(again|later)/i,
  /try\s?again\s?(later|in\s?a\s?moment)/i,
  /an\s?error\s?occurred/i,
