"use client";

import { recordAI, setFlightScope } from "@/lib/ai/flight-recorder";
setFlightScope({ scope: "resume-parser", feature: "Resume Parser", module: "src.lib.parser" });


import type { ResumeData } from "./types";
import { uid } from "./store";
import { isForbiddenSkill } from "./entity-lock";
import { detectSectionBoundaries } from "./section-boundary-parser";
import { extractSectionsFromResume } from "./dynamic-section-engine";
import { callAI, extractJSON } from "./ai";

function safeCall<T extends (...args: any[]) => any>(fn: T, args: Parameters<T>, fallback: ReturnType<T>): ReturnType<T> {
  try { return typeof fn === 'function' ? fn(...args) : fallback; } catch { return fallback; }
}

/**
 * Parse an uploaded file into a ResumeData object.
 * Supports: .txt, .pdf (via pdfjs-dist), .docx (via mammoth)
 */
export function calculateParserConfidence(resume: ResumeData): number {
  let score = 0;
  if (resume.summary && resume.summary.trim().length > 20) score += 25;
  if (resume.experience && resume.experience.length > 0) score += 25;
  if (resume.education && resume.education.length > 0) score += 20;
  if (resume.languages && resume.languages.length > 0) score += 15;
  if (resume.skills && resume.skills.length > 0) score += 10;
  if (resume.contact && (resume.contact.email || resume.contact.phone)) score += 5;
  return score;
}

export function validateParsedResume(resume: ResumeData): boolean {
  return (
    resume.experience.length > 0 ||
    resume.education.length > 0 ||
    resume.skills.length > 0
  );
}

export function RepairParser(text: string, fileName: string): ResumeData {
  console.log("RepairParser: Validation or confidence failed. Trying secondary parser...");
  let parsed = secondaryParser(text, fileName);
  let confidence = calculateParserConfidence(parsed);
  let isValid = validateParsedResume(parsed);

  if (!isValid) {
    console.log(`Secondary parser insufficient (confidence: ${confidence}, valid: ${isValid}). Trying heuristic parser...`);
    parsed = heuristicParser(text, fileName);
    confidence = calculateParserConfidence(parsed);
    isValid = validateParsedResume(parsed);
  }

  if (!isValid) {
    console.error("Heuristic parser failed to recover core sections. Throwing ParseError.");
    throw new Error("ParseError: Could not extract all required resume sections (Experience, Education) even after heuristic repair.");
  }

  return parsed;
}

export function secondaryParser(text: string, fileName: string): ResumeData {
  const normalizedText = text.replace(/\r/g, "");
  
  // Section regexes using line-start markers and word boundaries to avoid false matching
  const headerLookahead = `(?=(?:(?:^|\\n)\\s*(?:PROFESSIONAL EXPERIENCE|WORK EXPERIENCE|\\bEXPERIENCE\\b|EDUCATION|LANGUAGES|LANGUAGE|SKILLS|CORE COMPETENCIES|COMPETENCIES|CERTIFICATIONS|PROJECTS|REFERENCES|SUMMARY|PROFESSIONAL SUMMARY|CAREER OBJECTIVE|CAREER PROFILE|PROFESSIONAL PROFILE|ABOUT ME|PERSONAL INFORMATIONS|PERSONAL INFORMATION|PERSONAL INFO|PERSONAL DETAILS|INTERESTS|HOBBIES|NATIONALITY|CAREER HISTORY|PROFESSIONAL BACKGROUND|EMPLOYMENT HISTORY|PARCOURS PROFESSIONNEL|EXP[ÉE]RIENCES?(?:\\s+PROFESSIONNELLES?)?|EMPLOI|FORMATION|[ÉE]TUDES|COMP[ÉE]TENCES|LANGUES|PROFIL)\\b\\s*:?\\s*(?:\\n|$)))`;

  const expRegex = new RegExp('(?:^|\\n)\\s*(?:PROFESSIONAL EXPERIENCE|WORK EXPERIENCE|\\bEXPERIENCE\\b|\\bEXPERIENCES\\b|EMPLOYMENT HISTORY|HISTORY|CAREER HISTORY|PROFESSIONAL BACKGROUND|PARCOURS PROFESSIONNEL|EXP[ÉE]RIENCES?(?:\\s+PROFESSIONNELLES?)?|EMPLOI)\\b\\s*:?\\s*\\n([\\s\\S]*?)' + headerLookahead, 'i');
  const eduRegex = new RegExp('(?:^|\\n)\\s*(?:EDUCATION|ACADEMIC BACKGROUND|ACADEMIC|FORMATION|[ÉE]TUDES|PARCOURS ACAD[ÉE]MIQUE)\\b\\s*:?\\s*\\n([\\s\\S]*?)' + headerLookahead, 'i');
  const langRegex = new RegExp('(?:^|\\n)\\s*(?:LANGUAGES|LANGUAGE|LANGUES?(?:\\s+[ÉE]TRANG[ÈE]RES)?)\\b\\s*:?\\s*\\n([\\s\\S]*?)' + headerLookahead, 'i');
  // Also try inline format: "Languages: English, French, Arabic" (all on one line, no newline after colon)
  const langInlineRegex = /(?:^|\n)\s*(?:LANGUAGES|LANGUAGE)\s*:\s*([^\n]+)/i;
  const skillsRegex = new RegExp('(?:^|\\n)\\s*(?:SKILLS|TECHNICAL SKILLS|CORE SKILLS|CORE COMPETENCIES|CORE COMPETENCIES & SKILLS|COMPETENCIES|COMP[ÉE]TENCES?(?:\\s+(?:TECHNIQUES|CL[ÉE]S))?)\\b\\s*:?\\s*\\n([\\s\\S]*?)' + headerLookahead, 'i');
  const certsRegex = new RegExp('(?:^|\\n)\\s*(?:CERTIFICATIONS|CERTIFICATES|LICENSES)\\b\\s*:?\\s*\\n([\\s\\S]*?)' + headerLookahead, 'i');
  const projRegex = new RegExp('(?:^|\\n)\\s*(?:PROJECTS|PERSONAL PROJECTS|SIDE PROJECTS)\\b\\s*:?\\s*\\n([\\s\\S]*?)' + headerLookahead, 'i');
  const summaryRegex = new RegExp('(?:^|\\n)\\s*(?:SUMMARY|PROFESSIONAL SUMMARY|PROFILE|OBJECTIVE|CAREER OBJECTIVE|CAREER PROFILE|PROFESSIONAL PROFILE|ABOUT ME)\\b\\s*:?\\s*\\n([\\s\\S]*?)' + headerLookahead, 'i');

  const expMatch = normalizedText.match(expRegex);
  const eduMatch = normalizedText.match(eduRegex);
  const langMatch = normalizedText.match(langRegex);
  // Fallback: try "LANGUAGES" header to end of text (when languages is the last section)
  const langEndRegex = /(?:^|\n)\s*(?:LANGUAGES|LANGUAGE)\s*:?\s*\n([\s\S]+)$/i;
  const langEndMatch = !langMatch ? normalizedText.match(langEndRegex) : null;
  // Fallback 2: try inline format "Languages: English, French, Arabic" (all on one line)
  const langInlineMatch = !langMatch && !langEndMatch ? normalizedText.match(langInlineRegex) : null;
  const langLines = langMatch
    ? langMatch[1].split("\n").map(l => l.trim()).filter(Boolean)
    : langEndMatch
      ? langEndMatch[1].split("\n").map(l => l.trim()).filter(Boolean)
      : langInlineMatch
        ? langInlineMatch[1].split(/[,;]/).map(l => l.trim()).filter(Boolean)
        : [];
  const skillsMatch = normalizedText.match(skillsRegex);
  const certsMatch = normalizedText.match(certsRegex);
  const projMatch = normalizedText.match(projRegex);
  const summaryMatch = normalizedText.match(summaryRegex);

  const expLines = expMatch ? expMatch[1].split("\n").map(l => l.trim()).filter(Boolean) : [];
  const eduLines = eduMatch ? eduMatch[1].split("\n").map(l => l.trim()).filter(Boolean) : [];
  const skillsLines = skillsMatch ? skillsMatch[1].split("\n").map(l => l.trim()).filter(Boolean) : [];
  const certsLines = certsMatch ? certsMatch[1].split("\n").map(l => l.trim()).filter(Boolean) : [];
  const projLines = projMatch ? projMatch[1].split("\n").map(l => l.trim()).filter(Boolean) : [];
  const summary = summaryMatch ? summaryMatch[1].trim() : undefined;

  const experience = safeCall(parseExperiences, [expLines], []) as ResumeData["experience"];
  const education = safeCall(parseEducation, [eduLines], []) as ResumeData["education"];
  const skills = skillsLines
    .flatMap((l) => {
      // Detect "Category: item1, item2, item3" format — extract category + items
      const colonIdx = l.indexOf(":");
      if (colonIdx > 0 && colonIdx < 35) {
        const category = l.slice(0, colonIdx).trim();
        const rest = l.slice(colonIdx + 1);
        return rest.split(new RegExp("[,;•|]"))
          .map((s) => s.trim())
          .filter((s) => s.length > 0 && s.length < 40 && !isForbiddenSkill(s))
          .map((name) => ({ id: uid("s"), name, category }));
      }
      // Fallback: flat comma-separated skill names
      return l.split(new RegExp("[,;•|]"))
        .map((s) => s.trim())
        .filter((s) => s.length > 0 && s.length < 40 && !isForbiddenSkill(s))
        .map((s) => ({ id: uid("s"), name: s }));
    })
  const projects = parseProjects(projLines);
  const certifications = certsLines.map((c) => ({ id: uid("c"), name: c }));
  const languages: ResumeData["languages"] = [];
  const seenLangs = new Set<string>();
  for (const line of langLines) {
    const parts = line.split(new RegExp("[,;]"));
    for (const part of parts) {
      const detected = detectLanguage(part);
      if (detected && !seenLangs.has(detected.name.toLowerCase())) {
        seenLangs.add(detected.name.toLowerCase());
        languages.push({
          id: uid("l"),
          name: detected.name,
          proficiency: detected.proficiency,
        });
      }
    }
  }

  // Extract contact
  const firstLines = normalizedText.split("\n").slice(0, 15).join("\n");
  const emailMatch = firstLines.match(EMAIL_RE);
  const phoneMatch = firstLines.match(PHONE_RE);
  const urlMatches = Array.from(firstLines.matchAll(new RegExp(URL_RE.source, "gi"))).map((m) => m[0]);
  const linkedin = urlMatches.find((u) => /linkedin/i.test(u));
  const github = urlMatches.find((u) => /github/i.test(u));
  const website = urlMatches.find((u) => !/linkedin|github/i.test(u));
  // Try to find a location pattern near the top
  // Allow 1-3 capitalized words before the comma (e.g. "San Francisco, CA", "New York City, NY").
  // Also allow capitalized country/state names after the comma (e.g. "Rabat, Morocco", "London, United Kingdom").
  const locationLine = normalizedText.split("\n").slice(0, 15).find((l) => /\b([A-Z][a-zA-Z]+(?:\s+[A-Z][a-zA-Z]+){0,2},\s?[A-Z][a-zA-Z]+(?:\s+[A-Z][a-zA-Z]+)?)\b/.test(l));
  const location = locationLine?.match(/\b([A-Z][a-zA-Z]+(?:\s+[A-Z][a-zA-Z]+){0,2},\s?[A-Z][a-zA-Z]+(?:\s+[A-Z][a-zA-Z]+)?)\b/)?.[1];

  const name = extractNameFromLines(normalizedText.split("\n"));

  const now = new Date().toISOString();
  const baseResume: ResumeData = {
    id: uid("r"),
    name,
    contact: { email: emailMatch?.[1], phone: phoneMatch?.[1]?.trim(), location, website, linkedin, github },
    summary,
    experience,
    education,
    skills,
    projects,
    certifications,
    languages,
    template: "ats-professional" as const,
    accentColor: "#1154A3",
    createdAt: now,
    updatedAt: now,
    source: "upload",
    fileName,
  };

  // Populate dynamicSections from the engine to capture any
  // non-standard sections parsed from the source resume
  const dynamicSections = extractSectionsFromResume(baseResume).filter(
    (s) => !["summary", "experience", "education", "skills", "languages", "additionalinformation", "certifications", "projects", "achievements"].includes(s.normalizedTitle)
  );

  return cleanupParsedResume({
    ...baseResume,
    dynamicSections,
  });
}

export function cleanupParsedResume(resume: ResumeData): ResumeData {
  const cleaned = { ...resume };

  // 1. Clean up Languages
  if (Array.isArray(cleaned.languages)) {
    const validLanguages: typeof cleaned.languages = [];
    const seenLangs = new Set<string>();

    for (const lang of cleaned.languages) {
      let name = (lang.name || "").trim();
      // Remove generic descriptions like "Trilingual Communication", "Linguistic Skills"
      if (/trilingual|bilingual|multilingual|communication|linguistic|skills/i.test(name)) {
        continue;
      }
      // Remove trailing/leading punctuation and parenthesis fragments
      name = name.replace(/^[^a-zA-Z\s]+|[^a-zA-Z\s\(\)]+$/g, "").trim();
      // Clean up parentheses, e.g. "Arabic (Native" -> "Arabic"
      name = name.replace(/\s*\(.*$/, "").trim();
      
      const lowerName = name.toLowerCase();
      // Validate it is a known language or looks like one
      if (lowerName.length > 2 && !seenLangs.has(lowerName)) {
        seenLangs.add(lowerName);
        validLanguages.push({
          ...lang,
          name: name.charAt(0).toUpperCase() + name.slice(1),
          proficiency: lang.proficiency || "fluent"
        });
      }
    }
    cleaned.languages = validLanguages;
  }

  // 2. Clean up Skills
  if (Array.isArray(cleaned.skills)) {
    const validSkills: typeof cleaned.skills = [];
    const seenSkills = new Set<string>();

    for (const skill of cleaned.skills) {
      const rawName = (skill.name || "").trim();
      if (!rawName) continue;

      // Split if it contains commas, semicolons, or bullet/bar characters
      const parts = rawName.split(/[,;•|]/);
      for (const part of parts) {
        let name = part.trim();
        // Remove trailing/leading punctuation like parenthese fragments
        name = name.replace(/^[\s\(\)•\-\*]+|[\s\(\)•\-\*]+$/g, "").trim();
        
        // Skip if it looks like a language declaration inside skills
        if (/^(?:languages|language)\s*:/i.test(name) || /^(?:english|french|arabic|spanish|german|chinese)\)?$/i.test(name)) {
          continue;
        }

        const lowerName = name.toLowerCase();
        // Filter out short/empty names or duplicates
        if (name.length > 1 && name.length < 60 && !isForbiddenSkill(name) && !seenSkills.has(lowerName)) {
          seenSkills.add(lowerName);
          validSkills.push({
            id: skill.id || `s-${Math.random().toString(36).slice(2, 9)}`,
            name,
            category: skill.category || "General"
          });
        }
      }
    }
    cleaned.skills = validSkills;
  }

  return cleaned;
}

export function heuristicParser(text: string, fileName: string): ResumeData {
  const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
  let currentSection = "header";
  
  const sectionLines: { [key: string]: string[] } = {
    header: [],
    summary: [],
    experience: [],
    education: [],
    languages: [],
    skills: [],
    certifications: [],
    projects: [],
  };

  for (const line of lines) {
    if (/^\s*(?:(?:summary|profile|objective|career\s+objective|career\s+profile|professional\s+profile|about\s+me)s?|profil(?:\s+professionnel)?|objectif\s+de\s+carri[èe]re|[àa]\s+propos(?:\s+de\s+moi)?)\s*:?$/i.test(line)) {
      currentSection = "summary";
      continue;
    } else if (/^\s*(?:professional\s+)?experience[s]?|work\s+experience|employment\s+history|history\s*:?$/i.test(line) ||
               /^\s*(?:career\s+history|professional\s+background|parcours\s+professionnel|exp[ée]riences?(?:\s+professionnelles?)?|emplois?)\s*:?$/i.test(line)) {
      currentSection = "experience";
      continue;
    } else if (/^\s*(?:education|academic(?:\s+background)?|academic\s+history|formation(?:s)?|[ée]tudes?|parcours\s+acad[ée]mique)\s*:?$/i.test(line)) {
      currentSection = "education";
      continue;
    } else if (/^\s*(?:languages|language|langues?(?:\s+[ée]trang[èe]res)?)\s*:?$/i.test(line)) {
      currentSection = "languages";
      continue;
    } else if (/^\s*(?:skills|core\s+competencies|competencies|technical\s+skills|comp[ée]tences?(?:\s+(?:techniques|cl[ée]s))?)\s*:?$/i.test(line)) {
      currentSection = "skills";
      continue;
    } else if (/^\s*(?:certifications|certificates)\s*:?$/i.test(line)) {
      currentSection = "certifications";
      continue;
    } else if (/^\s*(?:projects)\s*:?$/i.test(line)) {
      currentSection = "projects";
      continue;
    }

    // Extract inline "Languages: English, French, Arabic" from skills section
    if (currentSection === "skills" && /^\s*languages?\s*:/i.test(line)) {
      sectionLines.languages.push(line);
      continue;
    }

    sectionLines[currentSection].push(line);
  }

  const summary = sectionLines.summary.join(" ").trim() || undefined;
  const experience = parseExperiences(sectionLines.experience);
  const education = parseEducation(sectionLines.education);
  const skills = sectionLines.skills
    .flatMap((l) => {
      // Detect "Category: item1, item2, item3" format — extract category + items
      const colonIdx = l.indexOf(":");
      if (colonIdx > 0 && colonIdx < 35) {
        const category = l.slice(0, colonIdx).trim();
        const rest = l.slice(colonIdx + 1);
        return rest.split(new RegExp("[,;•|]"))
          .map((s) => s.trim())
          .filter((s) => s.length > 0 && s.length < 40 && !isForbiddenSkill(s))
          .map((name) => ({ id: uid("s"), name, category }));
      }
      // Fallback: flat comma-separated skill names
      return l.split(new RegExp("[,;•|]"))
        .map((s) => s.trim())
        .filter((s) => s.length > 0 && s.length < 40 && !isForbiddenSkill(s))
        .map((s) => ({ id: uid("s"), name: s }));
    })
  const projects = parseProjects(sectionLines.projects);
  const certifications = sectionLines.certifications.map((c) => ({ id: uid("c"), name: c }));
  const languages: ResumeData["languages"] = [];
  const seenLangs = new Set<string>();
  for (const line of sectionLines.languages) {
    const parts = line.split(new RegExp("[,;]"));
    for (const part of parts) {
      const detected = detectLanguage(part);
      if (detected && !seenLangs.has(detected.name.toLowerCase())) {
        seenLangs.add(detected.name.toLowerCase());
        languages.push({
          id: uid("l"),
          name: detected.name,
          proficiency: detected.proficiency,
        });
      }
    }
  }

  // Contact info
  const headerText = sectionLines.header.join("\n");
  const emailMatch = headerText.match(EMAIL_RE);
  const phoneMatch = headerText.match(PHONE_RE);
  const urlMatches = Array.from(headerText.matchAll(new RegExp(URL_RE.source, "gi"))).map((m) => m[0]);
  const linkedin = urlMatches.find((u) => /linkedin/i.test(u));
  const github = urlMatches.find((u) => /github/i.test(u));
  const website = urlMatches.find((u) => !/linkedin|github/i.test(u));
  const locationLine = sectionLines.header.find((l) => /\b([A-Z][a-zA-Z]+(?:\s+[A-Z][a-zA-Z]+){0,2},\s?[A-Z][a-zA-Z]+(?:\s+[A-Z][a-zA-Z]+)?)\b/.test(l));
  const location = locationLine?.match(/\b([A-Z][a-zA-Z]+(?:\s+[A-Z][a-zA-Z]+){0,2},\s?[A-Z][a-zA-Z]+(?:\s+[A-Z][a-zA-Z]+)?)\b/)?.[1];

  const name = extractNameFromLines(sectionLines.header);

  const now = new Date().toISOString();
  const baseHeuristicResume: ResumeData = {
    id: uid("r"),
    name,
    contact: { email: emailMatch?.[1], phone: phoneMatch?.[1]?.trim(), location, website, linkedin, github },
    summary,
    experience,
    education,
    skills,
    projects,
    certifications,
    languages,
    template: "ats-professional" as const,
    accentColor: "#1154A3",
    createdAt: now,
    updatedAt: now,
    source: "upload",
    fileName,
  };

  // Populate dynamicSections from the engine to capture any
  // non-standard sections parsed from the source resume
  const heuristicDynamicSections = extractSectionsFromResume(baseHeuristicResume).filter(
    (s) => !["summary", "experience", "education", "skills", "languages", "additionalinformation", "certifications", "projects", "achievements"].includes(s.normalizedTitle)
  );

  return cleanupParsedResume({
    ...baseHeuristicResume,
    dynamicSections: heuristicDynamicSections,
  });
}

export async function parseResumeFile(file: File): Promise<ResumeData> {
  try {
    const name = file.name.toLowerCase();
    let rawText = "";

    if (name.endsWith(".txt")) {
      rawText = await file.text();
    } else if (name.endsWith(".pdf")) {
      rawText = await parsePdf(file);
    } else if (name.endsWith(".docx")) {
      rawText = await parseDocx(file);
    } else if (name.endsWith(".doc")) {
      rawText = await file.text().catch(() => "");
      if (!rawText.trim()) {
        console.warn("[parser] Legacy .doc not parseable in-browser. Returning blank resume.");
        return blankResume(file.name.replace(/\.[^/.]+$/, ""));
      }
    } else {
      console.warn("[parser] Unsupported file type. Returning blank resume.");
      return blankResume(file.name.replace(/\.[^/.]+$/, ""));
    }

    if (rawText.trim().length < 30) {
      console.warn("[parser] File appears empty or unparseable. Returning blank resume.");
      return blankResume(file.name.replace(/\.[^/.]+$/, ""));
    }

    try {
      console.log("[parser] Attempting AI parsing...");
      const aiParsed = await extractResumeWithAI(rawText, file.name);
      if (aiParsed && (aiParsed.experience.length > 0 || aiParsed.education.length > 0)) {
        // EXPERIENCE GAP GUARD: the AI parse is accepted when education OR
        // experience is present, but a resume without experience entries can
        // NEVER pass the downstream Structure Guardian ("Experience section
        // is empty" veto) — the optimizer would burn all its attempts on a
        // doomed job. If the AI missed the experience section, try the
        // heuristic parser and merge what it found (AI sections win when
        // non-empty).
        if (aiParsed.experience.length === 0) {
          const heuristic = safeCall(extractResumeFromText, [rawText, file.name], null as any);
          if (heuristic && heuristic.experience.length > 0) {
            console.warn(`[parser] AI parse missed the experience section — merging ${heuristic.experience.length} heuristic experience entry(ies)`);
            return mergeAiParsedWithHeuristics(aiParsed, heuristic);
          }
        }
        console.log("[parser] AI parsing successful");
        return aiParsed;
      }
      console.warn("[parser] AI parsed result is empty or incomplete, falling back to heuristics");
    } catch (aiErr) {
      console.warn("[parser] AI parsing encountered an error:", aiErr);
    }

    const primaryResult = safeCall(extractResumeFromText, [rawText, file.name], null as any);
    if (!primaryResult) {
      console.warn("[parser] extractResumeFromText failed. Returning blank resume.");
      return blankResume(file.name.replace(/\.[^/.]+$/, ""));
    }

    const primaryConfidence = safeCall(calculateParserConfidence, [primaryResult], 0);
    const isValid = safeCall(validateParsedResume, [primaryResult], false);

    if (!isValid) {
      console.warn(`[parser] Primary parser incomplete (valid: ${isValid}, confidence: ${primaryConfidence}). Running RepairParser...`);
      const repaired = safeCall(RepairParser, [rawText, file.name], null as any);
      if (repaired) {
        // MERGE: if primary had languages/experience/education that the repair lost, restore them
        if (primaryResult.languages?.length > 0 && (!repaired.languages || repaired.languages.length === 0)) {
          repaired.languages = primaryResult.languages;
        }
        if (primaryResult.experience?.length > 0 && (!repaired.experience || repaired.experience.length === 0)) {
          repaired.experience = primaryResult.experience;
        }
        if (primaryResult.education?.length > 0 && (!repaired.education || repaired.education.length === 0)) {
          repaired.education = primaryResult.education;
        }
        if (primaryResult.skills?.length > 0 && (!repaired.skills || repaired.skills.length === 0)) {
          repaired.skills = primaryResult.skills;
        }
        return repaired;
      }
      console.warn("[parser] RepairParser also failed. Returning primary result as-is.");
    }

    return primaryResult;
  } catch (e) {
    console.error("[parser] parseResumeFile unexpected error:", e);
    return blankResume(file.name.replace(/\.[^/.]+$/, ""));
  }
}

