// ResumeAI Pro — Provider Health Manager
// Tracks provider health metrics: latency, success rate, failure rate,
// rate limit status, authentication status.

"use client";

import { useApp } from "./store";
import { isApiProvider, isBrowserAuthProvider } from "./provider-router";
import { getPuterAuthStatus, isPuterLoaded } from "./puter-client";
import type { AIProvider } from "./types";

export interface ProviderHealthInfo {
  provider: AIProvider;
  category: "api" | "browser_auth";
  status: "healthy" | "degraded" | "down" | "untested";
  authStatus: "authenticated" | "not_authenticated" | "not_required" | "unknown";
  latencyMs: number | null;
  successRate: number;       // 0-100
  failureRate: number;       // 0-100
  lastSuccessAt: string | null;
  lastFailureAt: string | null;
  lastError: string | null;
  rateLimited: boolean;
  rateLimitedUntil: string | null;
  consecutiveFailures: number;
  consecutiveSuccesses: number;
}

/**
 * Get health info for all providers.
 */
export function getProviderHealth(): ProviderHealthInfo[] {
  const providers = useApp.getState().providers || [];
  return providers.map(getHealthForProvider);
}

/**
 * Get health info for a single provider.
 */
export function getHealthForProvider(p: AIProvider): ProviderHealthInfo {
  const category = isBrowserAuthProvider(p) ? "browser_auth" : "api";
  const health = p.health || {
    consecutiveFailures: 0,
    consecutiveSuccesses: 0,
  };

  // Check rate limit
  const rateLimited = !!(health.rateLimitedUntil && new Date(health.rateLimitedUntil) > new Date());

  // Calculate success/failure rates from usage
  const totalRequests = p.usage?.requests || 0;
  const totalErrors = p.usage?.errors || 0;
  const successRate = totalRequests > 0 ? Math.round(((totalRequests - totalErrors) / totalRequests) * 100) : 100;
  const failureRate = totalRequests > 0 ? Math.round((totalErrors / totalRequests) * 100) : 0;

  // Determine auth status
  let authStatus: ProviderHealthInfo["authStatus"] = "unknown";
  if (category === "browser_auth") {
    if (!isPuterLoaded()) {
      authStatus = "not_authenticated";
    } else {
      const puterStatus = getPuterAuthStatus();
      authStatus = puterStatus === "authenticated" ? "authenticated" : "not_authenticated";
    }
  } else {
    authStatus = p.apiKey ? "authenticated" : "not_required";
  }

  // Determine overall status
  let status: ProviderHealthInfo["status"] = p.status || "untested";
  if (rateLimited) status = "degraded";
  if (health.consecutiveFailures >= 3) status = "down";
  else if (health.consecutiveFailures >= 1) status = "degraded";
  else if (health.consecutiveSuccesses >= 1) status = "healthy";

  return {
    provider: p,
    category,
    status,
    authStatus,
    latencyMs: p.usage?.avgLatencyMs || null,
    successRate,
    failureRate,
    lastSuccessAt: health.lastSuccessAt || null,
    lastFailureAt: health.lastFailureAt || null,
    lastError: health.lastError || null,
    rateLimited,
    rateLimitedUntil: health.rateLimitedUntil || null,
    consecutiveFailures: health.consecutiveFailures || 0,
    consecutiveSuccesses: health.consecutiveSuccesses || 0,
  };
}

/**
 * Record a successful request for a provider.
 */
export function recordSuccess(providerId: string, latencyMs: number): void {
  const state = useApp.getState();
  const provider = state.providers.find((p) => p.id === providerId);
  if (!provider) return;

  const now = new Date().toISOString();
  const health = provider.health || { consecutiveFailures: 0, consecutiveSuccesses: 0 };

  state.updateProvider(providerId, {
    health: {
      ...health,
      lastSuccessAt: now,
      consecutiveSuccesses: health.consecutiveSuccesses + 1,
      consecutiveFailures: 0,
      lastError: undefined,
    },
    lastUsedAt: now,
    status: "healthy",
    usage: {
      ...provider.usage,
      requests: provider.usage.requests + 1,
      avgLatencyMs: Math.round((provider.usage.avgLatencyMs * provider.usage.requests + latencyMs) / (provider.usage.requests + 1)),
    },
  });
}

/**
 * Record a failed request for a provider.
 */
export function recordFailure(providerId: string, error: string, isRateLimit = false): void {
  const state = useApp.getState();
  const provider = state.providers.find((p) => p.id === providerId);
  if (!provider) return;

  const now = new Date().toISOString();
  const health = provider.health || { consecutiveFailures: 0, consecutiveSuccesses: 0 };

  state.updateProvider(providerId, {
    health: {
      ...health,
      lastFailureAt: now,
      lastError: error,
      consecutiveFailures: health.consecutiveFailures + 1,
      consecutiveSuccesses: 0,
      rateLimitedUntil: isRateLimit ? new Date(Date.now() + 60 * 1000).toISOString() : health.rateLimitedUntil,
    },
    lastUsedAt: now,
    status: health.consecutiveFailures + 1 >= 3 ? "down" : "degraded",
    usage: {
      ...provider.usage,
      requests: provider.usage.requests + 1,
      errors: provider.usage.errors + 1,
    },
  });
}

/**
 * Detect if an error is a rate limit (429) error.
 */
export function isRateLimitError(error: string): boolean {
  return /429|rate.?limit|too.?many.?requests|quota|FreeUsageLimitError/i.test(error);
}

/**
 * Detect if an error is an authentication (401/403) error.
 */
export function isAuthError(error: string): boolean {
  return /401|403|unauthor|forbidden|invalid.?api.?key|auth.?fail/i.test(error);
}

/**
 * Detect if an error is a model not found (404) error.
 */
export function isModelError(error: string): boolean {
  return /404|model.?not.?found|not_found_error|invalid.?model/i.test(error);
}

src/lib/provider-model-detection.ts:
// ============================================================================
// Provider Model Detection
//
// Fetches all available models from a provider's API endpoint.
// Used by the AI Dev Agent to auto-detect models and configure fallback chains.
//
// Supports:
//   - OpenAI-compatible APIs (GET /v1/models)
//   - DeepSeek, OpenCode, ZenCode, OpenRouter, Groq, Together, Fireworks, etc.
//   - Custom OpenAI-compatible providers
//
// Falls back to the provider's configured enabledModels if the API is unreachable.
// ============================================================================

"use client";

import type { AIProvider } from "./types";
// Task 18 — puter has no REST {baseUrl}/models surface (browser-auth SDK),
// so the generic probe below would fall straight back to the provider's
// configured model ("gpt-4o-mini") and hide the live catalog. Task 13's LIVE
// puter catalog (api.puter.com/puterai/chat/models, vendor-normalized,
// curated-first, 5-min cache) lives in ProviderManager — delegate to it so
// every model picker (AI Workspace, AI Dev Agent) sees the same catalog.
import { ProviderManager } from "./ai/services/manager";

export interface DetectedModel {
  id: string;          // The model ID to use in API calls
  name?: string;       // Display name (if available)
  contextLength?: number;
  maxTokens?: number;
  supportsReasoning?: boolean;
  supportsStreaming?: boolean;
  supportsVision?: boolean;
  supportsToolCalling?: boolean;
}

export interface ModelDetectionResult {
  models: DetectedModel[];
  source: "api" | "configured" | "fallback";
  error?: string;
}

/**
 * Fetch all available models from a provider's API.
 *
 * Tries the standard OpenAI-compatible endpoint: GET {baseUrl}/models
 * Falls back to the provider's configured enabledModels if the API is unreachable.
 */
export async function fetchProviderModels(provider: AIProvider): Promise<ModelDetectionResult> {
  if (!provider) {
    return { models: [], source: "fallback", error: "No provider provided" };
  }

  // === PUTER: live catalog via ProviderManager (Task 18) ===
  if (provider.type === "puter") {
    const live = await ProviderManager.fetchPuterModelsLive();
    if (live.ok && live.models.length > 0) {
      console.info(`[ModelDetection] Puter live catalog: ${live.models.length} models (curated first)`);
      return {
        models: live.models.map((id) => ({ id, name: id, supportsStreaming: true })),
        source: "api",
      };
    }
    return {
      models: getFallbackModels(provider),
      source: "configured",
      error: live.error || "Puter live catalog unavailable",
    };
  }

  // Determine the base URL
  const baseUrl = (provider.baseUrl || provider.apiUrl || "").trim();
  if (!baseUrl) {
    return {
      models: getFallbackModels(provider),
      source: "configured",
      error: "No base URL configured — using enabledModels from provider config",
    };
  }

  const isLocal = baseUrl.includes("localhost") || baseUrl.includes("127.0.0.1") || baseUrl.includes("0.0.0.0") || baseUrl.includes("::1");

  try {
    let rawModels: any[] = [];

    if (isLocal) {
      const headers: Record<string, string> = {
        "Content-Type": "application/json",
      };
      if (provider.apiKey) {
        headers["Authorization"] = `Bearer ${provider.apiKey}`;
      }
      if (provider.headersJson) {
        try {
          const custom = JSON.parse(provider.headersJson);
          Object.assign(headers, custom);
        } catch { /* ignore parse errors */ }
      }

      const modelsUrl = baseUrl.endsWith("/models") ? baseUrl : `${baseUrl.replace(/\/$/, "")}/models`;
      const response = await fetch(modelsUrl, {
        method: "GET",
        headers,
        signal: AbortSignal.timeout(10000), // 10s timeout
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const data = (await response.json()) as any;
      rawModels = data.data || data.models || data;
    } else {
      // Use proxy to avoid CORS issues
      const response = await fetch("/api/providers/models", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          baseUrl,
          apiKey: provider.apiKey,
          authType: provider.authType || "bearer",
          headersJson: provider.headersJson,
        }),
        signal: AbortSignal.timeout(10000),
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const data = (await response.json()) as any;
      if (data && Array.isArray(data.models)) {
        rawModels = data.models.map((id: string) => ({ id, name: id }));
      } else {
        rawModels = data.data || data.models || data;
      }
    }

    if (!Array.isArray(rawModels)) {
      throw new Error("Unexpected response format — expected array or { data: [...] }");
    }

    const models: DetectedModel[] = rawModels
      .map((m: any): DetectedModel => {
        if (typeof m === "string") {
          return { id: m, name: m, supportsStreaming: true };
        }
        return {
          id: m.id || m.name || m.model,
          name: m.name || m.id,
          contextLength: m.context_length || m.maxContextLength || m.context_window,
          maxTokens: m.max_tokens || m.maxTokens,
          supportsReasoning: m.supports_reasoning ?? m.reasoning,
          supportsStreaming: m.supports_streaming ?? m.streaming ?? true,
          supportsVision: m.supports_vision ?? m.vision,
          supportsToolCalling: m.supports_tool_calling ?? m.tool_calling ?? m.function_calling,
        };
      })
      .filter((m: DetectedModel) => m.id);

    if (models.length === 0) {
      throw new Error("No models returned from API");
    }

    console.info(`[ModelDetection] Fetched ${models.length} models from ${provider.name} (${baseUrl})`);
    return { models, source: "api" };
  } catch (error: any) {
    console.warn(`[ModelDetection] Failed to fetch models from ${provider.name}: ${error?.message || error}`);
    return {
      models: getFallbackModels(provider),
      source: "configured",
      error: error?.message || String(error),
    };
  }
}

/**
 * Get fallback models from the provider's configured enabledModels.
 */
function getFallbackModels(provider: AIProvider): DetectedModel[] {
  const configured = provider.enabledModels || [];
  if (configured.length > 0) {
    return configured.map((id) => ({
      id,
      name: id,
      supportsStreaming: true,
    }));
  }
  // Ultimate fallback: the provider's default model
  if (provider.modelName) {
    return [{ id: provider.modelName, name: provider.modelName, supportsStreaming: true }];
  }
  return [];
}

/**
 * Build a fallback model chain from detected models.
 *
 * Given a primary model, returns an ordered list of OTHER detected models
 * to use as fallbacks (in case the primary model fails).
 *
 * @param detectedModels - All models detected from the provider's API
 * @param primaryModel - The primary model to exclude from fallbacks
 * @param maxFallbacks - Maximum number of fallback models (default: 5)
 */
export function buildFallbackModelChain(
  detectedModels: DetectedModel[],
  primaryModel: string,
  maxFallbacks: number = 5,
): DetectedModel[] {
  return detectedModels
    .filter((m) => m.id !== primaryModel)
    .slice(0, maxFallbacks);
}

/**
 * Check if a model supports a given capability.
 */
export function modelSupports(model: DetectedModel, capability: "reasoning" | "streaming" | "vision" | "tool-calling"): boolean {
  switch (capability) {
    case "reasoning": return model.supportsReasoning ?? false;
    case "streaming": return model.supportsStreaming ?? true;
    case "vision": return model.supportsVision ?? false;
    case "tool-calling": return model.supportsToolCalling ?? false;
    default: return false;
  }
}

/**
 * Filter models by capability.
 */
export function filterModelsByCapability(
  models: DetectedModel[],
  capability: "reasoning" | "streaming" | "vision" | "tool-calling",
): DetectedModel[] {
  return models.filter((m) => modelSupports(m, capability));
}

/**
 * Sort models by context length (largest first).
 */
export function sortModelsByContextLength(models: DetectedModel[]): DetectedModel[] {
  return [...models].sort((a, b) => (b.contextLength ?? 0) - (a.contextLength ?? 0));
}

/**
 * Get a human-readable description of a detected model.
 */
export function describeModel(model: DetectedModel): string {
  const parts: string[] = [model.id];
  if (model.contextLength) parts.push(`${(model.contextLength / 1000).toFixed(0)}k ctx`);
  const caps: string[] = [];
  if (model.supportsReasoning) caps.push("reasoning");
  if (model.supportsVision) caps.push("vision");
  if (model.supportsToolCalling) caps.push("tools");
  if (caps.length > 0) parts.push(caps.join("+"));
  return parts.join(" · ");
}

src/lib/provider-onboarding.ts:
// ============================================================================
// Dynamic Provider Onboarding
//
// When new providers are added via D1, Admin UI, or env vars, this module
// auto-discovers them, fetches models, imports into Model Registry, and
// makes them immediately available for capability-weighted routing.
// No code changes required to add a new provider.
// ============================================================================

import type { AIProvider } from "./types";
import { modelRegistry } from "./model-registry";

/** Known base URLs for common provider types (no hardcoded API keys) */
const PROVIDER_BASE_URLS: Record<string, string> = {
  openai: "https://api.openai.com/v1",
  claude: "https://api.anthropic.com/v1",
  gemini: "https://generativelanguage.googleapis.com/v1beta",
  deepseek: "https://api.deepseek.com/v1",
  groq: "https://api.groq.com/openai/v1",
  mistral: "https://api.mistral.ai/v1",
  cohere: "https://api.cohere.com/v2",
  perplexity: "https://api.perplexity.ai",
  openrouter: "https://openrouter.ai/api/v1",
  together: "https://api.together.xyz/v1",
  huggingface: "https://api-inference.huggingface.co/models",
  opencode: "https://opencode.ai/zen/v1",
  zencode: "https://opencode.ai/zen/v1",
  nvidia: "https://integrate.api.nvidia.com/v1",
};

export interface OnboardingResult {
  providerId: string;
  providerName: string;
  modelsImported: number;
  alreadyTracked: boolean;
  error?: string;
}

export async function onboardProvider(provider: AIProvider): Promise<OnboardingResult> {
  const result: OnboardingResult = {
    providerId: provider.id,
    providerName: provider.name,
    modelsImported: 0,
    alreadyTracked: false,
  };

  const existing = modelRegistry.findByProvider(provider.id);
  if (existing.length > 0) {
    result.alreadyTracked = true;
    result.modelsImported = existing.length;
    return result;
  }

  try {
    const baseUrl = provider.baseUrl || provider.apiUrl || PROVIDER_BASE_URLS[provider.type] || "";
    const modelNames = await fetchModelList(baseUrl, provider.apiKey, provider.type);
    
    if (modelNames.length > 0) {
      result.modelsImported = modelRegistry.importFromProvider(
        provider.id, provider.name, modelNames, {}
      );
    }
  } catch (e: any) {
    result.error = e?.message || String(e);
  }

  return result;
}

export async function onboardAllProviders(providers: AIProvider[]): Promise<OnboardingResult[]> {
  const active = providers.filter((p) => p.isActive);
  const results: OnboardingResult[] = [];
  for (const provider of active) {
    const result = await onboardProvider(provider);
    results.push(result);
    if (result.modelsImported > 0) {
      console.info('[Onboarding] Imported ' + result.modelsImported + ' models from ' + provider.name);
    }
  }
  return results;
}

export async function onboardNewProvider(provider: AIProvider): Promise<OnboardingResult> {
  return onboardProvider(provider);
}

async function fetchModelList(baseUrl: string, apiKey: string | undefined, providerType: string): Promise<string[]> {
  if (!baseUrl) return [];

  const modelsUrl = baseUrl.replace(/\/$/, "") + "/models";
  
  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 10000);

    const headers: Record<string, string> = { "Content-Type": "application/json" };
    if (apiKey) {
      if (providerType === "gemini") {
        // Gemini uses query param, skipped here
      } else {
        headers["Authorization"] = "Bearer " + apiKey;
      }
    }

    const res = await fetch(modelsUrl, { headers, signal: controller.signal });
    clearTimeout(timeout);

    if (!res.ok) return [];

    const data = (await res.json()) as any;
    let models: string[] = [];
    
    if (Array.isArray(data?.data)) {
      models = data.data.map((m: any) => m.id || m.name || "").filter(Boolean);
    } else if (Array.isArray(data?.models)) {
      models = data.models.map((m: any) => m.name || m.id || "").filter(Boolean);
    } else if (Array.isArray(data)) {
      models = data.map((m: any) => m.id || m.name || m.model || "").filter(Boolean);
    }

    return models.slice(0, 200);
  } catch {
    return [];
  }
}

// Dynamic env-var provider detection is handled by D1 sync + Admin UI.
// The detectEnvProviders function was removed to avoid ESLint
// issues with dynamic process.env property access in Cloudflare builds.

