// ResumeAI Pro — Session Manager
// Manages provider sessions with encrypted token storage.
// Persists to localStorage (client) and D1/KV (cloud).
// Tokens are NEVER stored in plain text.

import type { ProviderSession } from "./interface";
import { createEmptySession } from "./interface";

// ============================================================================
// Encryption helpers using Web Crypto API (available in Edge + browser)
// ============================================================================

// Derive encryption key from a combination of origin + user agent fingerprint.
// This is NOT as secure as a per-user secret, but it's much better than a
// hardcoded key in source code. The key is unique per origin+browser combo,
// so stealing the source code does NOT give the decryption key.
// For production, replace with a proper server-side key management system.
async function getEncryptionKey(): Promise<CryptoKey> {
  // Create a stable but origin-specific key material
  const origin = typeof window !== "undefined" ? window.location.origin : "resumeai-pro-fallback";
  const ua = typeof navigator !== "undefined" ? navigator.userAgent : "unknown-ua";
  const keyMaterial = `ResumeAI-Pro-Session-${origin}-${ua.slice(0, 32)}`;

  // Use PBKDF2 to derive a proper AES-GCM key from the material
  const encoder = new TextEncoder();
  const baseKey = await crypto.subtle.importKey(
    "raw",
    encoder.encode(keyMaterial),
    { name: "PBKDF2" },
    false,
    ["deriveKey"],
  );

  // Use a fixed salt (acceptable for same-origin derivation — the salt
  // prevents rainbow table attacks even though it's in source code)
  const salt = encoder.encode("ResumeAI-Pro-PBKDF2-Salt-v1");

  return crypto.subtle.deriveKey(
    {
      name: "PBKDF2",
      salt,
      iterations: 100000, // OWASP recommended minimum
      hash: "SHA-256",
    },
    baseKey,
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"],
  );
}

/**
 * Encrypt a string value using AES-GCM.
 * Returns base64-encoded ciphertext.
 */
export async function encryptValue(plaintext: string | null): Promise<string | null> {
  if (!plaintext) return null;
  try {
    const key = await getEncryptionKey();
    const encoder = new TextEncoder();
    const iv = crypto.getRandomValues(new Uint8Array(12));
    const ciphertext = await crypto.subtle.encrypt(
      { name: "AES-GCM", iv },
      key,
      encoder.encode(plaintext),
    );
    // Combine iv + ciphertext and base64 encode
    const combined = new Uint8Array(iv.length + ciphertext.byteLength);
    combined.set(iv);
    combined.set(new Uint8Array(ciphertext), iv.length);
    // Use chunked encoding to avoid "Maximum call stack size exceeded" for large payloads
    return uint8ToBase64(combined);
  } catch (e) {
    // CRITICAL: Encryption failure must NOT silently store plaintext tokens.
    // Return a marker that indicates encryption failed — callers must handle this.
    console.error("[SessionManager] Encryption FAILED — refusing to store unencrypted token!", e);
    // Return null to signal encryption failure — the session manager should
    // refuse to persist rather than storing plaintext.
    return null;
  }
}

/**
 * Decrypt a value encrypted by encryptValue().
 */
export async function decryptValue(ciphertext: string | null): Promise<string | null> {
  if (!ciphertext) return null;
  try {
    const key = await getEncryptionKey();
    const combined = Uint8Array.from(atob(ciphertext), (c) => c.charCodeAt(0));
    const iv = combined.slice(0, 12);
    const data = combined.slice(12);
    const plaintext = await crypto.subtle.decrypt(
      { name: "AES-GCM", iv },
      key,
      data,
    );
    return new TextDecoder().decode(plaintext);
  } catch {
    // Decryption failed — might be unencrypted (from older version)
    // or the key material changed (different browser/origin)
    // Return the raw value and let the caller validate it
    console.warn("[SessionManager] Decryption failed — data may be from a different origin or older version");
    return null; // Don't return ciphertext as plaintext
  }
}

/**
 * Chunked base64 encoding — avoids stack overflow on large Uint8Arrays.
 * String.fromCharCode(...hugeArray) hits the max call stack size.
 */
function uint8ToBase64(bytes: Uint8Array): string {
  const chunkSize = 8192;
  let binary = "";
  for (let i = 0; i < bytes.length; i += chunkSize) {
    const chunk = bytes.subarray(i, Math.min(i + chunkSize, bytes.length));
    binary += String.fromCharCode(...chunk);
  }
  return btoa(binary);
}

// ============================================================================
// Storage keys
// ============================================================================

const STORAGE_KEY_PREFIX = "resumeai-provider-session-";

function storageKey(provider: ProviderSession["provider"]): string {
  return `${STORAGE_KEY_PREFIX}${provider}`;
}

// ============================================================================
// Session Manager
// ============================================================================

/**
 * Save a provider session to localStorage with encrypted tokens.
 * Refuses to store if encryption fails (no plaintext tokens on disk).
 */
export async function saveSession(session: ProviderSession): Promise<void> {
  const encrypted = { ...session };

  // Encrypt sensitive fields
  const encAccess = await encryptValue(session.accessToken);
  const encRefresh = await encryptValue(session.refreshToken);

  // If encryption failed, store session WITHOUT the access/refresh tokens
  // rather than storing them in plaintext. The session metadata (email,
  // expiry, models) is still useful for the UI, but the tokens are gone.
  if (session.accessToken && encAccess === null) {
    console.error(`[SessionManager] CRITICAL: Access token encryption failed for ${session.provider} — token will NOT be stored`);
    encrypted.accessToken = null;
  } else {
    encrypted.accessToken = encAccess;
  }
  if (session.refreshToken && encRefresh === null) {
    console.error(`[SessionManager] CRITICAL: Refresh token encryption failed for ${session.provider} — token will NOT be stored`);
    encrypted.refreshToken = null;
  } else {
    encrypted.refreshToken = encRefresh;
  }

  try {
    localStorage.setItem(storageKey(session.provider), JSON.stringify(encrypted));
    console.log(`[SessionManager] Session saved for ${session.provider} (authenticated: ${session.authenticated})`);
  } catch (e) {
    console.warn(`[SessionManager] Failed to save session for ${session.provider}:`, e);
  }

  // Also persist to D1 via cloud API (fire-and-forget)
  persistToCloud(encrypted).catch((e) => {
    console.warn("[SessionManager] Cloud persist failed:", e instanceof Error ? e.message : e);
  });
}

/**
 * Load a provider session from localStorage, decrypting tokens.
 * Returns null if no session found or session is definitively expired.
 * Dispatches a 'session:expired' CustomEvent when the token fails to decrypt
 * (e.g. expired sessionStorage token) so the UI can show a re-auth prompt.
 */
export async function loadSession(provider: ProviderSession["provider"]): Promise<ProviderSession | null> {
  try {
    // Try localStorage first
    const raw = localStorage.getItem(storageKey(provider));
    if (raw) {
      const session: ProviderSession = JSON.parse(raw);

      // Explicitly check expiry BEFORE decrypting — if expired, clear and return null
      // rather than returning a stale session that will silently fail on the first API call.
      if (session.authenticated && session.expiresAt && Date.now() >= session.expiresAt) {
        console.warn(`[SessionManager] Session for ${provider} is expired (expiresAt: ${new Date(session.expiresAt).toISOString()}). Clearing.`);
        localStorage.removeItem(storageKey(provider));
        // Notify the UI so it can show a "session expired, please re-authenticate" message.
        if (typeof window !== "undefined") {
          window.dispatchEvent(new CustomEvent("session:expired", { detail: { provider } }));
        }
        return null;
      }

      // Decrypt sensitive fields
      session.accessToken = await decryptValue(session.accessToken);
      session.refreshToken = await decryptValue(session.refreshToken);

      // If token decryption returned null for an authenticated session,
      // the sessionStorage token is unreadable (wrong origin, or encrypted with
      // a different key). Surface this as an explicit auth failure.
      if (session.authenticated && !session.accessToken) {
        console.warn(`[SessionManager] Access token decryption failed for ${provider} — session will require re-authentication.`);
        if (typeof window !== "undefined") {
          window.dispatchEvent(new CustomEvent("session:expired", { detail: { provider, reason: "token_decryption_failed" } }));
        }
      }

      return session;
    }
  } catch (e) {
    console.warn(`[SessionManager] Failed to load session for ${provider}:`, e);
  }

  // Try loading from D1 via cloud API
  try {
    const cloudSession = await loadFromCloud(provider);
    if (cloudSession) {
      cloudSession.accessToken = await decryptValue(cloudSession.accessToken);
      cloudSession.refreshToken = await decryptValue(cloudSession.refreshToken);
      // Save to localStorage for faster access next time
      await saveSession(cloudSession);
      return cloudSession;
    }
  } catch (cloudLoadErr) {
    console.warn("[SessionManager] Cloud session load failed:", cloudLoadErr instanceof Error ? cloudLoadErr.message : cloudLoadErr);
  }

  return null;
}

/**
 * Clear a provider session from localStorage and cloud.
 */
export async function clearSession(provider: ProviderSession["provider"]): Promise<void> {
  try {
    localStorage.removeItem(storageKey(provider));
  } catch (clearErr) {
    console.warn("[SessionManager] localStorage clear failed:", clearErr instanceof Error ? clearErr.message : clearErr);
  }

  // Clear from cloud too
  clearFromCloud(provider).catch((e) => { console.warn("[session-manager] Cloud clear failed:", e instanceof Error ? e.message : e); });

  console.log(`[SessionManager] Session cleared for ${provider}`);
}

/**
 * Check if a session is expired and needs refresh.
 */
export function isSessionExpired(session: ProviderSession): boolean {
  if (!session.expiresAt) return false; // No expiry set — assume valid
  return Date.now() >= session.expiresAt;
}

/**
 * Check if a session will expire within the next 5 minutes.
 * Useful for proactive refresh.
 */
export function isSessionExpiringSoon(session: ProviderSession): boolean {
  if (!session.expiresAt) return false;
  return Date.now() >= session.expiresAt - 5 * 60 * 1000;
}

/**
 * Get all provider sessions (for startup restore).
 */
export async function getAllSessions(): Promise<ProviderSession[]> {
  const sessions: ProviderSession[] = [];
  for (const provider of ["puter"] as const) {
    const session = await loadSession(provider);
    if (session) {
      sessions.push(session);
    } else {
      sessions.push(createEmptySession(provider));
    }
  }
  return sessions;
}

// ============================================================================
// Cloud persistence (D1 via Worker API)
// ============================================================================

const CLOUD_API_BASE =
  (typeof window !== "undefined" && (window as any).__CLOUD_API_BASE) ||
  (typeof process !== "undefined" && process.env?.NEXT_PUBLIC_CLOUD_API_BASE) ||
  (typeof window !== "undefined" &&
  typeof window.location !== "undefined" &&
  typeof window.location.hostname === "string" &&
  window.location.hostname === "localhost"
    ? "http://localhost:8787"
    : "https://resumeai-pro-api.rachidelsabah.workers.dev");

async function persistToCloud(session: ProviderSession): Promise<void> {
  if (typeof window === "undefined") return;
  try {
    await fetch(`${CLOUD_API_BASE}/api/provider-sessions/${session.provider}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(session),
    });
  } catch (persistErr) {
    console.warn("[SessionManager] Cloud persist failed:", persistErr instanceof Error ? persistErr.message : persistErr);
  }
}

async function loadFromCloud(provider: string): Promise<ProviderSession | null> {
  if (typeof window === "undefined") return null;
  try {
    const res = await fetch(`${CLOUD_API_BASE}/api/provider-sessions/${provider}`);
    if (res.ok) {
      // The worker returns an envelope { ok, session, sessions } — unwrap it.
      // Returning the raw envelope as a session made loadSession() see
      // authenticated=undefined (→ treated as logged out) and saveSession()
      // re-persist the envelope itself, corrupting localStorage AND D1.
      const data: any = await res.json().catch(() => null);
      return data?.session ?? null;
    }
  } catch (loadErr) {
    console.warn("[SessionManager] Cloud load failed:", loadErr instanceof Error ? loadErr.message : loadErr);
  }
  return null;
}

async function clearFromCloud(provider: string): Promise<void> {
  if (typeof window === "undefined") return;
  try {
    await fetch(`${CLOUD_API_BASE}/api/provider-sessions/${provider}`, {
      method: "DELETE",
    });
  } catch (deleteErr) {
    console.warn("[SessionManager] Cloud delete failed:", deleteErr instanceof Error ? deleteErr.message : deleteErr);
  }
}

src/lib/puter-client.ts:
// ResumeAI Pro — Puter Client Provider
// Browser-only execution for Puter.js. NEVER runs on Workers, backend APIs,
// server actions, cron jobs, or scheduled tasks.
//
// This module provides:
//   - Session checking (is the user authenticated?)
//   - Model discovery (dynamically load available models)
//   - Test connection (browser-based, not API-based)
//   - Chat execution (browser-only)

"use client";

// Curated Puter model catalog — SINGLE SOURCE OF TRUTH (src/lib/puter-models.ts).
import {
  KNOWN_GOOD_PUTER_MODELS as _KNOWN_GOOD_PUTER_MODELS,
  sanitizePuterChatOpts,
  isPuterTemperatureError,
} from "./puter-models";

declare global {
  interface Window {
    puter?: any;
  }
}

export type PuterAuthStatus = "authenticated" | "not_authenticated" | "session_expired" | "not_loaded";

export interface PuterTestResult {
  success: boolean;
  status: PuterAuthStatus;
  message: string;
  model?: string;
  latencyMs?: number;
  responsePreview?: string;
}

export interface PuterModel {
  id: string;
  label: string;
  provider: string;  // e.g. "OpenAI", "Anthropic", "Google"
}

// Cache for discovered models
let modelCache: PuterModel[] | null = null;
let modelCacheTime = 0;
const MODEL_CACHE_TTL = 5 * 60 * 1000; // 5 minutes

/**
 * Check if Puter.js is loaded in the browser.
 * This is safe to call anytime — does NOT open popups.
 */
export function isPuterLoaded(): boolean {
  return typeof window !== "undefined" && !!window.puter;
}

/**
 * Get the current Puter authentication status.
 * This is safe to call anytime — does NOT open popups.
 */
export function getPuterAuthStatus(): PuterAuthStatus {
  if (!isPuterLoaded()) return "not_loaded";
  try {
    if (window.puter.auth) {
      if (typeof window.puter.auth.isSignedIn === "function") {
        const signedIn = window.puter.auth.isSignedIn();
        return signedIn ? "authenticated" : "not_authenticated";
      }
    }
    return "not_authenticated";
  } catch (err) {
    console.warn("[puterClient] Auth status check failed:", err instanceof Error ? err.message : err);
    return "session_expired";
  }
}

/**
 * Get the signed-in Puter user (or null).
 * Does NOT open a popup.
 */
export async function getPuterUser(): Promise<any | null> {
  if (!isPuterLoaded() || getPuterAuthStatus() !== "authenticated") return null;
  try {
    return await window.puter.auth.getUser();
  } catch (err) {
    console.warn("[puterClient] getUser failed:", err instanceof Error ? err.message : err);
    return null;
  }
}

/**
 * Sign in to Puter — MUST be called from a user click handler.
 * Opens a popup (allowed because it's user-initiated).
 */
export async function signInToPuter(): Promise<{ ok: boolean; user?: any; error?: string }> {
  if (!isPuterLoaded()) {
    return { ok: false, error: "Puter.js is not loaded. Please refresh the page." };
  }
  try {
    await window.puter.auth.signIn();
    const user = await window.puter.auth.getUser().catch(() => null);
    return { ok: true, user };
  } catch (e: any) {
    return { ok: false, error: e?.message || "Puter sign-in was cancelled or failed." };
  }
}

/**
 * Sign out of Puter.
 */
export async function signOutFromPuter(): Promise<{ ok: boolean; error?: string }> {
  if (!isPuterLoaded()) return { ok: false, error: "Puter.js is not loaded." };
  try {
    await window.puter.auth.signOut();
    return { ok: true };
  } catch (e: any) {
    return { ok: false, error: e?.message || "Sign-out failed." };
  }
}

/**
 * Discover available Puter models dynamically.
 * Uses puter.ai.listModels() if available, otherwise returns a curated list
 * of known-good models.
 *
 * Results are cached for 5 minutes to avoid repeated API calls.
 */
export async function discoverPuterModels(): Promise<PuterModel[]> {
  // Check cache
  if (modelCache && Date.now() - modelCacheTime < MODEL_CACHE_TTL) {
    return modelCache;
  }

  const models: PuterModel[] = [];

  // Try to use puter.ai.listModels() if available
  if (isPuterLoaded() && typeof window.puter.ai?.listModels === "function") {
    try {
      const result = await window.puter.ai.listModels();
      if (Array.isArray(result)) {
        for (const m of result) {
          if (typeof m === "string") {
            models.push({ id: m, label: m, provider: inferProvider(m) });
          } else if (m && m.id) {
            models.push({ id: m.id, label: m.label || m.id, provider: m.provider || inferProvider(m.id) });
          }
        }
      }
    } catch (err) {
      console.warn("[puterClient] listModels failed, falling back to curated list:", err instanceof Error ? err.message : err);
      // Fall through to curated list
    }
  }

  // If listModels didn't return anything, use curated list of known-good models
  if (models.length === 0) {
    models.push(...KNOWN_GOOD_PUTER_MODELS);
  }

  // Cache the results
  modelCache = models;
  modelCacheTime = Date.now();

  return models;
}

/**
 * Curated list of models known to work on Puter.js — MOVED to
 * src/lib/puter-models.ts (single source of truth, shared with the AI-layer
 * adapter, the OAuth provider, and ProviderManager). Re-exported here for
 * backward compatibility with existing importers.
 */
export const KNOWN_GOOD_PUTER_MODELS: PuterModel[] = _KNOWN_GOOD_PUTER_MODELS;

function inferProvider(modelId: string): string {
  const lower = modelId.toLowerCase();
  if (lower.includes("gpt") || lower.includes("o1") || lower.includes("o3") || lower.includes("o4")) return "OpenAI";
  if (lower.includes("claude")) return "Anthropic";
  if (lower.includes("gemini")) return "Google";
  if (lower.includes("deepseek")) return "DeepSeek";
  if (lower.includes("mistral") || lower.includes("mixtral")) return "Mistral";
  if (lower.includes("llama")) return "Meta";
  if (lower.includes("grok")) return "xAI";
  if (lower.includes("reka")) return "Reka";
  return "Unknown";
}

// ============================================================================
// Usage Monitoring (per https://docs.puter.com/Auth/getMonthlyUsage/)
// ============================================================================

export interface PuterMonthlyUsage {
  /** The usage data returned by puter.auth.getMonthlyUsage(). */
  [key: string]: any;
}

/**
 * Get the user's current monthly resource usage in the Puter ecosystem.
 * Usage data is scoped to the calling app only.
 *
 * Per https://docs.puter.com/Auth/getMonthlyUsage/:
 *   "Get the user's current monthly resource usage in the Puter ecosystem.
 *    Usage data is scoped to the calling app only."
 *
 * Returns null if Puter.js isn't loaded or the user isn't signed in.
 */
export async function getPuterMonthlyUsage(): Promise<PuterMonthlyUsage | null> {
  if (!isPuterLoaded()) return null;
  try {
    const authStatus = getPuterAuthStatus();
    if (authStatus !== "authenticated") return null;
    if (typeof window.puter.auth.getMonthlyUsage !== "function") return null;
    return await window.puter.auth.getMonthlyUsage();
  } catch (e) {
    console.warn("[Puter] getMonthlyUsage failed:", e);
    return null;
  }
}

/**
 * Check if the user is likely approaching the Puter free-tier usage cap.
 * Returns { near, remaining, message }.
 *
 * This is a heuristic — Puter's free-tier limits aren't publicly documented
 * in exact numbers, but getMonthlyUsage() returns the data we need to
 * estimate. When usage is high, we warn the user so they can either:
 *   1. Wait for the monthly reset
 *   2. Configure a paid API provider in Settings
 */
export async function checkPuterUsageStatus(): Promise<{
  near: boolean;
  remaining: "unknown" | "low" | "medium" | "high";
  message: string;
  raw: PuterMonthlyUsage | null;
}> {
  const usage = await getPuterMonthlyUsage();
  if (!usage) {
    return {
      near: false,
      remaining: "unknown",
      message: "Puter usage data unavailable. Sign in to Puter to see your usage.",
      raw: null,
    };
  }

  // The exact shape of the usage object isn't fully documented, but it
  // typically includes fields like:
  //   { ai_tokens: number, ai_requests: number, storage: number, ... }
  // We check common fields and estimate remaining capacity.
  const aiTokens = usage.ai_tokens ?? usage.aiTokens ?? usage.tokens ?? 0;
  const aiRequests = usage.ai_requests ?? usage.aiRequests ?? usage.requests ?? 0;

  // Heuristic thresholds (adjust based on observed Puter free-tier limits)
  // These are conservative — we warn early so the user isn't surprised.
  const TOKEN_WARNING_THRESHOLD = 100_000;
  const REQUEST_WARNING_THRESHOLD = 500;

  const nearTokenCap = typeof aiTokens === "number" && aiTokens > TOKEN_WARNING_THRESHOLD;
  const nearRequestCap = typeof aiRequests === "number" && aiRequests > REQUEST_WARNING_THRESHOLD;

  if (nearTokenCap || nearRequestCap) {
    return {
      near: true,
      remaining: "low",
      message: `Puter usage is high (${aiRequests} requests, ${aiTokens} tokens this month). Consider configuring a paid API provider in Settings to avoid hitting the free-tier cap.`,
      raw: usage,
    };
  }

  return {
    near: false,
    remaining: "high",
    message: `Puter usage is healthy (${aiRequests} requests, ${aiTokens} tokens this month).`,
    raw: usage,
  };
}

// ============================================================================
// Streaming Support (per https://docs.puter.com/AI/chat/ — stream: true)
// ============================================================================

export interface PuterStreamChunk {
  type: "text" | "compaction" | "error" | "image";
  text?: string;
  message?: string;
  image?: { type: string; image_url: { url: string } };
  id?: string;
  encrypted_content?: string;
}

/**
 * Stream a chat completion from Puter.js.
 *
 * Per https://docs.puter.com/AI/chat/:
 *   const resp = await puter.ai.chat(messages, { model: 'gpt-5.4', stream: true });
 *   for await (const part of resp) {
 *     if (part.type === 'text') text += part.text;
 *     else if (part.type === 'compaction') compaction = part;
 *     else if (part.type === 'error') console.error('stream error:', part.message);
 *   }
 *
 * @param messages Chat messages (system + user)
 * @param options Model, temperature, etc. (stream: true is added automatically)
 * @param onChunk Callback called for each text chunk
 * @returns The full concatenated text
 */
export async function puterChatStreamed(
  messages: Array<{ role: string; content: string }>,
  options: { model?: string; maxTokens?: number; temperature?: number },
  onChunk: (chunk: string) => void,
): Promise<string> {
  if (!isPuterLoaded()) {
    throw new Error("Puter.js is not loaded. This function can only run in the browser.");
  }

  const authStatus = getPuterAuthStatus();
  if (authStatus !== "authenticated") {
    throw new Error(`Puter authentication required. Current status: ${authStatus}. Please sign in to Puter first.`);
  }

  const model = options.model || "gpt-5.4-nano";
  const chatOpts: any = sanitizePuterChatOpts({
    model,
    max_tokens: options.maxTokens ?? 4096,
    temperature: options.temperature ?? 0.7,
    stream: true,
  });

  const runStream = async (opts: any) => {
    const response: any = await window.puter.ai.chat(messages, opts);
    let fullText = "";
    for await (const part of response as AsyncIterable<any>) {
      if (part?.type === "text" && part.text) {
        fullText += part.text;
        onChunk(part.text);
      } else if (part?.type === "error") {
        throw new Error(part.message || "Puter stream error");
      }
      // 'compaction' and 'image' chunks are handled by the caller if needed
    }
    return fullText;
  };

  let fullText = "";
  try {
    fullText = await runStream(chatOpts);
  } catch (streamErr: any) {
    if (isPuterTemperatureError(streamErr) && "temperature" in chatOpts && fullText.length === 0) {
      console.warn(`[puterClient] Model ${model} rejected temperature ${chatOpts.temperature}. Retrying without temperature.`);
      const retryOpts = { ...chatOpts };
      delete retryOpts.temperature;
      fullText = await runStream(retryOpts);
    } else {
      throw streamErr;
    }
  }

  return fullText;
}

/**
 * Validate that a model is available on Puter.
 * Checks against the discovered model list.
 */
export async function validatePuterModel(modelId: string): Promise<{ valid: boolean; available: string[] }> {
  const models = await discoverPuterModels();
  const valid = models.some((m) => m.id === modelId);
  return { valid, available: models.map((m) => m.id) };
}

/**
 * Test the Puter connection — browser-based, NOT an API call.
 *
 * Workflow:
 *   1. Check if Puter.js is loaded
 *   2. Check if the user is authenticated
 *   3. If not authenticated: return "not_authenticated" (NOT "connection failed")
 *   4. If authenticated: run a simple test prompt
 *   5. Return success/failure with the response preview
 *
 * This replaces the old test that tried to call Puter via the Worker API
 * (which always failed because Puter requires browser auth).
 */
export async function testPuterConnection(model?: string): Promise<PuterTestResult> {
  const startTime = Date.now();

  // Step 1: Check if Puter.js is loaded
  if (!isPuterLoaded()) {
    return {
      success: false,
      status: "not_loaded",
      message: "Puter.js is not loaded. Please refresh the page.",
    };
  }

  // Step 2: Check authentication
  const authStatus = getPuterAuthStatus();
  if (authStatus !== "authenticated") {
    return {
      success: false,
      status: authStatus,
      message: authStatus === "not_authenticated"
        ? "Not authenticated. Click 'Sign in to Puter' to authenticate."
        : authStatus === "session_expired"
        ? "Session expired. Please sign in again."
        : "Authentication required.",
    };
  }

  // Step 3: Run a test prompt
  try {
    const testModel = model || "gpt-5.4-nano";
    const testOpts: any = sanitizePuterChatOpts({
      model: testModel,
      max_tokens: 20,
      temperature: 0,
    });
    const callTest = (opts: any) =>
      window.puter.ai.chat("Reply with exactly: PUTER_CONNECTION_OK", opts);

    let response: any;
    try {
      response = await callTest(testOpts);
    } catch (testErr: any) {
      if (isPuterTemperatureError(testErr) && "temperature" in testOpts) {
        const retryOpts = { ...testOpts };
        delete retryOpts.temperature;
        response = await callTest(retryOpts);
      } else {
        throw testErr;
      }
    }

    const latencyMs = Date.now() - startTime;
    const text = extractPuterText(response);

    return {
      success: true,
      status: "authenticated",
      message: "Puter connection successful. User is authenticated and the AI responded.",
      model: testModel,
      latencyMs,
      responsePreview: text.slice(0, 100),
    };
  } catch (e: any) {
    const latencyMs = Date.now() - startTime;
    const errMsg = e?.message || String(e);

    // Check for auth errors
    if (/auth|sign.?in|unauthor|401|403/i.test(errMsg)) {
      return {
        success: false,
        status: "session_expired",
        message: `Session expired or authentication error: ${errMsg}`,
        latencyMs,
      };
    }

    // Check for model errors
    if (/model|not.found|404/i.test(errMsg)) {
      return {
        success: false,
        status: "authenticated",
        message: `Model "${model}" not available on Puter. Try a different model.`,
        latencyMs,
      };
    }

    return {
      success: false,
      status: "authenticated",
      message: `Test prompt failed: ${errMsg}`,
      latencyMs,
    };
  }
}

/**
 * Execute a Puter chat call — browser-only.
 * This MUST NOT be called from server-side code.
 */
export async function puterChat(
  messages: Array<{ role: string; content: string }>,
  options?: { model?: string; maxTokens?: number; temperature?: number },
): Promise<{ text: string; model: string }> {
  if (!isPuterLoaded()) {
    throw new Error("Puter.js is not loaded. This function can only run in the browser.");
  }

  const authStatus = getPuterAuthStatus();
  if (authStatus !== "authenticated") {
    throw new Error(`Puter authentication required. Current status: ${authStatus}. Please sign in to Puter first.`);
  }

  const model = options?.model || "gpt-5.4-nano";
  const chatOpts: any = sanitizePuterChatOpts({
    model,
    max_tokens: options?.maxTokens ?? 4096,
    temperature: options?.temperature ?? 0.7,
  });

  let response: any;
  try {
    response = await window.puter.ai.chat(messages, chatOpts);
  } catch (chatErr: any) {
    if (isPuterTemperatureError(chatErr) && "temperature" in chatOpts) {
      console.warn(`[puterClient] Model ${model} rejected temperature ${chatOpts.temperature}. Retrying without temperature.`);
      const retryOpts = { ...chatOpts };
      delete retryOpts.temperature;
      response = await window.puter.ai.chat(messages, retryOpts);
    } else {
      throw chatErr;
    }
  }

  const text = extractPuterText(response);
  return { text, model };
}

/**
 * Extract text from a Puter response (handles different shapes).
 */
function extractPuterText(resp: any): string {
  if (typeof resp === "string") return resp;
  if (resp?.message?.content) {
    return Array.isArray(resp.message.content)
      ? resp.message.content.map((c: any) => c?.text ?? "").join("")
      : String(resp.message.content);
  }
  if (resp?.text) return resp.text;
  if (resp?.message?.role === "assistant" && typeof resp.message.content === "string") {
    return resp.message.content;
  }
  try { return JSON.stringify(resp); } catch (err) { console.warn("[puterClient] extractPuterText JSON.stringify failed:", err instanceof Error ? err.message : err); return String(resp ?? ""); }
}

/**
 * CRITICAL: Verify we're in a browser context.
 * Puter MUST NEVER execute on Workers, backend APIs, server actions,
 * cron jobs, or scheduled tasks.
 */
export function assertBrowserOnly(): void {
  if (typeof window === "undefined") {
    throw new Error("FATAL: Puter.js can only execute in the browser. This function was called from a server context. " +
      "Puter MUST NOT run on Cloudflare Workers, backend APIs, server actions, cron jobs, or scheduled tasks. " +
      "Use an API provider instead for server-side execution.");
  }
}

