    set((s) => ({ coverLetters: s.coverLetters.filter((c) => c.id !== id) }));
    cloudApiSafe(deleteCoverLetter)(id).catch((e) => { console.warn("[store] Cloud sync failed:", e); });
    if (typeof localStorage !== "undefined") {
      try {
