        localStorage.setItem(userScopedKey("resumeai-interview-sessions-backup"), JSON.stringify([s, ...existing.filter((x: any) => x.id !== s.id)].slice(0, 50)));
      } catch (syncErr) { console.warn("[store] Operation failed:", syncErr); }
