// ============================================================================
// Supervisor Memory — Shared Structured Memory
//
// Replaces repeated prompt context with a single shared memory object.
// Each agent reads only the sections it needs and appends its own output.
//
// Benefits:
//   - Reduces token usage (don't resend full resume + JD to every agent)
//   - Reduces latency (agents share state without re-prompting)
//   - Reduces inconsistency (all agents see the same data)
//   - Enables targeted regeneration (only failed sections are re-run)
// ============================================================================

"use client";

import type { SupervisorMemory, AgentExecutionRecord, AgentType } from "./pipeline-orchestration-types";

/**
 * Create a new Supervisor Memory instance for a pipeline execution.
 */
export function createSupervisorMemory(executionId?: string): SupervisorMemory {
  return {
    executionId: executionId || `exec_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
    startedAt: new Date().toISOString(),
    agentExecutions: [],
    scratchpad: {},
  };
}

/**
 * Read a section from shared memory.
 * Agents should call this to get only the data they need.
 */
export function readMemory<T = any>(
  memory: SupervisorMemory,
  section: keyof SupervisorMemory | string,
): T | undefined {
  // Check scratchpad first (for custom keys)
  if (typeof section === "string" && !(section in memory)) {
    return memory.scratchpad[section] as T;
  }
  return memory[section as keyof SupervisorMemory] as T;
}

/**
 * Write a section to shared memory.
 * Agents append their output here for other agents to read.
 */
export function writeMemory(
  memory: SupervisorMemory,
  section: keyof SupervisorMemory | string,
  value: any,
): void {
  // Custom keys go to scratchpad
  if (typeof section === "string" && !(section in memory)) {
    memory.scratchpad[section] = value;
  } else {
    (memory as any)[section] = value;
  }
}

/**
 * Record an agent execution in the memory's execution log.
 */
export function recordAgentExecution(
  memory: SupervisorMemory,
  record: AgentExecutionRecord,
): void {
  // Replace existing record for the same agent, or append
  const existingIndex = memory.agentExecutions.findIndex(
    (e) => e.agentId === record.agentId && e.status === "running",
  );
  if (existingIndex >= 0) {
    memory.agentExecutions[existingIndex] = record;
  } else {
    memory.agentExecutions.push(record);
  }
}

/**
 * Update an agent's execution status.
 */
export function updateAgentExecution(
  memory: SupervisorMemory,
  agentId: string,
  status: AgentExecutionRecord["status"],
  updates?: Partial<AgentExecutionRecord>,
): void {
  const record = memory.agentExecutions.find((e) => e.agentId === agentId);
  if (record) {
    record.status = status;
    if (status === "completed" || status === "failed") {
      record.completedAt = new Date().toISOString();
    }
    Object.assign(record, updates);
  }
}

/**
 * Get all executions for a specific agent type.
 */
export function getExecutionsByType(
  memory: SupervisorMemory,
  agentType: AgentType,
): AgentExecutionRecord[] {
  return memory.agentExecutions.filter((e) => e.agentType === agentType);
}

/**
 * Get the latest execution for an agent.
 */
export function getLatestExecution(
  memory: SupervisorMemory,
  agentId: string,
): AgentExecutionRecord | undefined {
  const executions = memory.agentExecutions.filter((e) => e.agentId === agentId);
  return executions[executions.length - 1];
}

/**
 * Mark the pipeline as completed.
 */
export function completeMemory(memory: SupervisorMemory): void {
  memory.completedAt = new Date().toISOString();
}

/**
 * Get a summary of the memory for logging/debugging.
 */
export function getMemorySummary(memory: SupervisorMemory): Record<string, any> {
  return {
    executionId: memory.executionId,
    startedAt: memory.startedAt,
    completedAt: memory.completedAt,
    hasResume: !!memory.resumeJson,
    hasJobDescription: !!memory.jobDescriptionJson,
    hasCompanyIntelligence: !!memory.companyIntelligence,
    hasJobIntelligence: !!memory.jobIntelligence,
    hasSkillGap: !!memory.skillGapAnalysis,
    hasAtsKeywords: !!memory.atsKeywords?.length,
    hasOptimizerOutput: !!memory.optimizerOutput,
    hasAssembledResume: !!memory.assembledResume,
    hasQaResults: !!memory.qaResults,
    hasReflectionNotes: !!memory.reflectionNotes,
    hasFactualConsistency: !!memory.factualConsistency,
    hasStructureGuardian: !!memory.structureGuardianResult,
    layoutMetadata: memory.layoutMetadata,
    exportMetadata: memory.exportMetadata,
    agentExecutionCount: memory.agentExecutions.length,
    scratchpadKeys: Object.keys(memory.scratchpad),
  };
}

/**
 * Build a compact context object for an agent prompt.
 * Instead of sending the full resume + JD, send only what the agent needs.
 */
export function buildAgentContext(
  memory: SupervisorMemory,
  requiredSections: string[],
): Record<string, any> {
  const context: Record<string, any> = {};
  for (const section of requiredSections) {
    const value = readMemory(memory, section);
    if (value !== undefined) {
      context[section] = value;
    }
  }
  return context;
}

src/lib/task-manager.ts:
// ============================================================================
// Task Manager — D1-backed async task tracking (replaces Durable Objects).
//
// This module provides CRUD operations for tracking async AI/build/test/patch/
// debug jobs in D1. The frontend polls /api/tasks/:id/status every 2 seconds
// to get updates.
//
// Architecture:
//   Browser → POST /api/tasks/create → D1 INSERT (status='queued')
//   Worker runs the task → UPDATE progress/message in D1
//   Browser polls GET /api/tasks/:id/status every 2s → reads from D1
//   Polling stops when status ∈ {completed, failed, cancelled}
//
// No Durable Objects, no WebSockets, no Workers Paid Plan required.
// Works entirely on Cloudflare Free plan (Pages + Workers + D1).
// ============================================================================

// Use a generic DB type so this module can be imported from both the worker
// (where D1Database is available) and the client (where it's not).
// The worker passes the real D1Database; the client never calls these functions
// directly (it uses the HTTP API via useTaskPolling).
export interface D1Like {
  prepare(sql: string): {
    bind(...values: any[]): {
      first<T = any>(): Promise<T | null>;
      all<T = any>(): Promise<{ results: T[] }>;
      run(): Promise<any>;
    };
  };
}

export type TaskType =
  | "optimization"
  | "cover_letter"
  | "interview"
  | "jd_scrape"
  | "ats_check"
  | "ai_builder"
  | "patch_generation"
  | "build"
  | "test"
  | "autonomous_debug"
  | "repository_audit"
  | "git_operation"
  | "generic";

export type TaskStatus = "queued" | "running" | "completed" | "failed" | "cancelled";

export interface TaskRecord {
  id: string;
  type: TaskType | string;
  status: TaskStatus;
  progress: number;      // 0-100
  message: string | null;
  result_json: string | null;  // JSON string
  error: string | null;
  created_at: number;    // epoch ms
  updated_at: number;    // epoch ms
}

export interface CreateTaskInput {
  id?: string;
  type: TaskType | string;
  message?: string;
}

export interface UpdateTaskInput {
  status?: TaskStatus;
  progress?: number;
  message?: string;
  result?: any;          // will be JSON.stringify'd
  error?: string;
}

// ============================================================================
// D1 queries — these run in the Cloudflare Worker
// ============================================================================

/**
 * Create a new task in D1. Returns the task record.
 */
export async function createTask(db: D1Like, input: CreateTaskInput): Promise<TaskRecord> {
  const id = input.id || `task_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
  const now = Date.now();
  const status: TaskStatus = "queued";
  const progress = 0;
  const message = input.message || "Initializing";

  await db.prepare(
    `INSERT INTO ai_tasks (id, type, status, progress, message, result_json, error, created_at, updated_at)
     VALUES (?, ?, ?, ?, ?, NULL, NULL, ?, ?)`,
  ).bind(id, input.type, status, progress, message, now, now).run();

  return {
    id,
    type: input.type,
    status,
    progress,
    message,
    result_json: null,
    error: null,
    created_at: now,
    updated_at: now,
  };
}

/**
 * Get a task by ID from D1.
 */
export async function getTask(db: D1Like, id: string): Promise<TaskRecord | null> {
  const row = await db.prepare(
    `SELECT id, type, status, progress, message, result_json, error, created_at, updated_at
     FROM ai_tasks WHERE id = ?`,
  ).bind(id).first<any>();

  if (!row) return null;
  return {
    id: row.id,
    type: row.type,
    status: row.status as TaskStatus,
    progress: row.progress,
    message: row.message,
    result_json: row.result_json,
    error: row.error,
    created_at: row.created_at,
    updated_at: row.updated_at,
  };
}

/**
 * Get only the status fields (lighter query for polling).
 */
export async function getTaskStatus(db: D1Like, id: string): Promise<{
  id: string;
  status: TaskStatus;
  progress: number;
  message: string | null;
  error: string | null;
  updated_at: number;
} | null> {
  const row = await db.prepare(
    `SELECT id, status, progress, message, error, updated_at FROM ai_tasks WHERE id = ?`,
  ).bind(id).first<any>();

  if (!row) return null;
  return {
    id: row.id,
    status: row.status as TaskStatus,
    progress: row.progress,
    message: row.message,
    error: row.error,
    updated_at: row.updated_at,
  };
}

/**
 * Update a task in D1. Only updates the provided fields.
 */
export async function updateTask(db: D1Like, id: string, input: UpdateTaskInput): Promise<void> {
  const updates: string[] = ["updated_at = ?"];
  const values: any[] = [Date.now()];

  if (input.status !== undefined) {
    updates.push("status = ?");
    values.push(input.status);
  }
  if (input.progress !== undefined) {
    updates.push("progress = ?");
    values.push(Math.max(0, Math.min(100, input.progress)));
  }
  if (input.message !== undefined) {
    updates.push("message = ?");
    values.push(input.message);
  }
  if (input.result !== undefined) {
    updates.push("result_json = ?");
    values.push(JSON.stringify(input.result));
  }
  if (input.error !== undefined) {
    updates.push("error = ?");
    values.push(input.error);
  }

  values.push(id);
  await db.prepare(
    `UPDATE ai_tasks SET ${updates.join(", ")} WHERE id = ?`,
  ).bind(...values).run();
}

/**
 * Cancel a task (sets status to 'cancelled' if it's still queued or running).
 */
export async function cancelTask(db: D1Like, id: string): Promise<boolean> {
  const now = Date.now();
  const result = await db.prepare(
    `UPDATE ai_tasks SET status = 'cancelled', message = 'Cancelled by user', updated_at = ?
     WHERE id = ? AND status IN ('queued', 'running')`,
  ).bind(now, id).run();

  // D1 returns meta.changes = number of rows updated
  const changes = (result as any)?.meta?.changes ?? 0;
  return changes > 0;
}

/**
 * Purge completed/failed/cancelled tasks older than 30 days.
 * Called by a scheduled cleanup (or manually).
 */
export async function purgeOldTasks(db: D1Like, maxAgeDays = 30): Promise<number> {
  const cutoff = Date.now() - maxAgeDays * 24 * 60 * 60 * 1000;
  const result = await db.prepare(
    `DELETE FROM ai_tasks
     WHERE status IN ('completed', 'failed', 'cancelled')
       AND created_at < ?`,
  ).bind(cutoff).run();

  const changes = (result as any)?.meta?.changes ?? 0;
  return changes;
}

/**
 * List recent tasks (for the admin dashboard).
 */
export async function listRecentTasks(
  db: D1Like,
  limit = 50,
  statusFilter?: TaskStatus,
): Promise<TaskRecord[]> {
  const sql = statusFilter
    ? `SELECT id, type, status, progress, message, result_json, error, created_at, updated_at
       FROM ai_tasks WHERE status = ? ORDER BY created_at DESC LIMIT ?`
    : `SELECT id, type, status, progress, message, result_json, error, created_at, updated_at
       FROM ai_tasks ORDER BY created_at DESC LIMIT ?`;

  const stmt = statusFilter
    ? db.prepare(sql).bind(statusFilter, limit)
    : db.prepare(sql).bind(limit);

  const { results } = await stmt.all<any>();
  return (results || []).map((row) => ({
    id: row.id,
    type: row.type,
    status: row.status as TaskStatus,
    progress: row.progress,
    message: row.message,
    result_json: row.result_json,
    error: row.error,
    created_at: row.created_at,
    updated_at: row.updated_at,
  }));
}

// ============================================================================
// Progress milestones (spec: 0, 10, 25, 50, 75, 100)
// ============================================================================

export const PROGRESS_MILESTONES = {
  INITIALIZING: { progress: 0, message: "Initializing" },
  READING_REPOSITORY: { progress: 10, message: "Reading Repository" },
  ANALYZING: { progress: 25, message: "Analyzing" },
  GENERATING_PATCH: { progress: 50, message: "Generating Patch" },
  RUNNING_TESTS: { progress: 75, message: "Running Tests" },
  BUILDING: { progress: 75, message: "Building Application" },
  COMPLETED: { progress: 100, message: "Completed" },
} as const;

/**
 * Helper: set a progress milestone on a task.
 */
export async function setProgress(
  db: D1Like,
  taskId: string,
  milestone: keyof typeof PROGRESS_MILESTONES,
  status: TaskStatus = "running",
): Promise<void> {
  const m = PROGRESS_MILESTONES[milestone];
  await updateTask(db, taskId, {
    status,
    progress: m.progress,
    message: m.message,
  });
}

// ============================================================================
// Terminal status check (for polling auto-stop)
// ============================================================================

export function isTerminalStatus(status: TaskStatus): boolean {
  return status === "completed" || status === "failed" || status === "cancelled";
}

src/lib/telemetry.ts:
// ============================================================================
// Telemetry Service — tracks agent execution, provider failures, pipeline
// health, repair history, and performance metrics.
//
// All data is stored in-memory (no D1 writes for telemetry — too high-frequency).
// The UI can read from getTelemetrySnapshot() for dashboards.
// ============================================================================

"use client";

export interface AgentExecutionRecord {
  agentName: string;
  timestamp: string;
  durationMs: number;
  success: boolean;
  retries: number;
  confidence: number;
  provider: string | null;
}

export interface ProviderFailureRecord {
  providerName: string;
  timestamp: string;
  errorType: "timeout" | "auth" | "rate_limit" | "network" | "unknown";
  errorMessage: string;
}

export interface PipelineFailureRecord {
  timestamp: string;
  stage: string;
  error: string;
  recovered: boolean;
}

export interface RepairHistoryRecord {
  timestamp: string;
  issue: string;
  rootCause: string;
  repairAction: string;
  durationMs: number;
  success: boolean;
  rollbackRequired: boolean;
}

export interface PerformanceMetrics {
  avgOptimizerDurationMs: number;
  avgQAConfidence: number;
  avgAtsScore: number;
  totalOptimizations: number;
  totalFailures: number;
  totalRepairs: number;
  repairSuccessRate: number;
}

export interface TelemetrySnapshot {
  timestamp: string;
  agentExecutions: AgentExecutionRecord[];
  providerFailures: ProviderFailureRecord[];
  pipelineFailures: PipelineFailureRecord[];
  repairHistory: RepairHistoryRecord[];
  performance: PerformanceMetrics;
}

// In-memory stores (capped to prevent memory leaks)
const MAX_RECORDS = 200;
const agentExecutions: AgentExecutionRecord[] = [];
const providerFailures: ProviderFailureRecord[] = [];
const pipelineFailures: PipelineFailureRecord[] = [];
const repairHistory: RepairHistoryRecord[] = [];

// Running totals for performance metrics
let totalOptimizerDuration = 0;
let totalOptimizerCount = 0;
let totalQAConfidence = 0;
let totalQACount = 0;
let totalAtsScore = 0;
let totalAtsCount = 0;
let totalOptimizations = 0;
let totalFailures = 0;
let totalRepairs = 0;
let successfulRepairs = 0;

/**
 * Record an agent execution.
 */
export function recordAgentExecution(record: Omit<AgentExecutionRecord, "timestamp">): void {
  const entry: AgentExecutionRecord = { ...record, timestamp: new Date().toISOString() };
  agentExecutions.push(entry);
  if (agentExecutions.length > MAX_RECORDS) agentExecutions.shift();

  // Track optimizer-specific metrics
  if (record.agentName === "optimizer") {
    totalOptimizerDuration += record.durationMs;
    totalOptimizerCount++;
  }
  if (record.agentName === "qa") {
    totalQAConfidence += record.confidence;
    totalQACount++;
  }
}

/**
 * Record a provider failure.
 */
export function recordProviderFailure(record: Omit<ProviderFailureRecord, "timestamp">): void {
  const entry: ProviderFailureRecord = { ...record, timestamp: new Date().toISOString() };
  providerFailures.push(entry);
  if (providerFailures.length > MAX_RECORDS) providerFailures.shift();
}

/**
 * Record a pipeline failure.
 */
export function recordPipelineFailure(record: Omit<PipelineFailureRecord, "timestamp">): void {
  const entry: PipelineFailureRecord = { ...record, timestamp: new Date().toISOString() };
  pipelineFailures.push(entry);
  if (pipelineFailures.length > MAX_RECORDS) pipelineFailures.shift();
  totalFailures++;
}

/**
 * Record a repair action.
 */
export function recordRepair(record: Omit<RepairHistoryRecord, "timestamp">): void {
  const entry: RepairHistoryRecord = { ...record, timestamp: new Date().toISOString() };
  repairHistory.push(entry);
  if (repairHistory.length > MAX_RECORDS) repairHistory.shift();
  totalRepairs++;
  if (record.success) successfulRepairs++;
}

/**
 * Record a successful optimization (for success rate calculation).
 */
export function recordOptimization(atsScore: number): void {
  totalOptimizations++;
  totalAtsScore += atsScore;
  totalAtsCount++;
}

/**
 * Get the current telemetry snapshot for dashboards.
 */
export function getTelemetrySnapshot(): TelemetrySnapshot {
  return {
    timestamp: new Date().toISOString(),
    agentExecutions: [...agentExecutions],
    providerFailures: [...providerFailures],
    pipelineFailures: [...pipelineFailures],
    repairHistory: [...repairHistory],
    performance: {
      avgOptimizerDurationMs: totalOptimizerCount > 0 ? Math.round(totalOptimizerDuration / totalOptimizerCount) : 0,
      avgQAConfidence: totalQACount > 0 ? Math.round(totalQAConfidence / totalQACount) : 0,
      avgAtsScore: totalAtsCount > 0 ? Math.round(totalAtsScore / totalAtsCount) : 0,
      totalOptimizations,
      totalFailures,
      totalRepairs,
      repairSuccessRate: totalRepairs > 0 ? Math.round((successfulRepairs / totalRepairs) * 100) : 0,
    },
  };
}

/**
 * Clear all telemetry data — useful for testing.
 */
export function clearTelemetry(): void {
  agentExecutions.length = 0;
  providerFailures.length = 0;
  pipelineFailures.length = 0;
  repairHistory.length = 0;
  totalOptimizerDuration = 0;
  totalOptimizerCount = 0;
  totalQAConfidence = 0;
  totalQACount = 0;
  totalAtsScore = 0;
  totalAtsCount = 0;
  totalOptimizations = 0;
  totalFailures = 0;
  totalRepairs = 0;
  successfulRepairs = 0;
}

