// ============================================================================
// ThemeEngine — resolves theme values from template + layout model
// ============================================================================
// Every renderer uses the resolved theme for fonts, colors, and spacing.
// No renderer may hardcode typography values.

import type { ResumeTheme, ResumeTemplate, ResumeLayoutModel } from "./types-phase3";
/** Bullet character per icon style */
function getBulletChar(iconStyle: ResumeTheme["iconStyle"]): string {
  switch (iconStyle) {
    case "bullet": return "•";
    case "checkmark": return "✓";
    case "arrow": return "→";
    default: return "•";
  }
}

/** Spacing values (in mm) per icon style */
function getBulletIndentMm(iconStyle: ResumeTheme["iconStyle"]): number {
  return 6.4; // consistent across all styles
}

const FALLBACK_COLORS = {
  nameColor: "#1a1a1a",
  headlineColor: "#333333",
  sectionTitleColor: "#2c3e50",
  bodyTextColor: "#000000",
  contactColor: "#333333",
  accentColor: "#2c5282",
  backgroundColor: "#ffffff",
  borderColor: "#cccccc",
};

const FALLBACK_SPACING = {
  sectionGapMm: 3.0,
  headerGapMm: 1.0,
  bulletIndentMm: 6.4,
  paragraphSpacingMm: 1.5,
  marginTopMm: 6.35,
  marginBottomMm: 6.35,
  marginLeftMm: 8.89,
  marginRightMm: 8.89,
};

/**
 * Build a fully resolved ResumeTheme from a template name + optional layout model.
 */
export function buildTheme(
  template: ResumeTemplate,
  accentColor?: string,
  layout?: Partial<ResumeLayoutModel>,
): ResumeTheme {
  // Merge layout override into defaults
  const L: ResumeLayoutModel = {
    pageSize: "A4",
    marginTopMm: FALLBACK_SPACING.marginTopMm,
    marginBottomMm: FALLBACK_SPACING.marginBottomMm,
    marginLeftMm: FALLBACK_SPACING.marginLeftMm,
    marginRightMm: FALLBACK_SPACING.marginRightMm,
    fontFamily: "Calibri",
    fallbackFontFamily: "Liberation Sans",
    nameSizePt: 16,
    sectionTitleSizePt: 11,
    bodyFontSizePt: 10,
    nameColor: FALLBACK_COLORS.nameColor,
    sectionTitleColor: FALLBACK_COLORS.sectionTitleColor,
    bodyTextColor: FALLBACK_COLORS.bodyTextColor,
    contactColor: FALLBACK_COLORS.contactColor,
    lineHeightMm: 4.2,
    sectionGapMm: FALLBACK_SPACING.sectionGapMm,
    headerGapMm: FALLBACK_SPACING.headerGapMm,
    bulletIndentMm: FALLBACK_SPACING.bulletIndentMm,
    paragraphSpacingMm: FALLBACK_SPACING.paragraphSpacingMm,
    photoWidthMm: 30,
    photoHeightMm: 40,
    enforceOnePage: true,
    minFontSizePt: 8,
    ...layout,
  };

  const iconStyle: ResumeTheme["iconStyle"] = (() => {
    switch (template) {
      case "modern":
      case "startup": return "checkmark";
      case "creative": return "arrow";
      default: return "bullet";
    }
  })();

  const showDividers: ResumeTheme["showDividers"] = (() => {
    switch (template) {
      case "executive":
      case "corporate":
      case "academic":
      case "consulting": return true;
      default: return false;
    }
  })();

  const borderStyle: ResumeTheme["borderStyle"] = (() => {
    switch (template) {
      case "executive": return "double";
      case "classic": return "solid";
      default: return "none";
    }
  })();

  return {
    name: template,
    fontFamily: L.fontFamily,
    fallbackFontFamily: L.fallbackFontFamily,
    nameSizePt: L.nameSizePt,
    headlineSizePt: L.nameSizePt - 2,
    sectionTitleSizePt: L.sectionTitleSizePt,
    bodyFontSizePt: L.bodyFontSizePt,
    minFontSizePt: L.minFontSizePt,
    lineHeight: 1.15,
    lineHeightMm: L.lineHeightMm,
    nameColor: L.nameColor,
    headlineColor: L.contactColor,
    sectionTitleColor: L.sectionTitleColor,
    bodyTextColor: L.bodyTextColor,
    contactColor: L.contactColor,
    accentColor: accentColor || L.sectionTitleColor,
    backgroundColor: "#ffffff",
    borderColor: "#cccccc",
    sectionGapMm: L.sectionGapMm,
    headerGapMm: L.headerGapMm,
    bulletIndentMm: getBulletIndentMm(iconStyle),
    paragraphSpacingMm: L.paragraphSpacingMm,
    marginTopMm: L.marginTopMm,
    marginBottomMm: L.marginBottomMm,
    marginLeftMm: L.marginLeftMm,
    marginRightMm: L.marginRightMm,
    pageSize: L.pageSize,
    columns: 1,
    columnGapMm: 0,
    enforceOnePage: L.enforceOnePage,
    showDividers,
    borderStyle,
    iconStyle,
  };
}

/**
 * Create a theme from a ResumeLayoutModel directly.
 */
export function themeFromLayout(layout: ResumeLayoutModel, template?: string): ResumeTheme {
  return buildTheme(
    (template as ResumeTemplate) || "ats-professional",
    undefined,
    layout,
  );
}

src/lib/token-rotation.ts:
// ============================================================================
// Token Rotation Manager — Feature 5: Automated Guest Session & Token Rotation
//
// When a provider returns 401 Unauthorized or a CreditsError, silently:
//   1. Request a new anonymous session token from the provider (if it supports it)
//   2. Retry the original request once with the new token
//   3. Update the provider's token in the store for future calls
//
// Currently handles:
//   - Puter.js: calls puter.auth.signIn() or uses anonymous guest mode
//   - OpenCode / ZenCode: attempts to refresh the free anonymous session
//   - Custom providers with refreshUrl: calls the refresh endpoint
//
// If rotation fails, the error propagates normally (caller applies cooldown).
// ============================================================================

"use client";

import { useApp } from "./store";

// ============================================================================
// Registry of supported rotation strategies
// ============================================================================

interface RotationResult {
  success: boolean;
  newToken?: string;
  message?: string;
}

/**
 * Attempt to silently rotate the session/token for a provider.
 * Returns true if rotation succeeded and the provider store was updated.
 * Returns false if this provider type doesn't support rotation or rotation failed.
 */
export async function tryRotateProviderToken(provider: any): Promise<RotationResult> {
  if (!provider) return { success: false, message: "No provider" };

  const pType = (provider.type || "").toLowerCase();

  // ---- Puter.js: Request a new anonymous guest session ----
  if (pType === "puter") {
    return rotatePuterSession(provider);
  }

  // ---- Providers with a declared refreshUrl ----
  if (provider.refreshUrl) {
    return rotateViaRefreshUrl(provider);
  }

  // ---- OpenCode / ZenCode: Re-register as anonymous user ----
  if (pType === "opencode" || pType === "zencode") {
    return rotateOpenCodeSession(provider);
  }

  return { success: false, message: `Provider type "${pType}" does not support token rotation` };
}

// ============================================================================
// Puter.js session rotation
// ============================================================================

async function rotatePuterSession(_provider: any): Promise<RotationResult> {
  if (typeof window === "undefined" || !window.puter) {
    return { success: false, message: "Puter SDK not available" };
  }
  try {
    // Attempt silent anonymous sign-in (no popup if guest mode available)
    const puterAny = window.puter as any;
    if (typeof puterAny.auth?.signIn === "function") {
      // Try signing in without triggering a popup by passing { no_ui: true }
      await puterAny.auth.signIn({ no_ui: true }).catch(() => null);
    }
    // After sign-in attempt, get the new auth token if available
    if (typeof puterAny.auth?.getToken === "function") {
      const newToken = await puterAny.auth.getToken().catch(() => null);
      if (newToken) {
        console.info("[TokenRotation] Puter: new session token acquired");
        return { success: true, newToken, message: "Puter session refreshed" };
      }
    }
    // If token acquisition failed but sign-in didn't throw, optimistically return success
    return { success: true, message: "Puter silent sign-in attempted" };
  } catch (err: any) {
    return {
      success: false,
      message: `Puter session rotation failed: ${err?.message || err}`,
    };
  }
}

// ============================================================================
// Generic refreshUrl-based rotation
// ============================================================================

async function rotateViaRefreshUrl(provider: any): Promise<RotationResult> {
  try {
    const res = await fetch(provider.refreshUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email: provider.email || "", password: provider.password || "" }),
      signal: AbortSignal.timeout(10000), // 10s max for token refresh
    });

    if (!res.ok) {
      return { success: false, message: `Refresh endpoint returned ${res.status}` };
    }

    const data = (await res.json()) as any;
    const newToken = data?.token || data?.access_token || data?.apiKey || data?.key;

    if (!newToken) {
      return { success: false, message: "Refresh response contained no token field" };
    }

    // Persist the new token to the provider store
    updateProviderToken(provider.id, newToken);
    console.info(`[TokenRotation] ${provider.name}: token rotated via refreshUrl`);

    return { success: true, newToken, message: "Token rotated via refreshUrl" };
  } catch (err: any) {
    return {
      success: false,
      message: `refreshUrl rotation failed: ${err?.message || err}`,
    };
  }
}

// ============================================================================
// OpenCode / ZenCode anonymous session re-registration
// ============================================================================

async function rotateOpenCodeSession(provider: any): Promise<RotationResult> {
  try {
    // OpenCode/ZenCode allow guest registration via /api/register/guest endpoint
    const baseUrl = (provider.apiUrl || provider.baseUrl || "").trim();
    if (!baseUrl) return { success: false, message: "No base URL for OpenCode session rotation" };

    // Try standard guest endpoint patterns
    const guestEndpoints = [
      `${baseUrl.replace(/\/v\d+.*$/, "")}/auth/guest`,
      `${baseUrl.replace(/\/v\d+.*$/, "")}/register/guest`,
      `${baseUrl.replace(/\/v\d+.*$/, "")}/api/guest`,
    ];

    for (const endpoint of guestEndpoints) {
      try {
        const res = await fetch(endpoint, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          signal: AbortSignal.timeout(8000),
        });

        if (!res.ok) continue;

        const data = (await res.json()) as any;
        const newToken = data?.token || data?.api_key || data?.apiKey || data?.key || data?.access_token;

        if (newToken) {
          updateProviderToken(provider.id, newToken);
          console.info(`[TokenRotation] ${provider.name}: new guest token acquired from ${endpoint}`);
          return { success: true, newToken, message: "OpenCode/ZenCode guest token rotated" };
        }
      } catch {
        // Try next endpoint
      }
    }

    return { success: false, message: "OpenCode/ZenCode guest registration endpoints not available" };
  } catch (err: any) {
    return {
      success: false,
      message: `OpenCode session rotation failed: ${err?.message || err}`,
    };
  }
}

// ============================================================================
// Store update helper
// ============================================================================

function updateProviderToken(providerId: string, newToken: string): void {
  if (!providerId || !newToken) return;
  try {
    const store = useApp.getState() as any;
    if (typeof store?.setProviders !== "function" && typeof store?.updateProvider !== "function") return;

    const providers: any[] = store?.providers || [];
    const updated = providers.map((p: any) => {
      if (p.id === providerId) {
        return { ...p, apiKey: newToken };
      }
      return p;
    });

    if (typeof store.updateProvider === "function") {
      store.updateProvider(providerId, { apiKey: newToken });
    } else if (typeof store.setProviders === "function") {
      store.setProviders(updated);
    }
  } catch (err) {
    console.warn("[TokenRotation] Failed to persist new token to store:", err);
  }
}

// ============================================================================
// Error detection helpers
// ============================================================================

/**
 * Returns true when the error is a billing/entitlement failure (no payment
 * method, insufficient credits, paid-model-on-free-workspace). Rotation can
 * never fix billing — a fresh token on the same workspace hits the same
 * billing wall — so these must bypass silent token rotation entirely and
 * surface as an actionable billing diagnosis instead.
 */
export function isBillingError(err: any): boolean {
  if (!err) return false;
  const msg = (err?.message || String(err || "")).toLowerCase();
  return (
    /creditserror/i.test(msg) ||
    /no.?credits/i.test(msg) ||
    /no.?payment.?method/i.test(msg) ||
    /add.?a.?payment/i.test(msg) ||
    /billing/i.test(msg) ||
    /insufficient.?credits/i.test(msg) ||
    /credit.?balance/i.test(msg) ||
    /payment.?required/i.test(msg) ||
    /free.?tier.?exceeded/i.test(msg) ||
    /quota.?exceeded/i.test(msg)
  );
}

/**
 * Returns true if the error indicates a credential/session expiry that
 * token rotation might fix (401 session expiry, invalid/expired token…).
 * Billing failures are explicitly EXCLUDED: rotating tokens against a
 * billing wall only burns time and spams CORS-doomed guest endpoints.
 */
export function isRotatableAuthError(err: any): boolean {
  if (!err) return false;
  if (isBillingError(err)) return false;
  // Entitlement opt-in (e.g. opencode.ai DataPolicyError): requires a manual
  // opt-in click in the provider dashboard — no token swap fixes that.
  const msg0 = (err?.message || String(err || "")).toLowerCase();
  if (/datapolicyerror|requires.?explicit.?opt.?in|opt.?in.?required|explicit.?consent.?required/i.test(msg0)) return false;
  const code = err?.statusCode || err?.status || 0;
  if (code === 401 || code === 403) return true;
  const msg = (err?.message || String(err || "")).toLowerCase();
  return (
    /unauthorized/i.test(msg) ||
    /session.?expired/i.test(msg) ||
    /token.?expired/i.test(msg) ||
    /invalid.?token/i.test(msg) ||
    /authentication.?required/i.test(msg) ||
    (/401/.test(msg) && !/429/.test(msg)) // 401 in message but not 429
  );
}

src/lib/tracing/lightweight-tracer.ts:
// ============================================================================
// Workers-Compatible Distributed Tracing — Section 13
// ============================================================================
// Full OpenTelemetry SDK has limited support in Workers runtime.
// This module uses Workers-native Trace Events / Logpush + a lightweight
// span-based tracer that's compatible with the CF Workers environment.
//
// Architecture:
//   - Tracer: creates spans with parent-child relationships
//   - Span: a single operation with timing + tags
//   - Exporter: sends spans via Logpush / Cloudflare Tail Workers
//   - OTel-compatible format: spans can be translated to OTLP for external APM
// ============================================================================

// ============================================================================
// Types
// ============================================================================

export type SpanStatus = 'ok' | 'error' | 'canceled';

export interface Span {
  traceId: string;
  spanId: string;
  parentSpanId: string | null;
  name: string;
  status: SpanStatus;
  startTime: number;
  endTime: number;
  durationMs: number;
  attributes: Record<string, string | number | boolean>;
  events: Array<{
    name: string;
    timestamp: number;
    attributes?: Record<string, string | number | boolean>;
  }>;
}

export interface TraceExportEvent {
  type: 'trace';
  service: string;
  resource: Record<string, string>;
  spans: Span[];
  timestamp: string;
}

export interface TracingOptions {
  /** Service name for trace identification */
  serviceName: string;
  /** Maximum spans per flush (dynamically sized, default: 50) */
  maxSpansPerFlush: number;
  /** Whether to sample from the tail end (always-on percentage, default: 100) */
  sampleRate: number;
  /** Enable trace events for Cloudflare Logpush */
  enableLogpush: boolean;
  /** Export endpoint URL (for external APM like Grafana Tempo) */
  exportEndpoint?: string;
  /** Export API key */
  exportApiKey?: string;
}

const DEFAULT_TRACING_OPTIONS: TracingOptions = {
  serviceName: 'resumeai-pro',
  maxSpansPerFlush: 50,
  sampleRate: 1.0,
  enableLogpush: true,
};

// ============================================================================
// LightweightTracer
// ============================================================================

export class LightweightTracer {
  private options: TracingOptions;
  private spans: Span[] = [];
  private activeSpans = new Map<string, Span>();
  private traceId: string;

  constructor(options?: Partial<TracingOptions>) {
    this.options = { ...DEFAULT_TRACING_OPTIONS, ...options };
    this.traceId = this.generateId(32);
  }

  /**
   * Start a new span as a child of the current active span (or as root).
   */
  startSpan(name: string, attributes?: Record<string, string | number | boolean>): string {
    const spanId = this.generateId(16);
    const parentSpanId = this.getActiveSpanId();

    const span: Span = {
      traceId: this.traceId,
      spanId,
      parentSpanId,
      name,
      status: 'ok',
      startTime: performance.now(),
      endTime: 0,
      durationMs: 0,
      attributes: attributes ?? {},
      events: [],
    };

    this.activeSpans.set(spanId, span);
    return spanId;
  }

  /**
   * End a span, recording its duration.
   */
  endSpan(spanId: string, status: SpanStatus = 'ok', attributes?: Record<string, string | number | boolean>): void {
    const span = this.activeSpans.get(spanId);
    if (!span) return;

    span.endTime = performance.now();
    span.durationMs = span.endTime - span.startTime;
    span.status = status;
    if (attributes) {
      Object.assign(span.attributes, attributes);
    }

    this.activeSpans.delete(spanId);
    this.spans.push(span);

    // Auto-flush if we hit the limit
    if (this.spans.length >= this.options.maxSpansPerFlush) {
      this.flush();
    }
  }

  /**
   * Add an event to a span.
   */
  addEvent(
    spanId: string,
    eventName: string,
    attributes?: Record<string, string | number | boolean>,
  ): void {
    const span = this.activeSpans.get(spanId);
    if (!span) return;

    span.events.push({
      name: eventName,
      timestamp: performance.now(),
      attributes,
    });
  }

  /**
   * Set an attribute on a span.
   */
  setAttribute(spanId: string, key: string, value: string | number | boolean): void {
    const span = this.activeSpans.get(spanId);
    if (!span) return;
    span.attributes[key] = value;
  }

  /**
   * Flush all completed spans.
   * In a Worker, this sends spans via Logpush structured logs.
   */
  async flush(): Promise<void> {
    if (this.spans.length === 0) return;

    const batch = this.spans.splice(0, this.options.maxSpansPerFlush);

    if (this.options.enableLogpush) {
      // Log in CF Logpush-compatible JSON format
      // In production, these are consumed by Cloudflare Logpush → your log sink
      console.log(JSON.stringify(this.toExportEvent(batch)));
    }

    // If external APM endpoint is configured, send via fetch
    if (this.options.exportEndpoint && this.options.exportApiKey) {
      this.sendToApmEndpoint(batch).catch(() => {
        // Fire-and-forget — don't block the request on export
      });
    }
  }

  /**
   * Finalize the trace: flush remaining spans and return the final report.
   */
  async finalize(): Promise<{ traceId: string; spanCount: number }> {
    // End any remaining active spans
    Array.from(this.activeSpans.entries()).forEach(([spanId, span]) => {
      span.endTime = performance.now();
      span.durationMs = span.endTime - span.startTime;
      span.status = 'ok';
      this.spans.push(span);
    });
    this.activeSpans.clear();

    await this.flush();

    return {
      traceId: this.traceId,
      spanCount: this.spans.length, // remaining after flush (should be 0)
    };
  }

  /**
   * Create an in-memory queryable trace from completed spans.
   * Useful for rendering waterfall diagrams in dev/debug.
   */
  toTrace(): Span[] {
    return [...this.spans];
  }

  // ── Private ─────────────────────────────────────────────────────────

  private getActiveSpanId(): string | null {
    // Return the last-started span that hasn't been ended
    // Using reverse-iteration to find deepest active span
    const entries = Array.from(this.activeSpans.entries());
    for (let i = entries.length - 1; i >= 0; i--) {
      return entries[i][0];
    }
    return null;
  }

  private toExportEvent(batch: Span[]): TraceExportEvent {
    return {
      type: 'trace',
      service: this.options.serviceName,
      resource: {
        'service.name': this.options.serviceName,
        'telemetry.sdk.name': 'resumeai-pro-lwt',
        'telemetry.sdk.language': 'typescript',
        'cloudflare.worker': 'true',
      },
      spans: batch,
      timestamp: new Date().toISOString(),
    };
  }

  private async sendToApmEndpoint(batch: Span[]): Promise<void> {
    if (!this.options.exportEndpoint || !this.options.exportApiKey) return;

    try {
      await fetch(this.options.exportEndpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${this.options.exportApiKey}`,
        },
        body: JSON.stringify({
          resourceSpans: [{
            resource: {
              attributes: [{ key: 'service.name', value: { stringValue: this.options.serviceName } }],
            },
            scopeSpans: [{
              scope: { name: 'resumeai-pro' },
              spans: batch.map((s) => ({
                traceId: s.traceId,
                spanId: s.spanId,
                parentSpanId: s.parentSpanId ?? undefined,
                name: s.name,
                status: { code: s.status === 'error' ? 2 : 1 },
                startTimeUnixNano: BigInt(Math.round(s.startTime * 1_000_000)).toString(),
                endTimeUnixNano: BigInt(Math.round(s.endTime * 1_000_000)).toString(),
                attributes: Object.entries(s.attributes).map(([k, v]) => ({
                  key: k,
                  value: { stringValue: String(v) },
                })),
              })),
            }],
          }],
        }),
      });
    } catch {
      // Export is best-effort
    }
  }

  private generateId(length: number): string {
    const chars = 'abcdef0123456789';
    let result = '';
    for (let i = 0; i < length; i++) {
      result += chars[Math.floor(Math.random() * chars.length)];
    }
    return result;
  }
}

