// ResumeAI Pro — core domain types

export type Role = "guest" | "user" | "admin" | "super_admin";

export type UserStatus = "pending" | "approved" | "suspended" | "deleted";

export interface User {
  id: string;
  name: string;
  username?: string;
  email: string;
  passwordHash?: string;
  avatarUrl?: string;
  role: Role;
  status: UserStatus;
  provider: "email" | "puter";
  createdAt: string;
  updatedAt?: string;
  lastActiveAt: string;
  lastLoginAt?: string;
  usage: {
    resumesGenerated: number;
    atsChecks: number;
    coverLetters: number;
    interviewPreps: number;
    downloads: number;
  };
}

/**
 * Target market for regional resume norms. Selecting a region turns on
 * region-specific personal-field guidance and ATS warnings (e.g. a photo is
 * expected on Gulf CVs but strongly discouraged on North American ones).
 */
export type ResumeRegion = "na" | "eu" | "gulf";

export interface ContactInfo {
  email?: string;
  phone?: string;
  location?: string;
  website?: string;
  linkedin?: string;
  github?: string;
  twitter?: string;
  /** Structured personal details — map of label → value for additional info fields
   *  (e.g. nationality, driving licence, passport, visa, address, marital status, availability).
   *  Stored alongside the free-text additionalInfo field for structured rendering. */
  personalDetails?: Record<string, string>;
  /**
   * Regional norms profile for this resume. Stored INSIDE contact_json (not a
   * dedicated D1 column) so the value round-trips through cloud sync with zero
   * schema migration — ALTER TABLE on resumes has a broken-CI history (see
   * migrations/0018). Semantically it is personal context, like personalDetails.
   */
  region?: ResumeRegion;
}

export interface ResumeExperience {
  id: string;
  company: string;
  title: string;
  location?: string;
  startDate: string;
  endDate: string; // "Present" or "YYYY-MM"
  bullets: string[];
  old_bullets?: string[];
}

export interface ResumeEducation {
  id: string;
  institution: string;
  degree: string;
  field?: string;
  location?: string;
  startDate: string;
  endDate: string;
  gpa?: string;
  highlights?: string[];
}

export interface ResumeSkill {
  id: string;
  name: string;
  category?: string;
  level?: "beginner" | "intermediate" | "advanced" | "expert";
}

export interface ResumeProject {
  id: string;
  name: string;
  description?: string;
  url?: string;
  bullets: string[];
}

export interface ResumeCertification {
  id: string;
  name: string;
  issuer?: string;
  date?: string;
  url?: string;
}

export interface ResumeLanguage {
  id: string;
  name: string;
  proficiency: "basic" | "conversational" | "fluent" | "native";
}

/**
 * DynamicSection — a resume section that exists in the original resume but is NOT
 * explicitly defined in the optimization directives (summary, experience, education,
 * skills, languages, additionalInfo).
 *
 * Examples: Certifications, Awards, Projects, Volunteer Experience, Internships,
 * Interests, Publications, Training, Memberships, References, Achievements,
 * Conferences, Licenses, Technical Skills, Personal Profile, Objective,
 * Professional Affiliations, Hobbies, Courses, Accomplishments, Extra-Curricular
 * Activities, Military Service, Community Involvement, or any custom section.
 *
 * These sections MUST be preserved through optimization — they may be enhanced
 * (grammar, ATS keywords, professional wording) but never removed.
 */
export interface DynamicSection {
  /** Unique fingerprint ID derived from normalizedTitle + content via SHA-256 */
  id: string;
  /** Section title (e.g., "Volunteer Experience", "Certifications") */
  title: string;
  /** Lowercased, trimmed, whitespace-collapsed version of title */
  normalizedTitle: string;
  /** Raw content string (the full text of the section, newline-separated) */
  content: string;
  /** Individual bullet points or lines within this section */
  bullets: string[];
  /** Position within the resume (0-based) */
  order: number;
  /** Source marker — always 'parsed' for dynamic sections */
  source: "parsed";
  /** Immutable marker — dynamic sections are never removed */
  immutable: true;
  /** Optional enhanced version of the content (after optimization) */
  enhanced?: string;
  /** Optional enhanced version of bullets (after optimization) */
  enhancedBullets?: string[];
}

export interface ResumeData {
  id: string;
  name: string;
  headline?: string;
  contact: ContactInfo;
  summary?: string;
  experience: ResumeExperience[];
  education: ResumeEducation[];
  skills: ResumeSkill[];
  projects: ResumeProject[];
  certifications: ResumeCertification[];
  languages: ResumeLanguage[];
  achievements?: string[];
  /**
   * Dynamic sections — any section parsed from the original resume that is NOT
   * one of the directive-defined sections. These MUST be preserved through
   * optimization and MUST appear in the final output.
   */
  dynamicSections?: DynamicSection[];
  template: ResumeTemplate;
  accentColor?: string;
  photoUrl?: string;
  dateOfBirth?: string;
  additionalInfo?: string;
  /** Original raw text extracted from the uploaded file/paste.
   *  Preserved so the LLM always has access to the full content
   *  even if the parser's structured extraction missed sections. */
  rawText?: string;
  createdAt: string;
  updatedAt: string;
  source?: "upload" | "manual" | "ai-optimized" | "ai-optimized-aviation" | "template";
  fileName?: string;
  /**
   * Set ONLY inside public share snapshots when the owner chose to hide
   * contact details (see src/lib/share.ts buildShareSnapshot). The live
   * resume never carries this flag — it marks the /r/<token> reader so it
   * can show "contact details hidden by the owner" instead of silently
   * rendering an empty contact block.
   */
  shareContactHidden?: boolean;
}

export type ResumeTemplate =
  | "ats-professional"
  | "executive"
  | "modern"
  | "corporate"
  | "europass"
  | "creative"
  | "minimal"
  | "infohas-pro"
  | "compact"
  | "tech"
  | "academic"
  | "consulting"
  | "startup"
  | "classic";

export interface JobDescription {
  id: string;
  title: string;
  company?: string;
  location?: string;
  employmentType?: string;
  salary?: string;
  responsibilities: string[];
  requiredSkills: string[];
  preferredSkills: string[];
  technologies: string[];
  experienceYears?: string;
  education?: string;
  keywords: string[];
  rawText?: string;
