export type AIProviderType =
  | "antigravity"
  | "zai-web"
  | "puter"
  | "workers-ai"
  | "openai"
  | "gemini"
  | "claude"
  | "deepseek"
  | "groq"
  | "mistral"
  | "cohere"
  | "perplexity"
  | "openrouter"
  | "together"
  | "huggingface"
  | "cerebras"
  | "sambanova"
  | "ollama"
  | "azure-openai"
  | "bedrock"
  | "opencode"
  | "opencode-zen"
  | "zencode"
  | "nvidia"
  | "github"
  | "custom";


export interface AIProvider {
  id: string;
  name: string;
  type: AIProviderType;
  // ============================================================
  // PROVIDER CLASSIFICATION (Category A vs Category B)
  // ============================================================
  // Category A: "api" — uses API keys, can run server-side (OpenAI, DeepSeek, etc.)
  // Category B: "browser_auth" — requires browser session (Puter.js)
  providerCategory: "api" | "browser_auth";

  /**
   * Task 29 — integration mechanism identity (OPTIONAL, additive).
   * Distinguishes HOW a provider is reached, independent of which vendor's
   * model names it exposes:
   *  - "api"     REST/OpenAI-compatible endpoint, Base URL required (Google
   *              Gemini API, OpenAI, NVIDIA NIM, …)
   *  - "cli"     CLI/runtime integration authenticated via OAuth or token —
   *              Base URL is N/A (Antigravity CLI)
   *  - "local"   local runtime (Ollama)
   *  - "browser" browser-native SDK (Puter.js)
   * Absent = legacy record; infer "api" except type "puter"/"antigravity".
   * Google sign-in inside a CLI integration is an AUTH MECHANISM, never proof
   * that the provider is the Google Gemini API.
   *
   * Task 30 — "web-session": authenticated chat.z.ai BROWSER SESSION
   * integrations (Z.ai Web). Entirely separate from the official Z.ai API
   * (key/Bearer + documented endpoints): the session credential is
   * credential_type = zai_web_session, discovered/validated through the
   * user-initiated same-origin browser bridge — never an API key.
   */
  integrationType?: "api" | "cli" | "local" | "browser" | "web-session";

  // Capabilities (what the provider supports)
  supportsServerSide: boolean;     // can execute from Worker/backend
  supportsClientSide: boolean;     // can execute from browser
  supportsStreaming: boolean;
  supportsFunctionCalling: boolean;
  supportsJsonMode: boolean;
  requiresBrowserAuth: boolean;    // true for Puter (needs user session)
  requiresApiKey: boolean;         // true for API providers

  apiUrl?: string;
  baseUrl?: string;
  apiKey?: string;
  /** Alternate API keys tried when primary key hits rate limit (429).
   * Each key is tried in order before marking the provider as rate-limited. */
  alternateApiKeys?: string[];
  headersJson?: string;
  parametersJson?: string;
  requestTemplate?: string;
  responsePath?: string;
  streamingEnabled?: boolean;
  modelName?: string;
  priority: number;
  isActive: boolean;
  isDefault?: boolean;
  isFallback?: boolean;
  isBuiltIn?: boolean;
  timeout: number;
  maxTokens: number;
  temperature: number;
  /** Optional provider-default nucleus sampling (0-1). Phase 8.1.3.2A. */
  topP?: number;
  retryAttempts?: number;
  rateLimitPerMinute?: number;
  /** Max simultaneous in-flight requests the router sends to this provider
   * (Task 19 / S3 polish). Clamped 1..6 by provider-concurrency; absent =
   * global default (2). Lower it for free tiers that 429 under parallel
   * agent load; raise it for endpoints that tolerate concurrency. */
  concurrencyCap?: number;
  applicationId?: string;
  clientId?: string;
  redirectUri?: string;
  enabledModels?: string[];
  authType?: "bearer" | "header" | "query" | "none";
  allowedForRegularUsers?: boolean;
  costPerInputToken?: number;
  costPerOutputToken?: number;
  status: "healthy" | "degraded" | "down" | "untested";
  usage: { requests: number; tokens: number; errors: number; avgLatencyMs: number; cost: number };
  lastUsedAt?: string;
  // Health tracking (for Provider Health Dashboard)
  health?: {
    lastSuccessAt?: string;
    lastFailureAt?: string;
    lastError?: string;
    consecutiveFailures: number;
    consecutiveSuccesses: number;
    rateLimitedUntil?: string;
    // === AUTO-HEAL STATE (Provider Auto-Heal subsystem) ===
    /** Coarse health/heal state shown in the AI Models UI. */
    healState?: "healthy" | "degraded" | "cooldown" | "model_error" | "endpoint_error"
      | "auth_error" | "healing" | "recovered" | "configuration_error" | "unavailable" | "untested";
    /** Human-readable diagnosis of the last classified failure. */
    lastDiagnosis?: string;
    /** Failure kind from the error classifier (rate_limited, model_error, …). */
    lastFailureKind?: string;
    /** ISO timestamp of the last heal attempt. */
    lastHealAt?: string;
    /** How many auto-heal attempts have been made for this provider. */
    autoHealAttempts?: number;
    /** Repairs that passed validation. */
    successfulRepairs?: number;
    /** Repairs that failed validation. */
    failedRepairs?: number;
  };
}

