// ============================================================================
// Task 20 — ADAPTIVE per-provider concurrency cap (AIMD)
//
// Task 19 made the cap user-configurable per provider. This closes the loop:
// the cap now tunes ITSELF from live traffic evidence.
//
//   on 429 (real traffic only): multiplicative DECREASE — current = floor(current/2),
//     floored at 1. A provider that rate-limits us gets hit more gently.
//   on success: additive INCREASE — after ADAPTIVE_CAP_RECOVER_THRESHOLD
//     consecutive successes, current += 1, never above the CONFIGURED ceiling
//     (per-provider cap ?? global default). The user's setting is always the
//     ceiling; the adaptive layer only tightens BELOW it.
//
// Why AIMD: multiplicative decrease reacts fast to congestion (the same
// reasoning as TCP); additive increase probes back slowly so a flapping
// free tier is not re-pounded at full parallelism after one lucky success.
//
// Probe/cooldown separation (Task 15/16) is preserved: the router only
// records rate-limit hits where it arms traffic cooldowns — probe evidence
// (requestType "test") never tightens the cap.
// ============================================================================

import { describe, it, expect, beforeEach } from "vitest";
import {
  acquireProviderSlot,
  releaseProviderSlot,
  getProviderInFlight,
  setProviderConcurrencyOpts,
  getEffectiveProviderCap,
  getConfiguredProviderCap,
  getAdaptiveProviderCap,
  recordProviderRateLimitHit,
  recordProviderTrafficSuccess,
  clampProviderConcurrencyCap,
  __resetProviderConcurrencyForTests,
  DEFAULT_PROVIDER_CONCURRENCY,
  ADAPTIVE_CAP_RECOVER_THRESHOLD,
} from "../provider-concurrency";

beforeEach(() => {
  __resetProviderConcurrencyForTests();
  setProviderConcurrencyOpts({ cap: DEFAULT_PROVIDER_CONCURRENCY, maxWaitMs: 10_000 });
});

describe("getConfiguredProviderCap — the user's setting (unchanged semantics)", () => {
  it("no per-provider cap → global default", () => {
    expect(getConfiguredProviderCap("p", undefined)).toBe(DEFAULT_PROVIDER_CONCURRENCY);
  });

  it("per-provider cap wins and is clamped to 1..6", () => {
    expect(getConfiguredProviderCap("p", 4)).toBe(4);
    expect(getConfiguredProviderCap("p", 0)).toBe(1);
    expect(getConfiguredProviderCap("p", 99)).toBe(6);
    expect(getConfiguredProviderCap("p", "abc")).toBe(DEFAULT_PROVIDER_CONCURRENCY);
  });
});

describe("recordProviderRateLimitHit — multiplicative decrease on 429 evidence", () => {
  it("first hit tightens 4 → 2", () => {
    const ch = recordProviderRateLimitHit("p", 4);
    expect(ch.changed).toBe(true);
    expect(ch.from).toBe(4);
    expect(ch.to).toBe(2);
    expect(getAdaptiveProviderCap("p")).toBe(2);
  });

  it("second hit tightens 2 → 1", () => {
    recordProviderRateLimitHit("p", 4);
    const ch = recordProviderRateLimitHit("p", 4);
    expect(ch.from).toBe(2);
    expect(ch.to).toBe(1);
  });

  it("floors at 1 — further hits report changed:false", () => {
    recordProviderRateLimitHit("p", 4);
    recordProviderRateLimitHit("p", 4);
    const ch = recordProviderRateLimitHit("p", 4);
    expect(ch.changed).toBe(false);
    expect(ch.to).toBe(1);
    expect(getAdaptiveProviderCap("p")).toBe(1);
  });

  it("odd values halve with floor: 3 → 1", () => {
    const ch = recordProviderRateLimitHit("p", 3);
    expect(ch.from).toBe(3);
    expect(ch.to).toBe(1);
  });

  it("a hit resets the consecutive-success counter", () => {
    const ceiling = 4;
    recordProviderRateLimitHit("p", ceiling);        // 4 → 2
    for (let i = 0; i < ADAPTIVE_CAP_RECOVER_THRESHOLD - 1; i++) {
      recordProviderTrafficSuccess("p", ceiling);    // counter → 4, no change yet
    }
    recordProviderRateLimitHit("p", ceiling);        // 2 → 1, counter reset
    const ch = recordProviderTrafficSuccess("p", ceiling);
    expect(ch.changed).toBe(false);                  // first success after the hit
  });

  it("out-of-range ceiling is clamped", () => {
    const ch = recordProviderRateLimitHit("p", 99);
    expect(ch.ceiling).toBe(clampProviderConcurrencyCap(99));
  });
});

describe("recordProviderTrafficSuccess — additive increase, ceiling respected", () => {
  it("success on a never-tightened provider creates NO adaptive state", () => {
    const ch = recordProviderTrafficSuccess("healthy-provider", 2);
    expect(ch.changed).toBe(false);
    expect(getAdaptiveProviderCap("healthy-provider")).toBeNull(); // nothing to recover
  });

  it(`recovers +1 only after ${ADAPTIVE_CAP_RECOVER_THRESHOLD} consecutive successes`, () => {
    recordProviderRateLimitHit("p", 4); // 4 → 2
    for (let i = 0; i < ADAPTIVE_CAP_RECOVER_THRESHOLD - 1; i++) {
      const ch = recordProviderTrafficSuccess("p", 4);
      expect(ch.changed).toBe(false);
    }
    const ch = recordProviderTrafficSuccess("p", 4); // threshold reached
    expect(ch.changed).toBe(true);
    expect(ch.from).toBe(2);
    expect(ch.to).toBe(3);
    expect(getAdaptiveProviderCap("p")).toBe(3);
  });

  it("never recovers above the configured ceiling", () => {
    recordProviderRateLimitHit("p", 2); // 2 → 1
    for (let i = 0; i < 10 * ADAPTIVE_CAP_RECOVER_THRESHOLD; i++) {
      recordProviderTrafficSuccess("p", 2);
    }
    expect(getAdaptiveProviderCap("p")).toBe(2); // clamped at the ceiling, not beyond
  });

  it("raises the ceiling when the user re-configures upward (recovery targets the NEW ceiling)", () => {
    recordProviderRateLimitHit("p", 2); // 2 → 1
    for (let i = 0; i < 10 * ADAPTIVE_CAP_RECOVER_THRESHOLD; i++) {
      recordProviderTrafficSuccess("p", 4); // user raised config to 4
    }
    expect(getAdaptiveProviderCap("p")).toBe(4);
  });
});

describe("getEffectiveProviderCap — adaptive-aware (min of configured and adaptive)", () => {
  it("no adaptive state → configured cap", () => {
    expect(getEffectiveProviderCap("p", 4)).toBe(4);
  });

  it("tightened state wins over a HIGHER configured cap", () => {
    recordProviderRateLimitHit("p", 4); // 4 → 2
    expect(getEffectiveProviderCap("p", 4)).toBe(2);
    recordProviderRateLimitHit("p", 4); // 2 → 1
    expect(getEffectiveProviderCap("p", 4)).toBe(1);
  });

  it("never reports above the configured cap even if state lags", () => {
    recordProviderRateLimitHit("p", 2); // current 1, ceiling 2
    expect(getEffectiveProviderCap("p", 1)).toBe(1); // configured lowered below adaptive
  });
});

describe("acquireProviderSlot gates at the ADAPTIVE cap", () => {
  it("after a hit, configured-2 traffic is gated to 1 slot", async () => {
    setProviderConcurrencyOpts({ cap: 2, maxWaitMs: 30 });
    recordProviderRateLimitHit("p", 2); // 2 → 1
    expect(await acquireProviderSlot("p")).toBe(true);
    expect(await acquireProviderSlot("p")).toBe(false); // adaptive cap 1
    expect(getProviderInFlight("p")).toBe(1);
    releaseProviderSlot("p");
  });

  it("after recovery, the configured cap applies again", async () => {
    setProviderConcurrencyOpts({ cap: 2, maxWaitMs: 30 });
    recordProviderRateLimitHit("p", 2); // 2 → 1
    for (let i = 0; i < ADAPTIVE_CAP_RECOVER_THRESHOLD; i++) {
      recordProviderTrafficSuccess("p", 2);
    }
    expect(getEffectiveProviderCap("p")).toBe(2);
    expect(await acquireProviderSlot("p")).toBe(true);
    expect(await acquireProviderSlot("p")).toBe(true); // back to 2 slots
    releaseProviderSlot("p");
    releaseProviderSlot("p");
  });

  it("probes still bypass an adaptively tightened provider", async () => {
    recordProviderRateLimitHit("p", 2);
    expect(await acquireProviderSlot("p", { probe: true })).toBe(true);
    expect(getProviderInFlight("p")).toBe(0);
  });
});

describe("__resetProviderConcurrencyForTests clears adaptive state", () => {
  it("adaptive state is gone after reset", () => {
    recordProviderRateLimitHit("p", 4);
    expect(getAdaptiveProviderCap("p")).not.toBeNull();
    __resetProviderConcurrencyForTests();
    expect(getAdaptiveProviderCap("p")).toBeNull();
  });
});

src/lib/__tests__/provider-concurrency-c:
// ============================================================================
// Task 19 — S3 polish: USER-CONFIGURABLE per-provider concurrency cap
//
// Task 18 (S3) shipped a per-provider semaphore with a GLOBAL cap (default 2)
// shared by every provider. Free tiers want it tight (1–2); beefier or paid
// endpoints want headroom (4–6). This pins the per-PROVIDER override:
//
//   - acquireProviderSlot(id, { cap }) — effective cap = clamp(provider cap)
//     falling back to the global default when the provider has none
//   - clamp 1..6 (floor 1: cap 0 would deadlock traffic; ceiling 6: beyond
//     that parallel agents self-inflict 429s again)
//   - overrides are per provider — A's cap never constrains B
//   - withProviderSlot forwards the cap
//   - getEffectiveProviderCap — introspection used by the router's busy
//     event metadata and the settings UI
//
// Router integration: the limiter reads the cap from the ROUTED provider
// object (AIProvider.concurrencyCap), so raising a paid provider's cap above
// the global default lets parallel agents actually run concurrently on it.
// ============================================================================

import { describe, it, expect, beforeEach, vi } from "vitest";
import {
  acquireProviderSlot,
  releaseProviderSlot,
  getProviderInFlight,
  setProviderConcurrencyOpts,
  getEffectiveProviderCap,
  clampProviderConcurrencyCap,
  withProviderSlot,
  DEFAULT_PROVIDER_CONCURRENCY,
  MIN_PROVIDER_CONCURRENCY_CAP,
  MAX_PROVIDER_CONCURRENCY_CAP,
} from "../provider-concurrency";

beforeEach(() => {
  setProviderConcurrencyOpts({ cap: DEFAULT_PROVIDER_CONCURRENCY, maxWaitMs: 10_000 });
});

describe("clampProviderConcurrencyCap", () => {
  it("passes through in-range integers", () => {
    expect(clampProviderConcurrencyCap(1)).toBe(1);
    expect(clampProviderConcurrencyCap(3)).toBe(3);
    expect(clampProviderConcurrencyCap(6)).toBe(6);
  });

  it("floors at 1 — cap 0 would deadlock all traffic", () => {
    expect(clampProviderConcurrencyCap(0)).toBe(MIN_PROVIDER_CONCURRENCY_CAP);
    expect(clampProviderConcurrencyCap(-5)).toBe(MIN_PROVIDER_CONCURRENCY_CAP);
  });

  it("ceilings at 6 — beyond that parallel agents self-inflict 429s", () => {
    expect(clampProviderConcurrencyCap(99)).toBe(MAX_PROVIDER_CONCURRENCY_CAP);
  });

  it("floors fractional input (a cap is a count, not a rate)", () => {
    expect(clampProviderConcurrencyCap(2.9)).toBe(2);
  });

  it("non-numeric garbage falls back to the global default", () => {
    expect(clampProviderConcurrencyCap("abc")).toBe(DEFAULT_PROVIDER_CONCURRENCY);
    expect(clampProviderConcurrencyCap(NaN)).toBe(DEFAULT_PROVIDER_CONCURRENCY);
    expect(clampProviderConcurrencyCap(undefined)).toBe(DEFAULT_PROVIDER_CONCURRENCY);
  });
});

describe("getEffectiveProviderCap", () => {
  it("no per-provider cap → global default", () => {
    expect(getEffectiveProviderCap("p1", undefined)).toBe(DEFAULT_PROVIDER_CONCURRENCY);
  });

  it("per-provider cap wins over the global default", () => {
    expect(getEffectiveProviderCap("p1", 4)).toBe(4);
  });

  it("per-provider cap is clamped", () => {
    expect(getEffectiveProviderCap("p1", 0)).toBe(1);
    expect(getEffectiveProviderCap("p1", 50)).toBe(6);
  });
});

describe("acquireProviderSlot with per-provider cap", () => {
  it("tightens: cap 1 → second traffic acquire is busy (global stays 2)", async () => {
    setProviderConcurrencyOpts({ cap: 2, maxWaitMs: 30 });
    expect(await acquireProviderSlot("cap1", { cap: 1 })).toBe(true);
    expect(await acquireProviderSlot("cap1", { cap: 1 })).toBe(false);
    expect(getProviderInFlight("cap1")).toBe(1);
    releaseProviderSlot("cap1");
  });

  it("raises: cap 4 admits 4 in-flight while the global default is 2", async () => {
    setProviderConcurrencyOpts({ cap: 2, maxWaitMs: 30 });
    expect(await acquireProviderSlot("cap4", { cap: 4 })).toBe(true);
    expect(await acquireProviderSlot("cap4", { cap: 4 })).toBe(true);
    expect(await acquireProviderSlot("cap4", { cap: 4 })).toBe(true);
    expect(await acquireProviderSlot("cap4", { cap: 4 })).toBe(true);
    expect(getProviderInFlight("cap4")).toBe(4);
    expect(await acquireProviderSlot("cap4", { cap: 4 })).toBe(false);
  });

  it("without an override the global default still applies", async () => {
    setProviderConcurrencyOpts({ cap: 2, maxWaitMs: 30 });
    expect(await acquireProviderSlot("plain")).toBe(true);
    expect(await acquireProviderSlot("plain")).toBe(true);
    expect(await acquireProviderSlot("plain")).toBe(false);
  });

  it("overrides are per provider — A's cap never constrains B", async () => {
    setProviderConcurrencyOpts({ cap: 2, maxWaitMs: 30 });
    expect(await acquireProviderSlot("iso-a", { cap: 1 })).toBe(true);
    expect(await acquireProviderSlot("iso-a", { cap: 1 })).toBe(false);
    expect(await acquireProviderSlot("iso-b", { cap: 3 })).toBe(true);
    expect(await acquireProviderSlot("iso-b", { cap: 3 })).toBe(true);
    expect(await acquireProviderSlot("iso-b", { cap: 3 })).toBe(true);
  });

  it("an out-of-range override is clamped at acquire time (0 → 1)", async () => {
    setProviderConcurrencyOpts({ cap: 2, maxWaitMs: 30 });
    expect(await acquireProviderSlot("clamped", { cap: 0 })).toBe(true);
    expect(await acquireProviderSlot("clamped", { cap: 0 })).toBe(false);
  });

  it("probes bypass regardless of a tight cap", async () => {
    setProviderConcurrencyOpts({ cap: 2, maxWaitMs: 30 });
    expect(await acquireProviderSlot("probe-cap", { cap: 1 })).toBe(true);
    expect(await acquireProviderSlot("probe-cap", { probe: true, cap: 1 })).toBe(true);
    expect(getProviderInFlight("probe-cap")).toBe(1); // probe never counted
    releaseProviderSlot("probe-cap");
  });
});

describe("withProviderSlot forwards the cap", () => {
  it("busy sentinel when a cap-1 provider is saturated", async () => {
    setProviderConcurrencyOpts({ cap: 2, maxWaitMs: 30 });
    expect(await acquireProviderSlot("wps", { cap: 1 })).toBe(true);
    const ran = vi.fn();
    const out = await withProviderSlot("wps", ran, { cap: 1, busyValue: "BUSY" });
    expect(out).toBe("BUSY");
    expect(ran).not.toHaveBeenCalled();
    releaseProviderSlot("wps");
  });

  it("runs fn when the raised cap admits the call", async () => {
    setProviderConcurrencyOpts({ cap: 1, maxWaitMs: 30 });
    const out = await withProviderSlot("wps2", async () => "OK", { cap: 3, busyValue: "BUSY" });
    expect(out).toBe("OK");
    expect(getProviderInFlight("wps2")).toBe(0); // released
  });
});

src/lib/__tests__/provider-concurrency-s:
// ============================================================================
// Task 21 — ADAPTIVE CAP OBSERVABILITY (snapshot + manual reset)
//
// Task 20 gave the router a self-tuning cap (halve on 429, +1 per 5 clean
// successes, ceiling-bound). But the state lives in a module-private map:
// the Providers page — the exact surface where the user CONFIGURES the
// ceiling — shows nothing about what the adaptive layer is actually
// enforcing right now. An operator watching 429-driven busy skips in the
// trajectory panel has no way to answer "what cap is in effect for this
// provider, and why?"
//
// This adds a read-only snapshot API + a surgical reset, pure logic first
// (the UI column is thin wiring over these calls):
//
//   getAdaptiveCapState(id)            → { current, ceiling, consecutiveSuccesses } | null
//   getProviderConcurrencySnapshot(id, perProviderCap?) → the full picture:
//     configuredCap (user ceiling, clamped) / adaptiveCap (null = never
//     tightened) / effectiveCap (what acquire enforces NOW) / inFlight /
//     tightened (effective < configured — the user-visible truth) /
//     consecutiveSuccesses (recovery progress toward the next +1 step)
//   resetProviderAdaptiveCap(id)       → manual escape hatch; returns whether
//     state existed. Clears ONE provider only — never touches others.
//
// "tightened" is derived from EFFECTIVE vs CONFIGURED (not from state
// existence): a fully-recovered provider (current == ceiling) and a provider
// whose adaptive current is masked by a lowered user ceiling both report
// tightened:false — nothing is being gated below the user's setting.
// ============================================================================

import { describe, it, expect, beforeEach } from "vitest";
import {
  acquireProviderSlot,
  releaseProviderSlot,
  setProviderConcurrencyOpts,
  getAdaptiveCapState,
  getProviderConcurrencySnapshot,
  resetProviderAdaptiveCap,
  recordProviderRateLimitHit,
  recordProviderTrafficSuccess,
  __resetProviderConcurrencyForTests,
  DEFAULT_PROVIDER_CONCURRENCY,
  ADAPTIVE_CAP_RECOVER_THRESHOLD,
} from "../provider-concurrency";

beforeEach(() => {
  __resetProviderConcurrencyForTests();
  setProviderConcurrencyOpts({ cap: DEFAULT_PROVIDER_CONCURRENCY, maxWaitMs: 10_000 });
});

describe("getAdaptiveCapState — raw adaptive introspection", () => {
  it("returns null for a provider with no adaptive evidence", () => {
    expect(getAdaptiveCapState("p")).toBeNull();
  });

  it("returns current/ceiling after a 429 hit", () => {
    recordProviderRateLimitHit("p", 4); // 4 → 2
    expect(getAdaptiveCapState("p")).toEqual({
      current: 2,
      ceiling: 4,
      consecutiveSuccesses: 0,
    });
  });

  it("tracks the consecutive-success counter between recovery steps", () => {
    recordProviderRateLimitHit("p", 4); // 4 → 2
    recordProviderTrafficSuccess("p", 4);
    recordProviderTrafficSuccess("p", 4);
    expect(getAdaptiveCapState("p")?.consecutiveSuccesses).toBe(2);
    expect(getAdaptiveCapState("p")?.current).toBe(2);
  });

  it("returns null after resetProviderAdaptiveCap", () => {
    recordProviderRateLimitHit("p", 4);
    expect(getAdaptiveCapState("p")).not.toBeNull();
    resetProviderAdaptiveCap("p");
    expect(getAdaptiveCapState("p")).toBeNull();
  });
});

describe("getProviderConcurrencySnapshot — the full per-provider picture", () => {
  it("never-tightened provider: configured cap, no adaptive, effective = configured", () => {
    const snap = getProviderConcurrencySnapshot("p", 4);
    expect(snap).toEqual({
      providerId: "p",
      configuredCap: 4,
      adaptiveCap: null,
      effectiveCap: 4,
      inFlight: 0,
      tightened: false,
      consecutiveSuccesses: 0,
    });
  });

  it("no per-provider cap → configured falls back to the global default", () => {
    setProviderConcurrencyOpts({ cap: 3 });
    const snap = getProviderConcurrencySnapshot("p");
    expect(snap.configuredCap).toBe(3);
    expect(snap.effectiveCap).toBe(3);
    expect(snap.tightened).toBe(false);
  });

  it("clamps garbage per-provider caps (out of range → ceiling; junk → default)", () => {
    expect(getProviderConcurrencySnapshot("p", 99).configuredCap).toBe(6);
    expect(getProviderConcurrencySnapshot("p", "abc").configuredCap).toBe(DEFAULT_PROVIDER_CONCURRENCY);
  });

  it("after a 429: adaptive current visible, effective gated, tightened=true", () => {
    recordProviderRateLimitHit("p", 4); // 4 → 2
    const snap = getProviderConcurrencySnapshot("p", 4);
    expect(snap.adaptiveCap).toBe(2);
    expect(snap.effectiveCap).toBe(2);
    expect(snap.tightened).toBe(true);
    expect(snap.consecutiveSuccesses).toBe(0);
  });

  it("fully-recovered provider reports tightened=false even though state exists", () => {
    setProviderConcurrencyOpts({ cap: 2 });
    recordProviderRateLimitHit("p", 2); // 2 → 1
    for (let i = 0; i < ADAPTIVE_CAP_RECOVER_THRESHOLD; i++) {
      recordProviderTrafficSuccess("p", 2); // +1 per threshold → back to 2
    }
    const snap = getProviderConcurrencySnapshot("p", 2);
    expect(snap.effectiveCap).toBe(2);
    expect(snap.configuredCap).toBe(2);
    expect(snap.tightened).toBe(false);
  });

  it("tightened=false when the user's lowered ceiling masks the adaptive current", () => {
    recordProviderRateLimitHit("p", 4); // adaptive current 2
    const snap = getProviderConcurrencySnapshot("p", 1); // user ceiling 1 < adaptive 2
    expect(snap.effectiveCap).toBe(1);
    expect(snap.configuredCap).toBe(1);
    expect(snap.tightened).toBe(false);
  });

  it("reflects live in-flight slots and returns to zero after release", async () => {
    setProviderConcurrencyOpts({ cap: 4, maxWaitMs: 30 });
    expect(await acquireProviderSlot("p")).toBe(true);
    expect(await acquireProviderSlot("p")).toBe(true);
    const busy = getProviderConcurrencySnapshot("p", 4);
    expect(busy.inFlight).toBe(2);
    releaseProviderSlot("p");
    releaseProviderSlot("p");
    expect(getProviderConcurrencySnapshot("p", 4).inFlight).toBe(0);
  });

  it("snapshots are per-provider — one provider's state never leaks into another", () => {
    recordProviderRateLimitHit("p1", 4); // p1 tightened to 2
    const a = getProviderConcurrencySnapshot("p1", 4);
    const b = getProviderConcurrencySnapshot("p2", 4);
    expect(a.tightened).toBe(true);
    expect(b.tightened).toBe(false);
    expect(b.adaptiveCap).toBeNull();
  });
});

describe("resetProviderAdaptiveCap — manual escape hatch", () => {
  it("returns false for a provider with no adaptive state (no-op)", () => {
    expect(resetProviderAdaptiveCap("ghost")).toBe(false);
  });

  it("returns true for a tightened provider and restores the configured cap", () => {
    recordProviderRateLimitHit("p", 4); // 4 → 2
    expect(getProviderConcurrencySnapshot("p", 4).tightened).toBe(true);
    expect(resetProviderAdaptiveCap("p")).toBe(true);
    const snap = getProviderConcurrencySnapshot("p", 4);
    expect(snap.adaptiveCap).toBeNull();
    expect(snap.effectiveCap).toBe(4);
    expect(snap.tightened).toBe(false);
  });

  it("clears only the target provider — siblings keep their adaptive state", () => {
    recordProviderRateLimitHit("p1", 4);
    recordProviderRateLimitHit("p2", 4);
    resetProviderAdaptiveCap("p1");
    expect(getAdaptiveCapState("p1")).toBeNull();
    expect(getAdaptiveCapState("p2")).not.toBeNull();
  });

  it("reset also clears the recovery counter — a fresh hit starts over", () => {
    recordProviderRateLimitHit("p", 4); // 4 → 2
    recordProviderTrafficSuccess("p", 4);
    recordProviderTrafficSuccess("p", 4);
    resetProviderAdaptiveCap("p");
    recordProviderRateLimitHit("p", 4); // first evidence again: 4 → 2
    const st = getAdaptiveCapState("p");
    expect(st?.current).toBe(2);
    expect(st?.consecutiveSuccesses).toBe(0);
  });

  it("traffic acquires at the configured cap immediately after reset", async () => {
    setProviderConcurrencyOpts({ cap: 2, maxWaitMs: 30 });
    recordProviderRateLimitHit("p", 2); // gated to 1
    expect(await acquireProviderSlot("p")).toBe(true);
    expect(await acquireProviderSlot("p")).toBe(false); // adaptive cap 1
    releaseProviderSlot("p");
    resetProviderAdaptiveCap("p");
    expect(await acquireProviderSlot("p")).toBe(true); // cap 2 again
    releaseProviderSlot("p");
    releaseProviderSlot("p");
  });
});

src/lib/__tests__/provider-cooldown-endp:
// ============================================================================
// Regression Tests — Endpoint-error cooldown (production evidence 2026-09-02)
//
// Antigravity (browser) proxies every call through cloudcode-pa.googleapis.com
// which answers 404 HTML on EVERY request; the dead NVIDIA NIM function id did
// the same. recordTrafficCooldownFromError only armed 429/401/timeout windows,
// so permanently-404ing providers were NEVER skipped — every pipeline step
// re-hit the same 404 all session long (dozens of console 404s per run).
//
// NOTE: vitest runs in the node environment; provider-cooldown.ts uses
// sessionStorage when present and is a no-op without it, so these tests
// install a minimal sessionStorage stub on globalThis to exercise real logic.
// ============================================================================

import { describe, it, expect, beforeEach } from "vitest";
import {
  markProviderEndpointCooldown,
  isProviderInCooldown,
  getProviderCooldownRemainingMs,
  getProviderCooldownClass,
  isEndpointNotFoundError,
  recordTrafficCooldownFromError,
  clearProviderCooldownOnSuccess,
} from "../provider-cooldown";

const PID = "p_test_endpoint";

/** Minimal sessionStorage/localStorage stub on globalThis.window (node env has no window). */
function installSessionStorageStub() {
  const map = new Map<string, string>();
  const store = {
    getItem: (k: string) => (map.has(k) ? map.get(k)! : null),
    setItem: (k: string, v: string) => void map.set(k, String(v)),
    removeItem: (k: string) => void map.delete(k),
    clear: () => void map.clear(),
  };
  (globalThis as any).window = { sessionStorage: store, localStorage: store };
  return map;
}

describe("endpoint-error cooldown (404-family)", () => {
  let map: Map<string, string>;

  beforeEach(() => {
    map = installSessionStorageStub();
  });

  it("isEndpointNotFoundError detects status codes and message variants", () => {
    expect(isEndpointNotFoundError(new Error("x"), 404)).toBe(true);
    expect(isEndpointNotFoundError(new Error("x"), 410)).toBe(true);
    expect(
      isEndpointNotFoundError(
        new Error('Antigravity proxy error 404: {"error":"API returned HTTP 404: <!DOCTYPE html>"}')
      )
    ).toBe(true);
    expect(isEndpointNotFoundError(new Error("Function '23d4f03a': Not found for account 'acct'"))).toBe(true);
    expect(isEndpointNotFoundError({ statusCode: 404 })).toBe(true);
    // Non-404 failures must NOT classify as endpoint errors
    expect(isEndpointNotFoundError(new Error("429 rate limit"))).toBe(false);
    expect(isEndpointNotFoundError(new Error("generate timed out after 25s"))).toBe(false);
    expect(isEndpointNotFoundError(new Error("HTTP 401: invalid key"))).toBe(false);
    expect(isEndpointNotFoundError(new Error("HTTP 500 overloaded"))).toBe(false);
  });

  it("markProviderEndpointCooldown arms a cooldown with class 'endpoint'", () => {
    expect(isProviderInCooldown(PID)).toBe(false);
    markProviderEndpointCooldown(PID);
    expect(isProviderInCooldown(PID)).toBe(true);
    expect(getProviderCooldownClass(PID)).toBe("endpoint");
    expect(getProviderCooldownRemainingMs(PID)).toBeGreaterThan(0);
    // Bounded window — 10 minutes, not an all-day block
    expect(getProviderCooldownRemainingMs(PID)).toBeLessThanOrEqual(10 * 60 * 1000);
    clearProviderCooldownOnSuccess(PID);
    expect(isProviderInCooldown(PID)).toBe(false);
  });

  it("recordTrafficCooldownFromError arms the endpoint class on REAL-traffic 404s", () => {
    const armed = recordTrafficCooldownFromError({
      cooldownId: PID,
      providerId: PID,
      error: new Error("Antigravity proxy error 404: API returned HTTP 404: <!DOCTYPE html>"),
      isTimeout: false,
      requestType: "chat",
    });
    expect(armed).toBe("endpoint");
    expect(isProviderInCooldown(PID)).toBe(true);
    expect(getProviderCooldownClass(PID)).toBe("endpoint");
    expect(map.size).toBeGreaterThan(0); // actually written to the session store
  });

  it("probes (requestType 'test') never arm the endpoint cooldown", () => {
    const armed = recordTrafficCooldownFromError({
      cooldownId: PID,
      providerId: PID,
      error: new Error("API returned HTTP 404"),
      isTimeout: false,
      requestType: "test",
    });
    expect(armed).toBeNull();
    expect(isProviderInCooldown(PID)).toBe(false);
  });

  it("does not misclassify non-404 failures as endpoint errors", () => {
    const armed = recordTrafficCooldownFromError({
      cooldownId: PID,
      providerId: PID,
      error: new Error("HTTP 500: upstream overloaded"),
      isTimeout: false,
      requestType: "chat",
    });
    expect(armed).toBeNull(); // 5xx stays evidence-only (pre-existing behavior)
    expect(isProviderInCooldown(PID)).toBe(false);
  });
});

src/lib/__tests__/provider-cooldown-pers:
// ============================================================================
// S1 — Cross-session quota cooldown persistence (Task 18)
//
// Session storage survives a page RELOAD but dies with the TAB. A 30-minute
// quota window stored only in sessionStorage therefore evaporates the moment
// the user closes and reopens the app — the first request of the new session
// re-hits the quota-dead provider (one wasted request + latency before the
// window re-arms).
//
// Contract under test:
//   - LONG windows (>= QUOTA_PERSIST_MIN_MS: quota 30m, 401 30m) are mirrored
//     into localStorage (keyed with a dedicated prefix) and survive a wiped
//     sessionStorage ("new tab" simulation).
//   - SHORT windows (429 3m, timeout 90s) remain session-only — a fresh tab
//     always starts with a clean tactical slate.
//   - Early-clear (success evidence) removes BOTH stores.
//   - Expired localStorage entries are ignored and removed (self-cleaning).
//   - Legacy bare-number entries (pre-JSON format) still parse.
//   - New introspection API: getProviderCooldownRemainingMs / Class.
// ============================================================================

import { describe, it, expect, beforeEach } from "vitest";
import {
  markProviderQuotaCooldown,
  markProvider429Cooldown,
  markProvider401Cooldown,
  markProviderTimeoutCooldown,
  markProviderRateLimitCooldown,
  isProviderInCooldown,
  clearProviderCooldownOnSuccess,
  getProviderCooldownRemainingMs,
  getProviderCooldownClass,
  PROVIDER_COOLDOWN_PREFIX,
  PROVIDER_QUOTA_PERSIST_PREFIX,
  QUOTA_PERSIST_MIN_MS,
  PROVIDER_QUOTA_COOLDOWN_MS,
} from "../provider-cooldown";

// -- Separate fakes: sessionStorage dies with the tab, localStorage does not --
const sessionStore = new Map<string, string>();
const localStore = new Map<string, string>();
(globalThis as any).window = {
  sessionStorage: {
    getItem: (k: string) => sessionStore.get(k) ?? null,
    setItem: (k: string, v: string) => void sessionStore.set(k, v),
    removeItem: (k: string) => void sessionStore.delete(k),
  },
  localStorage: {
    getItem: (k: string) => localStore.get(k) ?? null,
    setItem: (k: string, v: string) => void localStore.set(k, v),
    removeItem: (k: string) => void localStore.delete(k),
  },
};

let seq = 0;
const nextId = () => `p_persist_${++seq}`;

/** Simulates the user closing the tab and opening a new one. */
function simulateNewTab(): void {
  sessionStore.clear();
}

beforeEach(() => {
  sessionStore.clear();
  localStore.clear();
});

describe("S1 — long cooldowns survive a new tab (localStorage mirror)", () => {
  it("quota cooldown (30m) survives simulateNewTab()", () => {
    const id = nextId();
    markProviderQuotaCooldown(id);
    expect(isProviderInCooldown(id)).toBe(true);

    simulateNewTab();
    // The whole point of S1: still cooling down in the fresh tab.
    expect(isProviderInCooldown(id)).toBe(true);
    // ...and it was re-hydrated into the new session for consistency.
    expect(sessionStore.has(PROVIDER_COOLDOWN_PREFIX + id)).toBe(true);
  });

  it("401 cooldown (30m) survives simulateNewTab()", () => {
    const id = nextId();
    markProvider401Cooldown(id);
    simulateNewTab();
    expect(isProviderInCooldown(id)).toBe(true);
  });

  it("short 429 cooldown (3m) does NOT persist across tabs", () => {
    const id = nextId();
    markProvider429Cooldown(id);
    simulateNewTab();
    expect(isProviderInCooldown(id)).toBe(false);
  });

  it("timeout cooldown (90s) does NOT persist across tabs", () => {
    const id = nextId();
    markProviderTimeoutCooldown(id);
    simulateNewTab();
    expect(isProviderInCooldown(id)).toBe(false);
  });

  it("explicit windows below QUOTA_PERSIST_MIN_MS stay session-only", () => {
    const id = nextId();
    markProviderRateLimitCooldown(id, 5 * 60 * 1000); // 5m < 10m threshold
    expect(localStore.has(PROVIDER_QUOTA_PERSIST_PREFIX + id)).toBe(false);
  });

  it("explicit windows at/above QUOTA_PERSIST_MIN_MS are mirrored", () => {
    const id = nextId();
    markProviderRateLimitCooldown(id, 15 * 60 * 1000); // 15m >= 10m threshold
    expect(localStore.has(PROVIDER_QUOTA_PERSIST_PREFIX + id)).toBe(true);
    simulateNewTab();
    expect(isProviderInCooldown(id)).toBe(true);
  });
});

describe("S1 — early clear and expiry", () => {
  it("clearProviderCooldownOnSuccess removes BOTH stores (even across a new tab)", () => {
    const id = nextId();
    markProviderQuotaCooldown(id);
    simulateNewTab();
    expect(isProviderInCooldown(id)).toBe(true); // restored from localStorage
    clearProviderCooldownOnSuccess(id);
    expect(isProviderInCooldown(id)).toBe(false);
    expect(localStore.has(PROVIDER_QUOTA_PERSIST_PREFIX + id)).toBe(false);
    expect(sessionStore.has(PROVIDER_COOLDOWN_PREFIX + id)).toBe(false);
  });

  it("expired localStorage entries are ignored and self-cleaned", () => {
    const id = nextId();
    const expired = JSON.stringify({ until: Date.now() - 1000, class: "quota" });
    localStore.set(PROVIDER_QUOTA_PERSIST_PREFIX + id, expired);
    expect(isProviderInCooldown(id)).toBe(false);
    expect(localStore.has(PROVIDER_QUOTA_PERSIST_PREFIX + id)).toBe(false);
  });

  it("legacy bare-number entries (pre-JSON) still parse", () => {
    const id = nextId();
    localStore.set(
      PROVIDER_QUOTA_PERSIST_PREFIX + id,
      String(Date.now() + 60_000),
    );
    expect(isProviderInCooldown(id)).toBe(true);
    expect(getProviderCooldownClass(id)).toBe("unknown");
  });

  it("corrupted localStorage entries are ignored, not thrown", () => {
    const id = nextId();
    localStore.set(PROVIDER_QUOTA_PERSIST_PREFIX + id, "{not json!!");
    expect(() => isProviderInCooldown(id)).not.toThrow();
    expect(isProviderInCooldown(id)).toBe(false);
  });
});

describe("S1 — introspection API (feeds S2 structured skip reasons)", () => {
  it("getProviderCooldownRemainingMs returns real remaining time, 0 when none", () => {
    const id = nextId();
    expect(getProviderCooldownRemainingMs(id)).toBe(0);
    markProviderQuotaCooldown(id);
    const rem = getProviderCooldownRemainingMs(id);
    expect(rem).toBeGreaterThan(PROVIDER_QUOTA_COOLDOWN_MS - 60_000);
    expect(rem).toBeLessThanOrEqual(PROVIDER_QUOTA_COOLDOWN_MS);
  });

  it("getProviderCooldownRemainingMs works across a new tab", () => {
    const id = nextId();
    markProviderQuotaCooldown(id);
    simulateNewTab();
    expect(getProviderCooldownRemainingMs(id)).toBeGreaterThan(0);
  });

  it("getProviderCooldownClass reports the window class", () => {
    const id = nextId();
    markProviderQuotaCooldown(id);
    expect(getProviderCooldownClass(id)).toBe("quota");

    const id401 = nextId();
    markProvider401Cooldown(id401);
    expect(getProviderCooldownClass(id401)).toBe("401");

    const id429 = nextId();
    markProvider429Cooldown(id429);
    expect(getProviderCooldownClass(id429)).toBe("429");
  });

  it("QUOTA_PERSIST_MIN_MS is 10 minutes", () => {
    expect(QUOTA_PERSIST_MIN_MS).toBe(10 * 60 * 1000);
  });
});

src/lib/__tests__/provider-cooldown-snap:
// ============================================================================
// Task 22 — QUOTA-WINDOW VISIBILITY (cooldown snapshot + display formatting)
//
// Task 21 made the ADAPTIVE CAP visible on the Providers page. The other half
// of traffic control was still invisible there: the COOLDOWN windows (S1).
// The router parks providers in sessionStorage windows (429 → 3m, timeout →
// 90s) and mirrors long ones (quota 30m, auth 30m) into localStorage so they
// survive a tab close — but the Providers table showed none of it, and the
// health strip's COOLDOWN chip showed raw seconds without the CLASS (quota vs
// 429 vs auth vs timeout — the "why") or whether the window is PERSISTED.
//
// Pure logic first, thin UI wiring after (repo convention):
//   getProviderCooldownSnapshot(id) — the full window picture:
//     inCooldown / remainingMs / class / until / persisted (S1 mirror is the
//     active window → survives tab close). Mirrors the session→local lookup
//     order of getProviderCooldownRemainingMs exactly.
//   formatCooldownRemaining(ms) — human display: "30m 00s", "2m 05s", "45s".
//     Hours-capable for future windows longer than the current 30m cap.
//
// Manual clearing already exists as clearProviderCooldownOnSuccess (evidence-
// based early-clear) — the UI reuses it for the manual clear affordance.
// ============================================================================

import { describe, it, expect, beforeEach } from "vitest";
import {
  getProviderCooldownSnapshot,
  formatCooldownRemaining,
  markProvider429Cooldown,
  markProviderQuotaCooldown,
  markProvider401Cooldown,
  markProviderTimeoutCooldown,
  markProviderRateLimitCooldown,
  clearProviderCooldownOnSuccess,
  PROVIDER_COOLDOWN_PREFIX,
  PROVIDER_QUOTA_PERSIST_PREFIX,
} from "../provider-cooldown";

// -- Minimal window fake with BOTH stores (vitest runs in node env) ----------
const session = new Map<string, string>();
const local = new Map<string, string>();
(globalThis as any).window = {
  sessionStorage: {
    getItem: (k: string) => session.get(k) ?? null,
    setItem: (k: string, v: string) => void session.set(k, v),
    removeItem: (k: string) => void session.delete(k),
  },
  localStorage: {
    getItem: (k: string) => local.get(k) ?? null,
    setItem: (k: string, v: string) => void local.set(k, v),
    removeItem: (k: string) => void local.delete(k),
  },
};

let seq = 0;
const nextId = () => `p_snap_${++seq}`;

beforeEach(() => {
  session.clear();
  local.clear();
});

describe("getProviderCooldownSnapshot — the full window picture", () => {
  it("no window → not in cooldown, zeros, no class, not persisted", () => {
    const id = nextId();
    const snap = getProviderCooldownSnapshot(id);
    expect(snap).toEqual({
      providerId: id,
      inCooldown: false,
      remainingMs: 0,
      class: null,
      until: null,
      persisted: false,
    });
  });

  it("429 window (3m): class 429, session-only → persisted false", () => {
    const id = nextId();
    markProvider429Cooldown(id);
    const snap = getProviderCooldownSnapshot(id);
    expect(snap.inCooldown).toBe(true);
    expect(snap.class).toBe("429");
    expect(snap.persisted).toBe(false);
    expect(snap.remainingMs).toBeGreaterThan(0);
    expect(snap.remainingMs).toBeLessThanOrEqual(3 * 60 * 1000);
    expect(snap.until).toBeGreaterThan(Date.now());
  });

  it("quota window (30m): class quota, PERSISTED (survives tab close)", () => {
    const id = nextId();
    markProviderQuotaCooldown(id);
    const snap = getProviderCooldownSnapshot(id);
    expect(snap.class).toBe("quota");
    expect(snap.persisted).toBe(true);
    expect(local.has(PROVIDER_QUOTA_PERSIST_PREFIX + id)).toBe(true);
  });

  it("401 window (30m): class 401, persisted", () => {
    const id = nextId();
    markProvider401Cooldown(id);
    const snap = getProviderCooldownSnapshot(id);
    expect(snap.class).toBe("401");
    expect(snap.persisted).toBe(true);
  });

  it("timeout window (90s): class timeout, session-only", () => {
    const id = nextId();
    markProviderTimeoutCooldown(id);
    const snap = getProviderCooldownSnapshot(id);
    expect(snap.class).toBe("timeout");
    expect(snap.persisted).toBe(false);
  });

  it("explicit Retry-After window below the persist threshold stays session-only", () => {
    const id = nextId();
    markProviderRateLimitCooldown(id, 60_000); // 1m < 10m threshold
    expect(getProviderCooldownSnapshot(id).persisted).toBe(false);
  });

  it("expired session window with a LIVE local mirror → snapshot reads the persisted window", () => {
    const id = nextId();
    markProviderQuotaCooldown(id);
    // Age out the session copy; the S1 mirror remains authoritative.
    const raw = session.get(PROVIDER_COOLDOWN_PREFIX + id)!;
    const entry = JSON.parse(raw);
    session.set(PROVIDER_COOLDOWN_PREFIX + id, JSON.stringify({ ...entry, until: Date.now() - 1000 }));
    const snap = getProviderCooldownSnapshot(id);
    expect(snap.inCooldown).toBe(true);
    expect(snap.persisted).toBe(true);
    expect(snap.class).toBe("quota");
    expect(snap.remainingMs).toBeGreaterThan(0);
  });

  it("both stores expired → clean empty snapshot (no stale class leaks)", () => {
    const id = nextId();
    const past = Date.now() - 1000;
    session.set(PROVIDER_COOLDOWN_PREFIX + id, JSON.stringify({ until: past, class: "quota" }));
    local.set(PROVIDER_QUOTA_PERSIST_PREFIX + id, JSON.stringify({ until: past, class: "quota" }));
    const snap = getProviderCooldownSnapshot(id);
    expect(snap.inCooldown).toBe(false);
    expect(snap.class).toBeNull();
    expect(snap.until).toBeNull();
    expect(snap.persisted).toBe(false);
  });

  it("manual clear via clearProviderCooldownOnSuccess → snapshot back to none", () => {
    const id = nextId();
    markProviderQuotaCooldown(id);
    expect(getProviderCooldownSnapshot(id).inCooldown).toBe(true);
    clearProviderCooldownOnSuccess(id);
    const snap = getProviderCooldownSnapshot(id);
    expect(snap.inCooldown).toBe(false);
    expect(snap.class).toBeNull();
    expect(snap.persisted).toBe(false);
  });
});

describe("formatCooldownRemaining — human display", () => {
  it("zero / negative → 0s", () => {
    expect(formatCooldownRemaining(0)).toBe("0s");
    expect(formatCooldownRemaining(-5)).toBe("0s");
  });

  it("sub-minute → bare seconds", () => {
    expect(formatCooldownRemaining(45_000)).toBe("45s");
    expect(formatCooldownRemaining(5_000)).toBe("5s");
  });

  it("minutes + seconds, zero-padded", () => {
    expect(formatCooldownRemaining(90_000)).toBe("1m 30s");
    expect(formatCooldownRemaining(125_000)).toBe("2m 05s");
  });

  it("quarter-hour and the full 30m quota window", () => {
    expect(formatCooldownRemaining(15 * 60_000)).toBe("15m 00s");
    expect(formatCooldownRemaining(30 * 60_000)).toBe("30m 00s");
    expect(formatCooldownRemaining(29 * 60_000 + 59_000)).toBe("29m 59s");
  });

  it("hours-capable for windows beyond the current cap", () => {
    expect(formatCooldownRemaining(60 * 60_000)).toBe("1h 00m");
    expect(formatCooldownRemaining(2 * 3_600_000 + 5 * 60_000)).toBe("2h 05m");
  });

  it("rounds up so a window never displays as already-expired", () => {
    expect(formatCooldownRemaining(1_000)).toBe("1s");
    expect(formatCooldownRemaining(60_500)).toBe("1m 01s");
  });
});

src/lib/__tests__/provider-cooldown.test:
// ============================================================================
// Traffic-vs-PROBE cooldown authority — regression tests for the
// "providers cool down even though the API was never used" bug.
//
// Root cause: the router armed provider cooldowns (sessionStorage + in-memory
// rate-limit tracker) on EVERY failed call — including the app's own health
// probes (preflight / benchmark / heal pings, requestType "test"). Free-tier
// models 429 those probes constantly, so providers cycled in a perpetual
// "Temporary cooldown — 180s remaining" state with zero real user traffic.
//
// Contract under test (recordTrafficCooldownFromError):
//   - requestType "test"  → NEVER arms any cooldown (evidence only)
//   - real traffic 429    → tracker window + sessionStorage 429 cooldown
//   - real traffic 401    → 30-min auth cooldown
//   - real traffic timeout→ 90s timeout cooldown
//   - authExtra (race)    → billing/payment wording still classified
// ============================================================================

import { describe, it, expect, beforeEach } from "vitest";
import {
  recordTrafficCooldownFromError,
  isProviderInCooldown,
  PROVIDER_COOLDOWN_PREFIX,
  PROVIDER_429_COOLDOWN_MS,
  PROVIDER_401_COOLDOWN_MS,
  PROVIDER_QUOTA_COOLDOWN_MS,
  markProviderQuotaCooldown,
  markProvider429Cooldown,
  clearProviderCooldownOnSuccess,
} from "../provider-cooldown";
import { rateLimitTracker } from "../rate-limit-tracker";

// -- Minimal window/sessionStorage fake (vitest runs in node env) -----------
const store = new Map<string, string>();
(globalThis as any).window = {
  sessionStorage: {
    getItem: (k: string) => store.get(k) ?? null,
    setItem: (k: string, v: string) => void store.set(k, v),
    removeItem: (k: string) => void store.delete(k),
  },
};

const keyFor = (id: string) => PROVIDER_COOLDOWN_PREFIX + id;

// S1: cooldown entries are now JSON ({until, class}) — parse accordingly.
const readUntil = (id: string): number => {
  const raw = store.get(keyFor(id)) ?? "";
  if (raw.startsWith("{")) {
    try { return JSON.parse(raw).until as number; } catch { return NaN; }
  }
  return Number(raw);
};

// Unique provider ids per test — the rate-limit tracker is a process-level
// singleton with no reset, so tests must not share keys.
let seq = 0;
const nextId = () => `p_test_${++seq}`;

beforeEach(() => {
  store.clear();
});

describe("recordTrafficCooldownFromError — probe requests never arm cooldowns", () => {
  it("a probe 429 (requestType 'test') arms NOTHING — the phantom-cooldown bug", () => {
    const id = nextId();
    recordTrafficCooldownFromError({
      cooldownId: id,
      providerId: id,
      modelName: "hy3-free",
      error: new Error("HTTP 429: rate limit exceeded"),
      isTimeout: false,
      requestType: "test", // preflight / benchmark / heal ping
    });
    expect(isProviderInCooldown(id)).toBe(false);
    expect(rateLimitTracker.isRateLimited(id)).toBe(false);
  });

  it("a probe timeout (requestType 'test') arms NOTHING", () => {
    const id = nextId();
    recordTrafficCooldownFromError({
      cooldownId: id,
      providerId: id,
      error: new Error("Request timed out after 15000ms"),
      isTimeout: true,
      requestType: "test",
    });
    expect(isProviderInCooldown(id)).toBe(false);
  });

  it("a probe auth error (requestType 'test') arms NOTHING", () => {
    const id = nextId();
    recordTrafficCooldownFromError({
      cooldownId: id,
      providerId: id,
      error: new Error("HTTP 401: unauthorized"),
      isTimeout: false,
      requestType: "test",
    });
    expect(isProviderInCooldown(id)).toBe(false);
  });
});

describe("recordTrafficCooldownFromError — real traffic still arms cooldowns", () => {
  it("a REAL 429 arms the tracker window + the 3-minute sessionStorage cooldown", () => {
    const id = nextId();
    recordTrafficCooldownFromError({
      cooldownId: id,
      providerId: id,
      modelName: "hy3-free",
      error: new Error("HTTP 429: Too Many Requests"),
      isTimeout: false,
      requestType: "chat",
    });
    expect(isProviderInCooldown(id)).toBe(true);
    expect(rateLimitTracker.isRateLimited(id)).toBe(true);
    // sessionStorage key carries the 429 window
    const until = readUntil(id);
    expect(until - Date.now()).toBeGreaterThan(PROVIDER_429_COOLDOWN_MS - 5000);
  });

  it("a REAL 401 arms the 30-minute auth cooldown", () => {
    const id = nextId();
    recordTrafficCooldownFromError({
      cooldownId: id,
      providerId: id,
      error: new Error("HTTP 401: unauthorized"),
      isTimeout: false,
      requestType: "chat",
    });
    expect(isProviderInCooldown(id)).toBe(true);
    const until = readUntil(id);
    expect(until - Date.now()).toBeGreaterThan(PROVIDER_401_COOLDOWN_MS - 5000);
  });

  it("a REAL timeout arms the short timeout cooldown", () => {
    const id = nextId();
    recordTrafficCooldownFromError({
      cooldownId: id,
      providerId: id,
      error: new Error("Provider.generate timed out"),
      isTimeout: true,
      requestType: "chat",
    });
    expect(isProviderInCooldown(id)).toBe(true);
  });

  it("statusCode takes precedence over message matching (429 via status)", () => {
    const id = nextId();
    recordTrafficCooldownFromError({
      cooldownId: id,
      providerId: id,
      error: Object.assign(new Error("quota"), { statusCode: 429 }),
      isTimeout: false,
      requestType: "chat",
    });
    expect(isProviderInCooldown(id)).toBe(true);
  });

  it("authExtra (speculative race) still classifies billing/payment wording", () => {
    const id = nextId();
    recordTrafficCooldownFromError({
      cooldownId: id,
      providerId: id,
      error: new Error("payment required for this model"),
      isTimeout: false,
      requestType: "chat",
      authExtra: /billing|payment/i,
    });
    expect(isProviderInCooldown(id)).toBe(true);
  });

  it("non-rate-limit, non-auth, non-timeout errors arm nothing (failover only)", () => {
    const id = nextId();
    recordTrafficCooldownFromError({
      cooldownId: id,
      providerId: id,
      error: new Error("The model `foo` does not exist"),
      isTimeout: false,
      requestType: "chat",
    });
    expect(isProviderInCooldown(id)).toBe(false);
  });
});

// ============================================================================
// P1 — QUOTA-CLASS COOLDOWN. FreeUsageLimitError-style 429s mean the
// account/model quota is EXHAUSTED (resets on an hourly/daily window), not
// "backing off for a few seconds". A flat 3-minute window made the router
// re-attempt a quota-dead provider every 3 minutes all day (the retry
// treadmill). Quota-class evidence must park the provider for the long
// window; transient 429s keep the short one.
// ============================================================================
describe("recordTrafficCooldownFromError — quota-class cooldown (P1)", () => {
  it("real-traffic FreeUsageLimitError arms the 30-MINUTE quota cooldown, not 3 minutes", () => {
    const id = nextId();
    recordTrafficCooldownFromError({
      cooldownId: id,
      providerId: id,
      modelName: "mimo-v2.5-free",
      error: new Error(
        "API returned HTTP 429: FreeUsageLimitError: Rate limit exceeded. Please try again later."
      ),
      statusCode: 429,
      isTimeout: false,
      requestType: "chat",
    });
    const until = readUntil(id);
    expect(until - Date.now()).toBeGreaterThan(PROVIDER_QUOTA_COOLDOWN_MS - 5000);
  });

  it("real-traffic usage-limit wording (no FreeUsageLimitError token) is also quota-class", () => {
    const id = nextId();
    recordTrafficCooldownFromError({
      cooldownId: id,
      providerId: id,
      error: new Error("API returned HTTP 429: usage limit exceeded for this model"),
      statusCode: 429,
      isTimeout: false,
      requestType: "chat",
    });
    const until = readUntil(id);
    expect(until - Date.now()).toBeGreaterThan(PROVIDER_QUOTA_COOLDOWN_MS - 5000);
  });

  it("transient 429 without quota wording keeps the 3-minute window", () => {
    const id = nextId();
    recordTrafficCooldownFromError({
      cooldownId: id,
      providerId: id,
      error: new Error("HTTP 429: Too Many Requests (burst)"),
      statusCode: 429,
      isTimeout: false,
      requestType: "chat",
    });
    const until = readUntil(id);
    expect(until - Date.now()).toBeGreaterThan(PROVIDER_429_COOLDOWN_MS - 5000);
    expect(until - Date.now()).toBeLessThan(PROVIDER_QUOTA_COOLDOWN_MS - 60_000);
  });

  it("markProviderQuotaCooldown arms the long window directly", () => {
    const id = nextId();
    markProviderQuotaCooldown(id);
    const until = readUntil(id);
    expect(until - Date.now()).toBeGreaterThan(PROVIDER_QUOTA_COOLDOWN_MS - 5000);
  });
});

// ============================================================================
// P2 — RETRY-AFTER HONORED. When the provider tells us exactly when to come
// back (Retry-After header, relayed by the proxy as `retryAfterSeconds` or an
// "(retry-after: Ns)" note in the error text), use that EXACT window instead
// of guessing. Clamped to [5s, PROVIDER_QUOTA_COOLDOWN_MS].
// ============================================================================
describe("recordTrafficCooldownFromError — Retry-After honored (P2)", () => {
  it("error.retryAfterSeconds sets an exact ~120s window", () => {
    const id = nextId();
    recordTrafficCooldownFromError({
      cooldownId: id,
      providerId: id,
      error: Object.assign(new Error("HTTP 429: Too Many Requests"), { retryAfterSeconds: 120 }),
      statusCode: 429,
      isTimeout: false,
      requestType: "chat",
    });
    const until = readUntil(id);
    const windowMs = until - Date.now();
    expect(windowMs).toBeGreaterThan(110_000);
    expect(windowMs).toBeLessThanOrEqual(126_000);
  });

  it("an '(retry-after: 90s)' note embedded in the error message is parsed", () => {
    const id = nextId();
    recordTrafficCooldownFromError({
      cooldownId: id,
      providerId: id,
      error: new Error(
        'Proxy: {"ok":false,"error":"API returned HTTP 429: Rate limit exceeded. Please try again later. (retry-after: 90s)"}'
      ),
      statusCode: 429,
      isTimeout: false,
      requestType: "chat",
    });
    const until = readUntil(id);
    const windowMs = until - Date.now();
    expect(windowMs).toBeGreaterThan(85_000);
    expect(windowMs).toBeLessThanOrEqual(96_000);
  });

  it("Retry-After wins over the quota class (exact evidence beats a class guess)", () => {
    const id = nextId();
    recordTrafficCooldownFromError({
      cooldownId: id,
      providerId: id,
      error: Object.assign(
        new Error("FreeUsageLimitError: Rate limit exceeded. (retry-after: 60s)"),
        { retryAfterSeconds: 60 }
      ),
      statusCode: 429,
      isTimeout: false,
      requestType: "chat",
    });
    const until = readUntil(id);
    const windowMs = until - Date.now();
    expect(windowMs).toBeGreaterThan(55_000);
    expect(windowMs).toBeLessThanOrEqual(66_000);
  });

  it("Retry-After is clamped to the 30-minute cap", () => {
    const id = nextId();
    recordTrafficCooldownFromError({
      cooldownId: id,
      providerId: id,
      error: Object.assign(new Error("HTTP 429: Too Many Requests"), { retryAfterSeconds: 7200 }),
      statusCode: 429,
      isTimeout: false,
      requestType: "chat",
    });
    const until = readUntil(id);
    expect(until - Date.now()).toBeLessThanOrEqual(PROVIDER_QUOTA_COOLDOWN_MS + 5000);
  });

  it("non-429 classes ignore Retry-After (auth stays 30-min)", () => {
    const id = nextId();
    recordTrafficCooldownFromError({
      cooldownId: id,
      providerId: id,
      error: Object.assign(new Error("HTTP 401: unauthorized"), { retryAfterSeconds: 10 }),
      statusCode: 401,
      isTimeout: false,
      requestType: "chat",
    });
    const until = readUntil(id);
    expect(until - Date.now()).toBeGreaterThan(PROVIDER_401_COOLDOWN_MS - 5000);
  });
});

// ============================================================================
// Evidence of recovery must CLEAR cooldowns early. A successful call (real
// traffic or an honest probe) is strictly stronger evidence than any timer.
// ============================================================================
describe("clearProviderCooldownOnSuccess — evidence-based early clear", () => {
  it("clears an active rate-limit cooldown", () => {
    const id = nextId();
    markProvider429Cooldown(id);
    expect(isProviderInCooldown(id)).toBe(true);
    clearProviderCooldownOnSuccess(id);
    expect(isProviderInCooldown(id)).toBe(false);
  });

  it("clears an active quota cooldown", () => {
    const id = nextId();
    markProviderQuotaCooldown(id);
    expect(isProviderInCooldown(id)).toBe(true);
    clearProviderCooldownOnSuccess(id);
    expect(isProviderInCooldown(id)).toBe(false);
  });

  it("is safe on providers with no cooldown", () => {
    const id = nextId();
    expect(() => clearProviderCooldownOnSuccess(id)).not.toThrow();
    expect(isProviderInCooldown(id)).toBe(false);
  });
});

